<?php
/**
 * Standalone security regression tests for Static Bridge.
 *
 * These tests use WordPress API stubs and make no network or database requests.
 * Run with: php tests/security/run.php [--json] [--plugin=/path/to/static-bridge.php]
 */

declare(strict_types=1);

$fixtureRoot = sys_get_temp_dir() . '/static-bridge-security-' . getmypid() . '-' . bin2hex(random_bytes(8));
define('ABSPATH', $fixtureRoot . '/wordpress/');
define('WP_CONTENT_DIR', ABSPATH . 'wp-content');
define('WP_PLUGIN_DIR', WP_CONTENT_DIR . '/plugins');

$pluginFile = dirname(__DIR__, 2) . '/plugin/static-bridge.php';
if (!is_file($pluginFile)) {
    $pluginFile = dirname(__DIR__, 2) . '/static-bridge.php';
}
$emitJson = false;
foreach (array_slice($argv, 1) as $argument) {
    if ('--json' === $argument) {
        $emitJson = true;
    } elseif (0 === strpos($argument, '--plugin=')) {
        $pluginFile = substr($argument, strlen('--plugin='));
    }
}

if (!is_file($pluginFile)) {
    fwrite(STDERR, "Static Bridge source not found: {$pluginFile}\n");
    exit(2);
}

