class WP_Error
{
    private $code;
    private $message;
    private $data;

    public function __construct($code = '', $message = '', $data = null)
    {
        $this->code = $code;
        $this->message = $message;
        $this->data = $data;
    }

    public function get_error_code()
    {
        return $this->code;
    }

    public function get_error_message()
    {
        return $this->message;
    }

    public function get_error_data()
    {
        return $this->data;
    }
}

class WP_Post
{
    public $ID;
    public $post_type;
    public $post_status;
    public $post_password;
    public $post_content;
    public $post_author;
    public $post_date;
    public $post_parent;
    public $post_name;
    public $post_title;
    public $filter;

    public function __construct($post)
    {
        $post = (object) $post;
        $this->ID = isset($post->ID) ? (int) $post->ID : 0;
        $this->post_type = isset($post->post_type) ? (string) $post->post_type : 'post';
        $this->post_status = isset($post->post_status) ? (string) $post->post_status : 'publish';
        $this->post_password = isset($post->post_password) ? (string) $post->post_password : '';
        $this->post_content = isset($post->post_content) ? (string) $post->post_content : '';
        $this->post_author = isset($post->post_author) ? (int) $post->post_author : 0;
        $this->post_date = isset($post->post_date) ? (string) $post->post_date : '';
        $this->post_parent = isset($post->post_parent) ? (int) $post->post_parent : 0;
        $this->post_name = isset($post->post_name) ? (string) $post->post_name : '';
        $this->post_title = isset($post->post_title) ? (string) $post->post_title : '';
        $this->filter = isset($post->filter) ? (string) $post->filter : '';
        if ('raw' === $this->filter) {
            $GLOBALS['sb_test_wp_post_raw_count']++;
        }
    }
}

class SB_Test_Response extends RuntimeException
{
    public $status;
    public $data;

    public function __construct($status, $data = null)
    {
        $this->status = $status;
        $this->data = $data;
        parent::__construct('WordPress JSON response stub');
    }
}

class SB_Test_WP_Die extends RuntimeException
{
    public $details;

    public function __construct($message, $title = '', $args = array())
    {
        $this->details = array('title' => $title, 'args' => $args);
        parent::__construct(strip_tags((string) $message));
    }
}

class SB_Test_Skip extends RuntimeException {}

class SB_Test_WPDB
{
    public $prefix = 'wp_';
    public $posts = 'wp_posts';
    public $term_taxonomy = 'wp_term_taxonomy';
    public $term_relationships = 'wp_term_relationships';
    public $postmeta = 'wp_postmeta';
    public $options = 'wp_options';
    public $last_error = '';

    public function prepare($query, $args = array())
    {
        if (!is_array($args)) {
            $args = array_slice(func_get_args(), 1);
        }
        $id = ++$GLOBALS['sb_test_export_queue_prepared_id'];
        $token = '__SB_PREPARED_' . $id . '__';
        $GLOBALS['sb_test_export_queue_prepared'][$token] = array((string) $query, array_values($args));
        return $token;
    }

    public function get_charset_collate()
    {
        return 'DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci';
    }

    public function esc_like($value)
    {
        return addcslashes((string) $value, '_%\\');
    }

    public function apply_schema($sql)
    {
        if (!preg_match('/CREATE TABLE\s+([A-Za-z0-9_]+)/i', (string) $sql, $match)) {
            return array();
        }
        $GLOBALS['sb_test_export_queue_schema'][$match[1]] = true;
        return array($match[1] => 'created');
    }

    public function get_var($prepared)
    {
        $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared])
            ? $GLOBALS['sb_test_export_queue_prepared'][$prepared]
            : array('', array());
        list($sql, $args) = $query;
        if (false !== strpos($sql, 'SELECT option_value FROM wp_options WHERE option_name = %s')) {
            // The export worker lock read from its row (2.4.0): the same store as get_option().
            $name = (string) $args[0];
            if (!empty($GLOBALS['sb_test_option_read_before_race'][$name])) {
                // The read happened just before another request wrote the row.
                unset($GLOBALS['sb_test_option_read_before_race'][$name]);
                return null;
            }
            return array_key_exists($name, $GLOBALS['sb_test_options']) ? maybe_serialize($GLOBALS['sb_test_options'][$name]) : null;
        }
        if (0 === stripos($sql, 'SHOW TABLES LIKE')) {
            $table = isset($args[0]) ? str_replace('\\_', '_', (string) $args[0]) : '';
            return isset($GLOBALS['sb_test_export_queue_schema'][$table]) ? $table : null;
        }
        if (false !== strpos($sql, 'COUNT(DISTINCT tr.object_id)')) {
            // A parent category and its descendants: each post once.
            $term_ids = array_map('intval', array_slice($args, 1));
            $posts = array();
            foreach (sb_test_archive('terms') as $term_id => $term) {
                if (in_array((int) $term_id, $term_ids, true)) {
                    $posts = array_merge($posts, isset($term['posts']) ? $term['posts'] : array());
                }
            }
            return count(array_unique($posts));
        }
        if (false !== strpos($sql, 'post_modified_gmt > %s')) {
            // Content changed after the release (or a scheduled post published since): every status but
            // auto-draft and inherit, of the listed types.
            $types = array_slice($args, 2);
            return count(array_filter($GLOBALS['sb_test_posts'], function ($post) use ($args, $types) {
                $modified = isset($post['post_modified_gmt']) && $post['post_modified_gmt'] > $args[0];
                $published = 'publish' === ($post['post_status'] ?? 'publish') && isset($post['post_date_gmt']) && $post['post_date_gmt'] > $args[1];
                return ($modified || $published)
                    && !in_array($post['post_status'] ?? 'publish', array('auto-draft', 'inherit'), true)
                    && in_array($post['post_type'] ?? 'post', $types, true);
            }));
        }
        if (false !== strpos($sql, 'post_date >= %s AND post_date < %s')) {
            $start = $args[count($args) - 2];
            $end = $args[count($args) - 1];
            return count(array_filter(sb_test_archive('post_dates'), function ($date) use ($start, $end) {
                return $date >= $start && $date < $end;
            }));
        }
        if (false !== stripos($sql, 'SELECT COUNT(*)')) {
            $wanted_status = preg_match("/status = '([a-z]+)'/", $sql, $status_match) ? $status_match[1] : '';
            if ('' === $wanted_status) {
                $GLOBALS['sb_test_export_queue_total_count_queries']++;
            }
            $job_id = isset($args[0]) ? (string) $args[0] : '';
            $count = 0;
            foreach ($GLOBALS['sb_test_export_queue_rows'] as $row) {
                if ($row['job_id'] === $job_id
                    && ('' === $wanted_status || $wanted_status === $row['status'])) {
                    $count++;
                }
            }
            return $count;
        }
        return null;
    }

    public function query($prepared)
    {
        $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared])
            ? $GLOBALS['sb_test_export_queue_prepared'][$prepared]
            : array('', array());
        list($sql, $args) = $query;
        if (0 === stripos($sql, 'INSERT IGNORE INTO wp_options ')) {
            $name = (string) $args[0];
            if (array_key_exists($name, $GLOBALS['sb_test_options'])) {
                return 0;
            }
            $GLOBALS['sb_test_options'][$name] = maybe_unserialize((string) $args[1]);
            return 1;
        }
        if (0 === stripos($sql, 'DELETE FROM wp_options WHERE option_name = %s AND option_value = %s')) {
            $name = (string) $args[0];
            if (array_key_exists($name, $GLOBALS['sb_test_options']) && maybe_serialize($GLOBALS['sb_test_options'][$name]) === (string) $args[1]) {
                unset($GLOBALS['sb_test_options'][$name]);
                return 1;
            }
            return 0;
        }
        if (0 !== stripos($sql, 'INSERT IGNORE INTO ')) {
            return false;
        }
        $inserted = 0;
        for ($offset = 0; $offset + 4 < count($args); $offset += 5) {
            $job_id = (string) $args[$offset];
            $hash = (string) $args[$offset + 1];
            $key = $job_id . ':' . $hash;
            if (isset($GLOBALS['sb_test_export_queue_rows'][$key])) {
                continue;
            }
            $GLOBALS['sb_test_export_queue_rows'][$key] = array(
                'id' => $GLOBALS['sb_test_export_queue_next_id']++,
                'job_id' => $job_id,
                'url_hash' => $hash,
                'url' => (string) $args[$offset + 2],
                'status' => (string) $args[$offset + 3],
                'created_at' => (string) $args[$offset + 4],
            );
            $inserted++;
        }
        return $inserted;
    }

    public function get_row($prepared, $output = null)
    {
        $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared])
            ? $GLOBALS['sb_test_export_queue_prepared'][$prepared]
            : array('', array());
        list($sql, $args) = $query;
        if (false === stripos($sql, 'SELECT id,url_hash,url')) {
            return null;
        }
        $job_id = isset($args[0]) ? (string) $args[0] : '';
        $rows = array_filter($GLOBALS['sb_test_export_queue_rows'], function ($row) use ($job_id) {
            return $row['job_id'] === $job_id && 'pending' === $row['status'];
        });
        if (empty($rows)) {
            return null;
        }
        usort($rows, function ($left, $right) { return $left['id'] <=> $right['id']; });
        $row = reset($rows);
        return array_intersect_key($row, array_flip(array('id', 'url_hash', 'url')));
    }

    public function get_col($prepared)
    {
        if (is_string($prepared) && preg_match('/\ASELECT DISTINCT release_key FROM ([A-Za-z0-9_]+)\z/', $prepared, $release_key_query)) {
            if (!empty($GLOBALS['sb_test_release_key_query_fail'])) {
                $this->last_error = 'Simulated release-key query failure';
                return array();
            }
            return isset($GLOBALS['sb_test_release_keys'][$release_key_query[1]])
                ? array_values($GLOBALS['sb_test_release_keys'][$release_key_query[1]])
                : array();
        }
        $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared])
            ? $GLOBALS['sb_test_export_queue_prepared'][$prepared]
            : array('', array());
        list($sql, $args) = $query;
        if (false !== strpos($sql, "meta_key IN ('_children', '_upsell_ids')")) {
            // WooCommerce: the products whose _children or _upsell_ids list holds this one (sb_test_wc_meta).
            $id = preg_match('/i:(\d+);/', stripslashes((string) $args[0]), $match) ? (int) $match[1] : 0;
            return isset($GLOBALS['sb_test_wc_meta'][$id]) ? array_map('strval', $GLOBALS['sb_test_wc_meta'][$id]) : array();
        }
        if (false !== strpos($sql, "post_status = 'publish' AND post_password = ''")) {
            // The public content (reactivation, doc 23 item 169): published, no password, of the listed types.
            $types = array_slice($args, 0, -1);
            $ids = array();
            foreach ($GLOBALS['sb_test_posts'] as $post) {
                if ('publish' === ($post['post_status'] ?? 'publish') && '' === (string) ($post['post_password'] ?? '')
                    && in_array($post['post_type'] ?? 'post', $types, true)) {
                    $ids[] = (int) $post['ID'];
                }
            }
            sort($ids);
            return array_slice($ids, 0, (int) end($args));
        }
        if (false !== strpos($sql, "post_modified_gmt > %s AND (post_status NOT IN ('publish', 'auto-draft', 'inherit') OR post_password <> '')")) {
            // Changed after the release and not public now.
            $types = array_slice($args, 1, -1);
            $ids = array();
            foreach ($GLOBALS['sb_test_posts'] as $post) {
                $status = $post['post_status'] ?? 'publish';
                if (isset($post['post_modified_gmt']) && $post['post_modified_gmt'] > $args[0]
                    && (!in_array($status, array('publish', 'auto-draft', 'inherit'), true) || '' !== (string) ($post['post_password'] ?? ''))
                    && in_array($post['post_type'] ?? 'post', $types, true)) {
                    $ids[] = (int) $post['ID'];
                }
            }
            sort($ids);
            return array_slice($ids, 0, (int) end($args));
        }
        if (0 !== stripos($sql, 'SELECT ID FROM wp_posts')) {
            return array();
        }
        $after_id = isset($args[0]) ? (int) $args[0] : 0;
        $limit = !empty($args) ? (int) end($args) : 100;
        $last = min((int) $GLOBALS['sb_test_generated_post_count'], $after_id + $limit);
        return $last > $after_id ? range($after_id + 1, $last) : array();
    }

    public function get_results($prepared, $output = null)
    {
        $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared])
            ? $GLOBALS['sb_test_export_queue_prepared'][$prepared]
            : array('', array());
        list($sql, $args) = $query;
        if (0 === stripos($sql, 'SELECT id,url_hash,url FROM wp_static_bridge_export_urls')) {
            $job_id = isset($args[0]) ? (string) $args[0] : '';
            $limit = !empty($args) ? max(1, (int) end($args)) : 1;
            $rows = array_filter($GLOBALS['sb_test_export_queue_rows'], function ($row) use ($job_id) {
                return $row['job_id'] === $job_id && 'pending' === $row['status'];
            });
            usort($rows, function ($left, $right) { return $left['id'] <=> $right['id']; });
            return array_map(function ($row) {
                return array_intersect_key($row, array_flip(array('id', 'url_hash', 'url')));
            }, array_slice($rows, 0, $limit));
        }
        if (0 === strpos($sql, 'SELECT term_taxonomy_id, term_id, taxonomy, count FROM wp_term_taxonomy')) {
            $GLOBALS['sb_test_inventory_queries'][] = array('sql' => $sql, 'args' => $args);
            $after = (int) $args[0];
            $limit = (int) end($args);
            $taxonomies = array_slice($args, 1, -1);
            $rows = array();
            foreach (sb_test_archive('terms') as $term_id => $term) {
                if ((int) $term['term_taxonomy_id'] > $after && in_array($term['taxonomy'], $taxonomies, true)) {
                    $rows[(int) $term['term_taxonomy_id']] = (object) array('term_taxonomy_id' => $term['term_taxonomy_id'], 'term_id' => $term_id, 'taxonomy' => $term['taxonomy'], 'count' => isset($term['count']) ? $term['count'] : 0);
                }
            }
            ksort($rows);
            return array_slice(array_values($rows), 0, $limit);
        }
        if (false !== strpos($sql, ' AS archive_key, COUNT(*) AS posts FROM wp_posts')) {
            $GLOBALS['sb_test_inventory_queries'][] = array('sql' => $sql, 'args' => $args);
            $limit = (int) array_pop($args);
            $after = (int) array_pop($args);
            $groups = array();
            if (false !== strpos($sql, 'SELECT post_author AS')) {
                foreach (sb_test_archive('author_counts') as $author => $count) {
                    $groups[(int) $author] = $count;
                }
            } else {
                foreach (sb_test_archive('post_dates') as $date) {
                    list($year, $month, $day) = array_map('intval', explode('-', substr($date, 0, 10)));
                    $key = false !== strpos($sql, 'DAYOFMONTH') ? $year * 10000 + $month * 100 + $day
                        : (false !== strpos($sql, 'MONTH(post_date)') ? $year * 100 + $month : $year);
                    $groups[$key] = (isset($groups[$key]) ? $groups[$key] : 0) + 1;
                }
            }
            ksort($groups);
            $rows = array();
            foreach ($groups as $key => $count) {
                if ($key > $after) {
                    $rows[] = (object) array('archive_key' => $key, 'posts' => $count);
                }
            }
            return array_slice($rows, 0, $limit);
        }
        if (0 !== stripos($sql, 'SELECT * FROM wp_posts')) {
            return array();
        }
        $GLOBALS['sb_test_inventory_queries'][] = array('sql' => $sql, 'args' => $args);
        $after_id = isset($args[0]) ? (int) $args[0] : 0;
        $limit = !empty($args) ? (int) end($args) : 100;
        $types = array_map('strval', array_slice($args, 1, -1));
        if (!empty($GLOBALS['sb_test_generated_post_count'])) {
            $last = min((int) $GLOBALS['sb_test_generated_post_count'], $after_id + $limit);
            $rows = array();
            for ($id = $after_id + 1; $id <= $last; $id++) {
                $rows[] = (object) array('ID' => $id, 'post_type' => isset($types[0]) ? $types[0] : 'post', 'post_status' => 'publish', 'post_password' => '');
            }
            return $rows;
        }

        $posts = array_values(array_filter($GLOBALS['sb_test_posts'], function ($post) use ($after_id, $types) {
            return (int) $post['ID'] > $after_id
                && in_array($post['post_type'], $types, true)
                && 'publish' === $post['post_status']
                && '' === (string) $post['post_password'];
        }));
        usort($posts, function ($left, $right) { return (int) $left['ID'] <=> (int) $right['ID']; });
        return array_map(function ($post) { return (object) $post; }, array_slice($posts, 0, $limit));
    }

    public function update($table, $data, $where, $format = null, $where_format = null)
    {
        $updated = 0;
        foreach ($GLOBALS['sb_test_export_queue_rows'] as &$row) {
            if ($row['job_id'] === $where['job_id']
                && (!isset($where['url_hash']) || $row['url_hash'] === $where['url_hash'])
                && $row['status'] === $where['status']) {
                $row['status'] = $data['status'];
                $updated++;
            }
        }
        unset($row);
        return $updated;
    }

    public function delete($table, $where, $where_format = null)
    {
        $deleted = 0;
        foreach ($GLOBALS['sb_test_export_queue_rows'] as $key => $row) {
            if ($row['job_id'] === $where['job_id']) {
                unset($GLOBALS['sb_test_export_queue_rows'][$key]);
                $deleted++;
            }
        }
        return $deleted;
    }
}

$GLOBALS['wpdb'] = new SB_Test_WPDB();
if (!defined('ARRAY_A')) {
    define('ARRAY_A', 'ARRAY_A');
}
if (!defined('DAY_IN_SECONDS')) {
    define('DAY_IN_SECONDS', 86400);
}
if (!defined('MINUTE_IN_SECONDS')) {
    define('MINUTE_IN_SECONDS', 60);
}
function dbDelta($sql) { return $GLOBALS['wpdb']->apply_schema($sql); }

function add_action($hook, $callback, $priority = 10, $accepted_args = 1)
{
    $GLOBALS['sb_test_hooks'][] = array($hook, $callback, $priority, $accepted_args);
}
function wp_register_ability_category($slug, $args)
{
    $GLOBALS['sb_test_wp_abilities']['categories'][$slug] = $args;
    return true;
}
function wp_register_ability($name, $args)
{
    $GLOBALS['sb_test_wp_abilities']['abilities'][$name] = $args;
    return (object) array('name' => $name);
}
function remove_action($hook, $callback, $priority = 10)
{
    foreach ($GLOBALS['sb_test_hooks'] as $index => $registered) {
        if ($registered[0] === $hook && $registered[1] === $callback && (int) $registered[2] === (int) $priority) {
            unset($GLOBALS['sb_test_hooks'][$index]);
            $GLOBALS['sb_test_hooks'] = array_values($GLOBALS['sb_test_hooks']);
            return true;
        }
    }
    return false;
}
function add_filter($hook, $callback, $priority = 10, $accepted_args = 1)
{
    add_action($hook, $callback, $priority, $accepted_args);
}
function remove_filter($hook, $callback, $priority = 10)
{
    return remove_action($hook, $callback, $priority);
}
function apply_filters($tag, $value, ...$arguments)
{
    if (isset($GLOBALS['sb_test_filter_callbacks'][$tag])) {
        return call_user_func($GLOBALS['sb_test_filter_callbacks'][$tag], $value, ...$arguments);
    }
    return array_key_exists($tag, $GLOBALS['sb_test_filter_values']) ? $GLOBALS['sb_test_filter_values'][$tag] : $value;
}
function do_action($hook, ...$arguments)
{
    $GLOBALS['sb_test_actions_fired'][] = array($hook, $arguments);
    // A listener a test sets for one action (2.5.0: static_bridge_export_finished), called like WordPress would.
    if (isset($GLOBALS['sb_test_action_callbacks'][$hook])) {
