    $types = isset($args['post_type']) ? (array) $args['post_type'] : array('post');
    $posts = array_values(array_filter($posts, function ($post) use ($args, $types) {
        if (!in_array($post['post_type'], $types, true)) {
            return false;
        }
        if (isset($args['post_status']) && $args['post_status'] !== $post['post_status']) {
            return false;
