                return false;
            }
        }
        foreach (isset($args['tax_query']) ? (array) $args['tax_query'] : array() as $clause) {
            if (!is_array($clause) || 'category' !== ($clause['taxonomy'] ?? '')) {
                continue;
            }
            $post_terms = sb_test_archive('post_terms');
