                return false;
            }
        }
        if (isset($args['s']) && '' !== (string) $args['s']) {
            $searchable = (isset($post['post_title']) ? $post['post_title'] : '') . ' '
                . (isset($post['post_content']) ? $post['post_content'] : '') . ' '
                . (isset($post['post_excerpt']) ? $post['post_excerpt'] : '');
            if (false === stripos($searchable, (string) $args['s'])) {
                return false;
            }
        }
        if (isset($args['meta_query']) && is_array($args['meta_query'])) {
            if (!empty($GLOBALS['sb_test_skip_form_meta_query'])) {
                return false;
            }
            $relation = isset($args['meta_query']['relation']) && 'OR' === strtoupper((string) $args['meta_query']['relation']) ? 'OR' : 'AND';
            $matches = array();
            foreach ($args['meta_query'] as $clause) {
                if (!is_array($clause) || !isset($clause['key'])) {
                    continue;
                }
                $meta = isset($post['meta']) && is_array($post['meta']) && array_key_exists($clause['key'], $post['meta'])
                    ? $post['meta'][$clause['key']]
                    : '';
                $value = isset($clause['value']) ? (string) $clause['value'] : '';
                $matches[] = 'LIKE' === strtoupper(isset($clause['compare']) ? (string) $clause['compare'] : '=')
                    ? false !== stripos(is_scalar($meta) ? (string) $meta : json_encode($meta), $value)
                    : (string) $meta === $value;
            }
            if (!empty($matches) && ('OR' === $relation ? !in_array(true, $matches, true) : in_array(false, $matches, true))) {
                return false;
            }
        }
        return true;
    }));
    if (isset($args['orderby']) && 'date' === $args['orderby']) {
