    $target_path = trim((string) $page_path, '/');
    $post_types = (array) $post_type;
    foreach ($GLOBALS['sb_test_post_urls'] as $post_id => $post_url) {
        $url_path = trim((string) parse_url($post_url, PHP_URL_PATH), '/');
        $post = get_post($post_id);
        if ($post && $target_path === $url_path && in_array($post->post_type, $post_types, true)) {
            return $post;
        }
    }
    return null;
}
function get_post($post_id)
{
