        if ((int) $post['ID'] === (int) $post_id) {
            // As WordPress, a WP_Post when a test asks for it (the WooCommerce catalog checks the class).
            return !empty($GLOBALS['sb_test_get_post_wp_post']) ? new WP_Post($post) : (object) $post;
        }
