function get_post_meta($post_id, $key = '', $single = false)
{
    $post = get_post($post_id);
    $meta = $post && isset($post->meta) && is_array($post->meta) ? $post->meta : array();
    if ($post instanceof WP_Post) {
        // WP_Post has no meta property: read the fixture row.
        foreach ($GLOBALS['sb_test_posts'] as $row) {
            if ((int) $row['ID'] === (int) $post_id && isset($row['meta']) && is_array($row['meta'])) {
                $meta = $row['meta'];
            }
        }
    }
    if ('' === (string) $key) {
        return $meta;
    }
    if (!array_key_exists($key, $meta)) {
        return $single ? '' : array();
    }
    return $single ? $meta[$key] : array($meta[$key]);
}
