function shortcode_parse_atts($text)
{
    $attributes = array();
    if (preg_match_all('/([A-Za-z0-9_-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s\]]+))/', (string) $text, $matches, PREG_SET_ORDER)) {
        foreach ($matches as $match) {
            $attributes[$match[1]] = isset($match[2]) && '' !== $match[2]
                ? $match[2]
                : (isset($match[3]) && '' !== $match[3] ? $match[3] : (isset($match[4]) ? $match[4] : ''));
        }
    }
    return $attributes;
}
