    return sb_test_http_response($url, $args);
}
function wp_safe_remote_post($url, $args = array())
{
    $GLOBALS['sb_test_http_calls'][] = array('api' => 'wp_safe_remote_post', 'url' => $url, 'args' => $args);
    if (is_callable($GLOBALS['sb_test_http_post_callback'])) {
        return call_user_func($GLOBALS['sb_test_http_post_callback'], $url, $args);
    }
    return array('response' => array('code' => 200), 'headers' => array('content-type' => 'application/json'), 'body' => '{"success":true,"errors":[],"messages":[],"result":{"id":"0123456789abcdef0123456789abcdef"}}');
}
function wp_remote_get($url, $args = array())
{
    $GLOBALS['sb_test_http_calls'][] = array('api' => 'wp_remote_get', 'url' => $url, 'args' => $args);
    return sb_test_http_response($url, $args);
}
function sb_test_http_response($url, $args)
{
    if (is_callable($GLOBALS['sb_test_http_callback'])) {
        $custom = call_user_func($GLOBALS['sb_test_http_callback'], $url, $args);
        if (null !== $custom) {
            return $custom;
        }
    }
    $response = isset($GLOBALS['sb_test_http_responses'][$url]) ? $GLOBALS['sb_test_http_responses'][$url] : null;
    $parts = wp_parse_url($url);
    if (null === $response && is_array($parts) && isset($parts['query'])) {
        $query = array();
        parse_str($parts['query'], $query);
        unset($query['static_bridge_render']);
        $lookup = (isset($parts['scheme']) ? $parts['scheme'] . '://' : '')
            . (isset($parts['host']) ? $parts['host'] : '')
            . (isset($parts['port']) ? ':' . $parts['port'] : '')
            . (isset($parts['path']) ? $parts['path'] : '/');
        if (!empty($query)) {
            $lookup .= '?' . http_build_query($query);
        }
        $response = isset($GLOBALS['sb_test_http_responses'][$lookup]) ? $GLOBALS['sb_test_http_responses'][$lookup] : null;
    }
    if (null === $response) {
        $response = array('response' => array('code' => 404), 'headers' => array(), 'body' => '');
    }
    $strip_render_header = is_array($response) && !empty($response['_sb_strip_render_header']);
    if (is_array($response)) {
        unset($response['_sb_strip_render_header']);
    }
    if (is_array($response) && is_array($parts) && isset($parts['query'])) {
        $query = array();
        parse_str($parts['query'], $query);
        if (isset($query['static_bridge_render']) && is_string($query['static_bridge_render'])
            && preg_match('/^[a-f0-9]{48}$/', $query['static_bridge_render'])) {
            $has_header = false;
            foreach (isset($response['headers']) && is_array($response['headers']) ? $response['headers'] : array() as $name => $value) {
                if ('x-static-bridge-render' === strtolower((string) $name)) {
                    $has_header = true;
                    break;
                }
            }
            if (!$has_header && !$strip_render_header) {
                $response['headers']['X-Static-Bridge-Render'] = $query['static_bridge_render'];
            }
        }
    }
    return $response;
}
function wp_remote_retrieve_response_code($response)
{
    return isset($response['response']['code']) ? (int) $response['response']['code'] : 0;
}
function wp_remote_retrieve_header($response, $header)
{
    foreach ((isset($response['headers']) ? $response['headers'] : array()) as $name => $value) {
        if (strtolower((string) $name) === strtolower((string) $header)) {
            return $value;
        }
    }
    return '';
}
function wp_remote_retrieve_body($response) { return isset($response['body']) ? (string) $response['body'] : ''; }

