function sb_assert($condition, $message)
{
    if (!$condition) {
        throw new RuntimeException($message);
    }
}

function sb_private($object, $method, array $arguments = array())
{
    $reflection = new ReflectionMethod($object, $method);
    if (PHP_VERSION_ID < 80100) {
        $reflection->setAccessible(true);
    }
    return $reflection->invokeArgs($object, $arguments);
}

function sb_test_render_request_matches($actual, $expected_url)
{
    $actual_parts = wp_parse_url((string) $actual);
    $expected_parts = wp_parse_url((string) $expected_url);
    if (!is_array($actual_parts) || !is_array($expected_parts)
        || (isset($actual_parts['scheme']) ? $actual_parts['scheme'] : '') !== (isset($expected_parts['scheme']) ? $expected_parts['scheme'] : '')
        || (isset($actual_parts['host']) ? $actual_parts['host'] : '') !== (isset($expected_parts['host']) ? $expected_parts['host'] : '')
        || (isset($actual_parts['port']) ? $actual_parts['port'] : null) !== (isset($expected_parts['port']) ? $expected_parts['port'] : null)
        || (isset($actual_parts['path']) ? $actual_parts['path'] : '/') !== (isset($expected_parts['path']) ? $expected_parts['path'] : '/')) {
        return false;
    }
    $query = array();
    parse_str(isset($actual_parts['query']) ? $actual_parts['query'] : '', $query);
    return isset($query['static_bridge_bypass'], $query['static_bridge_render'])
        && '1' === (string) $query['static_bridge_bypass']
        && is_string($query['static_bridge_render'])
        && (bool) preg_match('/^[a-f0-9]{48}$/', $query['static_bridge_render'])
        && 2 === count($query);
}

function sb_method_body($source, $method)
{
    $pattern = '/^    (?:public|private|protected) (?:static\\s+)?function ' . preg_quote($method, '/') . '\\s*\\(/m';
    if (!preg_match($pattern, $source, $match, PREG_OFFSET_CAPTURE)) {
        return '';
    }
    $start = $match[0][1];
    $tail = substr($source, $start + strlen($match[0][0]));
    if (preg_match('/^    (?:public|private|protected) (?:static\\s+)?function /m', $tail, $next, PREG_OFFSET_CAPTURE)) {
        return substr($source, $start, strlen($match[0][0]) + $next[0][1]);
    }
    return substr($source, $start);
}

function sb_test_blocking_http_calls()
{
    // The background continuation of an export (non-blocking, to this site's admin-ajax.php) is not a blocking request.
    return array_values(array_filter($GLOBALS['sb_test_http_calls'], function ($call) {
        return !('wp_safe_remote_post' === $call['api'] && false === ($call['args']['blocking'] ?? true)
            && home_url('/wp-admin/admin-ajax.php') === $call['url']
            && Static_Bridge_Plugin::EXPORT_CONTINUE_ACTION === ($call['args']['body']['action'] ?? ''));
    }));
}

function sb_test($name, $callback)
{
    global $results;
    try {
        $callback();
        $results[] = array('name' => $name, 'status' => 'pass');
    } catch (Throwable $error) {
        $results[] = array(
            'name' => $name,
            'status' => $error instanceof SB_Test_Skip ? 'skip' : 'fail',
            'detail' => $error->getMessage(),
        );
    }
}

