sb_test('Export queue installs an indexed unique table and rejects an unsafe prefix', function () {
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    sb_assert('wp_static_bridge_export_urls' === $queue->table_name(), 'The export queue table name is not based on the trusted WordPress prefix.');
    sb_assert($queue->install(), 'The export queue schema was not installed.');

    $unsafe_db = new SB_Test_WPDB();
    $unsafe_db->prefix = 'wp_;DROP_';
    $unsafe_queue = new Static_Bridge_Export_Queue($unsafe_db);
    sb_assert('' === $unsafe_queue->table_name() && false === $unsafe_queue->install(), 'An unsafe database prefix was accepted.');
});

sb_test('Export queue deduplicates URLs, validates targets and returns unique ordered batches', function () {
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    sb_assert($queue->install(), 'The queue schema is unavailable.');
    $job_id = '12345678-1234-4234-8234-123456789abc';
    $first = home_url('/news/one/');
    $second = home_url('/news/two/');
    $added = $queue->enqueue_batch($job_id, array($first, $second, $first, 'file:///etc/passwd', 'https://user:pass@news.example.test/leak/', 'https://outside.example.test/external/', $first . '?preview=1'));
    sb_assert(2 === $added, 'Duplicate or unsafe URLs were queued.');
    sb_assert(2 === $queue->count_pending($job_id), 'Pending count does not match the inserted rows.');
    $batch = $queue->next_pending_batch($job_id, 2);
    sb_assert(is_array($batch) && 2 === count($batch), 'A two-row pending batch was not returned.');
    sb_assert($first === $batch[0]['url'] && $second === $batch[1]['url'] && $batch[0]['id'] !== $batch[1]['id'], 'The pending batch repeated or reordered a row.');
    $row = $queue->next_pending($job_id);
    sb_assert(is_array($row) && $first === $row['url'] && sha1($first) === $row['url_hash'], 'The first pending URL was not returned deterministically.');
    sb_assert($queue->mark($job_id, $row['url_hash'], 'done'), 'A pending URL could not be marked complete.');
    sb_assert(1 === $queue->count_pending($job_id), 'Marking a URL complete did not reduce the pending count.');
    sb_assert(false === $queue->mark($job_id, $row['url_hash'], 'published'), 'An unsupported queue status was accepted.');
    sb_assert($queue->delete_job($job_id) && 0 === $queue->count_pending($job_id), 'Queue rows could not be removed by the exact job id.');
});

sb_test('Core public pages are included in the indexed inventory and incremental post scope', function () use ($plugin) {
    $GLOBALS['sb_test_post_types'] = array(
        'post' => array('public' => true, 'publicly_queryable' => true),
        'page' => array('public' => true, 'publicly_queryable' => false),
        'private_story' => array('public' => false, 'publicly_queryable' => false),
        'internal_public_type' => array('public' => true, 'publicly_queryable' => false),
        'attachment' => array('public' => true, 'publicly_queryable' => true),
    );
    $GLOBALS['sb_test_posts'] = array(array(
        'ID' => 1,
        'post_type' => 'page',
        'post_status' => 'publish',
        'post_password' => '',
    ));
    $GLOBALS['sb_test_post_urls'] = array(1 => home_url('/sample-page/'));
    $GLOBALS['sb_test_inventory_queries'] = array();

    $types = sb_private($plugin, 'exportable_public_post_types');
    $batch = sb_private($plugin, 'discover_wordpress_post_url_batch', array(0));
    $page = new WP_Post(array('ID' => 1, 'post_type' => 'page', 'post_status' => 'publish'));
    $non_queryable_custom_type = new WP_Post(array('ID' => 2, 'post_type' => 'internal_public_type', 'post_status' => 'publish'));
    $attachment = new WP_Post(array('ID' => 3, 'post_type' => 'attachment', 'post_status' => 'publish'));

    sb_assert(in_array('page', $types, true), 'The built-in public page post type was omitted from static generation.');
    sb_assert(!in_array('private_story', $types, true) && !in_array('internal_public_type', $types, true) && !in_array('attachment', $types, true), 'A private, non-queryable custom type or attachment was added to public export scope.');
    sb_assert(array(home_url('/sample-page/')) === $batch['urls'], 'A public WordPress page was omitted from the indexed URL inventory.');
    sb_assert(true === sb_private($plugin, 'is_public_incremental_post', array($page)), 'A public WordPress page was excluded from incremental updates.');
    sb_assert(false === sb_private($plugin, 'is_public_incremental_post', array($non_queryable_custom_type)), 'A non-queryable custom type was added to incremental updates.');
    sb_assert(false === sb_private($plugin, 'is_public_incremental_post', array($attachment)), 'An attachment was added to incremental post updates.');

    $GLOBALS['sb_test_post_types'] = array();
    $GLOBALS['sb_test_posts'] = array();
    $GLOBALS['sb_test_post_urls'] = array();
    $GLOBALS['sb_test_inventory_queries'] = array();
});

sb_test('Manual post push immediately publishes the requested route and reports retries safely', function () use ($plugin, $source) {
    $expected_push_hooks = array(
        'add_meta_boxes' => 'register_post_push_meta_box',
        'admin_post_static_bridge_push_post' => 'handle_post_push',
        'admin_post_static_bridge_post_push_status' => 'handle_post_push_status',
        'admin_notices' => 'render_post_push_notice',
        'post_row_actions' => 'add_post_push_row_action',
        'page_row_actions' => 'add_post_push_row_action',
    );
    foreach ($expected_push_hooks as $hook_name => $callback_name) {
        $registered = false;
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            if ($hook_name === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0]
                && $callback_name === $hook[1][1]) {
                $registered = true;
                break;
            }
        }
        sb_assert($registered, 'A contextual push hook is missing: ' . $hook_name . '.');
    }

    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'post-push-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $option_names = array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION, Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION);
    $old_options = array();
    foreach ($option_names as $option) {
        $old_options[$option] = array_key_exists($option, $GLOBALS['sb_test_options']) ? $GLOBALS['sb_test_options'][$option] : null;
    }
    $old_post_types = $GLOBALS['sb_test_post_types'];
    $old_posts = $GLOBALS['sb_test_posts'];
    $old_post_urls = $GLOBALS['sb_test_post_urls'];
    $old_transients = $GLOBALS['sb_test_transients'];
    $old_meta_boxes = $GLOBALS['sb_test_meta_boxes'];
    $old_http_responses = $GLOBALS['sb_test_http_responses'];
    $old_http_calls = $GLOBALS['sb_test_http_calls'];
    $old_scheduled = isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue'])
        ? $GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']
        : false;

    try {
        sb_assert(false !== $old_current_target || (!file_exists($current) && !is_link($current)), 'The current release fixture is not a symlink and cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/news/story'), 'Could not create the isolated static release fixture.');
        sb_assert(false !== file_put_contents($release . '/index.html', '<html>home</html>'), 'Could not seed the static homepage.');
        sb_assert(false !== file_put_contents($release . '/news/story/index.html', '<html>article</html>'), 'Could not seed the static article.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its test release.');

        $GLOBALS['sb_test_post_types'] = array('post' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(array(
            'ID' => 8841,
            'post_type' => 'post',
            'post_status' => 'publish',
            'post_password' => '',
            'post_content' => 'A representative article body.',
            'post_author' => 0,
            'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() + 60),
        ));
        $GLOBALS['sb_test_post_urls'] = array(8841 => home_url('/news/story/'));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
            'incremental_enabled' => 1,
            'excluded_paths' => array(),
            'woocommerce_enabled' => 0,
            'selective_shared_updates' => 0,
        );
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $GLOBALS['sb_test_transients'] = array();
        $GLOBALS['sb_test_meta_boxes'] = array();
        unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']);
        $post = new WP_Post($GLOBALS['sb_test_posts'][0]);

        $actions = $plugin->add_post_push_row_action(array('edit' => 'Edit'), $post);
        sb_assert(isset($actions['static_bridge_push'])
            && false !== strpos($actions['static_bridge_push'], 'admin-post.php')
            && false !== strpos($actions['static_bridge_push'], 'static_bridge_push_post')
            && false !== strpos($actions['static_bridge_push'], 'test-nonce'), 'The published post row is missing its nonce-protected push action.');
        $plugin->register_post_push_meta_box('post', $post);
        sb_assert(!empty($GLOBALS['sb_test_meta_boxes']) && 'static-bridge-post-push' === $GLOBALS['sb_test_meta_boxes'][0][0], 'The post editor did not receive the Static Bridge meta box.');
        ob_start();
        $plugin->render_post_push_meta_box($post);
        $meta_box_html = ob_get_clean();
        sb_assert(false !== strpos($meta_box_html, 'admin-post.php')
            && false !== strpos($meta_box_html, 'action=static_bridge_push_post')
            && false !== strpos($meta_box_html, 'post_id=8841')
            && false !== strpos($meta_box_html, '_wpnonce=test-nonce')
            && false !== strpos($meta_box_html, 'Aggiorna copia statica')
            && false === strpos($meta_box_html, '<form'), 'The post editor push link must avoid nesting a form inside Gutenberg’s post editor form.');

        $push_token = 'aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa';
        $queued = sb_private($plugin, 'queue_manual_post_push', array($post, $push_token));
        sb_assert(true === $queued, 'The manual push helper rejected a published post with a valid current release.');
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $article = isset($queue[sha1('/news/story/')]) ? $queue[sha1('/news/story/')] : array();
        $home = isset($queue[sha1('/')]) ? $queue[sha1('/')] : array();
        sb_assert(isset($article['url']) && home_url('/news/story/') === $article['url']
            && 'refresh' === $article['action'] && 'single' === $article['role'] && 8841 === $article['post_id']
            && isset($article['manual_push_token']) && $push_token === $article['manual_push_token'], 'The manual push did not queue the exact article as a single-route refresh with a completion token.');
        $push_status = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
        sb_assert(isset($push_status[$push_token]['status']) && 'queued' === $push_status[$push_token]['status'], 'The manual push did not persist its pending status for user feedback.');
        sb_assert(isset($home['url']) && home_url('/') === $home['url'] && 'dependent' === $home['role'], 'The manual push omitted the homepage/archive dependency.');
        sb_assert(wp_next_scheduled('static_bridge_process_incremental_queue'), 'The manual push was queued without scheduling the incremental worker.');
        sb_assert(sha1('/news/story/') === array_key_first($queue), 'A manual single-route push was left behind older queue items instead of being prioritized.');

        $queue[sha1('/news/story/')]['last_error'] = 'HTTP 503 at https://news.example.test/news/story/?token=diagnostic-secret';
        update_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, $queue, false);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array(array(
            'time' => '2026-10-01 12:00',
            'message' => 'Aggiornamento incrementale non riuscito.',
            'detail' => '/news/story/ — https://news.example.test/news/story/?nonce=activity-secret — /news/story/?session=relative-secret',
            'error' => true,
        ));

        $plugin->register_mcp_ability_category();
        $plugin->register_mcp_abilities();
        $ability = isset($GLOBALS['sb_test_wp_abilities']['abilities'][Static_Bridge_Plugin::MCP_PUSH_DIAGNOSTIC_ABILITY])
            ? $GLOBALS['sb_test_wp_abilities']['abilities'][Static_Bridge_Plugin::MCP_PUSH_DIAGNOSTIC_ABILITY]
            : array();
        sb_assert(isset($GLOBALS['sb_test_wp_abilities']['categories'][Static_Bridge_Plugin::MCP_ABILITY_CATEGORY])
            && isset($ability['meta']['public'], $ability['meta']['show_in_rest'], $ability['meta']['mcp']['public'], $ability['meta']['mcp']['type'], $ability['meta']['annotations']['readonly'])
            && true === $ability['meta']['public'] && false === $ability['meta']['show_in_rest']
            && true === $ability['meta']['mcp']['public'] && 'tool' === $ability['meta']['mcp']['type']
            && true === $ability['meta']['annotations']['readonly'],
            'The push diagnostic ability must be discoverable to authenticated MCP clients, read-only, and not exposed through the public REST API.');
        sb_assert(isset($ability['input_schema']['required']) && array('post_id') === $ability['input_schema']['required'],
            'The push diagnostic ability must require exactly one content ID.');
        $push_ability = isset($GLOBALS['sb_test_wp_abilities']['abilities'][Static_Bridge_Plugin::MCP_PUSH_POST_ABILITY])
            ? $GLOBALS['sb_test_wp_abilities']['abilities'][Static_Bridge_Plugin::MCP_PUSH_POST_ABILITY]
            : array();
        sb_assert(isset($push_ability['meta']['mcp']['public'], $push_ability['meta']['mcp']['type'], $push_ability['meta']['show_in_rest'], $push_ability['meta']['annotations']['readonly'], $push_ability['meta']['annotations']['destructive'])
            && true === $push_ability['meta']['mcp']['public'] && 'tool' === $push_ability['meta']['mcp']['type']
            && false === $push_ability['meta']['show_in_rest'] && false === $push_ability['meta']['annotations']['readonly']
            && false === $push_ability['meta']['annotations']['destructive']
            && array('post_id', 'confirm') === $push_ability['input_schema']['required'],
            'The MCP push ability must require explicit confirmation, stay out of public REST, and be marked as a bounded non-destructive write tool.');
        $GLOBALS['sb_test_can_manage'] = false;
        $push_denied = false === call_user_func($push_ability['permission_callback'], array('post_id' => 8841, 'confirm' => true))
            && is_wp_error(call_user_func($push_ability['execute_callback'], array('post_id' => 8841, 'confirm' => true)));
        $GLOBALS['sb_test_can_manage'] = true;
        sb_assert($push_denied
            && is_wp_error(call_user_func($push_ability['execute_callback'], array('post_id' => 8841, 'confirm' => false))),
            'The MCP push tool must deny unauthorized users and refuse execution without explicit confirmation.');
        $diagnostic_options_before = $GLOBALS['sb_test_options'];
        $diagnostic_cron_before = $GLOBALS['sb_test_scheduled_hooks'];
        $diagnostic = call_user_func($ability['execute_callback'], array('post_id' => 8841));
        sb_assert(is_array($diagnostic) && 8841 === $diagnostic['post_id'] && true === $diagnostic['post_exists']
            && '/news/story/' === $diagnostic['route'] && 'queued' === $diagnostic['push_status']
            && true === $diagnostic['static_file_exists'] && true === $diagnostic['file_may_be_stale']
            && !empty($diagnostic['queue_items']) && true === $diagnostic['queue_items'][0]['has_manual_push'],
            'The MCP diagnostic did not report the queued push, active static file, and stale-file signal for the requested post.');
        sb_assert(0 < $diagnostic['worker_scheduled_at'] && !empty($diagnostic['recent_activity'])
            && false !== strpos($diagnostic['queue_items'][0]['last_error'], '[query redacted]')
            && false !== strpos($diagnostic['recent_activity'][0]['detail'], '[query redacted]')
            && false === strpos(wp_json_encode($diagnostic), 'diagnostic-secret')
            && false === strpos(wp_json_encode($diagnostic), 'activity-secret')
            && false === strpos(wp_json_encode($diagnostic), 'relative-secret'),
            'The MCP diagnostic must expose worker/error evidence while redacting URL query secrets.');
        sb_assert($diagnostic_options_before === $GLOBALS['sb_test_options'] && $diagnostic_cron_before === $GLOBALS['sb_test_scheduled_hooks'],
            'The MCP push diagnostic must not mutate options or scheduled jobs.');
        sb_assert(false === array_key_exists('url', $diagnostic['queue_items'][0])
            && false === array_key_exists('manual_push_token', $diagnostic['queue_items'][0])
            && false === array_key_exists('user_id', $diagnostic['queue_items'][0]),
            'The MCP push diagnostic must not disclose queue URLs, push tokens, or user IDs.');
        $GLOBALS['sb_test_can_manage'] = false;
        sb_assert(false === call_user_func($ability['permission_callback'], array('post_id' => 8841))
            && is_wp_error(call_user_func($ability['execute_callback'], array('post_id' => 8841))),
            'The MCP push diagnostic must deny callers without manage_options.');
        $GLOBALS['sb_test_can_manage'] = true;

        $manifest_file = $release . '/manifest.json';
        sb_assert(false !== file_put_contents($manifest_file, wp_json_encode(array('release' => $release_id, 'pages_saved' => 2, 'incremental_updates' => 0))), 'Could not seed the manual-push manifest fixture.');
        $render_url = add_query_arg('static_bridge_bypass', '1', home_url('/news/story/'));
        $GLOBALS['sb_test_http_responses'] = array($render_url => array(
            'response' => array('code' => 200),
            'headers' => array('content-type' => 'text/html; charset=UTF-8'),
            'body' => '<html><body>freshly rendered article</body></html>',
        ));
        $GLOBALS['sb_test_http_calls'] = array();
        $direct_push = sb_private($plugin, 'process_manual_post_push_now', array($post, $push_token));
        $published_html = is_file($release . '/news/story/index.html') ? file_get_contents($release . '/news/story/index.html') : '';
        $published_manifest = json_decode((string) file_get_contents($manifest_file), true);
        $queue_after_direct_push = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $status_after_direct_push = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
        sb_assert(true === $direct_push && false !== strpos($published_html, 'freshly rendered article')
            && !isset($queue_after_direct_push[sha1('/news/story/')])
            && isset($queue_after_direct_push[sha1('/')])
            && 'completed' === $status_after_direct_push[$push_token]['status']
            && 1 === (int) $published_manifest['incremental_updates']
            && 1 === count($GLOBALS['sb_test_http_calls']),
            'The manual push did not synchronously render, publish, and confirm only the requested article route.');
        $retry_token = 'bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb';
        sb_assert(true === sb_private($plugin, 'queue_manual_post_push', array($post, $retry_token)), 'The retry fixture could not enqueue a second manual push.');
        $previous_html = file_get_contents($release . '/news/story/index.html');
        $GLOBALS['sb_test_http_responses'][$render_url] = array(
            'response' => array('code' => 503),
            'headers' => array('content-type' => 'text/html; charset=UTF-8'),
            'body' => '<html>temporary server error</html>',
        );
        $retry_result = sb_private($plugin, 'process_manual_post_push_now', array($post, $retry_token));
        $retry_queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $retry_statuses = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
        sb_assert(false === $retry_result && $previous_html === file_get_contents($release . '/news/story/index.html')
            && isset($retry_queue[sha1('/news/story/')]) && 1 === (int) $retry_queue[sha1('/news/story/')]['attempts']
            && 'retrying' === $retry_statuses[$retry_token]['status']
            && false !== strpos($retry_statuses[$retry_token]['last_error'], '503'),
            'A failed immediate render must preserve the previous static page and expose a retry instead of claiming success.');

        $no_confirm = call_user_func($push_ability['execute_callback'], array('post_id' => 8841, 'confirm' => false));
        sb_assert(is_wp_error($no_confirm) && $previous_html === file_get_contents($release . '/news/story/index.html'),
            'The MCP push tool must refuse a request without confirmation and leave the prior static file untouched.');
        $GLOBALS['sb_test_posts'][0]['post_modified_gmt'] = gmdate('Y-m-d H:i:s', time() - 60);
        $GLOBALS['sb_test_http_responses'][$render_url] = array(
            'response' => array('code' => 200),
            'headers' => array('content-type' => 'text/html; charset=UTF-8'),
            'body' => '<html><body>fresh MCP-rendered article</body></html>',
        );
        $mcp_push_result = call_user_func($push_ability['execute_callback'], array('post_id' => 8841, 'confirm' => true));
        $mcp_published_html = file_get_contents($release . '/news/story/index.html');
        $mcp_queue_after_push = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert(is_array($mcp_push_result) && 8841 === $mcp_push_result['post_id']
            && '/news/story/' === $mcp_push_result['route'] && 'completed' === $mcp_push_result['status']
            && true === $mcp_push_result['static_file_exists'] && false === $mcp_push_result['file_may_be_stale']
            && hash('sha256', $mcp_published_html) === $mcp_push_result['static_file_sha256']
            && false !== strpos($mcp_published_html, 'fresh MCP-rendered article')
            && !isset($mcp_queue_after_push[sha1('/news/story/')])
            && isset($mcp_queue_after_push[sha1('/')]),
            'A confirmed MCP push must synchronously publish the fresh page, verify its file hash, and leave only dependent routes queued. Result: ' . wp_json_encode($mcp_push_result) . ' Queue keys: ' . wp_json_encode(array_keys($mcp_queue_after_push)) . ' HTML: ' . $mcp_published_html);
        $push_handler_body = sb_method_body($source, 'handle_post_push');
        $queue_call_position = strpos($push_handler_body, '$this->queue_manual_post_push($post, $push_token)');
        $direct_call_position = strpos($push_handler_body, '$this->process_manual_post_push_now($post, $push_token)');
        $redirect_call_position = strpos($push_handler_body, 'wp_safe_redirect(');
        sb_assert(false !== $queue_call_position && false !== $direct_call_position && false !== $redirect_call_position
            && $queue_call_position < $direct_call_position && $direct_call_position < $redirect_call_position,
            'The authenticated manual-push action must process the requested article before redirecting to the editor.');

        sb_private($plugin, 'set_post_push_status', array($push_token, 'completed', array('completed_at' => time())));
        $_REQUEST['token'] = $push_token;
        $GLOBALS['sb_test_nonce_calls'] = 0;
        $status_response = null;
        try {
            $plugin->handle_post_push_status();
        } catch (SB_Test_Response $response) {
            $status_response = $response;
        }
        sb_assert($status_response instanceof SB_Test_Response && 200 === $status_response->status
            && isset($status_response->data['status']) && 'completed' === $status_response->data['status']
            && 1 === $GLOBALS['sb_test_nonce_calls'], 'The authenticated status endpoint did not report a completed push after nonce validation.');
        unset($_REQUEST['token']);

        $worker_body = sb_method_body($source, 'process_incremental_item');
        $file_check = strpos($worker_body, 'is_file($write[\'file\'])');
        $manifest_check = strpos($worker_body, '$this->update_incremental_manifest($release, $page_delta)');
        $completed_status = strpos($worker_body, '$this->set_post_push_status($manual_push_token, \'completed\'');
        sb_assert(false !== $file_check && false !== $manifest_check && false !== $completed_status
            && $file_check < $manifest_check && $manifest_check < $completed_status,
            'The UI completion state must be persisted only after a real static file and its release manifest are confirmed.');
        sb_assert(false !== strpos($worker_body, 'realpath($release) === $this->current_release()'), 'The completion state must refer to the currently published release.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array('/news/story/');
        $blocked_actions = $plugin->add_post_push_row_action(array('edit' => 'Edit'), $post);
        $blocked_push = sb_private($plugin, 'queue_manual_post_push', array($post));
        $blocked_mcp_push = call_user_func($push_ability['execute_callback'], array('post_id' => 8841, 'confirm' => true));
        sb_assert(!isset($blocked_actions['static_bridge_push']) && is_wp_error($blocked_push) && is_wp_error($blocked_mcp_push), 'A route configured as dynamic/excluded still exposed or accepted a static push.');
    } finally {
        if (is_link($current)) {
            @unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array($release . '/index.html', $release . '/news/story/index.html', $release . '/manifest.json') as $file) {
            if (is_link($file) || is_file($file)) {
                @unlink($file);
            }
        }
        foreach (array($release . '/news/story', $release . '/news', $release, $static_root . '/releases') as $directory) {
            if (is_dir($directory) && !is_link($directory)) {
                @rmdir($directory);
            }
        }
        foreach ($old_options as $option => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$option]);
            } else {
                $GLOBALS['sb_test_options'][$option] = $value;
            }
        }
        $GLOBALS['sb_test_post_types'] = $old_post_types;
        $GLOBALS['sb_test_posts'] = $old_posts;
        $GLOBALS['sb_test_post_urls'] = $old_post_urls;
        $GLOBALS['sb_test_transients'] = $old_transients;
        $GLOBALS['sb_test_meta_boxes'] = $old_meta_boxes;
        $GLOBALS['sb_test_http_responses'] = $old_http_responses;
        $GLOBALS['sb_test_http_calls'] = $old_http_calls;
        if (false === $old_scheduled) {
            unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']);
        } else {
            $GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue'] = $old_scheduled;
        }
    }
});

sb_test('Query-based public post and page permalinks are reported as dynamic skips', function () use ($plugin) {
    $GLOBALS['sb_test_post_types'] = array(
        'post' => array('public' => true, 'publicly_queryable' => true),
        'page' => array('public' => true, 'publicly_queryable' => false),
    );
    $GLOBALS['sb_test_posts'] = array(
        array('ID' => 1, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => ''),
        array('ID' => 2, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => ''),
    );
    $GLOBALS['sb_test_post_urls'] = array(
        1 => home_url('/?p=1'),
        2 => home_url('/?page_id=2'),
    );
    $batch = sb_private($plugin, 'discover_wordpress_post_url_batch', array(0));
    sb_assert(array() === $batch['urls'], 'Query-based content was incorrectly added to the static file queue.');
    sb_assert(array(home_url('/?p=1'), home_url('/?page_id=2')) === $batch['dynamic_urls'], 'Query-based public routes were silently dropped instead of reported for dynamic fallback.');
    sb_assert(2 === (int) $batch['cursor'] && true === $batch['complete'], 'The query-based content batch did not advance its keyset cursor.');

    $GLOBALS['sb_test_post_types'] = array();
    $GLOBALS['sb_test_posts'] = array();
    $GLOBALS['sb_test_post_urls'] = array();
});

sb_test('Published shared components queue every existing static route safely', function () use ($fixtureRoot, $plugin) {
    $plugin = new Static_Bridge_Plugin();
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'shared-refresh-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $outside = $fixtureRoot . '/shared-refresh-outside';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $old_options = array();
    foreach (array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION) as $option) {
        $old_options[$option] = array_key_exists($option, $GLOBALS['sb_test_options']) ? $GLOBALS['sb_test_options'][$option] : null;
    }
    $old_scheduled = isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue'])
        ? $GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']
        : false;
    $old_post_types = $GLOBALS['sb_test_post_types'];

    try {
        sb_assert(false !== $old_current_target || (!file_exists($current) && !is_link($current)), 'The current release fixture is not a symlink and cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/news/one') && wp_mkdir_p($release . '/page-two') && wp_mkdir_p($outside), 'Could not create the isolated shared-content fixture.');
        sb_assert(false !== file_put_contents($release . '/index.html', '<html>home</html>'), 'Could not seed the static homepage.');
        sb_assert(false !== file_put_contents($release . '/news/one/index.html', '<html>article</html>'), 'Could not seed a static article.');
        sb_assert(false !== file_put_contents($release . '/page-two/index.html', '<html>page</html>'), 'Could not seed a static page.');
        sb_assert(false !== file_put_contents($release . '/not-a-route.html', '<html>not a route</html>'), 'Could not seed a non-route HTML file.');
        sb_assert(wp_mkdir_p($outside . '/secret') && false !== file_put_contents($outside . '/secret/index.html', '<html>outside</html>'), 'Could not seed the symlink escape sentinel.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its test release.');
        if (function_exists('symlink')) {
            @symlink($outside, $release . '/escaped');
        }

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array());
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']);
        $shared_block = new WP_Post(array('ID' => 8701, 'post_type' => 'wp_block', 'post_status' => 'publish'));
        $plugin->maybe_queue_shared_content_post(8701, $shared_block, true, null);

        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $paths = array();
        foreach ($queue as $item) {
            $paths[] = $item['path'];
            sb_assert('refresh' === $item['action'] && 'dependent' === $item['role'] && 0 === $item['post_id'], 'A shared refresh was treated as a single-post update.');
            sb_assert(!empty($item['shared_content']), 'A shared refresh lost its global-component provenance marker.');
        }
        sort($paths);
        sb_assert(array('/','/news/one/','/page-two/') === $paths, 'A shared Gutenberg block did not queue exactly the homepage and all static page routes.');
        sb_assert(wp_next_scheduled('static_bridge_process_incremental_queue'), 'Shared static routes were queued without scheduling the incremental worker.');
        $expected_shared_hooks = array(
            'customize_save_after' => 'maybe_queue_customizer_shared_output',
            'added_option' => 'maybe_queue_bricks_global_option',
            'updated_option' => 'maybe_queue_bricks_global_option',
            'deleted_option' => 'maybe_queue_bricks_global_option',
            'added_option ' => 'maybe_queue_etch_global_option',
            'updated_option ' => 'maybe_queue_etch_global_option',
            'deleted_option ' => 'maybe_queue_etch_global_option',
        );
        foreach ($expected_shared_hooks as $hook_name => $callback_name) {
            $hook_name = trim($hook_name);
            $hook_registered = false;
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                if ($hook_name === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0]
                    && $callback_name === $hook[1][1]) {
                    $hook_registered = true;
                    break;
                }
            }
            sb_assert($hook_registered, 'A global component save hook is not registered: ' . $hook_name . '.');
        }
        sb_assert(sb_private($plugin, 'is_shared_content_post_type', array('wp_block'))
            && sb_private($plugin, 'is_shared_content_post_type', array('wp_template'))
            && sb_private($plugin, 'is_shared_content_post_type', array('wp_template_part'))
            && sb_private($plugin, 'is_shared_content_post_type', array('wp_navigation'))
            && sb_private($plugin, 'is_shared_content_post_type', array('wp_global_styles'))
            && !sb_private($plugin, 'is_shared_content_post_type', array('post')), 'Core shared Gutenberg entity types are not recognized generically.');

        $GLOBALS['sb_test_post_types'] = array(
            'bricks_template' => array('public' => true, 'publicly_queryable' => true),
            'kadence_element' => array('public' => true, 'publicly_queryable' => true),
        );
        sb_assert(sb_private($plugin, 'is_shared_content_post_type', array('bricks_template'))
            && sb_private($plugin, 'is_shared_content_post_type', array('kadence_element'))
            && !sb_private($plugin, 'is_shared_content_post_type', array('unrelated_template')),
            'Registered Bricks/Kadence global component types were not recognized safely.');
        $bricks_plugin = new Static_Bridge_Plugin();
        $bricks_plugin->maybe_queue_shared_content_post(8704, new WP_Post(array('ID' => 8704, 'post_type' => 'bricks_template', 'post_status' => 'publish')), true, null);
        $kadence_plugin = new Static_Bridge_Plugin();
        $kadence_plugin->maybe_queue_shared_content_post(8705, new WP_Post(array('ID' => 8705, 'post_type' => 'kadence_element', 'post_status' => 'publish')), true, null);
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
            'Saving a Bricks or Kadence global component did not enqueue the current static routes.');

        $GLOBALS['sb_test_post_types'] = array();
        sb_assert(!sb_private($plugin, 'is_shared_content_post_type', array('bricks_template'))
            && !sb_private($plugin, 'is_shared_content_post_type', array('kadence_element')),
            'An inactive/unregistered builder post type was treated as a shared component.');

        $bricks_global_options = array(
            'bricks_global_classes', 'bricks_global_variables', 'bricks_theme_styles',
            'bricks_color_palette', 'bricks_breakpoints', 'bricks_components', 'bricks_pseudo_classes',
        );
        foreach ($bricks_global_options as $global_option) {
            $bricks_options_plugin = new Static_Bridge_Plugin();
            $bricks_options_plugin->maybe_queue_bricks_global_option($global_option, array(), array('changed' => true));
        }
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
            'One or more Bricks global data options did not enqueue the current static routes.');
        $activity_before_ignored_option = count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()));
        $ignored_options_plugin = new Static_Bridge_Plugin();
        $ignored_options_plugin->maybe_queue_bricks_global_option('siteurl', 'old', 'new');
        sb_assert($activity_before_ignored_option === count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array())),
            'An unrelated WordPress option triggered a global static refresh.');
        $customizer_plugin = new Static_Bridge_Plugin();
        $customizer_plugin->maybe_queue_customizer_shared_output(null);
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
            'A theme Customizer save did not enqueue the current static routes.');

        // Etch: styles, global stylesheets and loops are options; a CSS change made in Etch alone left every page stale.
        foreach (array('etch_styles', 'etch_global_stylesheets', 'etch_loops', 'etch_queries', 'etch_components') as $etch_option) {
            foreach (array(array($etch_option, array('a' => 1)), array($etch_option, array(), array('a' => 1)), array($etch_option)) as $etch_args) {
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
                call_user_func_array(array(new Static_Bridge_Plugin(), 'maybe_queue_etch_global_option'), $etch_args);
                sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
                    'Etch option ' . $etch_option . ' (' . count($etch_args) . ' hook arguments) did not enqueue the current static routes.');
            }
        }
        $etch_settings = array('remove_wp_default_styles_and_scripts' => true, 'ai_api_key' => 'k', 'experimental_ai' => false);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        (new Static_Bridge_Plugin())->maybe_queue_etch_global_option('etch_settings', $etch_settings, array_merge($etch_settings, array('ai_api_key' => 'other', 'experimental_ai' => true)));
        (new Static_Bridge_Plugin())->maybe_queue_etch_global_option('etch_ui_state', array(), array('panel' => 1));
        (new Static_Bridge_Plugin())->maybe_queue_etch_global_option('etch_stylesheets', array(), array('a' => 1));
        sb_assert(array() === get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()),
            'An Etch AI setting, its UI state or an unrelated option regenerated every page.');
        (new Static_Bridge_Plugin())->maybe_queue_etch_global_option('etch_settings', $etch_settings, array_merge($etch_settings, array('remove_wp_default_styles_and_scripts' => false)));
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
            'An Etch setting that changes the page output did not enqueue the current static routes.');
        // An Etch component is a wp_block whose properties live in etch_* meta; a meta-only save refreshes too.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_posts'] = array(array('ID' => 8717, 'post_type' => 'wp_block', 'post_status' => 'publish'));
        foreach (array('added_post_meta', 'updated_post_meta', 'deleted_post_meta') as $etch_meta_hook) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
            (new Static_Bridge_Plugin())->maybe_queue_shared_content_meta(57, 8717, 'etch_component_properties', array());
            sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())),
                'A meta-only save of an Etch component (' . $etch_meta_hook . ') did not enqueue the current static routes.');
        }
        $GLOBALS['sb_test_posts'] = array();
        // The activity log keeps 30 lines; the checks below count new ones.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();

        $GLOBALS['sb_test_post_types'] = array('bricks_template' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(array('ID' => 8706, 'post_type' => 'bricks_template', 'post_status' => 'publish'));
        $bricks_template_meta_plugin = new Static_Bridge_Plugin();
        $bricks_template_meta_plugin->maybe_queue_bricks_meta(56, 8706, '_bricks_page_content_2', array());
        $bricks_template_queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $bricks_template_urls = array_map(static function ($item) {
            return isset($item['url']) ? $item['url'] : '';
        }, $bricks_template_queue);
        sb_assert(!in_array(home_url('/post-8706/'), $bricks_template_urls, true),
            'Saving a Bricks shared template incorrectly queued its own synthetic permalink as a public content route.');
        $GLOBALS['sb_test_post_types'] = array();

        $GLOBALS['sb_test_posts'] = array(array('ID' => 8702, 'post_type' => 'wp_block', 'post_status' => 'publish'));
        $meta_plugin = new Static_Bridge_Plugin();
        $meta_plugin->maybe_queue_shared_content_meta(55, 8702, '_example', 'updated');
        $GLOBALS['sb_test_posts'] = array();
        $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())), 'Shared metadata changes did not enter the same deduplicated refresh path.');
        sb_assert(!empty($activity) && false !== strpos(end($activity)['message'], 'Aggiornamento incrementale'), 'The shared-component refresh was not visible in the activity log.');

        $GLOBALS['sb_test_post_types'] = array('elementor_library' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(array('ID' => 8707, 'post_type' => 'elementor_library', 'post_status' => 'publish'));
        $elementor_meta_plugin = new Static_Bridge_Plugin();
        $activity_before_generated_meta = count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()));
        $elementor_meta_plugin->maybe_queue_shared_content_meta(57, 8707, '_elementor_css', 'generated');
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()))
            && $activity_before_generated_meta === count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array())),
            'Generated Elementor CSS/cache metadata caused a redundant shared-route refresh.');
        $elementor_meta_plugin->maybe_queue_shared_content_meta(58, 8707, '_elementor_data', 'edited');
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()))
            && $activity_before_generated_meta < count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array())),
            'A real Elementor document-content change did not queue its shared-route refresh.');
        $GLOBALS['sb_test_posts'] = array();
        $GLOBALS['sb_test_post_types'] = array();

        $unpublished = new WP_Post(array('ID' => 8703, 'post_type' => 'wp_block', 'post_status' => 'draft'));
        $draft_plugin = new Static_Bridge_Plugin();
        $draft_plugin->maybe_queue_shared_content_post(8703, $unpublished, true, null);
        sb_assert(3 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())), 'A draft-only shared pattern caused unnecessary static regeneration.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array(
            $release . '/index.html', $release . '/news/one/index.html', $release . '/page-two/index.html',
            $release . '/not-a-route.html', $outside . '/secret/index.html', $release . '/escaped',
        ) as $file) {
            if (is_link($file) || is_file($file)) {
                @unlink($file);
            }
        }
        foreach (array($release . '/news/one', $release . '/news', $release . '/page-two', $release, $static_root . '/releases', $static_root, $outside . '/secret', $outside) as $directory) {
            if (is_dir($directory) && !is_link($directory)) {
                @rmdir($directory);
            }
        }
        foreach ($old_options as $option => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$option]);
            } else {
                $GLOBALS['sb_test_options'][$option] = $value;
            }
        }
        if (false === $old_scheduled) {
            unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']);
        } else {
            $GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue'] = $old_scheduled;
        }
        $GLOBALS['sb_test_post_types'] = $old_post_types;
        $GLOBALS['sb_test_posts'] = array();
    }
});

sb_test('Shared-route redirects are removed safely and do not retry forever', function () use ($plugin) {
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'shared-redirect-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $option_names = array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION);
    $old_options = array();
    foreach ($option_names as $option) {
        $old_options[$option] = array_key_exists($option, $GLOBALS['sb_test_options']) ? $GLOBALS['sb_test_options'][$option] : null;
    }
    $old_responses = $GLOBALS['sb_test_http_responses'];
    $old_calls = $GLOBALS['sb_test_http_calls'];

    try {
        sb_assert(false !== $old_current_target || (!file_exists($current) && !is_link($current)), 'The current release fixture is not a symlink and cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/legacy-component') && wp_mkdir_p($release . '/canonical-component'), 'Could not create the redirect release fixture.');
        sb_assert(false !== file_put_contents($release . '/index.html', '<html>home</html>'), 'Could not seed the redirect fixture homepage.');
        sb_assert(false !== file_put_contents($release . '/legacy-component/index.html', '<html>legacy</html>'), 'Could not seed the internal redirect alias.');
        sb_assert(false !== file_put_contents($release . '/canonical-component/index.html', '<html>canonical</html>'), 'Could not seed the canonical route.');
        sb_assert(false !== file_put_contents($release . '/.ready', "ready\n"), 'Could not mark the redirect release ready.');
        sb_assert(false !== file_put_contents($release . '/manifest.json', wp_json_encode(array('release' => $release_id, 'pages_saved' => 3, 'incremental_updates' => 0))), 'Could not seed the redirect manifest.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its redirect fixture.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array());
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $GLOBALS['sb_test_http_calls'] = array();
        $alias_url = home_url('/legacy-component/');
        $target_url = home_url('/canonical-component/');
        $alias_path = '/legacy-component/';
        $alias_key = sha1($alias_path);
        $alias_item = array('url' => $alias_url, 'path' => $alias_path, 'action' => 'refresh', 'role' => 'dependent', 'post_id' => 0, 'builders' => array(), 'shared_content' => 1, 'queued_at' => time(), 'token' => wp_generate_uuid4(), 'attempts' => 0);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array($alias_key => $alias_item);
        $GLOBALS['sb_test_http_responses'] = array(
            add_query_arg('static_bridge_bypass', '1', $alias_url) => array(
                'response' => array('code' => 301),
                'headers' => array('Location' => $target_url . '?static_bridge_bypass=1'),
                'body' => '',
            ),
        );
        $internal = sb_private($plugin, 'process_incremental_item', array($alias_key, $alias_item, $release));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $manifest = json_decode((string) file_get_contents($release . '/manifest.json'), true);
        $target_key = sha1('/canonical-component/');
        sb_assert('done' === $internal && !is_file($release . '/legacy-component/index.html'), 'A same-origin alias was not removed from the static release.');
        sb_assert(2 === (int) ($manifest['pages_saved'] ?? 0), 'The manifest was not decremented for the removed alias.');
        sb_assert(isset($queue[$target_key]) && !empty($queue[$target_key]['shared_content']) && $target_url === $queue[$target_key]['url'], 'A same-origin canonical destination was not queued as a shared refresh.');
        sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The redirect target was followed in the same request instead of being queued.');

        sb_assert(false !== file_put_contents($release . '/legacy-component/index.html', '<html>external alias</html>'), 'Could not restore the route for the external-redirect test.');
        sb_assert(false !== file_put_contents($release . '/manifest.json', wp_json_encode(array('release' => $release_id, 'pages_saved' => 3, 'incremental_updates' => 1))), 'Could not restore the redirect manifest for the external-redirect test.');
        $external_item = array_merge($alias_item, array('token' => wp_generate_uuid4(), 'attempts' => 0));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array($alias_key => $external_item);
        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_responses'] = array(
            add_query_arg('static_bridge_bypass', '1', $alias_url) => array(
                'response' => array('code' => 302),
                'headers' => array('Location' => 'https://outside.example.test/legacy-component/'),
                'body' => '',
            ),
        );
        $external = sb_private($plugin, 'process_incremental_item', array($alias_key, $external_item, $release));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $manifest = json_decode((string) file_get_contents($release . '/manifest.json'), true);
        $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
        sb_assert('done' === $external && !is_file($release . '/legacy-component/index.html'), 'An external redirect alias was left serving stale static HTML.');
        sb_assert(empty($queue) && 2 === (int) ($manifest['pages_saved'] ?? 0), 'An external redirect left a retry loop or an incorrect manifest count.');
        sb_assert(!empty(end($activity)['error']) && false !== strpos(end($activity)['message'], 'destinazione esterna'), 'The ignored external redirect was not clearly recorded as an activity warning.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array($release . '/index.html', $release . '/legacy-component/index.html', $release . '/canonical-component/index.html', $release . '/manifest.json', $release . '/.ready') as $file) {
            if (is_link($file) || is_file($file)) {
                @unlink($file);
            }
        }
        foreach (array($release . '/legacy-component', $release . '/canonical-component', $release, $static_root . '/releases', $static_root) as $directory) {
            if (is_dir($directory) && !is_link($directory)) {
                @rmdir($directory);
            }
        }
        foreach ($old_options as $option => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$option]);
            } else {
                $GLOBALS['sb_test_options'][$option] = $value;
            }
        }
        $GLOBALS['sb_test_http_responses'] = $old_responses;
        $GLOBALS['sb_test_http_calls'] = $old_calls;
    }
});

sb_test('Redirecting archive routes are removed and a failing route does not block the queue', function () use ($plugin) {
    // 2.0.24: an author archive that an SEO plugin redirects to the homepage was retried forever as the
    // first queue item, so the pages listing the changed post (XB loops, facets., data.) were never refreshed.
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'archive-redirect-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $option_names = array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION);
    $old_options = array();
    foreach ($option_names as $option) {
        $old_options[$option] = array_key_exists($option, $GLOBALS['sb_test_options']) ? $GLOBALS['sb_test_options'][$option] : null;
    }
    $old_responses = $GLOBALS['sb_test_http_responses'];
    $old_calls = $GLOBALS['sb_test_http_calls'];

    try {
        sb_assert(false !== $old_current_target || (!file_exists($current) && !is_link($current)), 'The current release fixture is not a symlink and cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/author/redazione') && wp_mkdir_p($release . '/elenco'), 'Could not create the archive-redirect release fixture.');
        sb_assert(false !== file_put_contents($release . '/index.html', '<html>home</html>'), 'Could not seed the fixture homepage.');
        sb_assert(false !== file_put_contents($release . '/author/redazione/index.html', '<html>author</html>'), 'Could not seed the author archive.');
        sb_assert(false !== file_put_contents($release . '/elenco/index.html', '<html>list</html>'), 'Could not seed the list page.');
        sb_assert(false !== file_put_contents($release . '/.ready', "ready\n"), 'Could not mark the fixture release ready.');
        sb_assert(false !== file_put_contents($release . '/manifest.json', wp_json_encode(array('release' => $release_id, 'pages_saved' => 3, 'incremental_updates' => 0))), 'Could not seed the fixture manifest.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its fixture.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array());
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $GLOBALS['sb_test_http_calls'] = array();
        $item = static function ($path, $role) {
            return array('url' => home_url($path), 'path' => $path, 'action' => 'refresh', 'role' => $role, 'post_id' => 7, 'builders' => array(), 'queued_at' => time(), 'token' => wp_generate_uuid4(), 'attempts' => 0);
        };
        $author = $item('/author/redazione/', 'dependent');
        $list = $item('/elenco/', 'dependent');
        $author_key = sha1('/author/redazione/');
        $list_key = sha1('/elenco/');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array($author_key => $author, $list_key => $list);
        $GLOBALS['sb_test_http_responses'] = array(
            add_query_arg('static_bridge_bypass', '1', home_url('/author/redazione/')) => array(
                'response' => array('code' => 301),
                'headers' => array('Location' => home_url('/') . '?static_bridge_bypass=1'),
                'body' => '',
            ),
        );
        $result = sb_private($plugin, 'process_incremental_item', array($author_key, $author, $release));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $manifest = json_decode((string) file_get_contents($release . '/manifest.json'), true);
        sb_assert('done' === $result, 'A redirecting archive route of a changed post was left to retry forever.');
        sb_assert(!isset($queue[$author_key]) && !is_file($release . '/author/redazione/index.html'), 'The redirecting archive kept a static copy that bypasses the redirect.');
        sb_assert(2 === (int) ($manifest['pages_saved'] ?? 0), 'The manifest was not decremented for the removed archive.');
        sb_assert(isset($queue[$list_key]) && isset($queue[sha1('/')]) && empty($queue[sha1('/')]['shared_content']), 'The redirect destination was not queued as an ordinary refresh, or the list page was dropped.');
        sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The redirect was followed in the same request.');

        // Any other failure is retried, but behind the routes queued after it.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array($author_key => $author, $list_key => $list);
        sb_private($plugin, 'retry_incremental_item', array($author_key, $author, 'HTTP 500'));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert(array($list_key, $author_key) === array_keys($queue), 'A failing route stayed first in the queue and blocks every route after it.');
        sb_assert(1 === (int) $queue[$author_key]['attempts'] && 'HTTP 500' === $queue[$author_key]['last_error'] && $author['token'] === $queue[$author_key]['token'], 'The retried route lost its attempt count, error or token.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array($release . '/index.html', $release . '/author/redazione/index.html', $release . '/elenco/index.html', $release . '/manifest.json', $release . '/.ready') as $file) {
            if (is_link($file) || is_file($file)) {
                @unlink($file);
            }
        }
        foreach (array($release . '/author/redazione', $release . '/author', $release . '/elenco', $release, $static_root . '/releases', $static_root) as $directory) {
            if (is_dir($directory) && !is_link($directory)) {
                @rmdir($directory);
            }
        }
        foreach ($old_options as $option => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$option]);
            } else {
                $GLOBALS['sb_test_options'][$option] = $value;
            }
        }
        $GLOBALS['sb_test_http_responses'] = $old_responses;
        $GLOBALS['sb_test_http_calls'] = $old_calls;
    }
});

sb_test('Indexed export queue stores a 34,000-URL inventory in bounded batches', function () {
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    sb_assert($queue->install(), 'The queue schema is unavailable.');
    $job_id = '23456789-1234-4234-8234-123456789abc';
    $inserted = 0;
    for ($base = 1; $base <= 34000; $base += Static_Bridge_Export_Queue::BATCH_SIZE) {
        $batch = array();
        $end = min(34000, $base + Static_Bridge_Export_Queue::BATCH_SIZE - 1);
        for ($index = $base; $index <= $end; $index++) {
            $batch[] = home_url('/news/article-' . $index . '/');
        }
        sb_assert(count($batch) <= 100, 'The exporter built an unbounded insert batch.');
        $result = $queue->enqueue_batch($job_id, $batch);
        sb_assert(false !== $result, 'A bounded inventory batch could not be inserted.');
        $inserted += $result;
    }
    sb_assert(34000 === $inserted && 34000 === $queue->count_pending($job_id), 'The 34,000-URL inventory was truncated or duplicated.');
    $first = $queue->next_pending($job_id);
    sb_assert(is_array($first) && home_url('/news/article-1/') === $first['url'], 'Large queue order is not stable.');
    sb_assert($queue->mark($job_id, $first['url_hash'], 'done'), 'A row could not be resumed and marked complete.');
    sb_assert(33999 === $queue->count_pending($job_id), 'Queue progress was not durable after a completed item.');
    sb_assert($queue->delete_job($job_id), 'Large job cleanup failed.');
});

sb_test('34,000-post inventory uses resumable keyset pages of at most 100 IDs', function () use ($plugin) {
    $GLOBALS['sb_test_post_types'] = array('post' => array('public' => true, 'publicly_queryable' => true));
    $GLOBALS['sb_test_generated_post_count'] = 34000;
    $GLOBALS['sb_test_post_queries'] = array();
    $GLOBALS['sb_test_inventory_queries'] = array();
    $GLOBALS['sb_test_wp_post_raw_count'] = 0;
    $first = sb_private($plugin, 'discover_wordpress_post_url_batch', array(0));
    $second = sb_private($plugin, 'discover_wordpress_post_url_batch', array($first['cursor']));
    $last = sb_private($plugin, 'discover_wordpress_post_url_batch', array(33900));
    $end = sb_private($plugin, 'discover_wordpress_post_url_batch', array(34000));
    sb_assert(100 === count($first['urls']) && 100 === $first['cursor'] && empty($first['complete']), 'The first 100-post batch was not bounded or resumable.');
    sb_assert(100 === count($second['urls']) && 200 === $second['cursor'], 'The next inventory batch did not resume from the last ID.');
    sb_assert(100 === count($last['urls']) && 34000 === $last['cursor'] && empty($last['complete']), 'The final full batch was truncated or prematurely closed.');
    sb_assert(empty($end['urls']) && !empty($end['complete']), 'The empty terminal query did not close discovery.');
    $prepared = end($GLOBALS['sb_test_export_queue_prepared']);
    sb_assert(false !== strpos($prepared[0], 'ID > %d') && false !== strpos($prepared[0], 'LIMIT %d') && false === stripos($prepared[0], 'OFFSET'), 'The large inventory query is not keyset-indexed.');
    sb_assert(4 === count($GLOBALS['sb_test_inventory_queries']), 'The inventory did not issue exactly one query for each bounded keyset batch.');
    sb_assert(300 === $GLOBALS['sb_test_wp_post_raw_count'], 'Temporary WP_Post objects were not marked raw; get_permalink() would reload and retain them in the global post cache.');
    foreach ($GLOBALS['sb_test_inventory_queries'] as $query) {
        sb_assert(false !== strpos($query['sql'], 'SELECT * FROM wp_posts') && false !== strpos($query['sql'], 'ID > %d') && false !== strpos($query['sql'], 'LIMIT %d') && false === stripos($query['sql'], 'OFFSET'), 'The inventory is not a bounded keyset query over complete post rows.');
        sb_assert(100 === (int) end($query['args']), 'The complete-row query exceeded the 100-post memory bound.');
    }
    $GLOBALS['sb_test_post_types'] = array();
    $GLOBALS['sb_test_generated_post_count'] = 0;
    $GLOBALS['sb_test_post_queries'] = array();
    $GLOBALS['sb_test_inventory_queries'] = array();
});

sb_test('Full and incremental writes preserve output when the free-space reserve cannot be guaranteed', function () use ($plugin, $fixtureRoot) {
    $stage = $fixtureRoot . '/stage-disk-reserve';
    sb_assert(wp_mkdir_p($stage), 'Could not create an isolated disk-space fixture.');
    $url = home_url('/news/one/');
    $relative = sb_private($plugin, 'relative_html_path', array($url));
    sb_assert(!is_wp_error($relative), 'Could not map the isolated incremental URL.');
    $existing_file = $stage . '/' . $relative;
    sb_assert(wp_mkdir_p(dirname($existing_file)), 'Could not create the existing incremental page fixture.');
    sb_assert(false !== file_put_contents($existing_file, 'previous static html'), 'Could not seed the previous incremental page.');
    $manifest_file = $stage . '/manifest.json';
    $manifest_before = '{"pages_saved":1,"incremental_updates":0}';
    sb_assert(false !== file_put_contents($manifest_file, $manifest_before), 'Could not seed the isolated manifest.');
    $GLOBALS['sb_test_filter_values']['static_bridge_min_free_space_bytes'] = PHP_INT_MAX;
    try {
        $full_result = sb_private($plugin, 'write_export_page', array(
            array('stage' => $stage),
            'nested/index.html',
            '<html><body>must not be written</body></html>',
        ));
        $incremental_result = sb_private($plugin, 'write_incremental_page', array(
            $stage,
            $url,
            '<html><body>replacement must not be written</body></html>',
        ));
        $manifest_result = sb_private($plugin, 'update_incremental_manifest', array($stage, 0));
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_min_free_space_bytes']);
    }
    sb_assert(is_wp_error($full_result) && 'static_bridge_disk_space' === $full_result->get_error_code(), 'The full exporter did not stop when the configured reserve exceeded available disk space.');
    sb_assert(is_wp_error($incremental_result) && 'static_bridge_disk_space' === $incremental_result->get_error_code(), 'The incremental exporter did not stop when the configured reserve exceeded available disk space.');
    sb_assert(false === $manifest_result, 'The incremental manifest was replaced without the configured free-space reserve.');
    sb_assert(!file_exists($stage . '/nested') && 'previous static html' === file_get_contents($existing_file), 'Insufficient space created a partial full-export file or replaced the prior incremental page.');
    sb_assert($manifest_before === file_get_contents($manifest_file), 'Insufficient space changed the previous incremental manifest.');
    sb_assert(array('manifest.json', 'news') === array_values(array_diff(scandir($stage), array('.', '..'))), 'A failed incremental manifest write left a temporary file behind.');

    $incremental_success = sb_private($plugin, 'write_incremental_page', array($stage, $url, '<html><body>updated</body></html>'));
    sb_assert(is_array($incremental_success) && empty($incremental_success['created']), 'A normal incremental replacement did not complete as an update.');
    sb_assert('<html><body>updated</body></html>' === file_get_contents($existing_file), 'A normal incremental update did not atomically replace the expected HTML.');
    sb_assert(sb_private($plugin, 'update_incremental_manifest', array($stage, 0)), 'A normal incremental manifest update failed.');
});

sb_test('Incremental deletion accepts absent parents but rejects symlink escapes', function () use ($plugin, $fixtureRoot) {
    $stage = $fixtureRoot . '/incremental-delete-release';
    $outside = $fixtureRoot . '/incremental-delete-outside';
    sb_assert(wp_mkdir_p($stage) && wp_mkdir_p($outside), 'Could not create isolated deletion fixtures.');

    $missing_parent_result = sb_private($plugin, 'remove_incremental_page', array(
        $stage,
        home_url('/never-created/nested/page/'),
    ));
    sb_assert(is_array($missing_parent_result) && empty($missing_parent_result['deleted']), 'Deleting a never-written route failed because its parent directory does not exist.');

    $outside_file = $outside . '/index.html';
    sb_assert(false !== file_put_contents($outside_file, 'must remain outside the release'), 'Could not seed the symlink escape fixture.');
    $escape_link = $stage . '/escape';
    if (!function_exists('symlink') || !@symlink($outside, $escape_link)) {
        throw new SB_Test_Skip('Symlinks are unavailable in this test environment.');
    }
    $escape_result = sb_private($plugin, 'remove_incremental_page', array(
        $stage,
        home_url('/escape/'),
    ));
    sb_assert(is_wp_error($escape_result) && 'static_bridge_incremental_delete_escape' === $escape_result->get_error_code(), 'A symlink pointing outside the release was not rejected.');
    sb_assert('must remain outside the release' === file_get_contents($outside_file), 'The deletion routine modified a file outside the release.');
});

sb_test('Queue worker resumes between bounded requests and atomically publishes only after discovery and crawl finish', function () use ($plugin, $fixtureRoot) {
    $job_id = '34567890-1234-4234-8234-123456789abc';
    $release_id = 'queue-worker-smoke';
    $stage = WP_CONTENT_DIR . '/static-bridge/releases/' . $release_id;
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $current_link = WP_CONTENT_DIR . '/static-bridge/current';
    $strict_marker = WP_CONTENT_DIR . '/static-bridge/.strict';
    $previous_target = is_link($current_link) ? readlink($current_link) : false;
    $previous_strict = file_exists($strict_marker);
    $previous_last_release = get_option('static_bridge_last_release', null);
    $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    sb_assert($queue->install() && wp_mkdir_p($stage), 'Could not prepare the isolated queue worker fixture.');
    $home = home_url('/');
    sb_assert(1 === $queue->enqueue_batch($job_id, array($home)), 'The homepage seed could not be enqueued.');
    $GLOBALS['sb_test_post_types'] = array('post' => array('public' => true, 'publicly_queryable' => true));
    $GLOBALS['sb_test_generated_post_count'] = 2;
    $GLOBALS['sb_test_post_urls'] = array(1 => home_url('/blocked-post/'), 2 => home_url('/post-1/'));
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1,
        'job_id' => $job_id,
        'status' => 'running',
        'release_id' => $release_id,
        'stage' => $stage,
        'discovery_source' => 'wordpress-keyset',
        'discovery_cursor' => 0,
        'discovery_complete' => false,
        'discovered' => 1,
        'started_at' => time(),
        'updated_at' => time(),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
        'current_url' => '',
    );
    $home_fetch = $home . '?static_bridge_bypass=1';
    $blocked_url = home_url('/blocked-post/');
    $blocked_fetch = $blocked_url . '?static_bridge_bypass=1';
    $post_url = home_url('/post-1/');
    $post_fetch = $post_url . '?static_bridge_bypass=1';
    $GLOBALS['sb_test_http_responses'] = array(
        $home_fetch => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body><a href="/blocked-post/">Blocked</a><a href="/post-1/">News</a></body></html>'),
        $blocked_fetch => array('response' => array('code' => 404), 'headers' => array(), 'body' => 'Page not found', '_sb_strip_render_header' => true),
        $post_fetch => new WP_Error('http_request_failed', 'cURL error 28: Operation timed out.'),
    );
    $GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size'] = 1;
    $GLOBALS['sb_test_export_queue_total_count_queries'] = 0;

    $held_lock_expires = time() + 60;
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION] = array('token' => 'held-lock', 'expires' => $held_lock_expires);
    $waiting = sb_private($plugin, 'run_export_queue_step');
    sb_assert(0 === (int) $waiting['processed'], 'A concurrent worker bypassed the active export lock.');
    sb_assert(!empty($waiting['_worker_busy']), 'A worker lock collision was not reported to the GUI as a busy worker.');
    $waiting_response = sb_private($plugin, 'job_response', array($waiting));
    sb_assert(!empty($waiting_response['workerBusy']), 'The busy-worker state was not returned to the GUI.');
    $plugin->process_export_queue_cron();
    $busy_cron = wp_next_scheduled('static_bridge_process_export_queue');
    sb_assert(is_int($busy_cron) && abs($busy_cron - ($held_lock_expires + 1)) <= 1, 'A cron collision was retried every few seconds instead of waiting for the held worker lock to expire.');
    wp_clear_scheduled_hook('static_bridge_process_export_queue');
    delete_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION);

    $watchdog_seen_during_fetch = false;
    $previous_http_callback = $GLOBALS['sb_test_http_callback'];
    $GLOBALS['sb_test_http_callback'] = function ($url, $args) use (&$watchdog_seen_during_fetch) {
        $scheduled = wp_next_scheduled('static_bridge_process_export_queue');
        $watchdog_seen_during_fetch = is_int($scheduled)
            && $scheduled - time() >= Static_Bridge_Plugin::EXPORT_WORKER_LOCK_TTL
            && $scheduled - time() <= Static_Bridge_Plugin::EXPORT_WORKER_WATCHDOG_DELAY;
        return null;
    };
    try {
        $first = sb_private($plugin, 'run_export_queue_step');
    } finally {
        $GLOBALS['sb_test_http_callback'] = $previous_http_callback;
    }
    sb_assert($watchdog_seen_during_fetch, 'The durable watchdog was not scheduled before the worker started its loopback fetch.');
    $next_worker = wp_next_scheduled('static_bridge_process_export_queue');
    sb_assert(is_int($next_worker) && $next_worker - time() >= 0 && $next_worker - time() <= 5, 'A successful worker step did not replace its watchdog with the prompt next continuation.');
    sb_assert('running' === $first['status'] && !empty($first['discovery_complete']) && 1 === (int) $first['processed'] && 1 === (int) $first['saved'], 'The first bounded worker step did not discover and save exactly one page.');
    sb_assert(2 === $queue->count_pending($job_id), 'The worker did not persist its remaining indexed URLs for resume.');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION] = array('token' => 'terminated-worker', 'expires' => time() - 1);
    wp_schedule_single_event(time(), 'static_bridge_process_export_queue');
    $plugin->process_export_queue_cron();
    $second = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    sb_assert('running' === $second['status'] && 2 === (int) $second['processed'], 'The scheduled worker did not resume the indexed queue after an expired lock.');
    sb_assert('running' === $second['status'] && 2 === (int) $second['processed'] && 1 === (int) $second['saved'] && 1 === (int) $second['skipped'], 'A single page-level HTTP 404 stopped the queue instead of being recorded and skipped.');
    sb_assert(1 === $queue->count_pending($job_id), 'The worker did not continue with the other queued page after the 404.');
    $third = sb_private($plugin, 'run_export_queue_step');
    sb_assert('running' === $third['status'] && 2 === (int) $third['processed'] && 1 === (int) $third['saved'] && 1 === (int) $third['skipped'], 'A transient transport timeout was counted as a completed URL or stopped the export immediately.');
    sb_assert(1 === (int) $third['retry_attempts'] && 1 === $queue->count_pending($job_id), 'The transient URL was not left pending with a durable retry count.');
    $GLOBALS['sb_test_http_responses'][$post_fetch] = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Article</body></html>');
    $fourth = sb_private($plugin, 'run_export_queue_step');
    sb_assert('complete' === $fourth['status'] && 3 === (int) $fourth['processed'] && 2 === (int) $fourth['saved'] && 1 === (int) $fourth['skipped'], 'The resumed worker did not publish the page after its transient timeout recovered.');
    $legacy_manifest = json_decode(file_get_contents($stage . '/manifest.json'), true);
    sb_assert(is_array($legacy_manifest) && 0 === (int) $legacy_manifest['portable_internal_urls'], 'A legacy in-progress job was incorrectly marked fully portable after an upgrade.');
    sb_assert(3 === (int) $fourth['discovered'], 'The unique-URL counter diverged from the seeded URL, WordPress inventory and discovered links.');
    sb_assert(!isset($fourth['retry_attempts'], $fourth['retry_url_hash']), 'Retry metadata was not cleared after a successful page render.');
    sb_assert(0 === $GLOBALS['sb_test_export_queue_total_count_queries'], 'The export worker rescanned the full URL queue instead of using its unique-URL counter.');
    sb_assert(is_file($stage . '/index.html') && is_file($stage . '/post-1/index.html') && realpath($plugin ? WP_CONTENT_DIR . '/static-bridge/current' : '') === realpath($stage), 'The final release is missing files or was not atomically activated.');
    sb_assert(!file_exists($stage . '/blocked-post/index.html') && 404 === sb_private($plugin, 'fetch_page', array($blocked_url))->get_error_data(), 'The missing page was written or its HTTP status was not preserved for diagnostics.');
    sb_assert(0 === $queue->count_total($job_id), 'Completed job rows were left in the indexed queue.');
    $published_before_retry_failure = realpath($current_link);
    $failure_job_id = '56789012-1234-4234-8234-123456789abc';
    $failure_release_id = 'queue-retry-failure';
    $failure_stage = $static_root . '/releases/' . $failure_release_id;
    $old_home_html = file_get_contents($stage . '/index.html');
    sb_assert(wp_mkdir_p($failure_stage) && 2 === $queue->enqueue_batch($failure_job_id, array($home, $post_url)), 'The retry-exhaustion fixture could not be prepared.');
    $GLOBALS['sb_test_http_responses'][$home_fetch] = new WP_Error('static_bridge_render_unverified', 'Rendering WordPress non verificato (HTTP 200; cache presente).');
    $activity_before_route_failure = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1,
        'job_id' => $failure_job_id,
        'status' => 'running',
        'release_id' => $failure_release_id,
        'stage' => $failure_stage,
        'discovery_source' => 'wordpress-keyset',
        'discovery_cursor' => 1,
        'discovery_complete' => true,
        'discovered' => 2,
        'started_at' => time(),
        'updated_at' => time(),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
        'current_url' => '',
    );
    $mismatched_route_job = array('job_id' => $failure_job_id, 'release_id' => $failure_release_id, 'stage' => $failure_stage);
    $mismatched_route_args = array(
        &$mismatched_route_job,
        $queue,
        array('url' => $post_url, 'url_hash' => sha1($home)),
        $home,
        'Injected queue-row mismatch',
    );
    $pending_before_mismatch = $queue->count_pending($failure_job_id);
    $mismatched_route_result = sb_private($plugin, 'skip_failed_export_queue_url', $mismatched_route_args);
    sb_assert(is_wp_error($mismatched_route_result) && $pending_before_mismatch === $queue->count_pending($failure_job_id)
        && !isset($mismatched_route_job['route_errors']), 'A row whose URL and hash disagree was allowed to alter the queue or route counters.');
    $missing_copy_url = home_url('/route-without-a-previous-copy/');
    $missing_copy = sb_private($plugin, 'preserve_previous_export_route', array(get_option(Static_Bridge_Plugin::JOB_OPTION, array()), $missing_copy_url));
    sb_assert(is_array($missing_copy) && empty($missing_copy['preserved']), 'A route absent from the current release was incorrectly reported as preserved.');
    $outside_route = $fixtureRoot . '/route-preservation-outside.html';
    $symlink_route_file = $stage . '/symlink-preserve-test/index.html';
    sb_assert(false !== file_put_contents($outside_route, '<html>OUTSIDE_SENTINEL</html>')
        && wp_mkdir_p(dirname($symlink_route_file)) && symlink($outside_route, $symlink_route_file), 'The isolated symlink-preservation fixture could not be created.');
    $symlink_copy_url = home_url('/symlink-preserve-test/');
    $symlink_copy = sb_private($plugin, 'preserve_previous_export_route', array(get_option(Static_Bridge_Plugin::JOB_OPTION, array()), $symlink_copy_url));
    sb_assert(is_array($symlink_copy) && empty($symlink_copy['preserved'])
        && '<html>OUTSIDE_SENTINEL</html>' === file_get_contents($outside_route), 'The preservation helper followed a symlink or altered its external sentinel.');
    @unlink($outside_route);
    $retry_one = sb_private($plugin, 'run_export_queue_step');
    $retry_two = sb_private($plugin, 'run_export_queue_step');
    $retry_exhausted = sb_private($plugin, 'run_export_queue_step');
    sb_assert('running' === $retry_one['status'] && 1 === (int) $retry_one['retry_attempts'], 'The first failed attempt did not remain resumable.');
    sb_assert('running' === $retry_two['status'] && 2 === (int) $retry_two['retry_attempts'], 'The worker did not apply exactly two bounded retries.');
    sb_assert('running' === $retry_exhausted['status'] && 1 === (int) $retry_exhausted['processed'], 'Retry exhaustion stopped the export instead of recording and skipping only the failed route.');
    sb_assert(1 === (int) $retry_exhausted['route_errors'] && 1 === (int) $retry_exhausted['pages_preserved'] && 1 === (int) $retry_exhausted['saved'], 'The failed route was not counted once or its prior static copy was not retained.');
    sb_assert(2 === $queue->count_pending($failure_job_id) && is_dir($failure_stage) && !file_exists($failure_stage . '/.ready'), 'Retry exhaustion did not retain the remaining queue/staging or exposed a ready marker too early.');
    sb_assert($old_home_html === file_get_contents($failure_stage . '/index.html'), 'The last-known-good static page was not copied byte-for-byte into the new release.');
    sb_assert($published_before_retry_failure === realpath($current_link), 'The previous release changed before the rest of the export completed.');
    $activity_after_route_failure = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    $route_error_events = array_filter(array_slice($activity_after_route_failure, count($activity_before_route_failure)), function ($entry) {
        return is_array($entry) && !empty($entry['error']) && false !== strpos((string) ($entry['message'] ?? ''), 'Errore su una pagina');
    });
    sb_assert(1 === count($route_error_events), 'The failed route was not written exactly once as an error in Activity.');

    $GLOBALS['sb_test_http_responses'][$post_fetch] = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Article after failed route</body></html>');
    $failure_after_post = sb_private($plugin, 'run_export_queue_step');
    sb_assert('running' === $failure_after_post['status'] && 1 === $queue->count_pending($failure_job_id), 'The worker did not keep processing other URLs after recording a page error.');
    $failure_complete = sb_private($plugin, 'run_export_queue_step');
    sb_assert('complete' === $failure_complete['status'] && 3 === (int) $failure_complete['processed'] && 2 === (int) $failure_complete['saved'], 'The worker did not finish and publish the other route after recording a page error and skipping an ordinary 404.');
    sb_assert(1 === (int) $failure_complete['route_errors'] && 1 === (int) $failure_complete['pages_preserved'], 'The completed release lost its one-error and preserved-page counters.');
    $failure_manifest = json_decode(file_get_contents($failure_stage . '/manifest.json'), true);
    sb_assert(is_array($failure_manifest) && 1 === (int) ($failure_manifest['route_errors'] ?? -1) && 1 === (int) ($failure_manifest['pages_preserved'] ?? -1), 'The published manifest omitted the route error or retained-copy count.');
    sb_assert(is_file($failure_stage . '/post-1/index.html') && realpath($failure_stage) === realpath($current_link) && 0 === $queue->count_total($failure_job_id), 'The remaining route was not atomically published or its completed queue rows were retained.');

    $legacy_paused_job_id = '67890124-1234-4234-8234-123456789abc';
    $legacy_paused_release_id = 'queue-legacy-paused';
    $legacy_paused_stage = $static_root . '/releases/' . $legacy_paused_release_id;
    $legacy_failed_url = $post_url;
    $legacy_remaining_url = home_url('/other-page/');
    $legacy_remaining_fetch = $legacy_remaining_url . '?static_bridge_bypass=1';
    sb_assert(wp_mkdir_p($legacy_paused_stage) && 2 === $queue->enqueue_batch($legacy_paused_job_id, array($legacy_failed_url, $legacy_remaining_url)), 'The legacy-paused upgrade fixture could not be prepared.');
    $GLOBALS['sb_test_http_responses'][$legacy_remaining_fetch] = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Remaining page after upgrade</body></html>');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1,
        'job_id' => $legacy_paused_job_id,
        'status' => 'paused',
        'release_id' => $legacy_paused_release_id,
        'stage' => $legacy_paused_stage,
        'discovery_source' => 'wordpress-keyset',
        'discovery_cursor' => 1,
        'discovery_complete' => true,
        'discovered' => 2,
        'started_at' => time(),
        'updated_at' => time(),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(array('url' => $legacy_failed_url, 'message' => 'Rendering non verificato dopo i retry precedenti.', 'retryable_transient' => true)),
        'current_url' => $legacy_failed_url,
        'retry_url_hash' => sha1($legacy_failed_url),
        'retry_attempts' => Static_Bridge_Plugin::MAX_EXPORT_HTTP_RETRIES,
    );
    $paused_snapshot = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    $tampered_checkpoint = $paused_snapshot;
    $tampered_checkpoint['retry_url_hash'] = sha1(home_url('/different-url/'));
    $expired_checkpoint = $paused_snapshot;
    $expired_checkpoint['updated_at'] = time() - Static_Bridge_Plugin::EXPORT_JOB_MAX_AGE - 1;
    sb_assert(sb_private($plugin, 'job_is_resumable', array($paused_snapshot)), 'A valid paused queue was rejected before resume.');
    sb_assert(!sb_private($plugin, 'job_is_resumable', array($tampered_checkpoint)), 'Resume accepted a checkpoint bound to a different pending URL.');
    sb_assert(!sb_private($plugin, 'job_is_resumable', array($expired_checkpoint)), 'Resume accepted a job older than the configured maximum age.');
    $activity_before_legacy_resume = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    $resume_response = null;
    try {
        $plugin->ajax_resume();
    } catch (SB_Test_Response $response) {
        $resume_response = $response;
    }
    sb_assert($resume_response instanceof SB_Test_Response && 200 === $resume_response->status && isset($resume_response->data['status']) && 'running' === $resume_response->data['status'], 'The authenticated resume endpoint did not reopen the legacy paused job.');
    $resumed_job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    sb_assert('running' === $resumed_job['status'] && !isset($resumed_job['retry_attempts'], $resumed_job['retry_url_hash']) && 1 === $queue->count_pending($legacy_paused_job_id), 'Resume did not mark the already-failed URL skipped and retain the rest of the queue.');
    sb_assert(1 === (int) $resumed_job['route_errors'] && 1 === (int) $resumed_job['pages_preserved'] && empty(array_filter($resumed_job['issues'], function ($issue) { return is_array($issue) && !empty($issue['retryable_transient']); })), 'Resume left duplicate retry issues or failed to preserve the previous copy.');
    sb_assert(isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_export_queue']), 'Resume did not schedule the durable export worker.');
    sb_assert(realpath($failure_stage) === realpath($current_link), 'Resuming prematurely replaced the previously published release.');
    $legacy_activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    $legacy_route_errors = array_filter(array_slice($legacy_activity, count($activity_before_legacy_resume)), function ($entry) {
        return is_array($entry) && !empty($entry['error']) && false !== strpos((string) ($entry['message'] ?? ''), 'Errore su una pagina');
    });
    sb_assert(1 === count($legacy_route_errors), 'Upgrading a paused job did not create exactly one route-error activity record.');
    $resumed_job = sb_private($plugin, 'run_export_queue_step');
    sb_assert('complete' === $resumed_job['status'] && 2 === (int) $resumed_job['processed'] && 2 === (int) $resumed_job['saved'], 'The resumed legacy job did not finish the remaining URL.');
    sb_assert(1 === (int) $resumed_job['route_errors'] && 1 === (int) $resumed_job['pages_preserved'], 'The resumed legacy job lost its route-error summary.');
    sb_assert(realpath($legacy_paused_stage) === realpath($current_link) && 0 === $queue->count_total($legacy_paused_job_id), 'Successful legacy resume did not atomically publish and clear only the completed job queue.');

    $cancel_job_id = '67890123-1234-4234-8234-123456789abc';
    $cancel_stage = $static_root . '/releases/queue-pause-cancel';
    sb_assert(wp_mkdir_p($cancel_stage) && 1 === $queue->enqueue_batch($cancel_job_id, array($home)), 'The paused cancellation fixture could not be prepared.');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1,
        'job_id' => $cancel_job_id,
        'status' => 'paused',
        'release_id' => 'queue-pause-cancel',
        'stage' => $cancel_stage,
        'discovery_source' => 'wordpress-keyset',
        'discovery_cursor' => 1,
        'discovery_complete' => true,
        'discovered' => 1,
        'started_at' => time(),
        'updated_at' => time(),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
        'current_url' => $home,
        'retry_url_hash' => sha1($home),
        'retry_attempts' => Static_Bridge_Plugin::MAX_EXPORT_HTTP_RETRIES,
    );
    $cancel_response = null;
    try {
        $plugin->ajax_cancel();
    } catch (SB_Test_Response $response) {
        $cancel_response = $response;
    }
    sb_assert($cancel_response instanceof SB_Test_Response && 200 === $cancel_response->status && 'cancelled' === get_option(Static_Bridge_Plugin::JOB_OPTION, array())['status'], 'A paused job could not be explicitly cancelled.');
    sb_assert(0 === $queue->count_total($cancel_job_id) && is_dir($cancel_stage) && realpath($legacy_paused_stage) === realpath($current_link), 'Cancelling a paused job did not discard only its queue while preserving staging and the current release.');
    if (is_link($current_link)) {
        unlink($current_link);
    }
    if (false !== $previous_target) {
        symlink($previous_target, $current_link);
    }
    if (!$previous_strict && is_file($strict_marker)) {
        unlink($strict_marker);
    }
    if (null === $previous_last_release) {
        delete_option('static_bridge_last_release');
    } else {
        update_option('static_bridge_last_release', $previous_last_release, false);
    }
    $remove_test_stage = function ($path) use (&$remove_test_stage) {
        if (is_link($path) || is_file($path)) {
            @unlink($path);
            return;
        }
        if (!is_dir($path)) {
            return;
        }
        foreach (scandir($path) as $entry) {
            if ('.' === $entry || '..' === $entry) {
                continue;
            }
            $remove_test_stage($path . DIRECTORY_SEPARATOR . $entry);
        }
        @rmdir($path);
    };
    foreach (array($stage, $failure_stage, $legacy_paused_stage, $cancel_stage) as $test_stage) {
        $remove_test_stage($test_stage);
    }
    if (null === $previous_job) {
        delete_option(Static_Bridge_Plugin::JOB_OPTION);
    } else {
        update_option(Static_Bridge_Plugin::JOB_OPTION, $previous_job, false);
    }
    if (!$root_existed) {
        @rmdir(WP_CONTENT_DIR . '/static-bridge/releases');
        if (is_dir($static_root)) {
            $remaining = array_values(array_diff(scandir($static_root), array('.', '..')));
            sb_assert(empty($remaining), 'The queue worker test left unexpected Static Bridge fixture paths: ' . implode(', ', $remaining));
        }
        @rmdir($static_root);
    }
    $GLOBALS['sb_test_post_types'] = array();
    $GLOBALS['sb_test_generated_post_count'] = 0;
    $GLOBALS['sb_test_post_urls'] = array();
    $GLOBALS['sb_test_http_responses'] = array();
    unset($GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size']);
});

sb_test('A redirect inside the site is followed during an export and not reported as a page left out (2.4.1)', function () use ($plugin) {
    $job_id = '78901234-1234-4234-8234-123456789abc';
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $stage = $static_root . '/releases/queue-redirect-followed';
    $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    $old = home_url('/book-author/mario-rossi/');
    $target = home_url('/autori/');
    sb_assert($queue->install() && wp_mkdir_p($stage) && 2 === $queue->enqueue_batch($job_id, array($old, home_url('/'))), 'The redirect fixture could not be prepared.');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => 'queue-redirect-followed', 'stage' => $stage,
        'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 1, 'discovery_complete' => true, 'discovered' => 2,
        'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0, 'issues' => array(), 'current_url' => '',
    );
    $GLOBALS['sb_test_http_responses'] = array(
        $old . '?static_bridge_bypass=1' => array('response' => array('code' => 301), 'headers' => array('Location' => $target), 'body' => '', '_sb_strip_render_header' => true),
    );
    $GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size'] = 1;
    try {
        $job = sb_private($plugin, 'run_export_queue_step');
        sb_assert('running' === $job['status'] && 1 === (int) $job['processed'] && 0 === (int) $job['skipped'] && 1 === (int) ($job['redirects'] ?? 0), 'The redirect was counted as a page left out: ' . json_encode(array_intersect_key($job, array_flip(array('status', 'processed', 'skipped', 'redirects')))));
        sb_assert(array() === $job['issues'], 'The followed redirect was listed among the problems: ' . json_encode($job['issues']));
        sb_assert(3 === (int) $job['discovered'] && 2 === $queue->count_pending($job_id), 'The redirect destination was not queued.');
        sb_assert(false !== strpos(sb_method_body(file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php'), 'publish_release'), "'redirects_followed'"), 'The manifest does not record the redirects followed.');
    } finally {
        $queue->delete_job($job_id);
        @rmdir($stage);
        if (!$root_existed) {
            @rmdir($static_root . '/releases');
            @rmdir($static_root);
        }
        if (null === $previous_job) {
            delete_option(Static_Bridge_Plugin::JOB_OPTION);
        } else {
            update_option(Static_Bridge_Plugin::JOB_OPTION, $previous_job, false);
        }
        $GLOBALS['sb_test_http_responses'] = array();
        unset($GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size']);
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
    }
});

sb_test('Deploy scripts and the Genera button ask for regenerated pages; dynamic pages, other page caches and SEO URLs are explained', function () use ($plugin, $source) {
    if (!class_exists('WP_REST_Response')) {
        eval('class WP_REST_Response { public $data; public $status; public function __construct($data = null, $status = 200) { $this->data = $data; $this->status = $status; } }');
    }
    $request = function (array $params) {
        return new class($params) {
            private $params;
            public function __construct($params) { $this->params = $params; }
            public function get_param($name) { return $this->params[$name] ?? null; }
        };
    };
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $release = $static_root . '/releases/refresh-request';
    $current = $static_root . '/current';
    $previous_target = is_link($current) ? readlink($current) : false;
    $previous_settings = get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array());
    $previous_can = $GLOBALS['sb_test_can_manage'] ?? null;
    try {
        // The REST route exists only for administrators.
        $GLOBALS['sb_test_rest_routes'] = array();
        sb_assert(false !== strpos($source, "register_rest_route('static-bridge/v1', '/refresh'") && false !== strpos(sb_method_body($source, 'register_rest_routes'), "current_user_can('manage_options')"),
            'The refresh REST route is not limited to administrators.');
        $GLOBALS['sb_test_can_manage'] = false;
        $denied = $plugin->rest_refresh($request(array('scope' => 'all')));
        sb_assert(is_wp_error($denied) && 403 === $denied->get_error_data()['status'], 'The refresh REST callback ran without the capability.');
        $GLOBALS['sb_test_can_manage'] = true;

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge((array) $previous_settings, array('incremental_enabled' => 1, 'excluded_paths' => array()));
        if (is_link($current)) {
            unlink($current);
        }
        $no_release = $plugin->rest_refresh($request(array('scope' => 'all')));
        sb_assert($no_release instanceof WP_REST_Response && 409 === $no_release->status && 'no_release' === $no_release->data['status'], 'A refresh without a static release was not refused.');

        sb_assert(wp_mkdir_p($release . '/chi-siamo') && false !== file_put_contents($release . '/index.html', '<html></html>')
            && false !== file_put_contents($release . '/chi-siamo/index.html', '<html></html>')
            && false !== file_put_contents($release . '/manifest.json', '{}') && false !== file_put_contents($release . '/.ready', '')
            && symlink('releases/refresh-request', $current), 'The refresh fixture could not be prepared.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $bad = $plugin->rest_refresh($request(array('scope' => 'paths', 'paths' => array())));
        sb_assert(is_wp_error($bad) && 400 === $bad->get_error_data()['status'], 'An empty path list was accepted.');
        $paths = $plugin->rest_refresh($request(array('scope' => 'paths', 'paths' => array('/chi-siamo/', '/wp-admin/', 'https://elsewhere.invalid/x/'), 'reason' => 'deploy')));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert($paths instanceof WP_REST_Response && 202 === $paths->status && 1 === $paths->data['queued'] && array(sha1('/chi-siamo/')) === array_keys($queue),
            'The REST refresh did not queue exactly the paths of this site that can be static.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $all = $plugin->rest_refresh($request(array('scope' => 'all')));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert(202 === $all->status && isset($queue[sha1('/')], $queue[sha1('/chi-siamo/')]) && !empty($queue[sha1('/')]['shared_content']),
            'The REST refresh of everything did not queue every static route.');
        sb_assert(false !== strpos((string) get_option(Static_Bridge_Plugin::SHARED_REFRESH_REASON_OPTION), 'REST'), 'The reason of a shared refresh was not kept for Attività.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 0;
        sb_assert('incremental_off' === sb_private($plugin, 'request_static_refresh', array('all'))['status'], 'A refresh with incremental updates off was queued.');
        sb_assert(false !== strpos(sb_method_body($source, 'handle_refresh_request'), "check_admin_referer('static_bridge_refresh')"), 'The Genera refresh button has no nonce.');

        // «Pagine dinamiche» says why each page is dynamic.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array('/iscriviti/');
        update_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION, array('release' => 'r', 'urls' => array(home_url('/storia/')), 'at' => time()), false);
        $dynamic = sb_private($plugin, 'dynamic_pages_with_reasons');
        sb_assert(isset($dynamic['/iscriviti/'], $dynamic['/storia/'], $dynamic['/…?…']) && false !== strpos($dynamic['/storia/'], '429'),
            'An excluded, rate-limited or query-string page is missing from «Pagine dinamiche» or has no reason.');
        delete_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION);

        // Other page caches: explained in Diagnostica, and their copy of a regenerated page is dropped.
        $GLOBALS['sb_test_actions_fired'] = array();
        sb_private($plugin, 'purge_other_page_caches', array(home_url('/chi-siamo/')));
        sb_private($plugin, 'purge_other_page_caches', array('https://elsewhere.invalid/'));
        sb_assert(empty($GLOBALS['sb_test_actions_fired']), 'A cache purge ran without a cache plugin or for another site.');
        sb_private($plugin, 'complete_incremental_item', array(sha1('/chi-siamo/'), array('url' => home_url('/chi-siamo/'), 'token' => 't')));
        $last = get_option(Static_Bridge_Plugin::LAST_PAGE_UPDATE_OPTION, array());
        sb_assert('/chi-siamo/' === $last['path'] && abs(time() - $last['at']) < 5, 'The last page update was not recorded for Genera.');

        // The SEO URLs Diagnostica compares between the static copy and WordPress.
        $seo = sb_private($plugin, 'seo_absolute_urls', array('<link rel="canonical" href="https://a.example/x/"><link rel="alternate" hreflang="en" href="https://a.example/en/x/">'
            . '<meta property="og:image" content="/wp-content/uploads/a.jpg"><meta name="twitter:image" content="https://a.example/t.jpg">'
            . '<script type="application/ld+json">{"@graph":[{"@id":"https:\/\/a.example\/#org"}]}</script>'));
        sb_assert(array('canonical' => 'https://a.example/x/', 'hreflang en' => 'https://a.example/en/x/', 'og:image' => '/wp-content/uploads/a.jpg',
            'twitter:image' => 'https://a.example/t.jpg', 'JSON-LD @id' => 'https://a.example/#org') === $seo, 'The SEO URLs of a page were not read: ' . json_encode($seo));
    } finally {
        $GLOBALS['sb_test_can_manage'] = $previous_can;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = $previous_settings;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        delete_option(Static_Bridge_Plugin::LAST_PAGE_UPDATE_OPTION);
        delete_option(Static_Bridge_Plugin::SHARED_REFRESH_REASON_OPTION);
        wp_clear_scheduled_hook('static_bridge_process_incremental_queue');
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $previous_target) {
            symlink($previous_target, $current);
        }
        foreach (array('/chi-siamo/index.html', '/index.html', '/manifest.json', '/.ready') as $file) {
            @unlink($release . $file);
        }
        @rmdir($release . '/chi-siamo');
        @rmdir($release);
        if (!$root_existed) {
            @rmdir($static_root . '/releases');
            @rmdir($static_root);
        }
    }
});

sb_test('Cloudflare /cdn-cgi/ links (email protection) are never crawled', function () use ($plugin) {
    foreach (array('/cdn-cgi/l/email-protection', '/cdn-cgi/l/email-protection/', '/CDN-CGI/challenge-platform/h/b/') as $path) {
        sb_assert('' === sb_private($plugin, 'normalize_public_url', array(home_url($path))), $path . ' entered the crawl.');
    }
    sb_assert('' !== sb_private($plugin, 'normalize_public_url', array(home_url('/cdn-cgi-guida/'))), 'A page whose slug starts with cdn-cgi was excluded.');
    $links = sb_private($plugin, 'extract_internal_links', array('<a href="/cdn-cgi/l/email-protection#a1b2c3">mail</a><a href="/chi-siamo/">chi siamo</a>', home_url('/')));
    sb_assert(array(home_url('/chi-siamo/')) === array_values($links), 'The email-protection link was queued: ' . implode(', ', $links));
});

sb_test('A full export goes on in background requests with a per-export token when the wp-admin tab is closed', function () use ($plugin) {
    $job_id = '56789012-3456-4456-8456-3456789abcde';
    $release_id = 'queue-background';
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $stage = $static_root . '/releases/' . $release_id;
    $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $previous_can = $GLOBALS['sb_test_can_manage'] ?? null;
    $continuations = function () {
        return array_values(array_filter($GLOBALS['sb_test_http_calls'], function ($call) {
            return 'wp_safe_remote_post' === $call['api'] && Static_Bridge_Plugin::EXPORT_CONTINUE_ACTION === ($call['args']['body']['action'] ?? '');
        }));
    };
    $call = function ($token) use ($plugin) {
        $_POST['token'] = $token;
        try {
            $plugin->ajax_export_continue();
        } catch (SB_Test_Response $response) {
            return $response;
        } finally {
            unset($_POST['token']);
        }
        return null;
    };
    try {
        sb_assert(wp_mkdir_p($stage), 'The background fixture could not be prepared.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
            'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => $release_id, 'stage' => $stage,
            'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 0, 'discovery_complete' => true, 'discovered' => 0,
            'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0, 'issues' => array(),
            'current_url' => '', 'retry_not_before' => time() + 1,
        );
        sb_private($plugin, 'arm_export_continuation', array($job_id));
        $GLOBALS['sb_test_http_calls'] = array();
        sb_assert(true === sb_private($plugin, 'send_export_continuation', array(true)), 'The first background request was not sent.');
        $sent = $continuations();
        $token = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['hop'];
        sb_assert(1 === count($sent) && home_url('/wp-admin/admin-ajax.php') === $sent[0]['url'] && false === $sent[0]['args']['blocking']
            && $sent[0]['args']['timeout'] <= 1 && 0 === $sent[0]['args']['redirection'] && $token === $sent[0]['args']['body']['token']
            && 1 === preg_match('/\A[a-f0-9]{64}\z/', $token), 'The background request is not a non-blocking POST to this site with the code of the hop.');
        sb_assert(false === strpos(wp_json_encode(sb_private($plugin, 'job_response', array(get_option(Static_Bridge_Plugin::JOB_OPTION)))), $token), 'The token reached the progress response.');
        sb_assert(false === sb_private($plugin, 'send_export_continuation', array(false)) && 1 === count($continuations()), 'A second background chain started while one was alive.');

        foreach (array('', str_repeat('0', 64), substr($token, 0, 63), $token . '0', strtoupper($token)) as $bad) {
            $refused = $call($bad);
            sb_assert($refused instanceof SB_Test_Response && 403 === $refused->status, 'A background request without the export token was accepted.');
        }
        sb_assert(1 === count($continuations()), 'A refused request started another one.');

        // The server asked to wait: the request pauses (one second here), then hands over to the next one.
        $started = microtime(true);
        $accepted = $call($token);
        $next_hop = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['hop'];
        sb_assert($accepted instanceof SB_Test_Response && 200 === $accepted->status && microtime(true) - $started >= 0.9
            && 2 === count($continuations()) && $next_hop !== $token && $next_hop === $continuations()[1]['args']['body']['token'],
            'An accepted background request did not wait and start the next one with a new code.');
        sb_assert(403 === $call($token)->status && 2 === count($continuations()), 'The code of a hop already used was accepted again.');

        // A newer request retires the older one (a tick, the cron or a new export): its code no longer works, and a
        // request that was already running checks the same export_continuation_is_current() after its step and pause.
        $retired_hop = $next_hop;
        sb_private($plugin, 'send_export_continuation', array(true));
        sb_assert(false === sb_private($plugin, 'export_continuation_is_current', array($retired_hop))
            && 403 === $call($retired_hop)->status && 3 === count($continuations()), 'A retired background request started another one: two chains.');
        $token = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['hop'];

        // The cron worker and the wp-admin tab also keep a chain alive once the lease has expired.
        $continue = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION);
        $continue['lease_until'] = time() - 1;
        update_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION, $continue, false);
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $job['retry_not_before'] = time() + 30;
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
        $plugin->process_export_queue_cron();
        sb_assert(4 === count($continuations()), 'The cron worker did not restart the background requests.');

        $GLOBALS['sb_test_filter_values']['static_bridge_export_background_requests'] = false;
        sb_assert(false === sb_private($plugin, 'send_export_continuation', array(true)), 'The filter did not turn the background requests off.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_export_background_requests']);

        // A stalled export is reported on every wp-admin page.
        $GLOBALS['sb_test_can_manage'] = true;
        ob_start();
        $plugin->render_stalled_export_notice();
        sb_assert('' === ob_get_clean(), 'A running export with recent progress was reported as stalled.');
        $job['updated_at'] = time() - 600;
        $job['retry_not_before'] = 0;
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
        $continue = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION);
        $continue['lease_until'] = time() - 1;
        update_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION, $continue, false);
        ob_start();
        $plugin->render_stalled_export_notice();
        $notice = ob_get_clean();
        // The page view answers first: the request leaves at the end of it (shutdown), not while the page renders.
        $deferred = array_filter($GLOBALS['sb_test_hooks'], static fn($hook) => 'shutdown' === $hook[0] && array($plugin, 'send_deferred_export_continuation') === $hook[1] && PHP_INT_MAX === $hook[2]);
        sb_assert(4 === count($continuations()) && 1 === count($deferred), 'The wp-admin page waited for the background request instead of sending it at the end of the request.');
        $plugin->send_deferred_export_continuation();
        sb_assert(false !== strpos($notice, 'notice-warning') && false !== strpos($notice, '10') && 5 === count($continuations()), 'A stalled export was not reported or restarted.');
        $plugin->send_deferred_export_continuation();
        ob_start();
        $plugin->render_stalled_export_notice();
        ob_end_clean();
        $plugin->send_deferred_export_continuation();
        sb_assert(5 === count($continuations()), 'Each wp-admin page view started another background chain.');
        $token = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['hop'];

        // Once the export is over the token is dropped and nothing is started.
        $job['status'] = 'complete';
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
        $done = $call($token);
        sb_assert($done instanceof SB_Test_Response && 403 === $done->status && 5 === count($continuations()), 'A request for a finished export was accepted.');
        sb_private($plugin, 'fail_export_queue_job', array(get_option(Static_Bridge_Plugin::JOB_OPTION), '', 'test'));
        sb_assert(false === get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION, false), 'The code of a failed export was kept.');
        sb_assert(403 === $call($token)->status, 'The token of a finished export still worked.');
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_export_background_requests']);
        $GLOBALS['sb_test_can_manage'] = $previous_can;
        delete_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION);
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        null === $previous_job ? delete_option(Static_Bridge_Plugin::JOB_OPTION) : update_option(Static_Bridge_Plugin::JOB_OPTION, $previous_job, false);
        @rmdir($stage);
        if (!$root_existed) {
            @rmdir($static_root . '/releases');
            @rmdir($static_root);
        }
    }
});

sb_test('An export step that finds the render lock held skips no page and uses no attempt (2.3.0)', function () use ($plugin) {
    sb_assert(sb_private($plugin, 'is_render_machinery_error', array(new WP_Error('static_bridge_render_recovery', 'x')))
        && !sb_private($plugin, 'is_render_machinery_error', array(new WP_Error('static_bridge_render_unverified', 'x')))
        && !sb_private($plugin, 'is_render_machinery_error', array(new WP_Error('static_bridge_render_route', 'x'))), 'Render machinery errors are not told from page errors.');
    $job_id = '56789012-3456-4456-8456-3456789abcde';
    $release_id = 'queue-render-busy';
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $stage = $static_root . '/releases/' . $release_id;
    $current_link = $static_root . '/current';
    $previous_target = is_link($current_link) ? readlink($current_link) : false;
    $previous_last_release = get_option('static_bridge_last_release', null);
    $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $previous_callback = $GLOBALS['sb_test_http_callback'];
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    $first_url = home_url('/prima/');
    $second_url = home_url('/seconda/');
    $fetched = array();
    $GLOBALS['sb_test_http_callback'] = function ($url) use (&$fetched) {
        $path = (string) wp_parse_url($url, PHP_URL_PATH);
        $fetched[] = $path;
        parse_str((string) wp_parse_url($url, PHP_URL_QUERY), $query);
        return array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html', 'X-Static-Bridge-Render' => (string) ($query['static_bridge_render'] ?? '')), 'body' => '<html><body>' . $path . '</body></html>');
    };
    $GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size'] = 2;
    // Another render holds the lock: the same file the plugin locks (acquire_render_bypass_lock()).
    $lock_path = trailingslashit(realpath(sys_get_temp_dir())) . 'static-bridge-render-' . substr(hash('sha256', trailingslashit(realpath(WP_CONTENT_DIR)) . 'static-bridge'), 0, 24) . '.lock';
    $holder = null;
    try {
        sb_assert($queue->install() && wp_mkdir_p($stage) && 2 === $queue->enqueue_batch($job_id, array($first_url, $second_url)), 'The render-busy fixture could not be prepared.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
            'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => $release_id, 'stage' => $stage,
            'portable_internal_urls' => 1, 'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 1, 'discovery_complete' => true,
            'discovered' => 2, 'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0,
            'issues' => array(), 'current_url' => '',
        );
        $holder = fopen($lock_path, 'c');
        sb_assert(is_resource($holder) && flock($holder, LOCK_EX | LOCK_NB), 'The test could not hold the render lock.');
        $started = microtime(true);
        $busy = sb_private($plugin, 'run_export_queue_step');
        $waited = microtime(true) - $started;
        sb_assert(array() === $fetched && 0 === (int) $busy['skipped'] && 0 === (int) $busy['processed'] && 1 === (int) $busy['render_waits']
            && !isset($busy['retry_attempts']) && 2 === $queue->count_pending($job_id) && 'running' === $busy['status'],
            'A held render lock skipped pages or used an attempt: ' . json_encode($busy));
        sb_assert($waited >= Static_Bridge_Plugin::EXPORT_RENDER_LOCK_WAIT - 0.2, 'The export step did not wait for the render lock before giving up.');
        // Past the limit the error follows the usual path: a retryable error, one attempt, still nothing skipped.
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
        $job['render_waits'] = Static_Bridge_Plugin::MAX_EXPORT_RENDER_WAITS;
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
        $limit = sb_private($plugin, 'run_export_queue_step');
        sb_assert(1 === (int) $limit['retry_attempts'] && 0 === (int) $limit['skipped'] && 2 === $queue->count_pending($job_id), 'Past the limit a held lock did not count one retryable attempt: ' . json_encode($limit));
        flock($holder, LOCK_UN);
        fclose($holder);
        $holder = null;
        $free = sb_private($plugin, 'run_export_queue_step');
        sb_assert(2 === (int) $free['saved'] && 0 === (int) $free['skipped'] && !isset($free['render_waits']) && is_file($stage . '/prima/index.html') && is_file($stage . '/seconda/index.html'),
            'With the lock free the pages were not saved: ' . json_encode($free));
    } finally {
        if (is_resource($holder)) {
            flock($holder, LOCK_UN);
            fclose($holder);
        }
        $GLOBALS['sb_test_http_callback'] = $previous_callback;
        unset($GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size']);
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        $queue->delete_job($job_id);
        if (is_link($current_link)) {
            unlink($current_link);
        }
        if (false !== $previous_target) {
            symlink($previous_target, $current_link);
        }
        null === $previous_last_release ? delete_option('static_bridge_last_release') : update_option('static_bridge_last_release', $previous_last_release, false);
        null === $previous_job ? delete_option(Static_Bridge_Plugin::JOB_OPTION) : update_option(Static_Bridge_Plugin::JOB_OPTION, $previous_job, false);
        foreach (array('/prima/index.html', '/seconda/index.html', '/manifest.json', '/.ready') as $file) {
            @unlink($stage . $file);
        }
        foreach (array('/prima', '/seconda', '') as $directory) {
            @rmdir($stage . $directory);
        }
        if (!$root_existed) {
            @rmdir($static_root . '/releases');
            @rmdir($static_root);
        }
    }
});

sb_test('An export rate limited by the server (HTTP 429) waits, defers the page, retries it slowly at the end and lists it for «Riprova queste»', function () use ($plugin) {
    sb_assert(7 === sb_private($plugin, 'retry_after_seconds', array('7')) && 0 === sb_private($plugin, 'retry_after_seconds', array(''))
        && 0 === sb_private($plugin, 'retry_after_seconds', array('soon')) && Static_Bridge_Plugin::MAX_RATE_LIMIT_WAIT === sb_private($plugin, 'retry_after_seconds', array('86400'))
        && 0 === sb_private($plugin, 'retry_after_seconds', array('-5')) && 9 === sb_private($plugin, 'retry_after_seconds', array(array('9'))), 'Retry-After in seconds was not read or clamped.');
    $date_wait = sb_private($plugin, 'retry_after_seconds', array(gmdate('D, d M Y H:i:s', time() + 40) . ' GMT'));
    sb_assert($date_wait >= 38 && $date_wait <= 40, 'Retry-After as an HTTP date was not read.');
    sb_assert(10 === sb_private($plugin, 'rate_limit_wait', array(1, 0)) && 20 === sb_private($plugin, 'rate_limit_wait', array(2, 7))
        && 45 === sb_private($plugin, 'rate_limit_wait', array(1, 45)), 'The wait is not the longest of Retry-After and the doubling pause.');

    $job_id = '45678901-2345-4345-8345-23456789abcd';
    $release_id = 'queue-rate-limited';
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $stage = $static_root . '/releases/' . $release_id;
    $current_link = $static_root . '/current';
    $previous_target = is_link($current_link) ? readlink($current_link) : false;
    $previous_last_release = get_option('static_bridge_last_release', null);
    $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $previous_callback = $GLOBALS['sb_test_http_callback'];
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    $home = home_url('/');
    $limited = home_url('/categoria-prodotto/storia/');
    $other = home_url('/altra/');
    $fetched = array();
    $limited_status = 429;
    $GLOBALS['sb_test_http_callback'] = function ($url) use (&$fetched, &$limited_status, $home, $limited, $other) {
        $path = (string) wp_parse_url($url, PHP_URL_PATH);
        $fetched[] = $path;
        parse_str((string) wp_parse_url($url, PHP_URL_QUERY), $query);
        $proof = array('X-Static-Bridge-Render' => (string) ($query['static_bridge_render'] ?? ''));
        if ((string) wp_parse_url($limited, PHP_URL_PATH) === $path) {
            return 429 === $limited_status
                ? array('response' => array('code' => 429), 'headers' => array('Retry-After' => '7'), 'body' => 'Too Many Requests')
                : array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html') + $proof, 'body' => '<html><body>Storia</body></html>');
        }
        return array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html') + $proof, 'body' => '<html><body>' . $path . '</body></html>');
    };
    $GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size'] = 1;
    $time_passes = function () {
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
        $job['retry_not_before'] = time() - 1;
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
    };
    try {
        sb_assert($queue->install() && wp_mkdir_p($stage) && 3 === $queue->enqueue_batch($job_id, array($home, $limited, $other)), 'The rate-limit fixture could not be prepared.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
            'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => $release_id, 'stage' => $stage,
            'portable_internal_urls' => 1, 'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 1, 'discovery_complete' => true,
            'discovered' => 3, 'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0,
            'issues' => array(), 'current_url' => '',
        );
        $first = sb_private($plugin, 'run_export_queue_step');
        sb_assert(1 === (int) $first['saved'] && empty($first['rate_limited']), 'The home page was not saved before the rate-limited page: ' . json_encode(array($first, $fetched)));

        $limited_once = sb_private($plugin, 'run_export_queue_step');
        $wait = (int) $limited_once['retry_not_before'] - time();
        sb_assert(1 === (int) $limited_once['retry_attempts'] && 1 === (int) $limited_once['rate_limited'] && $wait >= 9 && $wait <= 10,
            'A 429 with Retry-After: 7 did not wait the 10 s minimum before the retry.');
        $fetches = count($fetched);
        $waiting = sb_private($plugin, 'run_export_queue_step');
        sb_assert($fetches === count($fetched) && (int) $waiting['_waiting'] >= 9, 'A worker fetched while the server asked to wait.');
        $response = sb_private($plugin, 'job_response', array($waiting));
        sb_assert($response['waiting'] >= 9 && 'running' === $response['status'], 'The wait was not reported to the progress panel.');
        $plugin->process_export_queue_cron();
        $next = wp_next_scheduled('static_bridge_process_export_queue');
        sb_assert(is_int($next) && $next - time() >= 8 && $next - time() <= 10, 'The cron worker was not rescheduled for the end of the wait.');

        $time_passes();
        $limited_twice = sb_private($plugin, 'run_export_queue_step');
        $wait = (int) $limited_twice['retry_not_before'] - time();
        sb_assert(2 === (int) $limited_twice['retry_attempts'] && $wait >= 19 && $wait <= 20, 'The second 429 did not double the wait.');

        $time_passes();
        $deferred = sb_private($plugin, 'run_export_queue_step');
        sb_assert(1 === $queue->count_deferred($job_id) && 0 === (int) $deferred['route_errors'] && !isset($deferred['retry_attempts'])
            && 'running' === $deferred['status'], 'A page still rate limited after the retries was left out instead of deferred.');
        sb_assert(!file_exists($stage . '/categoria-prodotto/storia/index.html'), 'A deferred page was written.');

        $time_passes();
        $other_saved = sb_private($plugin, 'run_export_queue_step');
        sb_assert(2 === (int) $other_saved['saved'] && is_file($stage . '/altra/index.html'), 'The export did not go on with the other pages after deferring one.');
        sb_assert(1 === (int) $other_saved['rate_limit_calm'] && $other_saved['last_fetch_at'] > 0, 'A page answered without a rate limit did not count toward the slower pace ending.');

        $recovery = sb_private($plugin, 'run_export_queue_step');
        $wait = (int) $recovery['retry_not_before'] - time();
        sb_assert('running' === $recovery['status'] && 1 === (int) $recovery['recovery_round'] && 1 === $queue->count_pending($job_id)
            && 0 === $queue->count_deferred($job_id) && $wait >= Static_Bridge_Plugin::RATE_LIMIT_RECOVERY_DELAY - 1,
            'The export was published without the slow recovery round of the rate-limited page.');
        sb_assert(!file_exists($stage . '/.ready'), 'The release was marked ready before the recovery round.');

        // Still rate limited in the recovery round: the page is left out, the release is published, the page is listed.
        for ($attempt = 0; $attempt < 3; $attempt++) {
            $time_passes();
            $round = sb_private($plugin, 'run_export_queue_step');
        }
        sb_assert(1 === (int) $round['route_errors'] && array($limited) === $round['rate_limited_urls'] && 0 === $queue->count_pending($job_id),
            'A page still rate limited in the recovery round was not recorded once.');
        $time_passes();
        $published = sb_private($plugin, 'run_export_queue_step');
        sb_assert('complete' === $published['status'], 'The release was not published after the recovery round.');
        $listed = get_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION, array());
        sb_assert(array($limited) === $listed['urls'] && $release_id === $listed['release'], 'The page left out for 429 was not listed for «Riprova queste».');

        // «Riprova queste»: the listed route goes to the incremental queue, the list is cleared.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge((array) get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array()), array('incremental_enabled' => 1));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $retry = sb_private($plugin, 'request_static_refresh', array('rate_limited', array(), 'test'));
        $incremental = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert('queued' === $retry['status'] && 1 === $retry['queued'] && isset($incremental[sha1('/categoria-prodotto/storia/')])
            && false === get_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION, false), '«Riprova queste» did not queue the listed page and clear the list.');
        sb_assert('nothing' === sb_private($plugin, 'request_static_refresh', array('rate_limited', array(), 'test'))['status'], 'An empty list queued something.');

        // A clean export clears the list.
        sb_private($plugin, 'remember_rate_limited_routes', array(array('release_id' => 'x', 'rate_limited_urls' => array('https://elsewhere.invalid/x/'))));
        sb_assert(false === get_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION, false), 'A URL of another site was listed.');
    } finally {
        $GLOBALS['sb_test_http_callback'] = $previous_callback;
        unset($GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size']);
        delete_option(Static_Bridge_Plugin::RATE_LIMITED_ROUTES_OPTION);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        $queue->delete_job($job_id);
        if (is_link($current_link)) {
            unlink($current_link);
        }
        if (false !== $previous_target) {
            symlink($previous_target, $current_link);
        }
        null === $previous_last_release ? delete_option('static_bridge_last_release') : update_option('static_bridge_last_release', $previous_last_release, false);
        null === $previous_job ? delete_option(Static_Bridge_Plugin::JOB_OPTION) : update_option(Static_Bridge_Plugin::JOB_OPTION, $previous_job, false);
        foreach (array('/categoria-prodotto/storia/index.html', '/altra/index.html', '/index.html', '/manifest.json', '/.ready') as $file) {
            @unlink($stage . $file);
        }
        foreach (array('/categoria-prodotto/storia', '/categoria-prodotto', '/altra', '') as $directory) {
            @rmdir($stage . $directory);
        }
        if (!$root_existed) {
            @rmdir($static_root . '/releases');
            @rmdir($static_root);
        }
    }
});

sb_test('Export HTTP policy skips non-public responses but fails closed on server errors', function () use ($plugin, $source) {
    foreach (array(401, 403, 404, 410) as $status) {
        $error = new WP_Error('static_bridge_http', 'Risposta HTTP ' . $status . '.', $status);
        sb_assert(sb_private($plugin, 'is_skippable_export_http_error', array($error)), 'HTTP ' . $status . ' was not classified as a per-URL skip.');
    }
    $legacy_404 = new WP_Error('static_bridge_http', 'Risposta HTTP 404.');
    sb_assert(sb_private($plugin, 'is_skippable_export_http_error', array($legacy_404)), 'Legacy HTTP 404 errors without status data stopped being recoverable.');
    $server_error = new WP_Error('static_bridge_http', 'Risposta HTTP 500.', 500);
    sb_assert(!sb_private($plugin, 'is_skippable_export_http_error', array($server_error)), 'An HTTP 500 was treated as a safe per-page skip.');
    $transport_error = new WP_Error('http_request_failed', 'Connection timed out.');
    sb_assert(!sb_private($plugin, 'is_skippable_export_http_error', array($transport_error)), 'A transport failure was treated as a safe per-page skip.');
    sb_assert(sb_private($plugin, 'is_retryable_export_error', array($transport_error)), 'A transport timeout was not classified as retryable.');
    sb_assert(sb_private($plugin, 'is_retryable_export_error', array($server_error)), 'A transient HTTP 500 was not classified as retryable.');
    sb_assert(sb_private($plugin, 'is_retryable_export_error', array(new WP_Error('static_bridge_render_unverified', 'Rendering WordPress non verificato.'))), 'A missing fresh-render proof was not classified as retryable.');
    sb_assert(sb_private($plugin, 'is_retryable_export_error', array(new WP_Error('static_bridge_render_busy', 'Another route is being rendered.'))), 'A temporary render lock was not classified as retryable.');
    sb_assert(!sb_private($plugin, 'is_retryable_export_error', array(new WP_Error('static_bridge_http', 'Risposta HTTP 403.', 403))), 'A permanent HTTP 403 was treated as retryable.');
    $not_found = new WP_Error('static_bridge_http', 'Risposta HTTP 404.', 404);
    sb_assert(sb_private($plugin, 'is_skippable_export_http_error', array($not_found)) && !sb_private($plugin, 'is_retryable_export_error', array($not_found)), 'A normal HTTP 404 was not kept separate from transient render failures.');

    $queue_worker = sb_method_body($source, 'run_export_queue_step');
    sb_assert(false !== strpos($queue_worker, 'is_skippable_export_http_error'), 'The indexed queue worker does not use the explicit HTTP response policy.');
});

sb_test('Queue cancellation serializes against a running worker and preserves only the exact partial stage', function () use ($plugin) {
    $job_id = '45678901-1234-4234-8234-123456789abc';
    $release_id = 'queue-cancel-smoke';
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $root_existed = is_dir($static_root);
    $stage = $static_root . '/releases/' . $release_id;
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    sb_assert($queue->install() && wp_mkdir_p($stage) && 1 === $queue->enqueue_batch($job_id, array(home_url('/'))), 'The isolated cancellable job could not be prepared.');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'queue_version' => 1,
        'job_id' => $job_id,
        'status' => 'running',
        'release_id' => $release_id,
        'stage' => $stage,
        'discovery_cursor' => 0,
        'discovery_complete' => false,
        'discovered' => 1,
        'started_at' => time(),
        'updated_at' => time(),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
    );
    wp_schedule_single_event(time() + 5, 'static_bridge_process_export_queue');
    $GLOBALS['sb_test_nonce_valid'] = true;
    $response = null;
    try {
        $plugin->ajax_cancel();
    } catch (SB_Test_Response $caught) {
        $response = $caught;
    }
    $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    sb_assert($response instanceof SB_Test_Response && 200 === $response->status && 'cancelled' === $job['status'], 'The queued export was not cancelled under the worker lock.');
    sb_assert(is_dir($stage) && 0 === $queue->count_total($job_id), 'Cancellation deleted the stage or left this job’s queue rows behind.');
    sb_assert(false === wp_next_scheduled('static_bridge_process_export_queue') && false === get_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION, false), 'Cancellation left a worker event or lock active.');
    rmdir($stage);
    if (!$root_existed) {
        @rmdir($static_root . '/releases');
        @rmdir($static_root);
    }
});

