sb_test('Plugin metadata declares the PHP 8.4 and WordPress 6.9 floors enforced by activation preflight', function () use ($pluginFile) {
    $source = file_get_contents($pluginFile);
    sb_assert(is_string($source), 'The plugin header could not be read.');
    sb_assert(1 === preg_match('/^\s*\*\s+Version:\s*([^\s]+)\s*$/m', $source, $version_match), 'The plugin header version is missing.');
    sb_assert(Static_Bridge_Plugin::VERSION === $version_match[1], 'The plugin header and runtime version constant do not match.');
    sb_assert(1 === preg_match('/^\s*\*\s+Requires PHP:\s*8\.4\s*$/m', $source), 'The plugin header does not declare PHP 8.4.');
    sb_assert(1 === preg_match('/^\s*\*\s+Requires at least:\s*6\.9\s*$/m', $source), 'The plugin header does not declare WordPress 6.9.');
});

