sb_test('Activation preflight refuses a symlinked static root without touching its target', function () use ($fixtureRoot) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $outside = $fixtureRoot . '/outside-static-root';
    if (!@mkdir($outside, 0775, true) && !is_dir($outside)) {
        throw new RuntimeException('Could not create the isolated outside-directory fixture.');
    }
    if (!symlink($outside, $root)) {
        throw new RuntimeException('Could not create the isolated root symlink fixture.');
    }
    $report = Static_Bridge_Plugin::activation_preflight(array(
        'php_version' => '8.2.29',
        'wp_version' => '7.1.2',
        'memory_limit' => '256M',
        'current_memory' => 96 * 1048576,
        'peak_memory' => 112 * 1048576,
    ));
    sb_assert(empty($report['ok']), 'Activation accepted a symlinked Static Bridge root.');
    sb_assert(is_dir($outside) && 0 === count(array_diff(scandir($outside), array('.', '..'))), 'The preflight modified data outside wp-content.');
    unlink($root);
});

sb_test('Activation preflight fails closed before activation side effects when requirements or memory are unsafe', function () use ($source) {
    $optionsBefore = $GLOBALS['sb_test_options'];
    $report = Static_Bridge_Plugin::activation_preflight(array(
        'php_version' => '7.3.0',
        'wp_version' => '6.1.9',
        'memory_limit' => '256M',
        'current_memory' => 230 * 1048576,
        'peak_memory' => 231 * 1048576,
        'required_functions' => array('missing_wordpress_function'),
    ));
    sb_assert(empty($report['ok']) && count($report['errors']) >= 4, 'Unsupported versions, missing API, or insufficient memory were not blocked.');
    try {
        Static_Bridge_Plugin::halt_activation($report);
        throw new RuntimeException('The activation stop did not terminate the request.');
    } catch (SB_Test_WP_Die $blocked) {
        sb_assert(false !== strpos($blocked->getMessage(), 'non è stato attivato'), 'The block page did not explain the safe cancellation.');
        sb_assert(503 === $blocked->details['args']['response'], 'The activation stop did not return an explicit service-unavailable response.');
    }
    sb_assert($optionsBefore === $GLOBALS['sb_test_options'], 'The failed preflight changed WordPress options.');
    $activateBody = sb_method_body($source, 'activate');
    sb_assert(strpos($activateBody, 'activation_preflight') < strpos($activateBody, '$plugin = new self();'), 'Activation side effects begin before the preflight.');
});

