sb_test('Same-origin validation rejects host, scheme, port, credentials and non-HTTP protocols', function () use ($plugin) {
    $sameSite = function ($url) use ($plugin) { return sb_private($plugin, 'same_site_url', array($url)); };
    sb_assert($sameSite(home_url('/articoli/')), 'The configured origin should be accepted.');
    sb_assert(!$sameSite('https://news.example.test.attacker.invalid:8443/'), 'A hostile suffix host was accepted.');
    sb_assert(!$sameSite('http://news.example.test:8443/'), 'A scheme change was accepted.');
    sb_assert(!$sameSite('https://news.example.test:9443/'), 'A port change was accepted.');
    sb_assert(!$sameSite('https://user@news.example.test:8443/'), 'URL credentials were accepted.');
    sb_assert(!$sameSite('ftp://news.example.test:8443/'), 'A non-HTTP protocol was accepted.');
});

sb_test('Outbound HTTP uses safe API, disables redirects and bounds response size', function () use ($plugin) {
    $GLOBALS['sb_test_http_calls'] = array();
    $response = sb_private($plugin, 'remote_get', array(home_url('/robots.txt'), 7, 4096));
    sb_assert(!is_wp_error($response), 'A same-origin request should be allowed.');
    sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'Expected exactly one HTTP call.');
    $call = $GLOBALS['sb_test_http_calls'][0];
    sb_assert('wp_safe_remote_get' === $call['api'], 'Unsafe wp_remote_get() was used.');
    sb_assert(0 === $call['args']['redirection'], 'HTTP redirects must remain disabled.');
    sb_assert(4096 === $call['args']['limit_response_size'], 'The response size limit was not applied.');
    sb_assert('no-cache, no-store, max-age=0' === $call['args']['headers']['Cache-Control']
        && 'no-cache' === $call['args']['headers']['Pragma'], 'Internal HTML fetches must request a fresh response rather than reuse a cached page.');

    $callsBefore = count($GLOBALS['sb_test_http_calls']);
    $blocked = sb_private($plugin, 'remote_get', array('http://127.0.0.1:8080/latest/meta-data/', 7));
    sb_assert(is_wp_error($blocked), 'An off-origin metadata URL was not rejected.');
    sb_assert($callsBefore === count($GLOBALS['sb_test_http_calls']), 'A blocked URL still reached the HTTP API.');
});

sb_test('Fresh render requests add only a route-bound, non-authenticating cache-bypass cookie', function () use ($plugin) {
    $option = Static_Bridge_Plugin::RENDER_BYPASS_OPTION;
    $had_option = array_key_exists($option, $GLOBALS['sb_test_options']);
    $previous = $had_option ? $GLOBALS['sb_test_options'][$option] : null;
    $token = str_repeat('a', 48);
    $path = '/cache-bypass-probe/';
    $GLOBALS['sb_test_options'][$option] = array('token' => $token, 'routes' => array($path));

    try {
        $GLOBALS['sb_test_http_calls'] = array();
        sb_private($plugin, 'remote_get', array(home_url($path) . '?static_bridge_bypass=1&static_bridge_render=' . $token, 7, 4096));
        $headers = $GLOBALS['sb_test_http_calls'][0]['args']['headers'];
        sb_assert(isset($headers['Cookie']) && 'wordpress_logged_in_static_bridge_bypass=' . $token === $headers['Cookie'], 'A verified internal render did not signal WordPress-aware caches to bypass the static route.');
        sb_assert(isset($headers['X-Static-Bridge-Render-Bypass']) && $token === $headers['X-Static-Bridge-Render-Bypass'], 'The internal render marker header was not sent.');

        $GLOBALS['sb_test_http_calls'] = array();
        sb_private($plugin, 'remote_get', array(home_url('/other-route/') . '?static_bridge_bypass=1&static_bridge_render=' . $token, 7, 4096));
        $other_headers = $GLOBALS['sb_test_http_calls'][0]['args']['headers'];
        sb_assert(!isset($other_headers['Cookie']) && !isset($other_headers['X-Static-Bridge-Render-Bypass']), 'A render token was allowed to bypass cache handling for a route outside its transaction.');

        $GLOBALS['sb_test_http_calls'] = array();
        sb_private($plugin, 'remote_get', array(home_url('/robots.txt'), 7, 4096));
        $ordinary_headers = $GLOBALS['sb_test_http_calls'][0]['args']['headers'];
        sb_assert(!isset($ordinary_headers['Cookie']) && !isset($ordinary_headers['X-Static-Bridge-Render-Bypass']), 'An ordinary public fetch received an internal cache-bypass marker.');
    } finally {
        if ($had_option) {
            $GLOBALS['sb_test_options'][$option] = $previous;
        } else {
            unset($GLOBALS['sb_test_options'][$option]);
        }
    }
});

sb_test('Parallel HTTP transport preserves TLS, proxy and WordPress cURL hooks', function () use ($pluginFile) {
    $source = file_get_contents($pluginFile);
    sb_assert(is_string($source), 'The Static Bridge source could not be read for transport regression checks.');
    $batch_method = sb_method_body($source, 'remote_get_batch');
    sb_assert(false !== strpos($batch_method, '$this->render_request_headers($url)'), 'The parallel transport does not use the same cache/router bypass headers as sequential requests.');
    foreach (array(
        "'curl.before_multi_add'",
        'CURLOPT_SSL_VERIFYHOST',
        'CURLOPT_SSL_VERIFYPEER',
        'CURLOPT_CAINFO',
        '$multi_proxy->curl_before_send($handle)',
        "'http_api_curl'",
        "'wordpress_http_curl_hook'",
    ) as $required_transport_guard) {
        sb_assert(false !== strpos($source, $required_transport_guard), 'The parallel transport is missing required TLS/proxy compatibility guard: ' . $required_transport_guard);
    }
});

sb_test('Full export defaults to one loopback request while retaining the opt-in parallel path', function () use ($plugin, $source) {
    $had_filter = array_key_exists('static_bridge_export_concurrency', $GLOBALS['sb_test_filter_values']);
    $previous_filter = $had_filter ? $GLOBALS['sb_test_filter_values']['static_bridge_export_concurrency'] : null;
    unset($GLOBALS['sb_test_filter_values']['static_bridge_export_concurrency']);
    try {
        $default = sb_private($plugin, 'export_fetch_info');
        sb_assert(1 === $default['concurrency'] && 'sequential' === $default['mode'], 'The default export still creates loopback concurrency on a shared PHP-FPM pool.');
        $method = sb_method_body($source, 'export_fetch_info');
        sb_assert(false !== strpos($method, "apply_filters('static_bridge_export_concurrency', 1)"), 'The safe single-request default is not explicit in the filter contract.');
        sb_assert(false !== strpos($method, "'mode' => 'parallel'"), 'The administrator opt-in parallel path was removed.');
    } finally {
        if ($had_filter) {
            $GLOBALS['sb_test_filter_values']['static_bridge_export_concurrency'] = $previous_filter;
        } else {
            unset($GLOBALS['sb_test_filter_values']['static_bridge_export_concurrency']);
        }
    }
});

sb_test('Parallel page fetching falls back to WordPress safe HTTP when the Requests multi transport is unavailable', function () use ($plugin) {
    $first = home_url('/parallel-one/?static_bridge_bypass=1');
    $second = home_url('/parallel-two/?static_bridge_bypass=1');
    $GLOBALS['sb_test_http_responses'] = array(
        $first => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>One</body></html>'),
        $second => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Two</body></html>'),
    );
    $GLOBALS['sb_test_http_calls'] = array();
    $results = sb_private($plugin, 'fetch_pages', array(array(home_url('/parallel-one/'), home_url('/parallel-two/'))));
    sb_assert(2 === count($results) && !is_wp_error($results[home_url('/parallel-one/')]) && !is_wp_error($results[home_url('/parallel-two/')]), 'The bounded sequential fallback did not return both rendered pages.');
    sb_assert(2 === count($GLOBALS['sb_test_http_calls']), 'The fallback did not fetch each queued page exactly once.');
    foreach ($GLOBALS['sb_test_http_calls'] as $call) {
        sb_assert('wp_safe_remote_get' === $call['api'], 'The fallback bypassed WordPress safe HTTP.');
        sb_assert(0 === $call['args']['redirection'] && 5242880 === $call['args']['limit_response_size'], 'The fallback lost redirect or response-size protections.');
        sb_assert(isset($call['args']['headers']['Cookie']) && false !== strpos($call['args']['headers']['Cookie'], 'wordpress_logged_in_static_bridge_bypass='), 'The sequential fallback did not signal the server/cache to render dynamically.');
        sb_assert(isset($call['args']['headers']['Cache-Control']) && 'no-cache, no-store, max-age=0' === $call['args']['headers']['Cache-Control'], 'The sequential fallback dropped no-cache request headers.');
    }
});

sb_test('Internal page rendering suspends stale static routes and refuses unverified cached HTML', function () use ($plugin) {
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $releases = $static_root . '/releases';
    if (is_link($static_root) || (!is_dir($releases) && !wp_mkdir_p($releases))) {
        throw new RuntimeException('Could not prepare the isolated render-bypass fixture.');
    }
    $current = $static_root . '/current';
    if (file_exists($current) && !is_link($current)) {
        throw new RuntimeException('The current release fixture is not a symlink and cannot be safely replaced.');
    }
    $old_current_target = is_link($current) ? readlink($current) : false;
    $release_id = 'render-bypass-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $releases . '/' . $release_id;
    $route = '/sb-render-probe-' . bin2hex(random_bytes(4)) . '/';
    $route_file = $release . '/' . trim($route, '/') . '/index.html';
    $enabled = $static_root . '/.enabled';
    $strict = $static_root . '/.strict';
    if (!wp_mkdir_p(dirname($route_file))) {
        throw new RuntimeException('Could not create the route fixture directory.');
    }
    $old_enabled = is_file($enabled) ? file_get_contents($enabled) : false;
    $old_strict = is_file($strict) ? file_get_contents($strict) : false;
    if (is_link($enabled) || is_link($strict)
        || false === file_put_contents($route_file, '<html>OLD_STATIC</html>')) {
        throw new RuntimeException('Could not seed the isolated render-bypass fixture.');
    }

    try {
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not activate the isolated render-bypass release.');
        file_put_contents($enabled, "enabled\n");
        file_put_contents($strict, '');

        $url = home_url($route);
        $suspension_log = array();
        $GLOBALS['sb_test_http_calls'] = array();
        // This server ignores the query/cookie guard and keeps serving the static file:
        // only the move-aside fallback can reach WordPress.
        $GLOBALS['sb_test_http_callback'] = function ($request_url) use ($route_file, $enabled, $strict, &$suspension_log) {
            $parts = wp_parse_url($request_url);
            $query = array();
            parse_str(isset($parts['query']) ? $parts['query'] : '', $query);
            $token = isset($query['static_bridge_render']) ? (string) $query['static_bridge_render'] : '';
            $suspended = !file_exists($route_file) && is_file($enabled) && !file_exists($strict);
            $suspension_log[] = $suspended ? 'suspended' : (is_file($route_file) && file_exists($strict) ? 'in-place' : 'partial');
            if ($suspended && preg_match('/^[a-f0-9]{48}$/', $token)) {
                return array(
                    'response' => array('code' => 200),
                    // Simulate an intermediary stripping custom headers while the
                    // unpredictable proof emitted by WordPress remains in the body.
                    'headers' => array('Content-Type' => 'text/html'),
                    'body' => '<html>WORDPRESS_CURRENT<input value="' . esc_attr(home_url('/')) . '?static_bridge_bypass=1&amp;static_bridge_render=' . $token . '"></html><!--static-bridge-render:' . $token . '-->',
                    '_sb_strip_render_header' => true,
                );
            }
            return array(
                'response' => array('code' => 200),
                'headers' => array('Content-Type' => 'text/html'),
                'body' => '<html>OLD_STATIC</html>',
            );
        };
        $fresh = sb_private($plugin, 'fetch_page', array($url, 10));
        sb_assert(!is_wp_error($fresh) && false !== strpos($fresh['body'], 'WORDPRESS_CURRENT'), 'The bypass did not retrieve the simulated fresh WordPress page.');
        sb_assert(array('in-place', 'suspended') === $suspension_log, 'The route was not first rendered in place and suspended only after the guarded request missed WordPress: ' . json_encode($suspension_log));
        $fresh_headers = isset($GLOBALS['sb_test_http_calls'][0]['args']['headers']) ? $GLOBALS['sb_test_http_calls'][0]['args']['headers'] : array();
        sb_assert(isset($fresh_headers['Cookie']) && false !== strpos($fresh_headers['Cookie'], 'wordpress_logged_in_static_bridge_bypass='), 'The fresh render fetch omitted the synthetic cache/router bypass cookie.');
        sb_assert(isset($fresh_headers['X-Static-Bridge-Render-Bypass']), 'The fresh render fetch omitted the diagnostic bypass header.');
        sb_assert(false === strpos($fresh['body'], 'static_bridge_render=') && false === strpos($fresh['body'], 'static_bridge_bypass=1') && false === strpos($fresh['body'], 'static-bridge-render:'), 'A one-time loopback token or body proof leaked into the saved HTML.');
        sb_assert(is_file($route_file) && '<html>OLD_STATIC</html>' === file_get_contents($route_file), 'The previous static route was not restored after a successful fetch.');
        sb_assert("enabled\n" === file_get_contents($enabled) && '' === file_get_contents($strict), 'The original routing markers were not restored after the fetch.');

        $GLOBALS['sb_test_http_callback'] = function () {
            return array(
                'response' => array('code' => 200),
                'headers' => array('Content-Type' => 'text/html'),
                'body' => '<html>OLD_STATIC_FROM_CACHE</html>',
            );
        };
        $stale = sb_private($plugin, 'fetch_page', array($url, 10));
        sb_assert(is_wp_error($stale) && 'static_bridge_render_unverified' === $stale->get_error_code(), 'Cached HTML without the WordPress render proof was accepted.');
        sb_assert(4 === count($GLOBALS['sb_test_http_calls']), 'An unverified render was not retried exactly once with the route suspended.');
        sb_assert(false !== strpos($stale->get_error_message(), 'HTTP 200') && false !== strpos($stale->get_error_message(), 'SHA-256 risposta:'), 'The unverified response did not include safe HTTP/cache diagnostic details.');
        sb_assert('<html>OLD_STATIC</html>' === file_get_contents($route_file), 'An unverified response replaced the existing static route.');

        $context = sb_private($plugin, 'begin_dynamic_render_bypass', array(array($url), true));
        sb_assert(!is_wp_error($context) && !file_exists($route_file) && is_file($enabled) && !file_exists($strict), 'The interruption fixture did not enter its protected bypass state.');
        $saved_get = $_GET;
        $saved_request_uri = isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : null;
        try {
            $_GET = array('static_bridge_bypass' => '1', 'static_bridge_render' => $context['transaction']['token']);
            $_SERVER['REQUEST_URI'] = $route . '?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            sb_assert($context['transaction']['token'] === sb_private($plugin, 'dynamic_render_response_token'), 'WordPress did not recognize the active same-origin render token.');
            $proof_marker = '<!--static-bridge-render:' . $context['transaction']['token'] . '-->';
            $body_with_proof = sb_private($plugin, 'append_dynamic_render_body_proof', array('<html>fresh</html>', $context['transaction']['token']));
            // 2.2.13: the render facts (nonces in the page, a WooCommerce page, a private page) go right before the proof.
            sb_assert(1 === preg_match('~^<html>fresh</html><!--static-bridge-facts:' . $context['transaction']['token'] . ':([A-Za-z0-9+/=]+)-->' . preg_quote($proof_marker, '~') . '$~', $body_with_proof, $facts_match)
                && is_array(json_decode(base64_decode($facts_match[1]), true)), 'The authorized WordPress response did not receive its body proof.');
            sb_assert($body_with_proof === sb_private($plugin, 'append_dynamic_render_body_proof', array($body_with_proof, $context['transaction']['token'])), 'The body proof was appended more than once.');
            $_SERVER['REQUEST_URI'] = '/different-route/?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            sb_assert('' === sb_private($plugin, 'dynamic_render_response_token'), 'The render token was accepted for a route outside the transaction.');
            sb_assert('<html>fresh</html>' === sb_private($plugin, 'append_dynamic_render_body_proof', array('<html>fresh</html>', $context['transaction']['token'])), 'A body proof was appended to a route outside the active transaction.');

            // TranslatePress SEO Pack rewrites REQUEST_URI to the original-language slug on plugins_loaded
            // (/en/where-we-are/ -> /en/dove-siamo/), after Static Bridge is loaded and before send_headers.
            $_SERVER['REQUEST_URI'] = $route . '?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            $translated_plugin = new Static_Bridge_Plugin();
            $_SERVER['REQUEST_URI'] = '/sb-original-slug/?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            sb_assert($context['transaction']['token'] === sb_private($translated_plugin, 'dynamic_render_response_token'), 'The render token was refused after a plugin rewrote REQUEST_URI to the original-language slug.');
            sb_assert(str_ends_with(sb_private($translated_plugin, 'append_dynamic_render_body_proof', array('<html>fresh</html>', $context['transaction']['token'])), $proof_marker), 'A rewritten REQUEST_URI dropped the body proof of an authorized render.');
            $_SERVER['REQUEST_URI'] = '/different-route/?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            $outside_plugin = new Static_Bridge_Plugin();
            $_SERVER['REQUEST_URI'] = '/sb-original-slug/?static_bridge_bypass=1&static_bridge_render=' . $context['transaction']['token'];
            sb_assert('' === sb_private($outside_plugin, 'dynamic_render_response_token'), 'The render token was accepted for a route outside the transaction after REQUEST_URI was rewritten.');
        } finally {
            $_GET = $saved_get;
            if (null === $saved_request_uri) {
                unset($_SERVER['REQUEST_URI']);
            } else {
                $_SERVER['REQUEST_URI'] = $saved_request_uri;
            }
        }
        flock($context['lock'], LOCK_UN);
        fclose($context['lock']);
        new Static_Bridge_Plugin();
        sb_assert(is_file($route_file) && '<html>OLD_STATIC</html>' === file_get_contents($route_file), 'Startup recovery did not restore the original route after a simulated PHP interruption.');
        sb_assert("enabled\n" === file_get_contents($enabled) && '' === file_get_contents($strict), 'Startup recovery did not restore the original routing markers.');
        sb_assert(false === get_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION, false), 'The completed recovery left a stale transaction record.');
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        delete_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION);
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array('.enabled' => $old_enabled, '.strict' => $old_strict) as $filename => $contents) {
            $path = $static_root . '/' . $filename;
            if (false === $contents) {
                if (is_file($path) || is_link($path)) {
                    unlink($path);
                }
            } else {
                file_put_contents($path, $contents);
            }
        }
        if (is_dir($release)) {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
            foreach ($iterator as $entry) {
                $entry->isDir() && !$entry->isLink() ? @rmdir($entry->getPathname()) : @unlink($entry->getPathname());
            }
            @rmdir($release);
        }
    }
});

sb_test('Current release follows a pointer swapped by another PHP process despite the realpath cache', function () use ($plugin) {
    if (!function_exists('proc_open') || (int) ini_get('realpath_cache_ttl') < 1) {
        throw new SB_Test_Skip('Requires proc_open and an enabled realpath cache.');
    }
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $releases = $static_root . '/releases';
    $current = $static_root . '/current';
    $old_target = is_link($current) ? readlink($current) : false;
    sb_assert(false !== $old_target || !file_exists($current), 'An unexpected current entry blocks the realpath fixture.');
    $first = 'realpath-cache-a-' . bin2hex(random_bytes(4));
    $second = 'realpath-cache-b-' . bin2hex(random_bytes(4));
    try {
        sb_assert(wp_mkdir_p($releases . '/' . $first) && wp_mkdir_p($releases . '/' . $second), 'Could not create the realpath fixture releases.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $first, $current), 'Could not link the first fixture release.');
        sb_assert(realpath($releases . '/' . $first) === sb_private($plugin, 'current_release'), 'The first fixture release was not resolved.');
        // A different PHP-FPM worker publishes the next release atomically.
        $swap = 'symlink($argv[1], $argv[2] . ".swap") && rename($argv[2] . ".swap", $argv[2]) || exit(1);';
        $process = proc_open(array(PHP_BINARY, '-n', '-r', $swap, 'releases/' . $second, $current), array(1 => array('pipe', 'w'), 2 => array('pipe', 'w')), $pipes);
        sb_assert(is_resource($process), 'Could not start the release-swap subprocess.');
        stream_get_contents($pipes[1]);
        stream_get_contents($pipes[2]);
        fclose($pipes[1]);
        fclose($pipes[2]);
        sb_assert(0 === proc_close($process) && 'releases/' . $second === readlink($current), 'The subprocess did not swap the current pointer.');
        sb_assert(realpath($releases . '/' . $second) === sb_private($plugin, 'current_release'), 'A stale realpath cache entry returned the previous release after another process published a new one.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_target) {
            symlink($old_target, $current);
        }
        @rmdir($releases . '/' . $first);
        @rmdir($releases . '/' . $second);
    }
});

sb_test('Render tokens never leak into static HTML through entity-encoded query separators (comment reply links)', function () use ($plugin) {
    $token = str_repeat('9f', 24);
    $cases = array(
        '<a id="cancel-comment-reply-link" href="/hello-world/?static_bridge_bypass=1&#038;static_bridge_render=' . $token . '#respond">' => '<a id="cancel-comment-reply-link" href="/hello-world/#respond">',
        '<a href="/p/?static_bridge_bypass=1&#38;static_bridge_render=' . $token . '">' => '<a href="/p/">',
        '<a href="/p/?static_bridge_bypass=1&#x26;static_bridge_render=' . $token . '&#038;replytocom=5#respond">' => '<a href="/p/?replytocom=5#respond">',
        '<a href="/p/?replytocom=5&#038;static_bridge_bypass=1&#038;static_bridge_render=' . $token . '#respond">' => '<a href="/p/?replytocom=5#respond">',
        '<a href="/p/?static_bridge_bypass=1&amp;static_bridge_render=' . $token . '">' => '<a href="/p/">',
    );
    foreach ($cases as $input => $expected) {
        $output = sb_private($plugin, 'strip_render_bypass_parameters', array($input, $token));
        sb_assert($expected === $output, 'Render parameters survived in static HTML: ' . $output);
        sb_assert(false === strpos($output, $token), 'The render token leaked into static HTML.');
    }
});

sb_test('Render tokens never leak into static HTML through a percent-encoded current URL (share links, 2.2.5)', function () use ($plugin) {
    $token = str_repeat('7c', 24);
    $page = 'http%3A%2F%2Fsito-c.local%2Fcookie-policy-eu%2F';
    $cases = array(
        // Bricks Post Sharing: Facebook, WhatsApp and X, with the outer query going on after the encoded URL.
        '<a href="https://www.facebook.com/sharer.php?u=' . $page . '%3Fstatic_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '">' => '<a href="https://www.facebook.com/sharer.php?u=' . $page . '">',
        '<a href="https://api.whatsapp.com/send?text=Cookie+Policy+' . $page . '%3Fstatic_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '" target="_blank">' => '<a href="https://api.whatsapp.com/send?text=Cookie+Policy+' . $page . '" target="_blank">',
        '<a href="https://x.com/share?text=Cookie&amp;url=' . $page . '%3Fstatic_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '&amp;via=sito-c">' => '<a href="https://x.com/share?text=Cookie&amp;url=' . $page . '&amp;via=sito-c">',
        // Lower-case escapes, an encoded fragment, encoded entities as the separator.
        '<a href="/s?u=' . $page . '%3fstatic_bridge_bypass%3d1%26static_bridge_render%3d' . $token . '">' => '<a href="/s?u=' . $page . '">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '%23respond">' => '<a href="/s?u=' . $page . '%23respond">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D1%26%23038%3Bstatic_bridge_render%3D' . $token . '">' => '<a href="/s?u=' . $page . '">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D1%26amp%3Bstatic_bridge_render%3D' . $token . '">' => '<a href="/s?u=' . $page . '">',
        // In the middle of other parameters, first, or alone.
        '<a href="/s?u=' . $page . '%3Flang%3Den%26static_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '%26page%3D2">' => '<a href="/s?u=' . $page . '%3Flang%3Den%26page%3D2">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D1%26static_bridge_render%3D' . $token . '%26replytocom%3D5">' => '<a href="/s?u=' . $page . '%3Freplytocom%3D5">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_render%3D' . $token . '">' => '<a href="/s?u=' . $page . '">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_render%3D' . $token . '%26a%3D1">' => '<a href="/s?u=' . $page . '%3Fa%3D1">',
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D1">' => '<a href="/s?u=' . $page . '">',
        '<a href="/s?u=' . $page . '%3fstatic_bridge_bypass%3d1%26static_bridge_render%3d' . $token . '%26a%3d1">' => '<a href="/s?u=' . $page . '%3fa%3d1">',
        // Encoded twice: a share link inside a redirector's URL; the outer %26 belongs to the redirector.
        '<a href="https://l.example/?u=https%3A%2F%2Fwww.facebook.com%2Fsharer.php%3Fu%3Dhttp%253A%252F%252Fsito-c.local%252F%253Fstatic_bridge_bypass%253D1%2526static_bridge_render%253D' . $token . '%26h%3D9">' => '<a href="https://l.example/?u=https%3A%2F%2Fwww.facebook.com%2Fsharer.php%3Fu%3Dhttp%253A%252F%252Fsito-c.local%252F%26h%3D9">',
        // The same in plain form: the bypass flag between two parameters.
        '<a href="/p/?lang=en&amp;static_bridge_bypass=1&amp;static_bridge_render=' . $token . '&amp;page=2">' => '<a href="/p/?lang=en&amp;page=2">',
        // Another value that only starts the same way stays as it is.
        '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D12">' => '<a href="/s?u=' . $page . '%3Fstatic_bridge_bypass%3D12">',
    );
    foreach ($cases as $input => $expected) {
        $output = sb_private($plugin, 'strip_render_bypass_parameters', array($input, $token));
        sb_assert($expected === $output, 'Percent-encoded render parameters survived in static HTML: ' . $output);
        sb_assert(false === stripos($output, $token), 'The percent-encoded render token leaked into static HTML.');
    }
    // Built as Bricks Post Sharing builds it: rawurlencode(home_url(esc_url_raw(REQUEST_URI))), then &amp;picture=….
    $bricks = rawurlencode(html_entity_decode('http://sito-c.local/en/cookie-policy-eu/?static_bridge_bypass=1&static_bridge_render=' . $token, ENT_COMPAT, 'UTF-8'));
    $output = sb_private($plugin, 'strip_render_bypass_parameters', array('<a href="https://www.facebook.com/sharer.php?u=' . $bricks . '&amp;picture=&amp;title=Cookie%20Policy">', $token));
    sb_assert('<a href="https://www.facebook.com/sharer.php?u=' . rawurlencode('http://sito-c.local/en/cookie-policy-eu/') . '&amp;picture=&amp;title=Cookie%20Policy">' === $output, 'The Bricks share link kept render parameters: ' . $output);
    // A form no rule knows (JSON-escaped separator) still loses the token.
    $output = sb_private($plugin, 'strip_render_bypass_parameters', array('<script>var u="/p/?static_bridge_bypass=1&static_bridge_render=' . strtoupper($token) . '";</script>', $token));
    sb_assert(false === stripos($output, $token), 'The render token leaked into static HTML in an unknown encoding.');
});

sb_test('Translatable strings carry the text domain, number multiple placeholders and are escaped in wp_die', function () use ($pluginFile) {
    $i18n = array('__', '_e', '_x', '_ex', '_n', '_nx', 'esc_html__', 'esc_html_e', 'esc_attr__', 'esc_attr_e', 'esc_html_x', 'esc_attr_x');
    $problems = array();
    foreach (glob(dirname($pluginFile) . '/*.php') as $file) {
        $tokens = token_get_all((string) file_get_contents($file));
        $count = count($tokens);
        for ($i = 0; $i < $count; $i++) {
            if (!is_array($tokens[$i]) || T_STRING !== $tokens[$i][0]) {
                continue;
            }
            $name = $tokens[$i][1];
            $prev = $i - 1;
            while ($prev >= 0 && is_array($tokens[$prev]) && T_WHITESPACE === $tokens[$prev][0]) {
                $prev--;
            }
            $is_method = $prev >= 0 && is_array($tokens[$prev]) && in_array($tokens[$prev][0], array(T_OBJECT_OPERATOR, T_DOUBLE_COLON, T_FUNCTION), true);
            $next = $i + 1;
            while ($next < $count && is_array($tokens[$next]) && T_WHITESPACE === $tokens[$next][0]) {
                $next++;
            }
            if ($is_method || !isset($tokens[$next]) || '(' !== $tokens[$next]) {
                continue;
            }
            // Collect the call's top-level argument tokens.
            $depth = 0;
            $args = array(array());
            for ($j = $next; $j < $count; $j++) {
                $t = $tokens[$j];
                if ('(' === $t || '[' === $t) { $depth++; if (1 === $depth && '(' === $t) { continue; } }
                if (')' === $t || ']' === $t) { $depth--; if (0 === $depth) { break; } }
                if (1 === $depth && ',' === $t) { $args[] = array(); continue; }
                $args[count($args) - 1][] = $t;
            }
            $line = $tokens[$i][2];
            $where = basename($file) . ':' . $line;
            $literal = static function (array $arg) {
                $parts = array_values(array_filter($arg, static function ($t) { return !(is_array($t) && T_WHITESPACE === $t[0]); }));
                return 1 === count($parts) && is_array($parts[0]) && T_CONSTANT_ENCAPSED_STRING === $parts[0][0] ? stripcslashes(substr($parts[0][1], 1, -1)) : null;
            };
            if (in_array($name, $i18n, true)) {
                $domain_index = in_array($name, array('_n', '_nx'), true) ? ('_nx' === $name ? 4 : 3) : (in_array($name, array('_x', '_ex', 'esc_html_x', 'esc_attr_x'), true) ? 2 : 1);
                if (!isset($args[$domain_index]) || 'static-bridge' !== $literal($args[$domain_index])) {
                    $problems[] = $where . ' ' . $name . '() without the static-bridge text domain';
                }
                $text = $literal($args[0]);
                if (is_string($text) && preg_match_all('/%(?!%)(?:\d+\$)?[sdf]/', $text, $m) > 1 && preg_match('/%[sdf]/', $text)) {
                    $problems[] = $where . ' unnumbered placeholders in "' . substr($text, 0, 50) . '"';
                }
            }
            if ('wp_die' === $name && isset($args[0])) {
                $first = array_values(array_filter($args[0], static function ($t) { return !(is_array($t) && T_WHITESPACE === $t[0]); }));
                if (isset($first[0]) && is_array($first[0]) && T_STRING === $first[0][0] && in_array($first[0][1], array('__', '_x'), true)) {
                    $problems[] = $where . ' wp_die() prints an unescaped translation';
                }
            }
        }
    }
    sb_assert(array() === $problems, implode(' | ', $problems));
});

sb_test('Activation preflight refuses WordPress multisite before changing anything', function () {
    $base = array('php_version' => '8.4.18', 'wp_version' => '7.1.3', 'memory_limit' => '256M', 'current_memory' => 8388608, 'peak_memory' => 8388608, 'content_dir' => WP_CONTENT_DIR);
    $single = Static_Bridge_Plugin::activation_preflight($base + array('multisite' => false));
    $multi = Static_Bridge_Plugin::activation_preflight($base + array('multisite' => true));
    sb_assert(!empty($single['ok']), 'A supported single-site install was refused: ' . implode(' | ', (array) ($single['errors'] ?? array())));
    sb_assert(empty($multi['ok']), 'Activation was allowed on WordPress multisite, where sites would share one document root and static router.');
    sb_assert(false !== stripos(implode(' ', (array) $multi['errors']), 'multisit'), 'The multisite refusal does not explain the reason.');
});

sb_test('Uninstall removes every Static Bridge trace without following symlinks or touching unrelated data', function () use ($fixtureRoot, $pluginFile) {
    $uninstaller = dirname($pluginFile) . '/uninstaller.php';
    $entry = dirname($pluginFile) . '/uninstall.php';
    sb_assert(is_file($uninstaller) && is_file($entry), 'The plugin ships no uninstall routine (uninstall.php / uninstaller.php).');
    $entry_code = (string) file_get_contents($entry);
    sb_assert(false !== strpos($entry_code, "defined('WP_UNINSTALL_PLUGIN')"), 'uninstall.php does not refuse to run outside the WordPress uninstall flow.');
    require_once $uninstaller;

    $root = $fixtureRoot . '/uninstall-' . bin2hex(random_bytes(4));
    $abspath = $root . '/site/';
    $content = $abspath . 'wp-content';
    $static = $content . '/static-bridge';
    $outside = $root . '/outside';
    sb_assert(wp_mkdir_p($static . '/releases/r1/page') && wp_mkdir_p($static . '/releases/r2') && wp_mkdir_p($outside . '/keep-dir'), 'Could not build the uninstall fixture.');
    file_put_contents($static . '/releases/r1/page/index.html', 'PAGE');
    file_put_contents($static . '/releases/r1/.ready', '');
    file_put_contents($static . '/.enabled', "enabled\n");
    file_put_contents($static . '/.strict', '');
    file_put_contents($outside . '/keep.txt', 'KEEP');
    file_put_contents($outside . '/keep-dir/inner.txt', 'KEEP-INNER');
    symlink('releases/r1', $static . '/current');
    symlink($outside . '/keep.txt', $static . '/releases/r2/link-to-file');
    symlink($outside . '/keep-dir', $static . '/releases/r2/link-to-dir');
    $other_file = $content . '/other-plugin-data.txt';
    file_put_contents($other_file, 'OTHER');
    $htaccess = $abspath . '.htaccess';
    file_put_contents($htaccess, "# custom rule kept\nOptions -Indexes\n\n# BEGIN Static Bridge Archive Protection\nRewriteRule ^wp-content/static-bridge(?:/|$) - [F,END,NC]\n# END Static Bridge Archive Protection\n\n# BEGIN Static Bridge\nRewriteRule ^ - [END]\n# END Static Bridge\n\n# BEGIN WordPress\nRewriteRule . /index.php [L]\n# END WordPress\n");

    $saved_options = $GLOBALS['sb_test_options'];
    $saved_transients = $GLOBALS['sb_test_transients'];
    $saved_hooks = $GLOBALS['sb_test_scheduled_hooks'];
    foreach (array('static_bridge_settings', 'static_bridge_job', 'static_bridge_activity', 'static_bridge_post_push_status_42') as $name) {
        $GLOBALS['sb_test_options'][$name] = array('x' => 1);
    }
    $GLOBALS['sb_test_options']['blogname'] = 'Unrelated';
    $GLOBALS['sb_test_options']['static_bridgeish_other_plugin'] = 'keep';
    $GLOBALS['sb_test_transients']['static_bridge_incremental_lock'] = 'lock';
    foreach (array('static_bridge_process_export_queue', 'static_bridge_process_incremental_queue', 'static_bridge_release_retention', 'static_bridge_cloudflare_purge') as $hook) {
        $GLOBALS['sb_test_scheduled_hooks'][$hook] = time() + 60;
    }
    $GLOBALS['sb_test_scheduled_hooks']['other_plugin_hook'] = time() + 60;

    $db = new class {
        public $prefix = 'wp_';
        public $options = 'wp_options';
        public $queries = array();
        public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
        public function prepare($query, ...$args) { $args = isset($args[0]) && is_array($args[0]) ? $args[0] : $args; foreach ($args as $a) { $query = preg_replace('/%s/', "'" . $a . "'", $query, 1); } return $query; }
        public function get_col($query)
        {
            $this->queries[] = $query;
            $names = array();
            foreach (array_keys($GLOBALS['sb_test_options']) as $name) {
                if (0 === strpos($name, 'static_bridge_')) { $names[] = $name; }
            }
            foreach (array_keys($GLOBALS['sb_test_transients']) as $name) {
                if (0 === strpos($name, 'static_bridge_')) { $names[] = '_transient_' . $name; $names[] = '_transient_timeout_' . $name; }
            }
            return $names;
        }
        public function query($query) { $this->queries[] = $query; return true; }
    };

    try {
        $report = (new Static_Bridge_Uninstaller($db, $content, $abspath))->run();
        sb_assert(is_array($report), 'The uninstaller did not return a report.');
        foreach (array_keys($GLOBALS['sb_test_options']) as $name) {
            sb_assert(0 !== strpos($name, 'static_bridge_'), 'A Static Bridge option survived uninstall: ' . $name);
        }
        sb_assert('Unrelated' === $GLOBALS['sb_test_options']['blogname'] && 'keep' === $GLOBALS['sb_test_options']['static_bridgeish_other_plugin'], 'Uninstall deleted options that do not belong to Static Bridge.');
        sb_assert(!isset($GLOBALS['sb_test_transients']['static_bridge_incremental_lock']), 'A Static Bridge transient survived uninstall.');
        foreach (array('static_bridge_process_export_queue', 'static_bridge_process_incremental_queue', 'static_bridge_release_retention', 'static_bridge_cloudflare_purge') as $hook) {
            sb_assert(!isset($GLOBALS['sb_test_scheduled_hooks'][$hook]), 'A Static Bridge cron hook survived uninstall: ' . $hook);
        }
        sb_assert(isset($GLOBALS['sb_test_scheduled_hooks']['other_plugin_hook']), 'Uninstall cleared another plugin\'s cron hook.');
        $tables = array(Static_Bridge_Export_Queue::TABLE_SUFFIX, Static_Bridge_Dependency_Index::STATE_SUFFIX, Static_Bridge_Dependency_Index::ROUTES_SUFFIX, Static_Bridge_Dependency_Index::EDGES_SUFFIX, Static_Bridge_Header_Fragment_Index::TABLE_SUFFIX);
        $sql = implode("\n", $db->queries);
        foreach ($tables as $suffix) {
            sb_assert(false !== strpos($sql, 'DROP TABLE IF EXISTS `wp_' . $suffix . '`'), 'The table was not dropped: wp_' . $suffix);
        }
        sb_assert(!file_exists($static) && !is_link($static), 'wp-content/static-bridge was not removed.');
        sb_assert('KEEP' === file_get_contents($outside . '/keep.txt') && 'KEEP-INNER' === file_get_contents($outside . '/keep-dir/inner.txt'), 'Uninstall followed a symlink and deleted data outside the static folder.');
        sb_assert('OTHER' === file_get_contents($other_file), 'Uninstall deleted unrelated files in wp-content.');
        $rules = (string) file_get_contents($htaccess);
        sb_assert(false === strpos($rules, 'Static Bridge'), 'A Static Bridge block survived in .htaccess.');
        sb_assert(false !== strpos($rules, "# custom rule kept\nOptions -Indexes") && false !== strpos($rules, "# BEGIN WordPress\nRewriteRule . /index.php [L]\n# END WordPress"), 'Uninstall damaged .htaccess content that is not Static Bridge\'s.');
    } finally {
        $GLOBALS['sb_test_options'] = $saved_options;
        $GLOBALS['sb_test_transients'] = $saved_transients;
        $GLOBALS['sb_test_scheduled_hooks'] = $saved_hooks;
    }
});

sb_test('Uninstall refuses to delete a static root that is a symlink or resolves elsewhere', function () use ($fixtureRoot, $pluginFile) {
    $uninstaller = dirname($pluginFile) . '/uninstaller.php';
    sb_assert(is_file($uninstaller), 'The plugin ships no uninstall routine (uninstaller.php).');
    require_once $uninstaller;
    $root = $fixtureRoot . '/uninstall-link-' . bin2hex(random_bytes(4));
    $content = $root . '/site/wp-content';
    $target = $root . '/elsewhere';
    sb_assert(wp_mkdir_p($content) && wp_mkdir_p($target . '/releases/r1'), 'Could not build the symlinked-root fixture.');
    file_put_contents($target . '/releases/r1/index.html', 'ELSEWHERE');
    symlink($target, $content . '/static-bridge');
    $db = new class {
        public $prefix = 'wp_';
        public $options = 'wp_options';
        public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
        public function prepare($query, ...$args) { return $query; }
        public function get_col($query) { return array(); }
        public function query($query) { return true; }
    };
    $report = (new Static_Bridge_Uninstaller($db, $content, $root . '/site/'))->run();
    sb_assert('ELSEWHERE' === @file_get_contents($target . '/releases/r1/index.html'), 'Uninstall deleted files through a symlinked static root.');
    sb_assert(is_array($report) && empty($report['files_removed']), 'The report claims the static files were removed although the root was refused.');
});

sb_test('Plugin load during an active render does not translate before init and defers recovery to init', function () use ($plugin) {
    $option = Static_Bridge_Plugin::RENDER_BYPASS_OPTION;
    $had_option = array_key_exists($option, $GLOBALS['sb_test_options']);
    $old_option = $had_option ? $GLOBALS['sb_test_options'][$option] : null;
    $hook_count = count($GLOBALS['sb_test_hooks']);
    $lock = sb_private($plugin, 'acquire_render_bypass_lock');
    sb_assert(is_array($lock), 'The render lock fixture could not be acquired.');
    try {
        // An export worker holds the lock while WordPress renders the route
        // in a separate request that loads the plugin before init.
        $GLOBALS['sb_test_options'][$option] = array('token' => 'not-a-valid-token');
        $GLOBALS['sb_test_did_actions']['init'] = 0;
        $GLOBALS['sb_test_translations_before_init'] = array();
        new Static_Bridge_Plugin();
        sb_assert(array() === $GLOBALS['sb_test_translations_before_init'], 'Plugin load requested static-bridge translations before init: ' . implode(' | ', $GLOBALS['sb_test_translations_before_init']));
        $deferred = null;
        foreach (array_slice($GLOBALS['sb_test_hooks'], $hook_count) as $hook) {
            if ('init' === $hook[0] && 0 === $hook[2]) {
                $deferred = $hook[1];
            }
        }
        sb_assert(is_callable($deferred), 'Render recovery was not deferred to the init action.');
        sb_private($plugin, 'release_render_bypass_lock', array($lock['handle']));
        $lock = null;
        $GLOBALS['sb_test_did_actions']['init'] = 1;
        call_user_func($deferred);
        $after = get_option($option, false);
        sb_assert(is_array($after) && !empty($after['recovery_reported']), 'The deferred init recovery did not run.');
    } finally {
        if (is_array($lock)) {
            sb_private($plugin, 'release_render_bypass_lock', array($lock['handle']));
        }
        $GLOBALS['sb_test_did_actions']['init'] = 1;
        $GLOBALS['sb_test_translations_before_init'] = array();
        array_splice($GLOBALS['sb_test_hooks'], $hook_count);
        if ($had_option) {
            $GLOBALS['sb_test_options'][$option] = $old_option;
        } else {
            delete_option($option);
        }
    }
});

sb_test('Page fetch defaults to a bounded 60-second timeout and preserves shorter caller limits', function () use ($plugin) {
    $url = home_url('/diagnostic-news/');
    $fetch_url = add_query_arg('static_bridge_bypass', '1', $url);
    $GLOBALS['sb_test_http_responses'] = array(
        $fetch_url => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>News</body></html>'),
    );
    $GLOBALS['sb_test_http_calls'] = array();
    $result = sb_private($plugin, 'fetch_page', array($url));
    sb_assert(!is_wp_error($result), 'A valid HTML page was rejected by the default render path.');
    sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The default fetch did not make exactly one HTTP request.');
    sb_assert(60 === $GLOBALS['sb_test_http_calls'][0]['args']['timeout'], 'The default export request does not allow the bounded 60-second queue wait.');
    sb_assert(0 === $GLOBALS['sb_test_http_calls'][0]['args']['redirection'], 'The longer timeout enabled automatic redirects.');
    sb_assert(5242880 === $GLOBALS['sb_test_http_calls'][0]['args']['limit_response_size'], 'The longer timeout removed the 5 MiB response bound.');

    $GLOBALS['sb_test_http_calls'] = array();
    $result = sb_private($plugin, 'fetch_page', array($url, 120));
    sb_assert(!is_wp_error($result) && 60 === $GLOBALS['sb_test_http_calls'][0]['args']['timeout'], 'A caller bypassed the maximum export timeout.');

    $GLOBALS['sb_test_http_calls'] = array();
    $result = sb_private($plugin, 'fetch_page', array($url, 10));
    sb_assert(!is_wp_error($result) && 10 === $GLOBALS['sb_test_http_calls'][0]['args']['timeout'], 'A shorter diagnostic or incremental timeout was not preserved.');
});

sb_test('Export HTTP waits and worker budget stay below a 30-second PHP-FPM limit', function () use ($plugin) {
    $previous_limit = (string) ini_get('max_execution_time');
    if (false === ini_set('max_execution_time', '30')) {
        throw new RuntimeException('Could not set the isolated PHP execution-time fixture.');
    }

    try {
        sb_assert(20 === sb_private($plugin, 'safe_php_request_budget'), 'The worker budget did not reserve ten seconds below the PHP-FPM limit.');

        $first = home_url('/fpm-budget-one/?static_bridge_bypass=1');
        $second = home_url('/fpm-budget-two/?static_bridge_bypass=1');
        $GLOBALS['sb_test_http_responses'] = array(
            $first => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>One</body></html>'),
            $second => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Two</body></html>'),
        );
        $GLOBALS['sb_test_http_calls'] = array();
        $results = sb_private($plugin, 'fetch_pages', array(array(home_url('/fpm-budget-one/'), home_url('/fpm-budget-two/'))));
        sb_assert(2 === count($results), 'The request-budgeted fallback did not return both pages.');
        sb_assert(2 === count($GLOBALS['sb_test_http_calls']), 'The request-budgeted fallback did not issue two bounded requests.');
        foreach ($GLOBALS['sb_test_http_calls'] as $call) {
            sb_assert(20 === $call['args']['timeout'], 'A page request can exceed the safe 20-second budget for PHP-FPM max_execution_time=30.');
        }

        $GLOBALS['sb_test_http_calls'] = array();
        $single = sb_private($plugin, 'fetch_page', array(home_url('/fpm-budget-one/'), 10));
        sb_assert(!is_wp_error($single) && 10 === $GLOBALS['sb_test_http_calls'][0]['args']['timeout'], 'The PHP-FPM budget increased a caller-specified shorter timeout.');
    } finally {
        ini_set('max_execution_time', $previous_limit);
    }
});

sb_test('Page redirects are inspected without following foreign or dynamic targets', function () use ($plugin) {
    $source = home_url('/category/news/');
    $request = $source . '?static_bridge_bypass=1';
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'] = array(
        $request => array('response' => array('code' => 301), 'headers' => array('Location' => home_url('/categoria/news/') . '?static_bridge_bypass=1'), 'body' => ''),
    );
    $redirect = sb_private($plugin, 'fetch_page', array($source, 10));
    sb_assert(is_wp_error($redirect) && 'static_bridge_redirect' === $redirect->get_error_code(), 'A same-origin canonical redirect was not surfaced to the crawler.');
    sb_assert(home_url('/categoria/news/') === $redirect->get_error_data(), 'The internal bypass query was not stripped from the canonical destination.');
    sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The redirect was followed automatically.');

    $GLOBALS['sb_test_http_responses'][$request] = array('response' => array('code' => 301), 'headers' => array('Location' => 'https://outside.invalid/news/'), 'body' => '');
    $external = sb_private($plugin, 'fetch_page', array($source, 10));
    sb_assert(is_wp_error($external) && 'static_bridge_redirect_unsafe' === $external->get_error_code(), 'A foreign redirect target was accepted.');
    sb_assert(2 === count($GLOBALS['sb_test_http_calls']) && false === strpos($GLOBALS['sb_test_http_calls'][1]['url'], 'outside.invalid'), 'The crawler made a request to the foreign redirect target.');

    $GLOBALS['sb_test_http_responses'][$request] = array('response' => array('code' => 301), 'headers' => array('Location' => '/wp-admin/'), 'body' => '');
    $dynamic = sb_private($plugin, 'fetch_page', array($source, 10));
    sb_assert(is_wp_error($dynamic) && 'static_bridge_redirect_unsafe' === $dynamic->get_error_code(), 'A redirect to a dynamic WordPress route was accepted.');
    sb_assert(3 === count($GLOBALS['sb_test_http_calls']) && false === strpos($GLOBALS['sb_test_http_calls'][2]['url'], '/wp-admin/'), 'The crawler followed a redirect to wp-admin.');

    $GLOBALS['sb_test_http_responses'][$request] = array('response' => array('code' => 301), 'headers' => array('Location' => '/categoria/news/?utm_source=dynamic'), 'body' => '');
    $dynamic_query = sb_private($plugin, 'fetch_page', array($source, 10));
    sb_assert(is_wp_error($dynamic_query) && 'static_bridge_redirect_unsafe' === $dynamic_query->get_error_code(), 'A redirect carrying a non-bridge query parameter was accepted.');
    sb_assert(4 === count($GLOBALS['sb_test_http_calls']), 'The crawler made an unexpected extra request for a query-bearing redirect.');
});

sb_test('WordPress inventory includes only published public passwordless posts and pages, without sitemap requests', function () use ($plugin) {
    $GLOBALS['sb_test_post_types'] = array(
        'post' => array('public' => true, 'publicly_queryable' => true),
        'page' => array('public' => true, 'publicly_queryable' => true),
        'attachment' => array('public' => true, 'publicly_queryable' => true),
        'private_note' => array('public' => false, 'publicly_queryable' => false),
        'internal_api' => array('public' => true, 'publicly_queryable' => false),
    );
    $GLOBALS['sb_test_posts'] = array(
        array('ID' => 1, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => ''),
        array('ID' => 2, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => 'secret'),
        array('ID' => 3, 'post_type' => 'post', 'post_status' => 'draft', 'post_password' => ''),
        array('ID' => 4, 'post_type' => 'private_note', 'post_status' => 'publish', 'post_password' => ''),
        array('ID' => 5, 'post_type' => 'attachment', 'post_status' => 'publish', 'post_password' => ''),
        array('ID' => 6, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => ''),
    );
    $GLOBALS['sb_test_post_urls'] = array(
        1 => home_url('/news/one/'),
        2 => home_url('/protected/'),
        3 => home_url('/draft/'),
        4 => home_url('/private/'),
        5 => home_url('/attachment/'),
        6 => home_url('/about/'),
    );
    $GLOBALS['sb_test_post_queries'] = array();
    $GLOBALS['sb_test_generated_post_count'] = 0;
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'] = array();

    $GLOBALS['sb_test_inventory_queries'] = array();
    $found = sb_private($plugin, 'discover_wordpress_post_url_batch', array(0));
    $expected = array(home_url('/news/one/'), home_url('/about/'));
    sb_assert(!is_wp_error($found) && $expected === $found['urls'] && !empty($found['complete']), 'WordPress did not enumerate the public posts/pages or it exposed excluded content.');
    sb_assert(empty($GLOBALS['sb_test_http_calls']), 'The WordPress inventory made sitemap or robots.txt requests.');
    sb_assert(1 === count($GLOBALS['sb_test_inventory_queries']), 'The small WordPress inventory required an unexpected number of queries.');
    $query = $GLOBALS['sb_test_inventory_queries'][0];
    sb_assert(array('post', 'page') === array_slice($query['args'], 1, -1), 'Non-public or attachment post types were queried.');
    sb_assert(false !== strpos($query['sql'], "post_status = 'publish' AND post_password = ''") && 100 === end($query['args']), 'The inventory query did not exclude drafts or password-protected content, or is not bounded.');
    foreach ($found['urls'] as $url) {
        sb_assert(false === in_array($url, array(home_url('/protected/'), home_url('/draft/'), home_url('/private/'), home_url('/attachment/')), true), 'A non-public or password-protected URL entered the static release.');
    }

    $GLOBALS['sb_test_post_types'] = array();
    $GLOBALS['sb_test_posts'] = array();
    $GLOBALS['sb_test_post_urls'] = array();
    $GLOBALS['sb_test_post_queries'] = array();
});

sb_test('WordPress inventory paginates in bounded batches instead of loading every post at once', function () use ($plugin) {
