sb_test('Static route parity diagnostic identifies WordPress fallback and intermediary mismatch', function () use ($plugin) {
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release = $static_root . '/releases/diagnostic-route-parity';
    $current_link = $static_root . '/current';
    $url = home_url('/diagnostic-route/');
    $file = $release . '/diagnostic-route/index.html';
    $had_current = is_link($current_link);
    $previous_target = $had_current ? readlink($current_link) : null;
    $option = Static_Bridge_Plugin::JOB_OPTION;
    $had_job = array_key_exists($option, $GLOBALS['sb_test_options']);
    $previous_job = $had_job ? $GLOBALS['sb_test_options'][$option] : null;
    $html_file = '<html><body>Current static release</body></html>';
    $html_fresh = '<html><body>Current WordPress render</body></html>';
    $fetch_url = $url . '?static_bridge_bypass=1';

    try {
        $GLOBALS['sb_test_options'][$option] = array();
        sb_assert(wp_mkdir_p(dirname($file)), 'The route diagnostic release fixture could not be created.');
        file_put_contents($file, $html_file);
        if (file_exists($current_link) || is_link($current_link)) {
            @unlink($current_link);
        }
        sb_assert(@symlink('releases/diagnostic-route-parity', $current_link), 'The isolated current release pointer could not be created.');

        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_responses'] = array(
            $fetch_url => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => $html_fresh),
        );
        $public = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html', 'X-Cache' => 'HIT', 'Age' => '32'), 'body' => $html_fresh);
        $result = sb_private($plugin, 'diagnostic_static_route_parity_result', array('static-test', 'Static route', $url, $file, realpath($release), $public));
        sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'coincide con WordPress aggiornato'), 'A public WordPress fallback was not identified.');
        sb_assert(false !== strpos($result['summary'], 'SHA-256/byte') && $url === $result['url'], 'The failure report omitted fingerprints or the route field.');
        sb_assert(false !== strpos($result['summary'], 'x-cache=HIT') && false !== strpos($result['summary'], 'age=32'), 'The report omitted cache headers that can identify an intermediary hit.');
        sb_assert(1 === count($GLOBALS['sb_test_http_calls']) && sb_test_render_request_matches($GLOBALS['sb_test_http_calls'][0]['url'], $url), 'The diagnostic did not make exactly one verified fresh-render request.');
        sb_assert($html_file === file_get_contents($file), 'The comparison modified the active HTML file.');

        $GLOBALS['sb_test_http_calls'] = array();
        $public['body'] = $html_file;
        $result = sb_private($plugin, 'diagnostic_static_route_parity_result', array('static-test', 'Static route', $url, $file, realpath($release), $public));
        sb_assert('pass' === $result['status'] && empty($GLOBALS['sb_test_http_calls']), 'A byte-identical public static response did not pass without a needless WordPress render.');

        $html_public = '<html><body>Different intermediary response</body></html>';
        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_responses'][$fetch_url] = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => $html_file);
        $public['body'] = $html_public;
        $result = sb_private($plugin, 'diagnostic_static_route_parity_result', array('static-test', 'Static route', $url, $file, realpath($release), $public));
        sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'cache, proxy o trasformazione'), 'The diagnostic did not distinguish an intermediary mismatch from WordPress fallback.');
        sb_assert($html_file === file_get_contents($file), 'The second comparison modified the active HTML file.');

        $ssi_hash = str_repeat('a', 64);
        $html_ssi = '<html><body><!--#include virtual="/wp-content/static-bridge/current/fragments/headers/123/current/elementor-123-' . $ssi_hash . '.html" --><p>Static body</p></body></html>';
        file_put_contents($file, $html_ssi);
        file_put_contents($release . '/manifest.json', wp_json_encode(array('ssi_header_fragments' => 1)));
        $GLOBALS['sb_test_http_calls'] = array();
        $public['body'] = $html_ssi;
        $result = sb_private($plugin, 'diagnostic_static_route_parity_result', array('static-test', 'Static route', $url, $file, realpath($release), $public));
        sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'direttiva SSI non elaborata'), 'The diagnostic did not identify an SSI include that the server left unexpanded.');
        sb_assert(empty($GLOBALS['sb_test_http_calls']), 'An unexpanded SSI include triggered an unnecessary WordPress render.');
    } finally {
        if (is_link($current_link)) {
            unlink($current_link);
        }
        if ($had_current && is_string($previous_target)) {
            symlink($previous_target, $current_link);
        }
        foreach (array($file, $release . '/manifest.json', $release . '/.ready') as $fixture) {
            if (is_file($fixture) || is_link($fixture)) {
                unlink($fixture);
            }
        }
        if (is_dir(dirname($file))) {
            rmdir(dirname($file));
        }
        if (is_dir($release)) {
            rmdir($release);
        }
        if (is_dir(dirname($release))) {
            $entries = array_values(array_diff(scandir(dirname($release)), array('.', '..')));
            if (empty($entries)) {
                rmdir(dirname($release));
            }
        }
        if (is_dir($static_root . '/releases')) {
            $entries = array_values(array_diff(scandir($static_root . '/releases'), array('.', '..')));
            if (empty($entries)) {
                rmdir($static_root . '/releases');
            }
        }
        if (!$had_current && is_dir($static_root)) {
            @rmdir($static_root);
        }
        if ($had_job) {
            $GLOBALS['sb_test_options'][$option] = $previous_job;
        } else {
            unset($GLOBALS['sb_test_options'][$option]);
        }
        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_responses'] = array();
    }
});

sb_test('Diagnostic export job snapshot retains failure context without leaking stage paths or external URLs', function () use ($plugin) {
    $option = Static_Bridge_Plugin::JOB_OPTION;
    $had_previous = array_key_exists($option, $GLOBALS['sb_test_options']);
    $previous = $had_previous ? $GLOBALS['sb_test_options'][$option] : null;
    $GLOBALS['sb_test_options'][$option] = array(
        'queue_version' => 1,
        'job_id' => '12345678-1234-4234-8234-123456789abc',
        'status' => 'failed',
        'release_id' => 'failed-release',
        'stage' => '/sensitive/absolute/staging/path',
        'started_at' => 100,
        'updated_at' => 200,
        'discovery_complete' => true,
        'discovery_cursor' => 4,
        'discovered' => 4,
        'processed' => 3,
        'saved' => 2,
        'skipped' => 1,
        'current_url' => home_url('/news/current/'),
        'issues' => array(
            array('url' => 'https://outside.invalid/private/', 'message' => 'external must be omitted'),
            array('url' => home_url('/news/current/'), 'message' => '<b>render failed</b>', 'retryable_transient' => true, 'type' => 'route_error', 'previous_copy_preserved' => 1),
        ),
    );
    $snapshot = sb_private($plugin, 'diagnostic_export_job_snapshot');
    sb_assert('failed' === $snapshot['status'] && 3 === $snapshot['processed'] && 1 === $snapshot['skipped'], 'The snapshot omitted the failed job status or counters.');
    sb_assert(home_url('/news/current/') === $snapshot['current_url'] && home_url('/news/current/') === $snapshot['issues'][1]['url'], 'The same-origin failure route was not retained.');
    sb_assert('render failed' === $snapshot['issues'][1]['message'] && !empty($snapshot['issues'][1]['retryable_transient']), 'The issue message or retry classification was lost.');
    sb_assert('route_error' === $snapshot['issues'][1]['type'] && !empty($snapshot['issues'][1]['previous_copy_preserved']), 'The diagnostic snapshot lost the route-error type or last-known-good copy status.');
    sb_assert('' === $snapshot['issues'][0]['url'] && !isset($snapshot['stage']) && false === strpos(json_encode($snapshot), '/sensitive/absolute/'), 'The snapshot exposed an external URL or absolute staging path.');
    if ($had_previous) {
        $GLOBALS['sb_test_options'][$option] = $previous;
    } else {
        unset($GLOBALS['sb_test_options'][$option]);
    }
});

sb_test('Diagnostics select only a transient same-origin URL from a failed or paused export', function () use ($plugin) {
    $option = Static_Bridge_Plugin::JOB_OPTION;
    $had_previous = array_key_exists($option, $GLOBALS['sb_test_options']);
    $previous = $had_previous ? $GLOBALS['sb_test_options'][$option] : null;
    $latest_url = home_url('/latest-news/');
    $GLOBALS['sb_test_options'][$option] = array(
        'status' => 'failed',
        'issues' => array(
            array('url' => home_url('/older-news/'), 'message' => 'cURL error 28: Operation timed out'),
            array('url' => 'https://outside.invalid/private/', 'message' => 'cURL error 28: Operation timed out'),
            array('url' => $latest_url, 'message' => 'cURL error 28: Operation timed out after 20000 milliseconds'),
        ),
    );

    $target = sb_private($plugin, 'diagnostic_retryable_export_url');
    sb_assert($latest_url === $target, 'The diagnostic did not choose the latest valid transient failure.');
    $GLOBALS['sb_test_http_calls'] = array();
    $plan = sb_private($plugin, 'diagnostic_plan', array(''));
    $target_steps = array_values(array_filter($plan, function ($step) use ($latest_url) {
        return isset($step['type'], $step['url']) && 'render-failed-url' === $step['type'] && $latest_url === $step['url'];
    }));
    sb_assert(1 === count($target_steps), 'The diagnostic plan did not add exactly one targeted render check.');
    sb_assert(empty($GLOBALS['sb_test_http_calls']), 'Building a diagnostic plan unexpectedly sent an HTTP request.');

    $GLOBALS['sb_test_options'][$option]['status'] = 'running';
    sb_assert('' === sb_private($plugin, 'diagnostic_retryable_export_url'), 'An active export was incorrectly treated as a failed job for probing.');
    $GLOBALS['sb_test_options'][$option]['status'] = 'failed';
    $GLOBALS['sb_test_options'][$option]['issues'] = array(
        array('url' => 'https://outside.invalid/private/', 'message' => 'cURL error 28: Operation timed out'),
    );
    sb_assert('' === sb_private($plugin, 'diagnostic_retryable_export_url'), 'An external URL was accepted as the probe target.');

    if ($had_previous) {
        $GLOBALS['sb_test_options'][$option] = $previous;
    } else {
        unset($GLOBALS['sb_test_options'][$option]);
    }
});

sb_test('Diagnostica summaries use singular and plural forms correctly', function () use ($plugin) {
    $one = sb_private($plugin, 'diagnostic_summary', array(array(array('status' => 'fail'), array('status' => 'warning'), array('status' => 'pass'))));
    sb_assert('1 superato · 1 avviso · 1 errore' === $one['label'], 'Singular summary is wrong: ' . $one['label']);
    $many = sb_private($plugin, 'diagnostic_summary', array(array(array('status' => 'fail'), array('status' => 'fail'), array('status' => 'pass'), array('status' => 'pass'))));
    sb_assert('2 superati · 0 avvisi · 2 errori' === $many['label'], 'Plural summary is wrong: ' . $many['label']);
});

sb_test('Diagnostica catches a server block that serves the static copy to logged-in cookies or POST', function () use ($plugin, $fixtureRoot) {
    $saved_software = $_SERVER['SERVER_SOFTWARE'] ?? null;
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $current = $static_root . '/current';
    $old_target = is_link($current) ? readlink($current) : false;
    $release = 'diag-guard-' . bin2hex(random_bytes(4));
    $htaccess = ABSPATH . '.htaccess';
    $old_htaccess = is_file($htaccess) ? file_get_contents($htaccess) : null;
    try {
        sb_assert(wp_mkdir_p($static_root . '/releases/' . $release), 'Could not create the diagnostic release fixture.');
        file_put_contents($static_root . '/releases/' . $release . '/index.html', '<html>STATIC</html>');
        if (is_link($current)) { unlink($current); }
        symlink('releases/' . $release, $current);

        // Nginx: the plan probes both guards; a response marked static is a failure.
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $ids = array_column(sb_private($plugin, 'diagnostic_plan', array('')), 'id');
        sb_assert(in_array('logged-in-bypass', $ids, true) && in_array('post-bypass', $ids, true), 'The Nginx diagnostic plan does not probe the logged-in cookie and POST guards.');
        $static = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html', 'x-static-bridge-route' => 'static'), 'body' => '<html>STATIC</html>');
        $dynamic = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>WordPress</html>');
        foreach (array(array($static, 'fail'), array($dynamic, 'pass')) as [$answer, $expected]) {
            $GLOBALS['sb_test_http_calls'] = array();
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($answer) { return $answer; };
            $GLOBALS['sb_test_http_post_callback'] = function ($url, $args) use ($answer) { return $answer; };
            $cookie = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'logged-in-bypass', 'type' => 'cookie-bypass'), array()));
            $post = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'post-bypass', 'type' => 'post-bypass'), array()));
            sb_assert($expected === $cookie['status'], 'Logged-in cookie probe: expected ' . $expected . ', got ' . $cookie['status']);
            sb_assert($expected === $post['status'], 'POST probe: expected ' . $expected . ', got ' . $post['status']);
            $calls = $GLOBALS['sb_test_http_calls'];
            sb_assert(2 === count($calls), 'The two probes did not send exactly two requests.');
            sb_assert('wp_safe_remote_get' === $calls[0]['api'] && false !== strpos((string) ($calls[0]['args']['headers']['Cookie'] ?? ''), 'wordpress_logged_in_'), 'The cookie probe did not send a wordpress_logged_in_ cookie.');
            sb_assert('wp_safe_remote_post' === $calls[1]['api'] && home_url('/') === $calls[1]['url'] && '' === ($calls[1]['args']['body'] ?? null), 'The POST probe was not an empty POST to the homepage.');
            sb_assert(0 === $calls[0]['args']['redirection'] && 0 === $calls[1]['args']['redirection'], 'A probe followed redirects.');
        }

        // Apache: the rules check requires the cookie and method conditions.
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $ids = array_column(sb_private($plugin, 'diagnostic_plan', array('')), 'id');
        sb_assert(!in_array('logged-in-bypass', $ids, true), 'The header-based probes were planned on Apache, where the routing header needs mod_headers.');
        $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block') . "\n\n# BEGIN WordPress\n# END WordPress\n";
        $results = array();
        foreach (array('full' => $rules, 'no-cookie' => preg_replace('~^RewriteCond %\{HTTP_COOKIE\} .*wordpress_logged_in_.*\R~m', '', $rules), 'no-method' => preg_replace('~^RewriteCond %\{REQUEST_METHOD\} .*\R~m', '', $rules)) as $name => $contents) {
            file_put_contents($htaccess, $contents);
            $results[$name] = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()))['status'];
        }
        sb_assert('fail' !== $results['full'], 'The complete generated Apache rules were rejected: ' . json_encode($results));
        sb_assert('fail' === $results['no-cookie'] && 'fail' === $results['no-method'], 'Apache rules without the cookie or method condition were accepted: ' . json_encode($results));
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        $GLOBALS['sb_test_http_post_callback'] = null;
        if (null === $saved_software) { unset($_SERVER['SERVER_SOFTWARE']); } else { $_SERVER['SERVER_SOFTWARE'] = $saved_software; }
        if (is_link($current)) { unlink($current); }
        if (false !== $old_target) { symlink($old_target, $current); }
        @unlink($static_root . '/releases/' . $release . '/index.html');
        @rmdir($static_root . '/releases/' . $release);
        if (null === $old_htaccess) { @unlink($htaccess); } else { file_put_contents($htaccess, $old_htaccess); }
    }
});

sb_test('Targeted export diagnostic reuses bounded same-origin rendering and never publishes', function () use ($plugin) {
    $target = home_url('/diagnostic-news/');
    $fetch_url = add_query_arg('static_bridge_bypass', '1', $target);
    $options_before = $GLOBALS['sb_test_options'];
    $step = array('id' => 'render-failed-url', 'type' => 'render-failed-url', 'url' => $target);
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'] = array(
        $fetch_url => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>News</body></html>'),
    );
    $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
    sb_assert('pass' === $result['status'], 'A valid single-page render was not reported as recovered.');
    sb_assert($target === $result['url'], 'The diagnostic result did not identify the checked public path.');
    sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The targeted diagnostic made more than one render request.');
    sb_assert(sb_test_render_request_matches($GLOBALS['sb_test_http_calls'][0]['url'], $target), 'The target request did not use the verified exporter bypass URL.');
    sb_assert(60 === $GLOBALS['sb_test_http_calls'][0]['args']['timeout'], 'The target request timeout differs from the exporter.');
    sb_assert(0 === $GLOBALS['sb_test_http_calls'][0]['args']['redirection'], 'The targeted diagnostic followed redirects.');
    sb_assert(5242880 === $GLOBALS['sb_test_http_calls'][0]['args']['limit_response_size'], 'The target request omitted the bounded HTML response limit.');

    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'] = array(
        $fetch_url => new WP_Error('http_request_failed', 'cURL error 28: Operation timed out'),
    );
    $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
    sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'cURL error 28'), 'A reproduced loopback timeout was not visible in the diagnostic result.');

    $GLOBALS['sb_test_http_calls'] = array();
    $unsafe_step = array('id' => 'render-failed-url', 'type' => 'render-failed-url', 'url' => 'https://outside.invalid/private/');
    $result = sb_private($plugin, 'run_diagnostic_step', array($unsafe_step, array()));
    sb_assert('fail' === $result['status'] && empty($GLOBALS['sb_test_http_calls']), 'An invalid target triggered an outbound request.');

    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'] = array(
        $fetch_url => array('response' => array('code' => 404), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html>Missing</html>'),
    );
    $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
    sb_assert('warning' === $result['status'], 'A now-non-public URL was reported as a transient server failure instead of an export skip.');
    sb_assert($options_before === $GLOBALS['sb_test_options'], 'The one-URL diagnostic changed WordPress options or export state.');
    $GLOBALS['sb_test_http_responses'] = array();
});

sb_test('Targeted static parity diagnostic validates a same-site route and identifies stale duplicate images', function () use ($plugin) {
    $normalize = function ($value) use ($plugin) { return sb_private($plugin, 'normalize_diagnostic_target_url', array($value)); };
    $target = home_url('/presentazione-del-rettore/');
    sb_assert($target === $normalize('/presentazione-del-rettore/'), 'A root-relative same-site route was not accepted.');
    sb_assert($target === $normalize($target), 'An absolute URL for the configured origin was not accepted.');
    foreach (array(
        'https://outside.invalid/presentazione-del-rettore/',
        'https://news.example.test:9443/presentazione-del-rettore/',
        '/presentazione-del-rettore/?preview=1',
        '/presentazione-del-rettore/#content',
        '/%2e%2e/private/',
        '/wp-admin/',
        '/uploads/image.jpg',
        '//outside.invalid/path/',
        '/path with spaces/',
    ) as $invalid_target) {
        sb_assert('' === $normalize($invalid_target), 'An unsafe or non-page target was accepted: ' . $invalid_target);
    }

    $old_post = $_POST;
    $_POST = array('target_url' => 'https://outside.invalid/presentazione-del-rettore/');
    try {
        $plugin->ajax_diagnostic_start();
        throw new RuntimeException('The AJAX endpoint accepted an external diagnostic URL.');
    } catch (SB_Test_Response $response) {
        sb_assert(400 === $response->status, 'An invalid AJAX target did not return HTTP 400.');
    } finally {
        $_POST = $old_post;
    }

    $GLOBALS['sb_test_http_calls'] = array();
    $plan = sb_private($plugin, 'diagnostic_plan', array('', $target));
    $target_steps = array_values(array_filter($plan, function ($step) use ($target) {
        return isset($step['type'], $step['url']) && 'static-parity' === $step['type'] && $target === $step['url'];
    }));
    sb_assert(1 === count($target_steps), 'The full diagnostic plan did not include exactly one targeted parity check.');
    $route_steps = array_values(array_filter($plan, function ($step) use ($target) {
        return isset($step['type'], $step['url']) && 'static-route-parity' === $step['type'] && $target === $step['url'];
    }));
    sb_assert(1 === count($route_steps), 'The full diagnostic plan did not include the targeted HTML route comparison.');
    sb_assert(empty($GLOBALS['sb_test_http_calls']), 'Planning the targeted check unexpectedly sent an HTTP request.');

    $images = sb_private($plugin, 'diagnostic_image_inventory', array(
        '<img data-src="https://images.example.net/lazy.jpg?token=private" src="data:image/gif;base64,placeholder">'
            . '<img srcset="/uploads/responsive.jpg 1x, /uploads/responsive-large.jpg 2x">',
        $target,
    ));
    sb_assert(2 === $images['tags'] && 2 === $images['references'], 'Lazy-loaded and srcset image sources were not inventoried.');
    sb_assert(isset($images['images']['//images.example.net/lazy.jpg'], $images['images']['//news.example.test:8443/uploads/responsive.jpg']), 'The image inventory failed to resolve sources or strip tracking query strings.');

    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $releases = $static_root . '/releases';
    if (is_link($static_root) || (!is_dir($releases) && !wp_mkdir_p($releases))) {
        throw new RuntimeException('Could not prepare the isolated image-parity fixture.');
    }
    $current = $static_root . '/current';
    if ((file_exists($current) || is_link($current)) && !is_link($current)) {
        throw new RuntimeException('The current release fixture is not a symlink and cannot be safely replaced.');
    }
    $old_current_target = is_link($current) ? readlink($current) : false;
    $release_id = 'diagnostic-parity-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $releases . '/' . $release_id;
    $route_file = $release . '/presentazione-del-rettore/index.html';
    $enabled = $static_root . '/.enabled';
    $strict = $static_root . '/.strict';
    $old_enabled = is_file($enabled) ? file_get_contents($enabled) : false;
    $old_strict = is_file($strict) ? file_get_contents($strict) : false;
    if (is_link($enabled) || is_link($strict) || !wp_mkdir_p(dirname($route_file))) {
        throw new RuntimeException('The isolated image-parity fixture paths are unsafe or unavailable.');
    }
    $static_html = '<!doctype html><html><body><img src="https://images.example.net/photo.jpg?size=large&amp;token=must-not-leak"><img src="https://images.example.net/photo.jpg?size=small"></body></html>';
    $wordpress_html = '<!doctype html><html><body><p>Current WordPress page has no images.</p></body></html>';
    $had_job = array_key_exists(Static_Bridge_Plugin::JOB_OPTION, $GLOBALS['sb_test_options']);
    $old_job = $had_job ? $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] : null;
    $had_bypass = array_key_exists(Static_Bridge_Plugin::RENDER_BYPASS_OPTION, $GLOBALS['sb_test_options']);
    $old_bypass = $had_bypass ? $GLOBALS['sb_test_options'][Static_Bridge_Plugin::RENDER_BYPASS_OPTION] : null;

    try {
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not activate the isolated parity fixture release.');
        sb_assert(false !== file_put_contents($route_file, $static_html), 'Could not write the static image fixture.');
        file_put_contents($enabled, "enabled\n");
        file_put_contents($strict, 'strict-marker');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        delete_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION);

        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_callback'] = function ($request_url) use ($route_file, $static_html, $wordpress_html) {
            $parts = wp_parse_url($request_url);
            $query = array();
            parse_str(isset($parts['query']) ? $parts['query'] : '', $query);
            if (!empty($query['static_bridge_render'])) {
                $token = (string) $query['static_bridge_render'];
                // The guarded render reaches WordPress while the static file stays in place
                // for anonymous visitors (2.0.15: nothing the server may serve is moved).
                if (preg_match('/^[a-f0-9]{48}$/', $token) && is_file($route_file) && $static_html === file_get_contents($route_file)) {
                    return array(
                        'response' => array('code' => 200),
                        'headers' => array('Content-Type' => 'text/html', 'X-Static-Bridge-Render' => $token),
                        'body' => $wordpress_html,
                    );
                }
                return array('response' => array('code' => 503), 'headers' => array(), 'body' => 'static file moved during the render');
            }
            return array(
                'response' => array('code' => 200),
                'headers' => array('Content-Type' => 'text/html'),
                'body' => $static_html,
            );
        };
        $step = array('id' => 'static-parity-target', 'type' => 'static-parity', 'label' => 'Confronto mirato', 'url' => $target);
        $result = sb_private($plugin, 'run_diagnostic_step', array($step, array('release' => $release_id)));

        sb_assert('fail' === $result['status'], 'The stale static copy with two images was not flagged.');
        sb_assert(false !== strpos($result['summary'], 'file 2, pubblico 2, WordPress aggiornato 0'), 'The comparison did not report the three observed image counts.');
        sb_assert(false !== strpos($result['summary'], '//images.example.net/photo.jpg (file 2, pubblico 2, WordPress 0)'), 'The duplicate image source and counts were not identified.');
        sb_assert(false === strpos($result['summary'], 'must-not-leak'), 'An image query token leaked into the diagnostic result.');
        sb_assert(2 === count($GLOBALS['sb_test_http_calls']), 'The parity check did not make exactly one public and one verified WordPress GET.');
        sb_assert(is_file($route_file) && $static_html === file_get_contents($route_file), 'The parity check did not restore the original static route byte-for-byte.');
        sb_assert("enabled\n" === file_get_contents($enabled) && 'strict-marker' === file_get_contents($strict), 'The parity check did not restore the original routing markers.');
        sb_assert(false === get_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION, false), 'The parity check left an active render transaction behind.');
        sb_assert(empty(glob(dirname($route_file) . '/*.sb-render-*.bak')), 'The parity check left a temporary route backup behind.');

        $route_step = array('id' => 'static-route-target', 'type' => 'static-route-parity', 'label' => 'Parità HTML mirata', 'url' => $target);
        $route_result = sb_private($plugin, 'run_diagnostic_step', array($route_step, array('release' => $release_id)));
        sb_assert('pass' === $route_result['status'] && $target === $route_result['url'], 'The new targeted route comparison did not confirm a byte-identical active static file.');
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        if ($had_job) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $old_job;
        } else {
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        }
        if ($had_bypass) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::RENDER_BYPASS_OPTION] = $old_bypass;
        } else {
            delete_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION);
        }
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        if (is_file($route_file)) {
            unlink($route_file);
        }
        if (is_dir(dirname($route_file))) {
            rmdir(dirname($route_file));
        }
        if (is_dir($release)) {
            rmdir($release);
        }
        foreach (array($enabled => $old_enabled, $strict => $old_strict) as $marker => $contents) {
            if (false === $contents) {
                if (is_file($marker) || is_link($marker)) {
                    unlink($marker);
                }
            } elseif (!is_link($marker)) {
                file_put_contents($marker, $contents);
            }
        }
        $GLOBALS['sb_test_http_responses'] = array();
    }
});

sb_test('Filesystem mapping rejects traversal and foreign origins', function () use ($plugin) {
    $valid = sb_private($plugin, 'relative_html_path', array(home_url('/news/')));
    sb_assert('news/index.html' === $valid, 'A normal page did not map to the expected relative HTML file.');
    $traversal = sb_private($plugin, 'relative_html_path', array(home_url('/%2e%2e/private/')));
    sb_assert(is_wp_error($traversal), 'Encoded traversal was accepted.');
    $foreign = sb_private($plugin, 'relative_html_path', array('https://outside.invalid/news/'));
    sb_assert(is_wp_error($foreign), 'A foreign origin was accepted for filesystem mapping.');
});

sb_test('Filesystem mapping keeps the decoded bytes the web server looks up (slugs like pdf, c, _bozza, caffè)', function () use ($plugin) {
    $expected = array(
        '/tag/pdf/' => 'tag/pdf/index.html',
        '/tag/c/' => 'tag/c/index.html',
        '/class/' => 'class/index.html',
        '/tag/_bozza/' => 'tag/_bozza/index.html',
        '/tag/bozza-/' => 'tag/bozza-/index.html',
        '/caff%C3%A8/' => "caff\xC3\xA8/index.html",
        "/caff\xC3\xA8/" => "caff\xC3\xA8/index.html",
        '/%CE%B8%CE%B5%CE%BF%CF%82/%E6%96%87/' => "\xCE\xB8\xCE\xB5\xCE\xBF\xCF\x82/\xE6\x96\x87/index.html",
        '/' => 'index.html',
    );
    foreach ($expected as $path => $relative) {
        $mapped = sb_private($plugin, 'relative_html_path', array(home_url($path)));
        sb_assert($relative === $mapped, $path . ' mapped to ' . (is_wp_error($mapped) ? $mapped->get_error_message() : $mapped) . ' instead of ' . $relative . '.');
    }
    $refused = array('/../etc/', '/a/../b/', '/%2e%2e/b/', '/%2E%2E/', '/a/%2e/b/', '/a%2fb/', '/a%2Fb/', '/a%5cb/', '/a%00b/', '/a%0ab/', '/a%20b/', '/a%09b/',
        '/a%25b/', '/a%3fb/', '/a%23b/', '/.htaccess/', '/%2ehtaccess/', '/.well-known/x/', '/x/.git/', '/%ff%fe/', '/' . str_repeat('a', 256) . '/');
    foreach ($refused as $path) {
        $mapped = sb_private($plugin, 'relative_html_path', array(home_url('/') . ltrim($path, '/')));
        sb_assert(is_wp_error($mapped), $path . ' was mapped to ' . (is_string($mapped) ? $mapped : '?') . '.');
    }
    sb_assert('tag/' . str_repeat('a', 255) . '/index.html' === sb_private($plugin, 'relative_html_path', array(home_url('/tag/' . str_repeat('a', 255) . '/'))), 'A 255-byte segment was refused.');
});

sb_test('Canonical, hreflang, Open Graph, Twitter and JSON-LD keep absolute URLs while content links become portable', function () use ($plugin) {
    $old_home = $GLOBALS['sb_test_home'];
    $old_site = $GLOBALS['sb_test_site_url'];
    $GLOBALS['sb_test_home'] = 'https://shop.example.test';
    $GLOBALS['sb_test_site_url'] = 'https://shop.example.test';
    try {
        // A product page as a WooCommerce site with an SEO plugin renders it.
        $head = '<link rel="canonical" href="https://shop.example.test/prodotto/libro/">'
            . "<link rel='shortlink' href='https://shop.example.test/?p=42'>"
            . '<link rel="alternate" hreflang="en" href="https://shop.example.test/en/product/book/">'
            . '<link rel="alternate" type="application/rss+xml" href="https://shop.example.test/feed/">'
            . '<link REL="Alternate canonical" href=https://shop.example.test/x/>'
            . '<meta property="og:url" content="https://shop.example.test/prodotto/libro/">'
            . '<meta property="og:image" content="https://shop.example.test/wp-content/uploads/libro.jpg">'
            . '<meta property="og:image:secure_url" content="https://shop.example.test/wp-content/uploads/libro.jpg" />'
            . '<meta name="twitter:image" content="https://shop.example.test/wp-content/uploads/libro.jpg">'
            . '<script type="application/ld+json" class="seo-schema">{"@context":"https://schema.org","@graph":[{"@type":"Product","@id":"https:\/\/shop.example.test\/prodotto\/libro\/#product","url":"https://shop.example.test/prodotto/libro/","image":"https://shop.example.test/wp-content/uploads/libro.jpg"},{"@type":"BreadcrumbList","itemListElement":[{"item":"https://shop.example.test/"}]}]}</script>'
            . "<script type='application/ld+json'>{\"@type\":\"Organization\",\"url\":\"https://shop.example.test/\"}</SCRIPT >";
        $body = '<meta name="description" content="Vedi https://shop.example.test/catalogo/">'
            . '<link rel="stylesheet" href="https://shop.example.test/wp-content/themes/t/style.css">'
            . '<link rel="preload" as="image" href="https://shop.example.test/wp-content/uploads/libro.jpg">'
            . '<a href="https://shop.example.test/carrello/">carrello</a>'
            . '<img src="https://shop.example.test/wp-content/uploads/libro.jpg">'
            . '<script>var wc={"ajax":"https:\/\/shop.example.test\/?wc-ajax=%%endpoint%%"};</script>';
        $out = sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array('<head>' . $head . '</head><body>' . $body . '</body>'));
        sb_assert(false !== strpos($out, $head), 'A canonical, alternate, shortlink, og:, twitter: or JSON-LD tag lost its absolute URL: ' . $out);
        // The description is read in search results, so it keeps its URL like the text of the page (2.4.3).
        sb_assert(false !== strpos($out, 'content="Vedi https://shop.example.test/catalogo/"'), 'The meta description lost the origin of its URL.');
        sb_assert(false !== strpos($out, 'href="/wp-content/themes/t/style.css"')
            && false !== strpos($out, '<link rel="preload" as="image" href="/wp-content/uploads/libro.jpg">'), 'A stylesheet or preload kept the absolute origin.');
        sb_assert(false !== strpos($out, '<a href="/carrello/">') && false !== strpos($out, '<img src="/wp-content/uploads/libro.jpg">')
            && false !== strpos($out, '"ajax":"\/?wc-ajax=%%endpoint%%"'), 'A content link, image or inline script URL did not become root-relative.');
        sb_assert(false === strpos($out, 'sb-keep-'), 'A placeholder of a kept tag was left in the page.');
        $plain = '<meta name="description" content="x"><link rel="stylesheet" href="https://shop.example.test/a.css">';
        sb_assert('<meta name="description" content="x"><link rel="stylesheet" href="/a.css">' === sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($plain)), 'A stylesheet link or plain meta was kept absolute.');
        // A kept tag is restored only where it was: text that looks like a placeholder is left alone.
        $backtrack_limit = ini_get('pcre.backtrack_limit');
        ini_set('pcre.backtrack_limit', '10');
        try {
            $failed = sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array('<script type="application/ld+json">' . str_repeat('{"a":"b"}', 200) . '</script><a href="https://shop.example.test/x/">x</a>'));
        } finally {
            ini_set('pcre.backtrack_limit', $backtrack_limit);
        }
        sb_assert('' === $failed, 'A page the placeholder pass could not read was written with absolute internal origins instead of being refused.');
        $lookalike = '<p>&lt;sb-keep-0000000000000000-0&gt;</p><link rel="canonical" href="https://shop.example.test/">';
        sb_assert($lookalike === sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($lookalike)), 'Text resembling a placeholder changed the page.');
    } finally {
        $GLOBALS['sb_test_home'] = $old_home;
        $GLOBALS['sb_test_site_url'] = $old_site;
    }
});

sb_test('URLs a visitor reads or copies keep the origin while URLs the browser loads or follows become portable', function () use ($plugin) {
    $old_home = $GLOBALS['sb_test_home'];
    $old_site = $GLOBALS['sb_test_site_url'];
    $GLOBALS['sb_test_home'] = 'https://news.example.test';
    $GLOBALS['sb_test_site_url'] = 'https://news.example.test';
    try {
        // Each pair: what WordPress rendered, what the static copy must hold.
        $cases = array(
            // Read or copied: text between tags, <title>, <textarea>, <code>, readable attributes, visible inputs.
            array('<title>Archivio – https://news.example.test/</title>', '<title>Archivio – https://news.example.test/</title>'),
            array('<p class="indirizzo">Indirizzo: https://news.example.test/articolo/</p>', '<p class="indirizzo">Indirizzo: https://news.example.test/articolo/</p>'),
            array('<p data-citazione>Autore, «Titolo», 21/9/2026, https://news.example.test/articolo/</p>', '<p data-citazione>Autore, «Titolo», 21/9/2026, https://news.example.test/articolo/</p>'),
            array('<pre><code>curl https://news.example.test/wp-json/ | jq</code></pre>', '<pre><code>curl https://news.example.test/wp-json/ | jq</code></pre>'),
            array('<textarea readonly>https://news.example.test/articolo/ <a href="https://news.example.test/x/">x</a></TEXTAREA >', '<textarea readonly>https://news.example.test/articolo/ <a href="https://news.example.test/x/">x</a></TEXTAREA >'),
            array('<p>3 < 4, vedi https://news.example.test/x/</p>', '<p>3 < 4, vedi https://news.example.test/x/</p>'),
            array('<a href="https://news.example.test/articolo/">https://news.example.test/articolo/</a>', '<a href="/articolo/">https://news.example.test/articolo/</a>'),
            array('<img src="https://news.example.test/a.jpg" srcset="https://news.example.test/a.jpg 1x, https://news.example.test/b.jpg 2x" alt="Copertina di https://news.example.test/articolo/" title=\'https://news.example.test/\'>',
                '<img src="/a.jpg" srcset="/a.jpg 1x, /b.jpg 2x" alt="Copertina di https://news.example.test/articolo/" title=\'https://news.example.test/\'>'),
            array('<input type="url" readonly value="https://news.example.test/articolo/" aria-label="Link: https://news.example.test/articolo/">', '<input type="url" readonly value="https://news.example.test/articolo/" aria-label="Link: https://news.example.test/articolo/">'),
            array('<input value=https://news.example.test/articolo/ placeholder="https://news.example.test/cerca/">', '<input value=https://news.example.test/articolo/ placeholder="https://news.example.test/cerca/">'),
            array('<button type="button" data-clipboard-text="https://news.example.test/articolo/" data-copy=\'https://news.example.test/\'>Copia</button>', '<button type="button" data-clipboard-text="https://news.example.test/articolo/" data-copy=\'https://news.example.test/\'>Copia</button>'),
            array('<meta name="description" content="Leggi su https://news.example.test/">', '<meta name="description" content="Leggi su https://news.example.test/">'),
            array('<meta itemprop="url" content="https://news.example.test/articolo/">', '<meta itemprop="url" content="https://news.example.test/articolo/">'),
            // Loaded or followed: unchanged from before, root-relative.
            array('<input type="hidden" name="redirect_to" value="https://news.example.test/grazie/">', '<input type="hidden" name="redirect_to" value="/grazie/">'),
            array('<INPUT TYPE=Hidden value="https://news.example.test/grazie/">', '<INPUT TYPE=Hidden value="/grazie/">'),
            array('<option value="https://news.example.test/categoria/">https://news.example.test/categoria/</option>', '<option value="/categoria/">https://news.example.test/categoria/</option>'),
            array('<div data-src="https://news.example.test/b.jpg" data-bg=\'https://news.example.test/c.jpg\' style="background:url(https://news.example.test/d.jpg)"></div>', '<div data-src="/b.jpg" data-bg=\'/c.jpg\' style="background:url(/d.jpg)"></div>'),
            array('<form action="https://news.example.test/?s="><video poster="https://news.example.test/p.jpg"></video></form>', '<form action="/?s="><video poster="/p.jpg"></video></form>'),
            array('<style>.x{background:url("https://news.example.test/s.jpg")}</style>', '<style>.x{background:url("/s.jpg")}</style>'),
            array('<script>var u="https://news.example.test/api/", j={"a":"https:\/\/news.example.test\/b\/"}; if (a<b) { t = "</p>https://news.example.test/c/"; }</script >', '<script>var u="/api/", j={"a":"\/b\/"}; if (a<b) { t = "</p>/c/"; }</script >'),
            array('<!--[if lt IE 9]><script src="https://news.example.test/ie.js"></script><![endif]-->', '<!--[if lt IE 9]><script src="/ie.js"></script><![endif]-->'),
            array('<meta http-equiv="refresh" content="5;url=https://news.example.test/nuovo/">', '<meta http-equiv="refresh" content="5;url=/nuovo/">'),
            array('<link rel="stylesheet" href="https://news.example.test/s.css"><a href="https://news.example.test/" title="Home">Home</a>', '<link rel="stylesheet" href="/s.css"><a href="/" title="Home">Home</a>'),
        );
        foreach ($cases as $case) {
            $out = sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($case[0]));
            sb_assert($case[1] === $out, 'Expected ' . $case[1] . ' but the static copy has ' . $out);
        }
        // All of it in one page, as an article renders it: the same result as piece by piece.
        $page = implode("\n", array_column($cases, 0));
        $expected = implode("\n", array_column($cases, 1));
        sb_assert($expected === sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($page)), 'The whole page did not give the same result as its pieces.');
        // The real export writer keeps the printed address and the citation.
        $stage = WP_CONTENT_DIR . '/readable-urls-fixture';
        sb_assert(wp_mkdir_p($stage), 'Could not create an isolated static-write fixture.');
        $write = sb_private($plugin, 'write_export_page', array(array('stage' => $stage), 'articolo/index.html', $page));
        sb_assert(true === $write && $expected === file_get_contents($stage . '/articolo/index.html'), 'The export writer changed what a visitor reads.');
    } finally {
        $GLOBALS['sb_test_home'] = $old_home;
        $GLOBALS['sb_test_site_url'] = $old_site;
    }
});

sb_test('Static HTML internal URLs are portable while external URLs remain absolute', function () use ($plugin) {
    $old_home = $GLOBALS['sb_test_home'];
    $old_site = $GLOBALS['sb_test_site_url'];
    $GLOBALS['sb_test_home'] = 'https://news.example.test:8443';
    $GLOBALS['sb_test_site_url'] = 'https://news.example.test:8443/wordpress';
    try {
        $html = '<a href="https://news.example.test:8443/story/?view=full#article">story</a>'
            . '<img src="//news.example.test:8443/wp-content/uploads/cover.jpg">'
            . '<a href="http://news.example.test:8443?from=home">home</a>'
            . '<script>const admin="https://news.example.test:8443/wordpress/wp-admin/";</script>'
            . '<script>{"ajax":"https:\\/\\/news.example.test:8443\\/wp-admin\\/admin-ajax.php","external":"https:\\/\\/external.example.invalid\\/path"}</script>'
            . '<a href="https://news.example.test.attacker.invalid/story/">lookalike</a>'
            . '<a href="https://external.example.invalid/story/">external</a>';
        $portable = sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($html));
        sb_assert(false !== strpos($portable, 'href="/story/?view=full#article"'), 'An internal absolute URL did not preserve its path, query and fragment.');
        sb_assert(false !== strpos($portable, 'src="/wp-content/uploads/cover.jpg"'), 'A protocol-relative internal asset URL did not become root-relative.');
        sb_assert(false !== strpos($portable, 'href="/?from=home"'), 'A root-only URL with a query did not preserve the site root.');
        sb_assert(false !== strpos($portable, '"/wordpress/wp-admin/"'), 'A same-origin WordPress subdirectory URL was not preserved as a path.');
        sb_assert(false !== strpos($portable, '"ajax":"\\/wp-admin\\/admin-ajax.php"'), 'A same-origin JSON-escaped AJAX URL did not become a portable path.');
        sb_assert(false !== strpos($portable, '"external":"https:\\/\\/external.example.invalid\\/path"'), 'A JSON-escaped external URL was rewritten.');
        sb_assert(false !== strpos($portable, 'https://news.example.test.attacker.invalid/story/'), 'A lookalike foreign hostname was rewritten.');
        sb_assert(false !== strpos($portable, 'https://external.example.invalid/story/'), 'An external URL was rewritten.');

        $stage = WP_CONTENT_DIR . '/portable-write-fixture';
        sb_assert(wp_mkdir_p($stage), 'Could not create an isolated static-write fixture.');
        $write = sb_private($plugin, 'write_export_page', array(
            array('stage' => $stage),
            'story/index.html',
            '<link rel="canonical" href="https://news.example.test:8443/story/">'
                . '<a href="https://news.example.test:8443/next/">next</a>'
                . '<a href="https://external.example.invalid/">external</a>',
        ));
        $saved_html = file_get_contents($stage . '/story/index.html');
        sb_assert(true === $write && is_string($saved_html), 'The exporter could not write a portable HTML page.');
        sb_assert(false !== strpos($saved_html, '<link rel="canonical" href="https://news.example.test:8443/story/">') && false !== strpos($saved_html, 'href="/next/"'), 'The real export write path made the canonical relative or retained the absolute origin of a content link.');
        sb_assert(false !== strpos($saved_html, 'https://external.example.invalid/'), 'The real export write path rewrote an external URL.');

        $incremental_write = sb_private($plugin, 'write_incremental_page', array(
            $stage,
            home_url('/incremental-portability-probe/'),
            '<script>{"ajax":"https:\\/\\/news.example.test:8443\\/wp-admin\\/admin-ajax.php"}</script>'
                . '<a href="https://news.example.test:8443/next/">next</a>'
                . '<a href="https://external.example.invalid/">external</a>',
        ));
        $saved_incremental = file_get_contents($stage . '/incremental-portability-probe/index.html');
        sb_assert(!is_wp_error($incremental_write) && is_string($saved_incremental), 'The incremental writer did not save its portability fixture.');
        sb_assert(false === strpos($saved_incremental, 'news.example.test')
            && false !== strpos($saved_incremental, '"ajax":"\\/wp-admin\\/admin-ajax.php"')
            && false !== strpos($saved_incremental, 'href="/next/"'), 'The incremental write path retained the local origin or failed to preserve the JSON endpoint path.');
        sb_assert(false !== strpos($saved_incremental, 'https://external.example.invalid/'), 'The incremental write path rewrote an external URL.');
    } finally {
        $GLOBALS['sb_test_home'] = $old_home;
        $GLOBALS['sb_test_site_url'] = $old_site;
    }
});

sb_test('All-in-One export omits only the duplicated current pointer', function () use ($plugin) {
    $paths = $plugin->exclude_ai1wm_current_pointer(array('cache', 'static-bridge/releases'));
    sb_assert(in_array('static-bridge/current', $paths, true), 'The release symlink was not excluded from the AIO file list.');
    sb_assert(in_array(trailingslashit(WP_CONTENT_DIR) . 'static-bridge/current', $paths, true), 'The absolute current pointer was not excluded for iterator compatibility.');
    sb_assert(in_array('static-bridge/releases', $paths, true), 'Immutable static releases were incorrectly excluded from AIO.');
});

$ai1wmPluginDirectory = getenv('STATIC_BRIDGE_AI1WM_PLUGIN_DIR');
if (is_string($ai1wmPluginDirectory) && '' !== $ai1wmPluginDirectory) {
    sb_test('Installed All-in-One iterator archives the release once and excludes current', function () use ($plugin, $ai1wmPluginDirectory) {
        $iteratorFile = rtrim($ai1wmPluginDirectory, '/\\') . '/lib/vendor/servmask/iterator/class-ai1wm-recursive-directory-iterator.php';
        $filterFile = rtrim($ai1wmPluginDirectory, '/\\') . '/lib/vendor/servmask/filter/class-ai1wm-recursive-exclude-filter.php';
        sb_assert(is_file($iteratorFile) && is_file($filterFile), 'The configured All-in-One iterator classes were not found.');
        if (!function_exists('ai1wm_replace_forward_slash_with_directory_separator')) {
            function ai1wm_replace_forward_slash_with_directory_separator($path)
            {
                return str_replace('/', DIRECTORY_SEPARATOR, (string) $path);
            }
        }
        require_once $iteratorFile;
        require_once $filterFile;

        $static_root = WP_CONTENT_DIR . '/static-bridge';
        $release_id = 'aio-real-iterator-probe';
        $release = $static_root . '/releases/' . $release_id;
        $current = $static_root . '/current';
        $old_current_target = is_link($current) ? readlink($current) : false;
        sb_assert(!file_exists($current) || is_link($current), 'The real AIO iterator probe will not replace a non-symlink current path.');
        if (is_link($current)) {
            sb_assert(@unlink($current), 'Could not isolate the existing current symlink for the real AIO iterator probe.');
        }
        sb_assert(wp_mkdir_p($release), 'Could not create the real AIO iterator release fixture.');
        sb_assert(false !== file_put_contents($release . '/index.html', 'release-page'), 'Could not write the real AIO release fixture.');
        sb_assert(false !== file_put_contents($release . '/manifest.json', '{}'), 'Could not write the real AIO manifest fixture.');
        sb_assert(@symlink('releases/' . $release_id, $current), 'Could not create the real AIO current symlink fixture.');

        $collect = function ($recursive) {
            $files = array();
            foreach ($recursive as $item) {
                if ($item->isFile()) {
                    $files[] = str_replace(DIRECTORY_SEPARATOR, '/', substr($item->getPathname(), strlen(trailingslashit(WP_CONTENT_DIR))));
                }
            }
            return $files;
        };
        try {
            $baseline = $collect(new RecursiveIteratorIterator(
                new Ai1wm_Recursive_Directory_Iterator(WP_CONTENT_DIR),
                RecursiveIteratorIterator::LEAVES_ONLY,
                RecursiveIteratorIterator::CATCH_GET_CHILD
            ));
            $filtered = new Ai1wm_Recursive_Exclude_Filter(
                new Ai1wm_Recursive_Directory_Iterator(WP_CONTENT_DIR),
                $plugin->exclude_ai1wm_current_pointer(array())
            );
            $export_files = $collect(new RecursiveIteratorIterator($filtered, RecursiveIteratorIterator::LEAVES_ONLY, RecursiveIteratorIterator::CATCH_GET_CHILD));
            sb_assert(in_array('static-bridge/releases/' . $release_id . '/index.html', $export_files, true), 'AIO would omit the immutable release HTML.');
            sb_assert(false === in_array('static-bridge/current/index.html', $export_files, true), 'AIO would duplicate the current release under the symlink path.');
            if (in_array('static-bridge/current/index.html', $baseline, true)) {
                sb_assert(false === in_array('static-bridge/current/index.html', $export_files, true), 'The current symlink was not filtered from the real AIO traversal.');
            }
        } finally {
            if (is_link($current)) {
                @unlink($current);
            }
            foreach (array('index.html', 'manifest.json') as $filename) {
                if (is_file($release . '/' . $filename) && !is_link($release . '/' . $filename)) {
                    @unlink($release . '/' . $filename);
                }
            }
            @rmdir($release);
            if (false !== $old_current_target) {
                @symlink($old_current_target, $current);
            }
        }
    });
}

sb_test('AJAX handlers enforce capability before checking nonce', function () use ($plugin) {
    $GLOBALS['sb_test_can_manage'] = false;
    $GLOBALS['sb_test_nonce_calls'] = 0;
    $caught = null;
    try {
        sb_private($plugin, 'verify_ajax_request');
    } catch (SB_Test_Response $response) {
        $caught = $response;
    }
    sb_assert($caught instanceof SB_Test_Response && 403 === $caught->status, 'Unauthorized AJAX request was not rejected with HTTP 403.');
    sb_assert(0 === $GLOBALS['sb_test_nonce_calls'], 'Nonce processing ran before the capability check.');

    $GLOBALS['sb_test_can_manage'] = true;
    $GLOBALS['sb_test_nonce_valid'] = true;
    sb_private($plugin, 'verify_ajax_request');
    sb_assert(1 === $GLOBALS['sb_test_nonce_calls'], 'Authorized AJAX request did not verify a nonce.');
});

sb_test('Admin hooks remain authenticated and protected by capability plus nonce', function () use ($source) {
    // Four public AJAX actions exist. The Fluent Forms and WooCommerce nonce refreshers read no request input and
    // return only fixed-action nonces (see their static tests). The object-cache probe (2.3.0) answers only the
    // token of a probe in progress (see the object cache tests). The background continuation of an export (2.2.14)
    // has the random per-export token, compared in constant time, as its only credential.
    preg_match_all("/add_action\\('wp_ajax_nopriv_([a-z_]+)'/", $source, $publicHooks);
    $public = $publicHooks[1];
    sort($public);
    sb_assert(array('static_bridge_object_cache_probe', 'static_bridge_public_form_nonces') === $public, 'An unexpected unauthenticated AJAX hook was registered: ' . implode(', ', $public));
    preg_match_all("/add_action\\('wp_ajax_nopriv_' \\. self::([A-Z_]+), array\\(\\\$this, '([a-z_]+)'\\)\\);/", $source, $publicConstantHooks);
    $public_constant_handlers = array_combine($publicConstantHooks[1], $publicConstantHooks[2]);
    ksort($public_constant_handlers);
    sb_assert(array('EXPORT_CONTINUE_ACTION' => 'ajax_export_continue', 'WOOCOMMERCE_NONCE_AJAX_ACTION' => 'ajax_public_woocommerce_nonces') === $public_constant_handlers
        && 4 === substr_count($source, 'wp_ajax_nopriv_'), 'An unexpected unauthenticated AJAX hook was registered.');
    $continue_body = sb_method_body($source, 'ajax_export_continue');
    sb_assert(strpos($continue_body, 'hash_equals($continue[\'token\'], $token)') < strpos($continue_body, 'run_export_queue_step'),
        'The background continuation runs before its token is checked.');
    sb_assert(false !== strpos($source, "wp_ajax_static_bridge_cancel"), 'The export cancellation AJAX handler is missing.');
    sb_assert(false !== strpos($source, "wp_ajax_static_bridge_resume"), 'The export resume AJAX handler is missing.');
    preg_match_all("/add_action\\('wp_ajax_(static_bridge_[a-z_]+)', array\\(\\\$this, '([a-z_]+)'\\)\\);/", $source, $ajaxHooks, PREG_SET_ORDER);
    sb_assert(!empty($ajaxHooks), 'No authenticated AJAX handlers were found.');
    // 2.5.0: the five actions of the full export accept static_bridge_export_capability; every other one stays manage_options.
    $export_handlers = array('ajax_start', 'ajax_tick', 'ajax_status', 'ajax_resume', 'ajax_cancel');
    foreach ($ajaxHooks as $hook) {
        if ('static_bridge_public_form_nonces' === $hook[1] && 'ajax_public_form_nonces' === $hook[2]) {
            continue;
        }
        $body = sb_method_body($source, $hook[2]);
        $guard = in_array($hook[2], $export_handlers, true) ? '$this->verify_export_ajax_request();' : '$this->verify_ajax_request();';
        sb_assert(false !== strpos($body, $guard), 'AJAX handler ' . $hook[2] . ' is missing its shared capability/nonce guard.');
    }

    preg_match_all("/add_action\\('admin_post_(static_bridge_[a-z_]+)', array\\(\\\$this, '([a-z_]+)'\\)\\);/", $source, $postHooks, PREG_SET_ORDER);
    sb_assert(15 === count($postHooks), 'Expected the fifteen authenticated admin-post handlers (2.4.0: Versioni adds three; 2.5.0: «Controlla di nuovo i link» and the notice after an update).');
    foreach ($postHooks as $hook) {
        $body = sb_method_body($source, $hook[2]);
        // 2.5.0: «Rigenera» after an update starts the full export, so it takes the export capability, as ajax_start().
        sb_assert(false !== strpos($body, "current_user_can('manage_options')")
            || false !== strpos($body, "current_user_can('edit_post'")
            || ('handle_after_update' === $hook[2] && 0 === strpos(trim(substr($body, strpos($body, '{') + 1)), 'if (!$this->can_run_exports()) {')), 'Admin-post handler ' . $hook[2] . ' is missing its capability check.');
        sb_assert(false !== strpos($body, 'check_admin_referer('), 'Admin-post handler ' . $hook[2] . ' is missing its nonce check.');
    }
    $push_body = sb_method_body($source, 'handle_post_push');
    $push_capability = strpos($push_body, "current_user_can('edit_post'");
    $push_nonce = strpos($push_body, 'check_admin_referer(');
    sb_assert(false !== $push_capability && false !== $push_nonce && $push_capability < $push_nonce, 'The contextual push must check the per-post capability before the nonce.');
});

sb_test('Rewrite rules preserve wp-admin and deny direct old-release/manifest access', function () use ($plugin) {
    $GLOBALS['sb_test_options'] = array(
        'static_bridge_settings' => array('strict_mode' => 0, 'excluded_paths' => array('/iscriviti/'), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1),
        'static_bridge_form_modes' => array(),
        'static_bridge_incremental_queue' => array(),
    );
    $rules = sb_private($plugin, 'rewrite_block');
    sb_assert(false !== strpos($rules, 'REQUEST_METHOD} ^(?:GET|HEAD)$'), 'Static routing is not limited to GET and HEAD.');
    sb_assert(false !== strpos($rules, 'wp-admin|wp-content|wp-includes|wp-json'), 'WordPress administrative/API paths are not excluded.');
    sb_assert(false !== strpos($rules, 'QUERY_STRING} ^$'), 'Query-string requests are not excluded.');
    sb_assert(false !== strpos($rules, '!^/(?:iscriviti)(?:/|$)'), 'A configured dynamic path is not excluded.');

    $archiveRules = sb_private($plugin, 'archive_protection_block');
    sb_assert(false !== strpos($archiveRules, 'RewriteRule ^wp-content/static-bridge/releases(?:/|$) - [F,END,NC]'), 'Old release directories are not denied.');
    sb_assert(false !== strpos($archiveRules, 'static-bridge/current/(?:manifest\\.json|\\.ready)'), 'Current release metadata is not denied.');
});

sb_test('Redirects of other plugins and the domains of other languages reach the Apache and Nginx rules', function () use ($plugin) {
    $GLOBALS['sb_test_options'] = array(
        'static_bridge_settings' => array('strict_mode' => 1, 'excluded_paths' => array('/iscriviti/'), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1),
        'static_bridge_form_modes' => array(),
        'static_bridge_incremental_queue' => array(),
    );
    $plain = sb_private($plugin, 'rewrite_block');
    $plainNginx = sb_private($plugin, 'nginx_router_block');
    $GLOBALS['sb_test_filter_values']['static_bridge_redirects'] = array(
        '/fr/category/contenuti/' => array('to' => home_url('/fr/category/contenus/'), 'status' => 301),
        '/fr/' => array('to' => '/', 'status' => 302),
        '/en/old-page/' => array('to' => '/en/new-page/', 'status' => 999),
        '/wp-admin/x/' => array('to' => '/', 'status' => 301),
        '/other/' => array('to' => 'https://elsewhere.example/', 'status' => 301),
        '/space here/' => array('to' => '/', 'status' => 301),
        '/same/' => array('to' => '/same/', 'status' => 301),
        '/query/' => array('to' => '/x/?a=1', 'status' => 301),
        '/iscriviti/' => array('to' => '/', 'status' => 301),
    );
    $GLOBALS['sb_test_filter_values']['static_bridge_hosts'] = array('fr' => 'fr.example.test', 'de' => 'DE.example.test:8443', 'bad' => 'not a host', 'self' => (string) wp_parse_url(home_url('/'), PHP_URL_HOST));
    try {
        $rules = sb_private($plugin, 'rewrite_block');
        $nginx = sb_private($plugin, 'nginx_router_block');
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_redirects'], $GLOBALS['sb_test_filter_values']['static_bridge_hosts']);
    }
    $redirects = array();
    foreach (sb_test_apache_rule_groups($rules) as $group) {
        if (false !== strpos($group['rule'], '[R=30')) {
            $redirects[] = $group;
        }
    }
    sb_assert(3 === count($redirects), 'Only the three valid redirects reach the Apache rules: ' . count($redirects));
    sb_assert('RewriteRule ^fr/category/contenuti/?$ /fr/category/contenus/ [R=301,NE,END]' === $redirects[0]['rule'], 'The term redirect is not a 301 to the path: ' . $redirects[0]['rule']);
    sb_assert('RewriteRule ^fr/?$ / [R=302,NE,END]' === $redirects[1]['rule'], 'A 302 is not kept as 302.');
    sb_assert('RewriteRule ^en/old\\-page/?$ /en/new-page/ [R=301,NE,END]' === $redirects[2]['rule'], 'An unknown status does not fall back to 301: ' . $redirects[2]['rule']);
    sb_assert(in_array('RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/current/fr/category/contenuti/index.html !-f', $redirects[0]['conditions'], true), 'A redirect does not give way to a page the copy has at that path.');
    sb_assert(strpos($rules, '[R=30') < strpos($rules, 'RewriteRule ^$ '), 'The redirects do not come before the copy.');
    foreach (sb_test_apache_rule_groups($rules) as $group) {
        sb_assert(in_array('RewriteCond %{HTTP_HOST} !^(?:fr\\.example\\.test|de\\.example\\.test)(?::[0-9]+)?$ [NC]', $group['conditions'], true), 'A rule serves the copy on the domain of another language: ' . $group['rule']);
    }
    sb_assert(false !== strpos($nginx, 'location = /fr/category/contenuti/ { absolute_redirect off; return 301 /fr/category/contenus/$is_args$args; }') && false !== strpos($nginx, 'location = /fr/category/contenuti { absolute_redirect off; return 301 /fr/category/contenus/$is_args$args; }'), 'The Nginx block has no exact location for the redirect, or the redirect drops the query (Apache keeps it).');
    sb_assert(false !== strpos($nginx, 'location = /fr { absolute_redirect off; return 302 /$is_args$args; }') && 0 === preg_match('~ return 30[1278] [^;$]*;~', $nginx), 'A Nginx redirect drops the query, so ?format=markdown never reaches the target page.');
    sb_assert(2 === substr_count($nginx, 'if ($host ~* "^(?:fr\\.example\\.test|de\\.example\\.test)(?::[0-9]+)?$") { return 418; }'), 'The Nginx block serves the copy on the domain of another language.');
    sb_assert(false === strpos($nginx, 'elsewhere') && false === strpos($rules, 'elsewhere') && false === strpos($rules, 'wp-admin/x') && false === strpos($rules, 'iscriviti/?$'), 'A redirect to another site or from a dynamic path went into the rules.');
    sb_assert(false === strpos($plain, 'static_bridge_redirects') && false === strpos($plain, 'HTTP_HOST') && false === strpos($plainNginx, '$host ~*') && false === strpos($plainNginx, 'return 301'), 'Without the filters the rules changed.');
});

/**
 * «Importa i redirect di…» (2.5.0): a $wpdb with the tables of Redirection and Rank Math as those plugins store them.
 * $tables: full table name => columns; $rows: 'redirection' and 'rank_math' => rows as get_results(ARRAY_A) gives
 * them; every query is kept in $queries with its SQL and arguments, and one that did not go through prepare() too.
 */
function sb_redirect_import_wpdb()
{
    return new class extends SB_Test_WPDB {
        public $tables = array();
        public $rows = array();
        public $queries = array();
        public $fail = false;
        public function suppress_errors($suppress = true) { return false; }
        private function resolve($prepared)
        {
            $query = isset($GLOBALS['sb_test_export_queue_prepared'][$prepared]) ? $GLOBALS['sb_test_export_queue_prepared'][$prepared] : array('UNPREPARED ' . (string) $prepared, array());
            $this->queries[] = $query;
            return $query;
        }
        public function get_col($prepared)
        {
            list($sql, $args) = $this->resolve($prepared);
            if (false === strpos($sql, 'information_schema.COLUMNS')) {
                return parent::get_col($prepared);
            }
            return isset($this->tables[$args[0]]) ? $this->tables[$args[0]] : array();
        }
        public function get_results($prepared, $output = null)
        {
            list($sql, $args) = $this->resolve($prepared);
            foreach (array('redirection_items' => 'redirection', 'rank_math_redirections' => 'rank_math') as $table => $source) {
                if (false !== strpos($sql, $table)) {
                    return $this->fail ? null : (isset($this->rows[$source]) ? $this->rows[$source] : array());
                }
            }
            return parent::get_results($prepared, $output);
        }
    };
}

