sb_test('Deactivation removes static routing but retains archive privacy rules', function () use ($plugin) {
    if (!is_dir(ABSPATH) && !mkdir(ABSPATH, 0775, true) && !is_dir(ABSPATH)) {
        throw new RuntimeException('Could not create the private test WordPress directory.');
    }
    $htaccess = ABSPATH . '.htaccess';
    file_put_contents($htaccess, "# BEGIN WordPress\nRewriteEngine On\n# END WordPress\n");
    $retainedRelease = WP_CONTENT_DIR . '/static-bridge/releases/retained-release';
    if (!is_dir($retainedRelease) && !mkdir($retainedRelease, 0775, true) && !is_dir($retainedRelease)) {
        throw new RuntimeException('Could not create the private retained-release fixture.');
    }
    file_put_contents($retainedRelease . '/index.html', '<!doctype html>');
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not write activation rules to the isolated fixture.');
    $active = file_get_contents($htaccess);
    sb_assert(false !== strpos($active, '# BEGIN Static Bridge'), 'Static routing block was not installed.');
    sb_assert(false !== strpos($active, '# BEGIN Static Bridge Archive Protection'), 'Archive protection was not installed.');

    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(false)), 'Could not write deactivation rules to the isolated fixture.');
    $inactive = file_get_contents($htaccess);
    sb_assert(false === strpos($inactive, "# BEGIN Static Bridge\n"), 'Static routing remained active after deactivation.');
    sb_assert(false !== strpos($inactive, '# BEGIN Static Bridge Archive Protection'), 'Archive protection was removed along with static routing.');
});

sb_test('Rewrite-rule writer refuses a symlinked .htaccess without modifying its target', function () use ($plugin, $fixtureRoot) {
    $htaccess = ABSPATH . '.htaccess';
    $target = $fixtureRoot . '/external-htaccess-sentinel.txt';
    if (file_exists($htaccess) || is_link($htaccess)) {
        unlink($htaccess);
    }
    sb_assert(false !== file_put_contents($target, 'preserve this external file'), 'Could not create an external .htaccess sentinel.');
    sb_assert(symlink($target, $htaccess), 'Could not create the isolated .htaccess symlink.');
    $updated = sb_private($plugin, 'write_rewrite_rules', array(true));
    sb_assert(false === $updated, 'The rewrite writer accepted a symlinked .htaccess.');
    sb_assert('preserve this external file' === file_get_contents($target), 'The symlink target was modified.');
    unlink($htaccess);
});

function sb_test_apache_rule_groups($rules)
{
    // A RewriteCond binds only to the next RewriteRule: group each rule with its own conditions.
    $groups = array();
    $conditions = array();
    foreach (preg_split('/\R/', (string) $rules) as $line) {
        $line = trim($line);
        if (0 === strpos($line, 'RewriteCond ')) {
            $conditions[] = $line;
        } elseif (0 === strpos($line, 'RewriteRule ')) {
            $groups[] = array('rule' => $line, 'conditions' => $conditions);
            $conditions = array();
        }
    }
    return $groups;
}

function sb_test_apache_rule_matches($rule, $path)
{
    if (!preg_match('/^RewriteRule\s+(\S+)\s+(\S+)(?:\s+\[([^\]]*)\])?$/', $rule, $parts)) {
        return false;
    }
    $flags = isset($parts[3]) ? array_map('trim', explode(',', strtoupper($parts[3]))) : array();
    return 1 === preg_match('~' . str_replace('~', '\\~', $parts[1]) . '~' . (in_array('NC', $flags, true) ? 'i' : ''), $path);
}

sb_test('Every Apache rule that serves or 404s a static route carries the full routing guard', function () use ($plugin) {
    $GLOBALS['sb_test_options'] = array(
        'static_bridge_settings' => array('strict_mode' => 1, 'excluded_paths' => array('/iscriviti/', '/contatti/'), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1),
        'static_bridge_form_modes' => array(),
        // A queued homepage deletion is the only way "/" becomes dynamic.
        'static_bridge_incremental_queue' => array(array('url' => home_url('/'), 'action' => 'delete')),
    );
    $required = array(
        'routing marker' => '%{DOCUMENT_ROOT}/wp-content/static-bridge/.enabled -f',
        'GET/HEAD only' => 'RewriteCond %{REQUEST_METHOD} ^(?:GET|HEAD)$',
        'session cookies (Nginx parity)' => 'RewriteCond %{HTTP_COOKIE} !(?:wordpress_logged_in_|comment_author_|wp-postpass_|woocommerce_items_in_cart|woocommerce_cart_hash|wp_woocommerce_session_) [NC]',
        'empty query string' => 'RewriteCond %{QUERY_STRING} ^$',
        'WordPress paths' => 'wp-admin|wp-content|wp-includes|wp-json',
        'WordPress entry points' => 'wp-login|wp-cron|wp-comments-post',
        'sitemaps/robots' => 'sitemap[^/]*',
        'feeds' => 'comments/feed',
        'short feeds' => 'RewriteCond %{REQUEST_URI} !^/(?:.+/)?(?:rss|rss2|atom|rdf)/?$ [NC]',
        'search' => 'RewriteCond %{REQUEST_URI} !^/search(?:/|$) [NC]',
        'configured dynamic paths' => 'RewriteCond %{REQUEST_URI} !^/(?:iscriviti|contatti)(?:/|$) [NC]',
        'queued homepage deletion' => 'RewriteCond %{REQUEST_URI} !^/$',
    );
    $serving = 0;
    $strict = 0;
    foreach (sb_test_apache_rule_groups(sb_private($plugin, 'rewrite_block')) as $group) {
        $is_serving = false !== strpos($group['rule'], 'wp-content/static-bridge/current/');
        $is_strict = false !== strpos($group['rule'], 'R=404');
        if (!$is_serving && !$is_strict) {
            continue;
        }
        $serving += $is_serving ? 1 : 0;
        $strict += $is_strict ? 1 : 0;
        $conditions = implode("\n", $group['conditions']);
        $missing = array();
        foreach ($required as $label => $fragment) {
            if (false === strpos($conditions, $fragment)) {
                $missing[] = $label;
            }
        }
        sb_assert(empty($missing), 'Apache rule "' . $group['rule'] . '" is not guarded by: ' . implode(', ', $missing) . '.');
    }
    sb_assert($serving >= 2 && 1 === $strict, 'The Apache block no longer contains the expected homepage, route and strict rules.');
});

sb_test('Apache archive protection denies the whole Static Bridge tree by direct URL', function () use ($plugin) {
    $deny_rules = array();
    foreach (sb_test_apache_rule_groups(sb_private($plugin, 'archive_protection_block')) as $group) {
        if (empty($group['conditions']) && preg_match('/\s-\s\[[^\]]*\bF\b[^\]]*\bEND\b/', $group['rule'])) {
            $deny_rules[] = $group['rule'];
        }
    }
    foreach (array('wp-content/static-bridge', 'wp-content/static-bridge/', 'wp-content/static-bridge/.enabled', 'wp-content/static-bridge/.strict',
        'wp-content/static-bridge/current/', 'wp-content/static-bridge/current/index.html', 'wp-content/static-bridge/current/news/index.html',
        'wp-content/static-bridge/current/manifest.json', 'wp-content/static-bridge/releases/r1/news/index.html', 'WP-CONTENT/Static-Bridge/current/news/index.html') as $path) {
        $denied = false;
        foreach ($deny_rules as $rule) {
            $denied = $denied || sb_test_apache_rule_matches($rule, $path);
        }
        sb_assert($denied, 'Apache does not deny direct access to /' . $path . '.');
    }
    foreach (array('wp-content/uploads/a.jpg', 'wp-content/static-bridge-other/x', 'news/') as $path) {
        foreach ($deny_rules as $rule) {
            sb_assert(!sb_test_apache_rule_matches($rule, $path), 'Apache archive protection also denies an unrelated path: /' . $path . '.');
        }
    }
});

sb_test('Rewriting .htaccess is idempotent and keeps foreign rules byte-for-byte', function () use ($plugin) {
    $htaccess = ABSPATH . '.htaccess';
    if (file_exists($htaccess) || is_link($htaccess)) {
        unlink($htaccess);
    }
    $retainedRelease = WP_CONTENT_DIR . '/static-bridge/releases/retained-release';
    if (!is_dir($retainedRelease) && !mkdir($retainedRelease, 0775, true) && !is_dir($retainedRelease)) {
        throw new RuntimeException('Could not create the private retained-release fixture.');
    }
    $foreign_top = "# Host rules\nOptions -Indexes\n\n";
    $wordpress = "# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n\n# Trailing host rule\n";
    file_put_contents($htaccess, $foreign_top . $wordpress);
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not write activation rules to the isolated fixture.');
    $active = file_get_contents($htaccess);
    for ($i = 0; $i < 5; $i++) {
        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not rewrite activation rules.');
    }
    sb_assert(file_get_contents($htaccess) === $active, 'Repeated publications change .htaccess (' . strlen($active) . ' -> ' . strlen((string) file_get_contents($htaccess)) . ' bytes).');
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(false)), 'Could not write deactivation rules.');
    $inactive = file_get_contents($htaccess);
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(false)), 'Could not rewrite deactivation rules.');
    sb_assert(file_get_contents($htaccess) === $inactive, 'Repeated deactivation changes .htaccess.');
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not reactivate the rules.');
    sb_assert(file_get_contents($htaccess) === $active, 'Deactivate/reactivate does not restore the same .htaccess.');
    sb_assert(0 === strpos($active, $foreign_top) && false !== strpos($active, $wordpress) && strpos($active, '# BEGIN Static Bridge') < strpos($active, '# BEGIN WordPress'), 'Foreign or WordPress rules were not preserved around the Static Bridge block.');
    sb_assert(false === strpos($active, "\n\n\n"), 'The Static Bridge blocks leave runs of blank lines in .htaccess.');
    unlink($htaccess);
});

sb_test('Upgrading a pre-2.0.14 .htaccess replaces the old Apache blocks and drops accumulated blank lines', function () use ($plugin) {
    $htaccess = ABSPATH . '.htaccess';
    if (file_exists($htaccess) || is_link($htaccess)) {
        unlink($htaccess);
    }
    $legacy_archive = "# BEGIN Static Bridge Archive Protection\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteRule ^wp-content/static-bridge/releases(?:/|$) - [F,END,NC]\n</IfModule>\n# END Static Bridge Archive Protection";
    $legacy_routing = "# BEGIN Static Bridge\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteCond %{QUERY_STRING} ^$\nRewriteRule ^$ wp-content/static-bridge/current/index.html [END]\nRewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/current/$1/index.html -f\nRewriteRule ^(.+?)/?$ wp-content/static-bridge/current/$1/index.html [END]\n</IfModule>\n# END Static Bridge";
    $wordpress = "# BEGIN WordPress\nRewriteEngine On\n# END WordPress\n";
    file_put_contents($htaccess, "# Host rules\n" . str_repeat("\n", 40) . $legacy_archive . "\n\n" . $legacy_routing . str_repeat("\n", 12) . $wordpress);
    sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not rewrite a legacy .htaccess.');
    $upgraded = file_get_contents($htaccess);
    sb_assert(1 === substr_count($upgraded, "# BEGIN Static Bridge\n") && 1 === substr_count($upgraded, '# BEGIN Static Bridge Archive Protection'), 'The legacy Static Bridge blocks were duplicated instead of replaced.');
    sb_assert(false === strpos($upgraded, "RewriteCond %{QUERY_STRING} ^$\nRewriteRule ^$"), 'Legacy rules survived the upgrade.');
    sb_assert(false === strpos($upgraded, "\n\n\n") && 0 === strpos($upgraded, "# Host rules\n\n# BEGIN Static Bridge Archive Protection") && false !== strpos($upgraded, $wordpress), 'The upgraded .htaccess kept accumulated blank lines or lost foreign rules.');
    unlink($htaccess);
});

sb_test('Local Apache serves a release only to anonymous GET/HEAD and denies the Static Bridge tree', function () use ($plugin, $fixtureRoot) {
    $httpd = getenv('STATIC_BRIDGE_APACHE_BIN');
    if (!$httpd || !is_executable($httpd) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN to run this HTTP routing check.');
    }
    if (!function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('The HTTP routing check requires PHP 8.4 or newer.');
    }
    $apache_root = dirname(dirname($httpd));
    $modules = $apache_root . '/modules';
    foreach (array('rewrite', 'headers', 'authz_core', 'dir', 'mime', 'unixd', 'log_config') as $module) {
        if (!is_file($modules . '/mod_' . $module . '.so')) {
            throw new SB_Test_Skip('Apache module mod_' . $module . ' is not available next to STATIC_BRIDGE_APACHE_BIN.');
        }
    }
    // With mod_include the fixture also applies INCLUDES to .html, as some hosts do (hardening note 36).
    $with_include = is_file($modules . '/mod_include.so');
    $socket = stream_socket_server('tcp://127.0.0.1:0', $socket_error, $socket_message);
    if (false === $socket) {
        throw new RuntimeException('Could not reserve a local Apache test port: ' . $socket_message);
    }
    $port = (int) substr(strrchr((string) stream_socket_get_name($socket, false), ':'), 1);
    fclose($socket);
    sb_assert($port > 0, 'Could not determine the temporary Apache test port.');

    $previous_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 0,
        'excluded_paths' => array('/iscriviti/', '/contatti/'),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();

    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $probe_release_id = 'apache-route-probe-' . bin2hex(random_bytes(6));
    $release = $static_root . '/releases/' . $probe_release_id;
    $current_path = $static_root . '/current';
    $current_backup = $static_root . '/.qa-current-backup-' . $probe_release_id;
    $enabled_path = $static_root . '/.enabled';
    $enabled_backup = $static_root . '/.qa-enabled-backup-' . $probe_release_id;
    $strict_path = $static_root . '/.strict';
    $strict_backup = $static_root . '/.qa-strict-backup-' . $probe_release_id;
    $htaccess = ABSPATH . '.htaccess';
    $htaccess_backup = ABSPATH . '.htaccess.qa-backup-' . $probe_release_id;
    $fallback = ABSPATH . 'index.php';
    $ssi_control = ABSPATH . 'ssi-control.html';
    $server_root = $fixtureRoot . '/apache-http';
    $config_path = $server_root . '/httpd.conf';
    $log_path = $server_root . '/error.log';
    $moved = array();
    $process = null;
    try {
        foreach (array($current_path => $current_backup, $enabled_path => $enabled_backup, $strict_path => $strict_backup, $htaccess => $htaccess_backup) as $path => $backup) {
            if (file_exists($path) || is_link($path)) {
                sb_assert(!file_exists($backup) && !is_link($backup) && @rename($path, $backup), 'Could not preserve ' . basename($path) . ' for the isolated Apache fixture.');
                $moved[$path] = $backup;
            }
        }
        sb_assert(!file_exists($htaccess) && !is_link($htaccess) && !file_exists($fallback) && !file_exists($ssi_control), 'An unexpected .htaccess, index.php or ssi-control.html blocks the isolated Apache fixture.');
        foreach (array('', '/hello-world', '/iscriviti', '/ssi-probe') as $directory) {
            sb_assert(wp_mkdir_p($release . $directory), 'Could not create the isolated Apache release fixture.');
        }
        file_put_contents($release . '/index.html', 'STATIC_HOME');
        file_put_contents($release . '/hello-world/index.html', 'STATIC_HELLO');
        file_put_contents($release . '/iscriviti/index.html', 'STATIC_EXCLUDED_FORM');
        file_put_contents($release . '/ssi-probe/index.html', 'STATIC_SSI[<!--#echo var="DOCUMENT_NAME" -->]');
        file_put_contents($ssi_control, 'CONTROL[<!--#echo var="DOCUMENT_NAME" -->]');
        file_put_contents($release . '/manifest.json', '{"release":"apache-route-probe"}');
        sb_assert(symlink('releases/' . $probe_release_id, $current_path), 'Could not link the isolated current release.');
        file_put_contents($enabled_path, "enabled\n");
        // WordPress's own block; index.php stands in for WordPress (no PHP handler in this fixture).
        file_put_contents($fallback, 'WORDPRESS_FALLBACK');
        file_put_contents($htaccess, "# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n");
        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not write the Static Bridge .htaccess block.');
        sb_assert(wp_mkdir_p($server_root), 'Could not create the isolated Apache server root.');
        $load = '';
        foreach (array_merge(array('authz_core', 'dir', 'mime', 'rewrite', 'headers', 'unixd', 'log_config'), $with_include ? array('include') : array()) as $module) {
            $load .= 'LoadModule ' . $module . '_module "' . $modules . '/mod_' . $module . ".so\"\n";
        }
        $docroot = rtrim(ABSPATH, '/');
        $config = 'ServerRoot "' . $server_root . "\"\n" . 'Listen 127.0.0.1:' . $port . "\nServerName 127.0.0.1\n"
            . 'PidFile "' . $server_root . "/httpd.pid\"\n" . 'DefaultRuntimeDir "' . $server_root . "\"\n" . 'Mutex file:' . $server_root . " default\n"
            . 'ErrorLog "' . $log_path . "\"\nLogLevel warn\n" . $load
            . "TypesConfig /dev/null\nAddType text/html .html\nAddType text/plain .php .json\nDirectoryIndex index.html index.php\nAccessFileName .htaccess\n"
            . ($with_include ? "AddOutputFilter INCLUDES .html\n" : '')
            . "<Directory />\n Options FollowSymLinks\n AllowOverride None\n Require all denied\n</Directory>\n"
            . 'DocumentRoot "' . $docroot . "\"\n"
            . '<Directory "' . $docroot . "\">\n Options Indexes FollowSymLinks" . ($with_include ? ' Includes' : '') . "\n AllowOverride All\n Require all granted\n Header always set X-Fixture-Handler wordpress\n</Directory>\n"
            . '<Directory "' . $docroot . "/wp-content/static-bridge\">\n Header always set X-Fixture-Handler static-file\n</Directory>\n";
        sb_assert(false !== file_put_contents($config_path, $config), 'Could not write the isolated Apache configuration.');
        $environment = array('PATH' => (string) getenv('PATH'));
        if (is_dir($apache_root . '/shared-libs')) {
            $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
        }
        $descriptors = array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a'));
        $process = proc_open(array($httpd, '-f', $config_path, '-DFOREGROUND'), $descriptors, $pipes, $server_root, $environment);
        sb_assert(is_resource($process), 'Could not start the isolated Local Apache server.');

        $request = function ($path, $method = 'GET', array $headers = array()) use ($port) {
            $context = stream_context_create(array('http' => array('method' => $method, 'header' => implode("\r\n", $headers), 'content' => 'POST' === $method ? 'qa=1' : '', 'ignore_errors' => true, 'follow_location' => 0, 'timeout' => 3)));
            $body = @file_get_contents('http://127.0.0.1:' . $port . $path, false, $context);
            $status = 0;
            $handler = '';
            foreach ((array) http_get_last_response_headers() as $index => $header) {
                if (0 === $index && preg_match('/^HTTP\/\S+\s+(\d+)/', $header, $match)) {
                    $status = (int) $match[1];
                } elseif (0 === stripos($header, 'X-Fixture-Handler:')) {
                    $handler = trim(substr($header, strlen('X-Fixture-Handler:')));
                }
            }
            return array('status' => $status, 'handler' => $handler, 'body' => false === $body ? '' : $body);
        };
        $deadline = microtime(true) + 5;
        do {
            $home = $request('/');
            if (200 === $home['status']) {
                break;
            }
            usleep(100000);
        } while (microtime(true) < $deadline);

        $failures = array();
        $static = function ($label, $response, $body) use (&$failures) {
            if (!(200 === $response['status'] && 'static-file' === $response['handler'] && $body === $response['body'])) {
                $failures[] = $label . ' was not served from the release ' . json_encode($response);
            }
        };
        // WordPress fallback: index.php served as a file (405 for POST, since the fixture has no PHP handler).
        $dynamic = function ($label, $response) use (&$failures) {
            if (!('wordpress' === $response['handler'] && ('WORDPRESS_FALLBACK' === $response['body'] || (0 === strpos($label, 'POST') && 405 === $response['status'])))) {
                $failures[] = $label . ' did not reach WordPress ' . json_encode($response);
            }
        };
        $static('Anonymous GET /', $home, 'STATIC_HOME');
        $static('Anonymous GET /hello-world/', $request('/hello-world/'), 'STATIC_HELLO');
        $static('Anonymous HEAD /hello-world/', $request('/hello-world/', 'HEAD'), '');
        foreach (array('/' => 'homepage', '/hello-world/' => 'route') as $path => $label) {
            $dynamic('Query-string request to the ' . $label, $request($path . '?utm_source=qa'));
            $dynamic('Preview of the ' . $label, $request($path . '?preview=true'));
            $dynamic('POST to the ' . $label, $request($path, 'POST', array('Content-Type: application/x-www-form-urlencoded')));
            foreach (array('wordpress_logged_in_qa=1', 'comment_author_qa=1', 'woocommerce_items_in_cart=1') as $cookie) {
                $dynamic($cookie . ' request to the ' . $label, $request($path, 'GET', array('Cookie: ' . $cookie)));
            }
        }
        $dynamic('Configured dynamic path with a release file', $request('/iscriviti/'));
        if ($with_include) {
            // The control proves mod_include runs on this server; the static copy must reach visitors as written.
            $control = $request('/ssi-control.html');
            if ('CONTROL[ssi-control.html]' !== $control['body']) {
                $failures[] = 'mod_include did not process the control page outside Static Bridge, the SSI check proves nothing ' . json_encode($control);
            }
            $static('SSI directive in a static copy', $request('/ssi-probe/'), 'STATIC_SSI[<!--#echo var="DOCUMENT_NAME" -->]');
        }
        foreach (array('/wp-content/static-bridge/', '/wp-content/static-bridge/.enabled', '/wp-content/static-bridge/current/', '/wp-content/static-bridge/current/hello-world/index.html',
            '/wp-content/static-bridge/current/manifest.json', '/wp-content/static-bridge/releases/' . $probe_release_id . '/hello-world/index.html') as $private) {
            $response = $request($private);
            if (!(403 === $response['status'] && false === strpos($response['body'], 'STATIC_') && false === strpos($response['body'], 'apache-route-probe'))) {
                $failures[] = 'Direct URL ' . $private . ' was not denied ' . json_encode(array('status' => $response['status'], 'handler' => $response['handler']));
            }
        }

        // A post queued for deletion (unpublished/trashed) must leave static routing at once.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(array('url' => home_url('/hello-world/'), 'action' => 'delete'));
        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not rewrite the rules for the queued deletion.');
        $dynamic('Route queued for deletion', $request('/hello-world/'));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not restore the rules after the queued deletion.');

        file_put_contents($strict_path, '');
        $missing = $request('/non-esportato/');
        if (!(404 === $missing['status'] && false === strpos($missing['body'], 'WORDPRESS_FALLBACK'))) {
            $failures[] = 'Strict mode did not answer 404 for a missing public page ' . json_encode($missing);
        }
        $dynamic('Strict mode with a query string', $request('/non-esportato/?s=qa'));
        // «Versione Markdown delle pagine» (2.5.0): ?format=markdown reaches WP with the copy and Strict on, no new rule.
        $dynamic('Markdown version of a route with a copy, Strict on', $request('/hello-world/?format=markdown'));
        $dynamic('Markdown version of the homepage, Strict on', $request('/?format=markdown'));
        $dynamic('Markdown version of a route without a copy, Strict on', $request('/non-esportato/?format=markdown'));
        $markdown_head = $request('/hello-world/?format=markdown', 'HEAD');
        if ('wordpress' !== $markdown_head['handler']) {
            $failures[] = 'HEAD of the Markdown version did not reach WordPress ' . json_encode($markdown_head);
        }
        $static('Strict mode on a published route', $request('/hello-world/'), 'STATIC_HELLO');
        @unlink($enabled_path);
        $dynamic('Route after the routing marker is removed', $request('/hello-world/'));
        $dynamic('Homepage after the routing marker is removed', $request('/'));
        $dynamic('Strict 404 after the routing marker is removed', $request('/non-esportato/'));
        @unlink($strict_path);

        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(false)), 'Could not write the deactivation .htaccess.');
        file_put_contents($enabled_path, "enabled\n");
        $dynamic('Route after deactivation', $request('/hello-world/'));
        $after = $request('/wp-content/static-bridge/current/hello-world/index.html');
        if (403 !== $after['status']) {
            $failures[] = 'After deactivation the last release is still readable by direct URL ' . json_encode($after);
        }
        sb_assert(empty($failures), count($failures) . " Apache routing failure(s):\n  - " . implode("\n  - ", $failures));
    } finally {
        if (is_resource($process)) {
            proc_terminate($process, 15);
            proc_close($process);
        }
        if (null === $previous_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $previous_server_software;
        }
        @unlink($htaccess);
        @unlink($fallback);
        @unlink($ssi_control);
        if (is_link($current_path) && readlink($current_path) === 'releases/' . $probe_release_id) {
            @unlink($current_path);
        }
        // Any marker present now was created by this test: pre-existing ones were moved aside.
        foreach (array($enabled_path, $strict_path) as $marker) {
            if (is_file($marker) && !is_link($marker)) {
                @unlink($marker);
            }
        }
        foreach ($moved as $path => $backup) {
            if (!file_exists($path) && !is_link($path)) {
                @rename($backup, $path);
            }
        }
    }
});

sb_test('Internal rendering leaves the static file and Strict in place when the server honours the bypass guard', function () use ($plugin) {
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $releases = $static_root . '/releases';
    sb_assert(!is_link($static_root) && (is_dir($releases) || wp_mkdir_p($releases)), 'Could not prepare the isolated in-place render fixture.');
    $current = $static_root . '/current';
    sb_assert(!file_exists($current) || is_link($current), 'The current release fixture is not a symlink and cannot be safely replaced.');
    $old_current_target = is_link($current) ? readlink($current) : false;
    $release_id = 'render-in-place-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $releases . '/' . $release_id;
    $routes = array('/', '/sb-in-place-' . bin2hex(random_bytes(4)) . '/');
    $files = array();
    foreach ($routes as $route) {
        $files[$route] = $release . ('/' === $route ? '' : '/' . trim($route, '/')) . '/index.html';
        sb_assert(wp_mkdir_p(dirname($files[$route])) && false !== file_put_contents($files[$route], '<html>STATIC ' . $route . '</html>'), 'Could not seed the in-place render fixture.');
    }
    $enabled = $static_root . '/.enabled';
    $strict = $static_root . '/.strict';
    $old_enabled = is_file($enabled) ? file_get_contents($enabled) : false;
    $old_strict = is_file($strict) ? file_get_contents($strict) : false;
    sb_assert(!is_link($enabled) && !is_link($strict), 'A routing marker fixture is a symlink.');
    $observed = array();
    try {
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not activate the in-place render release.');
        file_put_contents($enabled, "enabled\n");
        file_put_contents($strict, 'strict');
        $GLOBALS['sb_test_http_calls'] = array();
        // Returning null keeps the default stub, which answers as WordPress with the render proof:
        // this is what the plugin's Nginx block and the 2.0.14 .htaccess do for the guarded request.
        $GLOBALS['sb_test_http_callback'] = function ($request_url) use (&$observed, $files, $enabled, $strict) {
            $path = (string) wp_parse_url($request_url, PHP_URL_PATH);
            $route = '' === $path ? '/' : $path;
            $observed[] = array(
                'route' => $route,
                'file' => isset($files[$route]) && is_file($files[$route]) && '<html>STATIC ' . $route . '</html>' === file_get_contents($files[$route]),
                'enabled' => is_file($enabled),
                'strict' => is_file($strict) && 'strict' === file_get_contents($strict),
                'leftovers' => count((array) glob(dirname(isset($files[$route]) ? $files[$route] : $request_url) . '/*.sb-render-*')),
            );
            return null;
        };
        foreach ($routes as $route) {
            $GLOBALS['sb_test_http_responses'][home_url($route) . '?static_bridge_bypass=1'] = array(
                'response' => array('code' => 200),
                'headers' => array('Content-Type' => 'text/html'),
                'body' => '<html>WORDPRESS ' . $route . '</html>',
            );
        }
        $single = sb_private($plugin, 'fetch_page', array(home_url($routes[1]), 10));
        sb_assert(!is_wp_error($single) && false !== strpos($single['body'], 'WORDPRESS ' . $routes[1]), 'The guarded render did not return the WordPress page: ' . (is_wp_error($single) ? $single->get_error_message() : $single['body']));
        $batch = sb_private($plugin, 'fetch_pages', array(array(home_url($routes[0]), home_url($routes[1]))));
        foreach ($routes as $route) {
            $result = isset($batch[home_url($route)]) ? $batch[home_url($route)] : null;
            sb_assert(is_array($result) && false !== strpos($result['body'], 'WORDPRESS ' . $route), 'The guarded batch render did not return WordPress for ' . $route . '.');
        }
        sb_assert(3 === count($observed), 'A guarded render that WordPress answered was repeated: ' . count($observed) . ' requests for 3 routes.');
        foreach ($observed as $observation) {
            sb_assert($observation['file'] && $observation['enabled'] && $observation['strict'] && 0 === $observation['leftovers'], 'A file the server may be serving was moved or a marker lifted during the render: ' . json_encode($observation));
        }
        foreach ($files as $route => $file) {
            sb_assert('<html>STATIC ' . $route . '</html>' === file_get_contents($file), 'The static file of ' . $route . ' changed during an in-place render.');
        }
        sb_assert('strict' === file_get_contents($strict) && "enabled\n" === file_get_contents($enabled), 'Routing markers changed during an in-place render.');
        sb_assert(false === get_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION, false), 'The in-place render left a transaction record behind.');

        $token = str_repeat('ab', 24);
        $missed = function ($code, array $headers = array(), $body = '') use ($plugin, $token) {
            return sb_private($plugin, 'render_missed_wordpress', array(array('response' => array('code' => $code), 'headers' => $headers, 'body' => $body), $token));
        };
        sb_assert($missed(200) && $missed(404) && $missed(200, array('X-Static-Bridge-Render' => str_repeat('cd', 24))), 'A static page, a static Strict 404 or a foreign token was not retried with the route suspended.');
        sb_assert(!$missed(200, array('x-static-bridge-render' => $token)) && !$missed(404, array('X-Static-Bridge-Render' => $token))
            && !$missed(200, array(), '<html></html><!--static-bridge-render:' . $token . '-->'), 'A response proven to come from WordPress was retried.');
        sb_assert(!$missed(301) && !$missed(403) && !$missed(503) && !sb_private($plugin, 'render_missed_wordpress', array(new WP_Error('http', 'down'), $token)), 'A redirect, a denial, a server error or a transport error triggered the move-aside fallback.');
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        foreach ($routes as $route) {
            unset($GLOBALS['sb_test_http_responses'][home_url($route) . '?static_bridge_bypass=1']);
        }
        delete_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION);
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array($enabled => $old_enabled, $strict => $old_strict) as $path => $contents) {
            if (false === $contents) {
                @unlink($path);
            } else {
                file_put_contents($path, $contents);
            }
        }
        if (is_dir($release)) {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
            foreach ($iterator as $entry) {
                $entry->isDir() && !$entry->isLink() ? @rmdir($entry->getPathname()) : @unlink($entry->getPathname());
            }
            @rmdir($release);
        }
    }
});

sb_test('Local Apache keeps answering anonymous readers from the release while a route is re-rendered', function () use ($plugin, $fixtureRoot) {
    $httpd = getenv('STATIC_BRIDGE_APACHE_BIN');
    if (!$httpd || !is_executable($httpd) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN to run this HTTP render-window check.');
    }
    if (!function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('The HTTP render-window check requires PHP 8.4 or newer.');
    }
    $apache_root = dirname(dirname($httpd));
    $modules = $apache_root . '/modules';
    foreach (array('rewrite', 'headers', 'authz_core', 'dir', 'mime', 'unixd', 'log_config') as $module) {
        if (!is_file($modules . '/mod_' . $module . '.so')) {
            throw new SB_Test_Skip('Apache module mod_' . $module . ' is not available next to STATIC_BRIDGE_APACHE_BIN.');
        }
    }
    $socket = stream_socket_server('tcp://127.0.0.1:0', $socket_error, $socket_message);
    if (false === $socket) {
        throw new RuntimeException('Could not reserve a local Apache test port: ' . $socket_message);
    }
    $port = (int) substr(strrchr((string) stream_socket_get_name($socket, false), ':'), 1);
    fclose($socket);
    sb_assert($port > 0, 'Could not determine the temporary Apache test port.');

    $previous_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 1,
        'excluded_paths' => array(),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();

    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $probe_release_id = 'apache-render-window-' . bin2hex(random_bytes(6));
    $release = $static_root . '/releases/' . $probe_release_id;
    $current_path = $static_root . '/current';
    $current_backup = $static_root . '/.qa-current-backup-' . $probe_release_id;
    $enabled_path = $static_root . '/.enabled';
    $enabled_backup = $static_root . '/.qa-enabled-backup-' . $probe_release_id;
    $strict_path = $static_root . '/.strict';
    $strict_backup = $static_root . '/.qa-strict-backup-' . $probe_release_id;
    $htaccess = ABSPATH . '.htaccess';
    $htaccess_backup = ABSPATH . '.htaccess.qa-backup-' . $probe_release_id;
    $fallback = ABSPATH . 'index.php';
    $server_root = $fixtureRoot . '/apache-render-window';
    $config_path = $server_root . '/httpd.conf';
    $log_path = $server_root . '/error.log';
    $reader_stop = $server_root . '/readers.stop';
    $reader_report = $server_root . '/readers.json';
    $moved = array();
    $process = null;
    $reader = null;
    try {
        foreach (array($current_path => $current_backup, $enabled_path => $enabled_backup, $strict_path => $strict_backup, $htaccess => $htaccess_backup) as $path => $backup) {
            if (file_exists($path) || is_link($path)) {
                sb_assert(!file_exists($backup) && !is_link($backup) && @rename($path, $backup), 'Could not preserve ' . basename($path) . ' for the isolated Apache fixture.');
                $moved[$path] = $backup;
            }
        }
        sb_assert(!file_exists($htaccess) && !is_link($htaccess) && !file_exists($fallback), 'An unexpected .htaccess or index.php blocks the isolated Apache fixture.');
        $pages = array('/' => 'STATIC_HOME', '/hello-world/' => 'STATIC_HELLO');
        $files = array();
        foreach ($pages as $route => $body) {
            $files[$route] = $release . ('/' === $route ? '' : '/' . trim($route, '/')) . '/index.html';
            sb_assert(wp_mkdir_p(dirname($files[$route])) && false !== file_put_contents($files[$route], $body), 'Could not create the isolated Apache release fixture.');
        }
        sb_assert(symlink('releases/' . $probe_release_id, $current_path), 'Could not link the isolated current release.');
        file_put_contents($enabled_path, "enabled\n");
        file_put_contents($strict_path, '');
        // WordPress's own block; index.php stands in for WordPress (no PHP handler in this fixture).
        file_put_contents($fallback, 'WORDPRESS_FALLBACK');
        file_put_contents($htaccess, "# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n");
        sb_assert(sb_private($plugin, 'write_rewrite_rules', array(true)), 'Could not write the Static Bridge .htaccess block.');
        sb_assert(wp_mkdir_p($server_root), 'Could not create the isolated Apache server root.');
        $load = '';
        foreach (array('authz_core', 'dir', 'mime', 'rewrite', 'headers', 'unixd', 'log_config') as $module) {
            $load .= 'LoadModule ' . $module . '_module "' . $modules . '/mod_' . $module . ".so\"\n";
        }
        $docroot = rtrim(ABSPATH, '/');
        $config = 'ServerRoot "' . $server_root . "\"\n" . 'Listen 127.0.0.1:' . $port . "\nServerName 127.0.0.1\n"
            . 'PidFile "' . $server_root . "/httpd.pid\"\n" . 'DefaultRuntimeDir "' . $server_root . "\"\n" . 'Mutex file:' . $server_root . " default\n"
            . 'ErrorLog "' . $log_path . "\"\nLogLevel warn\n" . $load
            . "TypesConfig /dev/null\nAddType text/html .html\nAddType text/plain .php .json\nDirectoryIndex index.html index.php\nAccessFileName .htaccess\n"
            . "<Directory />\n Options FollowSymLinks\n AllowOverride None\n Require all denied\n</Directory>\n"
            . 'DocumentRoot "' . $docroot . "\"\n"
            . '<Directory "' . $docroot . "\">\n Options Indexes FollowSymLinks\n AllowOverride All\n Require all granted\n Header always set X-Fixture-Handler wordpress\n</Directory>\n"
            . '<Directory "' . $docroot . "/wp-content/static-bridge\">\n Header always set X-Fixture-Handler static-file\n</Directory>\n";
        sb_assert(false !== file_put_contents($config_path, $config), 'Could not write the isolated Apache configuration.');
        $environment = array('PATH' => (string) getenv('PATH'));
        if (is_dir($apache_root . '/shared-libs')) {
            $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
        }
        $descriptors = array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a'));
        $process = proc_open(array($httpd, '-f', $config_path, '-DFOREGROUND'), $descriptors, $pipes, $server_root, $environment);
        sb_assert(is_resource($process), 'Could not start the isolated Local Apache server.');

        $request = function ($path, array $headers = array()) use ($port) {
            $context = stream_context_create(array('http' => array('method' => 'GET', 'header' => implode("\r\n", $headers), 'ignore_errors' => true, 'follow_location' => 0, 'timeout' => 3)));
            $body = @file_get_contents('http://127.0.0.1:' . $port . $path, false, $context);
            $status = 0;
            $handler = '';
            foreach ((array) http_get_last_response_headers() as $index => $header) {
                if (0 === $index && preg_match('/^HTTP\/\S+\s+(\d+)/', $header, $match)) {
                    $status = (int) $match[1];
                } elseif (0 === stripos($header, 'X-Fixture-Handler:')) {
                    $handler = trim(substr($header, strlen('X-Fixture-Handler:')));
                }
            }
            return array('status' => $status, 'handler' => $handler, 'body' => false === $body ? '' : $body);
        };
        $deadline = microtime(true) + 5;
        do {
            $home = $request('/');
            if (200 === $home['status']) {
                break;
            }
            usleep(100000);
        } while (microtime(true) < $deadline);
        sb_assert(200 === $home['status'] && 'STATIC_HOME' === $home['body'], 'The isolated Apache fixture did not serve the release before rendering ' . json_encode($home));

        // Anonymous visitors read both routes continuously in a separate process for the
        // whole render loop, as in the end-to-end "concurrent readers" scenario.
        $reader_code = '$base = $argv[1]; $stop = $argv[2]; $pages = array("/" => "STATIC_HOME", "/hello-world/" => "STATIC_HELLO"); $report = array("total" => 0, "bad" => array()); $end = microtime(true) + 60;'
            . 'while (!file_exists($stop) && microtime(true) < $end) { foreach ($pages as $path => $expected) {'
            . '$body = @file_get_contents($base . $path, false, stream_context_create(array("http" => array("ignore_errors" => true, "timeout" => 3))));'
            . '$line = (array) http_get_last_response_headers(); $status = isset($line[0]) && preg_match("/^HTTP\\/\\S+\\s+(\\d+)/", $line[0], $m) ? $m[1] : "0";'
            . '$report["total"]++; if ("200" !== $status || $expected !== $body) { $key = $path . " " . $status . ("200" === $status ? " " . substr((string) $body, 0, 40) : ""); $report["bad"][$key] = isset($report["bad"][$key]) ? $report["bad"][$key] + 1 : 1; } } }'
            . 'file_put_contents($argv[3], json_encode($report));';
        $reader = proc_open(array(PHP_BINARY, '-n', '-r', $reader_code, 'http://127.0.0.1:' . $port, $reader_stop, $reader_report), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a')), $reader_pipes);
        sb_assert(is_resource($reader), 'Could not start the concurrent anonymous reader.');

        $observations = array();
        $GLOBALS['sb_test_http_callback'] = function ($request_url, $args) use ($request, $pages, $files, $strict_path, &$observations) {
            $path = (string) wp_parse_url($request_url, PHP_URL_PATH);
            $route = '' === $path ? '/' : $path;
            $query = (string) wp_parse_url($request_url, PHP_URL_QUERY);
            $token = array();
            parse_str($query, $token);
            $token = isset($token['static_bridge_render']) ? (string) $token['static_bridge_render'] : '';
            $headers = array();
            foreach (isset($args['headers']) && is_array($args['headers']) ? $args['headers'] : array() as $name => $value) {
                $headers[] = $name . ': ' . $value;
            }
            // The loopback render goes to the real Apache with the plugin's query string and headers.
            $render = $request($route . ('' === $query ? '' : '?' . $query), $headers);
            // An anonymous visitor arriving while the route renders must still get the release file.
            $anonymous = $request($route);
            $observations[] = array(
                'route' => $route,
                'render' => array('status' => $render['status'], 'handler' => $render['handler']),
                'anonymous' => array('status' => $anonymous['status'], 'handler' => $anonymous['handler'], 'body' => substr($anonymous['body'], 0, 40)),
                'file' => isset($files[$route]) && is_file($files[$route]),
                'strict' => is_file($strict_path),
                'expected' => isset($pages[$route]) ? $pages[$route] : '',
            );
            if ('wordpress' === $render['handler'] && 'WORDPRESS_FALLBACK' === $render['body']) {
                // index.php stands in for WordPress: answer as WordPress would, with the render proof.
                return array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html', 'X-Static-Bridge-Render' => $token), 'body' => '<html>WORDPRESS_RENDER ' . $route . '</html>');
            }
            return array('response' => array('code' => $render['status']), 'headers' => array('Content-Type' => 'text/html'), 'body' => $render['body']);
        };

        $failures = array();
        for ($round = 0; $round < 20; $round++) {
            $batch = sb_private($plugin, 'fetch_pages', array(array(home_url('/'), home_url('/hello-world/'))));
            $single = sb_private($plugin, 'fetch_page', array(home_url('/hello-world/'), 10));
            foreach (array(home_url('/') => '/', home_url('/hello-world/') => '/hello-world/') as $url => $route) {
                $result = isset($batch[$url]) ? $batch[$url] : null;
                if (!is_array($result) || false === strpos($result['body'], 'WORDPRESS_RENDER ' . $route)) {
                    $failures['render ' . $route] = is_wp_error($result) ? $result->get_error_message() : 'no WordPress body';
                }
            }
            if (!is_array($single) || false === strpos($single['body'], 'WORDPRESS_RENDER /hello-world/')) {
                $failures['render single /hello-world/'] = is_wp_error($single) ? $single->get_error_message() : 'no WordPress body';
            }
        }
        foreach ($observations as $observation) {
            if (!('wordpress' === $observation['render']['handler'] && 200 === $observation['render']['status'])) {
                $failures['render request on ' . $observation['route'] . ' did not reach WordPress'] = json_encode($observation['render']);
            }
            if (!(200 === $observation['anonymous']['status'] && 'static-file' === $observation['anonymous']['handler'] && $observation['expected'] === $observation['anonymous']['body'])) {
                $failures['anonymous reader of ' . $observation['route'] . ' during the render did not get the release file'] = json_encode($observation['anonymous']);
            }
            if (!$observation['file'] || !$observation['strict']) {
                $failures['static file or Strict marker of ' . $observation['route'] . ' was removed during the render'] = json_encode(array('file' => $observation['file'], 'strict' => $observation['strict']));
            }
        }
        sb_assert(60 === count($observations), 'Expected 60 loopback renders, saw ' . count($observations) . '.');

        touch($reader_stop);
        $reader_deadline = microtime(true) + 10;
        while (!is_file($reader_report) && microtime(true) < $reader_deadline) {
            usleep(50000);
        }
        $report = is_file($reader_report) ? json_decode((string) file_get_contents($reader_report), true) : null;
        if (!is_array($report) || (int) $report['total'] < 20) {
            $failures['concurrent reader'] = 'no usable report ' . json_encode($report);
        } elseif (!empty($report['bad'])) {
            $failures['concurrent reader saw ' . array_sum($report['bad']) . ' of ' . $report['total'] . ' responses not from the release'] = json_encode($report['bad']);
        }
        foreach ($pages as $route => $body) {
            if ($body !== (string) @file_get_contents($files[$route])) {
                $failures['release file of ' . $route . ' changed'] = '';
            }
        }
        if (!is_file($strict_path) || false !== get_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION, false)) {
            $failures['render state not restored'] = '';
        }
        $lines = array();
        foreach ($failures as $label => $detail) {
            $lines[] = $label . ('' === $detail ? '' : ' ' . $detail);
        }
        sb_assert(empty($failures), count($failures) . " render-window failure kind(s):\n  - " . implode("\n  - ", $lines));
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        delete_option(Static_Bridge_Plugin::RENDER_BYPASS_OPTION);
        if (is_resource($reader)) {
            @touch($reader_stop);
            proc_terminate($reader, 15);
            proc_close($reader);
        }
        if (is_resource($process)) {
            proc_terminate($process, 15);
            proc_close($process);
        }
        if (null === $previous_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $previous_server_software;
        }
        @unlink($htaccess);
        @unlink($fallback);
        if (is_link($current_path) && readlink($current_path) === 'releases/' . $probe_release_id) {
            @unlink($current_path);
        }
        // Any marker present now was created by this test: pre-existing ones were moved aside.
        foreach (array($enabled_path, $strict_path) as $marker) {
            if (is_file($marker) && !is_link($marker)) {
                @unlink($marker);
            }
        }
        foreach ($moved as $path => $backup) {
            if (!file_exists($path) && !is_link($path)) {
                @rename($backup, $path);
            }
        }
    }
});

sb_test('Strict mode cannot create a 404 marker before the first release', function () use ($plugin, $fixtureRoot) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    sb_private($plugin, 'sync_strict_marker', array(true));
    sb_assert(!file_exists($root . '/.strict'), 'Strict mode was enabled without an active static release.');

    $releaseDirectory = $root . '/releases/test-release';
    if (!is_dir($releaseDirectory) && !mkdir($releaseDirectory, 0775, true) && !is_dir($releaseDirectory)) {
        throw new RuntimeException('Could not create the private test release directory.');
    }
    file_put_contents($releaseDirectory . '/index.html', '<!doctype html>');
    if (!symlink('releases/test-release', $root . '/current')) {
        throw new RuntimeException('Could not create the private test symlink.');
    }
    sb_private($plugin, 'sync_strict_marker', array(true));
    sb_assert(is_file($root . '/.strict'), 'Strict mode was not enabled once a release existed.');
    sb_private($plugin, 'sync_strict_marker', array(false));
    sb_assert(!file_exists($root . '/.strict'), 'Strict marker was not removed when disabled.');
});

sb_test('Current release and strict marker reject symlinks that escape the releases directory', function () use ($plugin, $fixtureRoot) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $release_root = $root . '/releases';
    $outside = $fixtureRoot . '/outside-release';
    if (!is_dir($outside) && !mkdir($outside, 0775, true) && !is_dir($outside)) {
        throw new RuntimeException('Could not create the isolated outside-release fixture.');
    }
    $current = $root . '/current';
    if (is_link($current) || file_exists($current)) {
        unlink($current);
    }
    if (!symlink($outside, $current)) {
        throw new RuntimeException('Could not create the isolated external-current symlink.');
    }
    sb_assert('' === sb_private($plugin, 'current_release'), 'An external current symlink was accepted as an active release.');

    $release = $release_root . '/test-release';
    if (!is_dir($release) && !mkdir($release, 0775, true) && !is_dir($release)) {
        throw new RuntimeException('Could not create the isolated internal release fixture.');
    }
    unlink($current);
    if (!symlink('releases/test-release', $current)) {
        throw new RuntimeException('Could not restore the isolated internal current symlink.');
    }
    $sentinel = $fixtureRoot . '/marker-sentinel.txt';
    file_put_contents($sentinel, 'unchanged');
    $marker = $root . '/.strict';
    if (file_exists($marker) || is_link($marker)) {
        unlink($marker);
    }
    if (!symlink($sentinel, $marker)) {
        throw new RuntimeException('Could not create the isolated strict-marker symlink.');
    }
    sb_assert(false === sb_private($plugin, 'sync_strict_marker', array(true)), 'A symlinked strict marker was accepted.');
    sb_assert('unchanged' === file_get_contents($sentinel), 'The strict-marker check modified the symlink target.');
    unlink($marker);
});

sb_test('A failed manifest write does not replace the active release', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $stage = $root . '/releases/manifest-failure-test';
    if (!is_dir($stage) && !mkdir($stage, 0775, true) && !is_dir($stage)) {
        throw new RuntimeException('Could not create the isolated manifest-failure fixture.');
    }
    $current_before = sb_private($plugin, 'current_release');
    $job = array(
        'release_id' => 'manifest-failure-test',
        'stage' => $stage,
        'saved' => 1,
        'skipped' => 0,
        'issues' => array(array('url' => '', 'message' => "invalid\xB1utf8")),
    );
    sb_private($plugin, 'publish_release', array(&$job));
    sb_assert('failed' === $job['status'], 'An invalid manifest was not rejected.');
    sb_assert($current_before === sb_private($plugin, 'current_release'), 'A failed manifest write replaced the previously active release.');
});

sb_test('The release ready marker commits only after the V2 dependency index', function () use ($pluginFile) {
    $source = (string) file_get_contents($pluginFile);
    $manifest_commit = strpos($source, 'if (!@rename($manifest_temporary, $manifest_file))');
    $index_commit = strpos($source, '$index->finish_release((string) $job[\'release_id\']');
    $ready_commit = strpos($source, '$ready_handle = @fopen($ready_file, \'x\');');
    $current_commit = strpos($source, 'if (!@rename($temporary, $link))');
    sb_assert(false !== $manifest_commit && false !== $index_commit && false !== $ready_commit && false !== $current_commit,
        'A publication commit boundary could not be located.');
    sb_assert($manifest_commit < $index_commit && $index_commit < $ready_commit && $ready_commit < $current_commit,
        'The release marker/current pointer can precede a completed dependency index.');
});

sb_test('The first verified Nginx release arms static routing only after current is published', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $releaseRoot = $root . '/releases';
    $releaseId = 'first-nginx-publication-test';
    $stage = $releaseRoot . '/' . $releaseId;
    $current = $root . '/current';
    $enabled = $root . '/.enabled';
    $strict = $root . '/.strict';
    if (file_exists($stage) || is_link($stage) || (file_exists($current) && !is_link($current))
        || is_link($enabled) || is_link($strict)) {
        throw new RuntimeException('Refusing to replace an unexpected Nginx publication fixture path.');
    }
    if (!mkdir($stage, 0755, true) || false === file_put_contents($stage . '/index.html', '<!doctype html><title>first release</title>')) {
        throw new RuntimeException('Could not create the isolated first-release fixture.');
    }

    $oldTarget = is_link($current) ? readlink($current) : null;
    $enabledExisted = is_file($enabled);
    $enabledContents = $enabledExisted ? (string) file_get_contents($enabled) : '';
    $enabledMode = $enabledExisted ? (fileperms($enabled) & 0777) : 0644;
    $strictExisted = is_file($strict);
    $strictContents = $strictExisted ? (string) file_get_contents($strict) : '';
    $strictMode = $strictExisted ? (fileperms($strict) & 0777) : 0644;
    $serverBefore = $_SERVER['SERVER_SOFTWARE'] ?? null;
    $settingsName = Static_Bridge_Plugin::SETTINGS_OPTION;
    $lastName = 'static_bridge_last_release';
    $activityName = Static_Bridge_Plugin::ACTIVITY_OPTION;
    $snapshots = array();
    foreach (array($settingsName, $lastName, $activityName) as $optionName) {
        $snapshots[$optionName] = array(
            'exists' => array_key_exists($optionName, $GLOBALS['sb_test_options']),
            'value' => $GLOBALS['sb_test_options'][$optionName] ?? null,
        );
    }

    try {
        if (null !== $oldTarget) {
            unlink($current);
        }
        if ($enabledExisted) {
            unlink($enabled);
        }
        if ($strictExisted) {
            unlink($strict);
        }
        $GLOBALS['sb_test_options'][$settingsName] = array('strict_mode' => 0, 'incremental_enabled' => 0);
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1 (first-publication regression fixture)';
        $job = array(
            'status' => 'complete',
            'release_id' => $releaseId,
            'stage' => $stage,
            'saved' => 1,
            'skipped' => 0,
            'issues' => array(),
            'portable_internal_urls' => 1,
        );
        sb_private($plugin, 'publish_release', array(&$job));
        sb_assert('complete' === $job['status'], 'The valid first Nginx release did not complete.');
        sb_assert(is_link($current) && realpath($current) === realpath($stage), 'The current pointer was not published before routing activation.');
        sb_assert(is_file($stage . '/.ready'), 'The release was not verified before Nginx routing activation.');
        sb_assert(is_file($enabled) && !is_link($enabled), 'The first verified Nginx release did not create the .enabled routing marker.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (null !== $oldTarget && !symlink($oldTarget, $current)) {
            throw new RuntimeException('Could not restore the original current pointer.');
        }
        foreach (array('index.html', 'manifest.json', '.ready') as $file) {
            if (is_file($stage . '/' . $file) && !is_link($stage . '/' . $file)) {
                unlink($stage . '/' . $file);
            }
        }
        if (is_dir($stage) && !is_link($stage)) {
            rmdir($stage);
        }
        foreach (array(array($enabled, $enabledExisted, $enabledContents, $enabledMode), array($strict, $strictExisted, $strictContents, $strictMode)) as $marker) {
            if (is_file($marker[0]) && !is_link($marker[0])) {
                unlink($marker[0]);
            }
            if ($marker[1]) {
                file_put_contents($marker[0], $marker[2], LOCK_EX);
                chmod($marker[0], $marker[3]);
            }
        }
        foreach ($snapshots as $optionName => $snapshot) {
            if ($snapshot['exists']) {
                $GLOBALS['sb_test_options'][$optionName] = $snapshot['value'];
            } else {
                unset($GLOBALS['sb_test_options'][$optionName]);
            }
        }
        if (null === $serverBefore) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $serverBefore;
        }
    }
});

sb_test('An interrupted publication is reconciled only when current and its manifest agree', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $release_root = $root . '/releases';
    $current = $root . '/current';
    $strict_marker = $root . '/.strict';
    $old_target = is_link($current) ? readlink($current) : null;
    if ((file_exists($current) || is_link($current)) && !is_link($current)) {
        throw new RuntimeException('Refusing to replace a non-symlink current fixture.');
    }
    $settings_name = Static_Bridge_Plugin::SETTINGS_OPTION;
    $job_name = Static_Bridge_Plugin::JOB_OPTION;
    $last_name = 'static_bridge_last_release';
    $settings_existed = array_key_exists($settings_name, $GLOBALS['sb_test_options']);
    $settings_before = $GLOBALS['sb_test_options'][$settings_name] ?? null;
    $job_existed = array_key_exists($job_name, $GLOBALS['sb_test_options']);
    $job_before = $GLOBALS['sb_test_options'][$job_name] ?? null;
    $last_existed = array_key_exists($last_name, $GLOBALS['sb_test_options']);
    $last_before = $GLOBALS['sb_test_options'][$last_name] ?? null;
    $strict_existed = is_file($strict_marker) && !is_link($strict_marker);
    $strict_before = $strict_existed ? file_get_contents($strict_marker) : null;
    $strict_mode = $strict_existed ? (fileperms($strict_marker) & 0777) : 0644;
    $server_before = $_SERVER['SERVER_SOFTWARE'] ?? null;
    $release_ids = array('crash-after-current-test', 'crash-before-current-test', 'crash-invalid-manifest-test');
    $restore = static function () use (
        $current, $old_target, $release_root, $release_ids, $strict_marker, $strict_existed, $strict_before, $strict_mode,
        $settings_name, $settings_existed, $settings_before, $job_name, $job_existed, $job_before,
        $last_name, $last_existed, $last_before, $server_before
    ): void {
        if (is_link($current)) {
            @unlink($current);
        }
        if (null !== $old_target && !@symlink($old_target, $current)) {
            throw new RuntimeException('Could not restore the original current symlink.');
        }
        foreach ($release_ids as $release_id) {
            $stage = $release_root . '/' . $release_id;
            foreach (array('index.html', 'manifest.json', '.ready') as $file) {
                if (is_file($stage . '/' . $file) && !is_link($stage . '/' . $file)) {
                    @unlink($stage . '/' . $file);
                }
            }
            if (is_dir($stage) && !is_link($stage)) {
                @rmdir($stage);
            }
        }
        if ($strict_existed) {
            @file_put_contents($strict_marker, (string) $strict_before, LOCK_EX);
            @chmod($strict_marker, $strict_mode);
        } elseif (is_file($strict_marker) && !is_link($strict_marker)) {
            @unlink($strict_marker);
        }
        foreach (array(
            array($settings_name, $settings_existed, $settings_before),
            array($job_name, $job_existed, $job_before),
            array($last_name, $last_existed, $last_before),
        ) as $option) {
            if ($option[1]) {
                $GLOBALS['sb_test_options'][$option[0]] = $option[2];
            } else {
                unset($GLOBALS['sb_test_options'][$option[0]]);
            }
        }
        if (null === $server_before) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $server_before;
        }
    };
    $create_release = static function ($release_id, $manifest_release = null) use ($release_root): string {
        $stage = $release_root . '/' . $release_id;
        if (!mkdir($stage, 0755)) {
            throw new RuntimeException('Could not create a private interrupted-publication fixture.');
        }
        $manifest = array(
            'release' => null === $manifest_release ? $release_id : $manifest_release,
            'pages_saved' => 1,
            'pages_skipped' => 0,
            'portable_internal_urls' => 1,
            'ssi_header_fragments' => 0,
        );
        file_put_contents($stage . '/index.html', '<!doctype html><title>recovery fixture</title>');
        file_put_contents($stage . '/manifest.json', json_encode($manifest, JSON_UNESCAPED_SLASHES));
        file_put_contents($stage . '/.ready', '');
        return $stage;
    };

    try {
        $GLOBALS['sb_test_options'][$settings_name] = array('strict_mode' => 0, 'incremental_enabled' => 0);
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1 (isolated unit fixture)';
        if (null !== $old_target) {
            @unlink($current);
        }
        $valid_id = $release_ids[0];
        $valid_stage = $create_release($valid_id);
        sb_assert(symlink('releases/' . $valid_id, $current), 'Could not create the valid post-swap crash state.');
        $valid_job = array('status' => 'running', 'release_id' => $valid_id, 'stage' => $valid_stage, 'saved' => 1, 'skipped' => 0, 'issues' => array());
        sb_assert(sb_private($plugin, 'job_release_is_current', array($valid_job)), 'The controlled post-swap fixture was not recognized as current.');
        $recovered = sb_private($plugin, 'close_incomplete_export_job', array($valid_job));
        sb_assert('complete' === ($recovered['status'] ?? ''), 'A valid already-active release was marked failed after a worker interruption.');
        sb_assert(1 === (int) ($recovered['recovered_after_publication'] ?? 0), 'The recovered job did not record its recovery state.');
        sb_assert($valid_id === ($GLOBALS['sb_test_options'][$last_name]['id'] ?? ''), 'The recovered release ID was not reconciled to the database option.');
        sb_assert(realpath($current) === realpath($valid_stage), 'Recovery changed the valid current release pointer.');

        $not_current_id = $release_ids[1];
        $not_current_stage = $create_release($not_current_id);
        $not_current_job = array('status' => 'running', 'release_id' => $not_current_id, 'stage' => $not_current_stage, 'saved' => 1, 'skipped' => 0, 'issues' => array());
        $not_recovered = sb_private($plugin, 'close_incomplete_export_job', array($not_current_job));
        sb_assert('failed' === ($not_recovered['status'] ?? ''), 'A ready stage that never became current was falsely reported as published.');
        sb_assert(realpath($current) === realpath($valid_stage), 'A pre-swap crash changed the release that was serving.');

        $invalid_id = $release_ids[2];
        $invalid_stage = $create_release($invalid_id, 'different-release-id');
        @unlink($current);
        sb_assert(symlink('releases/' . $invalid_id, $current), 'Could not create the invalid-manifest crash state.');
        $invalid_job = array('status' => 'running', 'release_id' => $invalid_id, 'stage' => $invalid_stage, 'saved' => 1, 'skipped' => 0, 'issues' => array());
        $invalid_result = sb_private($plugin, 'close_incomplete_export_job', array($invalid_job));
        sb_assert('failed' === ($invalid_result['status'] ?? ''), 'A mismatched manifest was accepted during recovery.');
        sb_assert(realpath($current) === realpath($invalid_stage), 'The fail-closed recovery path replaced an unverified current pointer.');
        sb_assert(false !== strpos((string) end($invalid_result['issues'])['message'], 'preservati'), 'An unverified active release was not reported as preserved for diagnosis.');
    } finally {
        $restore();
    }
});

sb_test('A release cannot publish when the manifest would consume the protected disk reserve', function () use ($plugin) {
    $stage = WP_CONTENT_DIR . '/static-bridge/releases/disk-space-publish-test';
    if (!is_dir($stage) && !mkdir($stage, 0775, true) && !is_dir($stage)) {
        throw new RuntimeException('Could not create the isolated disk-reserve publication fixture.');
    }
    $current_before = sb_private($plugin, 'current_release');
    $job = array(
        'release_id' => 'disk-space-publish-test',
        'stage' => $stage,
        'saved' => 1,
        'skipped' => 0,
        'issues' => array(),
    );
    $GLOBALS['sb_test_filter_values']['static_bridge_min_free_space_bytes'] = PHP_INT_MAX;
    try {
        sb_private($plugin, 'publish_release', array(&$job));
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_min_free_space_bytes']);
    }
    sb_assert('failed' === $job['status'], 'A release was published despite insufficient guaranteed space for its manifest.');
    sb_assert($current_before === sb_private($plugin, 'current_release'), 'A disk-space failure changed the current release pointer.');
    sb_assert(!file_exists($stage . '/manifest.json') && !file_exists($stage . '/.ready'), 'A manifest or ready marker was created after the reserve check failed.');
});

sb_test('Oversized HTML responses are rejected before static publication', function () use ($plugin) {
    $url = home_url('/oversized-news-page/');
    $bypass_url = $url . '?static_bridge_bypass=1';
    $GLOBALS['sb_test_http_responses'][$bypass_url] = array(
        'response' => array('code' => 200),
        'headers' => array('Content-Type' => 'text/html'),
        'body' => str_repeat('x', 5242880),
    );
    $result = sb_private($plugin, 'fetch_page', array($url, 10));
    sb_assert(is_wp_error($result) && 'static_bridge_page_too_large' === $result->get_error_code(), 'An oversized HTML response was accepted.');
    $last = end($GLOBALS['sb_test_http_calls']);
    sb_assert(5242880 === $last['args']['limit_response_size'], 'The HTML response byte limit was not enforced at the HTTP client.');
});

sb_test('PHP and database error output in a rendered page keeps it out of the static copy', function () use ($plugin) {
    $page = function ($body) {
        return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html; charset=UTF-8'), 'body' => $body);
    };
    $shell = function ($inside) {
        return "<!DOCTYPE html>\n<html><head><title>Notizie</title></head><body><main>" . $inside . "</main></body></html>";
    };
    $leaks = array(
        'Warning' => "<br />\n<b>Warning</b>:  Undefined variable \$autore in <b>/home/user/public_html/wp-content/themes/tema/single.php</b> on line <b>42</b><br />\n" . $shell('<p>Testo</p>'),
        'Deprecated' => $shell("<p>Testo</p>\n<br />\n<b>Deprecated</b>:  Creation of dynamic property Foo::\$bar is deprecated in <b>/home/user/public_html/wp-content/plugins/x/x.php</b> on line <b>7</b><br />\n"),
        'Notice' => "\nNotice: Function _load_textdomain_just_in_time was called <strong>incorrectly</strong>. in /var/www/Local Sites/sito/app/public/wp-includes/functions.php on line 6121\n" . $shell('<p>Testo</p>'),
        'Fatal error' => $shell("<div class=\"x\">\n<br />\n<b>Fatal error</b>:  Uncaught Error: Call to undefined function foo() in /srv/www/wp-content/themes/t/inc/a.php:12\nStack trace:\n#0 {main}\n  thrown in <b>/srv/www/wp-content/themes/t/inc/a.php</b> on line <b>12</b><br />\n"),
        'Xdebug' => $shell("<br />\n<font size='1'><table class='xe-warning xe-uncaught xdebug-error' dir='ltr' border='1' cellspacing='0' cellpadding='1'><tr><th>Warning</th></tr></table></font>"),
        'database' => $shell("<div id='error'><p class='wpdberror'><strong>WordPress database error:</strong> [Table 'sito.wp_eventi' doesn't exist]<br /><code>SELECT * FROM wp_eventi WHERE data &gt; NOW()</code></p></div><p>Testo</p>"),
    );
    foreach ($leaks as $kind => $body) {
        $result = sb_private($plugin, 'parse_fetched_page', array(home_url('/notizie/'), $page($body)));
        sb_assert(is_wp_error($result) && 'static_bridge_php_error_output' === $result->get_error_code(), 'A page printing a ' . $kind . ' error was accepted for the static copy.');
        sb_assert(false !== strpos($result->get_error_message(), '(' . $kind . ')'), 'The refusal does not name the PHP message: ' . $result->get_error_message());
        sb_assert(!sb_private($plugin, 'is_retryable_export_error', array($result)) && !sb_private($plugin, 'is_fatal_export_url_error', array($result)) && !sb_private($plugin, 'is_skippable_export_http_error', array($result)),
            'A page with PHP output must be skipped like a broken page, keeping its previous copy, not retried or stopping the export.');
    }

    // Text the page shows as text is not PHP output: an article about a PHP warning, a code block, a textarea,
    // a script string, a comment, and a sentence that only looks like one.
    $quiet = array(
        $shell('<p>Il messaggio era:</p><pre><code>Warning: Undefined variable $x in /var/www/a.php on line 3</code></pre>'),
        $shell("<p>Esempio:</p>\n<code>\nNotice: Undefined index: id in /var/www/b.php on line 9\n</code>"),
        $shell("<textarea>\nDeprecated: x in /var/www/c.php on line 1\n</textarea>"),
        $shell("<script>var help = \"\\nWarning: y in /var/www/d.php on line 2\";</script>"),
        $shell("<!--\nWarning: debug in /var/www/e.php on line 4\n-->"),
        $shell('<p>La classe da cercare è:</p><pre>&lt;p class="wpdberror"&gt;</pre><code><p class="wpdberror"></code>'),
        $shell('<p>Attenzione: il treno parte dal binario 3 on line booking.</p><p>Warning: the online form in our office is closed.</p>'),
        $shell('<p>&lt;b&gt;Warning&lt;/b&gt;:  Undefined variable $x in &lt;b&gt;/var/www/a.php&lt;/b&gt; on line &lt;b&gt;3&lt;/b&gt;</p>'),
    );
    foreach ($quiet as $index => $body) {
        $result = sb_private($plugin, 'parse_fetched_page', array(home_url('/notizie/'), $page($body)));
        sb_assert(is_array($result) && isset($result['body']), 'Page ' . $index . ' was refused although it prints no PHP or database error: ' . (is_wp_error($result) ? $result->get_error_message() : ''));
    }

    // The render path refuses it too, before any file is written.
    $url = home_url('/pagina-con-avviso/');
    $GLOBALS['sb_test_http_responses'][$url . '?static_bridge_bypass=1'] = $page($leaks['Warning']);
    $result = sb_private($plugin, 'fetch_page', array($url, 10));
    sb_assert(is_wp_error($result) && 'static_bridge_php_error_output' === $result->get_error_code(), 'The render path accepted a page with PHP output.');
});

sb_test('A running export job from before the export queue is closed without writing any page (note 34)', function () use ($plugin) {
    // The pre-queue worker wrote rendered HTML with no SSI guard and no rewrite step
    // (hardening note 34 of the 3 November 2026 audit): such a job is no longer resumed.
    $release_id = 'legacy-job-probe';
    $stage = WP_CONTENT_DIR . '/static-bridge/releases/' . $release_id;
    if (!wp_mkdir_p($stage)) {
        throw new RuntimeException('Could not create the isolated legacy-job stage.');
    }
    $url = home_url('/ssi-page/');
    $current_before = sb_private($plugin, 'current_release');
    $old_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
    $old_responses = $GLOBALS['sb_test_http_responses'];
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'status' => 'running',
        'release_id' => $release_id,
        'stage' => $stage,
        'started_at' => time(),
        'updated_at' => time(),
        'pending' => array($url),
        'seen' => array($url => 1),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
        'current_url' => '',
    );
    $GLOBALS['sb_test_http_responses'] = array(
        $url . '?static_bridge_bypass=1' => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body><!--#include virtual="/wp-config.php" --></body></html>'),
    );
    $response = null;
    try {
        try {
            $plugin->ajax_tick();
        } catch (SB_Test_Response $caught) {
            $response = $caught;
        }
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
        sb_assert($response instanceof SB_Test_Response && 409 === $response->status, 'A pre-queue job was resumed instead of being refused: ' . json_encode($response ? $response->status : null));
        sb_assert('failed' === ($job['status'] ?? '') && false !== strpos(json_encode($job['issues'] ?? array(), JSON_UNESCAPED_UNICODE), 'nuovo export'), 'The pre-queue job was not closed with a message asking for a new export.');
        sb_assert(array() === $GLOBALS['sb_test_http_calls'], 'The pre-queue worker still renders pages.');
        sb_assert(!file_exists($stage . '/ssi-page/index.html') && !file_exists($stage . '/.ready'), 'The pre-queue worker wrote a page without the SSI guard.');
        sb_assert($current_before === sb_private($plugin, 'current_release'), 'Closing the pre-queue job changed the active release.');
    } finally {
        $GLOBALS['sb_test_http_responses'] = $old_responses;
        if (null === $old_job) {
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        } else {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $old_job;
        }
    }
});

sb_test('Export cancellation is authenticated and preserves the partial stage without publishing it', function () use ($plugin) {
    $release_id = 'cancel-job-probe';
