sb_test('Nginx router protects releases and encodes dynamic exclusions safely', function () use ($plugin) {
    $GLOBALS['sb_test_options'] = array(
        'static_bridge_settings' => array('strict_mode' => 1, 'excluded_paths' => array('/iscriviti/', '/quote";return 403;/'), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1),
        'static_bridge_form_modes' => array(),
        'static_bridge_incremental_queue' => array(),
    );
    $block = sb_private($plugin, 'nginx_router_block');
    sb_assert(false !== strpos($block, 'location ^~ /wp-content/static-bridge/ { deny all; }'), 'Direct access to static releases is not denied.');
    sb_assert(false !== strpos($block, 'location ^~ /wp-content/ai1wm-backups/ { deny all; }'), 'Direct access to All-in-One WP Migration archives is not denied on Nginx.');
    sb_assert(false !== strpos($block, 'location = / {') && false !== strpos($block, 'try_files /wp-content/static-bridge/current/index.html @wperror;'), 'The homepage is not routed through the guarded static location.');
    sb_assert(false !== strpos($block, 'if ($request_method !~ ^(?:GET|HEAD)$) { return 418; }') && false !== strpos($block, 'error_page 418 = @wperror;'), 'Non-GET/HEAD requests do not fall back to WordPress.');
    sb_assert(false !== strpos($block, 'try_files /wp-content/static-bridge/current$uri/index.html @wperror;'), 'The active release is not routed by Nginx.');
    sb_assert(false !== strpos($block, 'if ($uri ~* "^/iscriviti(?:/|$)") { return 418; }'), 'The dynamic Fluent Forms route is missing.');
    sb_assert(false !== strpos($block, '\\x22') && false !== strpos($block, '\\x3B'), 'A hostile route literal was not escaped.');
    sb_assert(false === strpos($block, 'return 403;'), 'A route value injected an Nginx directive.');
    sb_assert(false !== strpos($block, '.enabled') && false !== strpos($block, '.strict'), 'Activation/deactivation and strict markers are not honored.');
});

sb_test('Generated Nginx routing block passes the Local Nginx parser', function () use ($plugin, $fixtureRoot) {
    $nginx = getenv('STATIC_BRIDGE_NGINX_BIN');
    if (!$nginx || !is_executable($nginx) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_NGINX_BIN to run this optional parser check.');
    }
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 1,
        'excluded_paths' => array('/iscriviti/', '/contatti/'),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
    $snippet = sb_private($plugin, 'nginx_router_block');
    $config = "worker_processes 1;\nerror_log stderr;\nevents { worker_connections 16; }\nhttp {\nserver {\nlisten 127.0.0.1:19099;\nroot \"" . ABSPATH . "\";\n" . $snippet . "\nlocation @wperror { return 404; }\n}\n}\n";
    $configPath = $fixtureRoot . '/nginx-static-bridge.conf';
    if (!is_dir($fixtureRoot . '/logs') && !mkdir($fixtureRoot . '/logs', 0775, true) && !is_dir($fixtureRoot . '/logs')) {
        throw new RuntimeException('Could not create the isolated Nginx log directory.');
    }
    if (false === file_put_contents($configPath, $config)) {
        throw new RuntimeException('Could not create the isolated Nginx parser fixture.');
    }
    $descriptors = array(0 => array('pipe', 'r'), 1 => array('pipe', 'w'), 2 => array('pipe', 'w'));
    $process = proc_open(array($nginx, '-t', '-p', $fixtureRoot, '-c', $configPath), $descriptors, $pipes);
    if (!is_resource($process)) {
        throw new RuntimeException('Could not start the Local Nginx parser.');
    }
    fclose($pipes[0]);
    $stdout = stream_get_contents($pipes[1]);
    $stderr = stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);
    $status = proc_close($process);
    unset($_SERVER['SERVER_SOFTWARE']);
    $parser_output = trim($stdout . ' ' . $stderr);
    if (0 !== $status && false !== stripos($parser_output, 'Operation not permitted')) {
        throw new SB_Test_Skip('The sandbox blocks Nginx from opening its validation socket.');
    }
    sb_assert(0 === $status, 'Nginx rejected the generated block: ' . $parser_output);
});

sb_test('Local Nginx serves a release and routes dynamic paths to WordPress fallback', function () use ($plugin, $fixtureRoot) {
    $nginx = getenv('STATIC_BRIDGE_NGINX_BIN');
    if (!$nginx || !is_executable($nginx) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_NGINX_BIN to run this HTTP routing check.');
    }
    if (!function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('The HTTP routing check requires PHP 8.4 or newer.');
    }

    $socket = stream_socket_server('tcp://127.0.0.1:0', $socket_error, $socket_message);
    if (false === $socket) {
        throw new RuntimeException('Could not reserve a local Nginx test port: ' . $socket_message);
    }
    $socket_name = stream_socket_get_name($socket, false);
    fclose($socket);
    $port = (int) substr(strrchr((string) $socket_name, ':'), 1);
    sb_assert($port > 0, 'Could not determine the temporary Nginx test port.');

    $previous_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 1,
        'excluded_paths' => array('/iscriviti/', '/contatti/'),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();

    $document_root = ABSPATH;
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $probe_release_id = 'http-route-probe-' . bin2hex(random_bytes(6));
    $release = $static_root . '/releases/' . $probe_release_id;
    $current_path = $static_root . '/current';
    $current_backup = $static_root . '/.qa-current-backup-' . $probe_release_id;
    $strict_path = $static_root . '/.strict';
    $strict_backup = $static_root . '/.qa-strict-backup-' . $probe_release_id;
    $enabled_path = $static_root . '/.enabled';
    $current_moved = false;
    $strict_moved = false;
    $enabled_created = false;
    $strict_probe_created = false;
    $config_root = $fixtureRoot . '/nginx-http-prefix';
    $config_path = $fixtureRoot . '/nginx-http.conf';
    $log_path = $fixtureRoot . '/nginx-http.log';
    $snippet = sb_private($plugin, 'nginx_router_block');
    $process = null;
    $wordpress_backend = trim((string) getenv('STATIC_BRIDGE_NGINX_WP_BACKEND'));
    $wordpress_credentials_path = trim((string) getenv('STATIC_BRIDGE_NGINX_WP_QA_CREDENTIALS'));
    $php_location = '';

    if ('' !== $wordpress_backend) {
        if (!preg_match('#^http://127\.0\.0\.1:[1-9][0-9]{1,4}$#D', $wordpress_backend)) {
            throw new RuntimeException('The optional WordPress test backend must use a loopback HTTP URL and explicit port.');
        }
        $backend_parts = wp_parse_url($wordpress_backend);
        $backend_host_header = isset($backend_parts['host'], $backend_parts['port'])
            ? $backend_parts['host'] . ':' . (int) $backend_parts['port']
            : '127.0.0.1';
        $fallback = 'location @wperror { proxy_set_header Host ' . $backend_host_header . '; proxy_set_header X-Forwarded-Proto $scheme; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_pass ' . $wordpress_backend . '; }';
        $php_location = 'location ~ \.php$ { proxy_set_header Host ' . $backend_host_header . '; proxy_set_header X-Forwarded-Proto $scheme; proxy_pass ' . $wordpress_backend . '; }';
    } else {
        $fallback = 'location @wperror { default_type text/plain; return 200 "WORDPRESS_FALLBACK:$request_uri"; }';
    }

    try {
        sb_assert(!is_link($static_root) && wp_mkdir_p($static_root . '/releases'), 'Could not create or safely resolve the isolated static root.');
        if (file_exists($current_path) || is_link($current_path)) {
            sb_assert(is_link($current_path) && !file_exists($current_backup) && !is_link($current_backup), 'An unexpected current pointer or backup target blocks the Nginx fixture.');
            sb_assert(@rename($current_path, $current_backup), 'Could not preserve the pre-existing current pointer for the isolated Nginx fixture.');
            $current_moved = true;
        }
        if (file_exists($strict_path) || is_link($strict_path)) {
            sb_assert((is_file($strict_path) || is_link($strict_path)) && !file_exists($strict_backup) && !is_link($strict_backup), 'An unexpected strict marker blocks the isolated Nginx fixture.');
            sb_assert(@rename($strict_path, $strict_backup), 'Could not preserve the pre-existing strict marker for the isolated Nginx fixture.');
            $strict_moved = true;
        }
        sb_assert(wp_mkdir_p($release . '/articolo'), 'Could not create the isolated Nginx release fixture.');
        sb_assert(wp_mkdir_p($config_root . '/logs'), 'Could not create the isolated Nginx prefix.');
        file_put_contents($release . '/index.html', 'STATIC_HOME');
        $header_document_id = '7';
        $header_markup = '<header>STATIC_HEADER</header>';
        $header_variant = hash('sha256', $header_markup);
        $header_filename = Static_Bridge_Header_Fragments::include_filename($header_document_id, $header_variant);
        $header_uri = Static_Bridge_Header_Fragments::include_uri($header_document_id, $header_variant);
        sb_assert(is_string($header_filename) && is_string($header_uri), 'Could not construct the isolated SSI header fixture.');
        file_put_contents($release . '/index.html', 'SSI-HOME-BEGIN<!--#include virtual="' . $header_uri . '" -->SSI-HOME-END');
        $header_generation = $release . '/fragments/headers/' . $header_document_id . '/generations/initial';
        sb_assert(wp_mkdir_p($header_generation), 'Could not create the isolated SSI header generation.');
        file_put_contents($header_generation . '/' . $header_filename, $header_markup);
        sb_assert(symlink('generations/initial', dirname(dirname($header_generation)) . '/current'), 'Could not create the isolated atomic SSI header pointer.');
        file_put_contents($release . '/articolo/index.html', 'SSI-BEGIN<!--#include virtual="' . $header_uri . '" -->SSI-END');
        file_put_contents($release . '/manifest.json', '{"release":"http-route-probe","ssi_header_fragments":1}');
        if (!file_exists($enabled_path) && !is_link($enabled_path)) {
            sb_assert(false !== file_put_contents($enabled_path, '1'), 'Could not create the isolated Nginx enabled marker.');
            $enabled_created = true;
        }
        sb_assert(symlink('releases/' . $probe_release_id, $current_path), 'Could not link the isolated current release.');
        // A redirect of another plugin (static_bridge_redirects, 2.5.0): the query must reach the target page.
        $GLOBALS['sb_test_filter_values']['static_bridge_redirects'] = array('/vecchio-articolo/' => array('to' => '/articolo/', 'status' => 301));
        try {
            $snippet = sb_private($plugin, 'nginx_router_block');
        } finally {
            unset($GLOBALS['sb_test_filter_values']['static_bridge_redirects']);
        }
        sb_assert(false !== strpos($snippet, 'ssi on;') && false !== strpos($snippet, 'internal;'), 'SSI is not enabled for the tested route or internal fragment protection is missing.');

        $config = "worker_processes 1;\n"
            . 'pid "' . $config_root . '/nginx.pid";' . "\n"
            . 'error_log "' . $log_path . '" notice;' . "\n"
            . "events { worker_connections 32; }\nhttp {\nserver {\n"
            . 'listen 127.0.0.1:' . $port . ";\n"
            . 'root "' . $document_root . '";' . "\n"
            . "index index.php index.html;\n"
            . $snippet . "\n" . $fallback . "\n" . $php_location . "\n}\n}\n";
        sb_assert(false !== file_put_contents($config_path, $config), 'Could not write the isolated Nginx HTTP configuration.');

        $descriptors = array(
            0 => array('file', '/dev/null', 'r'),
            1 => array('file', $log_path, 'a'),
            2 => array('file', $log_path, 'a'),
        );
        $process = proc_open(array($nginx, '-p', $config_root, '-c', $config_path, '-g', 'daemon off;'), $descriptors, $pipes);
        sb_assert(is_resource($process), 'Could not start the isolated Local Nginx server.');

        $request = function ($path, $method = 'GET', array $headers = array(), $content = '') use ($port) {
            $context = stream_context_create(array('http' => array(
                'method' => $method,
                'header' => implode("\r\n", $headers),
                'content' => $content,
                'ignore_errors' => true,
                'follow_location' => 0,
                'max_redirects' => 0,
                'timeout' => 3,
            )));
            $body = @file_get_contents('http://127.0.0.1:' . $port . $path, false, $context);
            $response_headers = http_get_last_response_headers();
            if (!is_array($response_headers)) {
                $response_headers = array();
            }
            $status = 0;
            $route = '';
            $backend = '';
            $cache_control = '';
            $etag = '';
            $location = '';
            $cookies = array();
            foreach ($response_headers as $index => $header) {
                if (0 === $index && preg_match('/^HTTP\/\S+\s+(\d+)/', $header, $match)) {
                    $status = (int) $match[1];
                }
                if (0 === stripos($header, 'X-Static-Bridge-Route:')) {
                    $route = strtolower(trim(substr($header, strlen('X-Static-Bridge-Route:'))));
                }
                if (0 === stripos($header, 'X-Static-Bridge-Test-Backend:')) {
                    $backend = strtolower(trim(substr($header, strlen('X-Static-Bridge-Test-Backend:'))));
                }
                if (0 === stripos($header, 'Cache-Control:')) {
                    $cache_control = strtolower(trim(substr($header, strlen('Cache-Control:'))));
                }
                if (0 === stripos($header, 'Location:')) {
                    $location = trim(substr($header, strlen('Location:')));
                }
                if (0 === stripos($header, 'ETag:')) {
                    $etag = trim(substr($header, strlen('ETag:')));
                }
                if (0 === stripos($header, 'Set-Cookie:')) {
                    $cookie_pair = explode(';', trim(substr($header, strlen('Set-Cookie:'))), 2)[0];
                    $separator = strpos($cookie_pair, '=');
                    if (false !== $separator) {
                        $cookies[substr($cookie_pair, 0, $separator)] = substr($cookie_pair, $separator + 1);
                    }
                }
            }
            return array('status' => $status, 'route' => $route, 'backend' => $backend, 'cookies' => $cookies, 'cache_control' => $cache_control, 'etag' => $etag, 'location' => $location, 'body' => false === $body ? '' : $body);
        };

        $home = null;
        $deadline = microtime(true) + 3;
        do {
            $home = $request('/');
            if (200 === $home['status']) {
                break;
            }
            usleep(100000);
        } while (microtime(true) < $deadline);

        sb_assert(200 === $home['status'] && 'SSI-HOME-BEGIN' . $header_markup . 'SSI-HOME-END' === $home['body'] && 'static' === $home['route'], 'Nginx did not compose the static homepage and its internal header fragment: ' . json_encode($home));
        sb_assert(false !== strpos($home['cache_control'], 'no-store') && '' === $home['etag'], 'The exact homepage location did not disable caching after SSI composition.');
        $article = $request('/articolo/');
        sb_assert(200 === $article['status'] && 'SSI-BEGIN' . $header_markup . 'SSI-END' === $article['body'] && 'static' === $article['route'], 'Nginx did not compose the static article and its independently stored header fragment: ' . json_encode($article));
        $moved = $request('/vecchio-articolo/?format=markdown');
        sb_assert(301 === $moved['status'] && (bool) preg_match('~^(?:https?://[^/]+)?/articolo/\?format=markdown$~D', $moved['location']), 'A Nginx redirect of static_bridge_redirects dropped the query: ' . json_encode($moved));
        // The Location is a path, as WP sends it: a URL built by Nginx carries its own scheme and listening port,
        // which behind a proxy are not the visitor's (2.5.0, seen on a real site).
        sb_assert('/articolo/?format=markdown' === $moved['location'], 'A Nginx redirect of static_bridge_redirects sends an absolute URL with the scheme and port Nginx listens on: ' . json_encode($moved));
        $moved = $request('/vecchio-articolo');
        sb_assert(301 === $moved['status'] && '/articolo/' === $moved['location'], 'A Nginx redirect without a query gained a stray question mark, or an absolute URL: ' . json_encode($moved));
        sb_assert(false !== strpos($article['cache_control'], 'no-store') && '' === $article['etag'], 'SSI-composed HTML was not marked uncacheable or retained an ETag.');
        $direct_fragment = $request($header_uri);
        sb_assert(404 === $direct_fragment['status'] && '' === $direct_fragment['route'], 'The internal-only header fragment was reachable directly over HTTP.');

        foreach (array('/iscriviti/', '/contatti/', '/wp-admin/', '/wp-admin/admin-ajax.php', '/wp-login.php', '/wp-json/', '/articolo/?preview=1') as $dynamic_path) {
            $dynamic = $request($dynamic_path);
            if ('' !== $wordpress_backend) {
                sb_assert($dynamic['status'] >= 200 && $dynamic['status'] < 500 && '' === $dynamic['route'] && 'wordpress-clone' === $dynamic['backend'], 'A dynamic or administrative request did not reach the real WordPress clone: ' . $dynamic_path);
                if ('/wp-admin/' === $dynamic_path) {
                    sb_assert(302 === $dynamic['status'], 'The real WordPress admin did not redirect an unauthenticated visitor to login.');
                } elseif ('/wp-login.php' === $dynamic_path) {
                    sb_assert(200 === $dynamic['status'], 'The real WordPress login screen was not reachable through Nginx.');
                }
            } else {
                sb_assert(200 === $dynamic['status'] && '' === $dynamic['route'] && false !== strpos($dynamic['body'], 'WORDPRESS_FALLBACK:'), 'A dynamic or administrative request was not sent to the WordPress fallback: ' . $dynamic_path);
            }
        }

        $authenticated = $request('/', 'GET', array('Cookie: wordpress_logged_in_test=1'));
        if ('' !== $wordpress_backend) {
            sb_assert($authenticated['status'] >= 200 && $authenticated['status'] < 500 && '' === $authenticated['route'] && 'wordpress-clone' === $authenticated['backend'], 'An authenticated-cookie request did not reach the real WordPress clone.');
        } else {
            sb_assert(200 === $authenticated['status'] && '' === $authenticated['route'] && false !== strpos($authenticated['body'], 'WORDPRESS_FALLBACK:/'), 'A logged-in homepage request was served statically.');
        }

        if ('' !== $wordpress_backend && '' !== $wordpress_credentials_path) {
            $credentials = json_decode((string) @file_get_contents($wordpress_credentials_path), true);
            sb_assert(is_array($credentials) && !empty($credentials['login']) && !empty($credentials['password']), 'Temporary WordPress QA credentials are unavailable.');
            $login_page = $request('/wp-login.php');
            sb_assert(200 === $login_page['status'] && 'wordpress-clone' === $login_page['backend'], 'The WordPress login form is unavailable through the static-domain router.');
            $cookie_jar = $login_page['cookies'];
            $cookie_header = implode('; ', array_map(function ($name, $value) {
                return $name . '=' . $value;
            }, array_keys($cookie_jar), array_values($cookie_jar)));
            $login_headers = array('Content-Type: application/x-www-form-urlencoded');
            if ('' !== $cookie_header) {
                $login_headers[] = 'Cookie: ' . $cookie_header;
            }
            $login_response = $request('/wp-login.php', 'POST', $login_headers, http_build_query(array(
                'log' => $credentials['login'],
                'pwd' => $credentials['password'],
                'wp-submit' => 'Log In',
                'redirect_to' => '/wp-admin/',
                'testcookie' => '1',
            )));
            sb_assert(302 === $login_response['status'] && 'wordpress-clone' === $login_response['backend'], 'WordPress did not complete the QA administrator login through Nginx.');
            $cookie_jar = array_merge($cookie_jar, $login_response['cookies']);
            $has_logged_in_cookie = false;
            foreach (array_keys($cookie_jar) as $cookie_name) {
                if (0 === strpos($cookie_name, 'wordpress_logged_in_')) {
                    $has_logged_in_cookie = true;
                    break;
                }
            }
            sb_assert($has_logged_in_cookie, 'WordPress did not issue an authenticated login cookie.');
            $authenticated_cookie_header = implode('; ', array_map(function ($name, $value) {
                return $name . '=' . $value;
            }, array_keys($cookie_jar), array_values($cookie_jar)));
            $admin = $request('/wp-admin/', 'GET', array('Cookie: ' . $authenticated_cookie_header));
            sb_assert(200 === $admin['status'] && '' === $admin['route'] && 'wordpress-clone' === $admin['backend'] && false !== strpos($admin['body'], 'id="wpwrap"'), 'The logged-in administrator could not use wp-admin through the static-domain router.');
        }

        $post = $request('/articolo/', 'POST');
        if ('' !== $wordpress_backend) {
            sb_assert($post['status'] >= 200 && $post['status'] < 500 && '' === $post['route'] && 'wordpress-clone' === $post['backend'], 'A non-GET request did not reach the real WordPress clone.');
        } else {
            sb_assert(200 === $post['status'] && '' === $post['route'] && false !== strpos($post['body'], 'WORDPRESS_FALLBACK:/articolo/'), 'A non-GET request was served statically.');
        }

        $private_file = $request('/wp-content/static-bridge/current/manifest.json');
        sb_assert(in_array($private_file['status'], array(403, 404), true), 'Nginx exposed a private release manifest by direct URL.');

        file_put_contents($static_root . '/.strict', '1');
        $strict_probe_created = true;
        $missing = $request('/non-esportato/');
        sb_assert(404 === $missing['status'] && 'static' === $missing['route'] && '' === $missing['backend'] && false === strpos($missing['body'], 'WORDPRESS_FALLBACK:'), 'Strict mode did not return a static 404 for a missing page.');
        // «Versione Markdown delle pagine» (2.5.0): ?format=markdown reaches WP with the copy, SSI and Strict on, no new rule.
        foreach (array('/', '/articolo/', '/non-esportato/') as $markdown_path) {
            $markdown = $request($markdown_path . '?format=markdown');
            if ('' !== $wordpress_backend) {
                sb_assert('' === $markdown['route'] && 'wordpress-clone' === $markdown['backend'], 'The Markdown version of ' . $markdown_path . ' did not reach the WordPress clone.');
            } else {
                sb_assert(200 === $markdown['status'] && '' === $markdown['route'] && false !== strpos($markdown['body'], 'WORDPRESS_FALLBACK:' . $markdown_path . '?format=markdown'),
                    'The Markdown version of ' . $markdown_path . ' did not reach WordPress: ' . json_encode(array($markdown['status'], $markdown['route'], substr($markdown['body'], 0, 80))));
            }
        }
    } finally {
        if (is_resource($process)) {
            proc_terminate($process, 15);
            proc_close($process);
        }
        if (null === $previous_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $previous_server_software;
        }
        if ($strict_probe_created && is_file($strict_path) && !is_link($strict_path)
            && '1' === file_get_contents($strict_path)) {
            @unlink($strict_path);
        }
        if (is_link($current_path) && readlink($current_path) === 'releases/' . $probe_release_id) {
            @unlink($current_path);
        }
        if ($current_moved && !file_exists($current_path) && !is_link($current_path) && is_link($current_backup)) {
            @rename($current_backup, $current_path);
        }
        if ($strict_moved && !file_exists($strict_path) && !is_link($strict_path)
            && (is_file($strict_backup) || is_link($strict_backup))) {
            @rename($strict_backup, $strict_path);
        }
        if ($enabled_created && is_file($enabled_path) && !is_link($enabled_path) && '1' === file_get_contents($enabled_path)) {
            @unlink($enabled_path);
        }
    }
});

sb_test('Fluent Forms scanning is paginated and bounded for large news sites', function () use ($source) {
    $body = sb_method_body($source, 'discover_form_pages');
    sb_assert(false !== strpos($body, "'s' => 'fluentform'"), 'The scan is not limited to content matching Fluent Forms.');
    sb_assert(false !== strpos($body, "'s' => 'fluentfom'"), 'The scan misses Fluent Forms’ registered legacy Gutenberg block slug.');
    sb_assert(false !== strpos($body, "'_elementor_data'") && false !== strpos($body, "'fluent-form-widget'") && false !== strpos($body, "'_bricks_page_content_2'"), 'The scan does not inspect Fluent Forms Elementor widgets and Bricks builder metadata.');
    sb_assert(false !== strpos($body, 'self::FORM_SCAN_PAGE_SIZE'), 'The scan does not use bounded pages.');
    sb_assert(false === strpos($body, "'posts_per_page' => -1"), 'The scan can still load every post at once.');
});

sb_test('Fluent Forms GUI pagination stays below input limits and preserves other pages', function () use ($plugin, $source) {
    $pages = array();
    for ($index = 1; $index <= 123; $index++) {
        $pages[] = array('path' => sprintf('/news-%03d/', $index), 'manual_excluded' => false);
    }
    $pages[] = array('path' => '/manual-dynamic/', 'manual_excluded' => true);

    $first = sb_private($plugin, 'paginate_form_pages', array($pages, 1));
    $second = sb_private($plugin, 'paginate_form_pages', array($pages, 2));
    $last = sb_private($plugin, 'paginate_form_pages', array($pages, 999));
    $zero = sb_private($plugin, 'paginate_form_pages', array($pages, 0));
    sb_assert(50 === count($first['items']) && 1 === $first['first_item'] && 50 === $first['last_item'], 'The first GUI page does not contain exactly 50 forms.');
    sb_assert(50 === count($second['items']) && '/news-051/' === $second['items'][0]['path'], 'The second GUI page has an incorrect range.');
    sb_assert(3 === $last['current_page'] && 24 === count($last['items']) && 124 === $last['total_items'], 'The last GUI page or out-of-range clamp is incorrect.');
    sb_assert(1 === $zero['current_page'], 'A zero page number was not clamped to the first page.');

    $saved = array(
        '/news-001/' => 'dynamic',
        '/news-051/' => 'dynamic',
        '/news-100/' => 'dynamic',
        '/manual-dynamic/' => 'static',
        '/no-longer-detected/' => 'dynamic',
    );
    $updated = sb_private($plugin, 'merge_form_modes', array(
        $pages,
        array('/news-001/', '/manual-dynamic/', '/not-detected/'),
        array('static', 'static', 'dynamic'),
        $saved,
    ));
    sb_assert('static' === $updated['/news-001/'], 'The submitted page mode was not updated.');
    sb_assert('dynamic' === $updated['/news-051/'] && 'dynamic' === $updated['/news-100/'], 'Saving one GUI page erased settings from other pages.');
    sb_assert(!isset($updated['/manual-dynamic/']), 'A manually excluded form page retained a conflicting saved mode.');
    sb_assert(!isset($updated['/not-detected/']) && 'dynamic' === $updated['/no-longer-detected/'], 'An untrusted submitted path was accepted or an unrelated saved mode was lost.');

    $render = sb_method_body($source, 'render_admin_page');
    $save = sb_method_body($source, 'save_form_modes');
    $paginate = sb_method_body($source, 'paginate_form_pages');
    sb_assert(false !== strpos($paginate, 'FORM_ADMIN_PAGE_SIZE') && false !== strpos($render, "\$form_pagination['items']"), 'The forms GUI does not render a bounded page slice.');
    sb_assert(false !== strpos($render, 'name="forms-page"') && false !== strpos($render, 'forms-page'), 'The forms page number is not preserved across navigation and save.');
    sb_assert(false !== strpos($save, 'merge_form_modes($detected, $paths, $modes'), 'The save handler does not merge the submitted page into existing settings.');
});

sb_test('Fluent Forms admin screen renders a 50-page batch and navigation', function () use ($plugin) {
    $previous = array(
        'post_types' => $GLOBALS['sb_test_post_types'],
        'posts' => $GLOBALS['sb_test_posts'],
        'post_urls' => $GLOBALS['sb_test_post_urls'],
        'post_queries' => $GLOBALS['sb_test_post_queries'],
        'generated_post_count' => $GLOBALS['sb_test_generated_post_count'],
        'options' => $GLOBALS['sb_test_options'],
    );
    $previous_get = $_GET;
    $buffer_level = ob_get_level();

    try {
        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true));
        $GLOBALS['sb_test_posts'] = array();
        $GLOBALS['sb_test_post_urls'] = array();
        $GLOBALS['sb_test_post_queries'] = array();
        $GLOBALS['sb_test_generated_post_count'] = 0;
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
        );
        for ($index = 1; $index <= 123; $index++) {
            $post_id = 8000 + $index;
            $GLOBALS['sb_test_posts'][] = array(
                'ID' => $post_id,
                'post_type' => 'page',
                'post_status' => 'publish',
                'post_password' => '',
                'post_title' => sprintf('News page %03d', $index),
                'post_content' => '[fluentform id="4"]',
                'meta' => array(),
            );
            $GLOBALS['sb_test_post_urls'][$post_id] = home_url(sprintf('/news-%03d/', $index));
        }
        $_GET = array('tab' => 'forms', 'forms-page' => '2');

        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();

        sb_assert(50 === substr_count($html, 'class="sb-form-entry"'), 'The rendered second page does not contain exactly 50 form cards.');
        sb_assert(50 === substr_count($html, 'name="form_paths[]"') && 50 === substr_count($html, 'name="form_modes[]"'), 'The rendered form batch has a mismatched number of submitted path/mode fields.');
        sb_assert(false !== strpos($html, 'name="forms-page" value="2"'), 'The rendered form does not preserve its current page on save.');
        sb_assert(false !== strpos($html, 'Visualizzate 51–100 di 123 pagine') && false !== strpos($html, 'aria-current="page">2'), 'The rendered pagination summary or current-page state is incorrect.');
        sb_assert(false !== strpos($html, 'Pagina precedente') && false !== strpos($html, 'Pagina successiva'), 'The rendered page navigation is missing previous/next controls.');
    } finally {
        while (ob_get_level() > $buffer_level) {
            ob_end_clean();
        }
        $_GET = $previous_get;
        $GLOBALS['sb_test_post_types'] = $previous['post_types'];
        $GLOBALS['sb_test_posts'] = $previous['posts'];
        $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
        $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
        $GLOBALS['sb_test_generated_post_count'] = $previous['generated_post_count'];
        $GLOBALS['sb_test_options'] = $previous['options'];
    }
});

sb_test('Fluent Forms are detected in Elementor and Bricks metadata plus native blocks', function () use ($plugin) {
    $previous = array(
        'post_types' => $GLOBALS['sb_test_post_types'],
        'posts' => $GLOBALS['sb_test_posts'],
        'post_urls' => $GLOBALS['sb_test_post_urls'],
        'post_queries' => $GLOBALS['sb_test_post_queries'],
        'generated_post_count' => $GLOBALS['sb_test_generated_post_count'],
        'options' => $GLOBALS['sb_test_options'],
        'skip_form_meta_query' => $GLOBALS['sb_test_skip_form_meta_query'],
        'skip_url_to_postid' => $GLOBALS['sb_test_skip_url_to_postid'],
    );
    $GLOBALS['sb_test_post_types'] = array(
        'page' => array('public' => true, 'publicly_queryable' => true),
        'post' => array('public' => true, 'publicly_queryable' => true),
    );
    $GLOBALS['sb_test_generated_post_count'] = 0;
    $GLOBALS['sb_test_post_queries'] = array();
    $GLOBALS['sb_test_options'] = array(
        Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array('/contatti/')),
        Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
    );
    $GLOBALS['sb_test_posts'] = array(
        array(
            'ID' => 701,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Contatti',
            'post_content' => '<div class="builder-shell">Ordinary content before the Elementor metadata.</div>',
            'meta' => array('_elementor_data' => json_encode(array(
                array('widgetType' => 'fluent-form-widget', 'settings' => array('form_list' => '3')),
                array('widgetType' => 'fluent-form-widget', 'settings' => array('form_list' => '4')),
            ))),
        ),
        array(
            'ID' => 702,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Modulo blocco',
            'post_content' => '<!-- wp:fluentfom/guten-block {"formId":7} /-->',
            'meta' => array(),
        ),
        array(
            'ID' => 703,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Iscrizione',
            'post_content' => '',
            'meta' => array('_bricks_page_content_2' => json_encode(array(array('name' => 'shortcode', 'settings' => array('shortcode' => "[fluentform id='19']"))))),
        ),
        array(
            'ID' => 704,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Testo senza modulo',
            'post_content' => '',
            'meta' => array('_elementor_data' => '{"widgetType":"form","note":"fluentform integration"}'),
        ),
        array(
            'ID' => 705,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Modulo blocco alternativo',
            'post_content' => '<!-- wp:fluentform/form {"formId":11} /-->',
            'meta' => array(),
        ),
        array(
            'ID' => 706,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Modulo shortcode Elementor',
            'post_content' => '',
            'meta' => array('_elementor_data' => json_encode(array(array('widgetType' => 'shortcode', 'settings' => array('shortcode' => '[fluentform id="22"]'))))),
        ),
    );
    $GLOBALS['sb_test_post_urls'] = array(
        701 => home_url('/contatti/'),
        702 => home_url('/modulo-blocco/'),
        703 => home_url('/iscriviti/'),
        704 => home_url('/solo-testo/'),
        705 => home_url('/modulo-blocco-alternativo/'),
        706 => home_url('/elementor-shortcode/'),
    );

    $pages = sb_private($plugin, 'discover_form_pages');
    $by_path = array();
    foreach ($pages as $page) {
        $by_path[$page['path']] = $page;
    }
    sb_assert(isset($by_path['/contatti/']) && array('3', '4') === $by_path['/contatti/']['form_ids'], 'The native Elementor Fluent Forms widget IDs were not detected.');
    sb_assert(!empty($by_path['/contatti/']['manual_excluded']) && 'dynamic' === $by_path['/contatti/']['mode'], 'A builder page manually excluded from static delivery was not kept dynamic.');
    sb_assert(isset($by_path['/modulo-blocco/']) && array('7') === $by_path['/modulo-blocco/']['form_ids'], 'The native Fluent Forms block or its ID was not detected.');
    sb_assert(isset($by_path['/modulo-blocco-alternativo/']) && array('11') === $by_path['/modulo-blocco-alternativo/']['form_ids'], 'The alternate Fluent Forms block marker was not detected.');
    sb_assert(isset($by_path['/iscriviti/']) && array('19') === $by_path['/iscriviti/']['form_ids'], 'The Bricks builder shortcode form or its ID was not detected.');
    sb_assert(isset($by_path['/elementor-shortcode/']) && array('22') === $by_path['/elementor-shortcode/']['form_ids'], 'The shortcode stored in Elementor metadata was not detected.');
    sb_assert(!isset($by_path['/solo-testo/']), 'A builder note containing the word fluentform was falsely detected as a form.');
    sb_assert(3 === count($GLOBALS['sb_test_post_queries']), 'Form discovery did not use separate bounded searches for shortcode content, the legacy block, and builder metadata.');
    foreach ($GLOBALS['sb_test_post_queries'] as $query) {
        sb_assert(isset($query['posts_per_page']) && $query['posts_per_page'] <= 100 && !empty($query['no_found_rows']), 'A form scan query is not bounded.');
    }

    $GLOBALS['sb_test_skip_form_meta_query'] = true;
    $GLOBALS['sb_test_skip_url_to_postid'] = true;
    $fallback_pages = sb_private($plugin, 'discover_form_pages');
    $fallback_forms = array();
    foreach ($fallback_pages as $page) {
        if ('/contatti/' === $page['path']) {
            $fallback_forms = $page['form_ids'];
            break;
        }
    }
    sb_assert(array('3', '4') === $fallback_forms, 'A form on a manually dynamic Elementor path was lost when the builder-meta search returned no candidates.');

    $GLOBALS['sb_test_post_types'] = $previous['post_types'];
    $GLOBALS['sb_test_posts'] = $previous['posts'];
    $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
    $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
    $GLOBALS['sb_test_generated_post_count'] = $previous['generated_post_count'];
    $GLOBALS['sb_test_options'] = $previous['options'];
    $GLOBALS['sb_test_skip_form_meta_query'] = $previous['skip_form_meta_query'];
    $GLOBALS['sb_test_skip_url_to_postid'] = $previous['skip_url_to_postid'];
});

sb_test('Fluent Forms token protection (nonce refresh off) forces only matching routes to WordPress dynamically', function () use ($plugin) {
    $previous = array(
        'post_types' => $GLOBALS['sb_test_post_types'],
        'posts' => $GLOBALS['sb_test_posts'],
        'post_urls' => $GLOBALS['sb_test_post_urls'],
        'post_queries' => $GLOBALS['sb_test_post_queries'],
        'options' => $GLOBALS['sb_test_options'],
        'filter_values' => $GLOBALS['sb_test_filter_values'],
    );
    $previous_get = $_GET;
    $buffer_level = ob_get_level();
    $reset_cache = static function () use ($plugin): void {
        $property = new ReflectionProperty(Static_Bridge_Plugin::class, 'token_protected_form_paths_cache');
        if (PHP_VERSION_ID < 80100) {
            $property->setAccessible(true);
        }
        $property->setValue($plugin, null);
    };

    try {
        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(array(
            'ID' => 765,
            'post_type' => 'page',
            'post_status' => 'publish',
            'post_password' => '',
            'post_title' => 'Modulo protetto',
            'post_content' => '[fluentform id="1"]',
            'meta' => array(),
        ));
        $GLOBALS['sb_test_post_urls'] = array(765 => home_url('/modulo-protetto/'));
        $GLOBALS['sb_test_post_queries'] = array();
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array('/modulo-protetto/' => 'static'),
            '_fluentform_global_form_settings' => array('misc' => array('tokenBasedProtectionStatus' => 'yes')),
            // 2.0.16: with the static nonce refresh switched off, the 2.0.15 behaviour must hold.
            'static_bridge_fluent_forms_nonce_refresh' => 0,
        );
        $reset_cache();

        $pages = sb_private($plugin, 'discover_form_pages');
        sb_assert(1 === count($pages) && '/modulo-protetto/' === $pages[0]['path'], 'The protected form fixture was not discovered.');
        sb_assert(!empty($pages[0]['token_protection_enabled']) && 'dynamic' === $pages[0]['mode'], 'Fluent Forms token protection did not override a saved static mode.');
        $settings = sb_private($plugin, 'settings');
        sb_assert(in_array('/modulo-protetto/', $settings['excluded_paths'], true), 'The protected form route was not added to dynamic server exclusions.');
        sb_assert(!in_array('/', $settings['excluded_paths'], true), 'The protected form setting unexpectedly made the homepage dynamic.');

        $_GET = array('tab' => 'forms');
        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();
        sb_assert(false !== strpos($html, 'la pagina resta dinamica per rinnovare nonce e token anti-spam'), 'The forms GUI does not explain why token-protected pages stay dynamic.');
        sb_assert(1 === preg_match('/<select\b[^>]*\bid="sb-form-mode-[0-9]+"[^>]*\bdisabled="disabled"[^>]*>/i', $html), 'The GUI still allows a token-protected form to be forced static.');
        sb_assert(false !== strpos($html, 'name="form_modes[]" value="dynamic"'), 'The form settings page does not preserve the forced dynamic mode when submitted.');

        $GLOBALS['sb_test_options']['_fluentform_global_form_settings'] = array('misc' => array('tokenBasedProtectionStatus' => 'no'));
        $GLOBALS['sb_test_filter_values']['fluentform/token_based_spam_protection_status'] = true;
        $reset_cache();
        $filtered_pages = sb_private($plugin, 'discover_form_pages');
        sb_assert(!empty($filtered_pages[0]['token_protection_enabled']) && 'dynamic' === $filtered_pages[0]['mode'], 'A per-form token-protection filter did not conservatively retain dynamic routing.');
    } finally {
        while (ob_get_level() > $buffer_level) {
            ob_end_clean();
        }
        $_GET = $previous_get;
        $GLOBALS['sb_test_post_types'] = $previous['post_types'];
        $GLOBALS['sb_test_posts'] = $previous['posts'];
        $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
        $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_filter_values'] = $previous['filter_values'];
        $reset_cache();
    }
});

sb_test('Fluent Forms rendered by a global template are detected from the active release', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $release_root = $root . '/releases';
    $release_id = 'fluent-global-form-detection-' . getmypid();
    $release = $release_root . '/' . $release_id;
    $current = $root . '/current';
    $previous_target = is_link($current) ? readlink($current) : null;
    $previous = array(
        'post_types' => $GLOBALS['sb_test_post_types'],
        'posts' => $GLOBALS['sb_test_posts'],
        'post_urls' => $GLOBALS['sb_test_post_urls'],
        'post_queries' => $GLOBALS['sb_test_post_queries'],
        'options' => $GLOBALS['sb_test_options'],
    );

    try {
        if (file_exists($release) || is_link($release)) {
            throw new RuntimeException('The isolated global-form fixture release already exists.');
        }
        if ((file_exists($current) || is_link($current)) && null === $previous_target) {
            throw new RuntimeException('The isolated current-release fixture is occupied by a non-symlink.');
        }
        if (!wp_mkdir_p($release . '/world-news')) {
            throw new RuntimeException('Could not create the isolated global-form release directory.');
        }
        $html = '<!doctype html><div class="fluentform" data-form_id="4"></div>';
        if (false === file_put_contents($release . '/world-news/index.html', $html)) {
            throw new RuntimeException('Could not write the isolated global-form release page.');
        }
        if (is_link($current) && !unlink($current)) {
            throw new RuntimeException('Could not temporarily replace the isolated current-release link.');
        }
        if (!symlink('releases/' . $release_id, $current)) {
            throw new RuntimeException('Could not point the isolated current-release link at the fixture.');
        }

        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array();
        $GLOBALS['sb_test_post_urls'] = array();
        $GLOBALS['sb_test_post_queries'] = array();
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
        );

        $pages = sb_private($plugin, 'discover_form_pages');
        $by_path = array();
        foreach ($pages as $page) {
            $by_path[$page['path']] = $page;
        }
        sb_assert(isset($by_path['/world-news/']) && array('4') === $by_path['/world-news/']['form_ids'], 'The form rendered by a global theme template was not detected from active-release HTML.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (null !== $previous_target) {
            symlink($previous_target, $current);
        }
        if (is_file($release . '/world-news/index.html')) {
            unlink($release . '/world-news/index.html');
        }
        if (is_dir($release . '/world-news')) {
            rmdir($release . '/world-news');
        }
        if (is_dir($release)) {
            rmdir($release);
        }
        $GLOBALS['sb_test_post_types'] = $previous['post_types'];
        $GLOBALS['sb_test_posts'] = $previous['posts'];
        $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
        $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
        $GLOBALS['sb_test_options'] = $previous['options'];
    }
});

sb_test('Nginx routing diagnostic requires the route header and exact release hash', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $release = $root . '/releases/nginx-probe';
    if (!is_dir($release) && !mkdir($release, 0775, true) && !is_dir($release)) {
        throw new RuntimeException('Could not create the private Nginx diagnostic release.');
    }
    $body = '<!doctype html><title>Static Nginx probe</title>';
    file_put_contents($release . '/index.html', $body);
    $current = $root . '/current';
    if (is_link($current) || is_file($current)) {
        unlink($current);
    }
    if (!symlink('releases/nginx-probe', $current)) {
        throw new RuntimeException('Could not create the Nginx diagnostic symlink.');
    }
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.27.4';
    $GLOBALS['sb_test_http_responses'][home_url('/')] = array(
        'response' => array('code' => 200),
        'headers' => array('Content-Type' => 'text/html', 'X-Static-Bridge-Route' => 'static'),
        'body' => $body,
    );
    $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
    sb_assert('pass' === $result['status'], 'A genuine Nginx static response was not accepted.');
    $GLOBALS['sb_test_http_responses'][home_url('/')] ['headers']['X-Static-Bridge-Route'] = 'wordpress';
    $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
    sb_assert('fail' === $result['status'], 'A WordPress response was incorrectly reported as static.');
    unset($_SERVER['SERVER_SOFTWARE']);
});

sb_test('Nginx routing diagnostic waits for a release before claiming routing failure', function () use ($plugin) {
    $current = WP_CONTENT_DIR . '/static-bridge/current';
    sb_assert(is_link($current), 'The test fixture has no current release symlink to temporarily remove.');
    $current_target = readlink($current);
    sb_assert(false !== $current_target && '' !== $current_target, 'The test fixture current symlink has no readable target.');
    sb_assert(unlink($current), 'The test fixture current symlink could not be removed.');

    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.27.4';
    try {
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
        sb_assert('skip' === $result['status'], 'The absent release was incorrectly reported as missing Nginx configuration.');
        sb_assert(false !== strpos($result['summary'], 'Nessuna release statica attiva'), 'The diagnostic did not explain why static routing cannot be tested yet.');
    } finally {
        unset($_SERVER['SERVER_SOFTWARE']);
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink($current_target, $current), 'The test fixture current symlink could not be restored.');
    }
});

sb_test('Static generation starts with a DB-backed job without blocking on sitemaps or robots.txt', function () use ($plugin) {
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.27.4';
    $GLOBALS['sb_test_can_manage'] = true;
    $GLOBALS['sb_test_nonce_valid'] = true;
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array();
    $origin = rtrim(home_url('/'), '/');
    $GLOBALS['sb_test_http_responses'] = array(
        home_url('/robots.txt') => array('response' => array('code' => 200), 'headers' => array(), 'body' => 'Sitemap: ' . home_url('/sitemap_index.xml') . "\n"),
        home_url('/sitemap_index.xml') => array('response' => array('code' => 200), 'headers' => array(), 'body' => '<urlset><url><loc>' . $origin . '/news/</loc></url></urlset>'),
    );
    $caught = null;
    try {
        $plugin->ajax_start();
    } catch (SB_Test_Response $response) {
        $caught = $response;
    } finally {
        unset($_SERVER['SERVER_SOFTWARE']);
    }
    sb_assert($caught instanceof SB_Test_Response && 200 === $caught->status, 'Static generation did not start on Nginx.');
    sb_assert(empty(sb_test_blocking_http_calls()), 'Starting a large export made blocking sitemap or robots.txt requests.');
    // The start answers before its background request leaves: that request is sent at the end (shutdown).
    sb_assert(empty($GLOBALS['sb_test_http_calls']), 'The start of an export waited for its background request before answering.');
    $plugin->send_deferred_export_continuation();
    $sent = $GLOBALS['sb_test_http_calls'];
    sb_assert(1 === count($sent) && false === $sent[0]['args']['blocking'] && Static_Bridge_Plugin::EXPORT_CONTINUE_ACTION === $sent[0]['args']['body']['action'], 'The start of an export did not send its background request at the end of the request.');
    $plugin->send_deferred_export_continuation();
    sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'The deferred background request was sent twice.');
    $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    sb_assert(isset($job['status']) && 'running' === $job['status'], 'The Nginx generation job was not recorded.');
    sb_assert(1 === (int) $job['queue_version'] && 'wordpress-keyset' === $job['discovery_source'], 'The job does not use the resumable keyset inventory.');
    sb_assert(1 === (int) $job['portable_internal_urls'], 'A new export job was not marked for portable internal URLs.');
    sb_assert(empty($job['pending']) && empty($job['seen']) && 1 === (int) $GLOBALS['wpdb']->get_var($GLOBALS['wpdb']->prepare("SELECT COUNT(*) FROM wp_static_bridge_export_urls WHERE job_id = %s AND status = 'pending'", $job['job_id'])), 'The URL inventory was stored in wp_options instead of the indexed queue.');
    sb_assert(false !== wp_next_scheduled('static_bridge_process_export_queue'), 'The large export has no background WP-Cron continuation.');
});

sb_test('An export is resumable only with a bounded queue and a real safe stage', function () use ($plugin) {
    $release_id = 'valid-job-probe';
    $stage = WP_CONTENT_DIR . '/static-bridge/releases/' . $release_id;
    if (!wp_mkdir_p($stage)) {
        throw new RuntimeException('Could not create the isolated export-job stage.');
    }
    $url = home_url('/news/');
    $job = array(
        'status' => 'running',
        'release_id' => $release_id,
        'stage' => $stage,
        'started_at' => time(),
        'updated_at' => time(),
        'pending' => array($url),
        'seen' => array($url => 1),
        'processed' => 0,
        'saved' => 0,
        'skipped' => 0,
        'issues' => array(),
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $job;
    sb_assert(sb_private($plugin, 'job_is_running'), 'A complete job with a valid stage was not resumable.');

    $job['pending'] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $job;
    sb_assert(!sb_private($plugin, 'job_is_running'), 'A running job with an empty queue remained resumable.');

    $job['pending'] = array($url);
    $job['stage'] = WP_CONTENT_DIR . '/static-bridge/releases/missing-stage';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $job;
    sb_assert(!sb_private($plugin, 'job_is_running'), 'A job whose staging directory is missing remained resumable.');
});

sb_test('Corrupt running exports are closed and replaced without a synchronous full-site scan', function () use ($plugin) {
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
        'status' => 'running',
        'updated_at' => time(),
        'issues' => array(),
    );
    $GLOBALS['sb_test_http_calls'] = array();
    $response = null;
    try {
        $plugin->ajax_start();
    } catch (SB_Test_Response $caught) {
        $response = $caught;
    }
    $job = get_option(Static_Bridge_Plugin::JOB_OPTION, array());
    sb_assert($response instanceof SB_Test_Response && 200 === $response->status, 'A corrupt old export prevented a new job from starting (response: ' . ($response instanceof SB_Test_Response ? $response->status : 'none') . ').');
    sb_assert('running' === $job['status'] && 1 === (int) $job['queue_version'] && false === $job['discovery_complete'], 'The stale job was not replaced by a fresh resumable export queue.');
    sb_assert('wordpress-keyset' === $job['discovery_source'], 'The new job lost its keyset inventory source.');
    sb_assert(empty(sb_test_blocking_http_calls()), 'Replacing a stale job blocked on network sitemap discovery.');
    sb_assert(is_dir($job['stage']), 'The fresh job has no staged release directory.');
});

sb_test('GUI security diagnostic detects an exposed release manifest', function () use ($plugin) {
    $release = sb_private($plugin, 'current_release');
    sb_assert('' !== $release, 'The test fixture is missing an active release.');
    sb_assert(false !== file_put_contents($release . '/manifest.json', '{"pages_saved":1}'), 'The active release manifest fixture could not be written.');
    $url = home_url('/wp-content/static-bridge/releases/' . rawurlencode(basename($release)) . '/manifest.json');
    $GLOBALS['sb_test_http_responses'][$url] = array('response' => array('code' => 200), 'headers' => array(), 'body' => '{"pages_saved":1}');
    $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'security-release-access', 'type' => 'security-release-access'), array()));
    sb_assert('fail' === $result['status'], 'A publicly readable release manifest was not flagged.');

    $GLOBALS['sb_test_http_responses'][$url] = array('response' => array('code' => 403), 'headers' => array(), 'body' => 'Forbidden');
    $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'security-release-access', 'type' => 'security-release-access'), array()));
    sb_assert('pass' === $result['status'], 'A denied release manifest was not reported as protected.');
});

sb_test('GUI security diagnostic checks archived HTML when current is absent', function () use ($plugin) {
    $current = WP_CONTENT_DIR . '/static-bridge/current';
    sb_assert(is_link($current), 'The test fixture has no current release symlink to temporarily remove.');
    $current_target = readlink($current);
    sb_assert(false !== $current_target && '' !== $current_target, 'The test fixture current symlink has no readable target.');
    sb_assert(unlink($current), 'The test fixture current symlink could not be removed.');

    try {
        $release_id = 'zzzz-security-orphan-' . wp_generate_password(6, false, false);
        $release = WP_CONTENT_DIR . '/static-bridge/releases/' . $release_id;
        sb_assert(wp_mkdir_p($release), 'The orphan-release fixture directory could not be created.');
        sb_assert(false !== file_put_contents($release . '/index.html', '<title>orphan release</title>'), 'The orphan-release HTML fixture could not be written.');
        $url = home_url('/wp-content/static-bridge/releases/' . rawurlencode($release_id) . '/index.html');

        $plan = sb_private($plugin, 'diagnostic_plan', array(''));
        $has_privacy_check = false;
        foreach ($plan as $step) {
            if (isset($step['id']) && 'security-release-access' === $step['id']) {
                $has_privacy_check = true;
                break;
            }
        }
        sb_assert($has_privacy_check, 'The GUI diagnostic omitted release privacy because no current release was linked.');

        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_responses'][$url] = array('response' => array('code' => 200), 'headers' => array(), 'body' => '<title>orphan release</title>');
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'security-release-access', 'type' => 'security-release-access'), array()));
        sb_assert('fail' === $result['status'], 'An exposed orphan HTML release was not flagged without a current symlink.');
        sb_assert(isset($GLOBALS['sb_test_http_calls'][0]['url']) && $url === $GLOBALS['sb_test_http_calls'][0]['url'], 'The diagnostic did not probe the orphan release HTML URL.');

        $GLOBALS['sb_test_http_responses'][$url] = array('response' => array('code' => 403), 'headers' => array(), 'body' => 'Forbidden');
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'security-release-access', 'type' => 'security-release-access'), array()));
        sb_assert('pass' === $result['status'], 'A denied orphan HTML release was not reported as protected.');
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink($current_target, $current), 'The test fixture current symlink could not be restored.');
    }
});

sb_test('Incomplete diagnostic sessions are closed visibly and can be restarted', function () use ($plugin) {
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::DIAGNOSTIC_OPTION] = array(
        'id' => 'legacy-empty-run',
        'status' => 'running',
        'updated_at' => time(),
        'steps' => array(),
        'cursor' => 0,
        'results' => array(),
    );
    sb_assert(false === sb_private($plugin, 'diagnostic_is_running'), 'A running diagnostic with no checks is still treated as resumable.');

    $response = null;
    try {
        $plugin->ajax_diagnostic_tick();
    } catch (SB_Test_Response $caught) {
        $response = $caught;
    }
    $run = get_option(Static_Bridge_Plugin::DIAGNOSTIC_OPTION, array());
    sb_assert($response instanceof SB_Test_Response && 200 === $response->status, 'The incomplete diagnostic was not returned as a handled result.');
    sb_assert('failed' === $run['status'], 'The incomplete diagnostic was not closed with a visible failure.');
    sb_assert(!empty($run['results']) && 'fail' === $run['results'][0]['status'], 'The user-facing diagnostic result does not explain the invalid session.');
    sb_assert(!sb_private($plugin, 'diagnostic_is_running'), 'A closed incomplete diagnostic is still treated as running.');
});

sb_test('Diagnostic GUI starts a fresh run when its resume flag is stale', function () use ($adminJs) {
