});

sb_test('Export GUI checks server status before starting or resuming and can cancel safely', function () use ($adminJs) {
    sb_assert(false !== strpos($adminJs, "let data = await request('static_bridge_status');"), 'The export GUI does not verify persisted status before starting or resuming.');
    sb_assert(false !== strpos($adminJs, "if (['idle', 'failed', 'cancelled', 'complete'].includes(data.status)) data = await request('static_bridge_start');"), 'The export GUI does not start a fresh job after an idle, failed, cancelled or completed status response.');
    sb_assert(false !== strpos($adminJs, "request('static_bridge_cancel')"), 'The export GUI has no authenticated cancel action.');
    sb_assert(false !== strpos($adminJs, "request('static_bridge_resume')"), 'The export GUI does not resume a paused durable queue.');
    sb_assert(false !== strpos($adminJs, "setBusy(false, cfg.strings.start);"), 'The export GUI can leave the start button disabled after a completed or failed status response.');
    sb_assert(false !== strpos($adminJs, 'data.issues[data.issues.length - 1].message'), 'The export GUI does not surface the latest saved job issue.');
});

sb_test('Export GUI replaces stale issue history safely when the active job changes', function () use ($source, $adminJs) {
    sb_assert(false !== strpos($source, 'Crea una release completa'), 'The export screen does not identify a full release clearly.');
    sb_assert(false !== strpos($source, 'Avvia export completo'), 'The export button does not identify the operation as a full export.');
    sb_assert(false !== strpos($source, 'articoli e pagine si aggiornano singolarmente'), 'The export screen does not explain incremental updates for ordinary published or updated posts and pages.');
    sb_assert(false !== strpos($source, "'retrying' => __('Nuovo tentativo di rendering'"), 'The export GUI has no localized retry status.');
    sb_assert(false !== strpos($adminJs, "'%1\$s %2\$s/%3\$s…'") && false !== strpos($adminJs, 'cfg.retryLimit)'), 'The export GUI does not expose the bounded retry count.');
    sb_assert(false !== strpos($source, 'id="sb-issues-card"'), 'The export issues panel has no stable container for live updates.');
    sb_assert(false !== strpos($source, 'id="sb-issues-list"'), 'The export issues list has no stable container for live updates.');
    sb_assert(false !== strpos($adminJs, "const issues = Array.isArray(data.issues) ? data.issues.slice(-8) : [];"), 'The GUI does not bound the live issue list.');
    sb_assert(false !== strpos($adminJs, 'issuesList.replaceChildren();'), 'The GUI does not clear stale issues when a fresh job has none.');
    sb_assert(false !== strpos($adminJs, 'url.textContent = typeof issue.url === \'string\' ? issue.url : \'\';'), 'Issue URLs are not rendered as text.');
    sb_assert(false !== strpos($adminJs, 'document.createTextNode(` — ${typeof issue.message === \'string\' ? issue.message : \'\'}`)'), 'Issue messages are not rendered as text nodes.');
    sb_assert(false !== strpos($adminJs, 'issuesCard.hidden = issuesList.childElementCount === 0;'), 'An empty current job does not hide the stale issues panel.');
});

sb_test('Admin overview distinguishes static publishing capability from an active release', function () use ($source) {
    $render = sb_method_body($source, 'render_admin_page');
    sb_assert(false !== strpos($render, 'Puoi pubblicare il frontend come file statici sullo stesso dominio'), 'The admin overview does not describe static publishing as a capability.');
    sb_assert(false === strpos($render, 'Il frontend pubblico viene servito da file statici.'), 'The admin overview claims the frontend is static even when no release has been published.');
    sb_assert(false !== strpos($render, "esc_html__('WordPress serve il frontend'"), 'The admin overview has no explicit WordPress fallback state when a release is missing.');
