sb_test('AIO import restores a portable release pointer and keeps incremental updates available', function () use ($plugin) {
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'qa-portable-import';
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $enabled_marker = $static_root . '/.enabled';
    $strict_marker = $static_root . '/.strict';
    $old_current_target = is_link($current) ? readlink($current) : false;
    sb_assert(!file_exists($current) || is_link($current), 'The import fixture will not replace a non-symlink current path.');
    if (is_link($current)) {
        sb_assert(@unlink($current), 'Could not isolate the existing current symlink for the import fixture.');
    }
    sb_assert(wp_mkdir_p($release), 'Could not create an isolated imported release.');
    $manifest = array(
        'release' => $release_id,
        'pages_saved' => 1,
        'pages_skipped' => 0,
        'portable_internal_urls' => 1,
        'absolute_url_origin' => 'https://shop.example.invalid',
    );
    $matching_manifest = array_merge($manifest, array('absolute_url_origin' => sb_private($plugin, 'home_origin')));
    sb_assert(false !== file_put_contents($release . '/manifest.json', json_encode($manifest)), 'Could not write the imported release manifest.');
    sb_assert(false !== file_put_contents($release . '/.ready', ''), 'Could not write the imported release marker.');
    sb_assert(false !== file_put_contents($release . '/index.html', '<a href="/news/">news</a>'), 'Could not write a sample static page.');

    $old_options = $GLOBALS['sb_test_options'];
    $old_scheduled = $GLOBALS['sb_test_scheduled_hooks'];
    $old_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 0,
        'excluded_paths' => array(),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    );
    $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => $release_id, 'pages' => 1, 'skipped' => 0);
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(
        sha1('/queued-story/') => array(
            'url' => 'http://localhost:18791/queued-story/',
            'path' => '/queued-story/',
            'action' => 'refresh',
            'role' => 'single',
            'post_id' => 55,
            'builders' => array(),
            'queued_at' => time(),
            'token' => 'previous-local-token',
            'attempts' => 0,
        ),
    );
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    try {
        // Exported on another domain: canonical and og: name that domain, so the release is not activated.
        sb_assert(false === $plugin->after_ai1wm_import(array()) && !is_link($current) && !file_exists($enabled_marker),
            'A release whose canonical and og: URLs name another domain was activated.');
        $origin_notes = array_filter((array) get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), function ($entry) {
            return false !== strpos((string) $entry['detail'], 'https://shop.example.invalid') && !empty($entry['error']);
        });
        sb_assert(1 === count($origin_notes), 'A release exported on another domain was refused without asking for a full export.');
        sb_assert(false === sb_private($plugin, 'imported_release_has_other_origin', array('missing-release')), 'A release without a manifest was reported as coming from another domain.');
        sb_assert(false !== file_put_contents($release . '/manifest.json', json_encode($matching_manifest)), 'Could not rewrite the imported release manifest.');
        sb_assert($plugin->after_ai1wm_import(array()), 'The AIO post-import handler did not validate and restore the imported release.');
        sb_assert(is_link($current) && realpath($current) === realpath($release), 'AIO import did not atomically recreate current from the immutable release.');
        sb_assert(is_file($enabled_marker) && !file_exists($strict_marker), 'Static routing markers do not reflect the imported non-strict release.');
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $item = reset($queue);
        sb_assert(is_array($item) && home_url('/queued-story/') === $item['url'], 'An imported pending incremental URL was not mapped to the destination domain.');
        sb_assert(wp_next_scheduled('static_bridge_process_incremental_queue'), 'The imported pending incremental queue was not scheduled.');
        sb_assert($release_id === get_option('static_bridge_last_release', array())['id'], 'The destination does not identify the imported release as current.');
        sb_assert(sb_private($plugin, 'enqueue_incremental_url', array(home_url('/new-live-post/'), 99, 'refresh', array(), 'single')), 'The imported current release did not accept a new incremental page update.');
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        sb_assert(isset($queue[sha1('/new-live-post/')]), 'A post published after import was not added to the incremental queue.');

        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        $old_htaccess = is_file($htaccess) && !is_link($htaccess) ? file_get_contents($htaccess) : false;
        sb_assert(!is_link($htaccess) && (!file_exists($htaccess) || is_file($htaccess)), 'The fail-closed import test will not replace an unexpected .htaccess path.');
        if (is_file($htaccess)) {
            sb_assert(@unlink($htaccess), 'Could not prepare an isolated .htaccess failure fixture.');
        }
        sb_assert(@mkdir($htaccess), 'Could not create the isolated .htaccess failure fixture.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['strict_mode'] = 1;
        $_SERVER['SERVER_SOFTWARE'] = 'Apache';
        try {
            sb_assert(false === $plugin->after_ai1wm_import(array()), 'The import handler reported success when Apache routing rules were unwritable.');
            sb_assert(!file_exists($enabled_marker) && !file_exists($strict_marker), 'The import handler left static/strict markers active after a routing failure.');
        } finally {
            @rmdir($htaccess);
            if (false !== $old_htaccess) {
                @file_put_contents($htaccess, $old_htaccess);
            }
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        }

        sb_assert(sb_private($plugin, 'sync_routing_enabled_marker', array(true)), 'Could not prepare the invalid-import recovery marker.');
        sb_assert(sb_private($plugin, 'sync_strict_marker', array(true)), 'Could not prepare the invalid-import strict marker.');
        sb_assert(is_link($current) && @unlink($current), 'Could not reproduce an imported site without its current pointer.');
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => 'qa-missing-portable-release');
        $GLOBALS['sb_test_is_admin'] = true;
        $GLOBALS['sb_test_can_manage'] = true;
        sb_assert(false === $plugin->maybe_recover_imported_release(), 'Admin recovery accepted a missing or unvalidated imported release.');
        sb_assert(!file_exists($enabled_marker) && !file_exists($strict_marker) && !is_link($current), 'Invalid import recovery did not fail open to WordPress.');
        $GLOBALS['sb_test_is_admin'] = false;
    } finally {
        if (is_link($current)) {
            @unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array('manifest.json', '.ready', 'index.html') as $filename) {
            if (is_file($release . '/' . $filename) && !is_link($release . '/' . $filename)) {
                @unlink($release . '/' . $filename);
            }
        }
        @rmdir($release);
        $GLOBALS['sb_test_options'] = $old_options;
        $GLOBALS['sb_test_scheduled_hooks'] = $old_scheduled;
        $GLOBALS['sb_test_is_admin'] = false;
        if (null === $old_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server_software;
        }
    }
});

sb_test('Fresh activation keeps routing disabled until a valid release exists', function () use ($plugin) {
    $root = WP_CONTENT_DIR . '/static-bridge';
    $current = $root . '/current';
    $enabled_marker = $root . '/.enabled';
    $strict_marker = $root . '/.strict';
    sb_assert(!file_exists($current) || is_link($current), 'The fresh-install activation test found an unexpected non-symlink current path.');
    sb_assert(!file_exists($enabled_marker) || is_file($enabled_marker), 'The fresh-install activation test found an unexpected enabled-marker path.');
    sb_assert(!file_exists($strict_marker) || is_file($strict_marker), 'The fresh-install activation test found an unexpected strict-marker path.');
    $old_current_target = is_link($current) ? readlink($current) : false;
    $old_enabled_contents = is_file($enabled_marker) ? file_get_contents($enabled_marker) : false;
    $old_strict_contents = is_file($strict_marker) ? file_get_contents($strict_marker) : false;
    if (is_link($current)) {
        sb_assert(@unlink($current), 'Could not isolate the existing current pointer for the fresh-install test.');
    }
    if (is_file($enabled_marker)) {
        sb_assert(@unlink($enabled_marker), 'Could not isolate the existing routing marker for the fresh-install test.');
    }
    if (is_file($strict_marker)) {
        sb_assert(@unlink($strict_marker), 'Could not isolate the existing strict marker for the fresh-install test.');
    }

    $old_options = $GLOBALS['sb_test_options'];
    $old_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $old_is_admin = $GLOBALS['sb_test_is_admin'];
    $old_can_manage = $GLOBALS['sb_test_can_manage'];
    unset($GLOBALS['sb_test_options']['static_bridge_last_release']);
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    try {
        Static_Bridge_Plugin::activate();
        sb_assert(!file_exists($enabled_marker) && !file_exists($strict_marker), 'A fresh activation armed static routing without a published release.');

        sb_assert(sb_private($plugin, 'sync_routing_enabled_marker', array(true)), 'Could not prepare the stale-marker/no-release recovery fixture.');
        $GLOBALS['sb_test_is_admin'] = true;
        $GLOBALS['sb_test_can_manage'] = true;
        sb_assert(false === $plugin->maybe_recover_imported_release(), 'Admin recovery treated a fresh install as an imported release.');
        sb_assert(!file_exists($enabled_marker) && !file_exists($strict_marker), 'A stale marker without a release was not cleared.');

        $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
        foreach ($activity as $item) {
            sb_assert(false === strpos(isset($item['message']) ? $item['message'] : '', 'Release importata non valida'), 'A fresh activation logged a false invalid-import warning.');
        }
    } finally {
        $GLOBALS['sb_test_options'] = $old_options;
        $GLOBALS['sb_test_is_admin'] = $old_is_admin;
        $GLOBALS['sb_test_can_manage'] = $old_can_manage;
        if (is_file($enabled_marker) && !is_link($enabled_marker)) {
            @unlink($enabled_marker);
        }
        if (is_file($strict_marker) && !is_link($strict_marker)) {
            @unlink($strict_marker);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        if (false !== $old_enabled_contents) {
            @file_put_contents($enabled_marker, $old_enabled_contents, LOCK_EX);
        }
        if (false !== $old_strict_contents) {
            @file_put_contents($strict_marker, $old_strict_contents, LOCK_EX);
        }
        if (null === $old_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server_software;
        }
    }
});

/*
 * Release retention (2.0.13). Every retention test runs against its own
 * wp-content/static-bridge tree: the shared fixture used by earlier tests is
 * moved aside first and restored afterwards, so a deletion bug can only ever
 * reach the private copy built here.
 */
function sb_retention_remove_tree($path)
{
    if (is_link($path) || is_file($path)) {
        @unlink($path);
        return;
    }
    if (!is_dir($path)) {
        return;
    }
    foreach (scandir($path) as $entry) {
        if ('.' !== $entry && '..' !== $entry) {
            sb_retention_remove_tree($path . '/' . $entry);
        }
    }
    @rmdir($path);
}

function sb_retention_isolated($fixtureRoot, callable $callback)
{
    $root = WP_CONTENT_DIR . '/static-bridge';
    $saved = $fixtureRoot . '/static-bridge-saved-for-retention-' . bin2hex(random_bytes(4));
    if ((file_exists($root) || is_link($root)) && !rename($root, $saved)) {
        throw new RuntimeException('Could not move the shared static-bridge fixture aside.');
    }
    $option_names = array(
        Static_Bridge_Plugin::SETTINGS_OPTION,
        Static_Bridge_Plugin::JOB_OPTION,
        Static_Bridge_Plugin::ACTIVITY_OPTION,
        Static_Bridge_Plugin::RENDER_BYPASS_OPTION,
        Static_Bridge_Plugin::DIAGNOSTIC_OPTION,
        Static_Bridge_Plugin::EXPORT_LOCK_OPTION,
        'static_bridge_retention_last',
        'static_bridge_last_release',
        'static_bridge_ssi_safe_release',
        'static_bridge_ssi_last_probe',
    );
    $previous_options = array();
    foreach ($option_names as $name) {
        $previous_options[$name] = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
        unset($GLOBALS['sb_test_options'][$name]);
    }
    $previous_transients = $GLOBALS['sb_test_transients'];
    $previous_scheduled = $GLOBALS['sb_test_scheduled_hooks'];
    $previous_schema = $GLOBALS['sb_test_export_queue_schema'];
    $GLOBALS['sb_test_transients'] = array();
    $GLOBALS['sb_test_release_keys'] = array();
    $GLOBALS['sb_test_release_key_query_fail'] = false;
    $GLOBALS['wpdb']->last_error = '';
    try {
        $callback($root);
    } finally {
        sb_retention_remove_tree($root);
        if (file_exists($saved) || is_link($saved)) {
            rename($saved, $root);
        }
        foreach ($previous_options as $name => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$name]);
            } else {
                $GLOBALS['sb_test_options'][$name] = $value[0];
            }
        }
        $GLOBALS['sb_test_transients'] = $previous_transients;
        $GLOBALS['sb_test_scheduled_hooks'] = $previous_scheduled;
        $GLOBALS['sb_test_export_queue_schema'] = $previous_schema;
        $GLOBALS['sb_test_release_keys'] = array();
        $GLOBALS['sb_test_release_key_query_fail'] = false;
        $GLOBALS['wpdb']->last_error = '';
    }
}

function sb_retention_release($root, $id, $ready, $mtime)
{
    $directory = $root . '/releases/' . $id;
    sb_assert(wp_mkdir_p($directory . '/news'), 'Could not create retention release fixture ' . $id);
    sb_assert(false !== file_put_contents($directory . '/index.html', '<!doctype html><title>' . $id . '</title>'), 'Could not seed ' . $id);
    sb_assert(false !== file_put_contents($directory . '/news/index.html', str_repeat('x', 1024)), 'Could not seed ' . $id);
    if ($ready) {
        file_put_contents($directory . '/manifest.json', json_encode(array('release' => $id, 'pages_saved' => 2, 'portable_internal_urls' => 1)));
        file_put_contents($directory . '/.ready', '');
        touch($directory . '/.ready', $mtime);
    }
    touch($directory . '/news', $mtime);
    touch($directory, $mtime);
    return $directory;
}

function sb_retention_point_current($root, $id)
{
    $current = $root . '/current';
    if (is_link($current) || file_exists($current)) {
        unlink($current);
    }
    sb_assert(symlink('releases/' . $id, $current), 'Could not create the retention current pointer.');
}

function sb_retention_enable($keep = 2)
{
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array(
        'strict_mode' => 0,
        'incremental_enabled' => 1,
        'excluded_paths' => array(),
        'retention_enabled' => 1,
        'retention_keep' => $keep,
    );
}

function sb_retention_listing($root)
{
    $entries = array_values(array_diff(scandir($root . '/releases'), array('.', '..')));
    sort($entries);
    return $entries;
}

sb_test('Release retention is off by default and a disabled run deletes nothing', function () use ($plugin, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        $settings = sb_private($plugin, 'settings');
        sb_assert(isset($settings['retention_enabled'], $settings['retention_keep']), 'Retention settings are not exposed by settings().');
        sb_assert(0 === $settings['retention_enabled'], 'Release retention is not disabled by default.');
        sb_assert(3 === $settings['retention_keep'], 'The default number of retained releases is not 3.');

        $old = time() - 30 * 86400;
        foreach (array('r01', 'r02', 'r03', 'r04', 'r05', 'r06') as $index => $id) {
            sb_retention_release($root, $id, true, $old + $index * 60);
        }
        sb_retention_release($root, 's-abandoned', false, $old);
        sb_retention_point_current($root, 'r06');
        $before = sb_retention_listing($root);

        $result = sb_private($plugin, 'apply_release_retention', array('manual'));
        sb_assert(is_array($result) && 'disabled' === $result['status'], 'A disabled retention run did not report the disabled state.');
        sb_assert($before === sb_retention_listing($root), 'A disabled retention run changed the releases directory.');
        sb_assert(false === sb_private($plugin, 'schedule_release_retention'), 'A disabled retention policy scheduled a cleanup.');
        sb_assert(!isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_release_retention']), 'A disabled retention policy left a scheduled cleanup.');
    });
});

sb_test('Release retention keeps current, AIO, job, SSI and indexed releases and removes only old unreferenced copies', function () use ($plugin, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin, $fixtureRoot) {
        $old = time() - 30 * 86400;
        $ids = array('r00', 'r01', 'r02', 'r03', 'r04', 'r05', 'r06', 'r07', 'r08', 'r09');
        foreach ($ids as $index => $id) {
            sb_retention_release($root, $id, true, $old + $index * 3600);
        }
        sb_retention_point_current($root, 'r09');
        sb_retention_release($root, 's-job-failed', false, $old);
        sb_retention_release($root, 's-job-paused', false, $old);
        sb_retention_release($root, 's-abandoned', false, $old);
        sb_retention_release($root, 's-fresh', false, time() - 120);
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => 'r02', 'published_at' => $old);
        // 2.4.0: only an export that can still go on (running or paused) keeps its folder; a failed one never resumes.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array('status' => 'paused', 'release_id' => 's-job-paused', 'stage' => $root . '/releases/s-job-paused');
        $GLOBALS['sb_test_options']['static_bridge_ssi_safe_release'] = 'r05';
        $GLOBALS['sb_test_export_queue_schema']['wp_static_bridge_v2_routes'] = true;
        $GLOBALS['sb_test_export_queue_schema']['wp_static_bridge_v2_fragments'] = true;
        $GLOBALS['sb_test_release_keys']['wp_static_bridge_v2_routes'] = array(hash('sha256', 'r03'));
        $GLOBALS['sb_test_release_keys']['wp_static_bridge_v2_fragments'] = array(hash('sha256', 'r04'));

        // Symlinks inside an expired release must be unlinked, never followed.
        $outside = $fixtureRoot . '/retention-outside-' . bin2hex(random_bytes(4));
        sb_assert(wp_mkdir_p($outside . '/nested'), 'Could not create the outside sentinel directory.');
        file_put_contents($outside . '/keep.txt', 'outside must survive');
        file_put_contents($outside . '/nested/keep.txt', 'outside nested must survive');
        sb_assert(symlink($outside, $root . '/releases/r00/news/dir-link'), 'Could not create a symlinked directory inside r00.');
        sb_assert(symlink($outside . '/keep.txt', $root . '/releases/r00/file-link.html'), 'Could not create a symlinked file inside r00.');
        // Entries the plugin did not create must be left alone.
        sb_assert(symlink($outside, $root . '/releases/linked-release'), 'Could not create a symlinked release entry.');
        file_put_contents($root . '/releases/stray.txt', 'not a release');
        sb_assert(wp_mkdir_p($root . '/releases/bad.name'), 'Could not create an unrecognised release directory.');
        touch($root . '/releases/bad.name', $old);
        sb_retention_enable(2);

        $plan = sb_private($plugin, 'release_retention_plan', array(2));
        sb_assert(is_array($plan) && !empty($plan['ok']), 'The retention plan was not computed for a safe release tree.');
        $actions = array();
        foreach ($plan['entries'] as $entry) {
            $actions[$entry['name']] = $entry['action'];
        }
        $expected_delete = array('r00', 'r01', 'r06', 's-abandoned', 's-job-failed');
        $protected = array();
        foreach ($plan['entries'] as $entry) {
            $protected[$entry['name']] = !empty($entry['protected']);
        }
        foreach (array('r09', 'r02', 'r03', 'r04', 'r05', 's-job-paused') as $name) {
            sb_assert(!empty($protected[$name]), 'A protected release was not marked protected: ' . $name);
        }
        foreach (array('r07', 'r08', 'r00', 's-abandoned', 's-fresh') as $name) {
            sb_assert(empty($protected[$name]), 'A release kept only by count or age was marked protected: ' . $name);
        }
        foreach ($actions as $name => $action) {
            sb_assert(in_array($name, $expected_delete, true) === ('delete' === $action), 'Unexpected retention decision for ' . $name . ': ' . $action);
        }
        foreach (array('linked-release', 'stray.txt', 'bad.name') as $ignored) {
            sb_assert(isset($actions[$ignored]) && 'ignore' === $actions[$ignored], 'An unrecognised entry was not explicitly ignored: ' . $ignored);
        }

        $result = sb_private($plugin, 'apply_release_retention', array('manual'));
        sb_assert('complete' === $result['status'], 'The retention run did not complete: ' . json_encode($result));
        $deleted = $result['deleted'];
        sort($deleted);
        sb_assert($expected_delete === $deleted, 'The retention run deleted an unexpected set: ' . json_encode($deleted));
        sb_assert($result['bytes'] > 0, 'The retention run did not account for reclaimed bytes.');
        $remaining = sb_retention_listing($root);
        foreach (array('r02', 'r03', 'r04', 'r05', 'r07', 'r08', 'r09', 's-job-paused', 's-fresh', 'linked-release', 'stray.txt', 'bad.name') as $kept) {
            sb_assert(in_array($kept, $remaining, true), 'Retention removed a protected entry: ' . $kept);
        }
        foreach ($expected_delete as $gone) {
            sb_assert(!in_array($gone, $remaining, true), 'Retention left an expired entry behind: ' . $gone);
        }
        sb_assert(0 === count(preg_grep('/\.sb-retention-/', $remaining)), 'Retention left a trash directory behind after a complete run.');
        sb_assert('outside must survive' === file_get_contents($outside . '/keep.txt')
            && 'outside nested must survive' === file_get_contents($outside . '/nested/keep.txt'), 'Retention followed a symlink and changed files outside the release root.');
        sb_assert(is_link($root . '/releases/linked-release') && is_file($root . '/releases/r02/.ready'), 'Retention altered a symlinked entry or a protected release.');
        sb_assert(realpath($root . '/current') === realpath($root . '/releases/r09') && is_file($root . '/current/index.html'), 'Retention disturbed the current release.');

        $last = get_option('static_bridge_retention_last', array());
        sb_assert(is_array($last) && 'complete' === $last['status'] && 5 === count($last['deleted']), 'The last retention result was not recorded.');
        $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
        $logged = end($activity);
        sb_assert(is_array($logged) && false !== strpos($logged['message'], 'Pulizia release') && false !== strpos($logged['detail'], 'r00'), 'The retention run was not logged with the deleted releases.');
        sb_assert(false === get_option(Static_Bridge_Plugin::INCREMENTAL_LOCK_OPTION, false) && false === get_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION, false), 'Retention did not release its locks.');
    });
});

sb_test('Release retention refuses to run during export, render, incremental or unsafe states', function () use ($plugin, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin, $fixtureRoot) {
        $old = time() - 30 * 86400;
        foreach (array('r01', 'r02', 'r03', 'r04', 'r05', 'r06') as $index => $id) {
            sb_retention_release($root, $id, true, $old + $index * 60);
        }
        sb_retention_release($root, 's-abandoned', false, $old);
        sb_retention_point_current($root, 'r06');
        sb_retention_enable(1);
        $before = sb_retention_listing($root);
        $expect = function ($status, $label) use ($plugin, $root, $before) {
            $result = sb_private($plugin, 'apply_release_retention', array('manual'));
            sb_assert(is_array($result) && $status === $result['status'], $label . ': expected ' . $status . ', got ' . json_encode($result));
            sb_assert($before === sb_retention_listing($root), $label . ': the releases directory changed.');
        };

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array('status' => 'running', 'release_id' => 'r99', 'stage' => $root . '/releases/r99');
        $expect('busy', 'running export job');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        sb_assert(false === get_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION, false), 'A refused run kept the export worker lock.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION] = array('token' => 'other-worker', 'expires' => time() + 60);
        $expect('busy', 'export worker lock held');
        sb_assert('other-worker' === get_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION)['token'], 'Retention released a lock owned by another worker.');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION]);

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::RENDER_BYPASS_OPTION] = array('release_id' => 'r06', 'routes' => array('/'));
        $expect('busy', 'pending render transaction');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::RENDER_BYPASS_OPTION]);

        $lock_path = rtrim(realpath(sys_get_temp_dir()), '/') . '/static-bridge-render-' . substr(hash('sha256', realpath(WP_CONTENT_DIR) . '/static-bridge'), 0, 24) . '.lock';
        $handle = fopen($lock_path, 'c');
        sb_assert(is_resource($handle) && flock($handle, LOCK_EX | LOCK_NB), 'Could not hold the render lock for the retention test.');
        try {
            $expect('busy', 'render lock held');
        } finally {
            flock($handle, LOCK_UN);
            fclose($handle);
        }

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_LOCK_OPTION] = array('token' => 'incremental-worker', 'expires' => time() + 60);
        $expect('busy', 'incremental worker lock held');
        sb_assert('incremental-worker' === get_option(Static_Bridge_Plugin::INCREMENTAL_LOCK_OPTION)['token'], 'Retention released an incremental lock it did not own.');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_LOCK_OPTION]);

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::DIAGNOSTIC_OPTION] = array('status' => 'running', 'updated_at' => time(), 'steps' => array('a'), 'cursor' => 0, 'results' => array());
        $expect('busy', 'running diagnostic');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::DIAGNOSTIC_OPTION]);

        $GLOBALS['sb_test_export_queue_schema']['wp_static_bridge_v2_state'] = true;
        $GLOBALS['sb_test_release_key_query_fail'] = true;
        $expect('error', 'unreadable dependency index');
        $GLOBALS['sb_test_release_key_query_fail'] = false;
        $GLOBALS['wpdb']->last_error = '';
        $GLOBALS['sb_test_release_keys']['wp_static_bridge_v2_state'] = array('not-a-release-key');
        $expect('error', 'malformed dependency index key');
        $GLOBALS['sb_test_release_keys'] = array();

        unlink($root . '/current');
        $expect('error', 'missing current pointer');
        $outside = $fixtureRoot . '/retention-outside-current-' . bin2hex(random_bytes(4));
        sb_assert(wp_mkdir_p($outside), 'Could not create an outside current target.');
        sb_assert(symlink($outside, $root . '/current'), 'Could not create an escaping current pointer.');
        $expect('error', 'current pointer outside the release root');
        unlink($root . '/current');
        sb_retention_point_current($root, 'r06');

        // A symlinked releases directory makes the whole tree untrusted.
        $real_releases = $fixtureRoot . '/retention-real-releases-' . bin2hex(random_bytes(4));
        sb_assert(rename($root . '/releases', $real_releases) && symlink($real_releases, $root . '/releases'), 'Could not create a symlinked releases root.');
        $result = sb_private($plugin, 'apply_release_retention', array('manual'));
        sb_assert('error' === $result['status'], 'Retention ran through a symlinked releases root.');
        $through_link = array_values(array_diff(scandir($real_releases), array('.', '..')));
        sort($through_link);
        sb_assert($before === $through_link, 'Retention deleted through a symlinked releases root.');
        unlink($root . '/releases');
        rename($real_releases, $root . '/releases');

        $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
        sb_assert(!empty($activity) && false !== strpos(json_encode($activity, JSON_UNESCAPED_UNICODE), 'Pulizia release'), 'Refused retention runs were not logged.');
        sb_assert(empty($GLOBALS['sb_test_transients']) && false === get_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION, false), 'A refused run leaked a lock.');

        $result = sb_private($plugin, 'apply_release_retention', array('manual'));
        sb_assert('complete' === $result['status'], 'Retention did not run once every guard was clear: ' . json_encode($result));
        $deleted = $result['deleted'];
        sort($deleted);
        sb_assert(array('r01', 'r02', 'r03', 'r04', 's-abandoned') === $deleted, 'Retention with keep=1 removed an unexpected set: ' . json_encode($deleted));
        sb_assert(array('r05', 'r06') === sb_retention_listing($root), 'Retention with keep=1 did not keep exactly current and the newest previous release.');
    });
});

sb_test('Release retention finishes only its own interrupted trash directories', function () use ($plugin, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        $old = time() - 30 * 86400;
        sb_retention_release($root, 'r01', true, $old);
        sb_retention_release($root, 'r02', true, $old + 60);
        sb_retention_point_current($root, 'r02');
        sb_retention_release($root, 'r00.sb-retention-0123456789ab', false, time());
        sb_retention_release($root, 'r00.sb-retention-short', false, $old);
        sb_retention_enable(3);
        $result = sb_private($plugin, 'apply_release_retention', array('manual'));
        sb_assert('complete' === $result['status'] && array('r00.sb-retention-0123456789ab') === $result['deleted'], 'An interrupted retention trash directory was not completed: ' . json_encode($result));
        sb_assert(array('r00.sb-retention-short', 'r01', 'r02') === sb_retention_listing($root), 'Retention touched a directory that only resembles its trash pattern.');
    });
});

sb_test('A completed publication schedules deferred retention only when enabled; deactivation clears it', function () use ($plugin, $source, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin, $source) {
        sb_assert(false !== strpos(sb_method_body($source, 'publish_release'), 'schedule_release_retention('), 'publish_release does not schedule the deferred retention run.');
        sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), "wp_clear_scheduled_hook('static_bridge_release_retention')"), 'Deactivation does not clear the retention event.');
        $registered = array_filter($GLOBALS['sb_test_hooks'], function ($hook) {
            return 'static_bridge_release_retention' === $hook[0];
        });
        sb_assert(!empty($registered), 'The retention cron hook is not registered.');
        $handler_registered = array_filter($GLOBALS['sb_test_hooks'], function ($hook) {
            return 'admin_post_static_bridge_apply_retention' === $hook[0];
        });
        sb_assert(!empty($handler_registered), 'The manual retention handler is not registered as an admin-post action.');
        unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_release_retention']);
        sb_assert(false === sb_private($plugin, 'schedule_release_retention'), 'Retention was scheduled while disabled.');
        sb_retention_enable(2);
        sb_assert(true === sb_private($plugin, 'schedule_release_retention'), 'Retention was not scheduled while enabled.');
        $when = $GLOBALS['sb_test_scheduled_hooks']['static_bridge_release_retention'] ?? 0;
        sb_assert($when >= time() + 240, 'Retention was scheduled without the post-publication grace delay.');
    });
});

sb_test('The export worker lock is atomic: two requests arriving together never both run a step (2.4.0)', function () use ($plugin) {
    $name = Static_Bridge_Plugin::EXPORT_LOCK_OPTION;
    $previous = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
    try {
        unset($GLOBALS['sb_test_options'][$name]);
        $mine = sb_private($plugin, 'acquire_export_worker_lock');
        sb_assert(is_string($mine) && $mine === get_option($name)['token'], 'A free lock was not taken.');
        sb_assert(false === sb_private($plugin, 'acquire_export_worker_lock'), 'A held lock was taken a second time.');
        // Another worker's lock appears between the read and the insert: add_option() would have overwritten it.
        unset($GLOBALS['sb_test_options'][$name]);
        $GLOBALS['sb_test_options'][$name] = array('token' => 'other-worker', 'expires' => time() + 60);
        $GLOBALS['sb_test_option_read_before_race'][$name] = true;
        sb_assert(false === sb_private($plugin, 'acquire_export_worker_lock') && 'other-worker' === get_option($name)['token'], 'A lock written meanwhile by another request was overwritten.');
        sb_private($plugin, 'release_export_worker_lock', array('not-mine'));
        sb_assert('other-worker' === get_option($name)['token'], 'Another worker\'s lock was released.');
        // An expired lock is replaced; the owner releases its own.
        $GLOBALS['sb_test_options'][$name] = array('token' => 'expired-worker', 'expires' => time() - 1);
        $fresh = sb_private($plugin, 'acquire_export_worker_lock');
        sb_assert(is_string($fresh) && $fresh === get_option($name)['token'], 'An expired lock was not replaced.');
        sb_private($plugin, 'release_export_worker_lock', array($fresh));
        sb_assert(false === get_option($name, false), 'The owner could not release its lock.');
    } finally {
        unset($GLOBALS['sb_test_option_read_before_race'][$name]);
        if (null === $previous) {
            unset($GLOBALS['sb_test_options'][$name]);
        } else {
            $GLOBALS['sb_test_options'][$name] = $previous[0];
        }
    }
});

sb_test('The incremental worker lock is a row: atomic, released only by its owner, and a push waits for the worker (2.4.1)', function () use ($plugin) {
    $name = Static_Bridge_Plugin::INCREMENTAL_LOCK_OPTION;
    $previous = $GLOBALS['sb_test_options'];
    $previous_hooks = $GLOBALS['sb_test_scheduled_hooks'];
    try {
        unset($GLOBALS['sb_test_options'][$name]);
        sb_assert(false === sb_private($plugin, 'row_lock_active', array($name)), 'A free lock was reported as held.');
        $mine = sb_private($plugin, 'acquire_incremental_lock');
        sb_assert(is_string($mine) && $mine === get_option($name)['token'] && true === sb_private($plugin, 'row_lock_active', array($name)), 'A free incremental lock was not taken.');
        sb_assert(false === sb_private($plugin, 'acquire_incremental_lock'), 'A held incremental lock was taken a second time.');
        // Another request writes the lock between the read and the insert: set_transient() would have overwritten it.
        $GLOBALS['sb_test_options'][$name] = array('token' => 'cron-worker', 'expires' => time() + 60);
        $GLOBALS['sb_test_option_read_before_race'][$name] = true;
        sb_assert(false === sb_private($plugin, 'acquire_incremental_lock') && 'cron-worker' === get_option($name)['token'], 'An incremental lock written meanwhile by another request was overwritten.');
        sb_private($plugin, 'release_incremental_lock', array($mine));
        sb_assert('cron-worker' === get_option($name)['token'], 'A request released the incremental lock of another request.');

        // The cron worker that finds the lock held leaves it alone (until 2.4.0 its finally deleted any lock).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 1;
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        $GLOBALS['sb_test_scheduled_hooks'] = array();
        $plugin->process_incremental_queue();
        sb_assert('cron-worker' === get_option($name)['token'] && isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_process_incremental_queue']), 'The incremental worker did not wait for the lock held by another request.');

        // An expired lock is replaced, and the worker that took it releases it.
        $GLOBALS['sb_test_options'][$name] = array('token' => 'dead-worker', 'expires' => time() - 1);
        sb_assert(false === sb_private($plugin, 'row_lock_active', array($name)), 'An expired lock was reported as held.');
        $plugin->process_incremental_queue();
        sb_assert(false === get_option($name, false), 'The incremental worker did not take an expired lock and release it.');
        sb_assert(false !== strpos(sb_method_body(file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php'), 'process_manual_post_push_now'), 'acquire_incremental_lock()')
            && false === strpos(file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php'), "set_transient('static_bridge_incremental_lock'"), 'A path still takes the incremental lock as a transient.');
    } finally {
        unset($GLOBALS['sb_test_option_read_before_race'][$name]);
        $GLOBALS['sb_test_options'] = $previous;
        $GLOBALS['sb_test_scheduled_hooks'] = $previous_hooks;
    }
});

sb_test('A render transaction left in the request\'s option cache by another render never blocks the next one (2.4.1)', function () use ($plugin) {
    $name = Static_Bridge_Plugin::RENDER_BYPASS_OPTION;
    $previous = $GLOBALS['sb_test_options'];
    try {
        unset($GLOBALS['sb_test_options'][$name]);
        // At init this request read the transaction of a render running elsewhere; that render ended and deleted its row.
        $GLOBALS['sb_test_option_request_cache'][$name] = array('token' => str_repeat('d', 48), 'started_at' => time(), 'release_id' => '', 'routes' => array('/altra/'), 'suspended' => false, 'files' => array(), 'markers' => array());
        sb_assert(false === update_option($name, array('token' => 'x')), 'The stub does not reproduce WordPress\' failed UPDATE on a cached option without its row.');
        $context = sb_private($plugin, 'begin_dynamic_render_bypass', array(array(home_url('/x/'))));
        sb_assert(!is_wp_error($context), 'The render could not save its transaction after another render ended: ' . ($context instanceof WP_Error ? $context->get_error_message() : ''));
        sb_assert(is_array(get_option($name, false)) && $context['transaction']['token'] === get_option($name)['token'] && array('/x/') === get_option($name)['routes'], 'The stored transaction is not the one of this render.');
        $ended = sb_private($plugin, 'end_dynamic_render_bypass', array($context));
        sb_assert(true === $ended && false === get_option($name, false), 'The render transaction was not closed: ' . json_encode($ended instanceof WP_Error ? $ended->get_error_message() : $ended));
    } finally {
        unset($GLOBALS['sb_test_option_request_cache']);
        $GLOBALS['sb_test_options'] = $previous;
    }
});

sb_test('An export that saves nothing says how many pages it processed and why most stayed out (2.4.1)', function () use ($plugin) {
    $reason = 'WooCommerce: la pagina resta dinamica perché contiene nonce che Static Bridge non sa rinnovare (-1).';
    $job = array('processed' => 70, 'issues' => array(
        array('url' => home_url('/'), 'message' => $reason),
        array('url' => home_url('/shop/'), 'message' => $reason),
        array('url' => home_url('/x/'), 'message' => 'Risposta HTTP 404.'),
    ));
    $message = sb_private($plugin, 'no_page_saved_message', array($job));
    sb_assert(false !== strpos($message, '70 pagine elaborate') && false !== strpos($message, '(2): «' . $reason . '»') && false !== strpos($message, 'La versione attuale non viene sostituita.'), 'The message does not tell the pages and the main reason: ' . $message);
    sb_assert('Nessuna pagina HTML è stata salvata: la versione attuale non viene sostituita.' === sb_private($plugin, 'no_page_saved_message', array(array('processed' => 0, 'issues' => array()))), 'An export with no page processed lost its plain message.');
});

sb_test('A new site starts with retention on and one previous release; an upgraded site keeps its choice (2.4.0)', function () use ($plugin) {
    $old_options = $GLOBALS['sb_test_options'];
    $old_server_software = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    try {
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]);
        Static_Bridge_Plugin::activate();
        $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array());
        $settings = sb_private($plugin, 'settings');
        sb_assert(1 === (int) ($stored['retention_enabled'] ?? 0) && 1 === (int) ($stored['retention_keep'] ?? 0)
            && 1 === $settings['retention_enabled'] && 1 === $settings['retention_keep'], 'A new site did not start with retention on and one previous release.');
        // Settings saved by an older version have no retention keys: they stay off, with the old default count.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0, 'excluded_paths' => array('/iscriviti/'), 'incremental_enabled' => 1);
        Static_Bridge_Plugin::activate();
        $settings = sb_private($plugin, 'settings');
        sb_assert(0 === $settings['retention_enabled'] && Static_Bridge_Plugin::RETENTION_DEFAULT_KEEP === $settings['retention_keep']
            && !isset(get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array())['retention_enabled']), 'An upgraded site had retention switched on or its settings rewritten.');
    } finally {
        $GLOBALS['sb_test_options'] = $old_options;
        if (null === $old_server_software) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server_software;
        }
    }
});

sb_test('Versioni (2.4.0): releases as blocks, protected ones locked, one-by-one and bulk deletion with capability, nonce and safe names', function () use ($plugin, $fixtureRoot) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        sb_assert(1 === sb_private($plugin, 'sanitize_retention_keep', array(0)) && 20 === sb_private($plugin, 'sanitize_retention_keep', array(99))
            && 3 === sb_private($plugin, 'sanitize_retention_keep', array('abc')) && 5 === sb_private($plugin, 'sanitize_retention_keep', array('5')), 'The retained-release count is not clamped to 1..20.');
        $old = time() - 30 * 86400;
        foreach (array('r01', 'r02', 'r03', 'r04', 'r05') as $index => $id) {
            sb_retention_release($root, $id, true, $old + $index * 60);
        }
        sb_retention_point_current($root, 'r05');
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => 'r01', 'published_at' => $old);
        $previous_get = $_GET;
        $buffer_level = ob_get_level();
        $render = function ($tab) use ($plugin) {
            $_GET = array('tab' => $tab);
            ob_start();
            $plugin->render_admin_page();
            return ob_get_clean();
        };
        try {
            // An upgraded site keeps retention off: the switch is unchecked and Versioni offers it, deleting nothing.
            $settings_html = $render('settings');
            sb_assert(1 === preg_match('/<input[^>]*name="retention_enabled"[^>]*>/', $settings_html, $retention_input) && false === strpos($retention_input[0], 'checked'), 'An upgraded site shows retention switched on.');
            sb_assert(false !== strpos($settings_html, 'name="retention_keep"') && false !== strpos($settings_html, 'tab=versions'), 'Settings or the tab bar lack the retention count or Versioni.');
            $activity_html = $render('activity');
            sb_assert(false !== strpos($activity_html, 'tab=versions') && false === strpos($activity_html, 'static_bridge_apply_retention'), 'Activity does not point to Versioni.');
            $html = $render('versions');
            sb_assert(false !== strpos($html, 'static_bridge_enable_retention') && false !== strpos($html, 'La pulizia automatica è spenta'), 'Versioni does not offer retention on an upgraded site.');
            sb_assert(false !== strpos($html, 'static_bridge_cleanup_releases') && 1 === substr_count($html, 'name="action" value="static_bridge_cleanup_releases"'), 'Versioni does not offer the bulk cleanup.');
            foreach (array('r02', 'r03', 'r04') as $name) {
                sb_assert(false !== strpos($html, 'name="release" value="' . $name . '"'), 'Versioni has no delete button for ' . $name);
            }
            foreach (array('r05', 'r01') as $name) {
                sb_assert(false === strpos($html, 'name="release" value="' . $name . '"') && false !== strpos($html, '<code>' . $name . '</code>'), 'Versioni lets the protected ' . $name . ' be deleted, or hides it.');
            }
            sb_assert(false !== strpos($html, 'Online') && false !== strpos($html, 'Release registrata per il ripristino') && false !== strpos($html, 'data-sb-confirm='), 'Versioni lacks the states, the protection reason or the confirmation.');
            sb_retention_enable(2);
            $enabled_html = $render('versions');
            sb_assert(false === strpos($enabled_html, 'static_bridge_enable_retention') && false !== strpos($enabled_html, 'Pulizia automatica attiva'), 'Versioni still offers retention once it is on.');
        } finally {
            while (ob_get_level() > $buffer_level) {
                ob_end_clean();
            }
            $_GET = $previous_get;
        }

        $before = sb_retention_listing($root);
        foreach (array('handle_apply_retention', 'handle_delete_release', 'handle_cleanup_releases', 'handle_enable_retention') as $handler) {
            $_POST = array('release' => 'r02');
            $GLOBALS['sb_test_can_manage'] = false;
            try {
                $plugin->$handler();
                throw new RuntimeException($handler . ' ran without manage_options.');
            } catch (SB_Test_WP_Die $expected) {
            } finally {
                $GLOBALS['sb_test_can_manage'] = true;
            }
            $GLOBALS['sb_test_nonce_valid'] = false;
            try {
                $plugin->$handler();
                throw new RuntimeException($handler . ' ran without a valid nonce.');
            } catch (RuntimeException $expected) {
                sb_assert('Invalid admin nonce' === $expected->getMessage(), $handler . ' did not check the admin nonce.');
            } finally {
                $GLOBALS['sb_test_nonce_valid'] = true;
            }
        }
        // Names that are not a direct child of releases/ stop before the nonce, whatever the nonce says.
        foreach (array('../r02', 'r02/../r03', '.', '..', 'r02/', '/tmp/x', "r02\0", 'r02 ', str_repeat('a', 101), 'r02.sb-retention-zz') as $bad) {
            $_POST = array('release' => $bad);
            try {
                $plugin->handle_delete_release();
                throw new RuntimeException('A bad release name reached the deletion: ' . json_encode($bad));
            } catch (SB_Test_WP_Die $expected) {
            }
        }
        $_POST = array();
        sb_assert($before === sb_retention_listing($root), 'A rejected request deleted releases.');

        // From Versioni, also with retention off: the online release and protected ones are refused, one release goes.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['retention_enabled'] = 0;
        $refused = sb_private($plugin, 'apply_release_retention', array('versions', array('r05', 'r01', 'current', 'nope')));
        sb_assert(array() === $refused['deleted'] && 4 === count($refused['refused']) && $before === sb_retention_listing($root), 'Versioni deleted the online, a protected or an unknown release: ' . json_encode($refused));
        $one = sb_private($plugin, 'apply_release_retention', array('versions', array('r02')));
        sb_assert(array('r02') === $one['deleted'] && !is_dir($root . '/releases/r02') && is_dir($root . '/releases/r03') && is_dir($root . '/releases/r04')
            && false !== strpos($one['message'], 'r02') && false === strpos($one['message'], 'release pronte più recenti'), 'Deleting one release from Versioni did not delete exactly that one: ' . json_encode($one));
        // The cron with retention off still deletes nothing: the bulk cleanup is a choice made in Versioni.
        sb_assert('disabled' === sb_private($plugin, 'apply_release_retention', array('cron'))['status'] && is_dir($root . '/releases/r03'), 'The cron deleted with retention off.');
        $bulk = sb_private($plugin, 'apply_release_retention', array('versions'));
        sb_assert(array('r03') === $bulk['deleted'] && is_dir($root . '/releases/r04') && is_dir($root . '/releases/r01') && is_dir($root . '/releases/r05'), 'The bulk cleanup did not keep the online release, one previous and the protected one: ' . json_encode($bulk));
    });
});


/**
 * A page as Fluent Forms 6.2.x renders it for an anonymous visitor: localized
 * fluentFormVars (with token_nonce when token protection is on), a per-page
 * embed id, the submit nonce, its referer field and the empty token field.
 */
function sb_ff_fixture_page($options = array())
{
    $options = array_merge(array(
        'form_id' => 3,
        'token_field' => true,
        'token_nonce_var' => true,
        'submit_nonce' => true,
        'vars' => true,
        'post_id' => 41,
        'footer' => false,
    ), $options);
    $id = (int) $options['form_id'];
    $vars = $options['vars']
        ? '<script id="fluent-form-submission-js-extra">var fluentFormVars = {"ajaxUrl":"https:\/\/news.example.test:8443\/wordpress\/wp-admin\/admin-ajax.php","forms":[],"nonce":"aa11bb22cc","file_delete_nonce":"dd33ee44ff","fluentform_version":"6.2.15"'
            . ($options['token_nonce_var'] ? ',"token_nonce":"0123456789"' : '') . '};</script>'
        : '';
    $form = "<div class='fluentform ff-default fluentform_wrapper_{$id}'><form data-form_id=\"{$id}\" id=\"fluentform_{$id}\" class=\"frm-fluent-form fluent_form_{$id} ff-el-form-top ff_form_instance_{$id}_1 ff-form-loading\" data-form_instance=\"ff_form_instance_{$id}_1\" method=\"POST\" ><fieldset><legend class=\"ff_screen_reader_title\">Contatti</legend>"
        . ($options['token_field'] ? "<input type=\"hidden\" id=\"__fluent_protection_token_{$id}\" class=\"fluent-form-token-field\" name=\"__fluent_protection_token_{$id}\">" : '')
        . "<input type='hidden' name='__fluent_form_embded_post_id' value='" . (int) $options['post_id'] . "' />"
        . ($options['submit_nonce'] ? "<input type=\"hidden\" id=\"_fluentform_{$id}_fluentformnonce\" name=\"_fluentform_{$id}_fluentformnonce\" value=\"9876543210\" /><input type=\"hidden\" name=\"_wp_http_referer\" value=\"/chi-siamo/\" />" : '')
        . "<div class='ff-el-group'><input type=\"email\" name=\"email\" class=\"ff-el-form-control\"></div><button type=\"submit\" class=\"ff-btn ff-btn-submit\">Invia</button></fieldset></form></div>";
    $main = $options['footer'] ? '<main><p>Articolo senza modulo nel contenuto.</p></main><footer class="site-footer">' . $form . '</footer>' : '<main>' . $form . '</main>';
    return '<!doctype html><html lang="it"><head><meta charset="utf-8"><title>Pagina</title></head><body>'
        . $main . $vars
        . '<script src="https://news.example.test:8443/wordpress/wp-content/plugins/fluentform/assets/js/form-submission.js?ver=6.2.15" id="fluent-form-submission-js"></script></body></html>';
}

function sb_ff_reset_state()
{
    foreach (array('token_protected_form_paths_cache', 'fluent_forms_dynamic_routes_cache') as $name) {
        if (property_exists(Static_Bridge_Plugin::class, $name)) {
            $property = new ReflectionProperty(Static_Bridge_Plugin::class, $name);
            if (PHP_VERSION_ID < 80100) {
                $property->setAccessible(true);
            }
            $property->setValue($GLOBALS['plugin'], null);
        }
    }
}

sb_test('Fluent Forms static pages: token-protected routes stay static by default and the nonce refresher is injected', function () use ($plugin) {
    $previous = array('options' => $GLOBALS['sb_test_options'], 'filters' => $GLOBALS['sb_test_filter_values'], 'posts' => $GLOBALS['sb_test_posts'], 'post_types' => $GLOBALS['sb_test_post_types'], 'post_urls' => $GLOBALS['sb_test_post_urls'], 'post_queries' => $GLOBALS['sb_test_post_queries']);
    try {
        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(array('ID' => 41, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Chi siamo', 'post_content' => '[fluentform id="3"]', 'meta' => array()));
        $GLOBALS['sb_test_post_urls'] = array(41 => home_url('/chi-siamo/'));
        $GLOBALS['sb_test_post_queries'] = array();
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
            '_fluentform_global_form_settings' => array('misc' => array('tokenBasedProtectionStatus' => 'yes')),
        );
        sb_ff_reset_state();

        $pages = sb_private($plugin, 'discover_form_pages');
        sb_assert(1 === count($pages) && !empty($pages[0]['token_protection_enabled']), 'The token-protected fixture page was not discovered.');
        sb_assert('static' === $pages[0]['mode'], 'With nonce refresh enabled (the default) a token-protected page is still forced dynamic.');
        $settings = sb_private($plugin, 'settings');
        sb_assert(!in_array('/chi-siamo/', $settings['excluded_paths'], true), 'The token-protected page is still excluded from the static export.');
        sb_assert(!in_array('/chi-siamo/', sb_private($plugin, 'routing_excluded_paths'), true) || !$pages[0]['file_exists'], 'The token-protected page is still routed dynamically.');

        $html = sb_ff_fixture_page();
        $prepared = sb_private($plugin, 'prepare_fluent_forms_static_html', array(home_url('/chi-siamo/'), $html));
        sb_assert(is_string($prepared), 'Valid Fluent Forms markup was rejected: ' . (is_wp_error($prepared) ? $prepared->get_error_message() : gettype($prepared)));
        sb_assert(1 === substr_count($prepared, 'id="static-bridge-fluent-forms"'), 'The nonce refresher was not injected exactly once.');
        sb_assert(1 === preg_match('~<script id="static-bridge-fluent-forms" src="[^"]*/static-bridge/assets/fluent-forms-static\.js\?ver=' . preg_quote(Static_Bridge_Plugin::VERSION, '~') . '" data-endpoint="[^"]*/wp-admin/admin-ajax\.php" defer></script></head>~', $prepared), 'The refresher tag is not a deferred head script pointing at admin-ajax.php.');
        sb_assert($html === str_replace(substr($prepared, strpos($prepared, '<script id="static-bridge-fluent-forms"'), strpos($prepared, '</head>') - strpos($prepared, '<script id="static-bridge-fluent-forms"')), '', $prepared), 'Injecting the refresher changed other bytes of the page (per-page fields must stay as rendered).');
        sb_assert(false !== strpos($prepared, "name='__fluent_form_embded_post_id' value='41'") && false !== strpos($prepared, 'name="_wp_http_referer" value="/chi-siamo/"'), 'Per-page Fluent Forms hidden fields were altered.');
        sb_assert($prepared === sb_private($plugin, 'prepare_fluent_forms_static_html', array(home_url('/chi-siamo/'), $prepared)), 'Preparing an already prepared page injected a second refresher.');

        $footer = sb_ff_fixture_page(array('footer' => true, 'post_id' => 77));
        $prepared_footer = sb_private($plugin, 'prepare_fluent_forms_static_html', array(home_url('/notizie/articolo/'), $footer));
        sb_assert(is_string($prepared_footer) && 1 === substr_count($prepared_footer, 'id="static-bridge-fluent-forms"'), 'A form in a global footer did not get the nonce refresher.');

        $plain = '<!doctype html><html><head><title>x</title></head><body><p>Nessun modulo</p></body></html>';
        sb_assert($plain === sb_private($plugin, 'prepare_fluent_forms_static_html', array(home_url('/altro/'), $plain)), 'A page without Fluent Forms was modified.');

        // Opt-out restores the 2.0.15 behaviour exactly: token pages dynamic, no injection.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FLUENT_FORMS_REFRESH_OPTION] = 0;
        sb_ff_reset_state();
        $pages_off = sb_private($plugin, 'discover_form_pages');
        sb_assert('dynamic' === $pages_off[0]['mode'], 'With nonce refresh disabled a token-protected page is not dynamic any more.');
        sb_assert(in_array('/chi-siamo/', sb_private($plugin, 'settings')['excluded_paths'], true), 'With nonce refresh disabled the token page is not excluded.');
        sb_assert($html === sb_private($plugin, 'prepare_fluent_forms_static_html', array(home_url('/chi-siamo/'), $html)), 'With nonce refresh disabled the refresher was still injected.');
    } finally {
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_filter_values'] = $previous['filters'];
        $GLOBALS['sb_test_posts'] = $previous['posts'];
        $GLOBALS['sb_test_post_types'] = $previous['post_types'];
        $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
        $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
        sb_ff_reset_state();
    }
});

sb_test('Fluent Forms static pages: missing markers fall back to WordPress dynamic per route and recover', function () use ($plugin) {
    $previous = array('options' => $GLOBALS['sb_test_options'], 'filters' => $GLOBALS['sb_test_filter_values']);
    try {
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
            '_fluentform_global_form_settings' => array('misc' => array('tokenBasedProtectionStatus' => 'yes')),
        );
        sb_ff_reset_state();
        $url = home_url('/chi-siamo/');
        $cases = array(
            'token_nonce missing from fluentFormVars' => array('token_nonce_var' => false),
            'empty token field missing' => array('token_field' => false),
            'fluentFormVars missing' => array('vars' => false),
            'submit nonce missing' => array('submit_nonce' => false),
        );
        foreach ($cases as $label => $case) {
            $result = sb_private($plugin, 'prepare_fluent_forms_static_html', array($url, sb_ff_fixture_page($case)));
            sb_assert(is_wp_error($result) && 'static_bridge_fluentforms_dynamic' === $result->get_error_code(), 'Drift case "' . $label . '" did not fall back to a dynamic route.');
        }
        sb_assert(true === sb_private($plugin, 'record_fluent_forms_dynamic_route', array('/chi-siamo/', 'token_nonce assente', array('3'))), 'The drift fallback could not be recorded.');
        sb_ff_reset_state();
        $routes = sb_private($plugin, 'fluent_forms_dynamic_routes');
        sb_assert(isset($routes['/chi-siamo/']) && array('3') === $routes['/chi-siamo/']['form_ids'], 'The drift fallback was not persisted per route.');
        sb_assert(in_array('/chi-siamo/', sb_private($plugin, 'routing_excluded_paths'), true), 'A drift route is not routed to WordPress (Strict mode would answer 404).');
        sb_assert(!sb_private($plugin, 'is_excluded_path', array('/chi-siamo/')), 'A drift route is excluded from the export, so it could never recover after a Fluent Forms update.');

        // Without token protection and without nonce verification nothing expires: keep the 2.0.15 static copy.
        $GLOBALS['sb_test_options']['_fluentform_global_form_settings'] = array('misc' => array('tokenBasedProtectionStatus' => 'no'));
        $untouched = sb_ff_fixture_page(array('token_field' => false, 'token_nonce_var' => false, 'submit_nonce' => false));
        sb_assert($untouched === sb_private($plugin, 'prepare_fluent_forms_static_html', array($url, $untouched)), 'A non-expiring form with unknown markup was not kept as the plain static copy.');
        $GLOBALS['sb_test_filter_values']['fluentform/nonce_verify'] = true;
        $verify = sb_private($plugin, 'prepare_fluent_forms_static_html', array($url, $untouched));
        sb_assert(is_wp_error($verify), 'With fluentform/nonce_verify on, a form without the submit nonce field was published static.');
        $refreshed = sb_private($plugin, 'prepare_fluent_forms_static_html', array($url, sb_ff_fixture_page(array('token_field' => false, 'token_nonce_var' => false))));
        sb_assert(is_string($refreshed) && false !== strpos($refreshed, 'id="static-bridge-fluent-forms"'), 'With fluentform/nonce_verify on, the submit nonce is not refreshed on the static page.');

        sb_assert(true === sb_private($plugin, 'forget_fluent_forms_dynamic_route', array('/chi-siamo/')), 'A recovered route could not be removed from the drift list.');
        sb_ff_reset_state();
        sb_assert(!in_array('/chi-siamo/', sb_private($plugin, 'routing_excluded_paths'), true), 'A recovered route is still routed dynamically.');
    } finally {
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_filter_values'] = $previous['filters'];
        sb_ff_reset_state();
    }
});

sb_test('Fluent Forms static pages: export and incremental writers apply the refresher or the dynamic fallback before writing', function () use ($source) {
    $export = sb_method_body($source, 'run_export_queue_step');
    $publish = sb_method_body($source, 'publish_release');
    // 2.2.13: prepare_static_html() runs the Fluent Forms preparation, then the WooCommerce one.
    sb_assert(false !== strpos(sb_method_body($source, 'prepare_static_html'), '$this->prepare_fluent_forms_static_html($url, $result[\'body\'])'), 'prepare_static_html() no longer prepares Fluent Forms pages.');
    sb_assert(false !== strpos(sb_method_body($source, 'record_dynamic_route_for'), 'record_fluent_forms_dynamic_route('), 'A refused Fluent Forms page is no longer recorded as dynamic.');
    $prepare = strpos($export, '$this->prepare_static_html($url, $result)');
    $write = strpos($export, '$this->write_export_page($job, $relative, $');
    sb_assert(false !== $prepare && false !== $write && $prepare < $write, 'The full export does not prepare Fluent Forms pages before writing them.');
    sb_assert(false !== strpos($export, "'static_bridge_fluentforms_dynamic'") && false !== strpos($export, 'record_dynamic_route_for('), 'The full export does not turn a drift route into a recorded dynamic skip.');
    sb_assert(1 === preg_match('/record_dynamic_route_for\(.*?extract_internal_links\(\$result\[\'body\'\], \$url\).*?\$this->write_export_page/s', $export), 'A drift route no longer feeds link discovery, so pages reachable only through it are lost.');
    sb_assert(1 === preg_match('/finally \{\s*if \(\$fluent_forms_routing_changed\) \{\s*\$this->update_routing_rules\(\);/', $export), 'A new drift route is routed to WordPress only at publication; a refused publication would leave stale copies in front.');
    sb_assert(false !== strpos($publish, '$this->prune_fluent_forms_dynamic_routes();'), 'A publication does not clear drift routes that have a static file again.');
    sb_assert(false !== strpos(sb_method_body($source, 'process_incremental_item'), 'forget_fluent_forms_dynamic_route($path)'), 'A successful incremental write does not clear the drift route.');
    $incremental = sb_method_body($source, 'process_incremental_item');
    $prepare = strpos($incremental, '$this->prepare_static_html($url, $result)');
    $write = strpos($incremental, '$this->write_incremental_page($release, $url, $');
    sb_assert(false !== $prepare && false !== $write && $prepare < $write, 'Incremental and manual pushes do not prepare Fluent Forms pages before writing them.');
    sb_assert(false !== strpos($incremental, 'record_dynamic_route_for(') && false !== strpos($incremental, 'remove_incremental_page($release, $url)'), 'An incremental drift route does not remove the stale static copy and record the dynamic fallback.');
});

sb_test('Fluent Forms static pages: the public nonce endpoint returns only fresh fixed-action nonces, never cached', function () use ($plugin, $source) {
    $previous = array('options' => $GLOBALS['sb_test_options'], 'filters' => $GLOBALS['sb_test_filter_values'], 'post' => $_POST, 'request' => $_REQUEST);
    $hooks = array();
    foreach ($GLOBALS['sb_test_hooks'] as $hook) {
        $hooks[$hook[0]] = $hook[1];
    }
    sb_assert(isset($hooks['wp_ajax_nopriv_static_bridge_public_form_nonces'], $hooks['wp_ajax_static_bridge_public_form_nonces']), 'The nonce endpoint is not registered for anonymous and logged-in visitors.');
    $body = sb_method_body($source, 'ajax_public_form_nonces');
    sb_assert(false !== strpos($body, 'nocache_headers()') && false !== strpos($body, 'no-store'), 'The nonce endpoint does not forbid caching.');
    sb_assert(false === strpos($body, '$_POST') && false === strpos($body, '$_GET') && false === strpos($body, '$_REQUEST'), 'The nonce endpoint reads request input; it must return a fixed set of nonces.');
    $call = static function () use ($plugin) {
        try {
            $plugin->ajax_public_form_nonces();
        } catch (SB_Test_Response $response) {
            return $response;
        }
        throw new RuntimeException('The nonce endpoint did not send a JSON response.');
    };
    try {
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_options'] = array('_fluentform_global_form_settings' => array('misc' => array('tokenBasedProtectionStatus' => 'yes')));
        if (!defined('FLUENTFORM_VERSION')) {
            $inactive = $call();
            sb_assert(200 !== $inactive->status, 'The nonce endpoint answered while Fluent Forms is inactive.');
            define('FLUENTFORM_VERSION', '6.2.15');
        }
        $_POST = $_REQUEST = array('action' => 'static_bridge_public_form_nonces', 'form_ids' => '3', 'nonce_action' => 'static_bridge_admin');
        $GLOBALS['sb_test_nonce_tick'] = 100;
        $first = $call();
        sb_assert(200 === $first->status && is_array($first->data), 'The nonce endpoint did not answer for an active Fluent Forms.');
        sb_assert(array('file_delete_nonce', 'submit_nonce', 'token_nonce', 'ttl', 'vars_nonce') === (function ($keys) { sort($keys); return $keys; })(array_keys($first->data)), 'The nonce endpoint returns unexpected fields.');
        sb_assert(wp_create_nonce('fluentform_generate_token_nonce') === $first->data['token_nonce']
            && wp_create_nonce('fluentform-submit-form') === $first->data['submit_nonce']
            && wp_create_nonce('fluentform_file_delete') === $first->data['file_delete_nonce']
            && wp_create_nonce() === $first->data['vars_nonce'], 'The endpoint nonces are not the Fluent Forms actions WordPress verifies (fluentFormVars.nonce has no action).');
        sb_assert(!in_array(wp_create_nonce('static_bridge_admin'), $first->data, true), 'The endpoint leaked a nonce for an action chosen by the request.');
        sb_assert(is_int($first->data['ttl']) && $first->data['ttl'] >= 60, 'The endpoint does not tell the page how long the nonces stay valid.');
        // Simulated expiry: two nonce ticks later the page must receive different, current values.
        $GLOBALS['sb_test_nonce_tick'] = 102;
        $later = $call();
        sb_assert($later->data['token_nonce'] !== $first->data['token_nonce'] && wp_create_nonce('fluentform_generate_token_nonce') === $later->data['token_nonce'], 'After the original nonce lifetime the endpoint did not return a fresh token_nonce.');

        $GLOBALS['sb_test_options']['_fluentform_global_form_settings'] = array('misc' => array('tokenBasedProtectionStatus' => 'no'));
        $no_token = $call();
        sb_assert(200 === $no_token->status && !isset($no_token->data['token_nonce']) && isset($no_token->data['submit_nonce']), 'Without token protection the endpoint should only refresh the submit and file nonces.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FLUENT_FORMS_REFRESH_OPTION] = 0;
        $disabled = $call();
        sb_assert(200 !== $disabled->status, 'The nonce endpoint answered while the refresh is disabled in the Moduli tab.');
    } finally {
        unset($GLOBALS['sb_test_nonce_tick']);
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_filter_values'] = $previous['filters'];
        $_POST = $previous['post'];
        $_REQUEST = $previous['request'];
    }
});

sb_test('Fluent Forms static pages: the Moduli tab exposes the refresh switch, per-page state and drift reasons', function () use ($plugin, $source) {
    $previous = array('options' => $GLOBALS['sb_test_options'], 'filters' => $GLOBALS['sb_test_filter_values'], 'posts' => $GLOBALS['sb_test_posts'], 'post_types' => $GLOBALS['sb_test_post_types'], 'post_urls' => $GLOBALS['sb_test_post_urls'], 'post_queries' => $GLOBALS['sb_test_post_queries'], 'get' => $_GET);
    $buffer_level = ob_get_level();
    try {
        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true, 'publicly_queryable' => true));
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 41, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Chi siamo', 'post_content' => '[fluentform id="3"]', 'meta' => array()),
            array('ID' => 42, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Iscrizioni', 'post_content' => '[fluentform id="5"]', 'meta' => array()),
        );
        $GLOBALS['sb_test_post_urls'] = array(41 => home_url('/chi-siamo/'), 42 => home_url('/iscrizioni/'));
        $GLOBALS['sb_test_post_queries'] = array();
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('excluded_paths' => array()),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
            '_fluentform_global_form_settings' => array('misc' => array('tokenBasedProtectionStatus' => 'yes')),
            Static_Bridge_Plugin::FLUENT_FORMS_DYNAMIC_OPTION => array('/iscrizioni/' => array('reason' => 'token_nonce assente in fluentFormVars', 'form_ids' => array('5'), 'at' => time())),
        );
        sb_ff_reset_state();
        $pages = array();
        foreach (sb_private($plugin, 'discover_form_pages') as $page) {
            $pages[$page['path']] = $page;
        }
        sb_assert('static' === $pages['/chi-siamo/']['mode'] && 'dynamic' === $pages['/iscrizioni/']['mode'], 'The drift route is not shown as dynamic while the healthy token page is static.');
        $_GET = array('tab' => 'forms');
        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();
        sb_assert(false !== strpos($html, 'name="action" value="static_bridge_save_form_nonce_refresh"') && 1 === preg_match('/<input[^>]+name="fluent_forms_nonce_refresh"[^>]+checked/', $html), 'The Moduli tab does not show the enabled nonce refresh switch.');
        sb_assert(false !== strpos($html, 'token_nonce assente in fluentFormVars'), 'The Moduli tab does not explain why a route fell back to dynamic.');
        sb_assert(false !== strpos($html, 'rinnova nonce e token'), 'The Moduli tab does not explain that token-protected static pages refresh their nonces.');
        sb_assert(0 === preg_match('/<select\b[^>]*\bid="sb-form-mode-0"[^>]*\bdisabled/i', $html), 'A healthy token-protected page cannot be switched between static and dynamic.');

        $handler = sb_method_body($source, 'save_form_nonce_refresh');
        sb_assert(false !== strpos($handler, "current_user_can('manage_options')") && false !== strpos($handler, "check_admin_referer('static_bridge_save_form_nonce_refresh')"), 'The refresh switch handler lacks capability or nonce checks.');
        sb_assert(false !== strpos($handler, 'update_routing_rules()'), 'Changing the refresh switch does not rewrite the routing rules.');
    } finally {
        while (ob_get_level() > $buffer_level) {
            ob_end_clean();
        }
        $_GET = $previous['get'];
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_filter_values'] = $previous['filters'];
        $GLOBALS['sb_test_posts'] = $previous['posts'];
        $GLOBALS['sb_test_post_types'] = $previous['post_types'];
        $GLOBALS['sb_test_post_urls'] = $previous['post_urls'];
        $GLOBALS['sb_test_post_queries'] = $previous['post_queries'];
        sb_ff_reset_state();
    }
});

// ---------------------------------------------------------------------------
// Cloudflare compatibility (2.0.17): render origin, CDN challenges, purge,
// Cache Rule expression, optional Cache-Control and Cloudflare diagnostics.
// ---------------------------------------------------------------------------

function sb_cf_options_isolated(callable $callback)
{
    $names = array(
        Static_Bridge_Plugin::SETTINGS_OPTION,
        Static_Bridge_Plugin::ACTIVITY_OPTION,
        Static_Bridge_Plugin::FORM_MODES_OPTION,
        Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION,
        'static_bridge_cloudflare_purge_pending',
        'static_bridge_cloudflare_purge_last',
    );
    $previous = array();
    foreach ($names as $name) {
        $previous[$name] = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
        unset($GLOBALS['sb_test_options'][$name]);
    }
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
    $previous_home = $GLOBALS['sb_test_home'];
    $previous_callback = $GLOBALS['sb_test_http_callback'];
    $previous_post_callback = $GLOBALS['sb_test_http_post_callback'];
    $previous_scheduled = $GLOBALS['sb_test_scheduled_hooks'];
    $previous_transients = $GLOBALS['sb_test_transients'];
    $previous_server = isset($_SERVER['SERVER_SOFTWARE']) ? array($_SERVER['SERVER_SOFTWARE']) : null;
    $GLOBALS['sb_test_http_calls'] = array();
    try {
        $callback();
    } finally {
        foreach ($previous as $name => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$name]);
            } else {
                $GLOBALS['sb_test_options'][$name] = $value[0];
            }
        }
        $GLOBALS['sb_test_home'] = $previous_home;
        $GLOBALS['sb_test_http_callback'] = $previous_callback;
        $GLOBALS['sb_test_http_post_callback'] = $previous_post_callback;
        $GLOBALS['sb_test_scheduled_hooks'] = $previous_scheduled;
        $GLOBALS['sb_test_transients'] = $previous_transients;
        if (null === $previous_server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $previous_server[0];
        }
        $GLOBALS['sb_test_http_calls'] = array();
    }
}

function sb_cf_settings(array $overrides = array())
{
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge(array(
        'strict_mode' => 1,
        'excluded_paths' => array('/iscriviti/', '/contatti/'),
        'woocommerce_enabled' => 0,
        'incremental_enabled' => 1,
    ), $overrides);
}

/** Emulates WordPress' cURL transport: runs the http_api_curl actions registered at call time, then the request. */
function sb_cf_curl_transport($url, $args)
{
    $handle = curl_init($url);
    $headers = array();
    foreach (isset($args['headers']) && is_array($args['headers']) ? $args['headers'] : array() as $name => $value) {
        $headers[] = $name . ': ' . $value;
    }
    curl_setopt_array($handle, array(
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HEADER => true,
        CURLOPT_FOLLOWLOCATION => false,
        CURLOPT_TIMEOUT => 5,
        CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_HTTPHEADER => $headers,
    ));
    foreach ($GLOBALS['sb_test_hooks'] as $hook) {
        if ('http_api_curl' === $hook[0] && is_callable($hook[1])) {
            $callback = $hook[1];
            $callback($handle, $args, $url);
        }
    }
    $raw = curl_exec($handle);
    if (false === $raw) {
        return new WP_Error('http_request_failed', curl_error($handle));
    }
    $header_size = (int) curl_getinfo($handle, CURLINFO_HEADER_SIZE);
    $response_headers = array();
    foreach (preg_split('/\r\n/', substr($raw, 0, $header_size)) as $line) {
        if (false !== strpos($line, ':')) {
            list($name, $value) = explode(':', $line, 2);
            $response_headers[strtolower(trim($name))] = trim($value);
        }
    }
    return array(
        'response' => array('code' => (int) curl_getinfo($handle, CURLINFO_RESPONSE_CODE)),
        'headers' => $response_headers,
        'body' => (string) substr($raw, $header_size),
    );
}

function sb_cf_free_port()
{
    $socket = stream_socket_server('tcp://127.0.0.1:0', $error, $message);
    if (false === $socket) {
        throw new RuntimeException('Could not reserve a local port: ' . $message);
    }
    $port = (int) substr(strrchr((string) stream_socket_get_name($socket, false), ':'), 1);
    fclose($socket);
    return $port;
}

sb_test('Render origin address accepts only a literal IP and optional port, never a hostname or unsafe range', function () use ($plugin) {
    $sanitize = function ($value) use ($plugin) { return sb_private($plugin, 'sanitize_render_origin', array($value)); };
    foreach (array(
        '' => '',
        '  ' => '',
        '127.0.0.1' => '127.0.0.1',
        ' 203.0.113.10 ' => '203.0.113.10',
        '203.0.113.10:8443' => '203.0.113.10:8443',
        '10.0.0.5:80' => '10.0.0.5:80',
        '[::1]' => '[::1]',
        '[2001:DB8:0::1]:8443' => '[2001:db8::1]:8443',
        '[2001:db8::1]:443' => '[2001:db8::1]:443',
        '[2001:db8::1]' => '[2001:db8::1]',
    ) as $input => $expected) {
        $actual = $sanitize($input);
        sb_assert($expected === $actual, 'Render origin ' . json_encode($input) . ' was normalized to ' . json_encode(is_wp_error($actual) ? $actual->get_error_code() : $actual) . ' instead of ' . json_encode($expected) . '.');
    }
    foreach (array('origin.example.com', 'localhost', 'http://127.0.0.1', '127.0.0.1/evil', "127.0.0.1\nX: y", '127.0.0.1:0', '127.0.0.1:70000',
        '127.0.0.1:80:81', '::1', '[::ffff:10.0.0.1]', '010.0.0.1', '0.0.0.0', '169.254.169.254', '224.0.0.1', '255.255.255.255', '240.0.0.1', '::', 'fe80::1', 'ff02::1', '2001:db8::1:443', '[2001:db8::1', '1.2.3') as $hostile) {
        sb_assert(is_wp_error($sanitize($hostile)), 'Unsafe render origin ' . json_encode($hostile) . ' was accepted.');
    }
});

sb_test('Render requests connect to the configured origin while keeping the same-site URL, Host and TLS name', function () use ($plugin, $source) {
    if (!function_exists('curl_init') || !defined('CURLOPT_CONNECT_TO') || !function_exists('proc_open')) {
        throw new SB_Test_Skip('cURL with CURLOPT_CONNECT_TO and proc_open are required for the origin connection check.');
    }
    sb_cf_options_isolated(function () use ($plugin, $source) {
        $origin_port = sb_cf_free_port();
        $public_port = sb_cf_free_port();
        $router = sys_get_temp_dir() . '/sb-origin-router-' . getmypid() . '-' . bin2hex(random_bytes(4)) . '.php';
        file_put_contents($router, '<?php header("Content-Type: text/html"); echo json_encode(array("origin" => true, "host" => $_SERVER["HTTP_HOST"] ?? "", "uri" => $_SERVER["REQUEST_URI"] ?? ""));');
        $process = proc_open(array(PHP_BINARY, '-n', '-S', '127.0.0.1:' . $origin_port, $router), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', '/dev/null', 'a'), 2 => array('file', '/dev/null', 'a')), $pipes);
        sb_assert(is_resource($process), 'Could not start the local origin fixture.');
        try {
            $deadline = microtime(true) + 5;
            do {
                $probe = @fsockopen('127.0.0.1', $origin_port, $errno, $errstr, 0.2);
                if ($probe) {
                    fclose($probe);
                    break;
                }
                usleep(50000);
            } while (microtime(true) < $deadline);

            // The public name does not resolve: only the configured connect-to address can reach a server.
            $GLOBALS['sb_test_home'] = 'http://origin-probe.invalid:' . $public_port;
            $GLOBALS['sb_test_http_callback'] = 'sb_cf_curl_transport';
            $url = home_url('/hello-world/');

            sb_cf_settings();
            $public = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(is_wp_error($public), 'Without a render origin the request unexpectedly reached a server.');

            sb_cf_settings(array('render_origin' => '127.0.0.1:' . $origin_port));
            sb_assert('origin-probe.invalid:' . $public_port . ':127.0.0.1:' . $origin_port === sb_private($plugin, 'render_origin_connect_to', array($url)), 'The cURL connect-to mapping does not keep the public host and port.');
            $response = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(!is_wp_error($response), 'The render request did not reach the configured origin: ' . (is_wp_error($response) ? $response->get_error_message() : ''));
            $echo = json_decode(wp_remote_retrieve_body($response), true);
            sb_assert(is_array($echo) && !empty($echo['origin']) && 'origin-probe.invalid:' . $public_port === $echo['host'] && '/hello-world/' === $echo['uri'], 'The origin did not receive the public Host header and path: ' . wp_remote_retrieve_body($response));
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                sb_assert('http_api_curl' !== $hook[0], 'The temporary http_api_curl hook stayed registered (it would disable the parallel transport).');
            }

            $diagnostic_public = sb_private($plugin, 'remote_get', array($url, 5, 4096));
            sb_assert(is_wp_error($diagnostic_public), 'A public (diagnostic) request was routed to the origin address.');

            $foreign = sb_private($plugin, 'remote_get', array('http://127.0.0.1:' . $origin_port . '/hello-world/', 5, 4096, true));
            sb_assert(is_wp_error($foreign), 'A foreign URL was fetched through the origin mapping.');

            // A transport that never runs the cURL hook must not return a response fetched over public DNS.
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) {
                return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => 'PUBLIC_EDGE_COPY');
            };
            $unapplied = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(is_wp_error($unapplied) && 'static_bridge_render_origin_unapplied' === $unapplied->get_error_code(), 'A response fetched without the origin mapping was accepted.');
        } finally {
            proc_terminate($process);
            proc_close($process);
            @unlink($router);
        }
    });
    $batch = sb_method_body($source, 'remote_get_batch');
    sb_assert(false !== strpos($batch, 'CURLOPT_CONNECT_TO') && false !== strpos($batch, 'render_origin_connect_to'), 'The parallel render transport does not apply the origin mapping.');
    $renders = sb_method_body($source, 'fetch_verified_renders');
    sb_assert(1 === preg_match('/remote_get\(\$fetch_url, [^;]+, true(?:, \$render_request)?\)/', $renders), 'Sequential render requests do not use the origin mapping.');
});

sb_test('A Cloudflare challenge on a render is retried and never skipped as an expected 403', function () use ($plugin) {
    $token = str_repeat('c', 48);
    foreach (array(403, 503, 200) as $status) {
        $challenge = array(
            'response' => array('code' => $status),
            'headers' => array('cf-mitigated' => 'challenge', 'cf-ray' => '8f00000000000000-MXP', 'content-type' => 'text/html'),
            'body' => '<html><title>Just a moment...</title><script src="/cdn-cgi/challenge-platform/h/g/orchestrate/chl_page/v1"></script></html>',
        );
        $verified = sb_private($plugin, 'verify_dynamic_render_response', array($challenge, $token));
        sb_assert(is_wp_error($verified) && 'static_bridge_cdn_challenge' === $verified->get_error_code(), 'A Cloudflare challenge (HTTP ' . $status . ') was not identified.');
        sb_assert(sb_private($plugin, 'is_retryable_export_error', array($verified)), 'A Cloudflare challenge is not retried.');
        sb_assert(!sb_private($plugin, 'is_skippable_export_http_error', array($verified)), 'A Cloudflare challenge would drop the route as an expected skip.');
        sb_assert(false !== strpos($verified->get_error_message(), 'origine'), 'The challenge error does not point to the render origin setting.');
    }
    $plain_forbidden = array('response' => array('code' => 403), 'headers' => array('cf-ray' => '8f00000000000000-MXP'), 'body' => 'Forbidden');
    $verified = sb_private($plugin, 'verify_dynamic_render_response', array($plain_forbidden, $token));
    sb_assert(!is_wp_error($verified) && 403 === wp_remote_retrieve_response_code($verified), 'An ordinary 403 behind Cloudflare stopped being an expected per-URL skip.');
});

sb_test('Static Cache-Control is opt-in, validated, and emitted only on static responses with no-store on Strict 404', function () use ($plugin) {
    $sanitize = function ($value) use ($plugin) { return sb_private($plugin, 'sanitize_static_cache_control', array($value)); };
    sb_assert('' === $sanitize(''), 'An empty Cache-Control must disable the header.');
    sb_assert('public, max-age=0, s-maxage=600' === $sanitize(' public,max-age=0 ,  S-MAXAGE=600 '), 'A valid Cache-Control was not normalized.');
    sb_assert('public, max-age=60, stale-while-revalidate=30, stale-if-error=86400' === $sanitize('public, max-age=60, stale-while-revalidate=30, stale-if-error=86400'), 'Standard cache extensions were rejected.');
    foreach (array('public"; add_header X 1', "public\nHeader set X y", 'public, foo', 'max-age=abc', 'max-age=-1', 'max-age=9999999999', 'public, private', 'no-cache="set-cookie"', 'public;max-age=1', str_repeat('public, ', 40)) as $hostile) {
        sb_assert(is_wp_error($sanitize($hostile)), 'Unsafe Cache-Control ' . json_encode($hostile) . ' was accepted.');
    }

    sb_cf_options_isolated(function () use ($plugin) {
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        sb_cf_settings();
        $default_nginx = sb_private($plugin, 'nginx_router_block');
        $default_apache = sb_private($plugin, 'rewrite_block');
        // Without the opt-in only the Strict 404 carries a Cache-Control: no-store, so a CDN never keeps it.
        preg_match('/location @static_bridge_strict_missing \{.*?\n\}/s', $default_nginx, $default_missing);
        sb_assert(1 === substr_count($default_nginx, 'Cache-Control') && !empty($default_missing) && false !== strpos($default_missing[0], 'add_header Cache-Control "no-store, max-age=0" always;')
            && false === strpos($default_apache, 'Cache-Control "public') && 2 === substr_count($default_apache, 'Header ') - substr_count($default_apache, 'Header always set X-Static-Bridge-Route ')
            && false !== strpos($default_apache, 'Header always set Cache-Control "no-store, max-age=0" env=REDIRECT_STATIC_BRIDGE_STRICT'), 'Static responses gained cache headers without the opt-in, or the Strict 404 lost no-store.');
        sb_assert(false !== strpos($default_nginx, 'try_files /wp-content/static-bridge/current$uri/index.html @static_bridge_strict_missing;'), 'The default Nginx Strict location does not reach its no-store 404.');

        sb_cf_settings(array('static_cache_control' => 'public, max-age=0, s-maxage=600'));
        $nginx = sb_private($plugin, 'nginx_router_block');
        preg_match('/location = \/ \{.*?\n\}/s', $nginx, $home_location);
        preg_match('/location @static_bridge \{.*?\n\}/s', $nginx, $route_location);
        preg_match('/location @static_bridge_strict \{.*?\n\}/s', $nginx, $strict_location);
        preg_match('/location @static_bridge_strict_missing \{.*?\n\}/s', $nginx, $missing_location);
        // With Strict on, Nginx answers every static route from @static_bridge_strict.
        foreach (array('home' => $home_location, 'route' => $route_location, 'strict route' => $strict_location) as $label => $location) {
            sb_assert(!empty($location) && false !== strpos($location[0], 'add_header Cache-Control "public, max-age=0, s-maxage=600" always;'), 'The Nginx ' . $label . ' location does not send the configured Cache-Control.');
        }
        sb_assert(false !== strpos($strict_location[0], 'try_files /wp-content/static-bridge/current$uri/index.html @static_bridge_strict_missing;'), 'A missing Strict route does not reach its no-store location.');
        sb_assert(!empty($missing_location) && false !== strpos($missing_location[0], 'add_header Cache-Control "no-store, max-age=0" always;') && false !== strpos($missing_location[0], 'return 404;'), 'The Nginx Strict 404 is not marked no-store.');
        preg_match('/location \/ \{.*?\n\}/s', $nginx, $wordpress_location);
        sb_assert(!empty($wordpress_location) && false === stripos($wordpress_location[0], 'Cache-Control'), 'The WordPress fallback location received the static Cache-Control.');

        $apache = sb_private($plugin, 'rewrite_block');
        sb_assert(2 === substr_count($apache, 'E=STATIC_BRIDGE_ROUTE:static]') && 1 === substr_count($apache, 'E=STATIC_BRIDGE_STRICT:1]'), 'The Apache rules do not tag static and Strict responses.');
        sb_assert(false !== strpos($apache, '<IfModule mod_headers.c>')
            && false !== strpos($apache, 'Header always set Cache-Control "public, max-age=0, s-maxage=600" env=REDIRECT_STATIC_BRIDGE_ROUTE')
            && false !== strpos($apache, 'Header always set Cache-Control "no-store, max-age=0" env=STATIC_BRIDGE_STRICT'), 'The Apache block does not set Cache-Control from the static/Strict tags.');
    });
});

sb_test('Generated Cloudflare Cache Rule mirrors the routing guard and excluded paths', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        sb_cf_settings(array('excluded_paths' => array('/iscriviti/', '/Area "Riservata"/')));
        $expression = sb_private($plugin, 'cloudflare_cache_rule_expression');
        foreach (array(
            'http.host eq "news.example.test"',
            'http.request.method in {"GET" "HEAD"}',
            'http.request.uri.query eq ""',
            'ends_with(http.request.uri.path, "/")',
            'not (http.cookie contains "wordpress_logged_in_")',
            'not (http.cookie contains "comment_author_")',
            'not (http.cookie contains "wp-postpass_")',
            'not (http.cookie contains "woocommerce_items_in_cart")',
            'not (http.cookie contains "woocommerce_cart_hash")',
            'not (http.cookie contains "wp_woocommerce_session_")',
            'not starts_with(lower(http.request.uri.path), "/wp-admin/")',
            'not starts_with(lower(http.request.uri.path), "/wp-json/")',
            'not starts_with(lower(http.request.uri.path), "/wp-content/")',
            'not starts_with(lower(http.request.uri.path), "/wp-includes/")',
            'not (lower(http.request.uri.path) contains "/feed/")',
            'not starts_with(lower(http.request.uri.path), "/iscriviti/")',
            'not starts_with(lower(http.request.uri.path), "/area \\"riservata\\"/")',
        ) as $required) {
            sb_assert(false !== strpos($expression, $required), 'The Cache Rule expression is missing: ' . $required);
        }
        sb_assert(false === strpos($expression, ' matches '), 'The Cache Rule uses regex matching (not available on every plan).');

        // 2.0.16: Fluent Forms routes kept WordPress-dynamic embed per-request nonces.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FLUENT_FORMS_DYNAMIC_OPTION] = array('/modulo-non-riconosciuto/' => array('reason' => 'qa', 'form_ids' => array('3'), 'at' => time()));
        $cache = new ReflectionProperty($plugin, 'fluent_forms_dynamic_routes_cache');
        $cache->setValue($plugin, null);
        try {
            $expression = sb_private($plugin, 'cloudflare_cache_rule_expression');
            sb_assert(false !== strpos($expression, 'not starts_with(lower(http.request.uri.path), "/modulo-non-riconosciuto/")'), 'A Fluent Forms route kept dynamic (fresh nonces) is not excluded from the edge cache.');
        } finally {
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::FLUENT_FORMS_DYNAMIC_OPTION]);
            $cache->setValue($plugin, null);
        }
        sb_assert(false === strpos($expression, "\n") && strlen($expression) < 4096, 'The Cache Rule expression is not a single line within Cloudflare limits.');

    });
});

