sb_test('Cloudflare credentials are read only from wp-config constants and validated without exposing the token', function () use ($plugin, $source) {
    $state = function ($zone, $token) use ($plugin) { return sb_private($plugin, 'cloudflare_credential_state', array($zone, $token)); };
    $valid = $state('0123456789abcdef0123456789abcdef', 'sbqaTOKENsecret_0123456789-abcdefghijklmn');
    sb_assert('valid' === $valid['zone'] && 'valid' === $valid['token'], 'Valid Cloudflare credentials were rejected.');
    $missing = $state('', '');
    sb_assert('missing' === $missing['zone'] && 'missing' === $missing['token'], 'Missing credentials were not reported as missing.');
    foreach (array(array('0123456789ABCDEF0123456789abcdef/../x', 'short'), array('zone', "tok\nen with space 0123456789")) as $invalid) {
        $result = $state($invalid[0], $invalid[1]);
        sb_assert('invalid' === $result['zone'] && 'invalid' === $result['token'], 'Malformed credentials were accepted: ' . json_encode($result));
    }
    sb_assert(false === strpos(sb_method_body($source, 'save_settings'), 'token'), 'The settings handler accepts a Cloudflare token (it must come from wp-config.php).');
    sb_assert(false === strpos(json_encode(sb_private($plugin, 'cloudflare_purge_config')), STATIC_BRIDGE_CLOUDFLARE_API_TOKEN), 'The public purge configuration exposes the API token.');
});

sb_test('Cloudflare purge is opt-in, batches changed URLs and purges everything on request', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        $GLOBALS['sb_test_http_post_callback'] = null;
        sb_cf_settings();
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/a/')), 'test'));
        sb_assert(!array_key_exists('static_bridge_cloudflare_purge_pending', $GLOBALS['sb_test_options']), 'A purge was queued while the Cloudflare option is disabled.');
        sb_private($plugin, 'run_cloudflare_purge');
        sb_assert(empty($GLOBALS['sb_test_http_calls']), 'A disabled purge contacted Cloudflare.');

        sb_cf_settings(array('cloudflare_purge' => 1));
        $urls = array();
        for ($i = 1; $i <= 65; $i++) {
            $urls[] = home_url('/pagina-' . $i . '/');
        }
        $urls[] = 'https://attacker.invalid/steal/';
        $urls[] = home_url('/pagina-1/');
        sb_private($plugin, 'queue_cloudflare_purge', array($urls, 'test'));
        sb_assert(isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_cloudflare_purge']), 'The purge was not scheduled in its own request.');
        $status = sb_private($plugin, 'run_cloudflare_purge');
        $calls = $GLOBALS['sb_test_http_calls'];
        sb_assert(3 === count($calls), 'Expected three purge requests for 65 unique URLs, got ' . count($calls) . '.');
        $purged = array();
        foreach ($calls as $call) {
            sb_assert('wp_safe_remote_post' === $call['api'], 'The purge did not use the safe HTTP API.');
            sb_assert('https://api.cloudflare.com/client/v4/zones/' . STATIC_BRIDGE_CLOUDFLARE_ZONE_ID . '/purge_cache' === $call['url'], 'The purge used an unexpected endpoint: ' . $call['url']);
            sb_assert('Bearer ' . STATIC_BRIDGE_CLOUDFLARE_API_TOKEN === $call['args']['headers']['Authorization'] && 0 === $call['args']['redirection'], 'The purge request lacks the bearer token or follows redirects.');
            $body = json_decode($call['args']['body'], true);
            sb_assert(is_array($body) && isset($body['files']) && count($body['files']) <= 30 && 1 === count($body), 'A purge batch is malformed or above 30 URLs.');
            $purged = array_merge($purged, $body['files']);
        }
        sb_assert(65 === count($purged) && 65 === count(array_unique($purged)) && !in_array('https://attacker.invalid/steal/', $purged, true), 'The purged URL set is not the unique same-site set.');
        sb_assert('ok' === $status['status'] && empty($GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending']), 'A successful purge left pending work.');
        $activity = json_encode($GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] ?? array());
        sb_assert(false !== strpos($activity, 'Cloudflare') && false === strpos($activity, STATIC_BRIDGE_CLOUDFLARE_API_TOKEN), 'The purge was not logged in Attività or the log exposes the token.');

        $GLOBALS['sb_test_http_calls'] = array();
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/x/')), 'test'));
        sb_private($plugin, 'queue_cloudflare_purge', array('everything', 'full export'));
        sb_private($plugin, 'run_cloudflare_purge');
        sb_assert(1 === count($GLOBALS['sb_test_http_calls']) && array('purge_everything' => true) === json_decode($GLOBALS['sb_test_http_calls'][0]['args']['body'], true), 'A full purge did not replace the pending URL purge with a single purge_everything request.');
    });
});

sb_test('Cloudflare purge failures are warnings that retry a bounded number of times and never throw', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        sb_cf_settings(array('cloudflare_purge' => 1));
        $responses = array(
            new WP_Error('http_request_failed', 'cURL error 28: timed out after 10000 ms for Bearer ' . STATIC_BRIDGE_CLOUDFLARE_API_TOKEN),
            array('response' => array('code' => 403), 'headers' => array(), 'body' => '{"success":false,"errors":[{"code":10000,"message":"Authentication error"}]}'),
            array('response' => array('code' => 200), 'headers' => array(), 'body' => '{"success":false,"errors":[{"code":1012,"message":"Request must contain one of purge_everything, files"}]}'),
            array('response' => array('code' => 200), 'headers' => array(), 'body' => 'not json'),
        );
        $GLOBALS['sb_test_http_post_callback'] = function ($url, $args) use (&$responses) {
            return array_shift($responses);
        };
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/a/')), 'test'));
        for ($attempt = 1; $attempt <= 3; $attempt++) {
            $status = sb_private($plugin, 'run_cloudflare_purge');
            sb_assert('failed' === $status['status'], 'Attempt ' . $attempt . ' was not reported as failed.');
            $pending = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending'] ?? array();
            sb_assert(!empty($pending['urls']) && $attempt === (int) $pending['attempts'], 'A failed purge was not kept for a bounded retry.');
            sb_assert(isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_cloudflare_purge']), 'A failed purge was not rescheduled.');
        }
        $status = sb_private($plugin, 'run_cloudflare_purge');
        sb_assert('failed' === $status['status'] && empty($GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending']), 'A purge kept retrying after the attempt limit.');
        $last = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_last'] ?? array();
        sb_assert('failed' === ($last['status'] ?? '') && false !== strpos((string) ($last['message'] ?? ''), 'manualmente'), 'The final purge failure does not tell the administrator to purge manually.');
        $activity = $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] ?? array();
        $errors = array_filter($activity, function ($item) { return !empty($item['error']); });
        sb_assert(count($errors) >= 4, 'Purge failures were not logged as warnings in Attività.');
        $logged = json_encode(array($activity, $last));
        sb_assert(false === strpos($logged, STATIC_BRIDGE_CLOUDFLARE_API_TOKEN), 'A purge failure leaked the API token into the log.');
        sb_assert(false !== strpos($logged, 'Authentication error') && false !== strpos($logged, '10000'), 'The Cloudflare error code/message is not reported.');
    });
});

sb_test('Every publication path queues the matching Cloudflare purge', function () use ($plugin, $source, $fixtureRoot) {
    $publish = sb_method_body($source, 'publish_release');
    $swap = strpos($publish, '@rename($temporary, $link)');
    $queued = strpos($publish, "queue_cloudflare_purge('everything'");
    sb_assert(false !== $swap && false !== $queued && $queued > $swap, 'A full export does not queue a purge of everything after the atomic swap.');
    $incremental = sb_method_body($source, 'process_incremental_item');
    sb_assert(substr_count($incremental, 'queue_cloudflare_purge(') >= 3, 'Incremental refresh/delete/404 outcomes do not all queue a URL purge.');
    sb_assert(false !== strpos(sb_method_body($source, 'process_redirected_item'), 'queue_cloudflare_purge('), 'A redirect removal does not purge the old URL.');
    sb_assert(false !== strpos(sb_method_body($source, 'process_header_fragment_item'), "queue_cloudflare_purge('everything'"), 'A published SSI header does not purge the composed pages.');
    sb_assert(false !== strpos(sb_method_body($source, 'process_incremental_queue'), 'run_cloudflare_purge('), 'The incremental worker does not flush its purges.');
    sb_assert(false !== strpos(sb_method_body($source, 'process_manual_post_push_now'), 'run_cloudflare_purge('), 'A manual push does not purge the edge copy immediately.');
    sb_assert(false !== strpos(sb_method_body($source, 'save_settings'), "queue_cloudflare_purge('everything'"), 'Routing-relevant settings changes do not purge the edge.');
    sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), 'purge_everything'), 'Deactivation leaves static HTML cached at the edge.');
    sb_assert(false !== strpos($source, "add_action(self::CLOUDFLARE_PURGE_HOOK, array(\$this, 'process_cloudflare_purge_cron'));"), 'The purge cron hook is not registered.');

    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        sb_cf_options_isolated(function () use ($plugin, $root) {
            sb_cf_settings(array('cloudflare_purge' => 1));
            sb_retention_release($root, 'cf-r1', true, time() - 60);
            sb_retention_point_current($root, 'cf-r1');
            $release = realpath($root . '/releases/cf-r1');
            $url = home_url('/news/');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/news/') => array('url' => $url, 'action' => 'delete', 'token' => 'x', 'role' => 'dependent'));
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION][sha1('/news/')], $release));
            sb_assert('done' === $result, 'The fixture deletion did not complete.');
            $pending = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending'] ?? array();
            sb_assert(!empty($pending['urls']) && in_array($url, array_keys($pending['urls']), true), 'Removing a static route did not queue its URL for purge.');
        });
    });
});

sb_test('Cloudflare settings, purge button and handler are guarded by capability and nonce', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        sb_cf_settings(array('cloudflare_purge' => 1, 'render_origin' => '127.0.0.1', 'static_cache_control' => 'public, max-age=0, s-maxage=600'));
        $previous_get = $_GET;
        $level = ob_get_level();
        try {
            $_GET = array('tab' => 'settings');
            ob_start();
            $plugin->render_admin_page();
            $html = ob_get_clean();
        } finally {
            while (ob_get_level() > $level) {
                ob_end_clean();
            }
            $_GET = $previous_get;
        }
        foreach (array('name="render_origin"', 'value="127.0.0.1"', 'name="static_cache_control"', 'name="cloudflare_purge"', 'static_bridge_cloudflare_purge', 'http.request.method in {&quot;GET&quot; &quot;HEAD&quot;}', 'STATIC_BRIDGE_CLOUDFLARE_API_TOKEN') as $required) {
            sb_assert(false !== strpos($html, $required), 'The Settings tab is missing ' . $required . '.');
        }
        sb_assert(false === strpos($html, STATIC_BRIDGE_CLOUDFLARE_API_TOKEN), 'The Settings tab prints the Cloudflare token.');

        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_can_manage'] = false;
        try {
            $plugin->handle_cloudflare_purge();
            throw new RuntimeException('The purge handler ran without manage_options.');
        } catch (SB_Test_WP_Die $expected) {
        } finally {
            $GLOBALS['sb_test_can_manage'] = true;
        }
        $GLOBALS['sb_test_nonce_valid'] = false;
        try {
            $plugin->handle_cloudflare_purge();
            throw new RuntimeException('The purge handler ran without a valid nonce.');
        } catch (RuntimeException $expected) {
            sb_assert('Invalid admin nonce' === $expected->getMessage(), 'The purge handler did not check the nonce.');
        } finally {
            $GLOBALS['sb_test_nonce_valid'] = true;
        }
        sb_assert(empty($GLOBALS['sb_test_http_calls']), 'A rejected purge request contacted Cloudflare.');
    });
});

sb_test('Cloudflare diagnostic detects the edge, challenges and missing origin rendering', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        sb_cf_settings();
        $home = home_url('/');
        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($home) {
            return $url === $home ? array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>ok</html>') : null;
        };
        $result = sb_private($plugin, 'diagnostic_cloudflare_edge_step', array('cloudflare-edge'));
        sb_assert('skip' === $result['status'], 'A site without Cloudflare headers was not reported as not behind Cloudflare: ' . json_encode($result));

        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($home) {
            return $url === $home ? array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html', 'cf-ray' => '8f0000-MXP', 'server' => 'cloudflare', 'cf-cache-status' => 'DYNAMIC'), 'body' => '<html>ok</html>') : null;
        };
        $result = sb_private($plugin, 'diagnostic_cloudflare_edge_step', array('cloudflare-edge'));
        sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'cf-ray') && false !== stripos($result['remediation'], 'origine'), 'Cloudflare without a render origin is not a warning that recommends one: ' . json_encode($result));

        sb_cf_settings(array('render_origin' => '127.0.0.1', 'cloudflare_purge' => 1));
        $result = sb_private($plugin, 'diagnostic_cloudflare_edge_step', array('cloudflare-edge'));
        sb_assert('pass' === $result['status'], 'Cloudflare with origin rendering and purge was not a pass: ' . json_encode($result));

        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($home) {
            return $url === $home ? array('response' => array('code' => 403), 'headers' => array('content-type' => 'text/html', 'cf-ray' => '8f0000-MXP', 'cf-mitigated' => 'challenge'), 'body' => 'Just a moment...') : null;
        };
        $result = sb_private($plugin, 'diagnostic_cloudflare_edge_step', array('cloudflare-edge'));
        sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'cf-mitigated'), 'A Cloudflare challenge to the PHP process was not a failure: ' . json_encode($result));

        sb_cf_settings(array('static_cache_control' => 'public, max-age=0, s-maxage=600'));
        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($home) {
            return $url === $home ? array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html', 'cf-ray' => '8f0000-MXP', 'cf-cache-status' => 'HIT'), 'body' => '<html>ok</html>') : null;
        };
        $result = sb_private($plugin, 'diagnostic_cloudflare_edge_step', array('cloudflare-edge'));
        sb_assert('warning' === $result['status'] && false !== stripos($result['summary'], 'HIT') && false !== stripos($result['remediation'], 'purge'), 'Edge-cached HTML without purge is not flagged: ' . json_encode($result));

        $plan = json_encode(sb_private($plugin, 'diagnostic_plan', array('')));
        sb_assert(false !== strpos($plan, '"cloudflare-edge"') && false !== strpos($plan, '"cloudflare-markup"'), 'The diagnostic plan does not include the Cloudflare checks.');
    });
});

