/** Starts Apache or Nginx on a private docroot with the plugin's generated rules; returns array(request, stop). */
function sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot, array $without_modules = array())
{
    $port = sb_cf_free_port();
    $server_root = $fixtureRoot . '/cf-' . $kind . '-' . bin2hex(random_bytes(4));
    sb_assert(wp_mkdir_p($server_root . '/logs'), 'Could not create the ' . $kind . ' server root.');
    $log = $server_root . '/error.log';
    $environment = array('PATH' => (string) getenv('PATH'));
    if ('apache' === $kind) {
        $apache_root = dirname(dirname($binary));
        $load = '';
        foreach (array_diff(array('authz_core', 'dir', 'mime', 'rewrite', 'headers', 'unixd', 'log_config'), $without_modules) as $module) {
            if (!is_file($apache_root . '/modules/mod_' . $module . '.so')) {
                throw new SB_Test_Skip('Apache module mod_' . $module . ' is not available next to STATIC_BRIDGE_APACHE_BIN.');
            }
            $load .= 'LoadModule ' . $module . '_module "' . $apache_root . '/modules/mod_' . $module . ".so\"\n";
        }
        file_put_contents($docroot . '/.htaccess', $rules);
        $config = 'ServerRoot "' . $server_root . "\"\nListen 127.0.0.1:" . $port . "\nServerName 127.0.0.1\nPidFile \"" . $server_root . "/httpd.pid\"\nDefaultRuntimeDir \"" . $server_root . "\"\nMutex file:" . $server_root . " default\nErrorLog \"" . $log . "\"\nLogLevel warn\n" . $load
            . "TypesConfig /dev/null\nAddType text/html .html\nAddType text/plain .php\nDirectoryIndex index.html index.php\nAccessFileName .htaccess\n"
            . "<Directory />\n AllowOverride None\n Require all denied\n</Directory>\nDocumentRoot \"" . $docroot . "\"\n<Directory \"" . $docroot . "\">\n Options FollowSymLinks\n AllowOverride All\n Require all granted\n</Directory>\n";
        file_put_contents($server_root . '/httpd.conf', $config);
        if (is_dir($apache_root . '/shared-libs')) {
            $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
        }
        $command = array($binary, '-f', $server_root . '/httpd.conf', '-DFOREGROUND');
    } else {
        $config = "worker_processes 1;\npid \"" . $server_root . "/nginx.pid\";\nerror_log \"" . $log . "\" notice;\nevents { worker_connections 32; }\nhttp {\nserver {\nlisten 127.0.0.1:" . $port . ";\nroot \"" . $docroot . "\";\nindex index.php index.html;\n"
            . $rules . "\nlocation @wperror { default_type text/plain; return 200 \"WORDPRESS_FALLBACK\"; }\n}\n}\n";
        file_put_contents($server_root . '/nginx.conf', $config);
        $command = array($binary, '-p', $server_root, '-c', $server_root . '/nginx.conf', '-g', 'daemon off;');
    }
    $process = proc_open($command, array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log, 'a'), 2 => array('file', $log, 'a')), $pipes, $server_root, $environment);
    sb_assert(is_resource($process), 'Could not start the local ' . $kind . ' server.');
    $request = function ($path, array $headers = array()) use ($port) {
        $context = stream_context_create(array('http' => array('method' => 'GET', 'header' => implode("\r\n", $headers), 'ignore_errors' => true, 'follow_location' => 0, 'timeout' => 3)));
        $body = @file_get_contents('http://127.0.0.1:' . $port . $path, false, $context);
        $status = 0;
        $cache_control = array();
        $all = array();
        foreach ((array) http_get_last_response_headers() as $index => $header) {
            if (0 === $index && preg_match('/^HTTP\/\S+\s+(\d+)/', $header, $match)) {
                $status = (int) $match[1];
            } elseif (0 === stripos($header, 'Cache-Control:')) {
                $cache_control[] = trim(substr($header, strlen('Cache-Control:')));
            }
            if ($index > 0 && false !== strpos($header, ':')) {
                list($name, $value) = explode(':', $header, 2);
                $all[strtolower(trim($name))][] = trim($value);
            }
        }
        return array('status' => $status, 'cache_control' => implode(' | ', $cache_control), 'headers' => $all, 'body' => false === $body ? '' : $body);
    };
    $deadline = microtime(true) + 5;
    do {
        $probe = $request('/');
        if ($probe['status'] > 0) {
            break;
        }
        usleep(100000);
    } while (microtime(true) < $deadline);
    $stop = function () use ($process, $log) {
        proc_terminate($process);
        proc_close($process);
        return is_file($log) ? (string) file_get_contents($log) : '';
    };
    return array($request, $stop);
}

sb_test('Local Apache and Nginx send the optional Cache-Control only on static routes and no-store on Strict 404', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the CDN header check.');
    }
    sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers) {
        sb_cf_settings(array('static_cache_control' => 'public, max-age=0, s-maxage=600'));
        $failures = array();
        foreach ($servers as $kind => $binary) {
            $docroot = $fixtureRoot . '/cf-docroot-' . $kind;
            $static = $docroot . '/wp-content/static-bridge';
            sb_assert(wp_mkdir_p($static . '/releases/r1/hello'), 'Could not create the ' . $kind . ' docroot.');
            file_put_contents($static . '/releases/r1/index.html', 'STATIC_HOME');
            file_put_contents($static . '/releases/r1/hello/index.html', 'STATIC_HELLO');
            file_put_contents($static . '/.enabled', '1');
            file_put_contents($static . '/.strict', '1');
            @symlink('releases/r1', $static . '/current');
            file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
            if ('apache' === $kind) {
                $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                    . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
            } else {
                $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                $rules = sb_private($plugin, 'nginx_router_block');
            }
            list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
            try {
                foreach (array('/' => 'STATIC_HOME', '/hello/' => 'STATIC_HELLO') as $path => $body) {
                    $response = $request($path);
                    if (!(200 === $response['status'] && $body === trim($response['body']) && 'public, max-age=0, s-maxage=600' === $response['cache_control'])) {
                        $failures[] = $kind . ' static ' . $path . ' ' . json_encode($response);
                    }
                }
                $strict = $request('/not-exported/');
                if (!(404 === $strict['status'] && 'no-store, max-age=0' === $strict['cache_control'])) {
                    $failures[] = $kind . ' Strict 404 ' . json_encode($strict);
                }
                foreach (array(array('/hello/?utm=1', array()), array('/hello/', array('Cookie: wordpress_logged_in_qa=1'))) as $dynamic) {
                    $response = $request($dynamic[0], $dynamic[1]);
                    if (false !== strpos($response['cache_control'], 's-maxage') || false !== strpos($response['body'], 'STATIC_')) {
                        $failures[] = $kind . ' dynamic ' . $dynamic[0] . ' ' . json_encode($response);
                    }
                }
            } finally {
                $log = $stop();
            }
            if (!empty($failures) && '' !== trim($log)) {
                $failures[] = $kind . ' log: ' . substr($log, -400);
            }
        }
        sb_assert(empty($failures), implode('; ', $failures));
    });
});

// 2.5.0: X-Static-Bridge-Route on Apache too, with the same value and on the same responses as the Nginx block.
sb_test('Local Apache and Nginx (2.5.0): X-Static-Bridge-Route static on the copy, its .gz and the Strict 404, never from WP; Apache without mod_headers still serves', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers') || !function_exists('gzencode')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+, zlib) to run the route header check.');
    }
    sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers) {
        sb_cf_settings(array('precompressed_pages' => 1));
        $failures = array();
        // Apache three times: as usual, with a host that sends its 404 to WP (ErrorDocument: the variables arrive
        // with REDIRECT_) and without mod_headers (no marker, nothing broken).
        $runs = array();
        if (isset($servers['apache'])) {
            $runs['apache'] = array('apache', '', array());
            $runs['apache-errordocument'] = array('apache', "ErrorDocument 404 /index.php\n", array());
            $runs['apache-no-headers'] = array('apache', '', array('headers'));
        }
        if (isset($servers['nginx'])) {
            $runs['nginx'] = array('nginx', '', array());
        }
        foreach ($runs as $name => $run) {
            list($kind, $extra, $without) = $run;
            $marker = array() === $without;
            $docroot = $fixtureRoot . '/route-header-docroot-' . $name;
            $static = $docroot . '/wp-content/static-bridge';
            sb_assert(wp_mkdir_p($static . '/releases/r1/hello'), 'Could not create the ' . $name . ' docroot.');
            foreach (array('index.html' => 'STATIC_HOME', 'hello/index.html' => 'STATIC_HELLO') as $relative => $body) {
                file_put_contents($static . '/releases/r1/' . $relative, $body);
                file_put_contents($static . '/releases/r1/' . $relative . '.gz', gzencode($body, 9));
            }
            file_put_contents($static . '/.enabled', '1');
            file_put_contents($static . '/.strict', '1');
            @symlink('releases/r1', $static . '/current');
            file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
            if ('apache' === $kind) {
                $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                $rules = $extra . sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                    . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
                sb_assert(4 === substr_count($rules, 'Header always set X-Static-Bridge-Route static env='), 'The Apache rules do not set the route marker for the four variables.');
            } else {
                $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                $rules = sb_private($plugin, 'nginx_router_block');
            }
            list($request, $stop) = sb_cf_start_server($kind, $servers[$kind], $docroot, $rules, $fixtureRoot, $without);
            try {
                $route = function ($response) {
                    return isset($response['headers']['x-static-bridge-route']) ? $response['headers']['x-static-bridge-route'] : array();
                };
                $static_marker = $marker ? array('static') : array();
                foreach (array('/' => 'STATIC_HOME', '/hello/' => 'STATIC_HELLO') as $path => $body) {
                    $plain = $request($path);
                    if (!(200 === $plain['status'] && $body === $plain['body'] && $static_marker === $route($plain))) {
                        $failures[] = $name . ' static ' . $path . ' ' . json_encode($plain);
                    }
                    // The precompressed copy: Apache rewrites to index.html.gz (the variable becomes REDIRECT_), Nginx
                    // uses gzip_static. Without mod_headers Apache would serve the .gz without Content-Encoding.
                    $gzip = $request($path, array('Accept-Encoding: gzip'));
                    $encoded = isset($gzip['headers']['content-encoding']) && array('gzip') === $gzip['headers']['content-encoding'];
                    $decoded = $encoded ? @gzdecode($gzip['body']) : $gzip['body'];
                    if (!(200 === $gzip['status'] && $body === $decoded && $static_marker === $route($gzip))) {
                        $failures[] = $name . ' gzip ' . $path . ' ' . json_encode(array('status' => $gzip['status'], 'headers' => $gzip['headers'], 'body' => bin2hex(substr($gzip['body'], 0, 16))));
                    }
                }
                $strict = $request('/not-exported/');
                if (!(404 === $strict['status'] && $static_marker === $route($strict))) {
                    $failures[] = $name . ' Strict 404 ' . json_encode($strict);
                }
                foreach (array(array('/hello/?utm=1', array()), array('/hello/', array('Cookie: wordpress_logged_in_qa=1')), array('/index.php', array()), array('/wp-login.php', array())) as $dynamic) {
                    $response = $request($dynamic[0], $dynamic[1]);
                    if (array() !== $route($response) || false !== strpos($response['body'], 'STATIC_')) {
                        $failures[] = $name . ' WP ' . $dynamic[0] . ' ' . json_encode($response);
                    }
                }
            } finally {
                $log = $stop();
            }
            if (!empty($failures) && '' !== trim($log)) {
                $failures[] = $name . ' log: ' . substr($log, -400);
            }
        }
        sb_assert(empty($failures), implode('; ', $failures));
    });
});

// Apache serves an immutable copy of the current release (served/<id>/, 2.0.20). A file that the
// rules have made servable never changes content, so Apache's stat-then-open race cannot cut or pad
// a page.
function sb_served_isolated($fixtureRoot, callable $callback)
{
    sb_retention_isolated($fixtureRoot, function ($root) use ($callback) {
        $htaccess = ABSPATH . '.htaccess';
        $saved_htaccess = is_file($htaccess) && !is_link($htaccess) ? file_get_contents($htaccess) : null;
        $previous_server = isset($_SERVER['SERVER_SOFTWARE']) ? array($_SERVER['SERVER_SOFTWARE']) : null;
        $names = array(
            'static_bridge_served_copy',
            Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION,
            Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION,
            Static_Bridge_Plugin::FORM_MODES_OPTION,
            'static_bridge_cloudflare_purge_pending',
            'static_bridge_cloudflare_purge_last',
        );
        $previous = array();
        foreach ($names as $name) {
            $previous[$name] = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
            unset($GLOBALS['sb_test_options'][$name]);
        }
        $previous_http = array($GLOBALS['sb_test_http_responses'], $GLOBALS['sb_test_http_calls'], $GLOBALS['sb_test_http_callback'], $GLOBALS['sb_test_http_post_callback']);
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0, 'excluded_paths' => array(), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_http_calls'] = array();
        $GLOBALS['sb_test_http_callback'] = null;
        $GLOBALS['sb_test_http_post_callback'] = null;
        if (is_link($htaccess) || is_dir($htaccess)) {
            sb_assert(@unlink($htaccess) || @rmdir($htaccess), 'Could not clear the .htaccess fixture.');
        }
        file_put_contents($htaccess, "# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n");
        chmod($htaccess, 0644);
        try {
            $callback($root, $htaccess);
        } finally {
            if (is_dir($root . '/served')) {
                @chmod($root . '/served', 0755);
            }
            if (is_link($htaccess) || is_dir($htaccess)) {
                @unlink($htaccess) || @rmdir($htaccess);
            }
            if (file_exists($htaccess)) {
                @chmod($htaccess, 0644);
                @unlink($htaccess);
            }
            if (null !== $saved_htaccess) {
                file_put_contents($htaccess, $saved_htaccess);
            }
            foreach ($previous as $name => $value) {
                if (null === $value) {
                    unset($GLOBALS['sb_test_options'][$name]);
                } else {
                    $GLOBALS['sb_test_options'][$name] = $value[0];
                }
            }
            list($GLOBALS['sb_test_http_responses'], $GLOBALS['sb_test_http_calls'], $GLOBALS['sb_test_http_callback'], $GLOBALS['sb_test_http_post_callback']) = $previous_http;
            if (null === $previous_server) {
                unset($_SERVER['SERVER_SOFTWARE']);
            } else {
                $_SERVER['SERVER_SOFTWARE'] = $previous_server[0];
            }
        }
    });
}

function sb_served_release($root, $id, array $pages)
{
    $directory = $root . '/releases/' . $id;
    foreach ($pages as $relative => $body) {
        sb_assert(wp_mkdir_p(dirname($directory . '/' . $relative)) && false !== file_put_contents($directory . '/' . $relative, $body), 'Could not seed ' . $id . '/' . $relative);
    }
    file_put_contents($directory . '/manifest.json', json_encode(array('release' => $id, 'pages_saved' => count($pages), 'incremental_updates' => 0)));
    file_put_contents($directory . '/.ready', '');
    return realpath($directory);
}

/** Bump the release manifest the way every incremental change does (temporary file + rename). */
function sb_served_touch_manifest($release)
{
    $manifest = json_decode((string) file_get_contents($release . '/manifest.json'), true);
    $manifest['incremental_updates'] = (int) ($manifest['incremental_updates'] ?? 0) + 1;
    file_put_contents($release . '/manifest.json.tmp-test', json_encode($manifest));
    rename($release . '/manifest.json.tmp-test', $release . '/manifest.json');
}

function sb_served_ids($rules)
{
    preg_match_all('~wp-content/static-bridge/served/([0-9]{8}T[0-9]{6}Z-[a-f0-9]{8})/~', (string) $rules, $matches);
    return array_values(array_unique($matches[1]));
}

function sb_served_refresh_item($url, $action = 'refresh')
{
    return array('url' => $url, 'path' => (string) wp_parse_url($url, PHP_URL_PATH), 'action' => $action, 'role' => 'dependent', 'post_id' => 0, 'builders' => array(), 'token' => wp_generate_uuid4(), 'attempts' => 0);
}

function sb_served_render($url, $body)
{
    $GLOBALS['sb_test_http_responses'][add_query_arg('static_bridge_bypass', '1', $url)] = array(
        'response' => array('code' => 200),
        'headers' => array('content-type' => 'text/html; charset=UTF-8'),
        'body' => $body,
    );
}

sb_test('Reactivation after content changed serves the release with Strict off until a full export, and says so', function () use ($plugin, $fixtureRoot, $source) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin, $source) {
        $old_options = $GLOBALS['sb_test_options'];
        $old_posts = $GLOBALS['sb_test_posts'];
        $old_types = $GLOBALS['sb_test_post_types'];
        $old_can_manage = $GLOBALS['sb_test_can_manage'];
        $old_server = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        try {
            sb_retention_release($root, 'r-stale', true, time() - 3600);
            sb_retention_point_current($root, 'r-stale');
            $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => 'r-stale', 'published_at' => time() - 3600);
            $settings = get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array());
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge(is_array($settings) ? $settings : array(), array('strict_mode' => 1));
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $GLOBALS['sb_test_post_types'] = array('post' => array('public' => true, 'publicly_queryable' => true), 'page' => array('public' => true));
            $GLOBALS['sb_test_posts'] = array(
                array('ID' => 91, 'post_type' => 'post', 'post_status' => 'publish', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 60)),
                array('ID' => 92, 'post_type' => 'page', 'post_status' => 'trash', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 30)),
                array('ID' => 93, 'post_type' => 'post', 'post_status' => 'auto-draft', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time())),
                array('ID' => 94, 'post_type' => 'wp_template', 'post_status' => 'publish', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time())),
                array('ID' => 95, 'post_type' => 'post', 'post_status' => 'publish', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200)),
            );
            Static_Bridge_Plugin::activate();
            $stale = get_option(Static_Bridge_Plugin::STALE_RELEASE_OPTION, array());
            sb_assert(is_array($stale) && 'r-stale' === ($stale['release'] ?? '') && 2 === ($stale['changes'] ?? 0), 'The changed post and the trashed page were not counted: ' . json_encode($stale));
            sb_assert(!file_exists($root . '/.strict'), 'Strict was armed on a release older than the content.');
            sb_assert(is_file($root . '/.enabled'), 'The previous release is no longer served after reactivation.');
            $logged = json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), JSON_UNESCAPED_UNICODE);
            sb_assert(false !== strpos($logged, 'Riattivazione: 2 contenuti') && false !== strpos($logged, 'export completo'), 'The activity does not explain the stale release: ' . $logged);
            sb_assert(true === sb_private($plugin, 'sync_strict_marker', array(true)) && !file_exists($root . '/.strict'), 'Saving the settings armed Strict before a full export.');
            $GLOBALS['sb_test_can_manage'] = true;
            ob_start();
            $plugin->render_stale_release_notice();
            $notice = ob_get_clean();
            sb_assert(false !== strpos($notice, 'notice-warning') && false !== strpos($notice, '2 contenuti') && false !== strpos($notice, 'export completo'), 'No admin notice for the stale release: ' . $notice);
            $GLOBALS['sb_test_can_manage'] = false;
            ob_start();
            $plugin->render_stale_release_notice();
            sb_assert('' === ob_get_clean(), 'The stale notice is shown without manage_options.');

            $publish = sb_method_body($source, 'publish_release');
            $cleared = strpos($publish, 'delete_option(self::STALE_RELEASE_OPTION)');
            sb_assert(false !== $cleared && $cleared < strpos($publish, 'sync_strict_marker('), 'A full publication does not clear the stale flag before arming Strict.');

            $recover = sb_method_body($source, 'recover_interrupted_release_publication');
            $cleared = strpos($recover, 'delete_option(self::STALE_RELEASE_OPTION)');
            sb_assert(false !== $cleared && $cleared < strpos($recover, 'sync_strict_marker(') && false !== strpos($recover, 'store_security_headers($job)'), 'A recovered publication keeps the stale flag or the old headers.');

            foreach (array(0, 1) as $index) {
                $GLOBALS['sb_test_posts'][$index]['post_modified_gmt'] = gmdate('Y-m-d H:i:s', time() - 7200);
            }
            // A post scheduled before the release that cron published while the plugin was off: post_modified is old.
            $GLOBALS['sb_test_posts'][] = array('ID' => 96, 'post_type' => 'post', 'post_status' => 'publish', 'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200), 'post_date_gmt' => gmdate('Y-m-d H:i:s', time() - 600));
            Static_Bridge_Plugin::activate();
            sb_assert(1 === (get_option(Static_Bridge_Plugin::STALE_RELEASE_OPTION, array())['changes'] ?? 0) && !file_exists($root . '/.strict'), 'A scheduled post published while the plugin was off was not counted.');
            array_pop($GLOBALS['sb_test_posts']);
            $GLOBALS['sb_test_options']['static_bridge_last_release']['permalink_structure'] = '/%year%/%postname%/';
            $GLOBALS['sb_test_options']['permalink_structure'] = '/%postname%/';
            Static_Bridge_Plugin::activate();
            sb_assert(1 === (get_option(Static_Bridge_Plugin::STALE_RELEASE_OPTION, array())['changes'] ?? 0), 'A permalink change while the plugin was off was not counted.');
            $GLOBALS['sb_test_options']['static_bridge_last_release']['permalink_structure'] = '/%postname%/';
            Static_Bridge_Plugin::activate();
            sb_assert(false === get_option(Static_Bridge_Plugin::STALE_RELEASE_OPTION, false), 'An up-to-date release kept the stale flag.');
            sb_assert(is_file($root . '/.strict'), 'Strict was not restored on an up-to-date release.');
        } finally {
            $GLOBALS['sb_test_options'] = $old_options;
            $GLOBALS['sb_test_posts'] = $old_posts;
            $GLOBALS['sb_test_post_types'] = $old_types;
            $GLOBALS['sb_test_can_manage'] = $old_can_manage;
            if (null === $old_server) {
                unset($_SERVER['SERVER_SOFTWARE']);
            } else {
                $_SERVER['SERVER_SOFTWARE'] = $old_server;
            }
        }
    });
});

// Doc 23, item 169: content withdrawn while the plugin was off must not come back online with the release.
// The option names are spelled out so that the tests fail on 2.2.10 on what they check, not on a missing constant.
function sb_withdrawn_state(callable $callback)
{
    $saved = array($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_can_manage'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_filter_callbacks'], $GLOBALS['sb_test_transients']);
    $saved_options = array();
    foreach (array(Static_Bridge_Plugin::STALE_RELEASE_OPTION, 'static_bridge_routing_hold', 'static_bridge_deactivation_public', 'permalink_structure') as $name) {
        $saved_options[$name] = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
        unset($GLOBALS['sb_test_options'][$name]);
    }
    $GLOBALS['sb_test_permalinks_from_slug'] = true;
    $GLOBALS['sb_test_post_types'] = array('post' => array('public' => true, 'publicly_queryable' => true), 'page' => array('public' => true));
    $GLOBALS['sb_test_post_urls'] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    $GLOBALS['sb_test_transients']['static_bridge_incremental_query_pages'] = array();
    try {
        $callback();
    } finally {
        unset($GLOBALS['sb_test_permalinks_from_slug']);
        list($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_can_manage'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_filter_callbacks'], $GLOBALS['sb_test_transients']) = $saved;
        foreach ($saved_options as $name => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$name]);
            } else {
                $GLOBALS['sb_test_options'][$name] = $value[0];
            }
        }
    }
}

function sb_withdrawn_post($id, $status, $slug, array $extra = array())
{
    return array_merge(array(
        'ID' => $id, 'post_type' => 'post', 'post_status' => $status, 'post_name' => $slug, 'post_password' => '',
        'post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 60), 'post_date_gmt' => gmdate('Y-m-d H:i:s', time() - 86400),
    ), $extra);
}

sb_test('Reactivation takes the static copies of content made draft, private, trashed or password-protected while the plugin was off out of the release before Apache serves it (doc 23, item 169)', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        sb_withdrawn_state(function () use ($root, $htaccess) {
            $id = '20261104T100000Z-wwww1';
            $pages = array('index.html' => '<html>home</html>', 'pubblico/index.html' => '<html>pubblico</html>');
            foreach (array('bozza', 'privato', 'cestino', 'password', 'en/bozza', 'en/privato') as $route) {
                $pages[$route . '/index.html'] = '<html>RITIRATO ' . $route . '</html>';
            }
            $release = sb_served_release($root, $id, $pages);
            sb_retention_point_current($root, $id);
            $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => $id, 'published_at' => time() - 3600);
            $GLOBALS['sb_test_posts'] = array(
                sb_withdrawn_post(81, 'draft', 'bozza'),
                sb_withdrawn_post(82, 'private', 'privato'),
                sb_withdrawn_post(83, 'trash', 'cestino__trashed', array('meta' => array('_wp_desired_post_slug' => 'cestino'))),
                sb_withdrawn_post(84, 'publish', 'password', array('post_password' => 'segreta')),
                sb_withdrawn_post(85, 'publish', 'pubblico'),
                sb_withdrawn_post(86, 'draft', 'mai-pubblicato', array('post_date_gmt' => '0000-00-00 00:00:00')),
            );
            // A language plugin names the translations of each route (filter of 2.2.9).
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_translated_urls'] = function ($urls, $url) {
                $path = (string) wp_parse_url($url, PHP_URL_PATH);
                return in_array($path, array('/bozza/', '/privato/'), true) ? array(home_url('/en' . $path)) : $urls;
            };
            Static_Bridge_Plugin::activate();
            clearstatcache();
            foreach (array('bozza', 'privato', 'cestino', 'password', 'en/bozza', 'en/privato') as $route) {
                sb_assert(!file_exists($release . '/' . $route . '/index.html'), 'The copy of /' . $route . '/ withdrawn while the plugin was off is still in the release.');
            }
            sb_assert(is_file($release . '/pubblico/index.html') && is_file($release . '/index.html'), 'Reactivation removed a copy of public content.');
            $ids = sb_served_ids((string) file_get_contents($htaccess));
            sb_assert(1 === count($ids), 'Reactivation did not publish the Apache rules on a served copy: ' . json_encode($ids));
            $served = $root . '/served/' . $ids[0];
            sb_assert(is_file($served . '/pubblico/index.html') && !file_exists($served . '/bozza/index.html') && !file_exists($served . '/en/privato/index.html') && !file_exists($served . '/cestino/index.html'),
                'The copy Apache serves after reactivation still has a withdrawn page.');
            sb_assert(is_file($root . '/.enabled') && false === get_option('static_bridge_routing_hold', false), 'The release was not served again although every withdrawn copy was found and removed.');
            $manifest = json_decode((string) file_get_contents($release . '/manifest.json'), true);
            sb_assert(2 === (int) ($manifest['pages_saved'] ?? -1), 'The manifest does not count the removed pages: ' . json_encode($manifest));
            $logged = json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            sb_assert(false !== strpos($logged, 'tolte 6 copie statiche') && false !== strpos($logged, '/bozza/'), 'The activity does not list the removed copies: ' . $logged);
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            sb_assert(isset($queue[sha1('/')]) && 'refresh' === $queue[sha1('/')]['action'] && 'dependent' === $queue[sha1('/')]['role'], 'The home page that listed the withdrawn posts is not queued for a refresh: ' . json_encode(array_keys($queue)));
        });
    });
});

sb_test('Reactivation keeps the routing off until a full export when content public at deactivation was deleted or moved meanwhile, and not for content that never had a copy (doc 23, item 169)', function () use ($plugin, $fixtureRoot, $source) {
    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin, $source) {
        sb_withdrawn_state(function () use ($root, $plugin, $source) {
            $old_server = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            try {
                $id = 'r-withdrawn';
                sb_retention_release($root, $id, true, time() - 3600);
                foreach (array('pubblico', 'vecchio', 'spostato') as $route) {
                    wp_mkdir_p($root . '/releases/' . $id . '/' . $route);
                    file_put_contents($root . '/releases/' . $id . '/' . $route . '/index.html', '<html>' . $route . '</html>');
                }
                sb_retention_point_current($root, $id);
                $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => $id, 'published_at' => time() - 3600);
                $settings = get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array());
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge(is_array($settings) ? $settings : array(), array('strict_mode' => 1, 'incremental_enabled' => 1, 'excluded_paths' => array('/contatti/')));
                $GLOBALS['sb_test_posts'] = array(
                    sb_withdrawn_post(85, 'publish', 'pubblico', array('post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200))),
                    sb_withdrawn_post(87, 'publish', 'vecchio', array('post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200))),
                    sb_withdrawn_post(88, 'publish', 'spostato', array('post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200))),
                    sb_withdrawn_post(89, 'publish', 'contatti', array('post_modified_gmt' => gmdate('Y-m-d H:i:s', time() - 7200))),
                );
                // Deactivation remembers the public content.
                Static_Bridge_Plugin::deactivate();
                $snapshot = get_option('static_bridge_deactivation_public', array());
                sb_assert(is_array($snapshot) && $id === ($snapshot['release'] ?? '') && '85,87,88,89' === ($snapshot['ids'] ?? ''), 'Deactivation did not remember the public content: ' . json_encode($snapshot));
                sb_assert(!file_exists($root . '/.enabled'), 'Deactivation left the Nginx marker.');

                // While off: 87 deleted (trash emptied), 88 renamed and made draft, 89 (an excluded route, never exported) made draft.
                $GLOBALS['sb_test_posts'] = array(
                    $GLOBALS['sb_test_posts'][0],
                    sb_withdrawn_post(88, 'draft', 'nuovo-nome'),
                    sb_withdrawn_post(89, 'draft', 'contatti'),
                );
                Static_Bridge_Plugin::activate();
                sb_assert(!file_exists($root . '/.enabled'), 'The release is served again although it still holds the copy of a deleted post and of a moved one.');
                $hold = get_option('static_bridge_routing_hold', array());
                sb_assert(is_array($hold) && $id === ($hold['release'] ?? '') && 2 === ($hold['unresolved'] ?? 0), 'The routing hold does not name the release and the two unresolved posts: ' . json_encode($hold));
                sb_assert(!file_exists($root . '/.strict'), 'Strict was armed while the routing is held.');
                sb_assert(false === get_option('static_bridge_deactivation_public', false), 'The deactivation snapshot outlived the reactivation.');
                $logged = json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), JSON_UNESCAPED_UNICODE);
                sb_assert(false !== strpos($logged, 'resta spento fino al prossimo export completo') && false !== strpos($logged, '#87') && false !== strpos($logged, '#88') && false === strpos($logged, '#89'), 'The activity does not explain the hold: ' . $logged);
                sb_assert(false === sb_private($plugin, 'sync_routing_enabled_marker', array(true)) && !file_exists($root . '/.enabled'), 'The routing marker can be armed while held.');
                sb_assert(true === sb_private($plugin, 'update_routing_rules') && !file_exists($root . '/.enabled'), 'Publishing the rules armed the routing while held.');
                $GLOBALS['sb_test_can_manage'] = true;
                ob_start();
                $plugin->render_stale_release_notice();
                $notice = ob_get_clean();
                sb_assert(false !== strpos($notice, 'notice-error') && false !== strpos($notice, 'non serve pagine statiche') && false !== strpos($notice, 'export completo'), 'No admin notice for the held routing: ' . $notice);

                // A second reactivation without new changes keeps the hold: the copies are still in the release.
                Static_Bridge_Plugin::activate();
                sb_assert(!file_exists($root . '/.enabled') && $id === (get_option('static_bridge_routing_hold', array())['release'] ?? ''), 'A second reactivation dropped the hold.');

                // Only a full export (publish or recovered publish) lifts it, before arming the routing.
                $publish = sb_method_body($source, 'publish_release');
                $cleared = strpos($publish, 'delete_option(self::ROUTING_HOLD_OPTION)');
                sb_assert(false !== $cleared && $cleared < strpos($publish, 'sync_routing_enabled_marker(true)') && $cleared < strpos($publish, 'update_routing_rules()'), 'A full publication does not lift the hold before arming the routing.');
                $recover = sb_method_body($source, 'recover_interrupted_release_publication');
                $cleared = strpos($recover, 'delete_option(self::ROUTING_HOLD_OPTION)');
                sb_assert(false !== $cleared && $cleared < strpos($recover, 'update_routing_rules()'), 'A recovered publication does not lift the hold.');
                // A hold names its release: another release is served normally.
                $GLOBALS['sb_test_options']['static_bridge_routing_hold'] = array('release' => 'r-older', 'unresolved' => 1);
                sb_assert(false === sb_private($plugin, 'routing_held'), 'A hold for another release applies to the current one.');

                // Content that never had a copy does not hold the routing: an excluded route, a draft never published.
                unset($GLOBALS['sb_test_options']['static_bridge_routing_hold']);
                $GLOBALS['sb_test_options']['static_bridge_deactivation_public'] = array('release' => $id, 'at' => time(), 'ids' => '85,89');
                $GLOBALS['sb_test_posts'][] = sb_withdrawn_post(90, 'draft', 'mai-pubblicato', array('post_date_gmt' => '0000-00-00 00:00:00'));
                unset($GLOBALS['sb_test_posts'][1]);
                Static_Bridge_Plugin::activate();
                sb_assert(is_file($root . '/.enabled') && false === get_option('static_bridge_routing_hold', false), 'Content that never had a static copy kept the whole site dynamic.');
            } finally {
                if (null === $old_server) {
                    unset($_SERVER['SERVER_SOFTWARE']);
                } else {
                    $_SERVER['SERVER_SOFTWARE'] = $old_server;
                }
            }
        });
    });
});

sb_test('A translated route queued with its post is refreshed, not removed, and goes away only with the post (doc 23, item 181)', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $saved = array($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_filter_callbacks']);
        try {
            $release = sb_served_release($root, '20261104T110000Z-ttttt', array(
                'index.html' => '<html>home</html>',
                'dove-siamo/index.html' => '<html>dove siamo v1</html>',
                'en/where-we-are/index.html' => '<html>where we are v1</html>',
            ));
            sb_retention_point_current($root, '20261104T110000Z-ttttt');
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
            $GLOBALS['sb_test_posts'] = array(array('ID' => 5, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => ''));
            $GLOBALS['sb_test_post_urls'] = array(5 => home_url('/dove-siamo/'));
            // A language plugin answers with the published translation, another post with its own route.
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_translated_urls'] = function ($urls, $url) {
                return '/dove-siamo/' === (string) wp_parse_url($url, PHP_URL_PATH) ? array(home_url('/en/where-we-are/')) : $urls;
            };
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
            sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/dove-siamo/')), 5, 'refresh', array(), 'single'));
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            $original = $queue[sha1('/dove-siamo/')] ?? null;
            $translation = $queue[sha1('/en/where-we-are/')] ?? null;
            sb_assert(is_array($original) && is_array($translation) && empty($original['translation']), 'The page and its translation were not both queued: ' . json_encode(array_keys($queue)));
            sb_served_render(home_url('/dove-siamo/'), '<html><body>dove siamo v2</body></html>');
            sb_served_render(home_url('/en/where-we-are/'), '<html><body>where we are v2</body></html>');
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/en/where-we-are/'), $translation, $release)), 'The translated route was not processed.');
            clearstatcache();
            sb_assert(is_file($release . '/en/where-we-are/index.html') && false !== strpos((string) file_get_contents($release . '/en/where-we-are/index.html'), 'where we are v2'),
                'The translated page was removed or left stale instead of refreshed.');
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/dove-siamo/'), $original, $release)) && false !== strpos((string) file_get_contents($release . '/dove-siamo/index.html'), 'dove siamo v2'), 'The page itself was not refreshed.');
            // A route that is not the permalink of a post (and not a translation of it) is still removed.
            $stray = array_merge($original, array('url' => home_url('/en/where-we-are/'), 'path' => '/en/where-we-are/', 'token' => wp_generate_uuid4()));
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION][sha1('/en/where-we-are/')] = $stray;
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/en/where-we-are/'), $stray, $release)) && !file_exists($release . '/en/where-we-are/index.html'), 'A route that is not the post permalink was refreshed.');
            // The post made private: its translated route goes too, as the post's own.
            file_put_contents($release . '/en/where-we-are/index.html', '<html>where we are v2</html>');
            $GLOBALS['sb_test_posts'][0]['post_status'] = 'private';
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION][sha1('/en/where-we-are/')] = $translation;
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/en/where-we-are/'), $translation, $release)), 'The translated route of a private post was not processed.');
            clearstatcache();
            sb_assert(!file_exists($release . '/en/where-we-are/index.html'), 'The translated copy of a post that is no longer public stayed in the release.');
        } finally {
            list($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_filter_callbacks']) = $saved;
        }
    });
});

sb_test('A redirect to a route with translations completes and queues the target once (doc 23, item 182)', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $saved = array($GLOBALS['sb_test_filter_callbacks'], $GLOBALS['sb_test_http_responses'] ?? array());
        try {
            $release = sb_served_release($root, '20261105T110000Z-rrrrr', array(
                'index.html' => '<html>home</html>',
                'en/index.html' => '<html>home en</html>',
                'template/menu/index.html' => '<html>template</html>',
            ));
            sb_retention_point_current($root, '20261105T110000Z-rrrrr');
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
            // TranslatePress on a real client site: every route has its /en/ twin, the home too.
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_translated_urls'] = function ($urls, $url) {
                $path = (string) wp_parse_url($url, PHP_URL_PATH);
                return 0 === strpos($path, '/en/') ? $urls : array(home_url('/en' . $path));
            };
            // A Bricks template listed as dependent redirects to the home.
            $GLOBALS['sb_test_http_responses'][add_query_arg('static_bridge_bypass', '1', home_url('/template/menu/'))] = array(
                'response' => array('code' => 301), 'headers' => array('Location' => home_url('/') . '?static_bridge_bypass=1'), 'body' => '');
            $item = array('url' => home_url('/template/menu/'), 'path' => '/template/menu/', 'action' => 'refresh', 'role' => 'dependent',
                'post_id' => 27, 'builders' => array(), 'queued_at' => time(), 'token' => wp_generate_uuid4(), 'attempts' => 0);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/template/menu/') => $item);
            sb_assert(true === sb_private($plugin, 'enqueue_incremental_url', array(home_url('/'), 0, 'refresh', array(), 'dependent')),
                'A route queued with its translation was reported as not queued.');
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION][sha1('/')], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION][sha1('/en/')]);
            sb_assert(false === sb_private($plugin, 'enqueue_incremental_url', array('https://outside.invalid/', 0, 'refresh', array(), 'dependent')),
                'A route of another site was reported as queued.');
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/template/menu/'), $item, $release));
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            sb_assert('done' === $result && !isset($queue[sha1('/template/menu/')]),
                'The redirected route stayed in the queue (retried for ever, queueing its target again each time): ' . json_encode(array_map(function ($i) { return array($i['path'], $i['last_error'] ?? ''); }, $queue)));
            clearstatcache();
            sb_assert(!file_exists($release . '/template/menu/index.html'), 'The copy of the redirected route stayed in the release.');
            sb_assert(isset($queue[sha1('/')], $queue[sha1('/en/')]) && 2 === count($queue), 'The canonical target and its translation were not queued: ' . json_encode(array_keys($queue)));
        } finally {
            list($GLOBALS['sb_test_filter_callbacks'], $GLOBALS['sb_test_http_responses']) = $saved;
        }
    });
});

sb_test('Links to /page/N/ beyond the per-archive cap are not followed, so endless pagination cannot fail the export', function () use ($plugin, $source) {
    foreach (array('/category/x/page/100/' => true, '/category/x/page/101/' => false, '/page/2/' => true, '/2024/01/page/999999999/' => false, '/category/x/' => true, '/page-101/' => true, '/category/x/page/101' => false) as $path => $kept) {
        sb_assert($kept === sb_private($plugin, 'within_archive_page_cap', array(home_url($path))), $path . ($kept ? ' was dropped.' : ' was followed.'));
    }
    $GLOBALS['sb_test_filter_values']['static_bridge_archive_max_pages'] = 3;
    try {
        sb_assert(true === sb_private($plugin, 'within_archive_page_cap', array(home_url('/tag/y/page/3/'))) && false === sb_private($plugin, 'within_archive_page_cap', array(home_url('/tag/y/page/4/'))), 'The cap does not follow static_bridge_archive_max_pages.');
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_archive_max_pages']);
    }
    sb_assert(2 === substr_count(sb_method_body($source, 'run_export_queue_step'), "'within_archive_page_cap'"), 'The export worker enqueues discovered links without the pagination cap.');
});

sb_test('Activation stops with a clear reason when the home is in a subfolder or the content folder is not /wp-content', function () use ($plugin) {
    $base = array('php_version' => '8.4.0', 'wp_version' => '6.9', 'multisite' => false, 'memory_limit' => '256M', 'current_memory' => 1048576, 'peak_memory' => 1048576);
    foreach (array(
        array(array('home_path' => '/blog/'), 'sottocartella (/blog/)'),
        array(array('home_path' => '/blog'), 'sottocartella (/blog/)'),
        array(array('home_path' => '/', 'content_path' => '/app'), 'non è /wp-content/ (qui /app/)'),
        array(array('home_path' => '', 'content_path' => '/wp/wp-content/'), 'qui /wp/wp-content/'),
    ) as $case) {
        $report = Static_Bridge_Plugin::activation_preflight(array_merge($base, $case[0]));
        sb_assert(empty($report['ok']) && false !== strpos(implode(' ', $report['errors']), $case[1]), 'Unsupported layout not refused: ' . json_encode($case[0]) . ' ' . json_encode($report['errors']));
    }
    foreach (array(array('home_path' => '/', 'content_path' => '/wp-content'), array('home_path' => '', 'content_path' => '/wp-content/'), array()) as $supported) {
        $report = Static_Bridge_Plugin::activation_preflight(array_merge($base, $supported));
        sb_assert(false === strpos(implode(' ', $report['errors']), 'sottocartella') && false === strpos(implode(' ', $report['errors']), 'cartella dei contenuti'), 'A standard layout was refused: ' . json_encode($report['errors']));
    }
    $old_home = $GLOBALS['sb_test_home'];
    $old_can = $GLOBALS['sb_test_can_manage'];
    try {
        $GLOBALS['sb_test_can_manage'] = true;
        ob_start();
        $plugin->render_layout_notice();
        sb_assert('' === ob_get_clean(), 'A standard layout shows the layout notice.');
        $GLOBALS['sb_test_home'] = 'https://news.example.test:8443/en';
        $GLOBALS['sb_test_options']['home'] = 'https://news.example.test:8443';
        // content_url() comes from WP_CONTENT_URL (the site URL), which language plugins do not filter.
        $GLOBALS['sb_test_content_url'] = 'https://news.example.test:8443/wp-content';
        ob_start();
        $plugin->render_layout_notice();
        sb_assert('' === ob_get_clean(), 'A home_url() filtered by a language plugin (/en/) was taken for a subfolder.');
        $GLOBALS['sb_test_options']['home'] = 'https://news.example.test:8443/blog';
        ob_start();
        $plugin->render_layout_notice();
        $notice = ob_get_clean();
        sb_assert(false !== strpos($notice, 'notice-error') && false !== strpos($notice, '/blog/'), 'An active install in a subfolder is not told why nothing is static: ' . $notice);
    } finally {
        $GLOBALS['sb_test_home'] = $old_home;
        $GLOBALS['sb_test_can_manage'] = $old_can;
        unset($GLOBALS['sb_test_options']['home'], $GLOBALS['sb_test_content_url']);
    }
});

sb_test('Security headers of the rendered page are whitelisted, validated and stored only when they change', function () use ($plugin) {
    $response = array('response' => array('code' => 200), 'headers' => array(
        'content-type' => 'text/html; charset=UTF-8',
        'x-frame-options' => 'SAMEORIGIN',
        'X-Content-Type-Options' => 'nosniff',
        'referrer-policy' => array('strict-origin-when-cross-origin', 'strict-origin-when-cross-origin'),
        'permissions-policy' => array('camera=()', 'geolocation=()'),
        'strict-transport-security' => 'max-age=31536000; includeSubDomains',
        'content-security-policy' => "script-src 'self' 'nonce-abc123'",
        'x-robots-tag' => 'noindex',
        'set-cookie' => 'session=1',
    ), 'body' => '<html>ok</html>');
    $headers = sb_private($plugin, 'security_headers_from_response', array($response));
    sb_assert(array(
        'X-Frame-Options' => 'SAMEORIGIN',
        'X-Content-Type-Options' => 'nosniff',
        'Referrer-Policy' => 'strict-origin-when-cross-origin',
        'Strict-Transport-Security' => 'max-age=31536000; includeSubDomains',
    ) === $headers, 'Unexpected captured headers: ' . json_encode($headers));
    $parsed = sb_private($plugin, 'parse_fetched_page', array(home_url('/'), $response));
    sb_assert(isset($parsed['security_headers']) && $headers === $parsed['security_headers'], 'A fetched page does not carry its security headers.');
    sb_assert('SAMEORIGIN' === sb_private($plugin, 'security_headers_from_response', array(array('headers' => array('content-security-policy' => "default-src 'self'; img-src 'self' data:", 'x-frame-options' => 'SAMEORIGIN'))))['X-Frame-Options'], 'A plain header was refused.');
    sb_assert("default-src 'self'; img-src 'self' data:" === sb_private($plugin, 'security_headers_from_response', array(array('headers' => array('content-security-policy' => "default-src 'self'; img-src 'self' data:"))))['Content-Security-Policy'], 'A CSP without nonce was refused.');
    sb_assert('geolocation=(self "https://maps.example.test")' === (sb_private($plugin, 'security_headers_from_response', array(array('headers' => array('permissions-policy' => 'geolocation=(self "https://maps.example.test")'))))['Permissions-Policy'] ?? ''), 'A Permissions-Policy with quoted origins was refused.');
    foreach (array("SAMEORIGIN\"\nHeader set X 1", 'SAMEORIGIN\\" always; add_header X 1', 'a\\b', 'x %{HTTP_COOKIE}e', 'x $http_cookie', "x\ty", 'é', str_repeat('a', 2049), '') as $hostile) {
        sb_assert(array() === sb_private($plugin, 'security_headers_from_response', array(array('headers' => array('x-frame-options' => $hostile)))), 'A value that would break the server rules was kept: ' . json_encode($hostile));
    }

    $old = get_option('static_bridge_security_headers', null);
    try {
        delete_option('static_bridge_security_headers');
        sb_assert(true === sb_private($plugin, 'store_security_headers', array(array('security_headers' => $headers))), 'New headers were not reported as a change.');
        sb_assert(false === sb_private($plugin, 'store_security_headers', array(array('security_headers' => $headers))), 'Unchanged headers were reported as a change.');
        sb_assert($headers === sb_private($plugin, 'security_headers'), 'The stored headers are not the ones the rules repeat.');
        sb_assert(true === sb_private($plugin, 'store_security_headers', array(array('security_headers' => array('X-Frame-Options' => 'DENY', 'X-Evil' => 'x', 'Referrer-Policy' => 'a\\b')))), 'Changed headers were not reported.');
        sb_assert(array('X-Frame-Options' => 'DENY') === get_option('static_bridge_security_headers'), 'An unknown or invalid header was stored.');
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_security_headers'] = function ($stored) {
            $stored['x-content-type-options'] = 'nosniff';
            $stored['Permissions-Policy'] = 'camera=() \\';
            unset($stored['X-Frame-Options']);
            return $stored;
        };
        sb_assert(array('X-Content-Type-Options' => 'nosniff') === sb_private($plugin, 'security_headers'), 'The filter is not applied or not validated.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_security_headers']);
        sb_assert(false === sb_private($plugin, 'store_security_headers', array(array())) && array('X-Frame-Options' => 'DENY') === get_option('static_bridge_security_headers'), 'A job without captured headers (started before 2.2.1) dropped the stored ones.');
        sb_assert(true === sb_private($plugin, 'store_security_headers', array(array('security_headers' => array()))), 'Headers that disappeared were not reported as a change.');
        sb_assert(array() === sb_private($plugin, 'security_headers'), 'Headers that disappeared from the render are still repeated.');
    } finally {
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_security_headers']);
        null === $old ? delete_option('static_bridge_security_headers') : update_option('static_bridge_security_headers', $old);
    }
});

sb_test('Generated Apache and Nginx rules repeat the stored security headers on static routes only', function () use ($plugin) {
    $old = get_option('static_bridge_security_headers', null);
    $old_server = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    try {
        update_option('static_bridge_security_headers', array('X-Frame-Options' => 'SAMEORIGIN', 'Content-Security-Policy' => "default-src 'self'", 'Permissions-Policy' => 'geolocation=(self "https://x.test")'));
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache = sb_private($plugin, 'rewrite_block');
        foreach (array('Header always setifempty X-Frame-Options "SAMEORIGIN" env=STATIC_BRIDGE_ROUTE', 'Header always setifempty X-Frame-Options "SAMEORIGIN" env=REDIRECT_STATIC_BRIDGE_ROUTE',
            "Header always setifempty Content-Security-Policy \"default-src 'self'\" env=REDIRECT_STATIC_BRIDGE_ROUTE") as $line) {
            sb_assert(false !== strpos($apache, $line), 'The Apache rules miss: ' . $line);
        }
        sb_assert(2 === substr_count($apache, '[END,E=STATIC_BRIDGE_ROUTE:static]'), 'Static rules do not always tag the response for the headers.');
        sb_assert(false === strpos($apache, 'setifempty X-Frame-Options "SAMEORIGIN" env=STATIC_BRIDGE_STRICT'), 'The Strict 404 repeats the page headers.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx = sb_private($plugin, 'nginx_router_block');
        sb_assert(3 === substr_count($nginx, '    add_header X-Frame-Options "SAMEORIGIN" always;'), 'Every static Nginx location must repeat the headers: ' . substr_count($nginx, 'X-Frame-Options'));
        sb_assert(3 === substr_count($nginx, "    add_header Content-Security-Policy \"default-src 'self'\" always;"), 'The Nginx CSP is not repeated in every static location.');
        sb_assert(3 === substr_count($nginx, '    add_header Permissions-Policy "geolocation=(self \\"https://x.test\\")" always;')
            && false !== strpos($apache, 'Header always setifempty Permissions-Policy "geolocation=(self \\"https://x.test\\")" env=STATIC_BRIDGE_ROUTE'), 'Quotes in a header value are not escaped for Apache and Nginx.');
        update_option('static_bridge_security_headers', array());
        sb_assert(false === strpos(sb_private($plugin, 'nginx_router_block'), 'X-Frame-Options'), 'Nginx repeats headers that are not stored.');
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        sb_assert(false === strpos(sb_private($plugin, 'rewrite_block'), 'setifempty'), 'Apache repeats headers that are not stored.');
    } finally {
        null === $old ? delete_option('static_bridge_security_headers') : update_option('static_bridge_security_headers', $old);
        if (null === $old_server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server;
        }
    }
});

sb_test('Local Apache and Nginx serve /tag/pdf/ and /caffè/ static and repeat the security headers only there', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the live header and path check.');
    }
    sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers) {
        sb_cf_settings();
        $old = get_option('static_bridge_security_headers', null);
        update_option('static_bridge_security_headers', array('X-Frame-Options' => 'SAMEORIGIN', 'X-Content-Type-Options' => 'nosniff', 'Content-Security-Policy' => "default-src 'self'; img-src 'self' data:", 'Permissions-Policy' => 'geolocation=(self "https://maps.example.test"), camera=()',
            // A value that tries to close the quotes and add a directive: it must arrive as one literal value.
            'Referrer-Policy' => 'no-referrer" always; add_header X-Evil "1" always; Header set X-Evil "1'));
        $failures = array();
        try {
            foreach ($servers as $kind => $binary) {
                $docroot = $fixtureRoot . '/sec-docroot-' . $kind;
                $static = $docroot . '/wp-content/static-bridge';
                $pages = array('/' => 'index.html', '/tag/pdf/' => 'tag/pdf/index.html', '/caff%C3%A8/' => "caff\xC3\xA8/index.html", '/tag/_bozza/' => 'tag/_bozza/index.html');
                foreach ($pages as $path => $relative) {
                    sb_assert($relative === sb_private($plugin, 'relative_html_path', array(home_url($path))), 'The plugin does not write ' . $path . ' where the server looks.');
                    sb_assert(wp_mkdir_p(dirname($static . '/releases/r1/' . $relative)), 'Could not create the ' . $kind . ' docroot.');
                    file_put_contents($static . '/releases/r1/' . $relative, 'STATIC ' . $path);
                }
                file_put_contents($static . '/.enabled', '1');
                file_put_contents($static . '/.strict', '1');
                @symlink('releases/r1', $static . '/current');
                file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
                if ('apache' === $kind) {
                    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                    $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                        . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
                } else {
                    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                    $rules = sb_private($plugin, 'nginx_router_block');
                }
                list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
                try {
                    foreach ($pages as $path => $relative) {
                        $response = $request($path);
                        $headers = $response['headers'];
                        if (!(200 === $response['status'] && 'STATIC ' . $path === trim($response['body'])
                            && array('SAMEORIGIN') === ($headers['x-frame-options'] ?? null) && array('nosniff') === ($headers['x-content-type-options'] ?? null)
                            && array("default-src 'self'; img-src 'self' data:") === ($headers['content-security-policy'] ?? null)
                            && array('geolocation=(self "https://maps.example.test"), camera=()') === ($headers['permissions-policy'] ?? null)
                            && array('no-referrer" always; add_header X-Evil "1" always; Header set X-Evil "1') === ($headers['referrer-policy'] ?? null) && !isset($headers['x-evil']))) {
                            $failures[] = $kind . ' static ' . $path . ' ' . json_encode($response);
                        }
                    }
                    $strict = $request('/tag/unnamed-file.pdf/');
                    if (404 !== $strict['status'] || isset($strict['headers']['x-frame-options'])) {
                        $failures[] = $kind . ' Strict 404 ' . json_encode($strict);
                    }
                    $dynamic = $request('/tag/pdf/', array('Cookie: wordpress_logged_in_qa=1'));
                    if (false === strpos($dynamic['body'], 'WORDPRESS_FALLBACK') || isset($dynamic['headers']['x-frame-options'])) {
                        $failures[] = $kind . ' dynamic ' . json_encode($dynamic);
                    }
                } finally {
                    $log = $stop();
                }
                if (!empty($failures) && '' !== trim($log)) {
                    $failures[] = $kind . ' log: ' . substr($log, -400);
                }
            }
        } finally {
            null === $old ? delete_option('static_bridge_security_headers') : update_option('static_bridge_security_headers', $old);
        }
        sb_assert(empty($failures), implode('; ', $failures));
    });
});

sb_test('Permalinks without the trailing slash or ending in .html: URLs, pagination and rules follow the structure', function () use ($plugin) {
    $old = get_option('permalink_structure', null);
    $old_server = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    try {
        update_option('permalink_structure', '/%postname%');
        foreach (array('/hello/' => '/hello', '/hello' => '/hello', '/' => '/', '/category/x/' => '/category/x') as $in => $out) {
            sb_assert(home_url($out) === sb_private($plugin, 'normalize_public_url', array(home_url($in))), $in . ' did not normalize to ' . $out . ' without the slash.');
        }
        sb_assert('' === sb_private($plugin, 'normalize_public_url', array(home_url('/hello.html'))), 'A .html file was a route without the .html structure.');
        $pages = sb_private($plugin, 'archive_page_urls', array(array(array(home_url('/category/x'), 3))));
        sb_assert(array(home_url('/category/x'), home_url('/category/x/page/2'), home_url('/category/x/page/3')) === $pages, 'Pagination without the slash: ' . json_encode($pages));
        sb_assert(true === sb_private($plugin, 'is_archive_page_past_end', array(home_url('/category/x/page/4'), new WP_Error('static_bridge_http', 'HTTP 404', 404))), 'A /page/N past the end without the slash is reported as an URL left out.');
        sb_assert('hello/index.html' === sb_private($plugin, 'relative_html_path', array(home_url('/hello'))), '/hello is not written where the server looks.');
        sb_assert(home_url('/about') === sb_private($plugin, 'route_url', array('/about/')) && home_url('/') === sb_private($plugin, 'route_url', array('/')), 'Probes and diagnostics would request /about/, which goes to WordPress without the slash structure.');
        $source = file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php');
        sb_assert(false !== strpos(sb_method_body($source, 'verify_nginx_ssi_runtime'), "\$this->route_url('/' . \$route_path . '/')") && false !== strpos(sb_method_body($source, 'nginx_route_probe'), '$this->route_url($path)'), 'The Nginx probes do not follow the permalink structure.');
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache = sb_private($plugin, 'rewrite_block');
        sb_assert(2 === substr_count($apache, "RewriteCond %{REQUEST_URI} !/$\n") && false === strpos($apache, "RewriteCond %{REQUEST_URI} /$\n"), 'Apache does not send /x/ to WordPress without the slash structure.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx = sb_private($plugin, 'nginx_router_block');
        sb_assert(false !== strpos($nginx, '    if ($uri ~ "/$") { return 418; }') && false === strpos($nginx, '    if ($uri !~ "/$") { return 418; }'), 'Nginx does not send /x/ to WordPress without the slash structure.');

        update_option('permalink_structure', '/%postname%.html');
        sb_assert(home_url('/hello.html') === sb_private($plugin, 'normalize_public_url', array(home_url('/hello.html'))), 'A .html route was refused with the .html structure.');
        sb_assert(home_url('/hello.html') === sb_private($plugin, 'normalize_public_url', array(home_url('/hello.html/'))), 'A .html route kept a slash.');
        sb_assert(home_url('/category/x') === sb_private($plugin, 'normalize_public_url', array(home_url('/category/x/'))), 'An archive kept the slash with the .html structure.');
        foreach (array('/style.css', '/file.pdf', '/.html', '/a/.html') as $file) {
            sb_assert('' === sb_private($plugin, 'normalize_public_url', array(home_url($file))), $file . ' became a route with the .html structure.');
        }
        sb_assert('hello.html/index.html' === sb_private($plugin, 'relative_html_path', array(home_url('/hello.html'))), '/hello.html is not written where the server looks.');
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        sb_assert(false !== strpos(sb_private($plugin, 'rewrite_block'), "RewriteCond %{REQUEST_URI} !\\.(?!html$)[A-Za-z0-9]{1,8}$\n"), 'Apache Strict does not treat .html routes as routes.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        sb_assert(false !== strpos(sb_private($plugin, 'nginx_router_block'), '    if ($uri ~ "\\.(?!html$)[A-Za-z0-9]{1,8}$") { return 418; }'), 'Nginx does not treat .html routes as routes.');

        update_option('permalink_structure', '/%postname%/');
        sb_assert(home_url('/hello/') === sb_private($plugin, 'normalize_public_url', array(home_url('/hello'))), 'The slash structure lost its slash.');
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        sb_assert(false !== strpos(sb_private($plugin, 'rewrite_block'), "RewriteCond %{REQUEST_URI} !\\.[A-Za-z0-9]{1,8}$\n"), 'The default extension rule changed.');
    } finally {
        null === $old ? delete_option('permalink_structure') : update_option('permalink_structure', $old);
        if (null === $old_server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server;
        }
    }
});

sb_test('Local Apache and Nginx serve routes without the slash and .html routes like WordPress links them', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the live permalink check.');
    }
    $old = get_option('permalink_structure', null);
    try {
        sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers) {
            sb_cf_settings();
            $failures = array();
            $cases = array(
                '/%postname%' => array('static' => array('/hello', '/category/x/page/2'), 'wordpress' => array('/hello/', '/style.css'), 'strict' => array('/missing')),
                '/%postname%.html' => array('static' => array('/hello.html', '/category/x'), 'wordpress' => array('/category/x/', '/style.css'), 'strict' => array('/missing.html', '/missing')),
            );
            foreach ($cases as $structure => $case) {
                update_option('permalink_structure', $structure);
                foreach ($servers as $kind => $binary) {
                    $docroot = $fixtureRoot . '/permalink-' . md5($structure) . '-' . $kind;
                    $static = $docroot . '/wp-content/static-bridge';
                    foreach ($case['static'] as $path) {
                        $relative = sb_private($plugin, 'relative_html_path', array(sb_private($plugin, 'normalize_public_url', array(home_url($path)))));
                        sb_assert(is_string($relative) && wp_mkdir_p(dirname($static . '/releases/r1/' . $relative)), 'Could not map ' . $path . '.');
                        file_put_contents($static . '/releases/r1/' . $relative, 'STATIC ' . $path);
                    }
                    file_put_contents($static . '/releases/r1/index.html', 'STATIC /');
                    file_put_contents($static . '/.enabled', '1');
                    file_put_contents($static . '/.strict', '1');
                    @symlink('releases/r1', $static . '/current');
                    file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
                    if ('apache' === $kind) {
                        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                        $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                            . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
                    } else {
                        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                        $rules = sb_private($plugin, 'nginx_router_block');
                    }
                    list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
                    try {
                        foreach (array_merge(array('/'), $case['static']) as $path) {
                            $response = $request($path);
                            if (!(200 === $response['status'] && 'STATIC ' . $path === trim($response['body']))) {
                                $failures[] = $structure . ' ' . $kind . ' static ' . $path . ' ' . json_encode($response);
                            }
                        }
                        foreach ($case['wordpress'] as $path) {
                            $response = $request($path);
                            if (false === strpos($response['body'], 'WORDPRESS_FALLBACK')) {
                                $failures[] = $structure . ' ' . $kind . ' WordPress ' . $path . ' ' . json_encode($response);
                            }
                        }
                        foreach ($case['strict'] as $path) {
                            $response = $request($path);
                            if (404 !== $response['status']) {
                                $failures[] = $structure . ' ' . $kind . ' Strict ' . $path . ' ' . json_encode($response);
                            }
                        }
                    } finally {
                        $log = $stop();
                    }
                    if (!empty($failures) && '' !== trim($log)) {
                        $failures[] = $kind . ' log: ' . substr($log, -400);
                    }
                }
            }
            sb_assert(empty($failures), implode('; ', $failures));
        });
    } finally {
        null === $old ? delete_option('permalink_structure') : update_option('permalink_structure', $old);
    }
});

/** Runs a server binary's configuration test; returns array(exit status, output). */
function sb_config_test(array $command, array $environment = array())
{
    $process = proc_open($command, array(0 => array('file', '/dev/null', 'r'), 1 => array('pipe', 'w'), 2 => array('pipe', 'w')), $pipes, null, $environment ?: null);
    sb_assert(is_resource($process), 'Could not start ' . $command[0] . '.');
    $output = stream_get_contents($pipes[1]) . stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);
    return array(proc_close($process), trim($output));
}

sb_test('Gate C: httpd -t and nginx -t accept every generated block (Strict, hostile exclusions, headers, permalink forms)', function () use ($plugin, $fixtureRoot) {
    $httpd = getenv('STATIC_BRIDGE_APACHE_BIN');
    $nginx = getenv('STATIC_BRIDGE_NGINX_BIN');
    if (!$httpd || !$nginx || !is_executable($httpd) || !is_executable($nginx) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and STATIC_BRIDGE_NGINX_BIN to run the configuration tests.');
    }
    $apache_root = dirname(dirname($httpd));
    $environment = array('PATH' => (string) getenv('PATH'));
    if (is_dir($apache_root . '/shared-libs')) {
        $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
    }
    $load = '';
    // mime and include, when present, make httpd -t parse the mod_include part of the protection block too.
    foreach (array_merge(array('authz_core', 'rewrite', 'headers', 'unixd'), array_values(array_filter(array('mime', 'include'), function ($module) use ($apache_root) {
        return is_file($apache_root . '/modules/mod_' . $module . '.so');
    }))) as $module) {
        $load .= 'LoadModule ' . $module . '_module "' . $apache_root . '/modules/mod_' . $module . ".so\"\n";
    }
    $old_options = $GLOBALS['sb_test_options'];
    $old_server = isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null;
    $variants = array(
        'slash' => array('/%postname%/', 'public, max-age=0, s-maxage=600'),
        'no-slash' => array('/%postname%', ''),
        'html' => array('/%postname%.html', 'public, max-age=60'),
        // 2.3.0: precompressed pages add a .gz rule before every static rule and an <If> block.
        'gzip' => array('/%postname%/', 'public, max-age=0, s-maxage=600', 1),
        // 2.5.0: the tracking expression in place of «^$» and the cookies that send to WP.
        'tracking' => array('/%postname%/', 'public, max-age=60', 1, true),
    );
    $results = array();
    try {
        foreach ($variants as $name => $variant) {
            $GLOBALS['sb_test_options']['permalink_structure'] = $variant[0];
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge((array) ($old_options[Static_Bridge_Plugin::SETTINGS_OPTION] ?? array()), array(
                'strict_mode' => 1, 'excluded_paths' => array('/iscriviti/', '/con spazio/', '/virgo"lette/', '/punto;virgola/'), 'static_cache_control' => $variant[1],
                'precompressed_pages' => isset($variant[2]) ? $variant[2] : 0,
                'ignore_tracking_params' => isset($variant[3]) ? 1 : 0, 'dynamic_cookies' => isset($variant[3]) ? array('wishlist', 'wp.lang', 'yith_wcwl_session_*') : array()));
            $GLOBALS['sb_test_options']['static_bridge_security_headers'] = array('X-Frame-Options' => 'SAMEORIGIN', 'X-Content-Type-Options' => 'nosniff',
                'Content-Security-Policy' => "default-src 'self'; img-src 'self' data: https://*.example.test; frame-ancestors 'self'", 'Permissions-Policy' => 'camera=(), geolocation=(self "https://x.test")',
                'Referrer-Policy' => 'no-referrer" always; add_header X-Evil "1" always; Header set X-Evil "1');
            $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
            $root = $fixtureRoot . '/gate-c-' . $name;
            sb_assert(wp_mkdir_p($root . '/docroot'), 'Could not create the Gate C fixture.');
            $block = sb_private($plugin, 'archive_protection_block') . "\n" . sb_private($plugin, 'rewrite_block');
            $conf = 'ServerRoot "' . $root . "\"\nListen 127.0.0.1:19098\nServerName 127.0.0.1\nPidFile \"" . $root . "/httpd.pid\"\nErrorLog \"" . $root . "/error.log\"\n" . $load
                . 'DocumentRoot "' . $root . "/docroot\"\n<Directory \"" . $root . "/docroot\">\n" . $block . "\n</Directory>\n";
            file_put_contents($root . '/httpd.conf', $conf);
            $results[$name . ' apache'] = sb_config_test(array($httpd, '-t', '-f', $root . '/httpd.conf'), $environment);
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            $nginx_conf = "worker_processes 1;\npid \"" . $root . "/nginx.pid\";\nerror_log stderr;\nevents { worker_connections 16; }\nhttp {\nserver {\nlisten 127.0.0.1:19097;\nroot \"" . $root . "/docroot\";\n"
                . sb_private($plugin, 'nginx_router_block') . "\nlocation @wperror { return 404; }\n}\n}\n";
            file_put_contents($root . '/nginx.conf', $nginx_conf);
            sb_assert(wp_mkdir_p($root . '/logs'), 'Could not create the Nginx log folder.');
            $results[$name . ' nginx'] = sb_config_test(array($nginx, '-t', '-p', $root, '-c', $root . '/nginx.conf'));
        }
        // Control: the test does read the block. An unescaped space, as before 2.2.0, must be refused.
        $root = $fixtureRoot . '/gate-c-control';
        sb_assert(wp_mkdir_p($root . '/docroot'), 'Could not create the Gate C control.');
        file_put_contents($root . '/httpd.conf', 'ServerRoot "' . $root . "\"\nListen 127.0.0.1:19098\nServerName 127.0.0.1\nPidFile \"" . $root . "/httpd.pid\"\nErrorLog \"" . $root . "/error.log\"\n" . $load
            . 'DocumentRoot "' . $root . "/docroot\"\n<Directory \"" . $root . "/docroot\">\nRewriteEngine On\nRewriteCond %{REQUEST_URI} !^/(?:con spazio)(?:/|$) [NC]\nRewriteRule ^ - [END]\n</Directory>\n");
        $control = sb_config_test(array($httpd, '-t', '-f', $root . '/httpd.conf'), $environment);
    } finally {
        $GLOBALS['sb_test_options'] = $old_options;
        if (null === $old_server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $old_server;
        }
    }
    foreach ($results as $name => $result) {
        if (false !== strpos($name, 'nginx') && 0 !== $result[0] && false !== stripos($result[1], 'Operation not permitted')) {
            throw new SB_Test_Skip('The sandbox blocks Nginx from opening its validation socket.');
        }
        sb_assert(0 === $result[0], 'Gate C ' . $name . ' refused the generated block: ' . $result[1]);
    }
    sb_assert(0 !== $control[0] && false !== strpos($control[1], 'AH00526'), 'The Gate C control (an unescaped space) was not refused: ' . $control[1]);
    echo '[GATE C] ' . implode(' · ', array_map(function ($name, $result) { return $name . ': ' . (0 === $result[0] ? 'OK' : 'FAIL'); }, array_keys($results), $results)) . ' · control: ' . strtok($control[1], "\n") . "\n";
});

sb_test('OpenLiteSpeed (2.3.0): rules on current/ with a probe, a folder guard, no .gz, the server remembered for WP-CLI', function () use ($plugin, $fixtureRoot) {
    $previous_edition = isset($_SERVER['LSWS_EDITION']) ? array($_SERVER['LSWS_EDITION']) : null;
    $previous_kind = array_key_exists(Static_Bridge_Plugin::WEB_SERVER_OPTION, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][Static_Bridge_Plugin::WEB_SERVER_OPTION]) : null;
    $previous_activity = array_key_exists(Static_Bridge_Plugin::ACTIVITY_OPTION, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION]) : null;
    try {
