            sb_served_release($root, '20261108T100000Z-aaaaa', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news</html>'));
            sb_retention_point_current($root, '20261108T100000Z-aaaaa');
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::WEB_SERVER_OPTION]);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['precompressed_pages'] = 1;
            $_SERVER['SERVER_SOFTWARE'] = 'LiteSpeed';
            $_SERVER['LSWS_EDITION'] = 'Openlitespeed 1.9.4';
            sb_assert('openlitespeed' === sb_private($plugin, 'web_server_kind') && 'openlitespeed' === $GLOBALS['sb_test_options'][Static_Bridge_Plugin::WEB_SERVER_OPTION], 'OpenLiteSpeed was not recognised from LSWS_EDITION and remembered.');
            sb_assert(false === sb_private($plugin, 'precompressed_pages_enabled'), 'Precompressed pages stay on under OpenLiteSpeed, which compresses static files itself.');
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the rules on OpenLiteSpeed failed.');
            $rules = (string) file_get_contents($htaccess);
            sb_assert(array() === sb_served_ids($rules) && false !== strpos($rules, 'wp-content/static-bridge/current/index.html -f')
                && (!is_dir($root . '/served') || array() === array_diff((array) scandir($root . '/served'), array('.', '..'))),
                'OpenLiteSpeed rules name a served copy, which the server would keep until its next restart.');
            sb_assert(false === strpos($rules, 'index.html.gz'), 'OpenLiteSpeed rules carry the .gz rules.');
            sb_assert(1 === preg_match('~^# BEGIN Static Bridge\n.*?^# END Static Bridge$~ms', $rules, $block) && 1 === preg_match('~^RewriteRule \^static-bridge-rules-([a-f0-9]{12})\$ - \[R=410,L\]$~m', $block[0], $probe),
                'The OpenLiteSpeed block has no probe rule.');
            $without = preg_replace("~^# OpenLiteSpeed legge questo file[^\n]*\nRewriteRule \^static-bridge-rules-[a-f0-9]{12}\\$ - \[R=410,L\]\n\n~m", '', $block[0]);
            sb_assert($probe[1] === substr(hash('sha256', $without), 0, 12), 'The probe digits are not the hash of the block without the probe.');
            sb_assert(is_file($guard) && Static_Bridge_Plugin::OPENLITESPEED_FOLDER_GUARD === file_get_contents($guard) && false !== strpos(file_get_contents($guard), "RewriteRule ^ - [F]\n"),
                'The folder guard was not written in wp-content/static-bridge/.htaccess.');
            sb_assert(1 === $logged(), 'The first OpenLiteSpeed rules were not logged with the restart to do.');
            // The incremental queue changes nothing in the rules (they would wait for a restart).
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(array('url' => home_url('/sparita/'), 'action' => 'delete'), array('url' => home_url('/nuova/')));
            sb_assert(true === sb_private($plugin, 'update_routing_rules') && $rules === file_get_contents($htaccess) && 1 === $logged(), 'Queued paths changed the OpenLiteSpeed rules or asked for a restart.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
            // WP-CLI and the system cron name no server: the remembered one is used.
            unset($_SERVER['SERVER_SOFTWARE'], $_SERVER['LSWS_EDITION']);
            sb_assert('openlitespeed' === sb_private($plugin, 'web_server_kind'), 'Without a server the remembered OpenLiteSpeed was not used.');
            sb_assert(true === sb_private($plugin, 'update_routing_rules') && $rules === file_get_contents($htaccess) && 1 === $logged(), 'A run without a server changed the OpenLiteSpeed rules.');
            // LiteSpeed Enterprise reads .htaccess again by itself: served copies, no probe, no guard; still no .gz.
            $_SERVER['SERVER_SOFTWARE'] = 'LiteSpeed';
            sb_assert('litespeed' === sb_private($plugin, 'web_server_kind') && false === sb_private($plugin, 'precompressed_pages_enabled'), 'LiteSpeed Enterprise was not told apart, or got precompressed pages.');
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the rules on LiteSpeed failed.');
            $enterprise = (string) file_get_contents($htaccess);
            sb_assert(1 === count(sb_served_ids($enterprise)) && false === strpos($enterprise, 'static-bridge-rules-') && !file_exists($guard), 'LiteSpeed Enterprise rules: served copy, no probe and no guard expected.');
            // A foreign file in the folder is never overwritten on OpenLiteSpeed nor removed elsewhere.
            file_put_contents($guard, "# altro\n");
            $_SERVER['LSWS_EDITION'] = 'Openlitespeed 1.9.4';
            sb_private($plugin, 'sync_openlitespeed_folder_guard');
            $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
            unset($_SERVER['LSWS_EDITION']);
            sb_private($plugin, 'sync_openlitespeed_folder_guard');
            sb_assert("# altro\n" === file_get_contents($guard), 'A foreign .htaccess in wp-content/static-bridge was overwritten or removed.');
            @unlink($guard);
            sb_assert('apache' === sb_private($plugin, 'web_server_kind') && (!function_exists('gzencode') || true === sb_private($plugin, 'precompressed_pages_enabled')), 'Apache lost the precompressed pages.');
        });
    } finally {
        if (null === $previous_edition) {
            unset($_SERVER['LSWS_EDITION']);
        } else {
            $_SERVER['LSWS_EDITION'] = $previous_edition[0];
        }
        foreach (array(Static_Bridge_Plugin::WEB_SERVER_OPTION => $previous_kind, Static_Bridge_Plugin::ACTIVITY_OPTION => $previous_activity) as $name => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$name]);
            } else {
                $GLOBALS['sb_test_options'][$name] = $value[0];
            }
        }
    }
});

sb_test('Apache rules serve an immutable hard-linked copy of the current release instead of current/', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $release = sb_served_release($root, '20261018T100000Z-aaaaa', array('index.html' => '<html>home v1</html>', 'news/index.html' => '<html>news v1</html>'));
        sb_retention_point_current($root, '20261018T100000Z-aaaaa');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $rules = file_get_contents($htaccess);
        $ids = sb_served_ids($rules);
        sb_assert(1 === count($ids), 'The Apache rules do not name exactly one served copy: ' . json_encode($ids));
        sb_assert(false === strpos($rules, 'static-bridge/current/index.html') && false === strpos($rules, 'static-bridge/current/$1/'), 'The Apache rules still serve files through the mutable current/ pointer.');
        $serving = 0;
        foreach (sb_test_apache_rule_groups($rules) as $group) {
            if (false !== strpos($group['rule'], 'index.html')) {
                ++$serving;
                sb_assert(false !== strpos($group['rule'], 'served/' . $ids[0] . '/') && false !== strpos(implode("\n", $group['conditions']), 'served/' . $ids[0] . '/'), 'A serving rule or its -f check does not use the served copy: ' . $group['rule']);
            }
        }
        sb_assert(2 === $serving, 'Expected the homepage and route serving rules.');
        $copy = $root . '/served/' . $ids[0];
        foreach (array('index.html', 'news/index.html', 'manifest.json') as $file) {
            sb_assert(is_file($copy . '/' . $file) && !is_link($copy . '/' . $file) && fileinode($copy . '/' . $file) === fileinode($release . '/' . $file), 'The served copy does not hard-link ' . $file . ' of the current release.');
        }
        sb_assert(!file_exists($copy . '/.ready'), 'The served copy contains files Apache never serves.');
        $recorded = get_option('static_bridge_served_copy', array());
        sb_assert(is_array($recorded) && $ids[0] === ($recorded['id'] ?? '') && 'link' === ($recorded['mode'] ?? '') && '20261018T100000Z-aaaaa' === ($recorded['release'] ?? ''), 'The served copy is not recorded with its release and hard-link mode: ' . json_encode($recorded));
        sb_assert(true === sb_private($plugin, 'update_routing_rules') && $ids === sb_served_ids(file_get_contents($htaccess)) && 1 === count(glob($root . '/served/*', GLOB_ONLYDIR)), 'Republishing unchanged rules created another served copy.');
    });
});

sb_test('Apache incremental updates and removals never change a file the rules have made servable', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $release = sb_served_release($root, '20261018T100000Z-bbbbb', array('index.html' => '<html>home v1</html>', 'news/index.html' => '<html>news v1</html>'));
        sb_retention_point_current($root, '20261018T100000Z-bbbbb');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $first = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($first), 'No served copy before the update.');
        $served = $root . '/served/' . $first[0] . '/news/index.html';
        $before = (string) @file_get_contents($served);
        $inode = @fileinode($served);
        $url = home_url('/news/');
        sb_served_render($url, '<html><body>news v2, a longer body ' . str_repeat('y', 500) . '</body></html>');
        $item = sb_served_refresh_item($url);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/news/') => $item);
        $result = sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $item, $release));
        sb_assert('done' === $result, 'The incremental refresh did not complete.');
        clearstatcache();
        sb_assert('<html>news v1</html>' === $before && $before === (string) @file_get_contents($served) && $inode === @fileinode($served), 'The file Apache served before the update changed in place.');
        $second = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($second) && $second[0] !== $first[0], 'The update did not switch Apache to a new served copy.');
        $new_file = $root . '/served/' . $second[0] . '/news/index.html';
        sb_assert(false !== strpos((string) @file_get_contents($new_file), 'news v2') && fileinode($new_file) === fileinode($release . '/news/index.html'), 'The new served copy does not link the updated page.');
        $recorded = get_option('static_bridge_served_copy', array());
        sb_assert(is_dir($root . '/served/' . $first[0]) && isset($recorded['retired'][$first[0]]), 'The previous copy was removed or not retired for its grace period.');

        $delete = sb_served_refresh_item($url, 'delete');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/news/') => $delete);
        sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $delete, $release)), 'The incremental removal did not complete.');
        $third = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($third) && $third[0] !== $second[0] && !file_exists($root . '/served/' . $third[0] . '/news/index.html') && is_file($root . '/served/' . $third[0] . '/index.html'), 'The removal was not published as a new served copy without the route.');
        sb_assert(false !== strpos((string) file_get_contents($new_file), 'news v2'), 'The removal unlinked the page from a copy Apache may still be serving.');
    });
});

sb_test('A full Apache publication switches to a copy of the new release and leaves the served copy intact', function () use ($plugin, $fixtureRoot, $source) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        sb_served_release($root, '20261018T100000Z-ccccc', array('index.html' => '<html>home v1</html>', 'news/index.html' => '<html>news v1</html>'));
        sb_retention_point_current($root, '20261018T100000Z-ccccc');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $first = sb_served_ids(file_get_contents($htaccess));
        $new = sb_served_release($root, '20261018T110000Z-ddddd', array('index.html' => '<html>home v2 ' . str_repeat('z', 300) . '</html>', 'news/index.html' => '<html>news v2</html>'));
        symlink('releases/20261018T110000Z-ddddd', $root . '/current.new-test');
        rename($root . '/current.new-test', $root . '/current');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the rules after the release swap failed.');
        $second = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($first) && 1 === count($second) && $first !== $second, 'The full publication did not switch Apache to a new served copy.');
        sb_assert('<html>home v1</html>' === @file_get_contents($root . '/served/' . $first[0] . '/index.html'), 'The copy served before the publication changed.');
        sb_assert(fileinode($root . '/served/' . $second[0] . '/index.html') === fileinode($new . '/index.html'), 'The new copy does not link the new release.');
    });
    $publish = sb_method_body($source, 'publish_release');
    $swap = strpos($publish, '@rename($temporary, $link)');
    $rules = strpos($publish, '$this->update_routing_rules()');
    $purge = strpos($publish, "queue_cloudflare_purge('everything'");
    sb_assert(false !== $swap && false !== $rules && false !== $purge && $swap < $rules && $rules < $purge, 'A full publication must publish the Apache rules after the swap and before queuing the purge.');
});

sb_test('Served copies are pruned after their grace period but never while .htaccess references them', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $release = sb_served_release($root, '20261018T100000Z-eeeee', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news</html>'));
        sb_retention_point_current($root, '20261018T100000Z-eeeee');
        $ids = array();
        for ($i = 0; $i < 3; $i++) {
            if ($i > 0) {
                sb_served_touch_manifest($release);
            }
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
            $ids[] = sb_served_ids(file_get_contents($htaccess))[0] ?? '';
        }
        sb_assert(3 === count(array_unique(array_filter($ids))), 'Three publications did not create three served copies: ' . json_encode($ids));
        list($s1, $s2, $s3) = $ids;
        $recorded = get_option('static_bridge_served_copy', array());
        sb_assert($s3 === ($recorded['id'] ?? '') && isset($recorded['retired'][$s1], $recorded['retired'][$s2]), 'The superseded copies were not retired.');
        $recorded['retired'][$s1] = time() - 3600;
        $recorded['retired'][$s2] = time() - 3600;
        update_option('static_bridge_served_copy', $recorded, false);
        // Another writer restored an older .htaccess that still names the first copy.
        file_put_contents($htaccess, str_replace('served/' . $s3 . '/', 'served/' . $s1 . '/', (string) file_get_contents($htaccess)));
        mkdir($root . '/served/.partial-20261018T000000Z-deadbeef/news', 0755, true);
        mkdir($root . '/served/20261018T000000Z-0badf00d', 0755, true);
        mkdir($root . '/served/not-a-static-bridge-copy', 0755, true);
        sb_private($plugin, 'prune_served_copies');
        clearstatcache();
        sb_assert(is_dir($root . '/served/' . $s1), 'A copy still referenced by .htaccess was pruned.');
        sb_assert(!file_exists($root . '/served/' . $s2), 'A retired copy past its grace period was not pruned.');
        sb_assert(is_dir($root . '/served/' . $s3), 'The recorded served copy was pruned.');
        sb_assert(!file_exists($root . '/served/.partial-20261018T000000Z-deadbeef'), 'An interrupted partial copy was not removed.');
        sb_assert(is_dir($root . '/served/20261018T000000Z-0badf00d'), 'An unknown copy was removed without a grace period.');
        sb_assert(is_dir($root . '/served/not-a-static-bridge-copy'), 'A folder the plugin did not create was removed.');
        $recorded = get_option('static_bridge_served_copy', array());
        sb_assert(isset($recorded['retired']['20261018T000000Z-0badf00d']) && $recorded['retired'][$s1] > time() - 60, 'The unknown copy or the re-referenced copy did not start a new grace period.');

        // .htaccess that cannot be read safely: nothing is removed.
        $recorded['retired']['20261018T000000Z-0badf00d'] = time() - 3600;
        $recorded['retired'][$s1] = time() - 3600;
        update_option('static_bridge_served_copy', $recorded, false);
        $kept = (string) file_get_contents($htaccess);
        unlink($htaccess);
        file_put_contents($root . '/elsewhere.htaccess', $kept);
        symlink($root . '/elsewhere.htaccess', $htaccess);
        sb_private($plugin, 'prune_served_copies');
        clearstatcache();
        sb_assert(is_dir($root . '/served/' . $s1) && is_dir($root . '/served/20261018T000000Z-0badf00d'), 'Copies were pruned although .htaccess could not be read safely.');
        unlink($htaccess);
        file_put_contents($htaccess, str_replace('served/' . $s1 . '/', 'served/' . $s3 . '/', $kept));
        sb_private($plugin, 'prune_served_copies');
        clearstatcache();
        sb_assert(!file_exists($root . '/served/' . $s1) && !file_exists($root . '/served/20261018T000000Z-0badf00d') && is_dir($root . '/served/' . $s3), 'Unreferenced retired copies were not pruned once .htaccess was readable again.');
    });
});

sb_test('Without hard links the served copy is a byte copy, and without any copy the rules fall back to current/', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $release = sb_served_release($root, '20261018T100000Z-fffff', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news</html>'));
        sb_retention_point_current($root, '20261018T100000Z-fffff');
        $property = new ReflectionProperty($plugin, 'served_copy_hardlinks');
        if (PHP_VERSION_ID < 80100) {
            $property->setAccessible(true);
        }
        $property->setValue($plugin, false);
        try {
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules without hard links failed.');
            $ids = sb_served_ids(file_get_contents($htaccess));
            sb_assert(1 === count($ids), 'No served copy was created without hard links.');
            $copy = $root . '/served/' . $ids[0] . '/news/index.html';
            sb_assert('<html>news</html>' === file_get_contents($copy) && fileinode($copy) !== fileinode($release . '/news/index.html'), 'The fallback did not produce an independent byte copy.');
            sb_assert('copy' === (get_option('static_bridge_served_copy', array())['mode'] ?? ''), 'The byte-copy mode is not recorded.');
        } finally {
            $property->setValue($plugin, null);
        }
        if (function_exists('posix_geteuid') && 0 === posix_geteuid()) {
            return; // root ignores the permission bits used below
        }
        chmod($root . '/served', 0555);
        sb_served_touch_manifest($release);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $published = sb_private($plugin, 'update_routing_rules');
        chmod($root . '/served', 0755);
        $rules = file_get_contents($htaccess);
        sb_assert(true === $published && array() === sb_served_ids($rules) && false !== strpos($rules, 'RewriteRule ^(.+?)/?$ wp-content/static-bridge/current/$1/index.html'), 'Without a usable served copy the rules must fall back to current/ (the 2.0.19 behaviour).');
        $activity = json_encode($GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] ?? array(), JSON_UNESCAPED_SLASHES);
        sb_assert(false !== strpos($activity, 'current/') && false !== strpos($activity, '"error":true'), 'The fallback to current/ was not reported as a warning in Attività.');
        sb_assert(true === sb_private($plugin, 'update_routing_rules') && 1 === count(sb_served_ids(file_get_contents($htaccess))), 'The rules did not return to a served copy once one could be created.');
    });
});

sb_test('An Apache push whose rules cannot be published stays queued instead of reporting success', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $release = sb_served_release($root, '20261018T100000Z-ggggg', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news v1</html>'));
        sb_retention_point_current($root, '20261018T100000Z-ggggg');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $first = sb_served_ids(file_get_contents($htaccess));
        $url = home_url('/news/');
        sb_served_render($url, '<html><body>news v2</body></html>');
        $token = 'cccccccc-cccc-4ccc-cccc-cccccccccccc';
        sb_private($plugin, 'set_post_push_status', array($token, 'queued', array('path' => '/news/')));
        $item = sb_served_refresh_item($url) + array('manual_push_token' => $token);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/news/') => $item);
        if (!(function_exists('posix_geteuid') && 0 === posix_geteuid())) {
            chmod($htaccess, 0444);
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $item, $release));
            chmod($htaccess, 0644);
            $status = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            sb_assert('retry' === $result && 'retrying' === ($status[$token]['status'] ?? '') && false !== strpos((string) ($status[$token]['last_error'] ?? ''), '.htaccess'), 'A push Apache cannot serve yet was reported as completed: ' . json_encode(array($result, $status[$token] ?? null)));
            sb_assert(isset($queue[sha1('/news/')]) && 1 === (int) $queue[sha1('/news/')]['attempts'], 'The unpublished push did not stay queued for a retry.');
            sb_assert($first === sb_served_ids(file_get_contents($htaccess)) && array($first[0]) === array_map('basename', glob($root . '/served/*', GLOB_ONLYDIR)), 'A copy the rules never referenced was left behind, or the served copy changed.');
            sb_assert('<html>news v1</html>' === file_get_contents($root . '/served/' . $first[0] . '/news/index.html'), 'The page served by the old rules changed.');
            $item = $queue[sha1('/news/')];
        }
        $result = sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $item, $release));
        $status = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
        $now = sb_served_ids(file_get_contents($htaccess));
        sb_assert('done' === $result && 'completed' === ($status[$token]['status'] ?? '') && 1 === count($now) && $now !== $first && false !== strpos((string) file_get_contents($root . '/served/' . $now[0] . '/news/index.html'), 'news v2'), 'The retried push was not published once .htaccess was writable.');

        // A site whose .htaccess has no Static Bridge rules (e.g. a CLI cron on Nginx) completes as before.
        file_put_contents($htaccess, "# BEGIN WordPress\n# END WordPress\n");
        if (!(function_exists('posix_geteuid') && 0 === posix_geteuid())) {
            chmod($htaccess, 0444);
        }
        sb_served_render($url, '<html><body>news v3</body></html>');
        $item = sb_served_refresh_item($url) + array('manual_push_token' => $token);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/news/') => $item);
        $result = sb_private($plugin, 'process_incremental_item', array(sha1('/news/'), $item, $release));
        chmod($htaccess, 0644);
        $status = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
        sb_assert('done' === $result && 'completed' === ($status[$token]['status'] ?? ''), 'A push on a site without Static Bridge Apache rules no longer completes.');
    });
});

sb_test('An Apache removal whose rules cannot be published stays queued and is not purged yet (note 28)', function () use ($plugin, $fixtureRoot) {
    // Hardening note 28 of the 3 November 2026 audit: the delete paths completed the item and queued the
    // purge without checking that .htaccess stopped naming the copy that still contains the route.
    if (function_exists('posix_geteuid') && 0 === posix_geteuid()) {
        throw new SB_Test_Skip('Root ignores the read-only .htaccess used by this check.');
    }
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        sb_cf_settings(array('cloudflare_purge' => 1, 'strict_mode' => 0, 'excluded_paths' => array()));
        $release = sb_served_release($root, '20261018T100000Z-jjjjj', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news</html>', 'old/index.html' => '<html>old</html>', 'moved/index.html' => '<html>moved</html>'));
        sb_retention_point_current($root, '20261018T100000Z-jjjjj');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $old = home_url('/old/');
        $GLOBALS['sb_test_http_responses'][add_query_arg('static_bridge_bypass', '1', $old)] = array('response' => array('code' => 404), 'headers' => array(), 'body' => 'Not found', '_sb_strip_render_header' => true);
        $moved = home_url('/moved/');
        $GLOBALS['sb_test_http_responses'][add_query_arg('static_bridge_bypass', '1', $moved)] = array('response' => array('code' => 301), 'headers' => array('Location' => 'https://outside.example.test/moved/'), 'body' => '');
        foreach (array('/news/' => sb_served_refresh_item(home_url('/news/'), 'delete'), '/old/' => sb_served_refresh_item($old), '/moved/' => sb_served_refresh_item($moved)) as $path => $item) {
            $first = sb_served_ids(file_get_contents($htaccess));
            $url = home_url($path);
            $key = sha1($path);
            $token = 'dddddddd-dddd-4ddd-dddd-' . substr(sha1($path), 0, 12);
            // A manual push that meets a redirect ends without removing the copy, so /moved/ is a plain refresh.
            $manual = '/moved/' !== $path;
            if ($manual) {
                sb_private($plugin, 'set_post_push_status', array($token, 'queued', array('path' => $path)));
                $item += array('manual_push_token' => $token);
            }
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array($key => $item);
            unset($GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending']);
            chmod($htaccess, 0444);
            $result = sb_private($plugin, 'process_incremental_item', array($key, $item, $release));
            chmod($htaccess, 0644);
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            $status = get_option(Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION, array());
            $pending = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending'] ?? array();
            sb_assert(!is_file($release . $path . 'index.html'), 'The route ' . $path . ' was not removed from the release.');
            sb_assert('retry' === $result && isset($queue[$key]) && 1 === (int) $queue[$key]['attempts'], 'A removal Apache still serves was completed: ' . $path . ' ' . json_encode($result));
            sb_assert(false !== strpos((string) ($manual ? ($status[$token]['last_error'] ?? '') : ($queue[$key]['last_error'] ?? '')), '.htaccess') && (!$manual || 'retrying' === ($status[$token]['status'] ?? '')), 'The removal of ' . $path . ' does not say that .htaccess was not updated.');
            sb_assert(empty($pending['urls'][$url]) && empty($pending['everything']), 'The edge was purged while Apache still served ' . $path . ' from the previous copy.');
            sb_assert($first === sb_served_ids(file_get_contents($htaccess)), 'The rules changed although .htaccess was read-only.');
            $result = sb_private($plugin, 'process_incremental_item', array($key, $queue[$key], $release));
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
            $pending = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending'] ?? array();
            $now = sb_served_ids(file_get_contents($htaccess));
            sb_assert('done' === $result && !isset($queue[$key]) && 1 === count($now) && $now !== $first && !file_exists($root . '/served/' . $now[0] . $path . 'index.html') && is_file($root . '/served/' . $now[0] . '/index.html'), 'The retried removal of ' . $path . ' was not published once .htaccess was writable.');
            sb_assert(!empty($pending['urls'][$url]), 'The completed removal of ' . $path . ' did not queue its Cloudflare purge.');
        }
    });
});

sb_test('A single-post refresh of a password-protected post removes its static copy without rendering it (note 29)', function () use ($plugin, $fixtureRoot) {
    // Hardening note 29 of the 3 November 2026 audit: the manual push and the full export leave out a
    // post with a password; the incremental worker must treat it as not public as well.
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $old_posts = $GLOBALS['sb_test_posts'];
        $old_urls = $GLOBALS['sb_test_post_urls'];
        try {
            $release = sb_served_release($root, '20261018T100000Z-kkkkk', array('index.html' => '<html>home</html>', 'riservato/index.html' => '<html>public copy</html>'));
            sb_retention_point_current($root, '20261018T100000Z-kkkkk');
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
            $url = home_url('/riservato/');
            $GLOBALS['sb_test_posts'] = array(array('ID' => 4242, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => 'segreta', 'post_title' => 'Riservato', 'post_content' => '', 'meta' => array()));
            $GLOBALS['sb_test_post_urls'] = array(4242 => $url);
            sb_served_render($url, '<html><body><form class="post-password-form">Password</form></body></html>');
            $item = array('url' => $url, 'path' => '/riservato/', 'action' => 'refresh', 'role' => 'single', 'post_id' => 4242, 'builders' => array(), 'token' => wp_generate_uuid4(), 'attempts' => 0);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/riservato/') => $item);
            $GLOBALS['sb_test_http_calls'] = array();
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/riservato/'), $item, $release));
            sb_assert('done' === $result && !file_exists($release . '/riservato/index.html'), 'The static copy of a password-protected post was kept or replaced: ' . json_encode($result));
            sb_assert(array() === $GLOBALS['sb_test_http_calls'], 'The password-protected post was rendered instead of being removed.');
            $GLOBALS['sb_test_posts'][0]['post_password'] = '';
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/riservato/') => $item);
            sb_served_render($url, '<html><body>public again</body></html>');
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/riservato/'), $item, $release));
            sb_assert('done' === $result && false !== strpos((string) @file_get_contents($release . '/riservato/index.html'), 'public again'), 'A public post is no longer written by a single-post refresh.');
        } finally {
            $GLOBALS['sb_test_posts'] = $old_posts;
            $GLOBALS['sb_test_post_urls'] = $old_urls;
        }
    });
});

sb_test('The SSI guard recognises the Nginx perl command and the Apache block removes mod_include from static copies (notes 35, 36)', function () use ($plugin) {
    foreach (array('<!--#perl sub="main::x" -->', '<!--# perl sub="x" -->', '<!--#PERL arg="1"-->') as $directive) {
        sb_assert(Static_Bridge_Header_Fragments::contains_ssi_directive('<p>a</p>' . $directive), 'The SSI guard missed ' . $directive . '.');
    }
    sb_assert(!Static_Bridge_Header_Fragments::contains_ssi_directive('<!--#perlish -->') && !Static_Bridge_Header_Fragments::contains_ssi_directive('<!-- perl -->'), 'The SSI guard rejects a comment that is not a perl command.');
    $block = sb_private($plugin, 'archive_protection_block');
    sb_assert(1 === preg_match('@<IfModule mod_include\.c>\s*<IfModule mod_mime\.c>\s*<If "%\{REQUEST_FILENAME\} =~ m#/wp-content/static-bridge/#">\s*RemoveOutputFilter \.html \.htm \.shtml\s*</If>\s*</IfModule>\s*</IfModule>\s*# END Static Bridge Archive Protection$@', $block), 'The Apache protection block does not take mod_include off the static copies: ' . $block);
});

sb_test('Cloudflare purges on Apache wait until the rules serve the published content', function () use ($plugin, $fixtureRoot) {
    if (function_exists('posix_geteuid') && 0 === posix_geteuid()) {
        throw new SB_Test_Skip('Root ignores the read-only .htaccess used by this check.');
    }
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        sb_cf_settings(array('cloudflare_purge' => 1, 'strict_mode' => 0, 'excluded_paths' => array()));
        $release = sb_served_release($root, '20261018T100000Z-hhhhh', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news v1</html>'));
        sb_retention_point_current($root, '20261018T100000Z-hhhhh');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $first = sb_served_ids(file_get_contents($htaccess));
        // The release changed but the rules still name the previous copy.
        file_put_contents($release . '/news/index.html.tmp-test', '<html>news v2</html>');
        rename($release . '/news/index.html.tmp-test', $release . '/news/index.html');
        sb_served_touch_manifest($release);
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/news/')), 'test'));
        chmod($htaccess, 0444);
        $GLOBALS['sb_test_http_calls'] = array();
        $status = sb_private($plugin, 'run_cloudflare_purge');
        chmod($htaccess, 0644);
        $pending = $GLOBALS['sb_test_options']['static_bridge_cloudflare_purge_pending'] ?? array();
        sb_assert(empty($GLOBALS['sb_test_http_calls']) && 'waiting' === ($status['status'] ?? '') && !empty($pending['urls']) && 0 === (int) $pending['attempts'] && isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_cloudflare_purge']), 'The edge was purged while Apache still served the previous copy: ' . json_encode($status));
        $status = sb_private($plugin, 'run_cloudflare_purge');
        $now = sb_served_ids(file_get_contents($htaccess));
        sb_assert('ok' === ($status['status'] ?? '') && 1 === count($GLOBALS['sb_test_http_calls']) && $now !== $first && '<html>news v2</html>' === file_get_contents($root . '/served/' . $now[0] . '/news/index.html'), 'The purge did not first publish the rules for the current content: ' . json_encode($status));
    });
});

sb_test('Deactivation, uninstall, AIO export and retention account for served copies', function () use ($plugin, $fixtureRoot, $source, $pluginFile) {
    sb_assert(in_array('static-bridge/served', $plugin->exclude_ai1wm_current_pointer(array()), true), 'All-in-One backups would archive every served copy (hard links are not preserved).');
    $uninstaller = file_get_contents(dirname($pluginFile) . '/uninstaller.php');
    sb_assert(false !== strpos($uninstaller, "'static_bridge_served_copy_maintenance'"), 'Uninstall does not clear the served-copy maintenance hook.');
    sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), 'self::SERVED_COPY_HOOK'), 'Deactivation leaves the served-copy maintenance hook scheduled.');
    sb_assert(false !== strpos($source, "add_action(self::SERVED_COPY_HOOK, array(\$this, 'process_served_copy_maintenance'));"), 'The served-copy maintenance hook is not registered.');
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        mkdir($root . '/served/20261018T000000Z-0badf00d', 0755, true);
        sb_assert(true === sb_private($plugin, 'has_archived_releases'), 'Deactivation would drop the archive protection while served copies remain.');
        $release = sb_served_release($root, '20261018T100000Z-iiiii', array('index.html' => str_repeat('a', 1000), 'news/index.html' => str_repeat('b', 3000)));
        mkdir($root . '/served/keep', 0755, true);
        link($release . '/news/index.html', $root . '/served/keep/linked.html');
        $bytes = 0;
        sb_private($plugin, 'remove_retention_tree', array($release, microtime(true) + 10, &$bytes, 0));
        sb_assert(!file_exists($release) && $bytes < 3000 && $bytes >= 1000, 'Retention counted bytes still held by a served copy as freed: ' . $bytes);
    });
});

sb_test('Apache rules left on current/ by 2.0.19 or by another writer are moved back to the served copy by the maintenance cron', function () use ($plugin, $fixtureRoot) {
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        sb_served_release($root, '20261018T100000Z-jjjjj', array('index.html' => '<html>home</html>', 'news/index.html' => '<html>news</html>'));
        sb_retention_point_current($root, '20261018T100000Z-jjjjj');
        // The .htaccess an upgraded 2.0.19 site still has.
        sb_assert(true === sb_private($plugin, 'write_rewrite_rules', array(true, 'current')), 'Could not write 2.0.19-style rules.');
        $diagnostic = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
        sb_assert('warning' === ($diagnostic['status'] ?? ''), 'The diagnostic does not warn that Apache still serves current/: ' . json_encode($diagnostic));
        $admin = $GLOBALS['sb_test_is_admin'];
        $GLOBALS['sb_test_is_admin'] = true;
        unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_served_copy_maintenance']);
        try {
            $plugin->maybe_schedule_served_copy_adoption();
        } finally {
            $GLOBALS['sb_test_is_admin'] = $admin;
        }
        sb_assert(isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_served_copy_maintenance']), 'An upgraded site with rules on current/ is not scheduled for adoption.');
        unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_served_copy_maintenance']);
        $plugin->process_served_copy_maintenance();
        $first = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($first) && false === strpos((string) file_get_contents($htaccess), 'static-bridge/current/index.html'), 'The maintenance cron did not move Apache to a served copy.');
        $diagnostic = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
        sb_assert('pass' === ($diagnostic['status'] ?? ''), 'The diagnostic does not accept rules on a served copy: ' . json_encode($diagnostic));

        // Another writer restores rules naming an older copy while the release has moved on.
        $old_rules = (string) file_get_contents($htaccess);
        $release = realpath($root . '/current');
        file_put_contents($release . '/news/index.html.tmp-test', '<html>news v2</html>');
        rename($release . '/news/index.html.tmp-test', $release . '/news/index.html');
        sb_served_touch_manifest($release);
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the second copy failed.');
        file_put_contents($htaccess, $old_rules);
        $diagnostic = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'rewrite-rules', 'type' => 'rewrite'), array()));
        sb_assert('fail' === ($diagnostic['status'] ?? ''), 'The diagnostic does not report rules that serve an older copy: ' . json_encode($diagnostic));
        sb_assert(is_dir($root . '/served/' . $first[0]), 'The copy named by the restored rules was removed.');
        $plugin->process_served_copy_maintenance();
        $now = sb_served_ids(file_get_contents($htaccess));
        sb_assert(1 === count($now) && $now !== $first && '<html>news v2</html>' === file_get_contents($root . '/served/' . $now[0] . '/news/index.html'), 'The maintenance cron did not republish the rules for the current release.');
    });
});

sb_test('A release that changes while its served copy is built keeps the previous copy instead of falling back to current/', function () use ($plugin, $fixtureRoot) {
    if (!function_exists('proc_open')) {
        throw new SB_Test_Skip('proc_open is required to change the release concurrently.');
    }
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $pages = array('index.html' => '<html>home</html>');
        for ($i = 0; $i < 3000; $i++) {
            $pages['p' . $i . '/index.html'] = '<html>page ' . $i . '</html>';
        }
        $release = sb_served_release($root, '20261018T100000Z-kkkkk', $pages);
        sb_retention_point_current($root, '20261018T100000Z-kkkkk');
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $first = sb_served_ids(file_get_contents($htaccess));
        $stop = $root . '/writer.stop';
        // Another worker replaces the manifest continuously, as an incremental update would.
        $code = '$m = $argv[1]; $stop = $argv[2]; $n = 0; $end = microtime(true) + 30; while (!file_exists($stop) && microtime(true) < $end) {'
            . 'file_put_contents($m . ".tmp-writer", json_encode(array("release" => "20261018T100000Z-kkkkk", "pages_saved" => 3001, "incremental_updates" => ++$n))); rename($m . ".tmp-writer", $m); usleep(200); }';
        $writer = proc_open(array(PHP_BINARY, '-n', '-r', $code, $release . '/manifest.json', $stop), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', '/dev/null', 'w'), 2 => array('file', '/dev/null', 'w')), $pipes);
        sb_assert(is_resource($writer), 'Could not start the concurrent manifest writer.');
        try {
            usleep(100000);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            unset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_served_copy_maintenance']);
            $published = sb_private($plugin, 'update_routing_rules');
        } finally {
            file_put_contents($stop, '1');
            proc_close($writer);
        }
        $rules = file_get_contents($htaccess);
        sb_assert(true === $published && $first === sb_served_ids($rules) && false === strpos($rules, 'static-bridge/current/index.html'), 'A release changing during the copy made the rules leave the previous served copy.');
        sb_assert(empty($GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION]) && isset($GLOBALS['sb_test_scheduled_hooks']['static_bridge_served_copy_maintenance']), 'A transient change was reported as a fallback, or no retry was scheduled.');
        sb_assert(array() === glob($root . '/served/.partial-*') && 1 === count(glob($root . '/served/*', GLOB_ONLYDIR)), 'Abandoned partial copies were left behind.');
        sb_assert(true === sb_private($plugin, 'update_routing_rules') && 1 === count(sb_served_ids(file_get_contents($htaccess))) && $first !== sb_served_ids(file_get_contents($htaccess)), 'The next publication did not serve the changed release.');
    });
});

sb_test('Local Apache never serves a cut or padded page while pages and releases are republished', function () use ($plugin, $fixtureRoot) {
    $httpd = getenv('STATIC_BRIDGE_APACHE_BIN');
    if (!$httpd || !is_executable($httpd) || !function_exists('proc_open')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN to run this Apache publication race check.');
    }
    $apache_root = dirname(dirname($httpd));
    $modules = $apache_root . '/modules';
    foreach (array('rewrite', 'headers', 'authz_core', 'dir', 'mime', 'unixd', 'log_config') as $module) {
        if (!is_file($modules . '/mod_' . $module . '.so')) {
            throw new SB_Test_Skip('Apache module mod_' . $module . ' is not available next to STATIC_BRIDGE_APACHE_BIN.');
        }
    }
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin, $fixtureRoot, $httpd, $apache_root, $modules) {
        $socket = stream_socket_server('tcp://127.0.0.1:0', $socket_error, $socket_message);
        sb_assert(false !== $socket, 'Could not reserve a local Apache test port: ' . $socket_message);
        $port = (int) substr(strrchr((string) stream_socket_get_name($socket, false), ':'), 1);
        fclose($socket);
        // Every version is self-checking: the same number opens and closes it, sizes alternate.
        $page = function ($version, $route) {
            $padding = str_repeat(chr(97 + $version % 26), 0 === $version % 2 ? 900 + $version : 70000 + 7 * $version);
            return '<html><!--v:' . $version . ' ' . $route . '-->' . $padding . '<!--v:' . $version . ' ' . $route . '--></html>';
        };
        $release_id = '20261018T120000Z-race0';
        $release = sb_served_release($root, $release_id, array('index.html' => $page(0, 'home'), 'news/index.html' => $page(0, 'news')));
        sb_retention_point_current($root, $release_id);
        file_put_contents($root . '/.enabled', "enabled\n");
        $fallback = ABSPATH . 'index.php';
        $had_fallback = file_exists($fallback);
        $server_root = $fixtureRoot . '/apache-publication-race';
        $config_path = $server_root . '/httpd.conf';
        $log_path = $server_root . '/error.log';
        $process = null;
        $readers = array();
        try {
            if (!$had_fallback) {
                file_put_contents($fallback, 'WORDPRESS_FALLBACK');
            }
            sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Could not publish the Apache rules for the race fixture.');
            sb_assert(wp_mkdir_p($server_root), 'Could not create the isolated Apache server root.');
            $load = '';
            foreach (array('authz_core', 'dir', 'mime', 'rewrite', 'headers', 'unixd', 'log_config') as $module) {
                $load .= 'LoadModule ' . $module . '_module "' . $modules . '/mod_' . $module . ".so\"\n";
            }
            $docroot = rtrim(ABSPATH, '/');
            $config = 'ServerRoot "' . $server_root . "\"\n" . 'Listen 127.0.0.1:' . $port . "\nServerName 127.0.0.1\n"
                . 'PidFile "' . $server_root . "/httpd.pid\"\n" . 'DefaultRuntimeDir "' . $server_root . "\"\n" . 'Mutex file:' . $server_root . " default\n"
                . 'ErrorLog "' . $log_path . "\"\nLogLevel warn\n" . $load
                . "TypesConfig /dev/null\nAddType text/html .html\nAddType text/plain .php .json\nDirectoryIndex index.html index.php\nAccessFileName .htaccess\n"
                . "<Directory />\n Options FollowSymLinks\n AllowOverride None\n Require all denied\n</Directory>\n"
                . 'DocumentRoot "' . $docroot . "\"\n"
                . '<Directory "' . $docroot . "\">\n Options FollowSymLinks\n AllowOverride All\n Require all granted\n Header always set X-Fixture-Handler wordpress\n</Directory>\n"
                . '<Directory "' . $docroot . "/wp-content/static-bridge\">\n Header always set X-Fixture-Handler static-file\n</Directory>\n";
            sb_assert(false !== file_put_contents($config_path, $config), 'Could not write the isolated Apache configuration.');
            $environment = array('PATH' => (string) getenv('PATH'));
            if (is_dir($apache_root . '/shared-libs')) {
                $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
            }
            $process = proc_open(array($httpd, '-f', $config_path, '-DFOREGROUND'), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a')), $pipes, $server_root, $environment);
            sb_assert(is_resource($process), 'Could not start the isolated Local Apache server.');
            $deadline = microtime(true) + 5;
            do {
                $probe = @file_get_contents('http://127.0.0.1:' . $port . '/news/');
                if (is_string($probe) && 0 === strpos($probe, '<html><!--v:0 news-->')) {
                    break;
                }
                usleep(100000);
            } while (microtime(true) < $deadline);
            sb_assert(is_string($probe) && 0 === strpos($probe, '<html><!--v:0 news-->'), 'The isolated Apache fixture did not serve the release.');

            $reader_code = '$base = $argv[1]; $stop = $argv[2]; $report = array("total" => 0, "bad" => array()); $end = microtime(true) + 90;'
                . 'while (!file_exists($stop) && microtime(true) < $end) { foreach (array("/" => "home", "/news/" => "news") as $path => $route) {'
                . '$body = @file_get_contents($base . $path, false, stream_context_create(array("http" => array("ignore_errors" => true, "timeout" => 5))));'
                . '$headers = (array) http_get_last_response_headers(); $status = isset($headers[0]) && preg_match("/^HTTP\\/\\S+\\s+(\\d+)/", $headers[0], $m) ? $m[1] : "0"; $length = -1;'
                . 'foreach ($headers as $h) { if (0 === stripos($h, "Content-Length:")) { $length = (int) trim(substr($h, 15)); } }'
                . '$report["total"]++; $body = (string) $body;'
                . '$valid = preg_match("~\\\\A<html><!--v:([0-9]+) " . $route . "-->~", $body, $v) && strlen($body) > strlen($v[0]) + 1;'
                . 'if ($valid) { $tail = "<!--v:" . $v[1] . " " . $route . "--></html>"; $middle = substr($body, strlen($v[0]), -strlen($tail));'
                . '$valid = substr($body, -strlen($tail)) === $tail && "" !== $middle && strspn($middle, $middle[0]) === strlen($middle); }'
                . 'if ("200" !== $status || !$valid || $length !== strlen($body)) {'
                . '$key = $path . " " . $status . " " . strlen($body) . "/" . $length . " " . substr($body, 0, 24) . "..." . bin2hex(substr($body, -12)); $report["bad"][$key] = ($report["bad"][$key] ?? 0) + 1; } } }'
                . 'file_put_contents($argv[3], json_encode($report));';
            for ($r = 0; $r < 6; $r++) {
                $readers[$r] = proc_open(array(PHP_BINARY, '-n', '-r', $reader_code, 'http://127.0.0.1:' . $port, $server_root . '/readers.stop', $server_root . '/reader-' . $r . '.json'), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a')), $reader_pipes);
                sb_assert(is_resource($readers[$r]), 'Could not start a concurrent anonymous reader.');
            }
            usleep(300000);
            $current_release = $release;
            $publications = 0;
            for ($version = 1; $version <= 600; $version++) {
                if (0 === $version % 60) {
                    // Full publication: a new release and an atomic swap of current.
                    $next_id = '20261018T12' . sprintf('%04d', $version) . 'Z-race' . ($version / 60);
                    $current_release = sb_served_release($root, $next_id, array('index.html' => $page($version, 'home'), 'news/index.html' => $page($version, 'news')));
                    symlink('releases/' . $next_id, $root . '/current.new-race');
                    rename($root . '/current.new-race', $root . '/current');
                } else {
                    // Push / incremental update: the same atomic write the queue worker uses.
                    $written = sb_private($plugin, 'write_incremental_page', array($current_release, home_url(0 === $version % 3 ? '/' : '/news/'), $page($version, 0 === $version % 3 ? 'home' : 'news')));
                    sb_assert(is_array($written) && sb_private($plugin, 'update_incremental_manifest', array($current_release, 0)), 'An incremental write failed in the race fixture.');
                }
                sb_private($plugin, 'update_routing_rules');
                ++$publications;
                usleep(4000);
            }
            usleep(300000);
            file_put_contents($server_root . '/readers.stop', '1');
            $total = 0;
            $bad = array();
            foreach ($readers as $r => $reader) {
                proc_close($reader);
                $report = json_decode((string) @file_get_contents($server_root . '/reader-' . $r . '.json'), true);
                sb_assert(is_array($report), 'A concurrent reader did not report.');
                $total += (int) $report['total'];
                foreach ((array) $report['bad'] as $key => $count) {
                    $bad[$key] = ($bad[$key] ?? 0) + $count;
                }
            }
            $readers = array();
            sb_assert($total > 2000, 'The readers made too few requests to exercise the race: ' . $total);
            sb_assert(empty($bad), array_sum($bad) . ' of ' . $total . ' responses during ' . $publications . ' publications were not a complete version: ' . json_encode(array_slice($bad, 0, 6, true)));
        } finally {
            if (!empty($readers)) {
                @file_put_contents($server_root . '/readers.stop', '1');
                foreach ($readers as $reader) {
                    @proc_close($reader);
                }
            }
            if (is_resource($process)) {
                proc_terminate($process);
                proc_close($process);
            }
            if (!$had_fallback && is_file($fallback)) {
                unlink($fallback);
            }
        }
    });
});

register_shutdown_function(function () use ($fixtureRoot) {
    $remove = function ($path) use (&$remove) {
        if (is_link($path) || is_file($path)) {
            @unlink($path);
            return;
        }
        if (!is_dir($path)) {
            return;
        }
        foreach (scandir($path) as $entry) {
            if ('.' === $entry || '..' === $entry) {
                continue;
            }
            $remove($path . DIRECTORY_SEPARATOR . $entry);
        }
        @rmdir($path);
    };
    $remove($fixtureRoot);
});


sb_test('XB and other plugins: precise component routes, styles releases, public actions and loops', function () use ($fixtureRoot) {
    $plugin = new Static_Bridge_Plugin();
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'xb-contract-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $old_options = array();
    foreach (array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION) as $option) {
        $old_options[$option] = array_key_exists($option, $GLOBALS['sb_test_options']) ? $GLOBALS['sb_test_options'][$option] : null;
    }
    $queued_paths = function () {
        $paths = array();
        foreach (get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()) as $item) {
            $paths[] = $item['path'];
        }
        sort($paths);
        return $paths;
    };
    $reset = function () use (&$plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin = new Static_Bridge_Plugin();
    };
    try {
        sb_assert(wp_mkdir_p($release . '/news/one') && wp_mkdir_p($release . '/page-two'), 'Could not create the XB contract fixture.');
        foreach (array('/index.html', '/news/one/index.html', '/page-two/index.html') as $file) {
            sb_assert(false !== file_put_contents($release . $file, '<html>x</html>'), 'Could not seed a static route.');
        }
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its test release.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array());
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $component = new WP_Post(array('ID' => 8801, 'post_type' => 'wp_block', 'post_status' => 'publish'));

        // 1. The plugin that owns a component names its pages: only those are regenerated.
        $reset();
        $GLOBALS['sb_test_filter_values']['static_bridge_dependents_for_post'] = array('/page-two/', home_url('/news/one/'), '/page-two/');
        $plugin->maybe_queue_shared_content_post(8801, $component, true, null);
        sb_assert(array('/news/one/', '/page-two/') === $queued_paths(), 'Known dependents of a component were not queued exactly.');

        // An answer naming another site, a file, a query or a traversal is not trusted: everything is refreshed.
        foreach (array(array('/page-two/', 'https://evil.example/x/'), array('/page-two/', '/../etc/'), array('/wp-config.php'), array('/?p=1')) as $untrusted) {
            $reset();
            $GLOBALS['sb_test_filter_values']['static_bridge_dependents_for_post'] = $untrusted;
            $plugin->maybe_queue_shared_content_post(8801, $component, true, null);
            sb_assert(array('/', '/news/one/', '/page-two/') === $queued_paths(), 'An untrusted dependents answer did not fall back to the full refresh: ' . implode(' ', $untrusted));
        }
        $reset();
        $GLOBALS['sb_test_filter_values']['static_bridge_dependents_for_post'] = array_fill(0, Static_Bridge_Plugin::MAX_KNOWN_DEPENDENTS + 1, '/page-two/');
        $plugin->maybe_queue_shared_content_post(8801, $component, true, null);
        sb_assert(3 === count($queued_paths()), 'Too many dependents did not fall back to the full refresh.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_dependents_for_post']);

        // 2. Opening a component in the editor changes nothing on the site.
        $reset();
        $GLOBALS['sb_test_posts'] = array(array('ID' => 8801, 'post_type' => 'wp_block', 'post_status' => 'publish'));
        $plugin->maybe_queue_shared_content_meta(1, 8801, '_edit_lock', '1:1');
        sb_assert(array() === $queued_paths(), 'An editor lock on a shared post queued static routes.');

        // 3. XB styles and settings releases change every page; a release of pages alone does not here.
        $reset();
        $plugin->maybe_queue_xb_release(7, array('post:5'));
        sb_assert(array() === $queued_paths(), 'An XB release of pages queued a global refresh.');
        $reset();
        $plugin->maybe_queue_xb_release(8, array('post:5', 'styles'));
        sb_assert(array('/', '/news/one/', '/page-two/') === $queued_paths(), 'An XB styles release did not refresh every static route.');
        $reset();
        $plugin->maybe_queue_xb_release(9, 'settings');
        sb_assert(array() === $queued_paths(), 'A malformed XB release payload was acted upon.');

        // 4. Public action: only routes of this site.
        $reset();
        $plugin->queue_public_paths(array('/page-two/', 'https://evil.example/', '/../secret/', 42, '//evil.example/x/'), 'test');
        sb_assert(array('/page-two/') === $queued_paths(), 'The public queue action accepted a route outside this site.');

        // 5. XB loops are query pages; other builders answer through the filter.
        $loop = new WP_Post(array('ID' => 8802, 'post_type' => 'page', 'post_status' => 'publish', 'post_content' => '<!-- wp:xb/loop {"source":{"kind":"preset","id":"posts"}} --><!-- /wp:xb/loop -->'));
        $plain = new WP_Post(array('ID' => 8803, 'post_type' => 'page', 'post_status' => 'publish', 'post_content' => '<!-- wp:xb/element {"tag":"p"} /-->'));
        sb_assert(sb_private($plugin, 'post_has_query_loop', array($loop)), 'An XB loop was not recognized as a query page.');
        sb_assert(!sb_private($plugin, 'post_has_query_loop', array($plain)), 'A page without lists was treated as a query page.');
        $GLOBALS['sb_test_filter_values']['static_bridge_post_has_query_loop'] = true;
        sb_assert(sb_private($plugin, 'post_has_query_loop', array($plain)), 'The query-page filter was ignored.');
        $GLOBALS['sb_test_filter_values']['static_bridge_post_has_query_loop'] = 'yes';
        sb_assert(!sb_private($plugin, 'post_has_query_loop', array($plain)), 'A non-boolean filter answer was trusted.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_post_has_query_loop']);

        // Hooks are registered, and a published release announces itself.
        foreach (array('xb_release_published' => 'maybe_queue_xb_release', 'static_bridge_queue_paths' => 'queue_public_paths') as $hook_name => $callback_name) {
            $found = false;
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                if ($hook_name === $hook[0] && is_array($hook[1]) && $callback_name === $hook[1][1]) {
                    $found = true;
                }
            }
            sb_assert($found, 'Hook not registered: ' . $hook_name);
        }
        $announced = false;
        foreach ($GLOBALS['sb_test_actions_fired'] as $fired) {
            $announced = $announced || 'static_bridge_release_published' === $fired[0];
        }
        sb_assert($announced, 'Publishing a release did not fire static_bridge_release_published.');

        // The public status: what a builder may show, from options only, never paths or secrets.
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => 'r1', 'published_at' => 1700000000, 'pages' => 3, 'skipped' => 0);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array(array('time' => 'ora', 'message' => '<b>Fatto</b>', 'detail' => ABSPATH . 'segreto', 'error' => false));
        $status = $plugin->public_status(null);
        sb_assert(is_array($status) && true === $status['serving'] && 3 === $status['pages'] && 1700000000 === $status['published_at'], 'The public status did not describe the served release.');
        sb_assert('Fatto' === $status['last']['message'] && !isset($status['last']['detail']), 'The public status leaked activity details or markup.');
        sb_assert(in_array($status['export'], array('idle', 'running', 'paused', 'failed', 'complete', 'cancelled'), true), 'The public status gave an unknown export state.');
        sb_assert(false === strpos(wp_json_encode($status), ABSPATH), 'The public status contains a server path.');
        $found = false;
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $found = $found || ('static_bridge_status' === $hook[0] && is_array($hook[1]) && 'public_status' === $hook[1][1]);
        }
        sb_assert($found, 'Hook not registered: static_bridge_status');

        // A language plugin adds the lists in the post's language; it cannot remove the others or leave the site.
        $GLOBALS['sb_test_filter_values']['static_bridge_archive_urls_for_post'] = array(home_url('/en/'), home_url('/en/category/news/'), 'https://evil.example/en/', home_url('/en/?s=x'), 42, array('x'));
        $archives = sb_private($plugin, 'archive_urls_for_post', array(new WP_Post(array('ID' => 7, 'post_type' => 'post', 'post_status' => 'publish', 'post_author' => 0))));
        sb_assert(in_array(home_url('/'), $archives, true), 'A language plugin removed the home from the lists to refresh.');
        sb_assert(in_array(home_url('/en/'), $archives, true) && in_array(home_url('/en/category/news/'), $archives, true), 'The lists in the post\'s language were not added.');
        sb_assert(3 === count($archives), 'Foreign, query or non-string routes were accepted: ' . implode(', ', $archives));
        $GLOBALS['sb_test_filter_values']['static_bridge_archive_urls_for_post'] = array_map(fn($i) => home_url('/en/p' . $i . '/'), range(1, 300));
        $archives = sb_private($plugin, 'archive_urls_for_post', array(new WP_Post(array('ID' => 7, 'post_type' => 'post', 'post_status' => 'publish', 'post_author' => 0))));
        sb_assert(1 + Static_Bridge_Plugin::MAX_ARCHIVE_URLS === count($archives), 'More list routes than allowed were accepted.');
        $GLOBALS['sb_test_filter_values']['static_bridge_archive_urls_for_post'] = 'not a list';
        $archives = sb_private($plugin, 'archive_urls_for_post', array(new WP_Post(array('ID' => 7, 'post_type' => 'post', 'post_status' => 'publish', 'post_author' => 0))));
        sb_assert(array(home_url('/')) === $archives, 'A malformed answer changed the lists to refresh.');
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_dependents_for_post'], $GLOBALS['sb_test_filter_values']['static_bridge_post_has_query_loop'], $GLOBALS['sb_test_filter_values']['static_bridge_archive_urls_for_post']);
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        foreach (array('/index.html', '/news/one/index.html', '/page-two/index.html') as $file) {
            @unlink($release . $file);
        }
        foreach (array($release . '/news/one', $release . '/news', $release . '/page-two', $release) as $directory) {
            @rmdir($directory);
        }
        foreach ($old_options as $option => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$option]);
            } else {
                $GLOBALS['sb_test_options'][$option] = $value;
            }
        }
        $GLOBALS['sb_test_posts'] = array();
    }
});

// --- Archives (2.1.1): a full export lists every archive, the incremental worker every page of it. ---

/** A blog with a category tree, an orphan category of 11 posts, tags, a CPT archive, two authors and dated posts. */
function sb_archive_isolated(callable $callback)
{
    $names = array(Static_Bridge_Plugin::SETTINGS_OPTION, Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, Static_Bridge_Plugin::ACTIVITY_OPTION,
        Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION, Static_Bridge_Plugin::FORM_MODES_OPTION, 'posts_per_page', 'show_on_front', 'page_for_posts');
    $previous = array();
    foreach ($names as $name) {
        $previous[$name] = array_key_exists($name, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][$name]) : null;
    }
    $previous_globals = array($GLOBALS['sb_test_archive'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_transients'], $GLOBALS['sb_test_posts']);
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $release_id = 'archives-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $GLOBALS['sb_test_post_types'] = array(
        'post' => array('public' => true, 'publicly_queryable' => true),
        'page' => array('public' => true),
        'evento' => array('public' => true, 'publicly_queryable' => true),
    );
    $GLOBALS['sb_test_archive'] = array(
        'taxonomies' => array(
            'category' => array('public' => true, 'publicly_queryable' => true, 'hierarchical' => true, 'base' => 'category'),
            'post_tag' => array('public' => true, 'publicly_queryable' => true, 'base' => 'tag'),
            'internal' => array('public' => false, 'publicly_queryable' => false, 'base' => 'internal'),
        ),
        'terms' => array(
            1 => array('term_taxonomy_id' => 11, 'taxonomy' => 'category', 'slug' => 'archivio', 'parent' => 0, 'count' => 0, 'posts' => array()),
            2 => array('term_taxonomy_id' => 12, 'taxonomy' => 'category', 'slug' => 'festa', 'parent' => 1, 'count' => 4, 'posts' => array(101, 102, 103, 104)),
            3 => array('term_taxonomy_id' => 13, 'taxonomy' => 'category', 'slug' => 'orfana', 'parent' => 0, 'count' => 11, 'posts' => range(201, 211)),
            4 => array('term_taxonomy_id' => 14, 'taxonomy' => 'post_tag', 'slug' => 'vuoto', 'parent' => 0, 'count' => 0, 'posts' => array()),
            5 => array('term_taxonomy_id' => 15, 'taxonomy' => 'internal', 'slug' => 'segreto', 'parent' => 0, 'count' => 3, 'posts' => array()),
        ),
        'post_terms' => array(201 => array(3, 4), 101 => array(2)),
        'counts' => array('post' => 25, 'evento' => 12, 'page' => 4),
        'author_counts' => array(3 => 11, 4 => 2),
        'post_dates' => array_merge(array_fill(0, 11, '2024-01-15 10:00:00'), array('2023-05-02 09:00:00')),
        'archive_types' => array('evento' => 'eventi'),
    );
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0, 'excluded_paths' => array(), 'woocommerce_enabled' => 0, 'incremental_enabled' => 1);
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options']['posts_per_page'] = 10;
    $GLOBALS['sb_test_options']['show_on_front'] = 'posts';
    unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION], $GLOBALS['sb_test_options']['page_for_posts']);
    $GLOBALS['sb_test_transients'] = array();
    try {
        sb_assert(wp_mkdir_p($release), 'Could not create the archive release fixture.');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at the archive release.');
        $callback(new Static_Bridge_Plugin(), $release);
    } finally {
        if (is_link($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            @symlink($old_current_target, $current);
        }
        if (is_dir($release)) {
            $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
            foreach ($files as $file) {
                $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
            }
            rmdir($release);
        }
        list($GLOBALS['sb_test_archive'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_transients'], $GLOBALS['sb_test_posts']) = $previous_globals;
        foreach ($previous as $name => $value) {
            if (null === $value) {
                unset($GLOBALS['sb_test_options'][$name]);
            } else {
                $GLOBALS['sb_test_options'][$name] = $value[0];
            }
        }
    }
}

function sb_archive_paths(array $urls)
{
    $paths = array_map(function ($url) { return (string) wp_parse_url($url, PHP_URL_PATH); }, $urls);
    sort($paths);
    return $paths;
}

function sb_archive_discover($plugin, $phase = 'terms')
{
    $urls = array();
    $cursor = 0;
    for ($guard = 0; 'done' !== $phase && $guard < 50; $guard++) {
        $batch = sb_private($plugin, 'discover_wordpress_archive_url_batch', array($phase, $cursor));
        sb_assert(is_array($batch), 'An archive batch failed: ' . (is_wp_error($batch) ? $batch->get_error_message() : gettype($batch)));
        $urls = array_merge($urls, $batch['urls']);
        $phase = $batch['phase'];
        $cursor = $batch['cursor'];
    }
    sb_assert('done' === $phase, 'The archive inventory did not end.');
    return sb_archive_paths(array_unique($urls));
}

function sb_queued_items()
{
    $items = array();
    foreach (get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()) as $item) {
        $items[$item['path']] = $item['action'];
    }
    ksort($items);
    return $items;
}

sb_test('Full export inventories unlinked term, author, date and CPT archives with their pages', function () {
    sb_archive_isolated(function ($plugin) {
        $GLOBALS['sb_test_filter_values']['static_bridge_export_urls'] = array(home_url('/en/category/orfana/'), 'https://evil.example/x/', home_url('/en/?s=x'), 7);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION] = array('/category/creata/' => time());
        $expected = array(
            '/', '/2023/', '/2023/05/', '/2023/05/02/', '/2024/', '/2024/01/', '/2024/01/15/', '/2024/01/15/page/2/', '/2024/01/page/2/', '/2024/page/2/',
            '/author/author-3/', '/author/author-3/page/2/', '/author/author-4/',
            '/category/archivio/', '/category/archivio/festa/', '/category/creata/', '/category/orfana/', '/category/orfana/page/2/',
            '/en/category/orfana/', '/eventi/', '/eventi/page/2/', '/page/2/', '/page/3/', '/tag/vuoto/',
        );
        $found = sb_archive_discover($plugin);
        sb_assert($expected === $found, 'Archive inventory mismatch: ' . implode(' ', array_diff($expected, $found)) . ' missing; ' . implode(' ', array_diff($found, $expected)) . ' unexpected.');

        // Keyset batches: a site with more terms than one block returns them over several calls.
        for ($id = 100; $id < 260; $id++) {
            $GLOBALS['sb_test_archive']['terms'][$id] = array('term_taxonomy_id' => $id + 1000, 'taxonomy' => 'post_tag', 'slug' => 't' . $id, 'parent' => 0, 'count' => 1);
        }
        $first = sb_private($plugin, 'discover_wordpress_archive_url_batch', array('terms', 0));
        sb_assert('terms' === $first['phase'] && 1195 === $first['cursor'] && 101 === count($first['urls']), 'The term inventory is not bounded by keyset blocks.');
        sb_assert(160 + 1 === count(array_filter(sb_archive_discover($plugin), function ($path) { return 0 === strpos($path, '/tag/'); })), 'Terms were lost between blocks.');

        // Off: only the routes other plugins add and those the incremental worker created.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 0;
        sb_assert(array('/category/creata/', '/en/category/orfana/') === sb_archive_discover($plugin), 'Archives were inventoried with the setting off.');
    });
});

sb_test('Archive pagination respects static_bridge_archive_max_pages and posts_per_page', function () {
    sb_archive_isolated(function ($plugin) {
        sb_assert(3 === sb_private($plugin, 'archive_page_count', array(25)) && 1 === sb_private($plugin, 'archive_page_count', array(0)), 'Pages are not derived from posts_per_page.');
        $GLOBALS['sb_test_filter_values']['static_bridge_archive_max_pages'] = 2;
        sb_assert(2 === sb_private($plugin, 'archive_page_count', array(250)), 'The per-archive page cap was ignored.');
        $GLOBALS['sb_test_filter_values']['static_bridge_archive_max_pages'] = -5;
        sb_assert(1 === sb_private($plugin, 'archive_page_count', array(250)), 'A negative cap was not clamped to page 1.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_archive_max_pages']);
        $GLOBALS['sb_test_options']['posts_per_page'] = -1;
        sb_assert(1 === sb_private($plugin, 'archive_page_count', array(250)), 'posts_per_page -1 (all on one page) did not give one page.');
        $GLOBALS['sb_test_options']['posts_per_page'] = 10;
        // A category lists its descendants' posts once each: 4 posts in a child make the parent one page.
        $GLOBALS['sb_test_archive']['terms'][2]['posts'] = range(101, 115);
        sb_assert(2 === sb_private($plugin, 'term_archive_pages', array(1, 'category', 0)), 'A parent category did not count its children\'s posts.');
        // A /page/N/ past the real last page answers 404: not an URL left out of the release.
        $not_found = new WP_Error('static_bridge_http', 'Risposta HTTP 404.', 404);
        sb_assert(sb_private($plugin, 'is_archive_page_past_end', array(home_url('/category/x/page/4/'), $not_found)), 'A missing archive page was reported as an error.');
        sb_assert(!sb_private($plugin, 'is_archive_page_past_end', array(home_url('/category/x/'), $not_found)), 'A missing archive was silenced.');
        sb_assert(!sb_private($plugin, 'is_archive_page_past_end', array(home_url('/category/x/page/4/'), new WP_Error('static_bridge_http', 'Risposta HTTP 500.', 500))), 'A server error on an archive page was silenced.');
    });
});

sb_test('The export worker inventories archives after the singles and publishes only when both are done', function () use ($plugin) {
    sb_archive_isolated(function ($plugin) {
        $job_id = '45678901-2345-4345-8345-23456789abcd';
        $stage = WP_CONTENT_DIR . '/static-bridge/releases/archive-worker-' . getmypid();
        $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
        $previous_job = get_option(Static_Bridge_Plugin::JOB_OPTION, null);
        $previous_generated = $GLOBALS['sb_test_generated_post_count'];
        $previous_responses = $GLOBALS['sb_test_http_responses'];
        sb_assert($queue->install() && wp_mkdir_p($stage), 'Could not prepare the archive worker fixture.');
        $GLOBALS['sb_test_generated_post_count'] = 150;
        $GLOBALS['sb_test_filter_values']['static_bridge_export_batch_size'] = 1;
        $GLOBALS['sb_test_http_responses'] = array(
            home_url('/category/x/page/9/') . '?static_bridge_bypass=1' => array('response' => array('code' => 404), 'headers' => array(), 'body' => 'Not found', '_sb_strip_render_header' => true),
        );
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array(
            'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => basename($stage), 'stage' => $stage,
            'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 0, 'discovery_complete' => false, 'discovered' => 0,
            'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0, 'issues' => array(), 'current_url' => '',
        );
        try {
            sb_assert(1 === $queue->enqueue_batch($job_id, array(home_url('/category/x/page/9/'))), 'Could not seed a page past the end.');
            $step = sb_private($plugin, 'run_export_queue_step');
            sb_assert(empty($step['discovery_complete']) && empty($step['archive_phase']) && 100 === (int) $step['discovery_cursor'], 'The first step did not stay on the singles.');
            sb_assert(0 === (int) $step['skipped'] && empty($step['issues']), 'A /page/N/ past the last page was reported as an URL left out.');
            $step = sb_private($plugin, 'run_export_queue_step');
            sb_assert(!empty($step['discovery_complete']) && 'done' === $step['archive_phase'], 'The archives were not inventoried after the singles.');
            $urls = array();
            foreach ($GLOBALS['sb_test_export_queue_rows'] as $row) {
                if ($job_id === $row['job_id']) {
                    $urls[] = $row['url'];
                }
            }
            foreach (array('/category/orfana/page/2/', '/2024/01/15/', '/author/author-3/page/2/', '/eventi/page/2/', '/tag/vuoto/') as $path) {
                sb_assert(in_array(home_url($path), $urls, true), 'The export queue lacks ' . $path);
            }
        } finally {
            $queue->delete_job($job_id);
            @rmdir($stage);
            $GLOBALS['sb_test_generated_post_count'] = $previous_generated;
            $GLOBALS['sb_test_http_responses'] = $previous_responses;
            if (null === $previous_job) {
                delete_option(Static_Bridge_Plugin::JOB_OPTION);
            } else {
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $previous_job;
            }
            wp_clear_scheduled_hook('static_bridge_process_export_queue');
            delete_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION);
        }
    });
});

sb_test('Incremental refresh queues ancestor terms, date archives, every page and pages past the new last one', function () {
    sb_archive_isolated(function ($plugin, $release) {
        foreach (array('category/orfana/page/2', 'category/orfana/page/5', 'category/orfana/page/x') as $directory) {
            sb_assert(wp_mkdir_p($release . '/' . $directory) && false !== file_put_contents($release . '/' . $directory . '/index.html', 'x'), 'Could not seed a paginated route.');
        }
        $post = new WP_Post(array('ID' => 201, 'post_type' => 'post', 'post_status' => 'publish', 'post_author' => 3, 'post_date' => '2024-01-15 10:00:00'));
        $GLOBALS['sb_test_archive']['post_terms'][201] = array(3, 2, 4);
        $paths = sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($post)));
        foreach (array('/', '/page/2/', '/page/3/', '/category/archivio/', '/category/archivio/festa/', '/category/orfana/page/2/', '/category/orfana/page/5/',
            '/tag/vuoto/', '/author/author-3/page/2/', '/2024/page/2/', '/2024/01/page/2/', '/2024/01/15/page/2/') as $path) {
            sb_assert(in_array($path, $paths, true), 'The incremental refresh lacks ' . $path . ': ' . implode(' ', $paths));
        }
        sb_assert(!in_array('/category/orfana/page/3/', $paths, true) && !in_array('/category/orfana/page/x/', $paths, true), 'Pages that do not exist were queued.');
        // A save queues every list page with a few option writes, not one per page.
        $GLOBALS['sb_test_option_writes'] = array();
        $plugin->maybe_queue_incremental_post(201, $post, true, $post);
        sb_assert(count(sb_queued_items()) > 15 && ($GLOBALS['sb_test_option_writes'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] ?? 0) <= 3,
            'A post change wrote the queue once per list page: ' . json_encode($GLOBALS['sb_test_option_writes']));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        // Archives off: page 1 of the post's own lists, as up to 2.1.0 (no parents, dates or /page/N/).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 0;
        sb_assert(array('/', '/author/author-3/', '/category/archivio/festa/', '/category/orfana/', '/tag/vuoto/') === sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($post))),
            'With archives off the incremental refresh went past page 1: ' . implode(' ', sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($post)))));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 1;
        // The order keeps the most visible pages under the cap: every page 1 before any page 2.
        $urls = sb_private($plugin, 'archive_urls_for_post', array($post));
        sb_assert(false === strpos(implode(' ', array_slice($urls, 0, 8)), '/page/'), 'Page 2 routes come before the page 1 routes.');
        // A page is in the author archive, the date archives and the home only if WordPress lists it there.
        $page = new WP_Post(array('ID' => 9, 'post_type' => 'page', 'post_status' => 'publish', 'post_author' => 3, 'post_date' => '2024-01-15 10:00:00'));
        sb_assert(array('/') === sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($page))), 'A page queued author, date or paginated home archives.');
        // A static front page: WordPress gives the home as the `post` archive link; its /page/N/ are not lists.
        $GLOBALS['sb_test_options']['show_on_front'] = 'page';
        $GLOBALS['sb_test_archive']['archive_types']['post'] = '';
        $paths = sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($post)));
        sb_assert(in_array('/', $paths, true) && !in_array('/page/2/', $paths, true), 'A static front page queued /page/N/ routes: ' . implode(' ', $paths));
        // A custom post type with an archive lists it with all its pages.
        $evento = new WP_Post(array('ID' => 300, 'post_type' => 'evento', 'post_status' => 'publish', 'post_author' => 3, 'post_date' => '2024-01-15 10:00:00'));
        $paths = sb_archive_paths(sb_private($plugin, 'archive_urls_for_post', array($evento)));
        sb_assert(in_array('/eventi/', $paths, true) && in_array('/eventi/page/2/', $paths, true) && !in_array('/author/author-3/', $paths, true), 'The CPT archive was not queued with its pages: ' . implode(' ', $paths));
    });
});

sb_test('Renaming, creating or deleting a term moves its static archive routes', function () {
    sb_archive_isolated(function ($plugin, $release) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 1;
        sb_assert(wp_mkdir_p($release . '/category/orfana/page/2') && false !== file_put_contents($release . '/category/orfana/page/2/index.html', 'x')
            && false !== file_put_contents($release . '/category/orfana/index.html', 'x'), 'Could not seed the term routes.');
        $plugin->remember_incremental_old_term(3, 'category');
        $GLOBALS['sb_test_archive']['terms'][3]['slug'] = 'orfane';
        $plugin->maybe_queue_term_archive(3, 13, 'category');
        sb_assert(array('/category/orfana/' => 'delete', '/category/orfana/page/2/' => 'delete', '/category/orfane/' => 'refresh', '/category/orfane/page/2/' => 'refresh') === sb_queued_items(),
            'A renamed term did not move its routes: ' . json_encode(sb_queued_items()));

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_term_archive(4, 14, 'post_tag');
        sb_assert(array('/tag/vuoto/' => 'refresh') === sb_queued_items(), 'A new (empty) term was not queued.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_deleted_term(3, 'category');
        sb_assert(array('/category/orfane/' => 'delete', '/category/orfane/page/2/' => 'delete') === sb_queued_items(), 'A deleted term kept its routes.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_term_archive(5, 15, 'internal');
        sb_assert(array() === sb_queued_items(), 'A private taxonomy was queued.');

        $plugin->maybe_queue_author_archive(3, (object) array('user_nicename' => 'vecchio'));
        sb_assert(array('/author/author-3/' => 'refresh', '/author/author-3/page/2/' => 'refresh', '/author/vecchio/' => 'delete', '/author/vecchio/page/2/' => 'delete') === sb_queued_items(),
            'A renamed author did not move the author archive: ' . json_encode(sb_queued_items()));

        // Off: the export does not list archives, so the worker does not follow term changes either.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 0;
        $plugin->maybe_queue_term_archive(4, 14, 'post_tag');
        sb_assert(array() === sb_queued_items(), 'A term change was queued with archives off.');

        $hooks = array();
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $hooks[$hook[0]] = true;
        }
        foreach (array('edit_terms', 'edited_term', 'created_term', 'pre_delete_term', 'profile_update', 'update_option_posts_per_page', 'update_option_permalink_structure', 'update_option_show_on_front') as $hook_name) {
            sb_assert(isset($hooks[$hook_name]), 'Hook not registered: ' . $hook_name);
        }
    });
});

sb_test('A posts_per_page or permalink change refreshes every release route and asks for a full export', function () {
    sb_archive_isolated(function ($plugin, $release) {
        foreach (array('', 'page/2/', 'category/orfana/') as $route) {
            sb_assert(wp_mkdir_p($release . '/' . $route) && false !== file_put_contents($release . '/' . $route . 'index.html', 'x'), 'Could not seed ' . $route);
        }
        $plugin->maybe_queue_reading_option_refresh(10, 10, 'posts_per_page');
        sb_assert(array() === sb_queued_items(), 'An unchanged option queued a refresh.');
        $plugin->maybe_queue_reading_option_refresh(10, 5, 'posts_per_page');
        sb_assert(array('/' => 'refresh', '/category/orfana/' => 'refresh', '/page/2/' => 'refresh') === sb_queued_items(), 'Not every route was refreshed: ' . json_encode(sb_queued_items()));
        $activity = wp_json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()));
        sb_assert(false !== strpos($activity, 'export completo'), 'The change did not recommend a full export.');
