});

sb_test('Core Query Loop, Latest Posts and Etch loops are list pages; unpublishing a post refreshes them', function () {
    sb_archive_isolated(function ($plugin) {
        foreach (array(
            '<!-- wp:query {"queryId":1,"query":{"perPage":3}} --><div><!-- wp:post-template /--></div><!-- /wp:query -->' => true,
            '<!-- wp:core/query {"queryId":1} -->' => true,
            '<!-- wp:latest-posts /-->' => true,
            '<!-- wp:latest-posts {"postsToShow":3} /-->' => true,
            '<!-- wp:archives /-->' => true,
            '<!-- wp:etch/loop {"loopId":"x"} --><!-- /wp:etch/loop -->' => true,
            '<!-- wp:query-title {"type":"archive"} /-->' => false,
            '<!-- wp:query-pagination /-->' => false,
            '<!-- wp:paragraph --><p>query loop</p><!-- /wp:paragraph -->' => false,
        ) as $content => $expected) {
            $page = new WP_Post(array('ID' => 77, 'post_type' => 'page', 'post_status' => 'publish', 'post_content' => $content));
            sb_assert($expected === sb_private($plugin, 'post_has_query_loop', array($page)), ($expected ? 'Not recognized as a list: ' : 'Taken for a list: ') . $content);
        }
        // Moving a published post to draft, trash or private must remove it from the list pages too.
        $GLOBALS['sb_test_transients']['static_bridge_incremental_query_pages'] = array(home_url('/percorsi-di-lettura/'));
        $before = new WP_Post(array('ID' => 201, 'post_type' => 'post', 'post_status' => 'publish'));
        $after = new WP_Post(array('ID' => 201, 'post_type' => 'post', 'post_status' => 'draft'));
        $plugin->maybe_queue_incremental_post(201, $after, true, $before);
        $queued = sb_queued_items();
        sb_assert(isset($queued['/percorsi-di-lettura/']) && 'refresh' === $queued['/percorsi-di-lettura/'], 'An unpublished post did not refresh the list pages: ' . json_encode($queued));
        sb_assert(isset($queued['/post-201/']) && 'delete' === $queued['/post-201/'], 'The unpublished post was not removed.');
    });
});

sb_test('Routes created by the incremental worker are seeded into the next full export, then forgotten', function () {
    sb_archive_isolated(function ($plugin) {
        sb_private($plugin, 'remember_incremental_added_route', array('/category/nuova/'));
        sb_private($plugin, 'remember_incremental_added_route', array('/../etc/'));
        $routes = get_option(Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION, array());
        sb_assert(array('/category/nuova/') === array_keys($routes), 'The created routes were not recorded safely.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_archives'] = 0;
        sb_assert(array('/category/nuova/') === sb_archive_discover($plugin, 'extra'), 'A created route was not seeded into the export.');
        // A route created while the export ran stays for the next one.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION]['/category/durante/'] = time() + 5;
        sb_private($plugin, 'forget_incremental_added_routes', array(time() + 1));
        sb_assert(array('/category/durante/') === array_keys(get_option(Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION, array())), 'The published routes were not forgotten, or a newer one was.');
        sb_private($plugin, 'forget_incremental_added_routes', array(time() + 10));
        sb_assert(false === get_option(Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION, false), 'An empty list was kept.');
        for ($index = 0; $index < Static_Bridge_Plugin::MAX_INCREMENTAL_ADDED_ROUTES + 3; $index++) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION]['/r' . $index . '/'] = 1;
        }
        sb_private($plugin, 'remember_incremental_added_route', array('/ultima/'));
        $routes = get_option(Static_Bridge_Plugin::INCREMENTAL_ADDED_ROUTES_OPTION, array());
        sb_assert(Static_Bridge_Plugin::MAX_INCREMENTAL_ADDED_ROUTES === count($routes) && isset($routes['/ultima/']), 'The created routes are not bounded.');
    });
});

sb_test('An incremental route that keeps failing is dropped after the last attempt; 410 removes the copy', function () {
    sb_archive_isolated(function ($plugin, $release) {
        sb_assert(wp_mkdir_p($release . '/rotta') && false !== file_put_contents($release . '/rotta/index.html', 'x') && wp_mkdir_p($release . '/andata')
            && false !== file_put_contents($release . '/andata/index.html', 'x') && false !== file_put_contents($release . '/manifest.json', '{"pages_saved":2}'), 'Could not seed the routes.');
        $previous_responses = $GLOBALS['sb_test_http_responses'];
        $GLOBALS['sb_test_http_responses'] = array(
            home_url('/rotta/') . '?static_bridge_bypass=1' => array('response' => array('code' => 503), 'headers' => array(), 'body' => 'busy', '_sb_strip_render_header' => true),
            home_url('/andata/') . '?static_bridge_bypass=1' => array('response' => array('code' => 410), 'headers' => array(), 'body' => 'gone', '_sb_strip_render_header' => true),
        );
        try {
            $item = array('url' => home_url('/rotta/'), 'path' => '/rotta/', 'action' => 'refresh', 'role' => 'dependent', 'post_id' => 0, 'builders' => array(), 'token' => 't1', 'attempts' => Static_Bridge_Plugin::MAX_INCREMENTAL_ATTEMPTS - 2);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $item);
            sb_assert('retry' === sb_private($plugin, 'process_incremental_item', array(sha1('/rotta/'), $item, $release)), 'A failing route was not retried.');
            $item['attempts'] = Static_Bridge_Plugin::MAX_INCREMENTAL_ATTEMPTS - 1;
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $item);
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/rotta/'), $item, $release)) && array() === sb_queued_items(), 'A route was retried for ever.');
            sb_assert(is_file($release . '/rotta/index.html'), 'Dropping a failing route removed its last good copy.');
            // Without a copy the route stays queued (dynamic): dropped, Strict would answer 404 for it.
            $GLOBALS['sb_test_http_responses'][home_url('/nuova/') . '?static_bridge_bypass=1'] = $GLOBALS['sb_test_http_responses'][home_url('/rotta/') . '?static_bridge_bypass=1'];
            $fresh = array('url' => home_url('/nuova/'), 'path' => '/nuova/', 'action' => 'refresh', 'role' => 'single', 'post_id' => 0, 'builders' => array(), 'token' => 't3', 'attempts' => Static_Bridge_Plugin::MAX_INCREMENTAL_ATTEMPTS + 3);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/nuova/') => $fresh);
            sb_assert('retry' === sb_private($plugin, 'process_incremental_item', array(sha1('/nuova/'), $fresh, $release)) && isset(sb_queued_items()['/nuova/']), 'A failing route without a static copy was dropped from the queue.');
            sb_assert(in_array('/nuova/', sb_private($plugin, 'routing_excluded_paths'), true), 'A queued route without a static copy is not kept dynamic.');
            sb_assert(false !== strpos(wp_json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION)), 'troppi tentativi'), 'The dropped route was not reported.');

            $gone = array('url' => home_url('/andata/'), 'path' => '/andata/', 'action' => 'refresh', 'role' => 'dependent', 'post_id' => 0, 'builders' => array(), 'token' => 't2', 'attempts' => 0);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/andata/') => $gone);
            sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1('/andata/'), $gone, $release)) && !is_file($release . '/andata/index.html'), 'A 410 kept serving the old copy.');
            // A page an access plugin now closes to visitors (401/403) loses its public copy at once.
            foreach (array(401, 403) as $code) {
                $route = '/chiusa-' . $code . '/';
                sb_assert(wp_mkdir_p($release . $route) && false !== file_put_contents($release . $route . 'index.html', 'pubblica'), 'Could not seed the closed route.');
                $GLOBALS['sb_test_http_responses'][home_url($route) . '?static_bridge_bypass=1'] = array('response' => array('code' => $code), 'headers' => array(), 'body' => 'no', '_sb_strip_render_header' => true);
                $closed = array('url' => home_url($route), 'path' => $route, 'action' => 'refresh', 'role' => 'single', 'post_id' => 0, 'builders' => array(), 'token' => 't' . $code, 'attempts' => 0);
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1($route) => $closed);
                sb_assert('done' === sb_private($plugin, 'process_incremental_item', array(sha1($route), $closed, $release)) && !is_file($release . $route . 'index.html'), 'A ' . $code . ' kept serving the earlier public copy.');
            }
        } finally {
            $GLOBALS['sb_test_http_responses'] = $previous_responses;
        }
    });
});

sb_test('Generated server rules keep short feeds, search and files dynamic, need the trailing slash and survive odd excluded paths', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        sb_cf_settings(array('excluded_paths' => array('/area riservata/', "/tab\tpath/")));
        $apache = sb_private($plugin, 'rewrite_block');
        foreach (array(
            'short feeds' => 'RewriteCond %{REQUEST_URI} !^/(?:.+/)?(?:rss|rss2|atom|rdf)/?$ [NC]',
            'search' => 'RewriteCond %{REQUEST_URI} !^/search(?:/|$) [NC]',
            'trailing slash' => "RewriteCond %{REQUEST_URI} /$\nRewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/current/$1/index.html -f",
            'Strict only on routes' => "RewriteCond %{REQUEST_URI} !^/\\.well-known/ [NC]\nRewriteCond %{REQUEST_URI} !\\.[A-Za-z0-9]{1,8}$\nRewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/.strict -f",
            'escaped space' => '!^/(?:area\\x20riservata|',
        ) as $label => $fragment) {
            sb_assert(false !== strpos($apache, $fragment), 'Apache rules lack: ' . $label);
        }
        sb_assert(!preg_match('/^RewriteCond [^\n]*!\^\/\(\?:[^\n]* [^\n]*\) \[NC\]$/m', str_replace(array('(?:/|$) [NC]'), '', $apache)), 'An excluded path still contains a raw space.');
        $nginx = sb_private($plugin, 'nginx_router_block');
        foreach (array(
            'if ($uri ~* "^/(?:.+/)?(?:rss|rss2|atom|rdf)/?$") { return 418; }',
            'if ($uri ~* "^/search(?:/|$)") { return 418; }',
            'if ($uri ~ "\\.[A-Za-z0-9]{1,8}$") { return 418; }',
            'if ($uri ~* "^/\\.well-known/") { return 418; }',
            'if ($uri !~ "/$") { return 418; }',
            'wordpress_logged_in_|comment_author_|wp-postpass_|woocommerce_items_in_cart',
        ) as $fragment) {
            sb_assert(false !== strpos($nginx, $fragment), 'Nginx rules lack: ' . $fragment);
        }
        // Permalinks without the final slash keep the previous rule: /x is the route itself.
        $GLOBALS['sb_test_options']['permalink_structure'] = '/%postname%';
        try {
            sb_assert(false === strpos(sb_private($plugin, 'rewrite_block'), "RewriteCond %{REQUEST_URI} /$\n") && false === strpos(sb_private($plugin, 'nginx_router_block'), '$uri !~ "/$"'), 'The trailing slash was required with permalinks without it.');
        } finally {
            unset($GLOBALS['sb_test_options']['permalink_structure']);
        }
        foreach (array('/rss2/', '/category/x/atom/', '/search/lettura/', '/search/') as $path) {
            sb_assert(sb_private($plugin, 'is_excluded_path', array($path)), 'Not excluded from the export: ' . $path);
        }
        sb_assert(!sb_private($plugin, 'is_excluded_path', array('/atomico/')) && !sb_private($plugin, 'is_excluded_path', array('/ricerca/search-engine/')), 'A route merely containing a feed or search word was excluded.');
        $GLOBALS['sb_test_filter_values']['static_bridge_excluded_paths'] = array('/en/iscriviti/', '../x', 'https://evil.example/y/', '/', 5);
        try {
            $paths = sb_private($plugin, 'settings')['excluded_paths'];
            sb_assert(in_array('/en/iscriviti/', $paths, true) && !in_array('/', $paths, true) && 3 === count($paths), 'The excluded-paths filter accepted an unsafe route: ' . implode(' ', $paths));
        } finally {
            unset($GLOBALS['sb_test_filter_values']['static_bridge_excluded_paths']);
        }
        // A callback that reads the plugin's settings again (for example through static_bridge_status) does not loop.
        $calls = 0;
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_excluded_paths'] = function ($value) use ($plugin, &$calls) {
            $calls++;
            $inner = sb_private($plugin, 'settings');
            return array_merge($value, array('/en/iscriviti/'), $inner['excluded_paths']);
        };
        try {
            $paths = sb_private($plugin, 'settings')['excluded_paths'];
            sb_assert(1 === $calls && in_array('/en/iscriviti/', $paths, true), 'A re-entrant excluded-paths filter looped or lost its answer.');
        } finally {
            unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_excluded_paths']);
        }
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]);
        sb_assert(0 === sb_private($plugin, 'settings')['strict_mode'], 'A missing strict_mode key turns Strict on (activation writes 0).');
    });
});

sb_test('Local Apache and Nginx with Strict on: archives static, short feeds, search, files and /x to WordPress', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the Strict routing check.');
    }
    sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers) {
        sb_cf_settings(array('excluded_paths' => array('/area riservata/')));
        $failures = array();
        foreach ($servers as $kind => $binary) {
            $docroot = $fixtureRoot . '/strict-docroot-' . $kind;
            $static = $docroot . '/wp-content/static-bridge';
            foreach (array('', 'category/x/', 'category/x/page/2/', 'area riservata/') as $route) {
                sb_assert(wp_mkdir_p($static . '/releases/r1/' . $route) && false !== file_put_contents($static . '/releases/r1/' . $route . 'index.html', 'STATIC_' . $route), 'Could not create the ' . $kind . ' docroot.');
            }
            file_put_contents($static . '/.enabled', '1');
            file_put_contents($static . '/.strict', '1');
            @symlink('releases/r1', $static . '/current');
            file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
            if ('apache' === $kind) {
                $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                    . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
            } else {
                $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                $rules = sb_private($plugin, 'nginx_router_block');
            }
            list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
            try {
                foreach (array('/category/x/' => 'STATIC_category/x/', '/category/x/page/2/' => 'STATIC_category/x/page/2/') as $path => $body) {
                    $response = $request($path);
                    if (!(200 === $response['status'] && $body === trim($response['body']))) {
                        $failures[] = $kind . ' static ' . $path . ' ' . json_encode($response);
                    }
                }
                foreach (array(array('/category/x', array()), array('/rss2/', array()), array('/category/x/atom/', array()), array('/search/lettura/', array()),
                    array('/favicon.ico', array()), array('/.well-known/security.txt', array()), array('/area%20riservata/', array()),
                    array('/category/x/', array('Cookie: wp-postpass_abc=1'))) as $dynamic) {
                    $response = $request($dynamic[0], $dynamic[1]);
                    if (!(200 === $response['status'] && 'WORDPRESS_FALLBACK' === trim($response['body']))) {
                        $failures[] = $kind . ' to WordPress ' . $dynamic[0] . ' ' . json_encode($response);
                    }
                }
                $strict = $request('/category/non-esportata/');
                if (!(404 === $strict['status'] && 'no-store, max-age=0' === $strict['cache_control'])) {
                    $failures[] = $kind . ' Strict 404 ' . json_encode($strict);
                }
            } finally {
                $log = $stop();
            }
            if (!empty($failures) && '' !== trim($log)) {
                $failures[] = $kind . ' log: ' . substr($log, -400);
            }
        }
        sb_assert(empty($failures), implode('; ', $failures));
    });
});

defined('ARRAY_N') || define('ARRAY_N', 'ARRAY_N');
if (!function_exists('cmplz_get_default_banner_id')) {
    function cmplz_get_default_banner_id() { return 1; }
    function cmplz_get_cookiebanner($id) { return (object) array('ID' => $id, 'banner_version' => $GLOBALS['sb_test_cmplz_banner_version']); }
    function cmplz_get_option($name) { return 'safe_mode' === $name ? !empty($GLOBALS['sb_test_cmplz_safe_mode']) : false; }
}

sb_test('A Complianz save refreshes every static route once, and a render never does', function () {
    $plugin = new Static_Bridge_Plugin();
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'complianz-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current_target = is_link($current) ? readlink($current) : false;
    $old_options = $GLOBALS['sb_test_options'];
    $old_hooks = $GLOBALS['sb_test_hooks'];
    $old_wpdb = $GLOBALS['wpdb'];
    $old_scheduled = $GLOBALS['sb_test_scheduled_hooks'];
    $wpdb = new class extends SB_Test_WPDB {
        public $banners = array(array('1', '30'));
        public function suppress_errors($suppress = true) { return false; }
        public function get_results($prepared, $output = null)
        {
            return false !== strpos((string) $prepared, 'cmplz_cookiebanners') ? $this->banners : parent::get_results($prepared, $output);
        }
    };
    $GLOBALS['wpdb'] = $wpdb;
    $finish_request = function () use (&$plugin) {
        // One request ends: what it left for `shutdown` runs, and the next request starts with a fresh object.
        $shutdown = array_filter($GLOBALS['sb_test_hooks'], static fn($hook) => 'shutdown' === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0]);
        foreach ($shutdown as $hook) {
            call_user_func($hook[1]);
        }
        $ran = count($shutdown);
        $plugin = new Static_Bridge_Plugin();
        return $ran;
    };
    $queued = static fn() => count((array) get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()));
    try {
        sb_assert(false !== $old_current_target || (!file_exists($current) && !is_link($current)), 'The current release fixture is not a symlink and cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/chi-siamo'), 'Could not create the isolated Complianz fixture.');
        file_put_contents($release . '/index.html', '<html>home</html>');
        file_put_contents($release . '/chi-siamo/index.html', '<html>page</html>');
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the isolated site at its test release.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array());
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $GLOBALS['sb_test_options']['cmplz_options'] = array('records_of_consent' => 'no');

        $expected = array('added_option' => 'maybe_note_complianz_option', 'updated_option' => 'maybe_note_complianz_option', 'deleted_option' => 'maybe_note_complianz_option', 'cmplz_after_css_generation' => 'note_complianz_change', 'cmplz_do_action' => 'note_complianz_admin_action');
        foreach ($expected as $hook_name => $callback_name) {
            $registered = array_filter($GLOBALS['sb_test_hooks'], static fn($hook) => $hook_name === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0] && $callback_name === $hook[1][1]);
            sb_assert(array() !== $registered, 'A Complianz hook is not registered: ' . $hook_name . '.');
        }

        $plugin->maybe_note_complianz_option('blogname');
        $plugin->maybe_note_complianz_option('cmplz_activation_time');
        sb_assert(0 === $finish_request(), 'An option that does not reach the HTML started a Complianz check.');

        // A settings save writes the option and regenerates the CSS of each banner: one refresh, at the end of the request.
        $plugin->maybe_note_complianz_option('cmplz_options');
        $plugin->note_complianz_change();
        $plugin->note_complianz_change();
        sb_assert(1 === $finish_request(), 'A Complianz save did not wait for the end of the request exactly once.');
        sb_assert(2 === $queued(), 'A Complianz save did not queue every static route.');
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION);
        foreach ($queue as $item) {
            sb_assert('refresh' === $item['action'] && !empty($item['shared_content']), 'A Complianz refresh was not queued as a shared refresh.');
        }
        sb_assert(wp_next_scheduled('static_bridge_process_incremental_queue'), 'A Complianz refresh was queued without the worker.');

        // Rendering a page can regenerate the CSS (even forever, when the uploads folder is not writable): nothing changed, nothing is queued.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        for ($render = 0; $render < 3; $render++) {
            $plugin->note_complianz_change();
            $finish_request();
        }
        sb_assert(0 === $queued(), 'A page render queued a refresh of the whole site.');

        // A banner save changes only Complianz's own table.
        $wpdb->banners = array(array('1', '31'));
        $plugin->note_complianz_change();
        $finish_request();
        sb_assert(2 === $queued(), 'A new banner_version did not queue the static routes.');

        // A new policy id is what asks past visitors for consent again.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_options']['complianz_active_policy_id'] = 20;
        $plugin->maybe_note_complianz_option('complianz_active_policy_id');
        $finish_request();
        sb_assert(2 === $queued(), 'A new consent policy id did not queue the static routes.');

        // An extension that prints into the banner adds its option with static_bridge_complianz_options; junk is dropped.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_note_complianz_option('consenso_bridge_impostazioni');
        sb_assert(0 === $finish_request(), 'An option nobody added to the Complianz list started a check.');
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_complianz_options'] = static fn($options) => array_merge($options, array('consenso_bridge_impostazioni', 7, array('x')));
        $GLOBALS['sb_test_options']['consenso_bridge_impostazioni'] = array('framework' => 'acss');
        $plugin->maybe_note_complianz_option('consenso_bridge_impostazioni');
        sb_assert(1 === $finish_request(), 'An option added with static_bridge_complianz_options was not watched.');
        sb_assert(2 === $queued(), 'A change to an option added with static_bridge_complianz_options did not queue the static routes.');
        $watched = sb_private($plugin, 'complianz_options', array());
        sb_assert(array_values(array_filter($watched, 'is_string')) === $watched && 1 === count(array_keys($watched, 'consenso_bridge_impostazioni', true)), 'static_bridge_complianz_options kept a value that is not an option name.');
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_complianz_options'] = static fn() => 'not an array';
        sb_assert(Static_Bridge_Plugin::COMPLIANZ_OPTIONS === sb_private($plugin, 'complianz_options', array()), 'A broken static_bridge_complianz_options filter dropped the Complianz options.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_complianz_options']);

        // Cookies and services live in tables outside the fingerprint; the filter must hand its value back untouched.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        sb_assert(array('x' => 1) === $plugin->note_complianz_admin_action(array('x' => 1), 'get_banner_data') && 0 === $finish_request(), 'Reading a Complianz screen started a check.');
        sb_assert(array('x' => 1) === $plugin->note_complianz_admin_action(array('x' => 1), 'update_cookie'), 'The Complianz filter changed the response.');
        $finish_request();
        sb_assert(2 === $queued(), 'An edited cookie did not refresh the pages that show the cookie policy.');

        // Incremental updates off: nothing is queued, and the save does not fail.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 0;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $wpdb->banners = array(array('1', '32'));
        $plugin->note_complianz_change();
        $finish_request();
        sb_assert(0 === $queued(), 'A Complianz save queued routes with incremental updates off.');

        // Diagnostica: the home page in the release against Complianz now.
        $GLOBALS['sb_test_cmplz_banner_version'] = 32;
        $GLOBALS['sb_test_options']['complianz_active_policy_id'] = 20;
        $config = 'var complianz = {"user_banner_id":"1","banner_version":"32","current_policy_id":"20"};';
        file_put_contents($release . '/index.html', '<html><script>' . $config . '</script></html>');
        $result = sb_private($plugin, 'diagnostic_complianz_step', array('complianz-banner'));
        sb_assert('pass' === $result['status'], 'Diagnostica did not accept a static page in step with Complianz.');
        // Safe mode: the banner is current, but the cookie blocker is off.
        $GLOBALS['sb_test_cmplz_safe_mode'] = true;
        $result = sb_private($plugin, 'diagnostic_complianz_step', array('complianz-banner'));
        unset($GLOBALS['sb_test_cmplz_safe_mode']);
        sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'modalità sicura'), 'Diagnostica did not report Complianz safe mode.');
        file_put_contents($release . '/index.html', '<html><script>' . str_replace('"current_policy_id":"20"', '"current_policy_id":"19"', $config) . '</script></html>');
        $result = sb_private($plugin, 'diagnostic_complianz_step', array('complianz-banner'));
        sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'policy 19') && false !== strpos($result['summary'], 'policy 20'), 'Diagnostica did not report an old consent policy in the static page.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 1;
        file_put_contents($release . '/index.html', '<html><script>' . str_replace('"banner_version":"32"', '"banner_version":"31"', $config) . '</script></html>');
        $result = sb_private($plugin, 'diagnostic_complianz_step', array('complianz-banner'));
        sb_assert('warning' === $result['status'], 'Diagnostica did not report an old banner in the static page.');
        file_put_contents($release . '/index.html', '<html>no banner</html>');
        $result = sb_private($plugin, 'diagnostic_complianz_step', array('complianz-banner'));
        sb_assert('skip' === $result['status'], 'A home page without the banner (banner off, no consent needed) was treated as a problem.');
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        $GLOBALS['sb_test_options'] = $old_options;
        $GLOBALS['sb_test_hooks'] = $old_hooks;
        $GLOBALS['sb_test_scheduled_hooks'] = $old_scheduled;
        if (is_link($current) && 'releases/' . $release_id === readlink($current)) {
            unlink($current);
        }
        if (false !== $old_current_target) {
            symlink($old_current_target, $current);
        }
        @unlink($release . '/chi-siamo/index.html');
        @rmdir($release . '/chi-siamo');
        @unlink($release . '/index.html');
        @rmdir($release);
    }
});

sb_test('Link discovery strips fragments and finds the same links with and without ext-dom', function () use ($plugin) {
    $html = '<html><head><link rel="next" href="/category/frag/page/2/"><link rel="canonical" href="/canonical/"><link rel="alternate" hreflang="en" href="/en/"></head><body>'
        . '<a href="/category/frag/page/3/#content">3</a><a class="x" href=\'/tag/frag/#main\'>t</a><a data-href="/data-only/" href="/plain/">p</a>'
        . '<a href=/unquoted/>u</a><a href="#top">top</a><div data-href="/not-a-link/"></div></body></html>';
    $expected = array('/category/frag/page/2/', '/category/frag/page/3/', '/plain/', '/tag/frag/', '/unquoted/');
    $regex = sb_archive_paths(sb_private($plugin, 'extract_internal_links', array($html, home_url('/'), true)));
    sb_assert($expected === $regex, 'Regex links: ' . implode(' ', $regex));
    if (class_exists('DOMDocument')) {
        $dom = sb_archive_paths(sb_private($plugin, 'extract_internal_links', array($html, home_url('/'))));
        sb_assert($expected === $dom, 'DOM links: ' . implode(' ', $dom));
    }
});

