    function size_format($bytes) { return (int) $bytes . ' B'; }
}
if (!function_exists('wp_convert_hr_to_bytes')) {
    function wp_convert_hr_to_bytes($value) { $value = strtolower(trim((string) $value)); $n = (int) $value; return str_ends_with($value, 'g') ? $n << 30 : (str_ends_with($value, 'm') ? $n << 20 : (str_ends_with($value, 'k') ? $n << 10 : $n)); }
}
