}

sb_test('Server check tells a cache that keeps pages from one that lets them through', function () {
    $layer = array('Static_Bridge_Server_Check', 'cache_layer');
    sb_assert(null === $layer(array(), array()), 'No cache headers must mean no cache.');
    sb_assert(null === $layer(array('cache-control' => 'max-age=0'), array('age' => '0')), 'Cache-Control alone is not a cache layer.');
    $cloudflare = $layer(array('cf-cache-status' => 'DYNAMIC'), array('cf-cache-status' => 'DYNAMIC'));
    sb_assert('cloudflare' === $cloudflare['id'] && false === $cloudflare['stores'], 'Cloudflare DYNAMIC keeps no HTML.');
    $cloudflare = $layer(array('cf-cache-status' => 'MISS'), array('cf-cache-status' => 'HIT'));
    sb_assert(true === $cloudflare['stores'] && 'cf-cache-status: HIT' === $cloudflare['evidence'], 'Cloudflare HIT keeps HTML.');
    sb_assert(null === $layer(array('x-aruba-cache' => 'NA'), array('x-aruba-cache' => 'NA')), 'x-aruba-cache NA is a server without cache (as the Aruba plugin reads it).');
    $aruba = $layer(array('x-aruba-cache' => 'MISS'), array('x-aruba-cache' => 'HIT'));
    sb_assert('aruba' === $aruba['id'] && true === $aruba['stores'], 'Aruba HiSpeed HIT keeps HTML.');
    $aruba = $layer(array('x-aruba-cache' => 'BYPASS'), array('x-aruba-cache' => 'BYPASS'));
    sb_assert(false === $aruba['stores'], 'Aruba BYPASS lets HTML through.');
    $generic = $layer(array('x-cache' => 'MISS'), array('x-cache' => 'HIT from proxy'));
    sb_assert('server' === $generic['id'] && true === $generic['stores'], 'A generic X-Cache HIT keeps HTML.');
    $varnish = $layer(array('x-varnish' => '123'), array('x-varnish' => '124 123', 'age' => '5'));
    sb_assert('varnish' === $varnish['id'] && true === $varnish['stores'], 'Varnish with a growing Age keeps HTML.');
    $age = $layer(array('age' => '0'), array('age' => '12'));
    sb_assert(true === $age['stores'], 'An Age header above zero shows a cache.');
});

sb_test('Server check reads how long a browser keeps a response', function () {
    $max_age = array('Static_Bridge_Server_Check', 'max_age');
    sb_assert(0 === $max_age('public, max-age=0, s-maxage=600'), 's-maxage is for shared caches, not the browser.');
    sb_assert(0 === $max_age('no-store, max-age=0'), 'no-store means no browser cache.');
    sb_assert(0 === $max_age('no-cache'), 'no-cache means revalidation on every visit.');
    sb_assert(31536000 === $max_age('public, max-age=31536000, immutable'), 'A year of max-age was not read.');
    sb_assert(3600 === $max_age('', 'Thu, 01 Jan 2026 01:00:00 GMT', 'Thu, 01 Jan 2026 00:00:00 GMT'), 'Expires was not measured from Date.');
    sb_assert(0 === $max_age('', '0'), 'An invalid Expires means already expired.');
    sb_assert(null === $max_age('', ''), 'No header must mean unknown.');
});

sb_test('Server check names page-cache plugins and leaves purge-only plugins alone', function () {
    $active = array('wp-rocket/wp-rocket.php', 'aruba-hispeed-cache/aruba-hispeed-cache.php', 'fluentform/fluentform.php', 'litespeed-cache/litespeed-cache.php');
    $found = Static_Bridge_Server_Check::plugins_in($active, Static_Bridge_Server_Check::PAGE_CACHE_PLUGINS);
    sb_assert(array('WP Rocket', 'LiteSpeed Cache') === $found, 'Page-cache plugins: ' . implode(', ', $found));
    $purgers = Static_Bridge_Server_Check::plugins_in($active, Static_Bridge_Server_Check::CACHE_PURGE_PLUGINS);
    sb_assert(array('Aruba HiSpeed Cache') === $purgers, 'Purge plugins: ' . implode(', ', $purgers));
    sb_assert('nginx' === Static_Bridge_Server_Check::server_software('nginx/1.26.1')['kind'], 'Nginx not recognised.');
    sb_assert('litespeed' === Static_Bridge_Server_Check::server_software('LiteSpeed')['kind'], 'LiteSpeed not recognised.');
    sb_assert('apache' === Static_Bridge_Server_Check::server_software('Apache/2.4.43 (Unix)')['kind'], 'Apache not recognised.');
    sb_assert('other' === Static_Bridge_Server_Check::server_software('')['kind'], 'An empty SERVER_SOFTWARE must stay unknown.');
});

sb_test('Server check reports a drop-in by its own name', function () {
    $file = WP_CONTENT_DIR . '/sb-test-object-cache.php';
    file_put_contents($file, "<?php\n/*\nPlugin Name: Redis Object Cache Drop-In\nVersion: 2.5\n*/\n");
    sb_assert('Redis Object Cache Drop-In' === Static_Bridge_Server_Check::file_owner($file, Static_Bridge_Server_Check::DROPIN_SIGNATURES), 'Plugin Name not read.');
    file_put_contents($file, "<?php\n// W3 Total Cache object cache\n");
    sb_assert('W3 Total Cache' === Static_Bridge_Server_Check::file_owner($file, Static_Bridge_Server_Check::DROPIN_SIGNATURES), 'Signature not recognised.');
    file_put_contents($file, "<?php\n// custom\n");
    sb_assert('' === Static_Bridge_Server_Check::file_owner($file, Static_Bridge_Server_Check::DROPIN_SIGNATURES), 'An unknown drop-in must have no owner.');
    unlink($file);
});

sb_test('Server check AJAX needs an administrator and the nonce, and runs only known checks', function () use ($plugin) {
    $old_post = $_POST;
    $GLOBALS['sb_test_can_manage'] = false;
    try {
        $plugin->ajax_server_check_step();
        throw new RuntimeException('A non-administrator ran a server check.');
    } catch (SB_Test_Response $response) {
        sb_assert(403 === $response->status, 'A non-administrator was not refused with 403.');
    } finally {
        $GLOBALS['sb_test_can_manage'] = true;
    }
    $GLOBALS['sb_test_nonce_valid'] = false;
    try {
        $plugin->ajax_server_check_start();
        throw new RuntimeException('A server check started without a valid nonce.');
    } catch (RuntimeException $error) {
        sb_assert('Invalid nonce' === $error->getMessage(), 'A missing nonce was not refused: ' . $error->getMessage());
    } finally {
        $GLOBALS['sb_test_nonce_valid'] = true;
    }
    $_POST = array('check' => '../../wp-config');
    try {
        $plugin->ajax_server_check_step();
        throw new RuntimeException('An unknown check was accepted.');
    } catch (SB_Test_Response $response) {
        sb_assert(400 === $response->status, 'An unknown check did not return HTTP 400.');
    } finally {
        $_POST = $old_post;
    }
});

sb_test('Server check asks for pages as a visitor and stores each result', function () use ($plugin) {
    $old_post = $_POST;
    $home = home_url('/');
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_http_responses'][$home] = array('response' => array('code' => 200), 'headers' => array('x-aruba-cache' => 'HIT', 'content-encoding' => 'gzip'), 'body' => '<html></html>');
    try {
        try {
            $plugin->ajax_server_check_start();
        } catch (SB_Test_Response $response) {
            sb_assert(200 === $response->status && 9 === count($response->data['checks']), 'The start did not list the nine checks.');
        }
        $_POST = array('check' => 'host-cache');
        try {
            $plugin->ajax_server_check_step();
            throw new RuntimeException('The step sent no response.');
        } catch (SB_Test_Response $response) {
            $result = $response->data['result'];
            sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'x-aruba-cache: HIT'), 'Aruba HiSpeed keeping pages was not reported: ' . json_encode($result));
            sb_assert(false === $response->data['done'], 'One check out of nine was reported as complete.');
        }
        $calls = $GLOBALS['sb_test_http_calls'];
        sb_assert(2 === count($calls), 'The cache check did not ask twice for the home page.');
        foreach ($calls as $call) {
            sb_assert('wp_safe_remote_get' === $call['api'] && $home === $call['url'], 'The probe left WordPress safe HTTP or the site.');
            $headers = array_change_key_case((array) ($call['args']['headers'] ?? array()));
            sb_assert(!isset($headers['cookie']) && !isset($headers['cache-control']) && !isset($headers['pragma']), 'The probe did not ask as an anonymous visitor: ' . json_encode($headers));
        }
        $stored = get_option('static_bridge_server_check');
        sb_assert(isset($stored['results']['host-cache']) && 0 === $stored['completed_at'], 'The result was not stored, or the run was marked complete.');
    } finally {
        $_POST = $old_post;
        unset($GLOBALS['sb_test_http_responses'][$home]);
        delete_option('static_bridge_server_check');
    }
});

sb_test('Server check results are escaped and the notice stops after the first check', function () use ($plugin, $source) {
    ob_start();
    sb_private($plugin, 'render_server_check_result', array(array('label' => '<b>x</b>', 'status' => '"><script>', 'summary' => '<img src=x onerror=1>', 'remediation' => '<a>')));
    $html = (string) ob_get_clean();
    sb_assert(false === strpos($html, '<script') && false === strpos($html, '<img') && false === strpos($html, '<b>'), 'Unescaped result markup: ' . $html);
    sb_assert(false !== strpos($html, 'is-skip'), 'An unknown status was not shown as not verifiable.');
    $module = file_get_contents(dirname(__DIR__, 2) . '/plugin/server-check.php');
    foreach (array('update_option', 'file_put_contents', 'wp_remote_post', 'wp_safe_remote_post', 'insert_with_markers', 'unlink(') as $write) {
        sb_assert(false === strpos($module, $write), 'The read-only server check writes something: ' . $write);
    }
    sb_assert(false !== strpos($source, "'completed_at']) {\n            return;"), 'The Server notice does not stop after the first check.');
});

// Server tab changes (2.3.0): the .htaccess block, the object-cache drop-in, Aruba's purge.
if (!function_exists('wp_is_writable')) {
