sb_test('Server block lives outside the routing blocks and never gives pages an expiry', function () {
    $block = Static_Bridge_Server_Tuning::htaccess_block();
    sb_assert(false === strpos($block, 'ExpiresByType text/html'), 'The block gives HTML pages an expiry.');
    sb_assert(false === strpos($block, 'ExpiresDefault'), 'A default expiry would reach the HTML pages too.');
    sb_assert(false !== strpos($block, '<IfModule mod_deflate.c>') && false !== strpos($block, '<IfModule mod_expires.c>') && false !== strpos($block, '<IfModule mod_filter.c>'), 'A directive is not guarded by its module.');
    $routing = "# BEGIN Static Bridge\nRewriteEngine On\n# END Static Bridge\n\n# BEGIN WordPress\nRewriteRule . /index.php [L]\n# END WordPress\n";
    $with = Static_Bridge_Server_Tuning::htaccess_contents($routing, true);
    sb_assert(0 === strpos($with, Static_Bridge_Server_Tuning::HTACCESS_BEGIN), 'The block is not at the top of the file.');
    sb_assert($with === Static_Bridge_Server_Tuning::htaccess_contents($with, true), 'Adding the block twice changed the file.');
    sb_assert($routing === Static_Bridge_Server_Tuning::htaccess_contents($with, false), 'Removing the block did not give the original file back.');
    // The routing rewrite (write_rewrite_rules) and the uninstaller remove their blocks with these patterns.
    $after_routing = preg_replace('~^# BEGIN Static Bridge\R.*?^# END Static Bridge\h*(?:\R\h*(?=\R|$))*\R?~ms', '', $with, 1);
    $after_routing = preg_replace('~^# BEGIN Static Bridge Archive Protection\R.*?^# END Static Bridge Archive Protection\h*(?:\R\h*(?=\R|$))*\R?~ms', '', $after_routing, 1);
    sb_assert(false !== strpos($after_routing, $block), 'Rewriting the routing rules damaged the server block.');
    sb_assert(false === strpos($after_routing, '# BEGIN Static Bridge' . "\n"), 'The routing block survived its own removal pattern.');
    $missing = WP_CONTENT_DIR . '/no-such-htaccess';
    sb_assert(is_wp_error(Static_Bridge_Server_Tuning::write_htaccess_block($missing, true)), 'A missing .htaccess was created.');
});

sb_test('Server block is taken away again when the server answers 500 with it', function () use ($plugin) {
    $htaccess = ABSPATH . '.htaccess';
    $original = is_file($htaccess) ? file_get_contents($htaccess) : null;
    $old_software = $_SERVER['SERVER_SOFTWARE'] ?? null;
    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
    file_put_contents($htaccess, "# BEGIN WordPress\n# END WordPress\n");
    $home = home_url('/');
    try {
        $GLOBALS['sb_test_http_responses'][$home] = array('response' => array('code' => 200), 'headers' => array(), 'body' => '');
        $result = sb_private($plugin, 'set_server_htaccess_block', array(true));
        sb_assert(true === $result && Static_Bridge_Server_Tuning::htaccess_has_block(file_get_contents($htaccess)), 'The block was not written.');
        sb_assert(true === sb_private($plugin, 'set_server_htaccess_block', array(false)) && !Static_Bridge_Server_Tuning::htaccess_has_block(file_get_contents($htaccess)), 'The block was not removed.');
        $GLOBALS['sb_test_http_responses'][$home] = array('response' => array('code' => 500), 'headers' => array(), 'body' => '');
        $result = sb_private($plugin, 'set_server_htaccess_block', array(true));
        sb_assert(is_wp_error($result) && false !== strpos($result->get_error_message(), '500'), 'A 500 with the block was not reported.');
        sb_assert("# BEGIN WordPress\n# END WordPress\n" === file_get_contents($htaccess), 'The block stayed after the server refused it.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        sb_assert(is_wp_error(sb_private($plugin, 'set_server_htaccess_block', array(true))), 'The block was written on Nginx.');
    } finally {
        unset($GLOBALS['sb_test_http_responses'][$home]);
        null === $original ? @unlink($htaccess) : file_put_contents($htaccess, $original);
        if (null === $old_software) { unset($_SERVER['SERVER_SOFTWARE']); } else { $_SERVER['SERVER_SOFTWARE'] = $old_software; }
    }
});

sb_test('Object cache drop-in is written with a clean configuration and no password', function () {
    $config = array('type' => 'redis', 'host' => "127.0.0.1'; system('id'); //", 'port' => 99999, 'auth' => true, 'database' => 3, 'prefix' => 'ABC.def$x');
    $source = Static_Bridge_Object_Cache::render_dropin($config);
    sb_assert('' !== $source, 'The template was not rendered.');
    token_get_all($source, TOKEN_PARSE); // throws ParseError on invalid PHP
    sb_assert(false === strpos($source, "system('id')"), 'The host was written unescaped.');
    sb_assert(false !== strpos($source, "'port' => 65535") && false !== strpos($source, "'prefix' => '.defx'") && false !== strpos($source, "'auth' => true"), 'The configuration was not sanitized: ' . substr($source, strpos($source, '/*SB-CONFIG*/'), 400));
    $config_line = substr($source, strpos($source, '/*SB-CONFIG*/'), strrpos($source, '/*SB-CONFIG*/') - strpos($source, '/*SB-CONFIG*/'));
    sb_assert(false === stripos($config_line, 'password') && 1 === substr_count($source, 'Static-Bridge-Object-Cache-Dropin'), 'The configuration holds a password, or the signature is not there once.');
    sb_assert('' === Static_Bridge_Object_Cache::render_dropin($config, "<?php\n// no marker\n"), 'A template without the configuration marker was accepted.');
    $first = Static_Bridge_Object_Cache::config_for(array('name' => 'Redis', 'host' => '127.0.0.1', 'port' => 6379, 'auth' => false, 'database' => 0));
    $second = Static_Bridge_Object_Cache::config_for(array('name' => 'Redis', 'host' => '127.0.0.1', 'port' => 6379, 'auth' => false, 'database' => 0));
    sb_assert(strtok($first['prefix'], '.') === strtok($second['prefix'], '.') && $first['prefix'] !== $second['prefix'], 'Each installation must start from a prefix of its own for the same site.');
});

sb_test('Only the main file is a plugin for WP (2.5.0): the drop-in template gets its plugin header when it is written', function () {
    // The same expression WP's get_file_data() uses to read «Plugin Name» from the first 8 KiB of a file.
    $plugin_name = function ($source) {
        return 1 === preg_match('/^(?:[ \t]*<\?php)?[ \t\/*#@]*Plugin Name:(.*)$/mi', substr(str_replace("\r", "\n", $source), 0, 8192), $match) ? trim($match[1]) : '';
    };
    $directory = dirname(__DIR__, 2) . '/plugin';
    foreach (glob($directory . '/*.php') as $file) {
        $name = $plugin_name((string) file_get_contents($file));
        sb_assert('static-bridge.php' === basename($file) ? 'Static Bridge' === $name : '' === $name, basename($file) . ' has the header that makes WP list it among the plugins: ' . $name);
    }
    $source = Static_Bridge_Object_Cache::render_dropin(array('type' => 'redis', 'host' => '127.0.0.1', 'port' => 6379, 'prefix' => 'x'));
    sb_assert('Static Bridge Object Cache' === $plugin_name($source) && false === strpos($source, 'Drop-in Name:'), 'The written drop-in has no name for the Drop-in list of WP.');
    sb_assert(false !== strpos(substr($source, 0, 2048), Static_Bridge_Object_Cache::SIGNATURE), 'The signature left the first 2 KiB of the drop-in.');
    $file = sys_get_temp_dir() . '/sb-dropin-name-' . getmypid() . '.php';
    file_put_contents($file, $source);
    try {
        sb_assert('Static Bridge Object Cache' === Static_Bridge_Server_Check::file_owner($file, Static_Bridge_Server_Check::DROPIN_SIGNATURES), 'The Server tab does not recognise the written drop-in.');
    } finally {
        @unlink($file);
    }
});

sb_test('Object cache never replaces or removes a drop-in that is not its own', function () {
    $dropin = WP_CONTENT_DIR . '/object-cache.php';
    $service = array('name' => 'Redis', 'reachable' => true, 'where' => '127.0.0.1:6379', 'host' => '127.0.0.1', 'port' => 6379, 'auth' => false, 'database' => 0);
    try {
        sb_assert('none' === Static_Bridge_Object_Cache::dropin_state(), 'A drop-in was found in an empty fixture.');
        file_put_contents($dropin, "<?php\n/* Plugin Name: Redis Object Cache Drop-In */\n");
        sb_assert('foreign' === Static_Bridge_Object_Cache::dropin_state(), 'A foreign drop-in was not recognised.');
        sb_assert(is_wp_error(Static_Bridge_Object_Cache::install($service)) && false !== strpos(file_get_contents($dropin), 'Redis Object Cache Drop-In'), 'A foreign drop-in was replaced.');
        sb_assert(is_wp_error(Static_Bridge_Object_Cache::remove()) && is_file($dropin), 'A foreign drop-in was removed.');
        unlink($dropin);
        $GLOBALS['sb_test_multisite'] = true;
        sb_assert(is_wp_error(Static_Bridge_Object_Cache::install($service)) && !is_file($dropin), 'The drop-in was installed on multisite.');
        $GLOBALS['sb_test_multisite'] = false;
        sb_assert(is_wp_error(Static_Bridge_Object_Cache::install(array('reachable' => false) + $service)) && !is_file($dropin), 'The drop-in was installed without a service that answers.');
    } finally {
        $GLOBALS['sb_test_multisite'] = false;
        @unlink($dropin);
    }
});

sb_test('Object cache drop-in is kept only when the site confirms it over HTTP', function () {
    $dropin = WP_CONTENT_DIR . '/object-cache.php';
    $service = array('name' => 'Redis', 'reachable' => true, 'where' => '127.0.0.1:6379', 'host' => '127.0.0.1', 'port' => 6379, 'auth' => false, 'database' => 0);
    $answer = null;
    $GLOBALS['sb_test_http_callback'] = function ($url, $args) use (&$answer) {
        if (false === strpos($url, 'action=static_bridge_object_cache_probe')) {
            return null;
        }
        sb_assert(empty($args['headers']['Cookie']), 'The probe carried cookies.');
        return $answer;
    };
    try {
        $answer = array('response' => array('code' => 500), 'headers' => array(), 'body' => 'Fatal error');
        $result = Static_Bridge_Object_Cache::install($service);
        sb_assert(is_wp_error($result) && !is_file($dropin), 'A drop-in that broke the site was kept.');
        $answer = array('response' => array('code' => 200), 'headers' => array(), 'body' => '{"success":true,"data":{"ours":true,"connected":false}}');
        sb_assert(is_wp_error(Static_Bridge_Object_Cache::install($service)) && !is_file($dropin), 'A drop-in that could not connect was kept.');
        $answer = array('response' => array('code' => 200), 'headers' => array(), 'body' => '{"success":true,"data":{"ours":true,"connected":true}}');
        sb_assert(true === Static_Bridge_Object_Cache::install($service) && 'ours' === Static_Bridge_Object_Cache::dropin_state(), 'A working drop-in was not kept.');
        sb_assert(false === get_option(Static_Bridge_Object_Cache::PROBE_OPTION), 'The probe token stayed in the database.');
        sb_assert(true === Static_Bridge_Object_Cache::remove() && !is_file($dropin), 'Static Bridge could not remove its own drop-in.');
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        @unlink($dropin);
    }
});

sb_test('Incremental refresh also queues the translated routes of TranslatePress and of the translated_urls filter', function () {
    if (!class_exists('TRP_Translate_Press')) {
        // The three TranslatePress methods Static Bridge reads; languages only while this test sets them.
        class TRP_Translate_Press
        {
            public static function get_trp_instance()
            {
                return new self();
            }

            public function get_component($name)
            {
                return 'settings' === $name ? new TRP_Settings_Fake() : new TRP_Url_Converter_Fake();
            }
        }
        class TRP_Settings_Fake
        {
            public function get_settings()
            {
                return array('default-language' => 'it_IT', 'publish-languages' => $GLOBALS['sb_test_trp_languages'] ?? array('it_IT'));
            }
        }
        class TRP_Url_Converter_Fake
        {
            public function get_url_for_language($language, $url, $processed)
            {
                $slugs = array('/dove-siamo/' => array('en_GB' => '/en/where-we-are/', 'de_DE' => '/de/wo-wir-sind/'));
                $path = (string) parse_url($url, PHP_URL_PATH);
                $prefix = 'en_GB' === $language ? '/en' : '/de';
                return 'evil' === $language ? 'https://evil.example/x/' : home_url($slugs[$path][$language] ?? $prefix . $path);
            }
        }
    }
    $plugin = new Static_Bridge_Plugin();
    $old_queue = $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] ?? null;
    $paths = function () {
        $out = array();
        foreach (get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()) as $item) {
            $out[] = $item['path'] . ' ' . $item['role'];
        }
        sort($out);
        return $out;
    };
    try {
        // No other language published: the queue is what it always was.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/dove-siamo/')), 5, 'refresh', array(), 'single'));
        sb_assert(array('/dove-siamo/ single') === $paths(), 'A site in one language queued more than the page.');

        // English and German: each route in each language, the translated slug included, with the same role.
        $GLOBALS['sb_test_trp_languages'] = array('it_IT', 'en_GB', 'de_DE', 'evil');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/dove-siamo/'), home_url('/menu/')), 5, 'refresh', array(), 'single'));
        sb_assert(array('/de/menu/ single', '/de/wo-wir-sind/ single', '/dove-siamo/ single', '/en/menu/ single', '/en/where-we-are/ single', '/menu/ single') === $paths(), 'Translated routes were not queued exactly: ' . implode(', ', $paths()));

        // Another plugin adds its own; a route of another site from any answer is dropped.
        unset($GLOBALS['sb_test_trp_languages']);
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_translated_urls'] = function ($urls, $url) {
            return array_merge($urls, array(str_replace(home_url('/'), home_url('/fr/'), $url), 'https://evil.example/fr/x/', 42));
        };
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/menu/')), 0, 'delete', array(), 'dependent'));
        sb_assert(array('/fr/menu/ dependent', '/menu/ dependent') === $paths(), 'The translated_urls filter was not honoured safely: ' . implode(', ', $paths()));
        foreach (get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array()) as $item) {
            sb_assert('delete' === $item['action'], 'A translated route lost the action of its original.');
        }
    } finally {
        unset($GLOBALS['sb_test_trp_languages'], $GLOBALS['sb_test_filter_callbacks']['static_bridge_translated_urls']);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = $old_queue;
    }
});

sb_test('Object cache probe answers only the token of a probe in progress', function () {
    $old_get = $_GET;
    try {
        update_option(Static_Bridge_Object_Cache::PROBE_OPTION, array('hash' => hash('sha256', 'right-token'), 'expires' => time() + 60), false);
        foreach (array(array(), array('token' => 'wrong'), array('token' => array('right-token'))) as $get) {
            $_GET = $get;
            try {
                Static_Bridge_Object_Cache::probe_response();
                throw new RuntimeException('The probe answered without the right token.');
            } catch (SB_Test_Response $response) {
                sb_assert(403 === $response->status && null === $response->data, 'A wrong token got an answer: ' . json_encode($response->data));
            }
        }
        $_GET = array('token' => 'right-token');
        try {
            Static_Bridge_Object_Cache::probe_response();
        } catch (SB_Test_Response $response) {
            sb_assert(200 === $response->status && array('ours' => false, 'connected' => false) === $response->data, 'The right token got the wrong answer: ' . json_encode($response->data));
        }
        update_option(Static_Bridge_Object_Cache::PROBE_OPTION, array('hash' => hash('sha256', 'right-token'), 'expires' => time() - 1), false);
        try {
            Static_Bridge_Object_Cache::probe_response();
        } catch (SB_Test_Response $response) {
            sb_assert(403 === $response->status, 'An expired probe got an answer.');
        }
    } finally {
        $_GET = $old_get;
        delete_option(Static_Bridge_Object_Cache::PROBE_OPTION);
    }
});

sb_test('Uninstall removes the server block and Static Bridge\'s own drop-in, nothing else', function () use ($pluginFile) {
    require_once dirname($pluginFile) . '/uninstaller.php';
    $root = sys_get_temp_dir() . '/sb-uninstall-server-' . bin2hex(random_bytes(4));
    mkdir($root . '/wp-content', 0777, true);
    $routing = "# BEGIN WordPress\nRewriteRule . /index.php [L]\n# END WordPress\n";
    file_put_contents($root . '/.htaccess', Static_Bridge_Server_Tuning::htaccess_contents($routing, true));
    file_put_contents($root . '/wp-content/object-cache.php', Static_Bridge_Object_Cache::render_dropin(array('type' => 'redis', 'host' => '127.0.0.1', 'port' => 6379, 'prefix' => 'x')));
    $db = new class {
        public $prefix = 'wp_';
        public $options = 'wp_options';
        public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
        public function prepare($query, ...$args) { return $query; }
        public function get_col($query) { return array(); }
        public function query($query) { return true; }
    };
    try {
        $report = (new Static_Bridge_Uninstaller($db, $root . '/wp-content', $root))->run();
        sb_assert($routing === file_get_contents($root . '/.htaccess'), 'The server block survived uninstall, or other rules were touched.');
        sb_assert(true === $report['object_cache_dropin_removed'] && !is_file($root . '/wp-content/object-cache.php'), 'Static Bridge\'s drop-in survived uninstall.');
        file_put_contents($root . '/wp-content/object-cache.php', "<?php\n// another plugin\n");
        $report = (new Static_Bridge_Uninstaller($db, $root . '/wp-content', $root))->run();
        sb_assert(false === $report['object_cache_dropin_removed'] && is_file($root . '/wp-content/object-cache.php'), 'Uninstall removed another plugin\'s drop-in.');
    } finally {
        @unlink($root . '/wp-content/object-cache.php');
        @unlink($root . '/.htaccess');
        @rmdir($root . '/wp-content');
        @rmdir($root);
    }
});

sb_test('Aruba HiSpeed Cache is emptied when Static Bridge publishes, through its own plugin', function () use ($plugin) {
    sb_assert(null === Static_Bridge_Server_Tuning::purge_aruba('everything'), 'A purge was reported without the Aruba plugin.');
    eval('namespace ArubaSPA\HiSpeedCache\Purger; class WpPurger { public static $calls = array(); public function setPurger($purger) { self::$calls[] = array("setPurger", $purger); } public function purgeAll() { self::$calls[] = array("purgeAll"); } public function purgeUrls($urls) { self::$calls[] = array("purgeUrls", $urls); } }');
    define('AHSC_PURGER', array('host' => '127.0.0.1'));
    $home = home_url('/');
    sb_private($plugin, 'queue_cloudflare_purge', array('everything', 'nuova release completa pubblicata'));
    sb_private($plugin, 'queue_cloudflare_purge', array(array($home . 'pagina/'), 'pagina statica aggiornata'));
    $calls = \ArubaSPA\HiSpeedCache\Purger\WpPurger::$calls;
    sb_assert(array('setPurger', AHSC_PURGER) === $calls[0] && array('purgeAll') === $calls[1], 'A full release did not purge everything: ' . json_encode($calls));
    sb_assert(array('purgeUrls', array($home . 'pagina/')) === $calls[3], 'An updated page was not purged by URL: ' . json_encode($calls));
});

// ---- WooCommerce (2.2.13) --------------------------------------------------------------------------------------
// WooCommerce becomes "active" here, after every other test: class WooCommerce plus the functions Static Bridge calls.
function sb_wc_activate()
{
    if (!class_exists('WooCommerce', false)) {
        eval('class WooCommerce {}');
    }
}

/** A product object with what Static Bridge reads: the ID and the changed properties. */
class SB_Test_WC_Product
{
    private $id;
    private $changes;
    public function __construct($id, $changes = array()) { $this->id = (int) $id; $this->changes = $changes; }
    public function get_id() { return $this->id; }
    public function get_changes() { return $this->changes; }
}

function sb_wc_isolated(callable $callback)
{
    sb_wc_activate();
    sb_archive_isolated(function ($plugin, $release) use ($callback) {
        $previous = array($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], !empty($GLOBALS['sb_test_get_post_wp_post']), $GLOBALS['sb_test_wc_meta'] ?? array());
        $GLOBALS['sb_test_post_types']['product'] = array('public' => true, 'publicly_queryable' => true);
        $GLOBALS['sb_test_post_types']['product_variation'] = array('public' => false);
        $GLOBALS['sb_test_archive']['archive_types']['product'] = 'shop';
        $GLOBALS['sb_test_archive']['counts']['product'] = 21;
        $GLOBALS['sb_test_archive']['taxonomies']['product_cat'] = array('public' => true, 'publicly_queryable' => true, 'hierarchical' => true, 'base' => 'product-category', 'object_type' => array('product'));
        $GLOBALS['sb_test_archive']['terms'][30] = array('term_taxonomy_id' => 130, 'taxonomy' => 'product_cat', 'slug' => 'caffe', 'parent' => 0, 'count' => 21, 'posts' => array(301));
        $GLOBALS['sb_test_archive']['post_terms'][301] = array(30);
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 301, 'post_type' => 'product', 'post_status' => 'publish', 'post_name' => 'miscela'),
            array('ID' => 302, 'post_type' => 'product_variation', 'post_status' => 'publish', 'post_parent' => 301),
            array('ID' => 303, 'post_type' => 'product', 'post_status' => 'publish', 'post_name' => 'kit'),
            array('ID' => 304, 'post_type' => 'product', 'post_status' => 'draft', 'post_name' => 'bozza'),
        );
        $GLOBALS['sb_test_post_urls'] = array(301 => home_url('/product/miscela/'), 303 => home_url('/product/kit/'), 304 => home_url('/?p=304'));
        $GLOBALS['sb_test_get_post_wp_post'] = true;
        // The grouped product 303 contains 301 (_children); the query of woocommerce_products_showing() answers it.
        $GLOBALS['sb_test_wc_meta'] = array(301 => array(303));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 1;
        $GLOBALS['sb_test_options']['show_on_front'] = 'page';
        try {
            $callback($plugin, $release);
        } finally {
            list($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_get_post_wp_post'], $GLOBALS['sb_test_wc_meta']) = $previous;
        }
    });
}

function sb_set_private($object, $property, $value)
{
    $reflection = new ReflectionProperty($object, $property);
    if (PHP_VERSION_ID < 80100) {
        $reflection->setAccessible(true);
    }
    $reflection->setValue($object, $value);
}

sb_test('WooCommerce: a catalog change queues the product page, the products that show it and, for a list change, the shop and its terms, once per request', function () use ($source) {
    sb_wc_isolated(function ($plugin) use ($source) {
        $hooks = array();
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $hooks[$hook[0]][] = is_array($hook[1]) ? $hook[1][1] : '';
        }
        foreach (array('woocommerce_update_product' => 'note_woocommerce_product_saved', 'woocommerce_update_product_variation' => 'note_woocommerce_product_saved',
            'woocommerce_new_product' => 'note_woocommerce_new_product', 'woocommerce_product_set_stock' => 'note_woocommerce_product_page',
            'woocommerce_variation_set_stock' => 'note_woocommerce_product_page', 'woocommerce_product_set_stock_status' => 'note_woocommerce_product_lists',
            'woocommerce_variation_set_stock_status' => 'note_woocommerce_product_lists', 'woocommerce_before_product_object_save' => 'note_woocommerce_product_changes',
            'woocommerce_before_delete_product_variation' => 'note_woocommerce_product_lists', 'woocommerce_after_product_ordering' => 'note_woocommerce_product_lists') as $hook => $method) {
            sb_assert(isset($hooks[$hook]) && in_array($method, $hooks[$hook], true), "WooCommerce hook {$hook} is not handled by {$method}.");
        }
        // Integration off: nothing is noted.
        // Switched off on purpose (2.2.13: undecided means on).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 0;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_decided'] = 1;
        $plugin->note_woocommerce_product_lists(301);
        $plugin->flush_woocommerce_catalog_changes();
        sb_assert(array() === sb_queued_items(), 'A product change was queued with the WooCommerce integration off.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 1;

        // A stock count (an order): the product page and the grouped product that shows it, no list.
        $plugin->note_woocommerce_product_changes(new SB_Test_WC_Product(302, array('stock_quantity' => 4)));
        $plugin->note_woocommerce_product_saved(302);
        $plugin->note_woocommerce_product_page(new SB_Test_WC_Product(302));
        sb_assert(array(301 => 'page') === (new ReflectionProperty($plugin, 'woocommerce_pending_products'))->getValue($plugin), 'A variation was not mapped to its parent, or a stock count was taken for a list change.');
        sb_assert(array() === sb_queued_items(), 'The queue was written before the end of the request.');
        $plugin->flush_woocommerce_catalog_changes();
        sb_assert(array('/product/kit/' => 'refresh', '/product/miscela/' => 'refresh') === sb_queued_items(), 'A stock count did not queue exactly the product page and the grouped product: ' . json_encode(sb_queued_items()));

        // A price (REST, import, scheduled sale): the lists too, with every page of the shop and of the category.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_option_writes'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = 0;
        $plugin->note_woocommerce_product_changes(new SB_Test_WC_Product(301, array('regular_price' => '13.90', 'date_modified' => 1)));
        $plugin->note_woocommerce_product_saved(301);
        $plugin->note_woocommerce_product_page(new SB_Test_WC_Product(301));
        $plugin->flush_woocommerce_catalog_changes();
        $queued = sb_queued_items();
        foreach (array('/', '/product/miscela/', '/product/kit/', '/shop/', '/shop/page/2/', '/shop/page/3/', '/product-category/caffe/', '/product-category/caffe/page/3/') as $path) {
            sb_assert(isset($queued[$path]), "A price change did not queue {$path}: " . json_encode($queued));
        }
        sb_assert(!isset($queued['/shop/page/4/']), 'The shop was paged with more pages than WooCommerce shows (21 products, 10 per page at most).');
        sb_assert(3 >= (int) $GLOBALS['sb_test_option_writes'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION], 'The queue was written for every route instead of once per kind of route.');

        // A withdrawn product and a render: nothing (wp_after_insert_post handles the first, the second must never queue).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->note_woocommerce_product_lists(304);
        $plugin->flush_woocommerce_catalog_changes();
        sb_assert(array() === sb_queued_items(), 'A draft product was queued.');
        sb_set_private($plugin, 'render_request_token_cache', str_repeat('a', 48));
        $plugin->note_woocommerce_product_lists(301);
        sb_set_private($plugin, 'render_request_token_cache', null);
        sb_assert(array() === (new ReflectionProperty($plugin, 'woocommerce_pending_products'))->getValue($plugin), 'A product write during a render was noted.');
        sb_assert(false !== strpos(sb_method_body($source, 'queue_woocommerce_product'), "add_action('shutdown', array(\$this, 'flush_woocommerce_catalog_changes'))"), 'Catalog changes are not written once at the end of the request.');
    });
});

sb_test('WooCommerce (2.3.0): a price change also refreshes the pages of products in the same categories, where «Related products» may show it', function () {
    sb_wc_isolated(function ($plugin) {
        $GLOBALS['sb_test_posts'][] = array('ID' => 305, 'post_type' => 'product', 'post_status' => 'publish', 'post_name' => 'filtri');
        $GLOBALS['sb_test_post_urls'][305] = home_url('/product/filtri/');
        $plugin->note_woocommerce_product_page(new SB_Test_WC_Product(301));
        $plugin->flush_woocommerce_catalog_changes();
        sb_assert(!isset(sb_queued_items()['/product/filtri/']), 'A stock count refreshed the related products too.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->note_woocommerce_product_lists(301);
        $plugin->flush_woocommerce_catalog_changes();
        sb_assert(isset(sb_queued_items()['/product/filtri/']), 'A price change did not refresh a product of the same category: ' . json_encode(sb_queued_items()));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_filter_values']['static_bridge_woocommerce_related_limit'] = 0;
        $plugin->note_woocommerce_product_lists(301);
        $plugin->flush_woocommerce_catalog_changes();
        unset($GLOBALS['sb_test_filter_values']['static_bridge_woocommerce_related_limit']);
        sb_assert(!isset(sb_queued_items()['/product/filtri/']), 'The static_bridge_woocommerce_related_limit filter at 0 did not turn the related pages off.');
    });
});

sb_test('WooCommerce: product blocks and shortcodes are list pages; product archives are paged like WooCommerce', function () {
    sb_wc_isolated(function ($plugin) {
        foreach (array(
            '<!-- wp:woocommerce/product-collection {"queryId":0} -->' => true,
            '<!-- wp:woocommerce/all-products {"columns":3} -->' => true,
            '<!-- wp:woocommerce/handpicked-products {"products":[1]} /-->' => true,
            '<!-- wp:shortcode -->[products limit="4"]<!-- /wp:shortcode -->' => true,
            '[sale_products]' => true,
            '<!-- wp:woocommerce/mini-cart /-->' => false,
            '<!-- wp:woocommerce/cart -->' => false,
            '[productsfoo]' => false,
        ) as $content => $expected) {
            $page = new WP_Post(array('ID' => 77, 'post_type' => 'page', 'post_status' => 'publish', 'post_content' => $content));
            sb_assert($expected === sb_private($plugin, 'post_has_query_loop', array($page)), ($expected ? 'Not recognized as a list: ' : 'Taken for a list: ') . $content);
        }
        sb_assert(10 === sb_private($plugin, 'archive_per_page', array(array('product'))), 'Products were paged with more than the smaller of posts_per_page and the shop number.');
