        sb_assert(16 === sb_private($plugin, 'archive_per_page', array(array('product'))) && 20 === sb_private($plugin, 'archive_per_page', array(array('post'))), 'The WooCommerce number per page (loop_shop_per_page) was not used for products only.');
    });
});

sb_test('WooCommerce: a page keeps only nonces Static Bridge renews; carts, private pages and other nonces stay with WordPress', function () {
    sb_wc_isolated(function ($plugin) {
        $html = '<html><head></head><body><script>var wcBlocksMiddlewareConfig = { storeApiNonce: \'0123456789\' };</script></body></html>';
        $prepared = sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/catalogo/'), $html, array('nonces' => array('wc_store_api' => '0123456789', 'wp_rest' => 'abcdef0123'))));
        sb_assert(is_string($prepared) && 1 === substr_count($prepared, 'id="static-bridge-woocommerce"') && false !== strpos($prepared, 'assets/woocommerce-static.js?ver=' . Static_Bridge_Plugin::VERSION)
            && false !== strpos($prepared, 'data-stale="{&quot;wc_store_api&quot;:&quot;0123456789&quot;,&quot;wp_rest&quot;:&quot;abcdef0123&quot;}"') && strpos($prepared, 'static-bridge-woocommerce') < strpos($prepared, '</head>'), 'The Store API page did not get the refresher with its stale values: ' . $prepared);
        sb_assert($prepared === sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/catalogo/'), $prepared, array('nonces' => array('wc_store_api' => '0123456789')))), 'The refresher was added twice.');
        sb_assert($html === sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('nonces' => array('fluentform-submit-form' => '1111111111')))), 'A page without Store API or REST nonces was changed.');
        foreach (array(
            'a foreign nonce' => array('nonces' => array('woocommerce-sbqa-probe' => '2222222222')),
            'the cart' => array('woocommerce' => true),
            'a private page' => array('private' => true),
            'too many nonces' => array('nonce_overflow' => true),
        ) as $case => $facts) {
            $error = sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, $facts));
            sb_assert($error instanceof WP_Error && 'static_bridge_woocommerce_dynamic' === $error->get_error_code() && '/x/' === $error->get_error_data()['path'], "A page with {$case} was kept static.");
        }
        sb_assert(array('woocommerce-sbqa-probe') === sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('nonces' => array('woocommerce-sbqa-probe' => '2'))))->get_error_data()['actions'], 'The refused action is not reported.');
        $GLOBALS['sb_test_filter_values']['static_bridge_static_nonce_actions'] = array('woocommerce-sbqa-probe');
        sb_assert(is_string(sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('nonces' => array('woocommerce-sbqa-probe' => '2'))))), 'An action declared harmless still made the page dynamic.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_static_nonce_actions']);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 0;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_decided'] = 1;
        sb_assert($html === sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('nonces' => array('woocommerce-sbqa-probe' => '2'), 'private' => true))), 'The nonce rules applied with the integration switched off.');
        sb_assert(sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('woocommerce' => true))) instanceof WP_Error, 'With the integration switched off a cart page became static.');
        sb_assert(false === strpos((string) sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/x/'), $html, array('nonces' => array('wc_store_api' => '0123456789')))), 'static-bridge-woocommerce'), 'The refresher was added with the integration switched off (its endpoint answers 404).');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 1;

        // The facts travel in the body, bound to the render token, and never reach a page.
        $token = str_repeat('b', 48);
        $facts = base64_encode(json_encode(array('nonces' => array('wc_store_api' => '0123456789', 'bad' => 'zz', "x\n" => '0123456789'), 'woocommerce' => true)));
        $body = '<p>pagina<!--static-bridge-facts:' . str_repeat('c', 48) . ':' . $facts . '--></p><!--static-bridge-facts:' . $token . ':' . $facts . '-->';
        list($clean, $read) = sb_private($plugin, 'extract_render_facts', array($body, $token));
        sb_assert(array('wc_store_api' => '0123456789') === $read['nonces'] && true === $read['woocommerce'] && false === $read['private'], 'The render facts were not read safely: ' . json_encode($read));
        sb_assert(false === strpos($clean, $token) && false !== strpos($clean, str_repeat('c', 48)), 'The facts of this render were left in the page, or a comment of another token was taken for them.');
        list(, $none) = sb_private($plugin, 'extract_render_facts', array('<!--static-bridge-facts:' . $token . ':%%%-->', $token));
        sb_assert(array() === $none['nonces'] && false === $none['woocommerce'], 'Malformed facts were trusted.');

        // Nonce actions are noted only while WordPress renders for Static Bridge.
        $plugin->record_render_nonce_action(86400, 'wc_store_api');
        sb_assert(array() === (new ReflectionProperty($plugin, 'render_nonce_actions'))->getValue($plugin), 'A nonce action was noted outside a render.');
        sb_set_private($plugin, 'render_request_token_cache', $token);
        sb_assert(86400 === $plugin->record_render_nonce_action(86400, 'wc_store_api'), 'The nonce lifetime was changed.');
        $plugin->record_render_nonce_action(86400, -1);
        for ($index = 0; $index < Static_Bridge_Plugin::MAX_RENDER_NONCE_ACTIONS + 2; $index++) {
            $plugin->record_render_nonce_action(86400, 'azione-' . $index);
        }
        $plugin->record_render_cache_headers(array('Cache-Control' => 'no-cache, must-revalidate, max-age=0, no-store, private'));
        $GLOBALS['sb_test_nonce_tick'] = 7;
        try {
            $seen = sb_private($plugin, 'render_facts', array('<p data-n="' . wp_create_nonce('wc_store_api') . '"></p>'));
        } finally {
            unset($GLOBALS['sb_test_nonce_tick']);
            sb_set_private($plugin, 'render_request_token_cache', null);
        }
        sb_assert(array('wc_store_api') === array_keys($seen['nonces']) && true === $seen['nonce_overflow'] && true === $seen['private'], 'The render did not report the nonce it printed, the overflow or the private header: ' . json_encode($seen));
    });
});

sb_test('WooCommerce with a Fluent Forms form in the footer: fluentFormVars.nonce (-1) keeps no page dynamic; the same value elsewhere still does (2.4.1)', function () {
    sb_wc_isolated(function ($plugin) {
        // Fluent Forms prints wp_create_nonce() with no action as fluentFormVars.nonce (here aa11bb22cc) on every page with a form.
        $page = str_replace('</head>', '<script>var wcBlocksMiddlewareConfig = { storeApiNonce: \'5555666677\' };</script></head>', sb_ff_fixture_page(array('footer' => true)));
        $facts = array('nonces' => array('-1' => 'aa11bb22cc', 'fluentform-submit-form' => '9876543210', 'fluentform_file_delete' => 'dd33ee44ff', 'wc_store_api' => '5555666677'));
        $prepared = sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/'), $page, $facts));
        sb_assert(is_string($prepared) && 1 === substr_count($prepared, 'id="static-bridge-woocommerce"')
            && false !== strpos($prepared, 'data-stale="{&quot;wc_store_api&quot;:&quot;5555666677&quot;}"'), 'The home with a footer form stayed dynamic for fluentFormVars.nonce: ' . ($prepared instanceof WP_Error ? $prepared->get_error_message() : ''));
        // The same -1 value printed anywhere else is a nonce of another plugin: the page stays with WordPress.
        $elsewhere = str_replace('<main>', '<main><input type="hidden" name="_wpnonce" value="aa11bb22cc">', $page);
        $error = sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/'), $elsewhere, $facts));
        sb_assert($error instanceof WP_Error && array('-1') === $error->get_error_data()['actions'], 'A -1 nonce printed outside fluentFormVars was taken for Fluent Forms\'.');
        // Without fluentFormVars, or with another value there, the -1 nonce still counts.
        $no_vars = str_replace('var fluentFormVars', 'var otherVars', $page);
        sb_assert(sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/'), $no_vars, $facts)) instanceof WP_Error, 'A -1 nonce without fluentFormVars kept the page static.');
        $other_value = str_replace('"nonce":"aa11bb22cc"', '"nonce":"0000000000"', $page) . '<i data-n="aa11bb22cc"></i>';
        sb_assert(sb_private($plugin, 'prepare_woocommerce_static_html', array(home_url('/'), $other_value, $facts)) instanceof WP_Error, 'A -1 nonce matched a fluentFormVars.nonce of another value.');
    });
});

