sb_test('WooCommerce: a GET form that repeats the query (catalog ordering) keeps no render parameter in the static copy', function () {
    $plugin = new Static_Bridge_Plugin();
    $token = str_repeat('d', 48);
    $form = '<form class="woocommerce-ordering" method="get"><select name="orderby"><option value="price">Prezzo</option></select>'
        . '<input type="hidden" name="paged" value="1" /><input type="hidden" name="static_bridge_bypass" value="1" />'
        . "<input type='hidden' name='static_bridge_render' value='{$token}'><input name=static_bridge_render value={$token}><input name=\"static_bridge_rendered\" value=\"x\"></form>";
    $clean = sb_private($plugin, 'strip_render_bypass_parameters', array($form, $token));
    sb_assert(false === stripos($clean, 'name="static_bridge_bypass"') && false === stripos($clean, "name='static_bridge_render'") && false === stripos($clean, 'name=static_bridge_render ')
        && false === strpos($clean, $token), 'The ordering form of a static page still sends the render parameters: ' . $clean);
    sb_assert(false !== strpos($clean, 'name="paged" value="1"') && false !== strpos($clean, 'name="static_bridge_rendered"') && false !== strpos($clean, '</select>'), 'The cleanup removed more than the render parameters: ' . $clean);
});

sb_test('WooCommerce: the public nonce endpoint returns only fresh Store API and REST nonces, never cached', function () use ($source) {
    sb_wc_isolated(function ($plugin) use ($source) {
        $hooks = array();
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $hooks[$hook[0]] = $hook[1];
        }
        sb_assert(isset($hooks['wp_ajax_nopriv_static_bridge_public_woocommerce_nonces'], $hooks['wp_ajax_static_bridge_public_woocommerce_nonces']), 'The WooCommerce nonce endpoint is not registered.');
        $body = sb_method_body($source, 'ajax_public_woocommerce_nonces');
        sb_assert(false !== strpos($body, 'nocache_headers()') && false !== strpos($body, 'no-store'), 'The endpoint does not forbid caching.');
        sb_assert(false === strpos($body, '$_POST') && false === strpos($body, '$_GET') && false === strpos($body, '$_REQUEST'), 'The endpoint reads request input.');
        $call = static function () use ($plugin) {
            try {
                $plugin->ajax_public_woocommerce_nonces();
            } catch (SB_Test_Response $response) {
                return $response;
            }
            throw new RuntimeException('The endpoint sent nothing.');
        };
        $GLOBALS['sb_test_nonce_tick'] = 40;
        try {
            $answer = $call();
            sb_assert(200 === $answer->status && wp_create_nonce('wc_store_api') === $answer->data['store_api'] && wp_create_nonce('wp_rest') === $answer->data['rest']
                && is_int($answer->data['ttl']) && $answer->data['ttl'] >= 60 && array('rest', 'store_api', 'ttl') === (function ($k) { sort($k); return $k; })(array_keys($answer->data)), 'The endpoint did not answer the two fixed nonces.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 0;
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_decided'] = 1;
            sb_assert(200 !== $call()->status, 'The endpoint answered with the integration off.');
        } finally {
            unset($GLOBALS['sb_test_nonce_tick']);
        }
    });
});

sb_test('WooCommerce: /wc-api/, /wc-auth/ and the routes kept with WordPress reach WordPress on Apache, Nginx and Cloudflare; a publication prunes them', function () {
    sb_wc_isolated(function ($plugin, $release) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::WOOCOMMERCE_DYNAMIC_OPTION] = array('/vetrina/' => array('reason' => 'nonce', 'actions' => array('woocommerce-sbqa-probe'), 'at' => 1), '../x' => array('reason' => 'x'));
        $paths = sb_private($plugin, 'routing_excluded_paths');
        foreach (array('/wc-api/', '/wc-auth/', '/vetrina/') as $path) {
            sb_assert(in_array($path, $paths, true), "{$path} is not routed to WordPress: " . json_encode($paths));
        }
        sb_assert(sb_private($plugin, 'is_excluded_path', array('/wc-api/WC_Gateway_Paypal/')), 'A payment gateway callback is not excluded from the export.');
        $apache = sb_private($plugin, 'rewrite_block');
        $nginx = sb_private($plugin, 'nginx_router_block');
        $cloudflare = sb_private($plugin, 'cloudflare_cache_rule_expression');
        sb_assert(false !== strpos($apache, 'wc\\-api') && false !== strpos($apache, 'wc\\-auth') && false !== strpos($apache, 'vetrina'), 'The Apache rules miss a WooCommerce route.');
        sb_assert(false !== strpos($nginx, 'wc-api') && false !== strpos($nginx, 'vetrina'), 'The Nginx block misses a WooCommerce route.');
        sb_assert(false !== strpos($cloudflare, '"/wc-api/"') && false !== strpos($cloudflare, '"/vetrina/"'), 'The Cloudflare expression misses a WooCommerce route.');
        sb_assert(wp_mkdir_p($release . '/vetrina') && false !== file_put_contents($release . '/vetrina/index.html', 'x'), 'Could not seed the route.');
        sb_private($plugin, 'prune_woocommerce_dynamic_routes');
        sb_assert(false === get_option(Static_Bridge_Plugin::WOOCOMMERCE_DYNAMIC_OPTION, false), 'A route with a static file again stayed with WordPress.');
        // Switched off on purpose: the cart, checkout, account and payment answers still reach WordPress (2.2.13).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_enabled'] = 0;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_decided'] = 1;
        $GLOBALS['sb_test_wc_pages'] = array('cart' => 301);
        $GLOBALS['sb_test_post_urls'][301] = home_url('/carrello/');
        try {
            $off = sb_private($plugin, 'routing_excluded_paths');
            sb_assert(in_array('/wc-api/', $off, true) && in_array('/wc-auth/', $off, true) && in_array('/carrello/', $off, true), 'With the integration switched off a WooCommerce transactional route became static: ' . json_encode($off));
            sb_assert(empty(sb_private($plugin, 'settings')['woocommerce_enabled']), 'The switch reads on after being switched off on purpose.');
            // Never decided: on, whatever the old default 0 says.
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['woocommerce_decided']);
            sb_assert(!empty(sb_private($plugin, 'settings')['woocommerce_enabled']), 'With WooCommerce active and no decision the integration is not on.');
        } finally {
            unset($GLOBALS['sb_test_wc_pages']);
        }
    });
});

sb_test('WooCommerce: a store setting shown on every page refreshes all the routes once; the Diagnostica checks the store', function () use ($source) {
    sb_wc_isolated(function ($plugin) use ($source) {
        $hooks = array();
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $hooks[$hook[0]][] = is_array($hook[1]) ? $hook[1][1] : '';
        }
        sb_assert(in_array('maybe_note_woocommerce_option', $hooks['updated_option'] ?? array(), true), 'Store setting changes are not watched.');
        sb_assert(in_array('maybe_queue_reading_option_refresh', $hooks['update_option_woocommerce_permalinks'] ?? array(), true), 'A new product base does not ask for a full export.');
        $plugin->maybe_note_woocommerce_option('woocommerce_email_from_name');
        sb_assert(!(new ReflectionProperty($plugin, 'woocommerce_option_change_noted'))->getValue($plugin), 'A setting that is not on the pages was noted.');
        $plugin->maybe_note_woocommerce_option('woocommerce_currency');
        sb_assert((new ReflectionProperty($plugin, 'woocommerce_option_change_noted'))->getValue($plugin), 'The currency was not noted.');
        $refresh = sb_method_body($source, 'maybe_queue_woocommerce_settings_refresh');
        sb_assert(false !== strpos($refresh, 'WOOCOMMERCE_FINGERPRINT_OPTION') && false !== strpos($refresh, 'queue_shared_output_refresh(') && false !== strpos($refresh, 'update_routing_rules()'), 'A store setting change does not refresh every route once, or does not rewrite the rules.');
        $plan = sb_method_body($source, 'diagnostic_plan');
        foreach (array('woocommerce-endpoint', 'woocommerce-store-api', 'woocommerce-catalog', 'woocommerce-dynamic', 'woocommerce-settings') as $type) {
            sb_assert(false !== strpos($plan, "'type' => '{$type}'") && false !== strpos(sb_method_body($source, 'run_diagnostic_step'), "case '{$type}':"), "The Diagnostica has no {$type} step.");
        }
        $GLOBALS['sb_test_options']['woocommerce_coming_soon'] = 'yes';
        $GLOBALS['sb_test_options']['woocommerce_default_customer_address'] = 'geolocation_ajax';
        try {
            $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'woocommerce-settings', 'type' => 'woocommerce-settings'), array()));
            sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'Prossimamente') && false !== strpos($result['summary'], '?v='), 'The Diagnostica did not flag coming soon and cache-friendly geolocation.');
            $off = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'woocommerce-disabled', 'type' => 'woocommerce-disabled'), array()));
            sb_assert('warning' === $off['status'], 'WooCommerce active with the integration off is not a warning.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::WOOCOMMERCE_DYNAMIC_OPTION] = array('/vetrina/' => array('reason' => 'nonce', 'actions' => array('woocommerce-sbqa-probe'), 'at' => 1));
            $dynamic = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'woocommerce-dynamic-pages', 'type' => 'woocommerce-dynamic'), array()));
            sb_assert('warning' === $dynamic['status'] && false !== strpos($dynamic['summary'], '/vetrina/'), 'A page kept with WordPress for a nonce is not reported.');
        } finally {
            unset($GLOBALS['sb_test_options']['woocommerce_coming_soon'], $GLOBALS['sb_test_options']['woocommerce_default_customer_address'], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::WOOCOMMERCE_DYNAMIC_OPTION]);
        }
    });
});

/** Static Bridge 2.5.0: a release with /chi-siamo/, /chi-siamo/team/ and /notizie/storia/, three posts, Nginx. */
function sb_editor_isolated(callable $callback)
{
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $release_id = 'editor-' . getmypid() . '-' . bin2hex(random_bytes(4));
    $release = $static_root . '/releases/' . $release_id;
    $current = $static_root . '/current';
    $old_current = is_link($current) ? readlink($current) : false;
    $keys = array('sb_test_options', 'sb_test_posts', 'sb_test_post_types', 'sb_test_post_urls', 'sb_test_scheduled_hooks', 'sb_test_caps',
        'sb_test_nonce_tick', 'sb_test_nonce_valid', 'sb_test_nonce_calls', 'sb_test_get_post_wp_post', 'sb_test_singular', 'sb_test_queried_object',
        'sb_test_current_screen', 'sb_test_is_admin', 'sb_test_filter_callbacks', 'sb_test_filter_values', 'sb_test_meta_boxes',
        'sb_test_transients', 'sb_test_menu_pages', 'sb_test_can_manage');
    $saved = array();
    foreach ($keys as $key) {
        $saved[$key] = array_key_exists($key, $GLOBALS) ? array($GLOBALS[$key]) : null;
    }
    $saved_server = $_SERVER['SERVER_SOFTWARE'] ?? null;
    $saved_post = $_POST;
    $saved_get = $_GET;
    $saved_request = $_REQUEST;
    $buffer_level = ob_get_level();
    try {
        sb_assert(false !== $old_current || (!file_exists($current) && !is_link($current)), 'The current release fixture cannot be safely replaced.');
        sb_assert(wp_mkdir_p($release . '/chi-siamo/team') && wp_mkdir_p($release . '/notizie/storia'), 'Could not create the release fixture.');
        foreach (array('index.html', 'chi-siamo/index.html', 'chi-siamo/team/index.html', 'notizie/storia/index.html') as $file) {
            file_put_contents($release . '/' . $file, '<html>' . $file . '</html>');
        }
        file_put_contents($release . '/manifest.json', wp_json_encode(array('release' => $release_id, 'pages_saved' => 4)));
        if (is_link($current)) {
            unlink($current);
        }
        sb_assert(symlink('releases/' . $release_id, $current), 'Could not point the site at the test release.');
        $GLOBALS['sb_test_post_types'] = array(
            'post' => array('public' => true, 'publicly_queryable' => true),
            'page' => array('public' => true, 'publicly_queryable' => false),
        );
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 501, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Chi siamo', 'post_content' => '', 'meta' => array()),
            array('ID' => 502, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Team', 'post_parent' => 501, 'post_content' => '', 'meta' => array()),
            array('ID' => 503, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_title' => 'Storia', 'post_content' => '', 'meta' => array()),
        );
        $GLOBALS['sb_test_post_urls'] = array(501 => home_url('/chi-siamo/'), 502 => home_url('/chi-siamo/team/'), 503 => home_url('/notizie/storia/'));
        $GLOBALS['sb_test_get_post_wp_post'] = true;
        $GLOBALS['sb_test_options'] = array(
            Static_Bridge_Plugin::SETTINGS_OPTION => array('incremental_enabled' => 1, 'excluded_paths' => array(), 'woocommerce_enabled' => 0, 'selective_shared_updates' => 0),
            Static_Bridge_Plugin::FORM_MODES_OPTION => array(),
            Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION => array(),
            Static_Bridge_Plugin::ACTIVITY_OPTION => array(),
        );
        $GLOBALS['sb_test_transients'] = array();
        $GLOBALS['sb_test_scheduled_hooks'] = array();
        $GLOBALS['sb_test_filter_callbacks'] = array();
        $GLOBALS['sb_test_filter_values'] = array();
        $GLOBALS['sb_test_meta_boxes'] = array();
        $GLOBALS['sb_test_menu_pages'] = array();
        // Nonces depend on their action, so a nonce of another post or form is refused.
        $GLOBALS['sb_test_nonce_tick'] = 'editor-tick';
        $GLOBALS['sb_test_nonce_valid'] = true;
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $_POST = array();
        $_GET = array();
        $_REQUEST = array();
        $callback($release);
    } finally {
        while (ob_get_level() > $buffer_level) {
            ob_end_clean();
        }
        if (is_link($current)) {
            @unlink($current);
        }
        if (false !== $old_current) {
            @symlink($old_current, $current);
        }
        if (is_dir($release)) {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
            foreach ($iterator as $entry) {
                $entry->isDir() && !$entry->isLink() ? @rmdir($entry->getPathname()) : @unlink($entry->getPathname());
            }
            @rmdir($release);
        }
        foreach ($saved as $key => $value) {
            if (null === $value) {
                unset($GLOBALS[$key]);
            } else {
                $GLOBALS[$key] = $value[0];
            }
        }
        if (null === $saved_server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $saved_server;
        }
        $_POST = $saved_post;
        $_GET = $saved_get;
        $_REQUEST = $saved_request;
    }
}

/** Admin bar double of WordPress: collects the nodes. */
final class SB_Test_Admin_Bar
{
    public $nodes = array();

    public function add_node($node)
    {
        $this->nodes[$node['id']] = $node;
    }
}

sb_test('Admin bar push (2.5.0): the push link and nonce of the meta box, only on a single content the user may push', function () use ($plugin, $source) {
    $registered = false;
    foreach ($GLOBALS['sb_test_hooks'] as $hook) {
        if ('admin_bar_menu' === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0] && 'add_admin_bar_push_node' === $hook[1][1]) {
            $registered = true;
        }
    }
    sb_assert($registered, 'The admin bar node is not registered on admin_bar_menu.');
    sb_editor_isolated(function () use ($plugin, $source) {
        $story = get_post(503);
        $node = function () use ($plugin) {
            $bar = new SB_Test_Admin_Bar();
            $plugin->add_admin_bar_push_node($bar);
            return $bar->nodes['static-bridge-push'] ?? null;
        };
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(503));
        $GLOBALS['sb_test_singular'] = true;
        $GLOBALS['sb_test_queried_object'] = $story;
        $front = $node();
        sb_assert(is_array($front) && 'Aggiorna la copia statica' === $front['title']
            && sb_private($plugin, 'post_push_action_url', array(503)) === $front['href']
            && false !== strpos($front['href'], 'action=static_bridge_push_post') && false !== strpos($front['href'], 'post_id=503')
            && false !== strpos($front['href'], '_wpnonce='), 'The front end of a single content has no admin bar push with the push URL and nonce.');

        $GLOBALS['sb_test_singular'] = false;
        sb_assert(null === $node(), 'A list or archive page received the push of one content.');
        $GLOBALS['sb_test_singular'] = true;

        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501));
        sb_assert(null === $node(), 'A user who cannot edit the content received the admin bar push.');
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(503));

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 0;
        sb_assert(null === $node(), 'The admin bar offered a push the plugin cannot do (incremental updates off).');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 1;

        // The edit screen of the content.
        $GLOBALS['sb_test_singular'] = false;
        $GLOBALS['sb_test_is_admin'] = true;
        $GLOBALS['sb_test_current_screen'] = (object) array('base' => 'post', 'id' => 'post');
        $_GET = array('post' => '503', 'action' => 'edit');
        $edit = $node();
        sb_assert(is_array($edit) && $front['href'] === $edit['href'], 'The edit screen of the content has no admin bar push, or a different link.');
        $_GET = array('post' => array('503'));
        sb_assert(null === $node(), 'A malformed post parameter on the edit screen produced a push.');
        $_GET = array('post' => '503');
        $GLOBALS['sb_test_current_screen'] = (object) array('base' => 'edit', 'id' => 'edit-post');
        sb_assert(null === $node(), 'The list screen received the push of a single content.');
        $GLOBALS['sb_test_is_admin'] = false;
        $GLOBALS['sb_test_singular'] = true;

        // static_bridge_can_push_post narrows everywhere, and never widens past edit_post.
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_can_push_post'] = function ($allowed, $post, $user_id) {
            return false;
        };
        $actions = $plugin->add_post_push_row_action(array('edit' => 'Edit'), $story);
        ob_start();
        $plugin->render_post_push_meta_box($story);
        $meta_box = ob_get_clean();
        $nonce_calls = $GLOBALS['sb_test_nonce_calls'];
        $_REQUEST = array('post_id' => '503', '_wpnonce' => 'test-nonce');
        $denied = '';
        try {
            $plugin->handle_post_push();
        } catch (SB_Test_WP_Die $die) {
            $denied = $die->getMessage() . '|' . ($die->details['args']['response'] ?? '');
        }
        sb_assert(null === $node() && !isset($actions['static_bridge_push']) && false === strpos($meta_box, 'Aggiorna copia statica')
            && false !== strpos($denied, '|403') && $nonce_calls === $GLOBALS['sb_test_nonce_calls'],
            'A filter that refuses the push left the admin bar, the row action, the meta box or the handler open, or the handler checked the nonce first.');
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(503), 'manage_options' => true);
        $plugin->register_mcp_abilities();
        $ability = $GLOBALS['sb_test_wp_abilities']['abilities'][Static_Bridge_Plugin::MCP_PUSH_POST_ABILITY];
        $mcp = call_user_func($ability['execute_callback'], array('post_id' => 503, 'confirm' => true));
        sb_assert(false === call_user_func($ability['permission_callback'], array('post_id' => 503, 'confirm' => true))
            && is_wp_error($mcp) && 'static_bridge_mcp_push_forbidden' === $mcp->get_error_code(), 'The MCP push ignored static_bridge_can_push_post.');

        foreach (array('yes', 1, array(true), new stdClass(), null) as $hostile) {
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_can_push_post'] = function () use ($hostile) {
                return $hostile;
            };
            sb_assert(null === $node(), 'A filter value that is not boolean true allowed the push: ' . gettype($hostile) . '.');
        }
        $seen = array();
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_can_push_post'] = function ($allowed, $post, $user_id) use (&$seen) {
            $seen = array($allowed, $post instanceof WP_Post ? $post->ID : 0, $user_id);
            return true;
        };
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501));
        sb_assert(null === $node() && array(false, 503, (int) $GLOBALS['sb_test_user_id']) === $seen,
            'The filter widened the push past edit_post, or did not receive the default, the WP_Post and the user ID.');
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(503));
        sb_assert(is_array($node()), 'A filter that allows the push of an editable content was not honoured.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_can_push_post']);

        $push_body = sb_method_body($source, 'handle_post_push');
        sb_assert(strpos($push_body, 'can_push_post(') < strpos($push_body, 'check_admin_referer('), 'handle_post_push() checks the nonce before static_bridge_can_push_post.');
    });
});

sb_test('Editor exclusion (2.5.0): the checkbox keeps a content with WP, removes its copy, follows its route and needs nonce and edit_post', function () use ($plugin, $source) {
    sb_editor_isolated(function ($release) use ($plugin, $source) {
        $about = get_post(501);
        $save = function ($post_id, array $post_fields) use ($plugin) {
            $_POST = $post_fields;
            $plugin->save_post_static_exclusion($post_id, get_post($post_id));
            $_POST = array();
        };
        $entries = function () {
            return get_option(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, array());
        };
        $meta = function ($post_id) {
            return (string) get_post_meta($post_id, Static_Bridge_Plugin::EDITOR_EXCLUDE_META, true);
        };
        $last_activity = function () {
            $items = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
            return is_array($items) && !empty($items) ? end($items) : array();
        };
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501, 502, 503));

        ob_start();
        $plugin->render_post_push_meta_box($about);
        $box = ob_get_clean();
        sb_assert(false !== strpos($box, 'name="static_bridge_exclude" value="1"') && false !== strpos($box, 'Non salvare questa pagina in statico')
            && false !== strpos($box, 'name="static_bridge_exclude_nonce"') && false === strpos($box, '<form')
            && false !== strpos($box, 'Copia il blocco Nginx aggiornato e ricarica Nginx.'), 'The meta box lacks the exclusion checkbox, its nonce or the Nginx notice, or nests a form.');

        $good_nonce = wp_create_nonce('static_bridge_editor_exclude_501');
        // A nonce of another content, a user without edit_post and hostile request values change nothing.
        $save(501, array('static_bridge_exclude_nonce' => wp_create_nonce('static_bridge_editor_exclude_502'), 'static_bridge_exclude' => '1'));
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(502, 503));
        $save(501, array('static_bridge_exclude_nonce' => $good_nonce, 'static_bridge_exclude' => '1'));
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501, 502, 503));
        $save(501, array('static_bridge_exclude_nonce' => array($good_nonce), 'static_bridge_exclude' => '1'));
        $save(501, array('static_bridge_exclude_nonce' => $good_nonce, 'static_bridge_exclude' => array('1')));
        sb_assert('' === $meta(501) && array() === $entries(), 'The exclusion was saved with a wrong nonce, without edit_post or from a malformed request.');

        $save(501, array('static_bridge_exclude_nonce' => $good_nonce, 'static_bridge_exclude' => '1'));
        $settings = sb_private($plugin, 'settings');
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $activity = $last_activity();
        sb_assert('1' === $meta(501) && array(501 => array('/chi-siamo/')) === $entries()
            && in_array('/chi-siamo/', $settings['excluded_paths'], true), 'The checked content did not join the excluded paths.');
        sb_assert(true === sb_private($plugin, 'is_excluded_path', array('/chi-siamo/team/')) && '' === sb_private($plugin, 'normalize_public_url', array(home_url('/chi-siamo/'))),
            'The excluded content (and its subpages) can still enter the full export or the incremental queue.');
        sb_assert(isset($queue[sha1('/chi-siamo/')]) && 'delete' === $queue[sha1('/chi-siamo/')]['action'] && wp_next_scheduled('static_bridge_process_incremental_queue'),
            'The existing static copy was not queued for removal.');
        sb_assert(isset($activity['message']) && 'Percorsi esclusi dall’editor aggiornati.' === $activity['message'] && !empty($activity['error'])
            && false !== strpos($activity['detail'], '/chi-siamo/') && false !== strpos($activity['detail'], 'Copia il blocco Nginx aggiornato e ricarica Nginx.'),
            'Attività does not say that the Nginx block must be copied again.');
        sb_assert(false !== strpos(sb_private($plugin, 'nginx_router_block'), sb_private($plugin, 'nginx_regex_literal', array('chi-siamo'))), 'The Nginx block does not keep the excluded content dynamic.');
        sb_assert('' !== sb_private($plugin, 'post_push_unavailable_reason', array($about)), 'An excluded content can still be pushed.');
        $dynamic = sb_private($plugin, 'dynamic_pages_with_reasons');
        sb_assert(isset($dynamic['/chi-siamo/']) && 'esclusa dall’editor del contenuto' === $dynamic['/chi-siamo/'], 'Genera does not explain why the content is dynamic.');

        $key = sha1('/chi-siamo/');
        sb_assert('done' === sb_private($plugin, 'process_incremental_item', array($key, $queue[$key], $release)) && !is_file($release . '/chi-siamo/index.html')
            && is_file($release . '/chi-siamo/team/index.html'), 'The incremental worker did not remove the excluded copy as for a removed page.');

        // Impostazioni lists it read-only, with the link to the editor.
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501, 502, 503), 'manage_options' => true);
        $_GET = array('tab' => 'settings');
        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();
        $_GET = array();
        sb_assert(false !== strpos($html, 'id="sb-editor-excluded"') && false !== strpos($html, 'post.php?post=501&amp;action=edit')
            && false !== strpos($html, '>Chi siamo</a>') && false !== strpos($html, '<code>/chi-siamo/</code>')
            && false === strpos(implode("\n", sb_private($plugin, 'manual_excluded_paths')), '/chi-siamo/'), 'Impostazioni does not list the excluded content with its edit link, or mixed it into the editable paths.');
        $GLOBALS['sb_test_caps'] = array('edit_post' => array(501, 502, 503));

        // The slug changes: the excluded route follows it without the nonce of the meta box (block editor REST save).
        $GLOBALS['sb_test_post_urls'][501] = home_url('/chi-siamo-ora/');
        $save(501, array());
        sb_assert(array(501 => array('/chi-siamo-ora/')) === $entries() && false === sb_private($plugin, 'is_excluded_path', array('/chi-siamo/'))
            && true === sb_private($plugin, 'is_excluded_path', array('/chi-siamo-ora/')), 'The excluded route did not follow the new slug.');

        // A subpage: renaming its parent page moves its route too.
        $save(502, array('static_bridge_exclude_nonce' => wp_create_nonce('static_bridge_editor_exclude_502'), 'static_bridge_exclude' => '1'));
        $GLOBALS['sb_test_post_urls'][501] = home_url('/azienda/');
        $GLOBALS['sb_test_post_urls'][502] = home_url('/azienda/team/');
        $save(501, array());
        sb_assert(array(501 => array('/azienda/'), 502 => array('/azienda/team/')) === $entries(), 'Renaming a parent page left its excluded subpage on the old route.');
        $GLOBALS['sb_test_post_urls'][502] = home_url('/staff/team/');
        $plugin->refresh_editor_excluded_paths();
        sb_assert(array('/staff/team/') === $entries()[502], 'A permalink structure change did not move the excluded routes.');

        // Trashed: the route goes back to the normal rules; restored, the choice is still there.
        $GLOBALS['sb_test_posts'][1]['post_status'] = 'trash';
        $save(502, array());
        sb_assert(!isset($entries()[502]) && '1' === $meta(502), 'A trashed content still keeps a route with WP, or lost its choice.');
        $GLOBALS['sb_test_posts'][1]['post_status'] = 'publish';
        $save(502, array());
        sb_assert(isset($entries()[502]), 'A restored content did not keep its exclusion.');
        $plugin->forget_deleted_post_exclusion(502);
        $GLOBALS['sb_test_posts'][1]['meta'] = array();
        sb_assert(!isset($entries()[502]), 'A deleted content still keeps a route with WP.');

        // Unchecked: the route leaves the exclusions and the page is queued again.
        update_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array(), false);
        $save(501, array('static_bridge_exclude_nonce' => $good_nonce));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array());
        $activity = $last_activity();
        sb_assert('' === $meta(501) && array() === $entries() && false === sb_private($plugin, 'is_excluded_path', array('/azienda/'))
            && isset($queue[sha1('/azienda/')]) && 'refresh' === $queue[sha1('/azienda/')]['action']
            && false !== strpos($activity['detail'] ?? '', 'Tornano statici: /azienda/.'), 'An unchecked content did not go back to the queue of static pages.');

        // At most MAX_EDITOR_EXCLUDED_POSTS contents.
        $many = array();
        for ($i = 0; $i < Static_Bridge_Plugin::MAX_EDITOR_EXCLUDED_POSTS; $i++) {
            $many[9000 + $i] = array('/pieno-' . $i . '/');
        }
        update_option(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, $many, false);
        $save(503, array('static_bridge_exclude_nonce' => wp_create_nonce('static_bridge_editor_exclude_503'), 'static_bridge_exclude' => '1'));
        $activity = $last_activity();
        sb_assert('' === $meta(503) && !isset($entries()[503]) && !empty($activity['error']) && false !== strpos($activity['message'], 'limite'),
            'The editor exclusions grew past their cap.');

        // A hostile option: only valid post IDs and site routes reach the rules.
        update_option(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, array(
            7 => array('/ok/', 'https://evil.example/x/', '/a/../b/', array('/nested/'), "/riga\nnuova/"),
            'x' => array('/chiave-non-numerica/'),
            -3 => array('/negativo/'),
            8 => '/non-un-elenco/',
        ), false);
        $paths = sb_private($plugin, 'settings')['excluded_paths'];
        sb_assert(in_array('/ok/', $paths, true) && !array_filter($paths, function ($path) {
            return false !== strpos($path, 'evil') || false !== strpos($path, '..') || false !== strpos($path, "\n")
                || in_array($path, array('/chiave-non-numerica/', '/negativo/', '/non-un-elenco/', '/nested/'), true);
        }), 'An invalid stored exclusion reached the excluded paths.');
        update_option(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, 'not an array', false);
        sb_assert(array() === sb_private($plugin, 'editor_excluded_paths'), 'A stored string was read as exclusions.');

        // Apache: the rules name the excluded route.
        update_option(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, array(501 => array('/azienda/')), false);
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.62 (Unix)';
        sb_assert(false !== strpos(sb_private($plugin, 'rewrite_block'), 'azienda'), 'The Apache rules do not keep the excluded content dynamic.');

        // settings() reads one option, never permalinks.
        $settings_body = sb_method_body($source, 'settings') . sb_method_body($source, 'editor_excluded_paths') . sb_method_body($source, 'editor_exclusion_entries');
        sb_assert(false === strpos($settings_body, 'get_permalink') && false === strpos($settings_body, 'get_post('), 'settings() builds permalinks on every call.');
    });
});

sb_test('Roles (2.5.0): static_bridge_export_capability opens only the export and Attività; everything that writes server files stays manage_options', function () use ($plugin) {
    sb_editor_isolated(function () use ($plugin) {
        foreach (array(null, '', '   ', array('edit_pages'), 7, true, new stdClass(), 'edit pages', "edit_pages\n", 'manage_options;drop', str_repeat('a', 65)) as $hostile) {
            $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = $hostile;
            sb_assert('manage_options' === sb_private($plugin, 'export_capability'), 'A hostile capability value was accepted: ' . var_export($hostile, true));
        }
        $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = 'edit_pages';
        sb_assert('edit_pages' === sb_private($plugin, 'export_capability'), 'A valid capability name was refused.');

        $ajax = function ($method) use ($plugin) {
            try {
                $plugin->$method();
            } catch (SB_Test_Response $response) {
                return $response->status;
            } catch (RuntimeException $error) {
                return $error->getMessage();
            }
            return 'no response';
        };
        $GLOBALS['sb_test_caps'] = array('edit_pages' => true);
        sb_assert(200 === $ajax('ajax_status'), 'A user with the export capability cannot read the export status.');
        foreach (array('ajax_diagnostic_status', 'ajax_diagnostic_start', 'ajax_server_check_start') as $admin_only) {
            sb_assert(403 === $ajax($admin_only), $admin_only . ' opened to the export capability.');
        }
        $GLOBALS['sb_test_nonce_valid'] = false;
        sb_assert('Invalid nonce' === $ajax('ajax_status'), 'The export AJAX skipped the nonce.');
        $GLOBALS['sb_test_nonce_valid'] = true;
        $GLOBALS['sb_test_caps'] = array('read' => true);
        foreach (array('ajax_status', 'ajax_start', 'ajax_tick', 'ajax_resume', 'ajax_cancel') as $export_action) {
            sb_assert(403 === $ajax($export_action), $export_action . ' answered a user without the export capability.');
        }
        $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = array('read');
        sb_assert(403 === $ajax('ajax_status'), 'A hostile filter value opened the export to a user without manage_options.');
        $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = 'edit_pages';

        // The admin-post actions that write settings, rules or server files stay with administrators, before the nonce.
        $GLOBALS['sb_test_caps'] = array('edit_pages' => true);
        foreach (array('save_settings', 'save_form_modes', 'handle_server_tuning', 'handle_refresh_request', 'handle_apply_retention', 'handle_delete_release', 'handle_cloudflare_purge', 'save_form_nonce_refresh', 'export_diagnostic_log') as $handler) {
            $calls = $GLOBALS['sb_test_nonce_calls'];
            $died = false;
            try {
                $plugin->$handler();
            } catch (SB_Test_WP_Die $die) {
                $died = true;
            }
            sb_assert($died && $calls === $GLOBALS['sb_test_nonce_calls'], $handler . ' accepted the export capability.');
        }

        // The menu and the page: Genera and Attività only.
        $plugin->register_admin_page();
        sb_assert('edit_pages' === end($GLOBALS['sb_test_menu_pages'])[2], 'The menu does not use the export capability.');
        foreach (array('settings', 'server', 'forms', 'diagnostics', 'versions', 'generate') as $tab) {
            $_GET = array('tab' => $tab);
            ob_start();
            $plugin->render_admin_page();
            $html = ob_get_clean();
            sb_assert(false !== strpos($html, 'id="sb-generate"') && false !== strpos($html, 'tab=activity')
                && false === strpos($html, 'tab=settings') && false === strpos($html, 'tab=server') && false === strpos($html, 'tab=diagnostics')
                && false === strpos($html, 'tab=versions') && false === strpos($html, 'tab=forms')
                && false === strpos($html, 'static_bridge_save_settings') && false === strpos($html, 'static_bridge_refresh'),
                'The export capability sees more than Genera and Attività (asked: ' . $tab . ').');
        }
        $_GET = array('tab' => 'activity');
        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();
        sb_assert(false !== strpos($html, 'Attività recente') && false === strpos($html, 'tab=versions'), 'The export capability cannot read Attività.');
        $GLOBALS['sb_test_caps'] = array('read' => true);
        ob_start();
        $plugin->render_admin_page();
        sb_assert('' === ob_get_clean(), 'The page rendered for a user without the export capability.');

        // An administrator keeps everything, whatever the filter says.
        $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = 'a_capability_nobody_has';
        $GLOBALS['sb_test_caps'] = array('manage_options' => true);
        $plugin->register_admin_page();
        sb_assert('manage_options' === end($GLOBALS['sb_test_menu_pages'])[2] && 200 === $ajax('ajax_status'), 'The filter locked an administrator out.');
        $_GET = array('tab' => 'server');
        ob_start();
        $plugin->render_admin_page();
        $html = ob_get_clean();
        sb_assert(false !== strpos($html, 'tab=settings') && false !== strpos($html, 'tab=server'), 'An administrator lost tabs to the export capability filter.');
        $_GET = array();
    });
});

sb_test('Uninstall (2.5.0) also removes the editor exclusion meta, and no other meta', function () use ($fixtureRoot) {
    $root = $fixtureRoot . '/uninstall-meta-' . bin2hex(random_bytes(4));
    mkdir($root . '/site/wp-content', 0777, true);
    $db = new class {
        public $prefix = 'wp_';
        public $options = 'wp_options';
        public $postmeta = 'wp_postmeta';
        public $queries = array();
        public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
        public function prepare($query, ...$args) { foreach ($args as $a) { $query = preg_replace('/%s/', "'" . $a . "'", $query, 1); } return $query; }
        public function get_col($query) { return array(); }
        public function query($query) { $this->queries[] = $query; return 1; }
    };
    $report = (new Static_Bridge_Uninstaller($db, $root . '/site/wp-content', $root . '/site/'))->run();
    $deletes = array_values(array_filter($db->queries, function ($query) {
        return 0 === strpos($query, 'DELETE FROM');
    }));
    sb_assert(1 === ($report['post_meta_deleted'] ?? 0) && array("DELETE FROM wp_postmeta WHERE meta_key = '_static_bridge_exclude'") === $deletes,
        'Uninstall left the editor exclusion meta, or deleted other meta.');
    sb_assert(Static_Bridge_Plugin::EDITOR_EXCLUDE_META === Static_Bridge_Uninstaller::POST_META_KEYS[0]
        && 0 === strpos(Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION, Static_Bridge_Uninstaller::OPTION_PREFIX), 'The uninstaller does not know the 2.5.0 keys.');
});

sb_test('Attesa dopo l’ultima modifica (2.5.0): 0..120 minutes, off by default, saved from Settings', function () use ($plugin, $source) {
    foreach (array(array('-5', 0), array(-30, 0), array('500', 120), array(121, 120), array('abc', 0), array('', 0), array(' 15 ', 15), array('7.9', 7),
        array(array(5), 0), array(null, 0), array(true, 0), array('1e9', 120), array(120, 120), array(0, 0)) as $case) {
        sb_assert($case[1] === sb_private($plugin, 'sanitize_incremental_wait', array($case[0])), 'The wait was not validated to 0..120: ' . var_export($case[0], true));
    }
    $previous = $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] ?? null;
    try {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array();
        $settings = sb_private($plugin, 'settings');
        sb_assert(0 === $settings['incremental_wait'] && 0 === $settings['failure_email'], 'A site without the 2.5.0 settings changes behavior.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_wait' => '-10', 'failure_email' => 'yes');
        $settings = sb_private($plugin, 'settings');
        sb_assert(0 === $settings['incremental_wait'] && 1 === $settings['failure_email'], 'A stored wait is not validated when read.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_wait' => 9999);
        sb_assert(120 === sb_private($plugin, 'settings')['incremental_wait'] && 7200 === sb_private($plugin, 'incremental_wait_seconds'), 'A stored wait over 120 minutes is not capped.');
    } finally {
        if (null === $previous) {
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]);
        } else {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = $previous;
        }
    }
    $save = sb_method_body($source, 'save_settings');
    sb_assert(false !== strpos($save, "'incremental_wait' => \$this->sanitize_incremental_wait(") && false !== strpos($save, "'failure_email' => isset(\$_POST['failure_email']) ? 1 : 0"),
        'The Settings form does not save the two 2.5.0 settings through their validation.');
    sb_assert(false !== strpos($source, 'name="incremental_wait" min="0" max="') && false !== strpos($source, 'name="failure_email" value="1"'), 'The Settings tab lacks the 2.5.0 fields.');
});

sb_test('Attesa dopo l’ultima modifica (2.5.0): the worker waits for automatic updates, never past twice the wait, and never for a push', function () {
    sb_archive_isolated(function ($plugin, $release) {
        $previous_responses = $GLOBALS['sb_test_http_responses'];
        $previous_hooks = $GLOBALS['sb_test_scheduled_hooks'];
        $previous_job = array_key_exists(Static_Bridge_Plugin::JOB_OPTION, $GLOBALS['sb_test_options']) ? array($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]) : null;
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        $wait_option = Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION;
        $hook = 'static_bridge_process_incremental_queue';
        $item = function ($route, $extra = array()) {
            return array_merge(array('url' => home_url($route), 'path' => $route, 'action' => 'refresh', 'role' => 'dependent', 'post_id' => 0,
                'builders' => array(), 'queued_at' => time(), 'token' => 'tok' . sha1($route), 'attempts' => 0), $extra);
        };
        try {
            sb_assert(false !== file_put_contents($release . '/manifest.json', '{"pages_saved":20}'), 'Could not seed the manifest.');
            foreach (array('/automatica/', '/spinta/') as $route) {
                sb_assert(wp_mkdir_p($release . $route) && false !== file_put_contents($release . $route . 'index.html', 'x'), 'Could not seed ' . $route);
                $GLOBALS['sb_test_http_responses'][home_url($route) . '?static_bridge_bypass=1'] = array('response' => array('code' => 410), 'headers' => array(), 'body' => 'gone', '_sb_strip_render_header' => true);
            }
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 10;
            $now = time();

            // An edit a minute ago: the automatic route waits, and the worker comes back when the wait ends.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/automatica/') => $item('/automatica/'));
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 60, 'last' => $now - 60);
            $GLOBALS['sb_test_scheduled_hooks'] = array();
            $plugin->process_incremental_queue();
            sb_assert(array('/automatica/' => 'refresh') === sb_queued_items() && is_file($release . '/automatica/index.html'), 'The worker did not wait after the last edit.');
            sb_assert(abs($GLOBALS['sb_test_scheduled_hooks'][$hook] - ($now + 540)) <= 2, 'The worker was not rescheduled for the rest of the wait.');

            // Each edit moves the wait, but never past twice the wait from the first change still waiting.
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 1150, 'last' => $now - 30);
            sb_assert(abs(sb_private($plugin, 'incremental_wait_remaining') - 50) <= 2, 'The wait went past twice its length from the first change.');
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 1300, 'last' => $now - 5);
            sb_assert(0 === sb_private($plugin, 'incremental_wait_remaining'), 'A site edited all the time never publishes.');
            $plugin->process_incremental_queue();
            sb_assert(array() === sb_queued_items() && !is_file($release . '/automatica/index.html'), 'The worker did not work once twice the wait had passed.');
            sb_assert(false === get_option($wait_option, false), 'The wait was not closed once the queue had nothing new.');

            // The wait ended (last edit more than the wait ago): the worker works.
            sb_assert(wp_mkdir_p($release . '/automatica') && false !== file_put_contents($release . '/automatica/index.html', 'x'), 'Could not seed the route again.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/automatica/') => $item('/automatica/'));
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 700, 'last' => $now - 700);
            $plugin->process_incremental_queue();
            sb_assert(array() === sb_queued_items(), 'The worker did not work after the wait.');

            // A manual push, even behind an automatic route, does not wait; the automatic route keeps waiting.
            sb_assert(wp_mkdir_p($release . '/automatica') && false !== file_put_contents($release . '/automatica/index.html', 'x'), 'Could not seed the route again.');
            $push_token = wp_generate_uuid4();
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(
                sha1('/automatica/') => $item('/automatica/'),
                sha1('/spinta/') => $item('/spinta/', array('manual_push_token' => $push_token, 'role' => 'single')),
            );
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 10, 'last' => $now - 10);
            $GLOBALS['sb_test_scheduled_hooks'] = array();
            $plugin->process_incremental_queue();
            sb_assert(array('/automatica/' => 'refresh') === sb_queued_items() && !is_file($release . '/spinta/index.html') && is_file($release . '/automatica/index.html'),
                'A manual push waited, or the automatic route did not: ' . wp_json_encode(sb_queued_items()));
            sb_assert(abs($GLOBALS['sb_test_scheduled_hooks'][$hook] - ($now + 590)) <= 2, 'After the push the worker was not rescheduled for the end of the wait.');
            // A push that must retry keeps its own short delay instead of the end of the wait.
            $GLOBALS['sb_test_scheduled_hooks'][$hook] = $now + 590;
            sb_private($plugin, 'schedule_incremental_worker_within', array(20));
            sb_assert(abs($GLOBALS['sb_test_scheduled_hooks'][$hook] - ($now + 20)) <= 2, 'A push retry stayed behind the end of the wait.');
            sb_private($plugin, 'schedule_incremental_worker_within', array(60));
            sb_assert(abs($GLOBALS['sb_test_scheduled_hooks'][$hook] - ($now + 20)) <= 2, 'An earlier event was moved later.');

            // 0 (the default) is today's behavior: a leftover wait is ignored.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 0;
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now, 'last' => $now);
            $plugin->process_incremental_queue();
            sb_assert(array() === sb_queued_items(), 'With the wait at 0 the worker still waited.');

            // An automatic change starts the wait and moves it; the worker's own routes and the setting at 0 do not.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 10;
            unset($GLOBALS['sb_test_options'][$wait_option]);
            sb_private($plugin, 'schedule_incremental_worker_after_change');
            $state = get_option($wait_option);
            sb_assert(is_array($state) && abs($state['first'] - $now) <= 2 && $state['first'] === $state['last'] && abs($GLOBALS['sb_test_scheduled_hooks'][$hook] - $now) <= 2,
                'An automatic change did not start the wait, or did not schedule the worker at once.');
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 100, 'last' => $now - 100);
            sb_assert(1 === sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/nuova-modifica/')), 0, 'refresh', array(), 'dependent')), 'Could not queue a route.');
            $state = get_option($wait_option);
            sb_assert($now - 100 === $state['first'] && abs($state['last'] - $now) <= 2, 'A new edit did not move the wait forward, or moved its start.');
            $processing = new ReflectionProperty($plugin, 'processing_incremental_items');
            if (PHP_VERSION_ID < 80100) {
                $processing->setAccessible(true);
            }
            $processing->setValue($plugin, true);
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 100, 'last' => $now - 100);
            sb_private($plugin, 'schedule_incremental_worker_after_change');
            $processing->setValue($plugin, false);
            sb_assert($now - 100 === get_option($wait_option)['last'], 'A route queued by the worker itself moved the wait.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 0;
            unset($GLOBALS['sb_test_options'][$wait_option]);
            sb_private($plugin, 'schedule_incremental_worker_after_change');
            sb_assert(false === get_option($wait_option, false), 'With the wait at 0 a change still wrote the wait.');

            // «Aggiorna tutte le pagine statiche», the REST refresh and deploy scripts end the wait.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 10;
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 10, 'last' => $now - 10);
            $result = sb_private($plugin, 'request_static_refresh', array('paths', array('/richiesta/'), 'deploy'));
            sb_assert('queued' === $result['status'] && false === get_option($wait_option, false), 'An explicit refresh waited for the last edit.');

            // Genera says until when the updates wait.
            $GLOBALS['sb_test_options'][$wait_option] = array('first' => $now - 10, 'last' => $now - 10);
            ob_start();
            try {
                $plugin->render_admin_page();
            } finally {
                $page = ob_get_clean();
            }
            sb_assert(false !== strpos($page, 'id="sb-incremental-wait-status"') && false !== strpos($page, gmdate('H:i', $now + 590)), 'Genera does not say until when the updates wait.');
        } finally {
            $GLOBALS['sb_test_http_responses'] = $previous_responses;
            $GLOBALS['sb_test_scheduled_hooks'] = $previous_hooks;
            unset($GLOBALS['sb_test_options'][$wait_option], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::POST_PUSH_STATUS_OPTION]);
            if (null !== $previous_job) {
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $previous_job[0];
            }
        }
    });
});

function sb_failure_isolated(callable $callback)
{
    $previous = array($GLOBALS['sb_test_options'], $GLOBALS['sb_test_actions_fired'], $GLOBALS['sb_test_scheduled_hooks'], $GLOBALS['sb_test_filter_values'],
        $GLOBALS['sb_test_mails'] ?? array(), $GLOBALS['sb_test_option_update_listeners'] ?? array(), $GLOBALS['sb_test_action_callbacks'] ?? array());
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'failure_email' => 1);
    $GLOBALS['sb_test_options']['admin_email'] = 'admin@example.test';
    $GLOBALS['sb_test_options']['blogname'] = 'Sito &amp; prova';
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::FAILURE_NOTICE_OPTION], $GLOBALS['sb_test_mail_result']);
    $GLOBALS['sb_test_mails'] = array();
    $GLOBALS['sb_test_actions_fired'] = array();
    try {
        $callback(new Static_Bridge_Plugin());
    } finally {
        list($GLOBALS['sb_test_options'], $GLOBALS['sb_test_actions_fired'], $GLOBALS['sb_test_scheduled_hooks'], $GLOBALS['sb_test_filter_values'],
            $GLOBALS['sb_test_mails'], $GLOBALS['sb_test_option_update_listeners'], $GLOBALS['sb_test_action_callbacks']) = $previous;
        unset($GLOBALS['sb_test_mail_result']);
    }
}

sb_test('Failure e-mail (2.5.0): off by default, once until an update works again, to a valid recipient, without server paths', function () {
    sb_failure_isolated(function ($plugin) {
        $activity = function () {
            return wp_json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), JSON_UNESCAPED_UNICODE);
        };
        sb_assert(true === sb_private($plugin, 'notify_update_failure', array('export', 'Scrittura non riuscita in ' . WP_CONTENT_DIR . '/static-bridge/releases/r1/x.html')), 'The failure e-mail was not sent.');
        sb_assert(1 === count($GLOBALS['sb_test_mails']), 'The failure e-mail was not sent once.');
        $mail = $GLOBALS['sb_test_mails'][0];
        sb_assert('admin@example.test' === $mail['to'] && false !== strpos($mail['subject'], 'Sito & prova') && false === strpos($mail['subject'], "\n"), 'Recipient or subject of the e-mail are wrong: ' . $mail['subject']);
        sb_assert(false !== strpos($mail['message'], 'wp-content/static-bridge/releases/r1/x.html') && false === strpos($mail['message'], ABSPATH)
            && false !== strpos($mail['message'], 'page=static-bridge') && false !== strpos($mail['message'], 'tab=activity'), 'The e-mail shows server paths or lacks the link to Static Bridge.');
        sb_assert(false !== strpos($activity(), 'Avviso per email inviato'), 'The e-mail sent is not in Attività.');

        // Not again for the next failure, export or incremental, until something works.
        sb_private($plugin, 'notify_update_failure', array('export', 'ancora'));
        $item = array('url' => home_url('/rotta/'), 'path' => '/rotta/', 'action' => 'refresh', 'role' => 'dependent', 'post_id' => 0, 'builders' => array(), 'token' => 't1', 'attempts' => 6);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $item);
        sb_private($plugin, 'retry_incremental_item', array(sha1('/rotta/'), $item, 'HTTP 503'));
        sb_assert(1 === count($GLOBALS['sb_test_mails']), 'A second failure sent a second e-mail.');

        // A published export (or a completed incremental update) resets it: the next failure e-mails again.
        $plugin->handle_export_job_saved(array('job_id' => 'j1', 'status' => 'running'), array('job_id' => 'j1', 'status' => 'complete', 'release_id' => 'r1', 'saved' => 3));
        sb_assert(false === get_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION, false), 'A published export did not reset the e-mail.');
        // The seventh failed attempt of an automatic route is the one that does not fix itself.
        $item['attempts'] = 5;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $item);
        sb_private($plugin, 'retry_incremental_item', array(sha1('/rotta/'), $item, 'HTTP 503'));
        sb_assert(1 === count($GLOBALS['sb_test_mails']), 'An incremental route e-mailed before its seventh attempt.');
        $item['attempts'] = 6;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $item);
        sb_private($plugin, 'retry_incremental_item', array(sha1('/rotta/'), $item, 'HTTP 503'));
        sb_assert(2 === count($GLOBALS['sb_test_mails']) && false !== strpos($GLOBALS['sb_test_mails'][1]['message'], '/rotta/ — HTTP 503'), 'The seventh failed attempt of an automatic route did not e-mail after a success.');
        // A manual push is not an automatic update: its retries never e-mail.
        delete_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION);
        $pushed = array_merge($item, array('manual_push_token' => wp_generate_uuid4()));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/rotta/') => $pushed);
        sb_private($plugin, 'retry_incremental_item', array(sha1('/rotta/'), $pushed, 'HTTP 503'));
        sb_assert(2 === count($GLOBALS['sb_test_mails']), 'The retry of a manual push e-mailed.');

        // An invalid recipient from the filter falls back to the administrator; a valid one is used.
        foreach (array('non-un-indirizzo', array('x@example.test'), "ops@example.test\nBcc: spia@example.test", '', 42) as $bad) {
            delete_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION);
            $GLOBALS['sb_test_filter_values']['static_bridge_failure_email_recipient'] = $bad;
            sb_private($plugin, 'notify_update_failure', array('export', 'x'));
            sb_assert('admin@example.test' === end($GLOBALS['sb_test_mails'])['to'], 'An invalid filter recipient was used: ' . var_export($bad, true));
        }
        delete_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION);
        $GLOBALS['sb_test_filter_values']['static_bridge_failure_email_recipient'] = 'ops@example.test';
        sb_private($plugin, 'notify_update_failure', array('export', 'x'));
        sb_assert('ops@example.test' === end($GLOBALS['sb_test_mails'])['to'], 'The valid filter recipient was not used.');
        unset($GLOBALS['sb_test_filter_values']['static_bridge_failure_email_recipient']);

        // wp_mail failing: one line in Attività, nothing else, and no new attempt at the next failure.
        delete_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION);
        $GLOBALS['sb_test_mail_result'] = false;
        $mails = count($GLOBALS['sb_test_mails']);
        sb_assert(false === sb_private($plugin, 'notify_update_failure', array('export', 'x')) && false !== strpos($activity(), 'Avviso per email non inviato: wp_mail non è riuscita.'), 'A failed wp_mail is not in Attività.');
        sb_private($plugin, 'notify_update_failure', array('export', 'x'));
        sb_assert($mails + 1 === count($GLOBALS['sb_test_mails']), 'A failed wp_mail was retried at once.');
        unset($GLOBALS['sb_test_mail_result']);

        // Off (the default): no e-mail.
        delete_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['failure_email'] = 0;
        $mails = count($GLOBALS['sb_test_mails']);
        sb_assert(false === sb_private($plugin, 'notify_update_failure', array('export', 'x')) && $mails === count($GLOBALS['sb_test_mails'])
            && false === get_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION, false), 'With the setting off an e-mail was sent.');
    });
});

sb_test('static_bridge_export_finished (2.5.0): once per export, published, failed or cancelled, and a failing listener changes nothing', function () {
    sb_failure_isolated(function ($plugin) {
        $registered = false;
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            $registered = $registered || ('update_option_' . Static_Bridge_Plugin::JOB_OPTION === $hook[0] && is_array($hook[1]) && 'handle_export_job_saved' === $hook[1][1] && 2 === $hook[3]);
        }
        sb_assert($registered, 'The end of an export is not watched where the job is saved.');
        $GLOBALS['sb_test_option_update_listeners'][Static_Bridge_Plugin::JOB_OPTION] = array($plugin, 'handle_export_job_saved');
        $finished = function () {
            return array_values(array_filter($GLOBALS['sb_test_actions_fired'], function ($fired) {
                return 'static_bridge_export_finished' === $fired[0];
            }));
        };
        $job = function ($id) {
            return array('queue_version' => 1, 'job_id' => $id, 'status' => 'running', 'release_id' => 'rel-' . $id, 'saved' => 4, 'skipped' => 1,
                'route_errors' => 2, 'started_at' => time() - 60, 'updated_at' => time(), 'issues' => array());
        };

        // Failed, through one of the many paths that fail an export: one action, one e-mail.
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job('j-fail'), false);
        sb_private($plugin, 'fail_export_queue_job', array(get_option(Static_Bridge_Plugin::JOB_OPTION), home_url('/x/'), 'Disco pieno in ' . WP_CONTENT_DIR . '/static-bridge/releases/rel-j-fail'));
        $events = $finished();
        sb_assert(1 === count($events) && 'failed' === $events[0][1][0], 'A failed export did not fire static_bridge_export_finished once.');
        $summary = $events[0][1][1];
        sb_assert('j-fail' === $summary['job_id'] && '' === $summary['release_id'] && 4 === $summary['saved'] && 2 === $summary['failed']
            && false !== strpos($summary['message'], 'Disco pieno in wp-content/static-bridge/releases/rel-j-fail') && false === strpos($summary['message'], ABSPATH),
            'The summary of a failed export is wrong: ' . wp_json_encode($summary));
        sb_assert(1 === count($GLOBALS['sb_test_mails']) && false !== strpos($GLOBALS['sb_test_mails'][0]['subject'], 'export completo non riuscito'), 'A failed export did not e-mail the administrator.');
        // Saved again with the same final status: not a new end.
        $saved = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $saved['updated_at']++;
        update_option(Static_Bridge_Plugin::JOB_OPTION, $saved, false);
        sb_assert(1 === count($finished()), 'The same export was announced twice.');

        // Published: the release ID, and the e-mail state is reset.
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job('j-ok'), false);
        $done = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $done['status'] = 'complete';
        update_option(Static_Bridge_Plugin::JOB_OPTION, $done, false);
        $events = $finished();
        sb_assert(2 === count($events) && 'complete' === $events[1][1][0] && 'rel-j-ok' === $events[1][1][1]['release_id']
            && false !== strpos($events[1][1][1]['message'], 'Versione pubblicata'), 'A published export was not announced with its release.');
        sb_assert(false === get_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION, false), 'A published export did not reset the failure e-mail.');

        // Cancelled: announced, no e-mail.
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job('j-stop'), false);
        $stopped = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $stopped['status'] = 'cancelled';
        $stopped['issues'][] = array('url' => '', 'message' => 'Esportazione annullata dall’utente.');
        update_option(Static_Bridge_Plugin::JOB_OPTION, $stopped, false);
        $events = $finished();
        sb_assert(3 === count($events) && 'cancelled' === $events[2][1][0] && '' === $events[2][1][1]['release_id'] && 1 === count($GLOBALS['sb_test_mails']),
            'A cancelled export was not announced, or e-mailed.');

        // A listener that throws: the export result stays, and Attività says so.
        $GLOBALS['sb_test_action_callbacks']['static_bridge_export_finished'] = function () {
            throw new RuntimeException('ascoltatore rotto');
        };
        update_option(Static_Bridge_Plugin::JOB_OPTION, $job('j-boom'), false);
        $boom = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $boom['status'] = 'complete';
        update_option(Static_Bridge_Plugin::JOB_OPTION, $boom, false);
        sb_assert('complete' === get_option(Static_Bridge_Plugin::JOB_OPTION)['status'] && 4 === count($finished()), 'A failing listener changed the export result.');
        sb_assert(false !== strpos(wp_json_encode(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION), JSON_UNESCAPED_UNICODE), 'un plugin in ascolto ha generato un errore'), 'A failing listener left no line in Attività.');
    });
});

sb_test('Uninstall (2.5.0) knows the options of the wait and of the failure e-mail', function () {
    foreach (array(Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION, Static_Bridge_Plugin::FAILURE_NOTICE_OPTION, Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION) as $name) {
        sb_assert(in_array($name, Static_Bridge_Uninstaller::OPTIONS, true) && 0 === strpos($name, Static_Bridge_Uninstaller::OPTION_PREFIX), 'The uninstaller does not know ' . $name);
    }
    $previous = $GLOBALS['sb_test_options'];
    try {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION] = array('first' => 1, 'last' => 2);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FAILURE_NOTICE_OPTION] = array('at' => 1);
        $db = new class {
            public $options = 'wp_options';
            public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
            public function prepare($query, ...$args) { return $query; }
            public function get_col($query) { return false; } // the prefix query fails
        };
        $report = sb_private(new Static_Bridge_Uninstaller($db, WP_CONTENT_DIR, ABSPATH), 'delete_options');
        sb_assert(2 <= $report && !isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION]) && !isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::FAILURE_NOTICE_OPTION]),
            'The 2.5.0 options survive an uninstall whose prefix query fails.');
    } finally {
        $GLOBALS['sb_test_options'] = $previous;
    }
});

// 2.5.0, group C: «Export completo pianificato» and the WP-CLI commands. Stubs used only from here on.
if (!function_exists('wp_timezone')) {
    function wp_timezone() { return new DateTimeZone($GLOBALS['sb_test_timezone'] ?? 'UTC'); }
}
if (!function_exists('wp_unschedule_event')) {
    function wp_unschedule_event($timestamp, $hook)
    {
        if (isset($GLOBALS['sb_test_scheduled_hooks'][$hook]) && (int) $GLOBALS['sb_test_scheduled_hooks'][$hook] === (int) $timestamp) {
            unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        }
        return true;
    }
}
if (!function_exists('sanitize_textarea_field')) {
    function sanitize_textarea_field($value) { return trim(strip_tags((string) $value)); }
}
if (!function_exists('wp_safe_redirect')) {
    function wp_safe_redirect($location, $status = 302) { throw new SB_Test_Response(302, array('location' => $location)); }
}

/** Runs $callback with the options, events, mails and HTTP log of the suite restored afterwards, and no export job. */
function sb_group_c_isolated(callable $callback)
{
    $saved = array($GLOBALS['sb_test_options'], $GLOBALS['sb_test_scheduled_hooks'], $GLOBALS['sb_test_mails'] ?? array(),
        $GLOBALS['sb_test_http_calls'], $GLOBALS['sb_test_http_responses'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_timezone'] ?? null, $_POST);
    $current = WP_CONTENT_DIR . '/static-bridge/current';
    $current_target = is_link($current) ? readlink($current) : false;
    unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION],
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FAILURE_NOTICE_OPTION]);
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    $GLOBALS['sb_test_scheduled_hooks'] = array();
    $GLOBALS['sb_test_http_calls'] = array();
    $GLOBALS['sb_test_mails'] = array();
    try {
        $callback(new Static_Bridge_Plugin());
    } finally {
        list($GLOBALS['sb_test_options'], $GLOBALS['sb_test_scheduled_hooks'], $GLOBALS['sb_test_mails'], $GLOBALS['sb_test_http_calls'],
            $GLOBALS['sb_test_http_responses'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_timezone'], $_POST) = $saved;
        if (false !== $current_target && (!is_link($current) || readlink($current) !== $current_target)) {
            @unlink($current);
            @symlink($current_target, $current);
        }
    }
}

/** The messages of the Attività rows written since the isolation started. */
function sb_group_c_activity()
{
    return array_map(function ($row) {
        return (string) $row['message'] . ' | ' . (string) $row['detail'] . ($row['error'] ? ' | error' : '');
    }, (array) get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()));
}

sb_test('start_export (2.5.0): the refusals of ajax_start as WP_Error with the same HTTP status, and ajax_start unchanged', function () use ($source) {
    sb_group_c_isolated(function ($plugin) use ($source) {
        $ajax = function () use ($plugin) {
            try {
                $plugin->ajax_start();
            } catch (SB_Test_Response $response) {
                return $response;
            }
            return null;
        };
        $GLOBALS['sb_test_can_manage'] = true;
        $GLOBALS['sb_test_nonce_valid'] = true;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1);

        // A start from the schedule: the job says who started it, Attività says it in the detail only.
        $job = sb_private($plugin, 'start_export', array('schedule'));
        sb_assert(is_array($job) && 'running' === $job['status'] && 'schedule' === $job['started_by'] && is_dir($job['stage']), 'start_export did not create a running job started by the schedule.');
        $rows = sb_group_c_activity();
        sb_assert(1 === count(array_filter($rows, function ($row) {
            return 0 === strpos($row, 'Esportazione avviata. | Inventario WordPress per blocchi indicizzati;') && false !== strpos($row, 'Avviata da: export pianificato.');
        })), 'The start row of Attività lost its message or does not say who started the export: ' . implode(' / ', $rows));
        $plugin->send_deferred_export_continuation();
        sb_assert(1 === count($GLOBALS['sb_test_http_calls']), 'A scheduled start did not hand the export to the background requests.');

        // An alive export: 409, the same message from start_export and from ajax_start.
        $refused = sb_private($plugin, 'start_export', array('cli'));
        sb_assert(is_wp_error($refused) && 'static_bridge_export_running' === $refused->get_error_code() && array('status' => 409) === $refused->get_error_data()
            && 'È già in corso un’esportazione.' === $refused->get_error_message(), 'A second start was not refused with 409 while an export runs.');
        $response = $ajax();
        sb_assert($response instanceof SB_Test_Response && 409 === $response->status && array('message' => 'È già in corso un’esportazione.') === $response->data, 'ajax_start changed its answer to a running export.');
        sb_assert($job['job_id'] === get_option(Static_Bridge_Plugin::JOB_OPTION)['job_id'], 'A refused start replaced the running export.');

        // A paused export: 409 with its own message.
        $paused = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $paused['status'] = 'paused';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $paused;
        $refused = sb_private($plugin, 'start_export', array('admin'));
        sb_assert(is_wp_error($refused) && 'static_bridge_export_paused' === $refused->get_error_code() && 409 === $refused->get_error_data()['status'], 'A paused export was not refused with 409.');
        $response = $ajax();
        sb_assert($response instanceof SB_Test_Response && 409 === $response->status && $refused->get_error_message() === $response->data['message'], 'ajax_start changed its answer to a paused export.');

        // The queue table cannot be installed: 500 and the same Attività row.
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $prefix = $GLOBALS['wpdb']->prefix;
        $GLOBALS['wpdb']->prefix = 'wp_;DROP_';
        try {
            $refused = sb_private($plugin, 'start_export', array('cli', false));
            $response = $ajax();
        } finally {
            $GLOBALS['wpdb']->prefix = $prefix;
        }
        sb_assert(is_wp_error($refused) && 'static_bridge_export_queue_unavailable' === $refused->get_error_code() && 500 === $refused->get_error_data()['status'], 'A queue that cannot be installed was not refused with 500.');
        sb_assert($response instanceof SB_Test_Response && 500 === $response->status && $refused->get_error_message() === $response->data['message'], 'ajax_start changed its answer to a queue that cannot be installed.');
        sb_assert(2 === count(array_filter(sb_group_c_activity(), function ($row) {
            return 0 === strpos($row, 'Avvio esportazione non riuscito. | Impossibile predisporre la coda indicizzata') && false !== strpos($row, '| error');
        })), 'The refused start did not write its error in Attività once per call.');
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]), 'A refused start saved a job.');

        // SSI fragments on and the release not prepared: 409, nothing started.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['shared_header_fragments'] = 1;
        $GLOBALS['sb_test_options']['static_bridge_ssi_safe_release'] = 'another-release';
        $refused = sb_private($plugin, 'start_export', array('schedule'));
        sb_assert(is_wp_error($refused) && 'static_bridge_export_ssi_unsafe' === $refused->get_error_code() && 409 === $refused->get_error_data()['status'], 'An unprepared SSI release was not refused with 409.');
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['shared_header_fragments'], $GLOBALS['sb_test_options']['static_bridge_ssi_safe_release']);

        // WP-CLI without --background: the job starts, the background requests are not armed.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION] = array('job_id' => 'old', 'hop' => '', 'lease_until' => 0);
        $GLOBALS['sb_test_http_calls'] = array();
        $job = sb_private($plugin, 'start_export', array('cli', false));
        sb_assert(is_array($job) && 'cli' === $job['started_by'], 'A WP-CLI start did not record its origin.');
        $plugin->send_deferred_export_continuation();
        sb_assert(empty($GLOBALS['sb_test_http_calls']) && 'old' === get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['job_id'],
            'A synchronous WP-CLI start armed the background requests.');
        $unknown = get_option(Static_Bridge_Plugin::JOB_OPTION);
        $unknown['status'] = 'cancelled';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $unknown;
        $job = sb_private($plugin, 'start_export', array('<script>'));
        sb_assert(is_array($job) && 'admin' === $job['started_by'], 'An unknown origin reached the job.');

        $start = sb_method_body($source, 'ajax_start');
        sb_assert(false !== strpos($start, '$this->verify_export_ajax_request();') && strpos($start, 'verify_export_ajax_request') < strpos($start, "start_export('admin')"),
            'ajax_start does not check capability and nonce before starting the export.');
        sb_assert(false === strpos(sb_method_body($source, 'start_export'), 'wp_send_json'), 'start_export answers JSON itself.');
    });
});

sb_test('Export completo pianificato (2.5.0): off by default, strict validation of frequency, time and day, saved from Settings', function () use ($source) {
    sb_group_c_isolated(function ($plugin) use ($source) {
        foreach (array(array('off', 'off'), array('daily', 'daily'), array('weekly', 'weekly'), array('Daily', null), array('monthly', null), array(' daily', null),
            array('', null), array(1, null), array(array('daily'), null), array(null, null)) as $case) {
            sb_assert($case[1] === sb_private($plugin, 'sanitize_scheduled_export_frequency', array($case[0])), 'Frequency not validated: ' . var_export($case[0], true));
        }
        foreach (array(array('03:00', '03:00'), array('00:00', '00:00'), array('23:59', '23:59'), array('24:00', null), array('3:00', null), array('03:60', null),
            array("03:00\n", null), array('03:00:00', null), array('03.00', null), array(300, null), array('', null)) as $case) {
            sb_assert($case[1] === sb_private($plugin, 'sanitize_scheduled_export_time', array($case[0])), 'Time not validated: ' . var_export($case[0], true));
        }
        foreach (array(array(0, 0), array(6, 6), array('1', 1), array('0', 0), array(7, null), array(-1, null), array('7', null), array('01', null), array('1 ', null),
            array(1.0, null), array(true, null), array('lunedì', null)) as $case) {
            sb_assert($case[1] === sb_private($plugin, 'sanitize_scheduled_export_day', array($case[0])), 'Day not validated: ' . var_export($case[0], true));
        }
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array();
        $settings = sb_private($plugin, 'settings');
        sb_assert('off' === $settings['scheduled_export'] && '03:00' === $settings['scheduled_export_time'] && 1 === $settings['scheduled_export_day'],
            'A site without the 2.5.0 schedule settings does not keep the export off, at 03:00 on Monday.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('scheduled_export' => 'hourly', 'scheduled_export_time' => '25:00', 'scheduled_export_day' => 9);
        $settings = sb_private($plugin, 'settings');
        sb_assert('off' === $settings['scheduled_export'] && '03:00' === $settings['scheduled_export_time'] && 1 === $settings['scheduled_export_day'],
            'Stored schedule values are not validated when read.');

        // The Settings form: a valid schedule is saved and scheduled, a forged value keeps the previous one.
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.27.4';
        $save = function ($post) use ($plugin) {
            $_POST = array_merge(array('incremental_enabled' => '1', 'excluded_paths' => ''), $post);
            try {
                $plugin->save_settings();
            } catch (SB_Test_Response $response) {
                return $response;
            }
            return null;
        };
        try {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1);
            $GLOBALS['sb_test_timezone'] = 'Europe/Rome';
            $response = $save(array('scheduled_export' => 'weekly', 'scheduled_export_time' => '04:30', 'scheduled_export_day' => '0'));
            $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
            sb_assert($response instanceof SB_Test_Response && 302 === $response->status, 'The Settings form did not redirect after saving.');
            sb_assert('weekly' === $stored['scheduled_export'] && '04:30' === $stored['scheduled_export_time'] && 0 === $stored['scheduled_export_day'], 'A valid schedule was not saved.');
            $next = wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK);
            $local = (new DateTimeImmutable('@' . (int) $next))->setTimezone(new DateTimeZone('Europe/Rome'));
            sb_assert(is_int($next) && $next > time() && $next <= time() + 7 * DAY_IN_SECONDS && '0 04:30' === $local->format('w H:i'), 'Saving a weekly schedule did not schedule the next Sunday 04:30 of the site.');
            sb_assert(!empty(array_filter(sb_group_c_activity(), function ($row) {
                return 0 === strpos($row, 'Export completo pianificato: il prossimo parte il ');
            })), 'Turning the schedule on is not in Attività.');

            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $save(array('scheduled_export' => 'hourly', 'scheduled_export_time' => '04:30; rm -rf /', 'scheduled_export_day' => '9'));
            $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
            sb_assert('weekly' === $stored['scheduled_export'] && '04:30' === $stored['scheduled_export_time'] && 0 === $stored['scheduled_export_day'], 'A forged schedule replaced the previous valid one.');
            sb_assert(!empty(array_filter(sb_group_c_activity(), function ($row) {
                return 0 === strpos($row, 'Pianificazione dell’export completo non valida; è stato mantenuto il valore precedente.') && false !== strpos($row, '| error');
            })), 'A forged schedule is not reported in Attività.');
            sb_assert(is_int(wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK)), 'A forged schedule removed the valid event.');

            // Turning it off removes the single event.
            $save(array('scheduled_export' => 'off', 'scheduled_export_time' => '04:30', 'scheduled_export_day' => '0'));
            sb_assert(false === wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK), 'Turning the schedule off left its event.');
            sb_assert(!empty(array_filter(sb_group_c_activity(), function ($row) {
                return 0 === strpos($row, 'Export completo pianificato disattivato.');
            })), 'Turning the schedule off is not in Attività.');
        } finally {
            unset($_SERVER['SERVER_SOFTWARE']);
        }
        sb_assert(false !== strpos($source, 'name="scheduled_export"') && false !== strpos($source, 'name="scheduled_export_time"') && false !== strpos($source, 'name="scheduled_export_day"'),
            'The Settings tab lacks the schedule fields.');
    });
});

sb_test('Export completo pianificato (2.5.0): the next time, daily and weekly, stays at the wall-clock time across daylight saving time', function () {
    sb_group_c_isolated(function ($plugin) {
        $GLOBALS['sb_test_timezone'] = 'Europe/Rome';
        $at = function ($local) {
            return (new DateTimeImmutable($local, new DateTimeZone('Europe/Rome')))->getTimestamp();
        };
        $next = function ($frequency, $time, $day, $now) use ($plugin) {
            return sb_private($plugin, 'next_scheduled_export_time', array(array('scheduled_export' => $frequency, 'scheduled_export_time' => $time, 'scheduled_export_day' => $day), $now));
        };
        $daily = array(
            // Later today, then tomorrow; an export due right now goes to the next day.
            array('2026-11-12 02:00', '2026-11-12 03:00'),
            array('2026-11-12 03:00', '2026-11-13 03:00'),
            array('2026-11-12 10:00', '2026-11-13 03:00'),
            // Spring forward (29 March 2026): 03:00 CEST comes 22 hours after 04:00 CET, not 86400 seconds.
            array('2026-03-28 04:00', '2026-03-29 03:00'),
            // Fall back (25 October 2026): 03:00 CET comes 25 hours after 03:00 CEST.
            array('2026-10-24 03:00', '2026-10-25 03:00'),
        );
        foreach ($daily as $case) {
            sb_assert($at($case[1]) === $next('daily', '03:00', 1, $at($case[0])), 'Daily export after ' . $case[0] . ' is not at ' . $case[1] . ' of the site.');
        }
        sb_assert(22 * 3600 === $next('daily', '03:00', 1, $at('2026-03-28 04:00')) - $at('2026-03-28 04:00')
            && 25 * 3600 === $next('daily', '03:00', 1, $at('2026-10-24 03:00')) - $at('2026-10-24 03:00'), 'The daily export moved with daylight saving time.');
        // 02:30 does not exist on 29 March: PHP moves it forward one hour, and the day after it is 02:30 again.
        sb_assert($at('2026-03-29 03:30') === $next('daily', '02:30', 1, $at('2026-03-28 12:00'))
            && $at('2026-03-30 02:30') === $next('daily', '02:30', 1, $at('2026-03-29 12:00')), 'A time missing at the change of time broke the next days.');
        $weekly = array(
            // Wednesday 11 November 2026 → Monday 16; Monday before the time → the same day; at the time → next Monday.
            array(1, '2026-11-11 10:00', '2026-11-16 03:00'),
            array(1, '2026-11-16 02:59', '2026-11-16 03:00'),
            array(1, '2026-11-16 03:00', '2026-11-23 03:00'),
            // Sunday across the spring change.
            array(0, '2026-03-22 05:00', '2026-03-29 03:00'),
            array(6, '2026-10-24 03:00', '2026-10-31 03:00'),
        );
        foreach ($weekly as $case) {
            sb_assert($at($case[2]) === $next('weekly', '03:00', $case[0], $at($case[1])), 'Weekly export (day ' . $case[0] . ') after ' . $case[1] . ' is not at ' . $case[2] . '.');
        }
        sb_assert(0 === $next('off', '03:00', 1, time()) && 0 === $next('hourly', '03:00', 1, time()), 'An export that is off has a next time.');
        $GLOBALS['sb_test_timezone'] = 'UTC';
        sb_assert(gmmktime(3, 0, 0, 11, 13, 2026) === $next('daily', '03:00', 1, gmmktime(9, 0, 0, 11, 12, 2026)), 'The site time zone is not used.');
    });
});

sb_test('Export completo pianificato (2.5.0): a run skips a running or paused export, starts otherwise, reports a refused start and always schedules the next run', function () {
    sb_group_c_isolated(function ($plugin) {
        $hook = Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'scheduled_export' => 'daily', 'scheduled_export_time' => '03:00', 'failure_email' => 1);
        $GLOBALS['sb_test_options']['admin_email'] = 'admin@example.test';
        $expected_next = function () use ($plugin) {
            return sb_private($plugin, 'next_scheduled_export_time', array(sb_private($plugin, 'settings')));
        };

        // Nothing running: the run starts an export from the schedule.
        $plugin->run_scheduled_export();
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION);
        sb_assert(is_array($job) && 'running' === $job['status'] && 'schedule' === $job['started_by'], 'The scheduled run did not start an export.');
        sb_assert($expected_next() === wp_next_scheduled($hook), 'The scheduled run did not schedule the next one.');

        // An export runs: the run is skipped, the export is untouched, the next run is scheduled.
        unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $plugin->run_scheduled_export();
        sb_assert($job === get_option(Static_Bridge_Plugin::JOB_OPTION), 'A scheduled run touched the running export.');
        sb_assert(array('Export pianificato saltato: è già in corso un’esportazione. | L’export in corso pubblicherà una versione nuova; il prossimo export pianificato resta in calendario.') === sb_group_c_activity(),
            'The skipped run is not in Attività as a skip: ' . implode(' / ', sb_group_c_activity()));
        sb_assert($expected_next() === wp_next_scheduled($hook), 'A skipped run did not schedule the next one.');

        // A paused export: skipped, in red, the paused job kept.
        $paused = $job;
        $paused['status'] = 'paused';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $paused;
        unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $plugin->run_scheduled_export();
        sb_assert($paused === get_option(Static_Bridge_Plugin::JOB_OPTION), 'A scheduled run replaced a paused export.');
        $rows = sb_group_c_activity();
        sb_assert(1 === count($rows) && 0 === strpos($rows[0], 'Export pianificato saltato: c’è un’esportazione in pausa.') && false !== strpos($rows[0], '| error'), 'The skip over a paused export is not in Attività.');
        sb_assert(is_int(wp_next_scheduled($hook)) && empty($GLOBALS['sb_test_mails']), 'A skip sent an e-mail or did not schedule the next run.');

        // A running export that is no longer alive (its staging is gone) is closed as from the Generate tab, then replaced.
        $dead = $job;
        $dead['status'] = 'running';
        $dead['stage'] = WP_CONTENT_DIR . '/static-bridge/releases/gone-' . bin2hex(random_bytes(3));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $dead;
        $plugin->run_scheduled_export();
        $new = get_option(Static_Bridge_Plugin::JOB_OPTION);
        sb_assert('running' === $new['status'] && $new['job_id'] !== $dead['job_id'] && !empty(array_filter(sb_group_c_activity(), function ($row) {
            return 0 === strpos($row, 'Sessione di esportazione incompleta chiusa.');
        })), 'A stale running export blocked the scheduled run or was not closed first.');

        // A refused start (queue table unavailable): in Attività, one e-mail «pianificato non avviato», next run scheduled.
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION], $GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $prefix = $GLOBALS['wpdb']->prefix;
        $GLOBALS['wpdb']->prefix = 'wp_;DROP_';
        try {
            $plugin->run_scheduled_export();
            $plugin->run_scheduled_export();
        } finally {
            $GLOBALS['wpdb']->prefix = $prefix;
        }
        sb_assert(2 === count(array_filter(sb_group_c_activity(), function ($row) {
            return 0 === strpos($row, 'Export pianificato non avviato. | Impossibile predisporre la coda indicizzata') && false !== strpos($row, '| error');
        })), 'A refused scheduled start is not in Attività.');
        sb_assert(1 === count($GLOBALS['sb_test_mails']) && false !== strpos($GLOBALS['sb_test_mails'][0]['subject'], 'export completo pianificato non avviato')
            && 'schedule' === get_option(Static_Bridge_Plugin::FAILURE_NOTICE_OPTION)['what'], 'A refused scheduled start did not send one e-mail.');
        sb_assert($expected_next() === wp_next_scheduled($hook), 'A refused start did not schedule the next run.');

        // Turned off meanwhile: the run does nothing and removes its event.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['scheduled_export'] = 'off';
        $plugin->run_scheduled_export();
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]) && false === wp_next_scheduled($hook), 'A run with the schedule off started an export or kept its event.');
    });
});

sb_test('Export completo pianificato (2.5.0): one single event, registered, removed on deactivation and uninstall, back on activation only when on', function () use ($source, $plugin) {
    $registered = false;
    foreach ($GLOBALS['sb_test_hooks'] as $hook) {
        $registered = $registered || (Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK === $hook[0] && is_array($hook[1]) && 'run_scheduled_export' === $hook[1][1]);
    }
    sb_assert($registered && 'static_bridge_scheduled_export' === Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK, 'The scheduled export event has no callback.');
    sb_assert(false === strpos($source, 'wp_schedule_event('), 'A recurring WP-Cron event was added.');
    sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), 'wp_clear_scheduled_hook(self::SCHEDULED_EXPORT_HOOK)'), 'Deactivation keeps the scheduled export.');
    sb_assert(false !== strpos(sb_method_body($source, 'activate'), '$plugin->schedule_scheduled_export();'), 'Activation does not schedule the export again.');
    sb_assert(in_array(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK, Static_Bridge_Uninstaller::CRON_HOOKS, true), 'Uninstall does not know the scheduled export event.');
    sb_group_c_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('scheduled_export' => 'off');
        $GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK] = time() + 60;
        sb_assert(0 === sb_private($plugin, 'schedule_scheduled_export') && false === wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK), 'An export that is off kept its event.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('scheduled_export' => 'daily');
        $first = sb_private($plugin, 'schedule_scheduled_export');
        $second = sb_private($plugin, 'schedule_scheduled_export');
        sb_assert($first > time() && $first === $second && $second === wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK), 'Scheduling twice did not keep one event at the next time.');
        $GLOBALS['sb_test_scheduled_hooks'] = array(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK => time() + 60);
        $db = new class {
            public $options = 'wp_options';
            public $prefix = 'wp_';
            public function esc_like($text) { return addcslashes((string) $text, '_%\\'); }
            public function prepare($query, ...$args) { return $query; }
            public function get_col($query) { return array(); }
            public function query($query) { return 0; }
        };
        $uninstaller = new Static_Bridge_Uninstaller($db, WP_CONTENT_DIR . '/no-static-root-' . bin2hex(random_bytes(3)), ABSPATH . 'no-htaccess-' . bin2hex(random_bytes(3)));
        $report = $uninstaller->run();
        sb_assert(false === wp_next_scheduled(Static_Bridge_Plugin::SCHEDULED_EXPORT_HOOK) && $report['cron_hooks_cleared'] >= 6, 'Uninstall left the scheduled export event.');
    });
});

// WP-CLI, as far as plugin/cli.php uses it: output collected, error() and halt() end the command like an exit.
class SB_Test_CLI_Exit extends RuntimeException
{
    public $exit_code;

    public function __construct($code, $message = '')
    {
        $this->exit_code = (int) $code;
        parent::__construct((string) $message);
    }
}
if (!class_exists('WP_CLI')) {
    class WP_CLI
    {
        public static $commands = array();
        public static $output = array();
        public static function add_command($name, $callable) { self::$commands[$name] = $callable; return true; }
        public static function line($message = '') { self::$output[] = array('line', (string) $message); }
        public static function log($message) { self::$output[] = array('log', (string) $message); }
        public static function success($message) { self::$output[] = array('success', (string) $message); }
        public static function warning($message) { self::$output[] = array('warning', (string) $message); }
        public static function error($message, $exit = true) { self::$output[] = array('error', (string) $message); throw new SB_Test_CLI_Exit(1, (string) $message); }
        public static function halt($code) { throw new SB_Test_CLI_Exit((int) $code); }
    }
}
if (!function_exists('WP_CLI\\Utils\\format_items')) {
    eval('namespace WP_CLI\\Utils; function format_items($format, $items, $fields) { \\WP_CLI::$output[] = array("table", array("format" => $format, "items" => $items, "fields" => $fields)); }');
}

/** Runs a WP-CLI command method; returns array(exit code, output rows). */
function sb_cli_run($command, $method, $args = array(), $assoc_args = array())
{
    WP_CLI::$output = array();
    $code = 0;
    try {
        $command->$method($args, $assoc_args);
    } catch (SB_Test_CLI_Exit $exit) {
        $code = $exit->exit_code;
    }
    return array($code, WP_CLI::$output);
}

sb_test('WP-CLI (2.5.0): plugin/cli.php loads only under WP-CLI and registers wp static-bridge with English help', function () use ($source, $pluginFile) {
    $cli_file = dirname($pluginFile) . '/cli.php';
    sb_assert(is_readable($cli_file), 'plugin/cli.php is missing.');
    sb_assert(false !== strpos($source, "if (defined('WP_CLI') && WP_CLI && is_readable(__DIR__ . '/cli.php')) {")
        && false !== strpos($source, "Static_Bridge_CLI::register(\$static_bridge_plugin);"), 'cli.php is not loaded only in a WP-CLI process, or not registered.');
    sb_assert(!class_exists('Static_Bridge_CLI', false), 'The WP-CLI module was loaded outside WP-CLI.');
    require_once $cli_file;
    Static_Bridge_CLI::register(new Static_Bridge_Plugin());
    sb_assert(isset(WP_CLI::$commands['static-bridge']) && WP_CLI::$commands['static-bridge'] instanceof Static_Bridge_CLI, 'wp static-bridge was not registered.');
    $reflection = new ReflectionClass('Static_Bridge_CLI');
    $commands = array();
    foreach ($reflection->getMethods(ReflectionMethod::IS_PUBLIC) as $method) {
        if (!$method->isStatic() && 0 !== strpos($method->getName(), '__')) {
            $commands[] = $method->getName();
        }
    }
    sort($commands);
    sb_assert(array('export', 'hand_off_on_shutdown', 'push', 'status') === $commands, 'Unexpected public methods (WP-CLI turns them into subcommands): ' . implode(', ', $commands));
    foreach (array('status' => '[--format=<format>]', 'export' => '[--background]', 'push' => '[--[no-]wait]') as $name => $synopsis) {
        $doc = (string) $reflection->getMethod($name)->getDocComment();
        sb_assert(false !== strpos($doc, $synopsis) && false !== strpos($doc, '## EXAMPLES') && !preg_match('/[àèéìòù]/u', $doc), 'The help of ' . $name . ' is not an English WP-CLI docblock.');
    }
    sb_assert(false !== strpos((string) $reflection->getMethod('push')->getDocComment(), '<id>'), 'push does not take the content ID.');
});

sb_test('WP-CLI (2.5.0): status --format=json and the table say release, last export, incremental queue and next scheduled export', function () {
    sb_group_c_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'scheduled_export' => 'weekly', 'scheduled_export_day' => 3, 'scheduled_export_time' => '05:15');
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('pages' => 42, 'published_at' => 1794500000);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(
            sha1('/a/') => array('url' => home_url('/a/'), 'path' => '/a/', 'attempts' => 0),
            sha1('/b/') => array('url' => home_url('/b/'), 'path' => '/b/', 'attempts' => 3),
        );
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array('queue_version' => 1, 'job_id' => '12345678-1234-4234-8234-cccccccccccc', 'status' => 'failed',
            'started_by' => 'schedule', 'processed' => 9, 'saved' => 7, 'route_errors' => 2, 'started_at' => 1794500000, 'updated_at' => 1794503600,
            'issues' => array(array('url' => '', 'message' => 'Spazio su disco esaurito in ' . WP_CONTENT_DIR . '/static-bridge/releases/x.')));
        $next = sb_private($plugin, 'schedule_scheduled_export');
        $cli = new Static_Bridge_CLI($plugin, function () {});
        list($code, $output) = sb_cli_run($cli, 'status', array(), array('format' => 'json'));
        $status = json_decode($output[0][1] ?? '', true);
        sb_assert(0 === $code && 1 === count($output) && is_array($status), 'status --format=json did not print one JSON document.');
        sb_assert(Static_Bridge_Plugin::VERSION === $status['version'] && basename((string) sb_private($plugin, 'current_release')) === $status['release']['id'] && 42 === $status['release']['pages'],
            'status does not say the release in use.');
        sb_assert('failed' === $status['export']['status'] && 'schedule' === $status['export']['started_by'] && 7 === $status['export']['saved'] && 2 === $status['export']['errors']
            && 1794500000 === $status['export']['started_at'] && 1794503600 === $status['export']['finished_at'], 'status does not say the last export.');
        sb_assert(false === strpos($status['export']['message'], WP_CONTENT_DIR) && false !== strpos($status['export']['message'], 'wp-content/static-bridge/releases/x'), 'status prints a server path.');
        sb_assert(array('enabled' => true, 'items' => 2, 'retrying' => 1, 'wait_until' => 0) === $status['incremental'], 'status does not say the incremental queue.');
        sb_assert(array('frequency' => 'weekly', 'time' => '05:15', 'day' => 3, 'next' => $next) === $status['schedule'] && $next > 0, 'status does not say the next scheduled export.');

        list($code, $output) = sb_cli_run($cli, 'status', array(), array());
        sb_assert(0 === $code && 'table' === $output[0][0] && 'table' === $output[0][1]['format'] && array('field', 'value') === $output[0][1]['fields'] && count($output[0][1]['items']) >= 8,
            'status without --format did not print a table.');
        list($code, $output) = sb_cli_run($cli, 'status', array(), array('format' => 'yaml'));
        sb_assert(1 === $code, 'status accepted an unknown format.');
    });
});

sb_test('WP-CLI (2.5.0): export runs the worker steps in the process, exits 0 only when published, waits for a busy lock, and Ctrl-C hands the export to the background', function () {
    // The command against a plugin double: the exit code and the pauses of each final state.
    $double = new class {
        public $states = array();
        public $started = null;
        public $handed = 0;
        public $start_error = null;
        public function cli_start_export($background) { $this->started = $background; return $this->start_error ?: array('status' => 'running'); }
        public function cli_export_step() { return array_shift($this->states); }
        public function cli_hand_export_to_background() { $this->handed++; return true; }
    };
    $pauses = array();
    $cli = new Static_Bridge_CLI($double, function ($seconds) use (&$pauses) { $pauses[] = $seconds; });
    $double->states = array(
        array('status' => 'running', 'processed' => 1, 'total' => 3, 'pause' => 0),
        array('status' => 'running', 'processed' => 1, 'total' => 3, 'workerBusy' => true, 'pause' => 80),
        array('status' => 'running', 'processed' => 2, 'total' => 3, 'waiting' => 12, 'pause' => 12),
        array('status' => 'complete', 'processed' => 3, 'total' => 3, 'saved' => 3, 'message' => 'Versione pubblicata.'),
    );
    list($code, $output) = sb_cli_run($cli, 'export');
    sb_assert(0 === $code && false === $double->started && array('success', 'Versione pubblicata.') === end($output), 'A published export did not exit 0.');
    sb_assert(array(30, 12) === $pauses, 'The process did not wait for a busy lock (at most 30 s at a time) or for the server.');
    sb_assert(0 === $double->handed, 'A finished export was handed to the background.');
    $cli->hand_off_on_shutdown();
    sb_assert(0 === $double->handed, 'The shutdown of a finished command handed the export to the background.');

    $double->states = array(array('status' => 'running', 'pause' => 0), array('status' => 'failed', 'issues' => array(array('url' => '', 'message' => 'Disco pieno.'))));
    list($code, $output) = sb_cli_run($cli, 'export');
    sb_assert(1 === $code && false !== strpos(end($output)[1], 'failed') && false !== strpos(end($output)[1], 'Disco pieno.'), 'A failed export did not exit 1 with its reason.');

    $double->start_error = new WP_Error('static_bridge_export_running', 'È già in corso un’esportazione.', array('status' => 409));
    list($code, $output) = sb_cli_run($cli, 'export', array(), array('background' => true));
    sb_assert(1 === $code && array('error', 'È già in corso un’esportazione.') === end($output), 'A refused start did not exit 1.');
    $double->start_error = null;
    list($code, $output) = sb_cli_run($cli, 'export', array(), array('background' => true));
    sb_assert(0 === $code && true === $double->started && 'success' === end($output)[0] && array() === $double->states, '--background did more than start the export.');

    // Ctrl-C during a step: after it, the export goes to the background requests and the command exits 1.
    $stopper = new class {
        public $cli;
        public $flag;
        public $steps = 0;
        public $handed = 0;
        public function cli_start_export($background) { return array('status' => 'running'); }
        public function cli_export_step() { $this->steps++; $this->flag->setValue($this->cli, true); return array('status' => 'running', 'pause' => 0); }
        public function cli_hand_export_to_background() { $this->handed++; return true; }
    };
    $stopper->flag = new ReflectionProperty('Static_Bridge_CLI', 'interrupted');
    $stopper->cli = new Static_Bridge_CLI($stopper, function () {});
    list($code, $output) = sb_cli_run($stopper->cli, 'export');
    sb_assert(1 === $code && 1 === $stopper->handed && 1 === $stopper->steps && 'error' === end($output)[0], 'Ctrl-C did not hand the export to the background after the step in progress.');

    // A process that dies while it drives the export (fatal error, exit): the shutdown hands it off once.
    $double->handed = 0;
    $driving = new ReflectionProperty('Static_Bridge_CLI', 'driving');
    $cli = new Static_Bridge_CLI($double, function () {});
    $driving->setValue($cli, true);
    $cli->hand_off_on_shutdown();
    $cli->hand_off_on_shutdown();
    sb_assert(1 === $double->handed, 'The shutdown of a dying export command did not hand the export off exactly once.');
});

sb_test('WP-CLI (2.5.0): the synchronous export holds the background lease, so the chain never works with it, and publishes in the process', function () {
    sb_group_c_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'export_archives' => 0);
        $previous_types = $GLOBALS['sb_test_post_types'];
        $previous_count = $GLOBALS['sb_test_generated_post_count'];
        $GLOBALS['sb_test_post_types'] = array();
        $GLOBALS['sb_test_generated_post_count'] = 0;
        $GLOBALS['sb_test_http_responses'] = array(
            home_url('/') . '?static_bridge_bypass=1' => array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body><p>Home CLI</p></body></html>'),
        );
        try {
            $started = $plugin->cli_start_export(false);
            $job = get_option(Static_Bridge_Plugin::JOB_OPTION);
            $continue = get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION);
            sb_assert('running' === $started['status'] && 'cli' === $job['started_by'], 'cli_start_export did not start an export from WP-CLI.');
            sb_assert($job['job_id'] === $continue['job_id'] && '' === $continue['hop'] && $continue['lease_until'] > time(), 'The synchronous export does not hold the lease of the background requests.');
            // While the shell holds the lease: no tick of the Generate tab, WP-Cron or stalled notice starts a chain.
            sb_assert(false === sb_private($plugin, 'send_export_continuation', array(false)) && empty($GLOBALS['sb_test_http_calls']), 'A background chain started while WP-CLI runs the export.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION]['lease_until'] = time() - 1;
            $_POST = array('token' => str_repeat('0', 64));
            try {
                $plugin->ajax_export_continue();
                $answer = null;
            } catch (SB_Test_Response $response) {
                $answer = $response;
            }
            sb_assert($answer instanceof SB_Test_Response && 403 === $answer->status, 'A background request was accepted while WP-CLI held the lease.');

            // Another request holds the worker lock: the step waits for it, and renews the lease.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EXPORT_LOCK_OPTION] = array('token' => 'other', 'expires' => time() + 40);
            $busy = $plugin->cli_export_step();
            sb_assert(!empty($busy['workerBusy']) && $busy['pause'] >= 40 && $busy['pause'] <= 42 && 0 === $busy['processed'], 'A busy worker lock was not reported with its wait.');
            sb_assert(get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['lease_until'] > time(), 'The step did not renew the lease.');
            delete_option(Static_Bridge_Plugin::EXPORT_LOCK_OPTION);

            $cli = new Static_Bridge_CLI($plugin, function () {});
            WP_CLI::$output = array();
            $code = 0;
            try {
                sb_private($cli, 'drive_export');
            } catch (SB_Test_CLI_Exit $exit) {
                $code = $exit->exit_code;
            }
            $done = get_option(Static_Bridge_Plugin::JOB_OPTION);
            sb_assert(0 === $code && 'complete' === $done['status'] && 'success' === end(WP_CLI::$output)[0], 'The synchronous export did not publish with exit 0: ' . json_encode(WP_CLI::$output));
            sb_assert(is_file($done['stage'] . '/index.html') && realpath(WP_CONTENT_DIR . '/static-bridge/current') === realpath($done['stage']), 'The release published from WP-CLI is not online.');
            sb_assert(empty($GLOBALS['sb_test_http_calls']) || empty(array_filter($GLOBALS['sb_test_http_calls'], function ($call) {
                return Static_Bridge_Plugin::EXPORT_CONTINUE_ACTION === ($call['args']['body']['action'] ?? '');
            })), 'The synchronous export sent background requests.');

            // Handing a running export to the background arms a fresh chain.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array_merge($done, array('status' => 'running'));
            sb_assert(true === $plugin->cli_hand_export_to_background(), 'A running export was not handed to the background.');
            $sent = array_values(array_filter($GLOBALS['sb_test_http_calls'], function ($call) {
                return Static_Bridge_Plugin::EXPORT_CONTINUE_ACTION === ($call['args']['body']['action'] ?? '');
            }));
            sb_assert(1 === count($sent) && hash_equals(get_option(Static_Bridge_Plugin::EXPORT_CONTINUE_OPTION)['hop'], $sent[0]['args']['body']['token'])
                && is_int(wp_next_scheduled('static_bridge_process_export_queue')), 'The handed-off export has no background request or WP-Cron worker.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]['status'] = 'complete';
            sb_assert(false === $plugin->cli_hand_export_to_background(), 'A finished export was handed to the background.');
        } finally {
            $GLOBALS['sb_test_post_types'] = $previous_types;
            $GLOBALS['sb_test_generated_post_count'] = $previous_count;
        }
    });
});

sb_test('WP-CLI (2.5.0): push publishes one content with the checks of the editor (not the push filter), waits for the result, exits 1 when it fails', function () {
    sb_group_c_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1, 'excluded_paths' => array('/riservata/'));
        $previous = array($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_filter_callbacks'] ?? array());
        $GLOBALS['sb_test_post_types'] = array('page' => array('public' => true));
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 501, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_name' => 'cli-pagina'),
            array('ID' => 502, 'post_type' => 'page', 'post_status' => 'draft', 'post_password' => '', 'post_name' => 'cli-bozza'),
            array('ID' => 503, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_name' => 'riservata'),
        );
        $GLOBALS['sb_test_post_urls'] = array(501 => home_url('/cli-pagina/'), 502 => home_url('/?page_id=502'), 503 => home_url('/riservata/'));
        // Nobody may push from the editor: the shell is trusted, the filter does not apply.
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_can_push_post'] = function () { return false; };
        $GLOBALS['sb_test_http_responses'][home_url('/cli-pagina/') . '?static_bridge_bypass=1'] = array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html'), 'body' => '<html><body>Pagina CLI</body></html>');
        $cli = new Static_Bridge_CLI($plugin, function () {});
        try {
            list($code, $output) = sb_cli_run($cli, 'push', array('501'));
            sb_assert(0 === $code && 'success' === end($output)[0] && false !== strpos(end($output)[1], '/cli-pagina/'), 'A push of a published page did not exit 0: ' . json_encode($output));
            sb_assert(is_file(sb_private($plugin, 'current_release') . '/cli-pagina/index.html'), 'The pushed page was not written to the release.');

            foreach (array(array('502', 'Il push è disponibile solo per contenuti pubblicati'), array('503', 'escluso o dinamico'), array('999', 'non è disponibile'), array('abc', 'ID contenuto valido'), array('0', 'ID contenuto valido')) as $case) {
                list($code, $output) = sb_cli_run($cli, 'push', array($case[0]));
                sb_assert(1 === $code && false !== strpos(end($output)[1], $case[1]), 'push ' . $case[0] . ' did not exit 1 with its reason: ' . json_encode($output));
            }

            // A render that fails: the push is retried by the queue; --no-wait only queues, waiting ends with exit 1 at the timeout.
            $GLOBALS['sb_test_http_responses'][home_url('/cli-pagina/') . '?static_bridge_bypass=1'] = array('response' => array('code' => 500), 'headers' => array(), 'body' => 'Errore');
            list($code, $output) = sb_cli_run($cli, 'push', array('501'), array('wait' => false));
            sb_assert(0 === $code && 'success' === end($output)[0] && false !== strpos(end($output)[1], 'in coda'), '--no-wait did not just queue the push: ' . json_encode($output));
            list($code, $output) = sb_cli_run($cli, 'push', array('501'), array('timeout' => '0'));
            sb_assert(1 === $code && false !== strpos(end($output)[1], 'non è concluso dopo 0 secondi'), 'A push still in retry at the timeout did not exit 1: ' . json_encode($output));

            $record = $plugin->cli_push_post(501);
            sb_assert(is_array($record) && $plugin->cli_push_status($record['token'])['status'] === $record['status'], 'cli_push_status does not read the state of the push.');
        } finally {
            list($GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_filter_callbacks']) = $previous;
        }
    });
});

sb_test('WP-CLI (2.5.0): push waits for the state of the push, runs a due retry in the process, and exits 1 on failed', function () {
    $double = new class {
        public $states = array();
        public $reads = 0;
        public function cli_push_post($post_id) { return array('token' => 'tok', 'path' => '/p/', 'status' => 'retrying', 'last_error' => ''); }
        public function cli_push_status($token) { $this->reads++; return array_shift($this->states) ?: array('status' => 'retrying', 'last_error' => ''); }
    };
    $hook = 'static_bridge_process_incremental_queue';
    $previous_hooks = $GLOBALS['sb_test_scheduled_hooks'];
    $previous_callbacks = $GLOBALS['sb_test_action_callbacks'] ?? array();
    $ran = 0;
    $GLOBALS['sb_test_action_callbacks'][$hook] = function () use (&$ran) { $ran++; };
    try {
        $GLOBALS['sb_test_scheduled_hooks'][$hook] = time() - 1;
        $double->states = array(array('status' => 'retrying', 'last_error' => ''), array('status' => 'retrying', 'last_error' => ''), array('status' => 'completed', 'last_error' => ''));
        $pauses = 0;
        $cli = new Static_Bridge_CLI($double, function () use (&$pauses) { $pauses++; });
        list($code, $output) = sb_cli_run($cli, 'push', array('7'));
        sb_assert(0 === $code && 'success' === end($output)[0] && 1 === $pauses, 'A push completed after a retry did not exit 0.');
        sb_assert(1 === $ran && false === wp_next_scheduled($hook), 'The due incremental worker did not run in the WP-CLI process.');

        $double->states = array(array('status' => 'failed', 'last_error' => 'HTTP 500 dal rendering.'));
        list($code, $output) = sb_cli_run($cli, 'push', array('7'));
        sb_assert(1 === $code && 'Push non completato: HTTP 500 dal rendering.' === end($output)[1], 'A failed push did not exit 1 with the error of the editor.');
        sb_assert(1 === $ran, 'The incremental worker ran without being due.');
    } finally {
        $GLOBALS['sb_test_scheduled_hooks'] = $previous_hooks;
        $GLOBALS['sb_test_action_callbacks'] = $previous_callbacks;
    }
});

// 2.5.0, group D: the link check after a publication with Strict. A static root of its own, moved back afterwards.
function sb_link_check_isolated($fixtureRoot, callable $callback)
{
    $root = WP_CONTENT_DIR . '/static-bridge';
    $saved = $fixtureRoot . '/static-bridge-saved-for-link-check-' . bin2hex(random_bytes(4));
    $outside = $fixtureRoot . '/link-check-outside-' . bin2hex(random_bytes(4));
    if ((file_exists($root) || is_link($root)) && !rename($root, $saved)) {
        throw new RuntimeException('Could not move the shared static-bridge fixture aside.');
    }
    try {
        sb_assert(wp_mkdir_p($root . '/releases') && wp_mkdir_p($outside), 'Could not create the link check fixture.');
        sb_group_c_isolated(function ($plugin) use ($callback, $root, $outside) {
            unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::LINK_CHECK_OPTION], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::LINK_CHECK_LOCK],
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION]);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 1, 'incremental_enabled' => 1, 'excluded_paths' => array('/esclusa/'));
            $callback($plugin, $root, $outside);
        });
    } finally {
        sb_retention_remove_tree($root);
        sb_retention_remove_tree($outside);
        if (file_exists($saved) || is_link($saved)) {
            rename($saved, $root);
        }
    }
}

/** A release of pages (route => HTML), current or not, in the isolated static root. */
function sb_link_check_release($root, $id, array $pages, $current = true)
{
    foreach ($pages as $route => $html) {
        $directory = rtrim($root . '/releases/' . $id . '/' . trim($route, '/'), '/');
        sb_assert(wp_mkdir_p($directory) && false !== file_put_contents($directory . '/index.html', $html), 'Could not seed ' . $route);
    }
    if ($current) {
        sb_retention_point_current($root, $id);
    }
    return $root . '/releases/' . $id;
}

/** Every file of a tree with its hash: what a check that changes nothing leaves identical. */
function sb_link_check_listing($directory)
{
    $listing = array();
    $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);
    foreach ($iterator as $file) {
        $listing[substr($file->getPathname(), strlen($directory))] = $file->isLink() ? 'link:' . readlink($file->getPathname()) : ($file->isFile() ? sha1_file($file->getPathname()) : 'dir');
    }
    ksort($listing);
    return $listing;
}

sb_test('Link check (2.5.0): only a linked route without a copy that the server rules do not send to WP is reported, with the pages that link it; nothing else changes', function () use ($fixtureRoot) {
    sb_link_check_isolated($fixtureRoot, function ($plugin, $root) {
        $home = '<!doctype html><html><body>'
            . '<a href="/con-copia/">con copia</a>'
            . '<a href="/senza-copia/">senza copia</a>'
            . '<a href="/senza-copia#sezione">stessa rotta senza barra e con frammento</a>'
            . '<a href="/esclusa/">esclusa</a><a href="/ESCLUSA/sotto/">esclusa, maiuscole e sotto</a>'
            . '<a href="/dall-editor/">esclusa dalla casella dell’editor</a>'
            . '<a href="/in-coda/">in coda incrementale, ancora senza file</a>'
            . '<a href="/vecchia/">reindirizzata da un altro plugin</a>'
            . '<a href="/documento.pdf">file</a><a href="/wp-content/uploads/foto.jpg">file</a>'
            . '<a href="/senza-copia-con-query/?pagina=2">query</a>'
            . '<a href="https://altro.example.org/senza-copia-esterna/">esterno</a>'
            . '<a href="//news.example.test:8443/con-copia/">stesso sito senza schema</a>'
            . '<a href="/feed/">feed</a><a href="/wp-admin/">admin</a><a href="/search/parola/">ricerca</a><a href="/.well-known/security.txt">well-known</a>'
            . '<a href="#top">frammento</a><a href="mailto:redazione@example.test">mail</a><a>senza href</a>'
            . '</body></html>';
        $page = '<!doctype html><html><body><a href="figlia/">relativo</a>'
            . '<map name="m"><area href="/senza-copia/" alt="mappa"></map>'
            . '<a href="../senza-copia/">relativo con ..</a></body></html>';
        $release = sb_link_check_release($root, 'r-links', array(
            '/' => $home,
            '/con-copia/' => $page,
            '/con-copia/figlia/' => '<!doctype html><a href="/">home</a><a href="/con-copia/">su</a>',
            '/esclusa/' => '<!doctype html><a href="/senza-copia/">la pagina esclusa non conta: il server la manda a WP</a>',
        ));
        // /esclusa/ still has a file, but the rules send it to WP: no visitor sees that copy, so its links do not count.
        sb_assert(false !== file_put_contents($root . '/.strict', ''), 'Could not create the Strict marker.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::EDITOR_EXCLUDED_OPTION] = array('15' => array('/dall-editor/'));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(
            sha1(home_url('/in-coda/')) => array('url' => home_url('/in-coda/'), 'path' => '/in-coda/', 'action' => 'refresh', 'attempts' => 0),
        );
        $GLOBALS['sb_test_filter_values']['static_bridge_redirects'] = array('/vecchia/' => array('to' => '/con-copia/', 'status' => 301));
        $settings_before = $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION];
        $files_before = sb_link_check_listing($root);
        $rules_before = sb_private($plugin, 'rewrite_block');
        $GLOBALS['sb_test_http_calls'] = array();

        sb_assert('queued' === sb_private($plugin, 'schedule_link_check', array(Static_Bridge_Plugin::LINK_CHECK_DELAY)), 'A check was not scheduled with Strict on.');
        $when = wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK);
        sb_assert($when >= time() + 55 && 'static_bridge_link_check' === Static_Bridge_Plugin::LINK_CHECK_HOOK, 'The check was not scheduled in its own later request.');
        unset($GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::LINK_CHECK_HOOK]);
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        sb_assert('complete' === $report['status'] && 'r-links' === $report['release'] && 4 === $report['pages'], 'The check did not read the four pages of the release: ' . json_encode($report));
        sb_assert(1 === $report['total'] && array('/senza-copia/' => array('/', '/con-copia/')) === $report['broken'],
            'The report is not the one route without a copy and its pages: ' . json_encode($report['broken']));
        sb_assert(false === wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK), 'A finished check scheduled another chunk.');
        $activity = sb_group_c_activity();
        sb_assert(false !== strpos((string) end($activity), 'Controllo dei link: 1 rotta linkata senza copia statica risponde 404. | Versione r-links: 4 pagine lette.')
            && false !== strpos((string) end($activity), '| error'), 'Attività has no error row for the broken link: ' . json_encode($activity));
        sb_assert(array() === $GLOBALS['sb_test_http_calls'], 'The check sent HTTP requests.');
        $with_dom = sb_private($plugin, 'html_link_hrefs', array($page, false, true));
        $with_regex = sb_private($plugin, 'html_link_hrefs', array($page, true, true));
        sort($with_dom);
        sort($with_regex);
        sb_assert(array('../senza-copia/', '/senza-copia/', 'figlia/') === $with_dom && $with_dom === $with_regex,
            'The links of a page, <area> included, differ with and without ext-dom.');
        sb_assert($files_before === sb_link_check_listing($root) && $settings_before === $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]
            && $rules_before === sb_private($plugin, 'rewrite_block'), 'The check changed the release, the settings or the rules.');
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::LINK_CHECK_LOCK]), 'The check left its lock.');

        // The same rules as the server: with the exclusion removed, the routes of /esclusa/ are routes again.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array();
        sb_private($plugin, 'schedule_link_check', array(0));
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        sb_assert(array('/senza-copia/', '/ESCLUSA/sotto/') === array_keys($report['broken']) && 2 === $report['total']
            && array('/', '/con-copia/', '/esclusa/') === $report['broken']['/senza-copia/'],
            'Without the manual exclusion the report does not follow the rules: ' . json_encode(array_keys($report['broken'])));

        // Once the route has a copy the check is clean, and Attività says so without an error.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array('/esclusa/');
        sb_assert(wp_mkdir_p($release . '/senza-copia') && false !== file_put_contents($release . '/senza-copia/index.html', '<!doctype html>'), 'Could not add the missing copy.');
        sb_private($plugin, 'schedule_link_check', array(0));
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $activity = sb_group_c_activity();
        sb_assert('complete' === $report['status'] && 0 === $report['total'] && array() === $report['broken'] && 5 === $report['pages']
            && false !== strpos((string) end($activity), 'Controllo dei link completato') && false === strpos((string) end($activity), '| error'), 'A clean check is not reported as clean.');
    });
});

sb_test('Link check (2.5.0): Strict off schedules nothing, publish_release schedules it after Strict is synced, a check of a release no longer current stops', function () use ($fixtureRoot, $source) {
    $publish = sb_method_body($source, 'publish_release');
    $synced = strpos($publish, 'sync_strict_marker(');
    $scheduled = strpos($publish, '$this->schedule_link_check(self::LINK_CHECK_DELAY);');
    sb_assert(false !== $synced && false !== $scheduled && $synced < $scheduled, 'publish_release does not schedule the link check after the Strict marker.');
    sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), 'wp_clear_scheduled_hook(self::LINK_CHECK_HOOK)')
        && in_array(Static_Bridge_Plugin::LINK_CHECK_HOOK, Static_Bridge_Uninstaller::CRON_HOOKS, true)
        && in_array(Static_Bridge_Plugin::LINK_CHECK_OPTION, Static_Bridge_Uninstaller::OPTIONS, true), 'Deactivation or uninstall does not know the link check.');
    $registered = false;
    foreach ($GLOBALS['sb_test_hooks'] as $hook) {
        $registered = $registered || (Static_Bridge_Plugin::LINK_CHECK_HOOK === $hook[0] && is_array($hook[1]) && 'run_link_check' === $hook[1][1]);
    }
    sb_assert($registered, 'The link check event has no callback.');
    sb_link_check_isolated($fixtureRoot, function ($plugin, $root) {
        sb_link_check_release($root, 'r-old', array('/' => '<a href="/manca/">x</a>'));
        // Strict saved but not applied (no marker): no check.
        sb_assert('strict_off' === sb_private($plugin, 'schedule_link_check', array(60)) && false === wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK)
            && false === get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION), 'A check was scheduled without the .strict marker.');
        sb_assert(false !== file_put_contents($root . '/.strict', ''), 'Could not create the Strict marker.');
        sb_assert('queued' === sb_private($plugin, 'schedule_link_check', array(60)), 'No check with the marker.');
        // A publication with Strict now off stops the waiting check and schedules nothing.
        unlink($root . '/.strict');
        sb_assert('strict_off' === sb_private($plugin, 'schedule_link_check', array(60)) && false === wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK)
            && 'stopped' === get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION)['status'], 'Strict off did not stop the waiting check.');

        // A check in progress on a release that is no longer the current one stops, without another chunk.
        file_put_contents($root . '/.strict', '');
        sb_private($plugin, 'schedule_link_check', array(0));
        unset($GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::LINK_CHECK_HOOK]);
        $running = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $running['status'] = 'running';
        $running['cursor'] = array();
        update_option(Static_Bridge_Plugin::LINK_CHECK_OPTION, $running, false);
        sb_link_check_release($root, 'r-new', array('/' => '<a href="/manca-ancora/">x</a>'));
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $activity = sb_group_c_activity();
        sb_assert('stopped' === $report['status'] && 'release_changed' === $report['reason'] && 'r-old' === $report['release'] && 0 === (int) $report['pages']
            && false === wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK), 'A check of a release no longer current went on: ' . json_encode($report));
        sb_assert(false !== strpos((string) end($activity), 'Controllo dei link fermato prima della fine.') && false === strpos((string) end($activity), '| error'), 'The stop is not in Attività.');
        // The marker removed during a check stops it too.
        sb_private($plugin, 'schedule_link_check', array(0));
        unlink($root . '/.strict');
        $plugin->run_link_check();
        sb_assert('strict_off' === get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION)['reason'], 'A check went on after Strict was turned off.');
    });
});

sb_test('Link check (2.5.0): a large release is read in chunks that resume from the cursor, inside the release, never through a symlink', function () use ($fixtureRoot) {
    sb_link_check_isolated($fixtureRoot, function ($plugin, $root, $outside) {
        $pages = array('/' => '<a href="/manca-home/">x</a>', '/a/' => '<a href="/manca-a/">x</a>', '/a/b/' => '<a href="/manca-a-b/">x</a>',
            '/a-b/' => '<a href="/manca-a-trattino-b/">x</a>', '/b/' => '<a href="/manca-b/">x</a>', '/10/' => '<a href="/manca-10/">x</a>', '/9/' => '<a href="/manca-9/">x</a>');
        for ($i = 0; $i < 200; $i++) {
            $pages[sprintf('/p%03d/', $i)] = sprintf('<a href="/manca-%03d/">x</a>', $i);
        }
        $release = sb_link_check_release($root, 'r-big', $pages);
        file_put_contents($root . '/.strict', '');
        // A folder and a page that are symlinks to files outside the release are never read.
        file_put_contents($outside . '/index.html', '<a href="/manca-fuori/">x</a>');
        sb_assert(symlink($outside, $release . '/fuori') && wp_mkdir_p($release . '/finta') && symlink($outside . '/index.html', $release . '/finta/index.html'), 'Could not create the symlinks.');
        $expected = count($pages);

        // Small chunks: every page once, in order, whatever the chunk size.
        sb_private($plugin, 'schedule_link_check', array(0));
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $cursors = array();
        for ($chunk = 0; $chunk < 200 && 'complete' !== $report['status']; $chunk++) {
            $report = sb_private($plugin, 'link_check_step', array($report, 3));
            sb_assert(in_array($report['status'], array('running', 'complete'), true), 'A chunk stopped the check.');
            $cursors[] = $report['cursor'];
            if (0 === $chunk) {
                // A page written before the cursor during the check: the next chunks go on from the cursor.
                sb_assert(array('9') === $report['cursor'] && wp_mkdir_p($release . '/0-nuova')
                    && false !== file_put_contents($release . '/0-nuova/index.html', '<a href="/manca-nuova/">x</a>'), 'Unexpected first chunk: ' . json_encode($report['cursor']));
            }
        }
        sb_assert('complete' === $report['status'] && $expected === $report['pages'] && $expected === $report['total'], 'The chunks did not read each page once: ' . $report['pages'] . ' / ' . $expected);
        sb_assert(!isset($report['broken']['/manca-fuori/']) && !isset($report['broken']['/manca-nuova/']) && 100 === count($report['broken']),
            'A symlink was followed, a chunk started again from the beginning, or the list is not capped at 100.');
        unlink($release . '/0-nuova/index.html');
        rmdir($release . '/0-nuova');
        sb_assert(array('/manca-home/', '/manca-10/', '/manca-9/', '/manca-a/', '/manca-a-b/', '/manca-a-trattino-b/') === array_slice(array_keys($report['broken']), 0, 6),
            'The pages are not read in the fixed order (a folder before its subfolders, byte order): ' . json_encode(array_slice(array_keys($report['broken']), 0, 6)));
        sb_assert(array('/a/b/') === $report['broken']['/manca-a-b/'], 'A route is not listed with the page that links it.');

        // In WP-Cron: a chunk of at most LINK_CHECK_BATCH_PAGES pages, the next event, then the end.
        sb_private($plugin, 'schedule_link_check', array(0));
        unset($GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::LINK_CHECK_HOOK]);
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $next = wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK);
        sb_assert('running' === $report['status'] && Static_Bridge_Plugin::LINK_CHECK_BATCH_PAGES === $report['pages'] && is_array($report['cursor'])
            && $next >= time() + 5 && $next <= time() + 30, 'The first chunk did not stop at its page limit and schedule the next one.');
        // A second request while the lock is held only makes sure there is a next run.
        $lock = sb_private($plugin, 'acquire_row_lock', array(Static_Bridge_Plugin::LINK_CHECK_LOCK, 120));
        unset($GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::LINK_CHECK_HOOK]);
        $plugin->run_link_check();
        sb_assert(Static_Bridge_Plugin::LINK_CHECK_BATCH_PAGES === get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION)['pages'] && false !== wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK),
            'A chunk ran while another one held the lock.');
        sb_private($plugin, 'release_row_lock', array(Static_Bridge_Plugin::LINK_CHECK_LOCK, $lock));
        $plugin->run_link_check();
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        sb_assert('complete' === $report['status'] && $expected === $report['pages'] && $expected === $report['total'] && array() === $report['counted'], 'The second chunk did not resume from the cursor and finish.');
    });
});

sb_test('Link check (2.5.0): the links of an SSI header fragment count as links of every page that includes it, only through a verified fragment', function () use ($fixtureRoot) {
    sb_link_check_isolated($fixtureRoot, function ($plugin, $root, $outside) {
        $menu = '<header><nav><a href="/manca-menu/">Menu</a> <a href="/a/">A</a> <a href="/pagina/">Pagina</a></nav></header>';
        $variant = hash('sha256', $menu);
        $file = 'elementor-42-' . $variant . '.html';
        $directive = '<!--#include virtual="/wp-content/static-bridge/current/fragments/headers/42/current/' . $file . '" -->';
        $forged = '<a href="/manca-falso/">x</a>';
        $forged_file = 'elementor-43-' . str_repeat('0', 64) . '.html';
        $forged_directive = '<!--#include virtual="/wp-content/static-bridge/current/fragments/headers/43/current/' . $forged_file . '" -->';
        $release = sb_link_check_release($root, 'r-ssi', array(
            '/' => $directive . '<main><a href="/manca-menu/">di nuovo</a></main>',
            '/a/' => $directive . '<main>A</main>' . $forged_directive,
            '/pagina/' => '<main>Senza header</main><!--#include virtual="/wp-content/static-bridge/current/../../wp-config.php" -->',
        ));
        foreach (array('42' => array($file, $menu), '43' => array($forged_file, $forged)) as $document => $fragment) {
            $generation = $release . '/fragments/headers/' . $document . '/generations/initial';
            sb_assert(wp_mkdir_p($generation) && false !== file_put_contents($generation . '/' . $fragment[0], $fragment[1])
                && symlink('generations/initial', $release . '/fragments/headers/' . $document . '/current'), 'Could not create the SSI header fragment.');
        }
        file_put_contents($root . '/.strict', '');
        sb_private($plugin, 'schedule_link_check', array(0));
        $report = sb_private($plugin, 'link_check_step', array(get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION)));
        sb_assert('complete' === $report['status'] && 3 === $report['pages'], 'The check did not read the three pages: ' . json_encode($report));
        sb_assert(array('/', '/a/') === ($report['broken']['/manca-menu/'] ?? null), 'A broken link of the header fragment is not reported with the pages that include it: ' . json_encode($report['broken']));
        sb_assert(!isset($report['broken']['/manca-falso/']) && 1 === $report['total'], 'A fragment whose content is not the variant in its name was read: ' . json_encode($report['broken']));
        // / links /manca-menu/ in its body and in the header (once), /a/ and /pagina/; /a/ the three of the header.
        sb_assert(6 === $report['links'], 'A route linked by the page and by its header counts twice, or a header link is missing: ' . $report['links']);
    });
});

sb_test('Link check (2.5.0): «Controlla di nuovo i link» needs manage_options and the nonce; Genera shows the escaped report, and without Strict only says it serves with Strict; WP-CLI status says it', function () use ($fixtureRoot) {
    sb_link_check_isolated($fixtureRoot, function ($plugin, $root) {
        $release = sb_link_check_release($root, 'r-ui', array('/' => '<a href="/manca/">x</a>'));
        file_put_contents($root . '/.strict', '');
        foreach (array('capability', 'nonce') as $missing) {
            'capability' === $missing ? $GLOBALS['sb_test_can_manage'] = false : $GLOBALS['sb_test_nonce_valid'] = false;
            try {
                $plugin->handle_link_check();
                throw new RuntimeException('The link check ran without its ' . $missing . '.');
            } catch (SB_Test_WP_Die $expected) {
                sb_assert('capability' === $missing, 'The capability is not checked first.');
            } catch (RuntimeException $expected) {
                sb_assert('Invalid admin nonce' === $expected->getMessage(), $expected->getMessage());
            } finally {
                $GLOBALS['sb_test_can_manage'] = true;
                $GLOBALS['sb_test_nonce_valid'] = true;
            }
            sb_assert(false === wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK) && false === get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION), 'A refused request scheduled a check.');
        }
        try {
            $plugin->handle_link_check();
            throw new RuntimeException('The link check did not redirect.');
        } catch (SB_Test_Response $redirect) {
            sb_assert(false !== strpos($redirect->data['location'], 'tab=generate') && false !== strpos($redirect->data['location'], 'link-check=queued')
                && false !== wp_next_scheduled(Static_Bridge_Plugin::LINK_CHECK_HOOK), 'The button did not schedule a check on the current release.');
        }

        $render = function ($full_access) use ($plugin, $release) {
            ob_start();
            sb_private($plugin, 'render_link_check_card', array($release, $full_access));
            return (string) ob_get_clean();
        };
        $report = get_option(Static_Bridge_Plugin::LINK_CHECK_OPTION);
        $report['status'] = 'complete';
        $report['finished_at'] = time();
        $report['pages'] = 1;
        $report['total'] = 2;
        $report['broken'] = array('/<script>alert(1)</script>/' => array('/"onmouseover="x/'), '/caffè/' => array('/'));
        update_option(Static_Bridge_Plugin::LINK_CHECK_OPTION, $report, false);
        $html = $render(true);
        sb_assert(false !== strpos($html, '2 rotte linkate senza copia statica') && false !== strpos($html, '&lt;script&gt;alert(1)&lt;/script&gt;')
            && false === strpos($html, '<script>') && false === strpos($html, '"onmouseover') && false !== strpos($html, 'href="https://news.example.test:8443/%22onmouseover%3D%22x/"')
            && false !== strpos($html, '<code>/caffè/</code>'), 'The report is not shown escaped: ' . $html);
        sb_assert(false !== strpos($html, 'name="action" value="static_bridge_link_check"') && false !== strpos($html, 'Controlla di nuovo i link'), 'The button is missing for an administrator.');
        sb_assert(false === strpos($render(false), 'static_bridge_link_check'), 'Who cannot manage options sees the button.');

        list($code, $output) = sb_cli_run(new Static_Bridge_CLI($plugin, function () {}), 'status', array(), array('format' => 'json'));
        $status = json_decode($output[0][1] ?? '', true);
        sb_assert(0 === $code && array('release' => 'r-ui', 'status' => 'complete', 'pages' => 1, 'broken' => 2, 'capped' => false, 'finished_at' => $report['finished_at']) === $status['link_check'],
            'wp static-bridge status does not say the last link check.');

        unlink($root . '/.strict');
        $html = $render(true);
        sb_assert(false !== strpos($html, 'serve solo con la modalità strict') && false === strpos($html, 'static_bridge_link_check') && false === strpos($html, 'caff'),
            'Without Strict the card does not say it serves only with Strict, or still offers the button.');
        try {
            $plugin->handle_link_check();
        } catch (SB_Test_Response $redirect) {
            sb_assert(false !== strpos($redirect->data['location'], 'link-check=strict_off'), 'The button scheduled a check without Strict.');
        }
    });
});

sb_test('Relative dates: human_time_diff is wrapped only in a verified render with the setting on, and only when $to is now', function () use ($plugin, $source) {
    $previous = array('options' => $GLOBALS['sb_test_options'], 'hooks' => $GLOBALS['sb_test_hooks'], 'get' => $_GET, 'uri' => $_SERVER['REQUEST_URI'] ?? null);
    $hooked = static function () {
        return array_values(array_filter($GLOBALS['sb_test_hooks'], static function ($hook) {
            return 'human_time_diff' === $hook[0];
        }));
    };
    $render = static function () use ($plugin) {
        $level = ob_get_level();
        $plugin->start_dynamic_render_body_proof();
        while (ob_get_level() > $level) {
            ob_end_clean();
        }
    };
    try {
        $token = str_repeat('ab', 24);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::RENDER_BYPASS_OPTION] = array('token' => $token, 'routes' => array('/notizie/'));
        $_SERVER['REQUEST_URI'] = '/notizie/?static_bridge_bypass=1&static_bridge_render=' . $token;

        // Off by default: a verified render adds no filter.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1);
        $_GET = array('static_bridge_bypass' => '1', 'static_bridge_render' => $token);
        sb_assert(0 === sb_private($plugin, 'settings')['relative_dates'], 'Relative dates are on by default; they change the HTML of an installed site.');
        $render();
        sb_assert(array() === $hooked(), 'The human_time_diff filter was added with the setting off.');

        // On, but a request without the render token (a visitor, a logged-in user): no filter.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['relative_dates'] = 1;
        $_GET = array();
        $render();
        sb_assert(array() === $hooked(), 'The human_time_diff filter was added outside a verified render.');
        $_GET = array('static_bridge_bypass' => '1', 'static_bridge_render' => str_repeat('cd', 24));
        $render();
        sb_assert(array() === $hooked(), 'The human_time_diff filter was added for a token that is not the transaction one.');

        // On, in the verified render: last priority, four arguments.
        $_GET = array('static_bridge_bypass' => '1', 'static_bridge_render' => $token);
        $render();
        $hooks = $hooked();
        sb_assert(1 === count($hooks) && array($plugin, 'mark_relative_date') === $hooks[0][1] && PHP_INT_MAX === $hooks[0][2] && 4 === $hooks[0][3], 'The verified render did not add the human_time_diff filter at the last priority with 4 arguments.');
    } finally {
        $GLOBALS['sb_test_options'] = $previous['options'];
        $GLOBALS['sb_test_hooks'] = $previous['hooks'];
        $_GET = $previous['get'];
        if (null === $previous['uri']) {
            unset($_SERVER['REQUEST_URI']);
        } else {
            $_SERVER['REQUEST_URI'] = $previous['uri'];
        }
    }

    $now = time();
    $open = Static_Bridge_Plugin::RELATIVE_DATE_OPEN;
    $separator = Static_Bridge_Plugin::RELATIVE_DATE_SEPARATOR;
    $close = Static_Bridge_Plugin::RELATIVE_DATE_CLOSE;
    $marked = $plugin->mark_relative_date('3 ore', 10800, $now - 10800, $now);
    sb_assert($open . ($now - 10800) . $separator . $now . $separator . '3 ore' . $close === $marked, 'A date compared with now was not wrapped with $from and $to.');
    sb_assert($open . ($now - 10800) . $separator . ($now - 2) . $separator . '3 ore' . $close === $plugin->mark_relative_date('3 ore', 10800, (string) ($now - 10800), $now - 2), 'A numeric string $from or a $to a few seconds old was not wrapped.');
    // The markers survive the escaping a template applies, and are valid UTF-8 (wp_check_invalid_utf8()).
    sb_assert($marked === esc_html($marked) && $marked === esc_attr($marked) && $marked === htmlspecialchars($marked, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') && 1 === preg_match('//u', $marked), 'The markers do not survive esc_html(), esc_attr() or htmlspecialchars().');
    foreach (array(
        'two fixed dates' => array('2 giorni', 172800, $now - 400000, $now - 227200),
        'a $to in the future' => array('1 ora', 3600, $now, $now + 3600),
        'a $from that is not a time' => array('3 ore', 10800, 'ieri', $now),
        'a negative $from' => array('3 ore', 10800, -5, $now),
        'markup in the text' => array('<b>3</b> ore', 10800, $now - 10800, $now),
        'text already marked' => array($marked, 10800, $now - 10800, $now),
        'an empty text' => array('', 0, $now, $now),
    ) as $label => $arguments) {
        sb_assert($arguments[0] === $plugin->mark_relative_date(...$arguments), 'Wrapped although the call has ' . $label . '.');
    }

    $save = sb_method_body($source, 'save_settings');
    sb_assert(false !== strpos($save, "'relative_dates' => isset(\$_POST['relative_dates']) ? 1 : 0"), 'save_settings() does not save «Date relative aggiornate nel browser».');
    sb_assert(false !== strpos($source, 'name="relative_dates" value="1"'), 'The Settings tab lacks «Date relative aggiornate nel browser».');
});

sb_test('Relative dates: markers become spans in visible text, plain text elsewhere, and none is ever written', function () use ($plugin, $source) {
    $open = Static_Bridge_Plugin::RELATIVE_DATE_OPEN;
    $separator = Static_Bridge_Plugin::RELATIVE_DATE_SEPARATOR;
    $close = Static_Bridge_Plugin::RELATIVE_DATE_CLOSE;
    $from = 1799989200;
    $to = 1800000000;
    $m = static function ($text, $since = 1799989200, $until = 1800000000) use ($open, $separator, $close) {
        return $open . $since . $separator . $until . $separator . $text . $close;
    };
    $span = '<span data-sb-since="' . $from . '" data-sb-to="' . $to . '">3 ore</span>';
    $page = static function ($body) {
        return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html; charset=UTF-8'), 'body' => $body);
    };
    $no_marker = static function ($html) use ($plugin) {
        return !sb_private($plugin, 'has_relative_date_markers', array($html)) && false === strpos($html, "\xF4\x8F\xBF")
            && false === stripos($html, '\udbff');
    };
    $html = '<!DOCTYPE html><html lang="it"><head><title>Notizia · ' . $m('3 ore') . '</title>'
        . '<meta name="description" content="Pubblicato ' . $m('3 ore') . ' fa">'
        . '<script>var raw = "' . $m('3 ore') . '"; var json = ' . json_encode(array('t' => $m('3 ore'))) . ';</script>'
        . '<style>/* ' . $m('3 ore') . ' */</style></head>'
        . '<body class="single"><p>Pubblicato ' . $m('3 ore') . ' fa</p>'
        . '<a href="/notizie/" title="' . $m('3 ore') . '" data-x=\'' . $m('3 ore') . '\'>Notizie</a>'
        . '<!-- ' . $m('3 ore') . ' --><textarea>' . $m('3 ore') . '</textarea><noscript>' . $m('3 ore') . '</noscript>'
        . '<p class="c">' . $m('5 min', 1799999700) . ' e ' . $m('2 giorni', 1799827200) . '</p>'
        . '<p class="unclosed">A' . $open . $from . $separator . $to . $separator . '3 ore</p>'
        . '<p class="stray">B' . $close . 'x' . $separator . '</p>'
        . '<p class="nested">C' . $open . $from . $separator . $to . $separator . 'a ' . $m('3 ore') . ' b' . $close . '</p>'
        . '<p class="numbers">D' . $open . 'abc' . $separator . '12' . $separator . '3 ore' . $close . '</p>'
        . '<p class="long">E' . $open . '1234567890123' . $separator . $to . $separator . '3 ore' . $close . '</p>'
        . '<p class="one">F' . $open . $from . $separator . '3 ore' . $close . '</p>'
        . '<p class="across">G' . $open . $from . $separator . $to . $separator . '<b>3</b> ore' . $close . '</p>'
        . '</body></html>';
    $result = sb_private($plugin, 'parse_fetched_page', array(home_url('/notizie/'), $page($html)));
    sb_assert(is_array($result) && isset($result['body']), 'A page with relative dates was refused.');
    $out = $result['body'];
    sb_assert($no_marker($out), 'A relative-date marker is left in the HTML: ' . $out);
    sb_assert(false !== strpos($out, '<p>Pubblicato ' . $span . ' fa</p>'), 'The marker in a text run did not become a span: ' . $out);
    sb_assert(false !== strpos($out, '<p class="c"><span data-sb-since="1799999700" data-sb-to="1800000000">5 min</span> e <span data-sb-since="1799827200" data-sb-to="1800000000">2 giorni</span></p>'), 'Two dates in one text run did not both become spans.');
    sb_assert(3 === substr_count($out, 'data-sb-since='), 'Only the visible text runs may carry spans: ' . substr_count($out, 'data-sb-since='));
    foreach (array(
        '<title>Notizia · 3 ore</title>', 'content="Pubblicato 3 ore fa"', 'var raw = "3 ore";', 'var json = {"t":"3 ore"};', '/* 3 ore */',
        'title="3 ore" data-x=\'3 ore\'', '<!-- 3 ore -->', '<textarea>3 ore</textarea>', '<noscript>3 ore</noscript>',
        '<p class="unclosed">A3 ore</p>', '<p class="stray">Bx</p>', '<p class="nested">Ca 3 ore b</p>', '<p class="numbers">D3 ore</p>',
        '<p class="long">E3 ore</p>', '<p class="one">F3 ore</p>', '<p class="across">G<b>3</b> ore</p>',
    ) as $expected) {
        sb_assert(false !== strpos($out, $expected), 'Expected «' . $expected . '» in the cleaned page: ' . $out);
    }
    $script = '<script id="static-bridge-relative-dates" src="' . home_url('/wp-content/plugins/static-bridge/assets/relative-dates.js?ver=' . Static_Bridge_Plugin::VERSION) . '" defer></script></head>';
    sb_assert(1 === substr_count($out, 'relative-dates.js') && false !== strpos($out, $script), 'The page with spans did not get exactly one deferred relative-dates.js before </head>.');
    sb_assert($out === sb_private($plugin, 'relative_dates_static_html', array($out)), 'A second pass changed the page or added the script again.');
    // The writers make the release root-relative, as for the other front-end scripts.
    sb_assert(false !== strpos(sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array($out)), 'src="/wp-content/plugins/static-bridge/assets/relative-dates.js?ver='), 'The script URL is not portable in the release.');

    // Markers only where no span can go: plain text, and no script.
    $quiet = sb_private($plugin, 'relative_dates_static_html', array('<html><head><title>' . $m('3 ore') . '</title></head><body><p>x</p></body></html>'));
    sb_assert('<html><head><title>3 ore</title></head><body><p>x</p></body></html>' === $quiet, 'A page without visible relative dates got a span or the script: ' . $quiet);
    $head_text = sb_private($plugin, 'relative_dates_static_html', array('<html><head>' . $m('3 ore') . '</head><body><p>x</p></body></html>'));
    sb_assert('<html><head>3 ore</head><body><p>x</p></body></html>' === $head_text, 'Text before <body> got a span.');

    // Every encoded form goes, with its numbers; the guard is the last step of both writers.
    $encoded = 'a' . json_encode($m('1 ora')) . ' b' . str_replace('\\', '\\\\', json_encode($m('1 ora'))) . ' c' . rawurlencode($m('1 ora'))
        . ' d' . rawurlencode(rawurlencode($m('1 ora'))) . ' e&#x10FFF1;' . $from . '&#x10fff2;' . $to . '&#1114098;1 ora&#1114099; f' . $close;
    $stripped = sb_private($plugin, 'strip_relative_date_markers', array($encoded));
    sb_assert($no_marker($stripped) && false === strpos($stripped, (string) $from) && false === strpos($stripped, (string) $to), 'An encoded marker or its numbers survived the final check: ' . $stripped);
    sb_assert(false !== strpos($stripped, ' e1 ora f'), 'The final check removed the text of an entity-encoded date: ' . $stripped);
    foreach (array('write_export_page', 'write_incremental_page') as $writer) {
        sb_assert(false !== strpos(sb_method_body($source, $writer), '$body = $this->strip_relative_date_markers($this->rewrite_internal_origins_as_root_relative((string) $body));'), $writer . '() does not remove relative-date markers before writing.');
    }

    // Setting off: no marker in the render, and the page comes back byte for byte, private-use icons included.
    $plain = '<!DOCTYPE html><html lang="it"><head><title>Notizia</title><script>var q = "%F4%80%80"; var n = 1114097; var i = "";</script></head>'
        . '<body><p>Pubblicato 3 ore fa <i class="fa">' . "\u{F015}\u{E87C}" . '</i> &#xf015; &#x10fff0; ' . "\u{10FFF0}\u{10FFFD}" . '</p></body></html>';
    $result = sb_private($plugin, 'parse_fetched_page', array(home_url('/notizie/'), $page($plain)));
    sb_assert(is_array($result) && $plain === $result['body'], 'A page without markers changed: ' . (is_array($result) ? $result['body'] : ''));
    sb_assert($plain === sb_private($plugin, 'strip_relative_date_markers', array($plain)), 'The final check changed a page without markers.');
});

/** 2.5.0 Basic Auth: the credentials of this request, as basic_auth_from() makes them from the two constants of wp-config.php. */
function sb_ba_set($plugin, $user, $password)
{
    $property = new ReflectionProperty($plugin, 'basic_auth');
    $property->setValue($plugin, sb_private($plugin, 'basic_auth_from', array($user, $password)));
}

/** The Authorization header of a recorded request, '' without one (any spelling of the name). */
function sb_ba_header_of(array $call)
{
    foreach (isset($call['args']['headers']) && is_array($call['args']['headers']) ? $call['args']['headers'] : array() as $name => $value) {
        if ('authorization' === strtolower((string) $name)) {
            return (string) $value;
        }
    }
    return '';
}

/** A fake user name and password for these tests only: never real credentials. */
const SB_BA_USER = 'sbqa-utente';
const SB_BA_PASSWORD = 'Finta:Password-di-prova';

/** The secrets these tests look for in everything the plugin stores, logs or prints. */
function sb_ba_secrets()
{
    return array(SB_BA_PASSWORD, base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD), SB_BA_USER . ':' . SB_BA_PASSWORD);
}

/** An answer as a web server behind Basic Auth gives it: 401 without the right header, $answer with it. */
function sb_ba_server($answer, $expected)
{
    return function ($url, $args) use ($answer, $expected) {
        if ($expected !== sb_ba_header_of(array('args' => $args))) {
            return array('response' => array('code' => 401), 'headers' => array('www-authenticate' => 'Basic realm="staging"', 'content-type' => 'text/html'), 'body' => '<html>401</html>');
        }
        return $answer;
    };
}

sb_test('Basic Auth (2.5.0): only two valid wp-config.php constants turn it on, never an option, a setting or a form', function () use ($source, $pluginFile) {
    sb_group_c_isolated(function ($plugin) use ($source, $pluginFile) {
        $from = function ($user, $password) use ($plugin) {
            return sb_private($plugin, 'basic_auth_from', array($user, $password));
        };
        sb_assert(array('state' => 'off') === $from(null, null), 'Basic Auth is not off without the two constants.');
        $invalid = array(
            'only the user' => array('sbqa', null), 'only the password' => array(null, 'Finta-Password'),
            'a number as user' => array(1234, 'Finta-Password'), 'a number as password' => array('sbqa', 12345678),
            'an array' => array(array('sbqa'), 'x'), 'a boolean' => array('sbqa', true), 'an empty user' => array('', 'x'),
            'a user with :' => array('sb:qa', 'x'), 'a user with LF' => array("sbqa\n", 'x'), 'a user with NUL' => array("sb\0qa", 'x'),
            'a password with CR LF' => array('sbqa', "x\r\nX-Injected: 1"), 'a password with LF' => array('sbqa', "x\ny"),
            'a password with NUL' => array('sbqa', "x\0y"), 'a password with TAB' => array('sbqa', "x\ty"), 'a password with DEL' => array('sbqa', "x\x7f"),
        );
        foreach ($invalid as $case => list($user, $password)) {
            sb_assert(array('state' => 'invalid') === $from($user, $password), 'Constants with ' . $case . ' are not reported as invalid.');
        }
        sb_assert(array('state' => 'on', 'user' => SB_BA_USER, 'password' => SB_BA_PASSWORD) === $from(SB_BA_USER, SB_BA_PASSWORD), 'Valid constants (a password with :) were refused.');
        sb_assert('on' === $from('sbqa', '')['state'], 'An empty password was refused.');

        // Missing, one only, not a string, a user with ':', CR/LF: no request carries the header.
        $html = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>OK</html>');
        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) { return $html; };
        $GLOBALS['sb_test_http_post_callback'] = function ($url, $args) use ($html) { return $html; };
        try {
            foreach (array('absent' => array(null, null), 'one only' => array(SB_BA_USER, null), 'not a string' => array(SB_BA_USER, 12345678),
                'user with :' => array('sb:qa', SB_BA_PASSWORD), 'CR/LF' => array(SB_BA_USER, "Finta\r\nPassword")) as $case => list($user, $password)) {
                sb_ba_set($plugin, $user, $password);
                $GLOBALS['sb_test_http_calls'] = array();
                sb_private($plugin, 'remote_get', array(home_url('/chi-siamo/'), 5, 4096, true));
                sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, false, array('method' => 'POST')));
                sb_private($plugin, 'self_request', array('POST', admin_url('admin-ajax.php'), array('redirection' => 0)));
                sb_private($plugin, 'self_request_follow', array(home_url('/'), array('redirection' => 3)));
                sb_private($plugin, 'server_check_module')->run('host-cache');
                list($headers, $options) = sb_private($plugin, 'self_request_auth_options', array(home_url('/x/'), array('Accept' => 'text/html'), array('redirects' => 5)));
                sb_assert(count($GLOBALS['sb_test_http_calls']) >= 6, 'The requests of case ' . $case . ' were not sent.');
                foreach ($GLOBALS['sb_test_http_calls'] as $call) {
                    sb_assert('' === sb_ba_header_of($call), 'Constants ' . $case . ' sent an Authorization header to ' . $call['url']);
                }
                sb_assert(array('Accept' => 'text/html') === $headers && array('redirects' => 5) === $options, 'Constants ' . $case . ' changed a parallel request.');
                sb_assert(array() === sb_private($plugin, 'self_request_auth_headers', array(home_url('/'))), 'Constants ' . $case . ' built a header.');
            }
        } finally {
            $GLOBALS['sb_test_http_callback'] = null;
            $GLOBALS['sb_test_http_post_callback'] = null;
        }

        // Read from the two constants only: no option, no setting, nothing to remove at uninstall.
        $read = sb_method_body($source, 'basic_auth_credentials');
        sb_assert(false !== strpos($read, "defined('STATIC_BRIDGE_BASIC_AUTH_USER') ? constant('STATIC_BRIDGE_BASIC_AUTH_USER') : null")
            && false !== strpos($read, "defined('STATIC_BRIDGE_BASIC_AUTH_PASSWORD') ? constant('STATIC_BRIDGE_BASIC_AUTH_PASSWORD') : null"), 'The credentials are not read from the two constants.');
        sb_assert(2 === substr_count($source, "'STATIC_BRIDGE_BASIC_AUTH_USER'") && 2 === substr_count($source, "'STATIC_BRIDGE_BASIC_AUTH_PASSWORD'"), 'The constants are read somewhere else too.');
        preg_match_all('/[\'"]static_bridge_[a-z_]*basic[a-z_]*[\'"]/', $source, $names);
        sb_assert(array("'static_bridge_basic_auth_echo'") === array_values(array_unique($names[0])) && !preg_match('/_option\([^;)]*basic/i', $source), 'Basic Auth reached an option: ' . json_encode($names[0]));
        sb_assert(empty(preg_grep('/basic/i', array_keys(sb_private($plugin, 'settings')))), 'Basic Auth reached the settings.');
        sb_assert(false === stripos((string) file_get_contents(dirname($pluginFile) . '/uninstaller.php'), 'basic'), 'The uninstaller knows of a Basic Auth option that must not exist.');
        sb_assert(false === stripos(sb_method_body($source, 'save_settings') . sb_method_body($source, 'render_settings_tab'), 'basic_auth'), 'A form of wp-admin handles Basic Auth.');
        // One place builds the header.
        sb_assert(1 === substr_count($source, "'Basic '") && 1 === substr_count($source, 'base64_encode($credentials[\'user\'] . \':\' . $credentials[\'password\'])'), 'The Basic Auth header is built in more than one place.');
    });
});

sb_test('Basic Auth (2.5.0): the header goes on every request to this site, never to another host, never with a redirect', function () use ($source, $pluginFile) {
    sb_group_c_isolated(function ($plugin) use ($source, $pluginFile) {
        $expected = 'Basic ' . base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD);
        $html = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html><body>OK</body></html>');
        $all_calls = array();
        sb_ba_set($plugin, SB_BA_USER, SB_BA_PASSWORD);
        try {
            sb_assert(array('Authorization' => $expected) === sb_private($plugin, 'self_request_auth_headers', array(home_url('/chi-siamo/'))), 'Valid constants did not give the header for this site.');
            // Never to another host, scheme or port, to a URL with credentials, to Cloudflare or to the release updater.
            foreach (array('https://other.example.test/', 'https://news.example.test.attacker.invalid:8443/', 'http://news.example.test:8443/', 'https://news.example.test:8444/',
                'https://news.example.test/', 'https://sbqa:x@news.example.test:8443/', Static_Bridge_Plugin::CLOUDFLARE_API_BASE . '0123/purge_cache',
                'https://api.github.com/repos/example/static-bridge/releases/latest', '/chi-siamo/', '') as $foreign) {
                sb_assert(array() === sb_private($plugin, 'self_request_auth_headers', array($foreign)), 'The header was built for ' . $foreign);
            }
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) { return $html; };
            $GLOBALS['sb_test_http_post_callback'] = function ($url, $args) use ($html) { return $html; };
            $GLOBALS['sb_test_http_calls'] = array();
            sb_private($plugin, 'self_request', array('GET', 'https://other.example.test/', array('redirection' => 2)));
            sb_private($plugin, 'self_request', array('POST', Static_Bridge_Plugin::CLOUDFLARE_API_BASE . '0123/purge_cache', array('redirection' => 0)));
            sb_assert(2 === count($GLOBALS['sb_test_http_calls']) && '' === sb_ba_header_of($GLOBALS['sb_test_http_calls'][0]) && '' === sb_ba_header_of($GLOBALS['sb_test_http_calls'][1])
                && 2 === $GLOBALS['sb_test_http_calls'][0]['args']['redirection'], 'A request to another host carried the header or lost its own arguments.');
            $updater = (string) file_get_contents(dirname($pluginFile) . '/release-updater.php');
            sb_assert(false === stripos($updater, 'authorization') && false === stripos($updater, 'self_request') && false === stripos($updater, 'BASIC_AUTH'), 'The release updater can send the Basic Auth header.');
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);

            // remote_get(): rendering, incrementals, diagnostics, the POST probe; the Diagnostica's request without credentials.
            $GLOBALS['sb_test_http_calls'] = array();
            sb_private($plugin, 'remote_get', array(home_url('/chi-siamo/'), 5, 4096, true));
            sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, false, array('method' => 'POST')));
            sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, false, array('basic_auth' => false)));
            $calls = $GLOBALS['sb_test_http_calls'];
            sb_assert(3 === count($calls) && $expected === sb_ba_header_of($calls[0]) && 'wp_safe_remote_post' === $calls[1]['api'] && $expected === sb_ba_header_of($calls[1]) && '' === sb_ba_header_of($calls[2]),
                'remote_get() did not add the header, or added it to the request without credentials.');
            sb_assert(isset($calls[0]['args']['headers']['Accept'], $calls[0]['args']['headers']['Cache-Control'], $calls[0]['args']['headers']['Pragma']), 'The header replaced the render headers.');
            $all_calls = array_merge($all_calls, $calls);

            // The verified render: fetch_page() → fetch_verified_renders() → remote_get(), and the parallel fallback.
            $GLOBALS['sb_test_http_callback'] = null;
            $GLOBALS['sb_test_http_responses'][home_url('/chi-siamo/') . '?static_bridge_bypass=1'] = $html;
            $GLOBALS['sb_test_http_responses'][home_url('/dove-siamo/') . '?static_bridge_bypass=1'] = $html;
            $GLOBALS['sb_test_http_calls'] = array();
            $page = sb_private($plugin, 'fetch_page', array(home_url('/chi-siamo/'), 10));
            sb_assert(is_array($page) && isset($page['body']), 'The render behind Basic Auth failed: ' . (is_wp_error($page) ? $page->get_error_message() : ''));
            $pages = sb_private($plugin, 'fetch_pages', array(array(home_url('/chi-siamo/'), home_url('/dove-siamo/'))));
            sb_assert(2 === count($pages) && !is_wp_error($pages[home_url('/dove-siamo/')]), 'The batch render behind Basic Auth failed.');
            sb_assert(3 === count($GLOBALS['sb_test_http_calls']), 'The renders did not send three requests.');
            foreach ($GLOBALS['sb_test_http_calls'] as $call) {
                sb_assert($expected === sb_ba_header_of($call) && false !== strpos($call['url'], 'static_bridge_render='), 'A render request lacks the header: ' . $call['url']);
            }
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);

            // remote_get_batch(): the Requests multi transport gets the header for the URL actually sent, and no redirects.
            list($headers, $options) = sb_private($plugin, 'self_request_auth_options', array(home_url('/a/'), array('Accept' => 'text/html'), array('redirects' => 5, 'timeout' => 5)));
            sb_assert(array('Accept' => 'text/html', 'Authorization' => $expected) === $headers && false === $options['follow_redirects'] && !isset($options['redirects']) && 5 === $options['timeout'],
                'The parallel request does not carry the header without redirects.');
            list($headers, $options) = sb_private($plugin, 'self_request_auth_options', array('https://other.example.test/a/', array('Accept' => 'text/html'), array('redirects' => 5)));
            sb_assert(array('Accept' => 'text/html') === $headers && array('redirects' => 5) === $options, 'The parallel transport would send the header to another host.');
            $batch = sb_method_body($source, 'remote_get_batch');
            $at_auth = strpos($batch, 'list($headers, $options) = $this->self_request_auth_options($url, $headers, $options);');
            sb_assert(false !== $at_auth && $at_auth > strpos($batch, "'curl.before_multi_add'") && $at_auth < strpos($batch, "'headers' => \$headers,")
                && false === stripos($batch, 'authorization'), 'remote_get_batch() does not add the header right before the request, for the final URL.');

            // The background chain of the export.
            $job_id = '12345678-1234-4234-8234-bbbbbbbbbbbb';
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array('queue_version' => 1, 'job_id' => $job_id, 'status' => 'running');
            sb_private($plugin, 'arm_export_continuation', array($job_id));
            $GLOBALS['sb_test_http_calls'] = array();
            sb_assert(true === sb_private($plugin, 'send_export_continuation', array(true)), 'The background request was not sent.');
            $sent = $GLOBALS['sb_test_http_calls'];
            sb_assert(1 === count($sent) && 'wp_safe_remote_post' === $sent[0]['api'] && home_url('/wp-admin/admin-ajax.php') === $sent[0]['url'] && $expected === sb_ba_header_of($sent[0])
                && false === $sent[0]['args']['blocking'] && 0 === $sent[0]['args']['redirection'], 'The background request of the export lacks the header.');
            $all_calls = array_merge($all_calls, $sent);

            // The Diagnostica's requests.
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) { return $html; };
            $GLOBALS['sb_test_http_calls'] = array();
            sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'wp-admin', 'type' => 'admin'), array()));
            sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'query-bypass', 'type' => 'bypass'), array()));
            sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'render-origin', 'type' => 'render-origin'), array()));
            sb_assert(count($GLOBALS['sb_test_http_calls']) >= 3, 'The diagnostic steps sent no request.');
            foreach ($GLOBALS['sb_test_http_calls'] as $call) {
                sb_assert($expected === sb_ba_header_of($call), 'A diagnostic request lacks the header: ' . $call['url']);
            }
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);

            // The Server tab: the plugin follows a same-site redirect itself, with the header; never one to another host.
            $GLOBALS['sb_test_http_calls'] = array();
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) {
                if (home_url('/') === $url) {
                    return array('response' => array('code' => 301), 'headers' => array('location' => '/benvenuto/'), 'body' => '');
                }
                return home_url('/benvenuto/') === $url ? $html : null;
            };
            $result = sb_private($plugin, 'server_check_module')->run('host-cache');
            $urls = array_column($GLOBALS['sb_test_http_calls'], 'url');
            sb_assert(array(home_url('/'), home_url('/benvenuto/'), home_url('/'), home_url('/benvenuto/')) === $urls && 'skip' !== $result['status'], 'The server check did not follow the same-site redirect: ' . json_encode($urls));
            foreach ($GLOBALS['sb_test_http_calls'] as $call) {
                sb_assert($expected === sb_ba_header_of($call) && 0 === $call['args']['redirection'], 'A server check request lacks the header or lets WordPress follow redirects.');
            }
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);
            $GLOBALS['sb_test_http_calls'] = array();
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) {
                return home_url('/') === $url ? array('response' => array('code' => 302), 'headers' => array('location' => 'https://login.other.example.test/?next=/'), 'body' => '') : $html;
            };
            sb_private($plugin, 'server_check_module')->run('host-cache');
            sb_assert(array(home_url('/'), home_url('/')) === array_column($GLOBALS['sb_test_http_calls'], 'url'), 'A redirect to another host was followed with the header.');
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);
            sb_assert(false !== strpos(sb_method_body($source, 'set_server_htaccess_block'), '$this->self_request_follow($url, array(')
                && false === strpos(sb_method_body($source, 'set_server_htaccess_block'), 'wp_safe_remote_'), 'The test of the .htaccess block does not go through self_request_follow().');
            $ssi = sb_method_body($source, 'verify_nginx_ssi_runtime');
            sb_assert(2 === substr_count($ssi, "\$this->self_request('GET', ") && false === strpos(str_replace("function_exists('wp_safe_remote_get')", '', $ssi), 'wp_safe_remote_'), 'The SSI probe does not go through self_request().');

            // The object cache probe, through the closure the Server tab gives it.
            $GLOBALS['sb_test_http_calls'] = array();
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html) { return $html; };
            Static_Bridge_Object_Cache::probe(function ($url, $args) use ($plugin) { return sb_private($plugin, 'self_request', array('GET', $url, (array) $args)); });
            sb_assert(1 === count($GLOBALS['sb_test_http_calls']) && $expected === sb_ba_header_of($GLOBALS['sb_test_http_calls'][0]), 'The object cache probe lacks the header.');
            sb_assert(false !== strpos(sb_method_body($source, 'handle_server_tuning'), "Static_Bridge_Object_Cache::install((array) \$service, function (\$url, \$args) {\n                    return \$this->self_request('GET', \$url, (array) \$args);"),
                'The Server tab does not give the object cache probe self_request().');
            $all_calls = array_merge($all_calls, $GLOBALS['sb_test_http_calls']);

            // Every request with the header has redirection 0.
            foreach ($all_calls as $call) {
                if ('' !== sb_ba_header_of($call)) {
                    sb_assert(0 === ($call['args']['redirection'] ?? null), 'A request with the header may follow a redirect: ' . $call['url']);
                }
            }
            // Not even another plugin's http_request_args filter can make WordPress follow one: the last filter puts 0 back.
            $seen = array();
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($html, &$seen) {
                $args['redirection'] = 5;
                $filters = array_values(array_filter($GLOBALS['sb_test_hooks'], function ($hook) { return 'http_request_args' === $hook[0]; }));
                usort($filters, function ($a, $b) { return $a[2] <=> $b[2]; });
                foreach ($filters as $filter) {
                    $args = call_user_func($filter[1], $args, $url);
                }
                $seen[] = $args['redirection'];
                return $html;
            };
            sb_private($plugin, 'remote_get', array(home_url('/'), 5));
            sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, false, array('basic_auth' => false)));
            sb_assert(array(0, 5) === $seen, 'The redirect guard did not hold the header request at 0, or touched a request without the header: ' . json_encode($seen));
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                sb_assert('http_request_args' !== $hook[0], 'The redirect guard stayed registered after the request.');
            }
            $guard = sb_method_body($source, 'self_request');
            sb_assert(false !== strpos($guard, "add_filter('http_request_args', \$no_redirects, PHP_INT_MAX, 2);") && false !== strpos($guard, "remove_filter('http_request_args', \$no_redirects, PHP_INT_MAX);"), 'The redirect guard is not the last filter.');

            // Only self_request(), self_request_follow() (without the header) and the Cloudflare API call WordPress' HTTP API.
            preg_match_all('/^(?![ \t]*(?:\*|\/\/)).*?\bwp_safe_remote_(?:get|post)\(/m', $source, $matches, PREG_OFFSET_CAPTURE);
            $owners = array();
            foreach ($matches[0] as $match) {
                preg_match_all('/function ([a-z_]+)\(/', substr($source, 0, $match[1]), $functions);
                $owners[] = end($functions[1]);
            }
            $owners = array_values(array_unique($owners));
            sort($owners);
            sb_assert(array('cloudflare_purge_request', 'self_request', 'self_request_follow') === $owners, 'The plugin calls the HTTP API outside self_request(): ' . json_encode($owners));
        } finally {
            $GLOBALS['sb_test_http_callback'] = null;
            $GLOBALS['sb_test_http_post_callback'] = null;
        }
    });
});

sb_test('Basic Auth (2.5.0): with render_origin the header reaches the origin IP, the URL and Host stay the site\'s', function () {
    if (!function_exists('curl_init') || !defined('CURLOPT_CONNECT_TO') || !function_exists('proc_open')) {
        throw new SB_Test_Skip('cURL with CURLOPT_CONNECT_TO and proc_open are required for the origin connection check.');
    }
    sb_group_c_isolated(function ($plugin) {
        $old_home = $GLOBALS['sb_test_home'];
        $port = sb_cf_free_port();
        $public_port = sb_cf_free_port();
        $router = sys_get_temp_dir() . '/sb-basic-auth-router-' . getmypid() . '-' . bin2hex(random_bytes(4)) . '.php';
        // A web server behind Basic Auth: 401 without the right credentials, the Host and path it received with them.
        file_put_contents($router, '<?php if (($_SERVER["PHP_AUTH_USER"] ?? null) !== ' . var_export(SB_BA_USER, true) . ' || ($_SERVER["PHP_AUTH_PW"] ?? null) !== ' . var_export(SB_BA_PASSWORD, true)
            . ') { http_response_code(401); header("WWW-Authenticate: Basic realm=\"staging\""); echo "AUTH"; return; } header("Content-Type: text/html"); echo json_encode(array("host" => $_SERVER["HTTP_HOST"] ?? "", "uri" => $_SERVER["REQUEST_URI"] ?? ""));');
        $process = proc_open(array(PHP_BINARY, '-n', '-S', '127.0.0.1:' . $port, $router), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', '/dev/null', 'a'), 2 => array('file', '/dev/null', 'a')), $pipes);
        sb_assert(is_resource($process), 'Could not start the Basic Auth origin fixture.');
        try {
            $deadline = microtime(true) + 5;
            do {
                $probe = @fsockopen('127.0.0.1', $port, $errno, $errstr, 0.2);
                if ($probe) {
                    fclose($probe);
                    break;
                }
                usleep(50000);
            } while (microtime(true) < $deadline);
            // The public name does not resolve: only the connect-to address reaches a server.
            $GLOBALS['sb_test_home'] = 'http://basic-auth-probe.invalid:' . $public_port;
            $GLOBALS['sb_test_http_callback'] = 'sb_cf_curl_transport';
            sb_cf_settings(array('render_origin' => '127.0.0.1:' . $port));
            $url = home_url('/hello-world/');

            sb_ba_set($plugin, null, null);
            $denied = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(!is_wp_error($denied) && 401 === wp_remote_retrieve_response_code($denied), 'Without the constants the origin did not answer 401.');

            sb_ba_set($plugin, SB_BA_USER, SB_BA_PASSWORD);
            $response = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(!is_wp_error($response) && 200 === wp_remote_retrieve_response_code($response), 'With the constants the render through the origin address was refused: ' . (is_wp_error($response) ? $response->get_error_message() : wp_remote_retrieve_response_code($response)));
            $echo = json_decode(wp_remote_retrieve_body($response), true);
            sb_assert(is_array($echo) && 'basic-auth-probe.invalid:' . $public_port === $echo['host'] && '/hello-world/' === $echo['uri'], 'The origin did not receive the public Host and path: ' . wp_remote_retrieve_body($response));
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                sb_assert('http_api_curl' !== $hook[0] && 'http_request_args' !== $hook[0], 'A temporary HTTP hook stayed registered.');
            }
            // Wrong credentials: the origin refuses them, and the error says nothing of them.
            sb_ba_set($plugin, SB_BA_USER, 'Altra-Password-finta');
            $wrong = sb_private($plugin, 'remote_get', array($url, 5, 4096, true));
            sb_assert(!is_wp_error($wrong) && 401 === wp_remote_retrieve_response_code($wrong), 'Wrong credentials were accepted by the origin fixture.');
            $parsed = sb_private($plugin, 'parse_fetched_page', array($url, $wrong));
            sb_assert(is_wp_error($parsed) && false === strpos($parsed->get_error_message(), 'Altra-Password-finta'), 'The 401 error shows the password.');
        } finally {
            proc_terminate($process);
            proc_close($process);
            @unlink($router);
            $GLOBALS['sb_test_home'] = $old_home;
            $GLOBALS['sb_test_http_callback'] = null;
        }
    });
});

sb_test('Basic Auth (2.5.0): the Diagnostica step gives the five outcomes, and says invalid constants without a value', function () {
    sb_group_c_isolated(function ($plugin) {
        $expected = 'Basic ' . base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD);
        $ok = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>OK</html>');
        $denied = array('response' => array('code' => 401), 'headers' => array('www-authenticate' => 'Basic realm="staging"'), 'body' => '');
        $plan = array_column(sb_private($plugin, 'diagnostic_plan', array('')), 'id');
        $at = array_search('basic-auth', $plan, true);
        sb_assert(false !== $at && $plan[$at + 1] === 'render-origin', 'The plan does not check Basic Auth right before the render: ' . json_encode($plan));
        $run = function ($state, $callback) use ($plugin) {
            sb_ba_set($plugin, $state[0], $state[1]);
            $GLOBALS['sb_test_http_calls'] = array();
            $GLOBALS['sb_test_http_callback'] = $callback;
            $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'basic-auth', 'type' => 'basic-auth'), array()));
            foreach ($GLOBALS['sb_test_http_calls'] as $call) {
                sb_assert(home_url('/') === $call['url'] && 0 === $call['args']['redirection'], 'A Basic Auth probe left the home or allows redirects.');
            }
            $text = json_encode($result, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            foreach (array_merge(sb_ba_secrets(), array("Finta\r\nPassword", 'sb:qa')) as $secret) {
                sb_assert(false === strpos($text, $secret), 'The diagnostic result shows a credential: ' . $text);
            }
            return array($result, array_map('sb_ba_header_of', $GLOBALS['sb_test_http_calls']));
        };
        $valid = array(SB_BA_USER, SB_BA_PASSWORD);
        try {
            // 1. 401 without credentials and no constants: error, with the names of the two constants.
            list($result, $headers) = $run(array(null, null), sb_ba_server($ok, $expected));
            sb_assert('fail' === $result['status'] && array('') === $headers && false !== strpos($result['remediation'], 'STATIC_BRIDGE_BASIC_AUTH_USER')
                && false !== strpos($result['remediation'], 'STATIC_BRIDGE_BASIC_AUTH_PASSWORD') && false !== strpos($result['remediation'], 'wp-config.php'), 'Outcome 1: ' . json_encode($result));
            // 2. 401 also with the credentials: wrong credentials.
            list($result, $headers) = $run($valid, function () use ($denied) { return $denied; });
            sb_assert('fail' === $result['status'] && array('', $expected) === $headers && false !== strpos($result['summary'], 'sbagliati'), 'Outcome 2: ' . json_encode($result));
            // 3. 2xx or 3xx with the credentials: Basic Auth on.
            foreach (array(200, 301) as $code) {
                list($result, $headers) = $run($valid, sb_ba_server(array('response' => array('code' => $code), 'headers' => array('location' => home_url('/it/')), 'body' => ''), $expected));
                sb_assert('pass' === $result['status'] && array('', $expected) === $headers && false !== strpos($result['summary'], 'Basic Auth attiva'), 'Outcome 3 (HTTP ' . $code . '): ' . json_encode($result));
            }
            // 4. No 401 without credentials and no constants: the site does not ask, nothing is needed.
            list($result, $headers) = $run(array(null, null), function () use ($ok) { return $ok; });
            sb_assert('skip' === $result['status'] && array('') === $headers && false !== strpos($result['summary'], 'non chiede Basic Auth'), 'Outcome 4: ' . json_encode($result));
            // 5. Constants, but the site does not ask: a light warning, and no request with the credentials.
            list($result, $headers) = $run($valid, function () use ($ok) { return $ok; });
            sb_assert('warning' === $result['status'] && array('') === $headers && false !== strpos($result['summary'], 'non servono'), 'Outcome 5: ' . json_encode($result));
            // Invalid constants: an error if the site asks, a warning if not; never a header, never a value.
            foreach (array(array(SB_BA_USER, "Finta\r\nPassword"), array('sb:qa', SB_BA_PASSWORD), array(SB_BA_USER, null)) as $state) {
                list($result, $headers) = $run($state, sb_ba_server($ok, $expected));
                sb_assert('fail' === $result['status'] && array('') === $headers && false !== strpos($result['summary'], 'non sono valide')
                    && false !== strpos($result['remediation'], 'STATIC_BRIDGE_BASIC_AUTH_PASSWORD'), 'Invalid constants behind Basic Auth: ' . json_encode($result));
                list($result, $headers) = $run($state, function () use ($ok) { return $ok; });
                sb_assert('warning' === $result['status'] && array('') === $headers, 'Invalid constants without Basic Auth: ' . json_encode($result));
            }
            // No answer at all: a warning that points to the render step.
            list($result) = $run($valid, function () { return new WP_Error('http_request_failed', 'cURL error 28: Operation timed out'); });
            sb_assert('warning' === $result['status'], 'A home that does not answer was not a warning.');
        } finally {
            $GLOBALS['sb_test_http_callback'] = null;
        }
    });
});

sb_test('Basic Auth (2.5.0): the credentials never reach Attività, errors, the Diagnostica, the CLI, the options or a static page', function () use ($pluginFile) {
    sb_group_c_isolated(function ($plugin) use ($pluginFile) {
        $expected = 'Basic ' . base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD);
        sb_ba_set($plugin, SB_BA_USER, SB_BA_PASSWORD);
        $outputs = array();
        try {
            // A run of the Diagnostica behind Basic Auth, with the results saved as the GUI saves them.
            $GLOBALS['sb_test_http_callback'] = sb_ba_server(array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>OK</html>'), $expected);
            foreach (array(array('id' => 'basic-auth', 'type' => 'basic-auth'), array('id' => 'render-origin', 'type' => 'render-origin'), array('id' => 'wp-admin', 'type' => 'admin')) as $step) {
                $outputs[] = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
            }
            // Errors of the HTTP layer and of the render, with and without the credentials.
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) { return new WP_Error('http_request_failed', 'cURL error 7: Failed to connect to ' . wp_parse_url($url, PHP_URL_HOST)); };
            $outputs[] = sb_private($plugin, 'fetch_page', array(home_url('/chi-siamo/'), 10));
            $outputs[] = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'basic-auth', 'type' => 'basic-auth'), array()));
            $GLOBALS['sb_test_http_callback'] = function () { return array('response' => array('code' => 401), 'headers' => array(), 'body' => ''); };
            $outputs[] = sb_private($plugin, 'fetch_page', array(home_url('/chi-siamo/'), 10));
            $outputs[] = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'basic-auth', 'type' => 'basic-auth'), array()));
            // The CLI: only the state.
            if (!class_exists('Static_Bridge_CLI', false)) {
                require_once dirname($pluginFile) . '/cli.php';
            }
            $status = $plugin->cli_status();
            sb_assert('on' === $status['basic_auth'], 'status does not say that Basic Auth is on.');
            $rows = sb_private(new Static_Bridge_CLI($plugin, function () {}), 'status_rows', array($status));
            sb_assert(in_array(array('field' => 'Basic Auth', 'value' => 'attiva'), $rows, true), 'The status table does not say «Basic Auth: attiva».');
            foreach (array(array('off', 'spenta'), array('invalid', 'costanti non valide')) as list($state, $label)) {
                $other = sb_private(new Static_Bridge_CLI($plugin, function () {}), 'status_rows', array(array_merge($status, array('basic_auth' => $state))));
                sb_assert(in_array(array('field' => 'Basic Auth', 'value' => $label), $other, true), 'The status table does not say «Basic Auth: ' . $label . '».');
            }
            $outputs[] = $status;
            $outputs[] = $rows;
            $outputs[] = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
            $outputs[] = $GLOBALS['sb_test_options'];
            $outputs[] = $GLOBALS['sb_test_actions_fired'] ?? array();
            $text = json_encode($outputs, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR, 64);
            $text .= serialize(array_map(function ($value) { return is_wp_error($value) ? $value->get_error_code() . ' ' . $value->get_error_message() : $value; }, $outputs));
            foreach (sb_ba_secrets() as $secret) {
                sb_assert(false === strpos($text, $secret), 'A credential reached the output, the options or Attività.');
            }

            // A page that shows the credentials (phpinfo(), a dump of the request headers) never enters the copy.
            $page = function ($body) {
                return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html><body>' . $body . '</body></html>');
            };
            foreach (array('HTTP_AUTHORIZATION ' . $expected, '<td>PHP_AUTH_PW</td><td>' . SB_BA_PASSWORD . '</td>', SB_BA_USER . ':' . SB_BA_PASSWORD) as $echo) {
                $refused = sb_private($plugin, 'parse_fetched_page', array(home_url('/info/'), $page($echo)));
                sb_assert(is_wp_error($refused) && 'static_bridge_basic_auth_echo' === $refused->get_error_code(), 'A page showing the credentials was accepted: ' . $echo);
                foreach (sb_ba_secrets() as $secret) {
                    sb_assert(false === strpos($refused->get_error_message(), $secret), 'The refusal shows a credential.');
                }
                sb_assert(!sb_private($plugin, 'is_retryable_export_error', array($refused)) && !sb_private($plugin, 'is_skippable_export_http_error', array($refused)), 'The refusal would be retried or skipped as a non-public page.');
            }
            $accepted = sb_private($plugin, 'parse_fetched_page', array(home_url('/info/'), $page('Autore: ' . SB_BA_USER)));
            sb_assert(is_array($accepted), 'A page that names the user only was refused.');
            sb_ba_set($plugin, SB_BA_USER, 'Corta');
            sb_assert(is_array(sb_private($plugin, 'parse_fetched_page', array(home_url('/info/'), $page('Una frase Corta.')))), 'A short password refused an ordinary page.');
            sb_ba_set($plugin, null, null);
            sb_assert(is_array(sb_private($plugin, 'parse_fetched_page', array(home_url('/info/'), $page('HTTP_AUTHORIZATION ' . $expected)))), 'Without Basic Auth a page was refused for text that is not a credential of this site.');
        } finally {
            $GLOBALS['sb_test_http_callback'] = null;
        }
    });
});

sb_test('Local Apache behind AuthType Basic: 401 without the constants, the export path and the Diagnostica pass with them', function () use ($fixtureRoot) {
    $httpd = getenv('STATIC_BRIDGE_APACHE_BIN');
    if (!$httpd || !is_executable($httpd) || !function_exists('proc_open') || !function_exists('curl_init')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN to run this Basic Auth check.');
    }
    $apache_root = dirname(dirname($httpd));
    $modules = $apache_root . '/modules';
    $needed = array('authz_core', 'authn_core', 'authn_file', 'auth_basic', 'authz_user', 'dir', 'mime', 'unixd', 'log_config');
    foreach ($needed as $module) {
        if (!is_file($modules . '/mod_' . $module . '.so')) {
            throw new SB_Test_Skip('Apache module mod_' . $module . ' is not available next to STATIC_BRIDGE_APACHE_BIN.');
        }
    }
    sb_group_c_isolated(function ($plugin) use ($fixtureRoot, $httpd, $apache_root, $modules, $needed) {
        $old_home = $GLOBALS['sb_test_home'];
        $port = sb_cf_free_port();
        $server_root = $fixtureRoot . '/apache-basic-auth-' . bin2hex(random_bytes(4));
        $docroot = $server_root . '/htdocs';
        $log_path = $server_root . '/error.log';
        $process = null;
        try {
            sb_assert(wp_mkdir_p($docroot), 'Could not create the Basic Auth docroot.');
            file_put_contents($docroot . '/index.html', 'BASIC_HOME');
            // Apache's {SHA} format, written here: no htpasswd binary and no system file.
            file_put_contents($server_root . '/htpasswd', SB_BA_USER . ':{SHA}' . base64_encode(sha1(SB_BA_PASSWORD, true)) . "\n");
            $load = '';
            foreach ($needed as $module) {
                $load .= 'LoadModule ' . $module . '_module "' . $modules . '/mod_' . $module . ".so\"\n";
            }
            $config = 'ServerRoot "' . $server_root . "\"\nListen 127.0.0.1:" . $port . "\nServerName 127.0.0.1\n"
                . 'PidFile "' . $server_root . "/httpd.pid\"\n" . 'DefaultRuntimeDir "' . $server_root . "\"\n" . 'Mutex file:' . $server_root . " default\n"
                . 'ErrorLog "' . $log_path . "\"\nLogLevel warn\n" . $load
                . "TypesConfig /dev/null\nAddType text/html .html\nDirectoryIndex index.html\n"
                . "<Directory />\n AllowOverride None\n Require all denied\n</Directory>\n"
                . 'DocumentRoot "' . $docroot . "\"\n"
                . '<Directory "' . $docroot . "\">\n AuthType Basic\n AuthName \"staging\"\n AuthBasicProvider file\n AuthUserFile \"" . $server_root . "/htpasswd\"\n Require valid-user\n</Directory>\n";
            file_put_contents($server_root . '/httpd.conf', $config);
            $environment = array('PATH' => (string) getenv('PATH'));
            if (is_dir($apache_root . '/shared-libs')) {
                $environment['LD_LIBRARY_PATH'] = $apache_root . '/shared-libs';
            }
            $process = proc_open(array($httpd, '-f', $server_root . '/httpd.conf', '-DFOREGROUND'), array(0 => array('file', '/dev/null', 'r'), 1 => array('file', $log_path, 'a'), 2 => array('file', $log_path, 'a')), $pipes, $server_root, $environment);
            sb_assert(is_resource($process), 'Could not start the Basic Auth Apache server.');
            $deadline = microtime(true) + 5;
            do {
                $probe = @fsockopen('127.0.0.1', $port, $errno, $errstr, 0.2);
                if ($probe) {
                    fclose($probe);
                    break;
                }
                usleep(100000);
            } while (microtime(true) < $deadline);

            $GLOBALS['sb_test_home'] = 'http://127.0.0.1:' . $port;
            $GLOBALS['sb_test_http_callback'] = 'sb_cf_curl_transport';
            $step = array('id' => 'basic-auth', 'type' => 'basic-auth');

            sb_ba_set($plugin, null, null);
            $plain = sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096));
            sb_assert(!is_wp_error($plain) && 401 === wp_remote_retrieve_response_code($plain), 'Apache did not ask for Basic Auth: ' . (is_wp_error($plain) ? $plain->get_error_message() : wp_remote_retrieve_response_code($plain)) . ' ' . @file_get_contents($log_path));
            $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
            sb_assert('fail' === $result['status'] && false !== strpos($result['remediation'], 'STATIC_BRIDGE_BASIC_AUTH_USER'), 'Apache 401 without constants: ' . json_encode($result));

            sb_ba_set($plugin, SB_BA_USER, 'Altra-Password-finta');
            $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
            sb_assert('fail' === $result['status'] && false !== strpos($result['summary'], 'sbagliati'), 'Apache with a wrong password: ' . json_encode($result));

            sb_ba_set($plugin, SB_BA_USER, SB_BA_PASSWORD);
            $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
            sb_assert('pass' === $result['status'], 'Apache with the right credentials: ' . json_encode($result));
            $home = sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, true));
            sb_assert(!is_wp_error($home) && 200 === wp_remote_retrieve_response_code($home) && 'BASIC_HOME' === wp_remote_retrieve_body($home), 'The render path did not pass Apache\'s Basic Auth.');

            // render_origin: the public name does not resolve, the connection goes to Apache's IP with the header.
            $GLOBALS['sb_test_home'] = 'http://basic-auth-apache.invalid:' . $port;
            sb_cf_settings(array('render_origin' => '127.0.0.1:' . $port));
            $origin = sb_private($plugin, 'remote_get', array(home_url('/'), 5, 4096, true));
            sb_assert(!is_wp_error($origin) && 200 === wp_remote_retrieve_response_code($origin) && 'BASIC_HOME' === wp_remote_retrieve_body($origin), 'The render through the origin address did not pass Apache\'s Basic Auth.');
        } finally {
            if (is_resource($process)) {
                proc_terminate($process);
                proc_close($process);
            }
            $GLOBALS['sb_test_home'] = $old_home;
            $GLOBALS['sb_test_http_callback'] = null;
        }
    });
});

sb_test('Basic Auth (2.5.0): the WP-Cron loopback carries the header only to this site and never follows a redirect', function () use ($source) {
    sb_assert(false !== strpos($source, "add_filter('cron_request', array(\$this, 'add_basic_auth_to_cron_request'), PHP_INT_MAX, 1);"), 'The cron_request filter is not registered.');
    sb_group_c_isolated(function ($plugin) {
        $expected = 'Basic ' . base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD);
        $cron = array(
            'url' => home_url('/wp-cron.php') . '?doing_wp_cron=1731420000.1234',
            'key' => '1731420000.1234',
            'args' => array('timeout' => 0.01, 'blocking' => false, 'sslverify' => false, 'headers' => array('X-Other' => 'kept')),
        );
        sb_ba_set($plugin, null, null);
        sb_assert($cron === $plugin->add_basic_auth_to_cron_request($cron), 'Without the constants the cron loopback changed.');
        sb_ba_set($plugin, SB_BA_USER, null);
        sb_assert($cron === $plugin->add_basic_auth_to_cron_request($cron), 'With invalid constants the cron loopback changed.');
        sb_ba_set($plugin, SB_BA_USER, SB_BA_PASSWORD);
        $filtered = $plugin->add_basic_auth_to_cron_request($cron);
        sb_assert($expected === sb_ba_header_of(array('args' => $filtered['args'])), 'The cron loopback did not carry the header.');
        sb_assert(0 === $filtered['args']['redirection'], 'The cron loopback with the header can follow a redirect.');
        sb_assert('kept' === $filtered['args']['headers']['X-Other'] && 0.01 === $filtered['args']['timeout'] && false === $filtered['args']['blocking']
            && $cron['url'] === $filtered['url'] && $cron['key'] === $filtered['key'], 'The filter lost the arguments of WP.');
        foreach (array('https://other.example.test/wp-cron.php?doing_wp_cron=1', 'http://news.example.test/wp-cron.php', '/wp-cron.php', '') as $foreign) {
            $moved = $cron;
            $moved['url'] = $foreign;
            sb_assert($moved === $plugin->add_basic_auth_to_cron_request($moved), 'The cron loopback carried the header to ' . $foreign);
        }
        foreach (array(null, 'x', array('args' => array()), array('url' => 42)) as $odd) {
            sb_assert($odd === $plugin->add_basic_auth_to_cron_request($odd), 'An odd cron_request value was changed.');
        }
    });
});

