const SB_MD_HOME = 'https://news.example.test:8443';

/** The converter module, as markdown_document() loads it on the first Markdown answer. */
function sb_md_module()
{
    global $pluginFile;
    if (!class_exists('Static_Bridge_Markdown')) {
        require_once dirname($pluginFile) . '/markdown.php';
    }
}

/**
 * Runs $callback($plugin, $root, $outside) with a static root of its own (sb_link_check_isolated()), the setting on,
 * a public page /chi-siamo/ (ID 101) queried by an anonymous GET ?format=markdown, and the request state restored.
 */
function sb_md_isolated($fixtureRoot, callable $callback)
{
    $saved = array($_GET, $_SERVER['REQUEST_METHOD'] ?? null, $_SERVER['REQUEST_URI'] ?? null, $GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_types'],
        $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_singular'] ?? null, $GLOBALS['sb_test_queried_object'] ?? null, $GLOBALS['sb_test_user_id'],
        $GLOBALS['sb_test_is_admin'], $GLOBALS['sb_test_filter_callbacks'] ?? array(), $GLOBALS['sb_test_wc_pages'] ?? array(), $GLOBALS['wp_query'] ?? null);
    try {
        sb_link_check_isolated($fixtureRoot, function ($plugin, $root, $outside) use ($callback) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 1, 'incremental_enabled' => 1, 'excluded_paths' => array('/esclusa/'), 'markdown_pages' => 1);
            $GLOBALS['sb_test_post_types'] = array(
                'post' => array('public' => true, 'publicly_queryable' => true),
                'page' => array('public' => true, 'publicly_queryable' => false),
                'attachment' => array('public' => true, 'publicly_queryable' => true),
                'evento' => array('public' => true, 'publicly_queryable' => true),
                'wp_block' => array('public' => true, 'publicly_queryable' => true),
            );
            $GLOBALS['sb_test_posts'] = array();
            $GLOBALS['sb_test_post_urls'] = array();
            $GLOBALS['sb_test_md_modified'] = array();
            $GLOBALS['sb_test_wc_pages'] = array();
            $GLOBALS['sb_test_filter_callbacks'] = array();
            $GLOBALS['sb_test_user_id'] = 0;
            $GLOBALS['sb_test_is_admin'] = false;
            $GLOBALS['wp_query'] = (object) array('posts' => array());
            sb_md_page($plugin, 101, array());
            $callback($plugin, $root, $outside);
        });
    } finally {
        list($_GET, $method, $uri, $GLOBALS['sb_test_posts'], $GLOBALS['sb_test_post_types'], $GLOBALS['sb_test_post_urls'], $GLOBALS['sb_test_singular'],
            $GLOBALS['sb_test_queried_object'], $GLOBALS['sb_test_user_id'], $GLOBALS['sb_test_is_admin'], $GLOBALS['sb_test_filter_callbacks'],
            $GLOBALS['sb_test_wc_pages'], $GLOBALS['wp_query']) = $saved;
        if (null === $method) {
            unset($_SERVER['REQUEST_METHOD']);
        } else {
            $_SERVER['REQUEST_METHOD'] = $method;
        }
        if (null === $uri) {
            unset($_SERVER['REQUEST_URI']);
        } else {
            $_SERVER['REQUEST_URI'] = $uri;
        }
        $GLOBALS['sb_test_md_flags'] = array();
        $GLOBALS['sb_test_md_modified'] = array();
    }
}

/** Makes $id the queried content of a GET ?format=markdown: a public page /chi-siamo/ unless $fields say otherwise. */
function sb_md_page($plugin, $id, array $fields, array $flags = array())
{
    $post = array_merge(array('ID' => $id, 'post_type' => 'page', 'post_status' => 'publish', 'post_password' => '', 'post_name' => 'chi-siamo',
        'post_title' => 'Chi "siamo" & noi', 'post_content' => '<p>Dal <strong>contenuto</strong> con un <a href="/contatti/">link</a>.</p>'), $fields);
    $GLOBALS['sb_test_posts'] = array_values(array_filter($GLOBALS['sb_test_posts'], function ($row) use ($id) { return (int) $row['ID'] !== (int) $id; }));
    $GLOBALS['sb_test_posts'][] = $post;
    $GLOBALS['sb_test_post_urls'][$id] = home_url('/' . $post['post_name'] . '/');
    $GLOBALS['sb_test_md_modified'][$id] = 1794477600; // 2026-11-12T10:00:00+00:00
    $GLOBALS['sb_test_singular'] = true;
    $GLOBALS['sb_test_queried_object'] = new WP_Post($post);
    $GLOBALS['sb_test_md_flags'] = $flags;
    $_GET = array('format' => 'markdown');
    $_SERVER['REQUEST_METHOD'] = 'GET';
    $_SERVER['REQUEST_URI'] = '/' . $post['post_name'] . '/?format=markdown';
    return $GLOBALS['sb_test_queried_object'];
}

/** The <link> wp_head prints. */
function sb_md_head($plugin)
{
    ob_start();
    $plugin->print_markdown_alternate_link();
    return (string) ob_get_clean();
}

sb_test('Markdown (2.5.0): off by default, no answer and no <link>; only a GET or HEAD of the public site with ?format=markdown', function () use ($fixtureRoot, $source) {
    foreach (array("add_filter('determine_current_user', array(\$this, 'markdown_request_user'), PHP_INT_MAX, 1);",
        "add_action('template_redirect', array(\$this, 'maybe_serve_markdown'), self::MARKDOWN_PRIORITY);",
        "add_action('wp_head', array(\$this, 'print_markdown_alternate_link'), 9);",
        "'markdown_pages' => isset(\$_POST['markdown_pages']) ? 1 : 0,") as $needle) {
        sb_assert(false !== strpos($source, $needle), 'Missing in the plugin: ' . $needle);
    }
    sb_assert(Static_Bridge_Plugin::MARKDOWN_PRIORITY > 10, 'The Markdown answer runs before redirect_canonical.');
    sb_md_isolated($fixtureRoot, function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0);
        sb_assert(0 === sb_private($plugin, 'settings')['markdown_pages'], 'The Markdown version is on by default.');
        sb_assert(null === sb_private($plugin, 'markdown_response'), 'Setting off: a Markdown answer.');
        sb_assert('' === sb_md_head($plugin), 'Setting off: a <link> in the page.');
        sb_assert(7 === $plugin->markdown_request_user(7), 'Setting off: the user was dropped.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['markdown_pages'] = 1;
        sb_assert(1 === sb_private($plugin, 'settings')['markdown_pages'], 'The setting is not read.');
        sb_assert(is_array(sb_private($plugin, 'markdown_response')), 'Setting on: no answer to a GET ?format=markdown.');
        $refused = array(
            'no format' => function () { $_GET = array(); },
            'format=Markdown' => function () { $_GET = array('format' => 'Markdown'); },
            'format=md' => function () { $_GET = array('format' => 'md'); },
            'format as array' => function () { $_GET = array('format' => array('markdown')); },
            'POST' => function () { $_SERVER['REQUEST_METHOD'] = 'POST'; },
            'PUT' => function () { $_SERVER['REQUEST_METHOD'] = 'PUT'; },
            'wp-admin' => function () { $GLOBALS['sb_test_is_admin'] = true; },
            'REST path' => function () { $_SERVER['REQUEST_URI'] = '/wp-json/wp/v2/posts?format=markdown'; },
            'rest_route' => function () { $_GET['rest_route'] = '/wp/v2/posts'; },
        );
        foreach ($refused as $label => $change) {
            sb_md_page($plugin, 101, array());
            $GLOBALS['sb_test_is_admin'] = false;
            $change();
            sb_assert(null === sb_private($plugin, 'markdown_response'), 'Answered in Markdown: ' . $label);
            sb_assert(7 === $plugin->markdown_request_user(7), 'The user was dropped for: ' . $label);
        }
        $GLOBALS['sb_test_is_admin'] = false;
        sb_md_page($plugin, 101, array());
        $_SERVER['REQUEST_METHOD'] = 'HEAD';
        $head = sb_private($plugin, 'markdown_response');
        sb_assert(is_array($head) && 200 === $head['status'], 'A HEAD was not answered like the GET.');
    });
});

sb_test('Markdown (2.5.0): a public page answers text/markdown with front matter, canonical Link, noindex and a short public cache; the <link> stays absolute in the copy', function () use ($fixtureRoot) {
    sb_md_isolated($fixtureRoot, function ($plugin) {
        $response = sb_private($plugin, 'markdown_response');
        $url = SB_MD_HOME . '/chi-siamo/';
        sb_assert(200 === $response['status'], 'Status ' . $response['status']);
        sb_assert(array(
            'Content-Type' => 'text/markdown; charset=utf-8',
            'Cache-Control' => 'public, max-age=300',
            'Link' => '<' . $url . '>; rel="canonical"',
            'X-Robots-Tag' => 'noindex',
            'X-Content-Type-Options' => 'nosniff',
        ) === $response['headers'], 'Headers: ' . json_encode($response['headers']));
        $expected = "---\ntitle: \"Chi \\\"siamo\\\" & noi\"\nurl: \"" . $url . "\"\nlang: \"it-IT\"\nmodified: \"2026-11-12T10:00:00+00:00\"\n---\n\n"
            . "# Chi \"siamo\" & noi\n\nDal **contenuto** con un [link](" . SB_MD_HOME . "/contatti/).\n";
        sb_assert($expected === $response['body'], "Body:\n" . $response['body']);
        sb_assert(defined('DONOTCACHEPAGE') && DONOTCACHEPAGE, 'Page caches may keep the Markdown answer as the page.');

        // The front matter survives a title that tries to close it.
        sb_md_page($plugin, 101, array('post_title' => "Uno\n---\nadmin: true"));
        $body = sb_private($plugin, 'markdown_response')['body'];
        sb_assert(0 === strpos($body, "---\ntitle: \"Uno --- admin: true\"\nurl: "), 'The title broke the front matter: ' . $body);

        sb_md_page($plugin, 101, array());
        $GLOBALS['sb_test_singular'] = true;
        $_GET = array();
        $link = sb_md_head($plugin);
        sb_assert('<link rel="alternate" type="text/markdown" href="' . $url . '?format=markdown" />' . "\n" === $link, 'The <link> in wp_head: ' . $link);
        $copy = sb_private($plugin, 'rewrite_internal_origins_as_root_relative', array('<html><head>' . trim($link) . '</head><body><a href="' . $url . '">x</a></body></html>'));
        sb_assert(false !== strpos($copy, 'href="' . $url . '?format=markdown"') && false !== strpos($copy, '<a href="/chi-siamo/">'), 'The <link> is not kept absolute in the copy: ' . $copy);
        sb_assert(!in_array($url . '?format=markdown', sb_private($plugin, 'html_link_hrefs', array($copy, true)), true), 'The export would follow the Markdown address.');

        // A home page that lists posts and has no copy: the site name and the public posts as links.
        $GLOBALS['sb_test_singular'] = false;
        $GLOBALS['sb_test_queried_object'] = null;
        $GLOBALS['sb_test_md_flags'] = array('is_front_page' => true, 'is_home' => true);
        $_GET = array('format' => 'markdown');
        $GLOBALS['sb_test_posts'][] = array('ID' => 102, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_name' => 'notizia', 'post_title' => 'Una notizia');
        $GLOBALS['sb_test_posts'][] = array('ID' => 103, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => 'x', 'post_name' => 'riservata', 'post_title' => 'Riservata');
        $GLOBALS['sb_test_post_urls'][102] = home_url('/notizia/');
        $GLOBALS['wp_query'] = (object) array('posts' => array(new WP_Post($GLOBALS['sb_test_posts'][1]), new WP_Post($GLOBALS['sb_test_posts'][2])));
        $home = sb_private($plugin, 'markdown_response');
        sb_assert(200 === $home['status'] && '<' . SB_MD_HOME . '/>; rel="canonical"' === $home['headers']['Link'], 'The home page was not answered: ' . json_encode($home));
        sb_assert(false !== strpos($home['body'], "title: \"Notizie & co\"") && false !== strpos($home['body'], "# Notizie & co\n\nIl giornale del paese\n\n- [Una notizia](" . SB_MD_HOME . "/notizia/)")
            && false === strpos($home['body'], 'Riservata'), 'Home page: ' . $home['body']);
    });
});

sb_test('Markdown (2.5.0): drafts, private, password, attachments, archives, search, 404, feeds, previews and paged views get the same bare 404, logged in or not', function () use ($fixtureRoot) {
    sb_md_isolated($fixtureRoot, function ($plugin) {
        $bare = array(
            'status' => 404,
            'headers' => array('Content-Type' => 'text/plain; charset=utf-8', 'Cache-Control' => 'no-store, max-age=0', 'X-Robots-Tag' => 'noindex', 'X-Content-Type-Options' => 'nosniff'),
            'body' => "Pagina non trovata.\n",
        );
        $cases = array(
            'draft' => array(array('post_status' => 'draft'), array()),
            'pending' => array(array('post_status' => 'pending'), array()),
            'scheduled' => array(array('post_status' => 'future'), array()),
            'private' => array(array('post_status' => 'private'), array()),
            'trash' => array(array('post_status' => 'trash'), array()),
            'password' => array(array('post_password' => 'segreta'), array()),
            'attachment' => array(array('post_type' => 'attachment', 'post_status' => 'publish'), array('is_attachment' => true)),
            'template' => array(array('post_type' => 'wp_block'), array()),
            'unknown type' => array(array('post_type' => 'privato_cpt'), array()),
            'preview' => array(array(), array('is_preview' => true)),
            'second page of a post' => array(array(), array('vars' => array('page' => 2))),
            'comments page' => array(array(), array('vars' => array('cpage' => 3))),
            'embed' => array(array(), array('is_embed' => true)),
            'feed' => array(array(), array('is_feed' => true)),
            'trackback' => array(array(), array('is_trackback' => true)),
        );
        foreach (array(false, true) as $logged_in) {
            foreach ($cases as $label => $case) {
                sb_md_page($plugin, 101, $case[0], $case[1]);
                $GLOBALS['sb_test_user_id'] = $logged_in ? 7 : 0;
                $response = sb_private($plugin, 'markdown_response');
                sb_assert($bare === $response, ($logged_in ? 'Logged in, ' : '') . $label . ': ' . json_encode($response));
            }
            foreach (array('archive' => array(), 'search' => array('is_search' => true), '404' => array('is_404' => true),
                'paged home' => array('is_front_page' => true, 'is_home' => true, 'is_paged' => true), 'blog page' => array('is_home' => true)) as $label => $flags) {
                sb_md_page($plugin, 101, array(), $flags);
                $GLOBALS['sb_test_singular'] = false;
                $GLOBALS['sb_test_queried_object'] = null;
                $GLOBALS['sb_test_user_id'] = $logged_in ? 7 : 0;
                sb_assert($bare === sb_private($plugin, 'markdown_response'), ($logged_in ? 'Logged in, ' : '') . $label . ' was answered.');
                sb_assert('' === sb_md_head($plugin), 'A <link> on ' . $label);
            }
        }
        // WooCommerce: the cart, the checkout and the account show one visitor's session.
        foreach (array('cart', 'checkout', 'myaccount') as $page) {
            sb_md_page($plugin, 101, array());
            $GLOBALS['sb_test_wc_pages'] = array($page => 101);
            sb_assert($bare === sb_private($plugin, 'markdown_response'), 'The WooCommerce ' . $page . ' page was answered.');
            $GLOBALS['sb_test_wc_pages'] = array();
        }

        // A logged-in visitor gets exactly what an anonymous one gets, even where the_content would show more.
        $GLOBALS['sb_test_filter_callbacks']['the_content'] = function ($content) {
            return $content . (0 !== get_current_user_id() ? '<p>RISERVATO AI MEMBRI</p>' : '');
        };
        sb_md_page($plugin, 101, array());
        $anonymous = sb_private($plugin, 'markdown_response');
        sb_md_page($plugin, 101, array());
        $GLOBALS['sb_test_user_id'] = 7;
        sb_assert(0 === $plugin->markdown_request_user(7), 'determine_current_user keeps the user of a Markdown request.');
        $logged = sb_private($plugin, 'markdown_response');
        sb_assert(0 === get_current_user_id(), 'The Markdown request still runs as the logged-in user.');
        sb_assert($anonymous === $logged && false === strpos($logged['body'], 'RISERVATO'), 'A logged-in visitor got something else: ' . $logged['body']);
        // A page shown to logged-in users only has no <link>: the visitor would get a 404.
        sb_md_page($plugin, 101, array('post_status' => 'private'));
        $_GET = array();
        $GLOBALS['sb_test_user_id'] = 7;
        sb_assert('' === sb_md_head($plugin), 'A private page announces a Markdown version.');
    });
});

sb_test('Markdown (2.5.0): the text comes from the fresh copy in the release, from the_content otherwise, never through a symlink', function () use ($fixtureRoot) {
    sb_md_isolated($fixtureRoot, function ($plugin, $root, $outside) {
        $copy = '<!doctype html><html lang="it-IT"><head><title>T</title><script>var n="COPIA_NONCE";</script></head><body>'
            . '<header><nav><a href="/">Menu</a></nav></header><main><h1>Dalla copia</h1><p>Testo <span class="sb-relative" data-sb-since="1" data-sb-to="2">3 ore fa</span> e <a href="/altro/">altro</a>.</p>'
            . '<form><input type="hidden" name="_wpnonce" value="COPIA_NONCE"></form></main><footer>Piede</footer></body></html>';
        $release = sb_link_check_release($root, 'md-release', array('/' => '<html><body><main><h1>Home</h1></main></body></html>', '/chi-siamo/' => $copy));
        $file = $release . '/chi-siamo/index.html';
        touch($file, 1794477600 + 60);
        $body = sb_private($plugin, 'markdown_response')['body'];
        sb_assert(false !== strpos($body, "# Dalla copia\n\nTesto 3 ore fa e [altro](" . SB_MD_HOME . '/altro/).') && false === strpos($body, 'Dal **contenuto**'),
            'The fresh copy was not used: ' . $body);
        foreach (array('COPIA_NONCE', 'Menu', 'Piede', '<form', '<script', 'data-sb') as $leak) {
            sb_assert(false === strpos($body, $leak), 'Leaked from the copy: ' . $leak);
        }
        // A content changed after its copy: the_content has the newer text.
        touch($file, 1794477600 - 60);
        sb_assert(false !== strpos(sb_private($plugin, 'markdown_response')['body'], 'Dal **contenuto**'), 'A stale copy was used.');
        touch($file, 1794477600 + 60);
        // A path kept with WP (excluded, a form, the editor checkbox): its copy is not what visitors see.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array('/chi-siamo/');
        sb_assert(false !== strpos(sb_private($plugin, 'markdown_response')['body'], 'Dal **contenuto**'), 'The copy of an excluded path was used.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array();
        // Too large for the reader.
        file_put_contents($file, str_repeat('x', Static_Bridge_Markdown::MAX_HTML_BYTES + 1));
        touch($file, 1794477600 + 60);
        sb_assert(false !== strpos(sb_private($plugin, 'markdown_response')['body'], 'Dal **contenuto**'), 'An oversized copy was read.');
        // A symlink below the release, to a folder or to a file outside it, is never followed.
        file_put_contents($outside . '/index.html', '<main><h1>FUORI DALLA RELEASE</h1></main>');
        touch($outside . '/index.html', 1794477600 + 60);
        sb_retention_remove_tree($release . '/chi-siamo');
        sb_assert(symlink($outside, $release . '/chi-siamo'), 'Could not create the folder symlink.');
        $body = sb_private($plugin, 'markdown_response')['body'];
        sb_assert(false === strpos($body, 'FUORI') && false !== strpos($body, 'Dal **contenuto**'), 'A folder symlink was followed: ' . $body);
        unlink($release . '/chi-siamo');
        mkdir($release . '/chi-siamo');
        sb_assert(symlink($outside . '/index.html', $file), 'Could not create the file symlink.');
        $body = sb_private($plugin, 'markdown_response')['body'];
        sb_assert(false === strpos($body, 'FUORI') && false !== strpos($body, 'Dal **contenuto**'), 'A file symlink was followed: ' . $body);
        // No release: the_content; a PHP error printed by the_content is never shown.
        unlink($root . '/current');
        sb_assert(false !== strpos(sb_private($plugin, 'markdown_response')['body'], 'Dal **contenuto**'), 'Without a release the_content was not used.');
        $GLOBALS['sb_test_filter_callbacks']['the_content'] = function ($content) {
            return $content . "<br />\n<b>Warning</b>:  Undefined variable \$x in <b>/var/www/html/wp-content/themes/t/functions.php</b> on line <b>12</b><br />";
        };
        sb_assert(404 === sb_private($plugin, 'markdown_response')['status'], 'A page with a PHP warning was turned into Markdown.');
        $GLOBALS['sb_test_filter_callbacks']['the_content'] = function ($content) {
            echo 'ECO DI UNO SHORTCODE';
            throw new RuntimeException('the_content failed');
        };
        ob_start();
        $failed = sb_private($plugin, 'markdown_response');
        $echoed = ob_get_clean();
        sb_assert(404 === $failed['status'] && '' === $echoed, 'An exception of the_content: ' . json_encode($failed) . ' ' . $echoed);
    });
});

sb_test('Markdown (2.5.0): the conversion keeps the text and the structure, makes links absolute, drops scripts, forms and nonces, and escapes the specials', function () {
    sb_md_module();
    $html = '<!DOCTYPE html><html lang="it-IT"><head><title>T</title><meta name="x" content="y"><script>var nonce="SCRIPT_NONCE";</script></head>'
        . '<body><a class="skip-link screen-reader-text" href="#content">Salta</a><header class="site-header"><nav><a href="/">Home</a></nav><p>Testata</p></header>'
