MD;
    $options = array('url' => SB_MD_HOME . '/blog/articolo/', 'origin' => SB_MD_HOME);
    $parsers = array('tokenizer' => true);
    if (class_exists('DOMDocument')) {
        $parsers['DOMDocument'] = false;
    }
    foreach ($parsers as $label => $tokenizer) {
        $result = Static_Bridge_Markdown::convert($html, $options + array('tokenizer' => $tokenizer));
        sb_assert($expected === $result['markdown'], $label . " gave:\n" . $result['markdown']);
        sb_assert(false === $result['truncated'] && 'it-IT' === $result['lang'], $label . ': ' . json_encode(array($result['truncated'], $result['lang'])));
        foreach (array('NONCE', 'TESTO_FORM', 'MODULO_TESTO', 'Invia', 'Testata', 'Sidebar', 'Copyright', 'Salta', 'nascosto', 'icona', 'invisibile', 'Popup', 'javascript', 'data:', '#include') as $leak) {
            sb_assert(false === strpos($result['markdown'], $leak), $label . ' kept ' . $leak);
        }
    }
    // Without <main>: the only <article>; several articles or none: <body> without the site's header and footer.
    $one = Static_Bridge_Markdown::convert('<body><header>Testata</header><div>Fuori</div><article><header><h2>Dentro</h2></header><p>Corpo</p></article></body>', $options + array('tokenizer' => true));
    sb_assert("## Dentro\n\nCorpo\n" === $one['markdown'], 'One article: ' . $one['markdown']);
    $body = Static_Bridge_Markdown::convert('<body><header>Testata</header><article><p>A</p></article><article><p>B</p></article><footer>Piede</footer></body>', $options + array('tokenizer' => true));
    sb_assert("A\n\nB\n" === $body['markdown'], 'Body: ' . $body['markdown']);
    // An unclosed <p> and <li>, as the HTML parser closes them.
    $loose = Static_Bridge_Markdown::convert('<p>Uno<p>Due<ul><li>a<li>b</ul><table><tr><td>1<td>2<tr><td>3<td>4</table>', $options + array('tokenizer' => true));
    sb_assert("Uno\n\nDue\n\n- a\n- b\n\n| 1 | 2 |\n| --- | --- |\n| 3 | 4 |\n" === $loose['markdown'], 'Implied end tags: ' . $loose['markdown']);
});

sb_test('Markdown (2.5.0): the limits of HTML read, Markdown written, depth and time cut the text with [...]', function () {
    sb_md_module();
    $options = array('url' => SB_MD_HOME . '/a/', 'origin' => SB_MD_HOME, 'tokenizer' => true);
    $paragraphs = str_repeat('<p>' . str_repeat('parola ', 20) . '</p>', 100);
    $small = Static_Bridge_Markdown::convert($paragraphs, $options + array('max_bytes' => 1000));
    sb_assert($small['truncated'] && strlen($small['markdown']) <= 1000 + 10 && "[…]\n" === substr($small['markdown'], -strlen("[…]\n"))
        && 0 === strpos($small['markdown'], 'parola parola'), 'The Markdown limit: ' . strlen($small['markdown']) . ' ' . substr($small['markdown'], -40));
    $huge = Static_Bridge_Markdown::convert('<p>' . str_repeat('é', Static_Bridge_Markdown::MAX_HTML_BYTES) . '</p><p>DOPO_IL_LIMITE</p>', $options + array('max_bytes' => 4 * Static_Bridge_Markdown::MAX_HTML_BYTES));
    sb_assert($huge['truncated'] && false === strpos($huge['markdown'], 'DOPO_IL_LIMITE') && preg_match('//u', $huge['markdown']), 'The HTML limit.');
    $deep = Static_Bridge_Markdown::convert(str_repeat('<div>', 30) . '<p>Profondo <a href="/x/">link</a></p>' . str_repeat('</div>', 30), $options + array('max_depth' => 10));
    sb_assert("Profondo link\n" === $deep['markdown'], 'Below the depth limit the text was not plain: ' . $deep['markdown']);
    $late = Static_Bridge_Markdown::convert($paragraphs, $options + array('deadline' => microtime(true) - 1));
    sb_assert($late['truncated'] && "[…]\n" === $late['markdown'], 'Out of time: ' . substr($late['markdown'], 0, 60));
    $nodes = Static_Bridge_Markdown::convert(str_repeat('<b>x</b>', Static_Bridge_Markdown::MAX_NODES), $options);
    sb_assert($nodes['truncated'], 'The node limit did not cut the page.');
    $tags = Static_Bridge_Markdown::convert(str_repeat('<span>', Static_Bridge_Markdown::MAX_OPEN_ELEMENTS + 50) . 'fondo' . str_repeat('</span>', Static_Bridge_Markdown::MAX_OPEN_ELEMENTS + 50) . '<p>dopo</p>', $options);
    sb_assert("fondo\n\ndopo\n" === $tags['markdown'], 'Too many open elements: ' . $tags['markdown']);
});

sb_test('Markdown (2.5.0): the public filters take only their type and survive an exception', function () use ($fixtureRoot) {
    sb_md_isolated($fixtureRoot, function ($plugin) {
        $plain = sb_private($plugin, 'markdown_response');
        sb_assert(200 === $plain['status'], 'No answer without filters.');
        foreach (array('false' => false, 'one' => 1, 'string' => 'yes', 'array' => array(true), 'null' => null) as $label => $value) {
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_enabled'] = function ($enabled, $post) use ($value) {
                return $value;
            };
            sb_assert(404 === sb_private($plugin, 'markdown_response')['status'], 'static_bridge_markdown_enabled ' . $label . ' served the page.');
        }
        $seen = array();
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_enabled'] = function ($enabled, $post) use (&$seen) {
            $seen[] = array($enabled, $post instanceof WP_Post ? $post->ID : null);
            return true;
        };
        sb_assert($plain === sb_private($plugin, 'markdown_response') && array(array(true, 101)) === $seen, 'static_bridge_markdown_enabled true: ' . json_encode($seen));
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_enabled'] = function () {
            throw new RuntimeException('filter failed');
        };
        sb_assert(404 === sb_private($plugin, 'markdown_response')['status'], 'An exception of static_bridge_markdown_enabled served the page.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_enabled']);

        $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown'] = function ($markdown, $post) {
            return $markdown . "\nAggiunto per il post " . $post->ID . "\n";
        };
        sb_assert($plain['body'] . "\nAggiunto per il post 101\n" === sb_private($plugin, 'markdown_response')['body'], 'static_bridge_markdown did not change the text.');
        foreach (array('array' => array('x'), 'number' => 42, 'null' => null, 'empty' => '', 'invalid UTF-8' => "\xC3\x28",
            'too large' => str_repeat('x', Static_Bridge_Markdown::MAX_DOCUMENT_BYTES + 1)) as $label => $value) {
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown'] = function () use ($value) {
                return $value;
            };
            sb_assert($plain === sb_private($plugin, 'markdown_response'), 'static_bridge_markdown ' . $label . ' was accepted.');
        }
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown'] = function () {
            throw new RuntimeException('filter failed');
        };
        sb_assert($plain === sb_private($plugin, 'markdown_response'), 'An exception of static_bridge_markdown changed the answer.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown']);

        foreach (array(array(60, 'public, max-age=60'), array(0, 'no-cache, max-age=0'), array(86400, 'public, max-age=86400'),
            array('60', 'public, max-age=300'), array(-1, 'public, max-age=300'), array(86401, 'public, max-age=300'), array(1.5, 'public, max-age=300')) as $case) {
            $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_max_age'] = function () use ($case) {
                return $case[0];
            };
            sb_assert($case[1] === sb_private($plugin, 'markdown_response')['headers']['Cache-Control'], 'static_bridge_markdown_max_age ' . var_export($case[0], true));
        }
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_markdown_max_age'] = function () {
            throw new RuntimeException('filter failed');
        };
        sb_assert('public, max-age=300' === sb_private($plugin, 'markdown_response')['headers']['Cache-Control'], 'An exception of static_bridge_markdown_max_age.');
    });
});

sb_test('Basic Auth (2.5.0): the two constants of wp-config.php are read as they are defined', function () {
    // Last, and in a plugin of its own: the constants stay defined for the rest of this process.
    sb_group_c_isolated(function ($plugin) {
        sb_assert('off' === sb_private($plugin, 'basic_auth_state'), 'Basic Auth is on without the constants.');
        sb_assert(array() === sb_private($plugin, 'self_request_auth_headers', array(home_url('/'))), 'A header without the constants.');
    });
    define('STATIC_BRIDGE_BASIC_AUTH_USER', SB_BA_USER);
    define('STATIC_BRIDGE_BASIC_AUTH_PASSWORD', SB_BA_PASSWORD);
    sb_group_c_isolated(function ($plugin) {
        sb_assert('on' === sb_private($plugin, 'basic_auth_state'), 'Valid constants did not turn Basic Auth on.');
        sb_assert(array('Authorization' => 'Basic ' . base64_encode(SB_BA_USER . ':' . SB_BA_PASSWORD)) === sb_private($plugin, 'self_request_auth_headers', array(home_url('/'))), 'The constants did not give the header.');
        sb_assert(array() === sb_private($plugin, 'self_request_auth_headers', array('https://other.example.test/')), 'The constants gave the header for another host.');
    });
});

/** Runs $callback with the settings of the suite and the filters of the two 2.5.0 guard options restored afterwards. */
function sb_guard_isolated(callable $callback)
{
    $saved = array($GLOBALS['sb_test_options'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_filter_callbacks'] ?? array(),
        isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : null, $GLOBALS['sb_test_http_callback'], $_POST);
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::FORM_MODES_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    try {
        $callback(new Static_Bridge_Plugin());
    } finally {
        list($GLOBALS['sb_test_options'], $GLOBALS['sb_test_filter_values'], $GLOBALS['sb_test_filter_callbacks'], $server, $GLOBALS['sb_test_http_callback'], $_POST) = $saved;
        if (null === $server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $server;
        }
    }
}

sb_test('Tracking parameters (2.5.0): off by default the rules are as before; on, only a query of listed names, compared with case, gets the copy', function () {
    sb_guard_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 1, 'excluded_paths' => array('/iscriviti/'));
        $settings = sb_private($plugin, 'settings');
        sb_assert(0 === $settings['ignore_tracking_params'] && array() === sb_private($plugin, 'tracking_param_names'), 'The tracking parameters are not off by default.');
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache_off = sb_private($plugin, 'rewrite_block');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx_off = sb_private($plugin, 'nginx_router_block');
        sb_assert(3 === substr_count($apache_off, "RewriteCond %{QUERY_STRING} ^$\n"), 'Off, the Apache guard is no longer «^$» before the home, route and Strict rules.');
        sb_assert(2 === substr_count($nginx_off, 'if ($args != "") { return 418; }') && false === strpos($nginx_off, '$args !~'), 'Off, the Nginx block is no longer «$args != ""».');
        sb_assert('' === sb_private($plugin, 'tracking_query_pattern'), 'Off, a tracking expression is written.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['ignore_tracking_params'] = 1;
        $names = sb_private($plugin, 'tracking_param_names');
        sb_assert(Static_Bridge_Plugin::TRACKING_PARAMS_DEFAULT === $names, 'On, the default list is not the documented one: ' . implode(',', $names));
        $pattern = sb_private($plugin, 'tracking_query_pattern');
        $long = 'utm_source=' . str_repeat('a', 2100);
        $cases = array(
            '' => true, 'utm_source=x' => true, 'utm_source=x&fbclid=y' => true, 'utm_campaign=autunno%202026&utm_medium=email&mc_cid=ab12&mc_eid=cd34' => true,
            'utm_source=' => true, '_gl=1*abc*_ga*MTIz.456' => true, 'gclid=Cj0KC-x_y' => true, 'utm_source=x%26p%3D1' => true,
            // Repeated: PHP keeps the last value and WP renders the same page; the file served never depends on it.
            'fbclid=a&fbclid=b' => true,
            'utm_source=x&p=1' => false, 'p=1&utm_source=x' => false, '%75tm_source=x' => false, 'utm_source[]=x' => false, 'utm_source%5B%5D=x' => false,
            'utm_source=x&&fbclid=y' => false, '=' => false, '&' => false, '=x' => false, 'utm_source' => false, 'utm_source=x&' => false, '&utm_source=x' => false,
            'UTM_SOURCE=x' => false, 'Fbclid=x' => false, 'utm_=x' => false, 'utm_source=a;p=1' => false, 'utm_source=a=b' => false, 'utm_source=a b' => false,
            'format=markdown' => false, 'utm_source=x&format=markdown' => false, 'static_bridge_bypass=1' => false, 'utm_source=x&static_bridge_bypass=1' => false,
            "utm_source=x\nfoo" => false, 'utm_source="x"' => false, 'utm_source=x#y' => false, $long => false,
        );
        foreach ($cases as $query => $copy) {
            sb_assert($copy === (bool) preg_match('#' . $pattern . '#', (string) $query), 'The tracking expression decides «' . substr((string) $query, 0, 60) . '» wrongly.');
        }
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache_on = sb_private($plugin, 'rewrite_block');
        sb_assert(false === strpos($apache_on, "RewriteCond %{QUERY_STRING} ^$\n") && substr_count($apache_on, 'RewriteCond %{QUERY_STRING} ' . $pattern . "\n") === substr_count($apache_off, "RewriteCond %{QUERY_STRING} ^$\n"),
            'On, the Apache guard does not carry the tracking expression in place of «^$» before every rule.');
        sb_assert(str_replace('RewriteCond %{QUERY_STRING} ' . $pattern . "\n", "RewriteCond %{QUERY_STRING} ^$\n", $apache_on) === $apache_off, 'On, the Apache block changes more than the query condition.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx_on = sb_private($plugin, 'nginx_router_block');
        sb_assert(2 === substr_count($nginx_on, 'if ($args !~ "' . $pattern . '") { return 418; }') && false === strpos($nginx_on, '$args != ""'), 'On, the Nginx block does not test $args with the expression in both locations.');
        sb_assert(false === strpos($pattern, '"') && false === strpos($pattern, ' ') && false === strpos($pattern, '{ ') && false === strpos($pattern, '\\t'), 'The expression holds a character that ends an argument.');
        sb_assert(false !== strpos(sb_private($plugin, 'cloudflare_cache_rule_expression'), 'http.request.uri.query eq ""'), 'The Cloudflare rule no longer asks for an empty query.');

        // The link check after a publication decides as the rules.
        $rules = sb_private($plugin, 'link_check_rules');
        sb_assert('/chi-siamo/' === sb_private($plugin, 'link_check_route', array(home_url('/chi-siamo/?utm_source=x&fbclid=y'), $rules)), 'The link check sends a tracking query to WP.');
        sb_assert('' === sb_private($plugin, 'link_check_route', array(home_url('/chi-siamo/?utm_source=x&p=1'), $rules)), 'The link check serves a query with another parameter.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['ignore_tracking_params'] = 0;
        sb_assert('' === sb_private($plugin, 'link_check_route', array(home_url('/chi-siamo/?utm_source=x'), sb_private($plugin, 'link_check_rules'))), 'Off, the link check serves a tracking query.');
    });
});

sb_test('Tracking parameters (2.5.0): the filter cannot add a name or prefix that WP, a plugin or Static Bridge reads, nor a character outside [A-Za-z0-9_-]', function () {
    sb_guard_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('ignore_tracking_params' => 1);
        $GLOBALS['sb_test_filter_callbacks']['query_vars'] = function ($vars) {
            return array_merge((array) $vars, array('lang', 'wc-api'));
        };
        $GLOBALS['sb_test_filter_values']['static_bridge_tracking_params'] = array(
            'p', 's', 'S', 'format', 'preview', 'page_id', 'rest_route', 'lang', 'wc-api', 'static_bridge_bypass', 'static_bridge_x',
            'post_*', 'page_*', 'pa*', 'static_*', 'stat*', 'p_*', '*', '_*', 'utm*',
            'x y', 'evil"x', 'a;b', 'a$b', 'a.b', 'a[]', '%75tm', "n\nl", "n\0l", str_repeat('a', 65), 42, array('x'), null,
            'utm_*', 'ok_name', 'hsa_*', 'fbclid', 'fbclid', '  igshid  ',
        );
        $names = sb_private($plugin, 'tracking_param_names');
        sb_assert(array('utm_*', 'ok_name', 'hsa_*', 'fbclid', 'igshid') === $names, 'The filter let through a reserved or invalid name: ' . implode(',', $names));
        $GLOBALS['sb_test_filter_values']['static_bridge_tracking_params'] = array_map(function ($n) { return 'n' . $n; }, range(1, 80));
        sb_assert(Static_Bridge_Plugin::MAX_TRACKING_PARAMS === count(sb_private($plugin, 'tracking_param_names')), 'The tracking list is not capped.');
        $GLOBALS['sb_test_filter_values']['static_bridge_tracking_params'] = 'utm_*';
        sb_assert(array() === sb_private($plugin, 'tracking_param_names') && '' === sb_private($plugin, 'tracking_query_pattern'), 'A filter that returns no array still writes an expression.');
    });
});

sb_test('Cookies that send to WP (2.5.0): validated names, compared by name and never by value, in Apache, Nginx and the Cloudflare rule', function () {
    sb_guard_isolated(function ($plugin) {
        $check = sb_private($plugin, 'sanitize_dynamic_cookie_names', array(array('wishlist', ' yith_wcwl_session_* ', 'WISHLIST', 'wp.lang', 'ab*', 'a b', 'x"y', 'x;y', 'x=y', '*', 'é', str_repeat('c', 65), '', 7)));
        sb_assert(array('wishlist', 'yith_wcwl_session_*', 'wp.lang') === $check['names'] && array('ab*', 'a b', 'x"y', 'x;y', 'x=y', '*', 'é', str_repeat('c', 65)) === $check['invalid'],
            'Cookie names are not validated: ' . json_encode($check));
        $many = sb_private($plugin, 'sanitize_dynamic_cookie_names', array(array_map(function ($n) { return 'c' . $n; }, range(1, 40))));
        sb_assert(Static_Bridge_Plugin::MAX_DYNAMIC_COOKIES === count($many['names']) && 10 === $many['dropped'], 'The cookie list is not capped.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 1, 'excluded_paths' => array());
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache_off = sb_private($plugin, 'rewrite_block');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx_off = sb_private($plugin, 'nginx_router_block');
        $cloudflare_off = sb_private($plugin, 'cloudflare_cache_rule_expression');
        sb_assert(array() === sb_private($plugin, 'settings')['dynamic_cookies'] && '' === sb_private($plugin, 'dynamic_cookie_pattern'), 'The cookie list is not empty by default.');

        // Stored values are validated again when read; the filter adds names, validated the same way.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['dynamic_cookies'] = array('wishlist', 'bad name', 'x") { return 200; } #');
        $GLOBALS['sb_test_filter_values']['static_bridge_dynamic_cookies'] = array('yith_wcwl_session_*', 'evil"', 'wp.lang');
        sb_assert(array('wishlist', 'yith_wcwl_session_*', 'wp.lang') === sb_private($plugin, 'dynamic_cookie_names'), 'Stored or filtered cookie names are not validated.');
        $pattern = sb_private($plugin, 'dynamic_cookie_pattern');
        sb_assert('(?:^|[;,])\s*(?:wishlist(?:[=;,\s]|$)|yith_wcwl_session_|wp\.lang(?:[=;,\s]|$))' === $pattern, 'Unexpected cookie expression: ' . $pattern);
        foreach (array('wishlist=1' => true, 'a=1; wishlist=2' => true, 'a=1;wishlist=2' => true, 'a=1, wishlist=2' => true, 'WishList=1' => true, 'wishlist' => true, 'a=1; wishlist' => true,
            'yith_wcwl_session_9f=x' => true, 'wp.lang=it' => true, 'a=wishlist' => false, 'a=x; b=wishlist=1' => false, 'notwishlist=1' => false, 'wishlists=1' => false,
            'wpxlang=it' => false, 'yith_wcwl=1' => false, 'a=1; b=yith_wcwl_session_9' => false) as $header => $to_wp) {
            sb_assert($to_wp === (bool) preg_match('#' . $pattern . '#i', $header), 'The cookie expression decides «' . $header . '» wrongly.');
        }
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $apache_on = sb_private($plugin, 'rewrite_block');
        $line = 'RewriteCond %{HTTP_COOKIE} !' . $pattern . " [NC]\n";
        sb_assert(str_replace($line, '', $apache_on) === $apache_off && substr_count($apache_on, $line) === substr_count($apache_on, "RewriteCond %{QUERY_STRING} ^$\n"),
            'The Apache guard does not carry the cookie condition before every rule, or changes something else.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $nginx_on = sb_private($plugin, 'nginx_router_block');
        $nginx_line = '    if ($http_cookie ~* "' . $pattern . "\") { return 418; }\n";
        // The fingerprint of the block (X-Static-Bridge-Rules, D5) changes with it: compared without.
        $unmarked = function ($block) { return preg_replace('/^    add_header X-Static-Bridge-Rules \S+ always;\n/m', '', $block); };
        sb_assert(2 === substr_count($nginx_on, $nginx_line) && $unmarked(str_replace($nginx_line, '', $nginx_on)) === $unmarked($nginx_off), 'The Nginx block does not carry the cookie condition in both locations.');
        $cloudflare_on = sb_private($plugin, 'cloudflare_cache_rule_expression');
        foreach (array('wishlist', 'yith_wcwl_session_', 'wp.lang') as $cookie) {
            sb_assert(false !== strpos($cloudflare_on, 'not (http.cookie contains "' . $cookie . '")'), 'The Cloudflare rule misses the cookie ' . $cookie . '.');
        }
        sb_assert(strlen($cloudflare_on) > strlen($cloudflare_off) && false === strpos($cloudflare_on, '*'), 'The Cloudflare rule keeps a «*».');
    });
});

sb_test('Settings (2.5.0): the two guard options are saved off and empty unless asked, invalid cookie lines are said in Attività, and Nginx is told to copy the block', function () use ($source) {
    sb_guard_isolated(function ($plugin) use ($source) {
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        $save = function ($post) use ($plugin) {
            $_POST = array_merge(array('incremental_enabled' => '1', 'excluded_paths' => ''), $post);
            try {
                $plugin->save_settings();
            } catch (SB_Test_Response $response) {
                return $response;
            }
            return null;
        };
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('incremental_enabled' => 1);
        $save(array());
        $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
        sb_assert(0 === $stored['ignore_tracking_params'] && array() === $stored['dynamic_cookies'], 'A form without the new fields turned them on.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $save(array('ignore_tracking_params' => '1', 'dynamic_cookies' => "wishlist\r\nbad name\n\n yith_* \nWISHLIST"));
        $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
        sb_assert(1 === $stored['ignore_tracking_params'] && array('wishlist', 'yith_*') === $stored['dynamic_cookies'], 'The two options were not saved: ' . json_encode($stored));
        $activity = implode("\n", sb_group_c_activity());
        sb_assert(false !== strpos($activity, 'Nomi non validi: «bad name»') && false !== strpos($activity, 'Parametri di tracciamento ignorati dalle regole del server.')
            && 2 <= substr_count($activity, 'Copia il blocco Nginx aggiornato e ricarica Nginx.') && false !== strpos($activity, 'Cookie che mandano a WP aggiornati.'),
            'Attività does not say the invalid name, the change or the Nginx copy: ' . $activity);
        $tab = sb_method_body($source, 'render_admin_page');
        foreach (array('name="ignore_tracking_params"', 'name="dynamic_cookies"', 'static_bridge_tracking_params', 'static_bridge_dynamic_cookies') as $needle) {
            sb_assert(false !== strpos($tab, $needle), 'The Settings tab misses ' . $needle . '.');
        }
    });
});

sb_test('Diagnostica (2.5.0): tracking parameters served from the copy, query-bypass with one of them, and a warning for a cookie that every visitor probably has', function () {
    sb_guard_isolated(function ($plugin) {
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('excluded_paths' => array());
        $plan = sb_private($plugin, 'diagnostic_plan', array(null));
        $ids = array_column($plan, 'id');
        sb_assert(!in_array('tracking-query', $ids, true) && !in_array('dynamic-cookies', $ids, true), 'Off, the Diagnostica has the new steps.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('excluded_paths' => array(), 'ignore_tracking_params' => 1, 'dynamic_cookies' => array('wishlist', '_ga', 'cmplz_banner-status', 'lingua'));
        $ids = array_column(sb_private($plugin, 'diagnostic_plan', array(null)), 'id');
        sb_assert(in_array('tracking-query', $ids, true) && in_array('dynamic-cookies', $ids, true), 'On, the Diagnostica misses the new steps.');
        sb_assert('utm_source=static-bridge-diagnostic&fbclid=static-bridge-diagnostic' === sb_private($plugin, 'diagnostic_tracking_query'), 'Unexpected Diagnostica query.');
        $skipped = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'tracking-query', 'type' => 'tracking-query'), array('release' => '')));
        sb_assert('skip' === $skipped['status'], 'Without a release the tracking step does not skip: ' . json_encode($skipped));

        $requests = array();
        $GLOBALS['sb_test_http_callback'] = function ($url, $args) use (&$requests) {
            $requests[] = array($url, $args['headers']['Cookie'] ?? '');
            if (home_url('/') . '?static_bridge_bypass=1' === $url) {
                return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html', 'set-cookie' => array('lingua=it; path=/', 'other=1')), 'body' => '<html></html>');
            }
            if (home_url('/') . '?utm_source=static-bridge-diagnostic&fbclid=static-bridge-diagnostic&static_bridge_bypass=1' === $url) {
                return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => '<html>wp</html>');
            }
            return null;
        };
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'dynamic-cookies', 'type' => 'dynamic-cookies'), array()));
        sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'WP li dà a ogni visitatore della home: lingua.')
            && false !== strpos($result['summary'], '_ga, cmplz_banner-status') && false === strpos($result['summary'], 'wishlist'), 'The cookie warning is wrong: ' . json_encode($result));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['dynamic_cookies'] = array('wishlist');
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'dynamic-cookies', 'type' => 'dynamic-cookies'), array()));
        sb_assert('pass' === $result['status'], 'A cookie nobody has by default is warned about: ' . json_encode($result));
        $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'query-bypass', 'type' => 'bypass'), array()));
        sb_assert('pass' === $result['status'] && in_array(array(home_url('/') . '?utm_source=static-bridge-diagnostic&fbclid=static-bridge-diagnostic&static_bridge_bypass=1', ''), $requests, true),
            'query-bypass does not add the tracking parameters: ' . json_encode($result));
        foreach (array(array('wishlist', 'wishlist2', false), array('_ga_*', '_ga_XYZ', true), array('cmplz_*', 'cmplz_marketing', true), array('lingua', 'Lingua', true), array('ab*', 'abc*', true), array('a', 'ab', false)) as $case) {
            sb_assert($case[2] === sb_private($plugin, 'cookie_names_overlap', array($case[0], $case[1])) && $case[2] === sb_private($plugin, 'cookie_names_overlap', array($case[1], $case[0])), 'cookie_names_overlap is wrong for ' . $case[0] . ' / ' . $case[1]);
        }
        sb_assert(false === sb_private($plugin, 'cookie_names_overlap', array('wishlist', 'wishlist2')) && true === sb_private($plugin, 'cookie_names_overlap', array('wishlist', 'WISHLIST')), 'Exact names overlap wrongly.');
    });
});

sb_test('Local Apache and Nginx (2.5.0): tracking parameters get the copy, any other or odd query and the listed cookies reach WP, Strict and ?format=markdown included', function () use ($fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the tracking and cookie routing check.');
    }
    sb_guard_isolated(function ($plugin) use ($fixtureRoot, $servers) {
        $failures = array();
        $static = array(
            '/pagina/?utm_source=x&fbclid=y', '/?utm_source=newsletter', '/pagina/?utm_campaign=autunno%202026&utm_medium=email&mc_cid=ab12',
            '/pagina/?fbclid=a&fbclid=b', '/pagina/?utm_source=x%26p%3D1', '/pagina/?utm_source=', '/pagina/?_gl=1*abc*_ga*MTIz',
        );
        $to_wp = array(
            '/pagina/?utm_source=x&p=1', '/?utm_source=x&p=1', '/pagina/?p=1&utm_source=x', '/pagina/?%75tm_source=x', '/pagina/?utm_source[]=x', '/pagina/?utm_source%5B%5D=x',
            '/pagina/?utm_source=x&&fbclid=y', '/pagina/?=', '/pagina/?&', '/pagina/?utm_source', '/pagina/?utm_source=x&', '/pagina/?UTM_SOURCE=x',
            '/pagina/?utm_source=a;p=1', '/pagina/?utm_source=a=b', '/pagina/?format=markdown', '/pagina/?utm_source=x&format=markdown', '/pagina/?utm_source=%22x%22&s=1',
            '/pagina/?static_bridge_bypass=1&utm_source=x', '/pagina/?utm_source=' . str_repeat('a', 2100), '/non-esportata/?utm_source=x&p=1',
        );
        foreach ($servers as $kind => $binary) {
            foreach (array('on', 'off') as $mode) {
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = 'on' === $mode
                    ? array('strict_mode' => 1, 'excluded_paths' => array(), 'ignore_tracking_params' => 1, 'dynamic_cookies' => array('wishlist', 'yith_wcwl_session_*'))
                    : array('strict_mode' => 1, 'excluded_paths' => array());
                $docroot = $fixtureRoot . '/tracking-' . $kind . '-' . $mode;
                $root = $docroot . '/wp-content/static-bridge';
                foreach (array('', 'pagina/') as $route) {
                    sb_assert(wp_mkdir_p($root . '/releases/r1/' . $route) && false !== file_put_contents($root . '/releases/r1/' . $route . 'index.html', 'STATIC_' . $route), 'Could not create the ' . $kind . ' docroot.');
                }
                file_put_contents($root . '/.enabled', '1');
                file_put_contents($root . '/.strict', '1');
                @symlink('releases/r1', $root . '/current');
                file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
                if ('apache' === $kind) {
                    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                    $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                        . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
                } else {
                    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                    $rules = sb_private($plugin, 'nginx_router_block');
                }
                list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
                $is_static = function ($response, $path) use ($kind) {
                    return 200 === $response['status'] && ('/' === $path[0] && 0 === strpos(trim($response['body']), 'STATIC_'))
                        && ('apache' === $kind || array('static') === ($response['headers']['x-static-bridge-route'] ?? array()));
                };
                $is_wp = function ($response) {
                    return 200 === $response['status'] && 'WORDPRESS_FALLBACK' === trim($response['body']);
                };
                try {
                    foreach ($static as $path) {
                        $response = $request($path);
                        $expected = 'on' === $mode;
                        if ($expected ? !$is_static($response, $path) : !$is_wp($response)) {
                            $failures[] = $kind . ' ' . $mode . ' ' . ($expected ? 'copy' : 'WP') . ' ' . substr($path, 0, 80) . ' ' . substr(json_encode($response), 0, 300);
                        }
                    }
                    foreach ($to_wp as $path) {
                        $response = $request($path);
                        if (!$is_wp($response)) {
                            $failures[] = $kind . ' ' . $mode . ' WP ' . substr($path, 0, 80) . ' ' . substr(json_encode($response), 0, 300);
                        }
                    }
                    // Strict: a tracking query on a route without a copy is the Strict 404, as without the query.
                    $strict = $request('/non-esportata/?utm_source=x');
                    if ('on' === $mode ? !(404 === $strict['status'] && 'no-store, max-age=0' === $strict['cache_control']) : !$is_wp($strict)) {
                        $failures[] = $kind . ' ' . $mode . ' Strict ' . json_encode($strict);
                    }
                    foreach (array('Cookie: wishlist=1' => true, 'Cookie: a=1; wishlist=2' => true, 'Cookie: WISHLIST=1' => true, 'Cookie: yith_wcwl_session_9f=1' => true,
                        'Cookie: a=wishlist' => false, 'Cookie: notwishlist=1' => false, 'Cookie: wishlists=1' => false) as $cookie => $sends) {
                        $response = $request('/pagina/', array($cookie));
                        $expected_wp = 'on' === $mode && $sends;
                        if ($expected_wp ? !$is_wp($response) : !$is_static($response, '/pagina/')) {
                            $failures[] = $kind . ' ' . $mode . ' ' . $cookie . ' ' . substr(json_encode($response), 0, 300);
                        }
                    }
                } finally {
                    $log = $stop();
                }
                if (!empty($failures) && '' !== trim($log)) {
                    $failures[] = $kind . ' log: ' . substr($log, -400);
                }
            }
        }
        sb_assert(empty($failures), implode('; ', $failures));
    });
});

// --- 2.5.0, cache comparison items 2, 3, 8 and 9: comments, neighbours, menus and widgets, refresh paths, public action. ---

/** sb_archive_isolated() with the posts, comments, caps, events and $_POST of the suite restored afterwards. */
function sb_cache_items_isolated(callable $callback)
{
    $saved = array(!empty($GLOBALS['sb_test_get_post_wp_post']), $GLOBALS['sb_test_comments'] ?? array(), $GLOBALS['sb_test_caps'] ?? null,
        $GLOBALS['sb_test_scheduled_hooks'], $_POST, $GLOBALS['sb_test_hooks'], $GLOBALS['sb_test_action_callbacks'] ?? array(),
        $GLOBALS['sb_test_filter_callbacks'] ?? array(), $GLOBALS['sb_test_actions_fired'] ?? array(), $GLOBALS['sb_test_options']);
    $GLOBALS['sb_test_get_post_wp_post'] = true;
    $GLOBALS['sb_test_scheduled_hooks'] = array();
    try {
        sb_archive_isolated($callback);
    } finally {
        list($GLOBALS['sb_test_get_post_wp_post'], $GLOBALS['sb_test_comments'], $GLOBALS['sb_test_caps'], $GLOBALS['sb_test_scheduled_hooks'], $_POST,
            $GLOBALS['sb_test_hooks'], $GLOBALS['sb_test_action_callbacks'], $GLOBALS['sb_test_filter_callbacks'], $GLOBALS['sb_test_actions_fired'],
            $GLOBALS['sb_test_options']) = $saved;
        if (null === $GLOBALS['sb_test_caps']) {
            unset($GLOBALS['sb_test_caps']);
        }
    }
}

/** Writes an index.html for each route of the release. */
function sb_cache_items_routes($release, array $routes)
{
    foreach ($routes as $route) {
        $directory = rtrim($release . '/' . trim($route, '/'), '/');
        sb_assert(wp_mkdir_p($directory) && false !== file_put_contents($directory . '/index.html', 'x'), 'Could not seed ' . $route);
    }
}

sb_test('Comments (2.5.0): an approved, unapproved or edited approved comment refreshes its post and comment pages; pending, spam and moderation never do', function () {
    sb_cache_items_isolated(function ($plugin, $release) {
        sb_cache_items_routes($release, array('/post-202/', '/post-202/comment-page-2/', '/post-205/'));
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 202, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2024-01-15 10:00:00'),
            array('ID' => 204, 'post_type' => 'post', 'post_status' => 'draft', 'post_password' => '', 'post_date' => '2024-01-17 10:00:00'),
            array('ID' => 205, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => 'segreta', 'post_date' => '2024-01-18 10:00:00'),
            array('ID' => 206, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2024-01-19 10:00:00'),
        );
        $GLOBALS['sb_test_comments'] = array(
            31 => array('comment_ID' => 31, 'comment_post_ID' => 202, 'comment_approved' => '0'),
            32 => array('comment_ID' => 32, 'comment_post_ID' => 202, 'comment_approved' => 'spam'),
            33 => array('comment_ID' => 33, 'comment_post_ID' => 202, 'comment_approved' => '1'),
        );
        $registered = array();
        foreach ($GLOBALS['sb_test_hooks'] as $hook) {
            if (is_array($hook[1]) && $hook[1][0] instanceof Static_Bridge_Plugin) {
                $registered[$hook[0] . ':' . $hook[1][1]] = (int) $hook[3];
            }
        }
        sb_assert(3 === ($registered['wp_update_comment_count:maybe_queue_comment_count_change'] ?? 0) && 2 === ($registered['edit_comment:maybe_queue_edited_comment'] ?? 0),
            'The comment hooks are not registered.');

        // WP counts again also when a pending comment is marked as spam or deleted: the same number queues nothing.
        $plugin->maybe_queue_comment_count_change(202, 3, 3);
        $plugin->maybe_queue_edited_comment(31, array());
        $plugin->maybe_queue_edited_comment(32, array());
        $plugin->maybe_queue_edited_comment(99, array());
        sb_assert(array() === sb_queued_items(), 'A pending or spam comment queued a page: ' . json_encode(sb_queued_items()));

        // Approved (4 instead of 3) and unapproved, trashed or deleted (2 instead of 3): the post and its comment pages.
        foreach (array(array(3, 4), array(3, 2)) as $count) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
            $plugin->maybe_queue_comment_count_change(202, $count[1], $count[0]);
            sb_assert(array('/post-202/' => 'refresh', '/post-202/comment-page-2/' => 'refresh') === sb_queued_items(), 'A new number of approved comments did not refresh the post: ' . json_encode(sb_queued_items()));
            $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION);
            sb_assert('single' === $queue[sha1('/post-202/')]['role'] && 202 === $queue[sha1('/post-202/')]['post_id'], 'The commented post was not queued as its own page.');
        }
        // An approved comment edited in place.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_edited_comment(33, array());
        sb_assert(isset(sb_queued_items()['/post-202/']), 'An edited approved comment did not refresh its post.');
        // Many comments: one entry per route, never a duplicate.
        for ($comment = 0; $comment < 5; $comment++) {
            $plugin->maybe_queue_comment_count_change(202, 5 + $comment, 4 + $comment);
        }
        sb_assert(2 === count(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION)), 'Several comments duplicated the routes of their post.');

        // A post with a password, a draft, a post without a copy, incremental updates off: nothing.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        foreach (array(205, 204, 206, 999) as $post_id) {
            $plugin->maybe_queue_comment_count_change($post_id, 1, 0);
        }
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_enabled'] = 0;
        $plugin->maybe_queue_comment_count_change(202, 1, 0);
        sb_assert(array() === sb_queued_items(), 'A comment queued a protected, unpublished or uncopied post, or with incremental updates off: ' . json_encode(sb_queued_items()));
    });
});

sb_test('Neighbours (2.5.0): publishing, withdrawing, redating or deleting a post refreshes the previous and next posts a visitor sees', function () {
    sb_cache_items_isolated(function ($plugin, $release) {
        sb_cache_items_routes($release, array('/post-201/', '/post-202/', '/post-203/', '/post-205/', '/post-207/', '/post-208/'));
        $GLOBALS['sb_test_posts'] = array(
            array('ID' => 201, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2024-01-10 10:00:00'),
            array('ID' => 202, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2024-01-15 10:00:00'),
            array('ID' => 203, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2024-01-20 10:00:00'),
            array('ID' => 204, 'post_type' => 'post', 'post_status' => 'draft', 'post_password' => '', 'post_date' => '2024-01-17 10:00:00'),
            array('ID' => 205, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => 'segreta', 'post_date' => '2024-01-18 10:00:00'),
            array('ID' => 207, 'post_type' => 'post', 'post_status' => 'private', 'post_password' => '', 'post_date' => '2024-01-16 10:00:00'),
            array('ID' => 208, 'post_type' => 'post', 'post_status' => 'publish', 'post_password' => '', 'post_date' => '2023-12-01 10:00:00'),
        );
        // 201 and 208 share category 3: the «previous in the same category» of a post in it.
        $GLOBALS['sb_test_archive']['post_terms'] = array(201 => array(3), 208 => array(3), 204 => array(3));
        $draft = new WP_Post(array('ID' => 204, 'post_type' => 'post', 'post_status' => 'draft', 'post_date' => '2024-01-17 10:00:00'));
        $published = new WP_Post(array('ID' => 204, 'post_type' => 'post', 'post_status' => 'publish', 'post_date' => '2024-01-17 10:00:00'));
        $GLOBALS['sb_test_posts'][3]['post_status'] = 'publish';
        $plugin->maybe_queue_incremental_post(204, $published, true, $draft);
        $queued = sb_queued_items();
        // Previous: 202 (207 is private); next: 203 (205 has a password); in category 3: 201 before, nothing after.
        foreach (array('/post-202/', '/post-203/', '/post-201/') as $path) {
            sb_assert(isset($queued[$path]) && 'refresh' === $queued[$path], 'Publishing did not refresh the neighbour ' . $path . ': ' . json_encode($queued));
        }
        foreach (array('/post-205/', '/post-207/', '/post-208/') as $path) {
            sb_assert(!isset($queued[$path]), 'A post that is not the neighbour a visitor sees was queued: ' . $path);
        }
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION);
        sb_assert('single' === $queue[sha1('/post-204/')]['role'], 'The published post lost its own entry to a neighbour.');

        // Withdrawn: the neighbours it had, read before the change (pre_post_update), drop its link.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->remember_incremental_old_archives(204, array());
        $GLOBALS['sb_test_posts'][3]['post_status'] = 'draft';
        $plugin->maybe_queue_incremental_post(204, $draft, true, $published);
        $queued = sb_queued_items();
        sb_assert('delete' === ($queued['/post-204/'] ?? '') && isset($queued['/post-202/'], $queued['/post-203/']), 'Withdrawing a post did not refresh its neighbours: ' . json_encode($queued));

        // A new date: the old neighbours and the new ones.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $GLOBALS['sb_test_posts'][1]['post_date'] = '2024-01-15 10:00:00';
        $plugin->remember_incremental_old_archives(202, array());
        $GLOBALS['sb_test_posts'][1]['post_date'] = '2023-11-01 10:00:00';
        $before = new WP_Post(array('ID' => 202, 'post_type' => 'post', 'post_status' => 'publish', 'post_date' => '2024-01-15 10:00:00'));
        $after = new WP_Post(array('ID' => 202, 'post_type' => 'post', 'post_status' => 'publish', 'post_date' => '2023-11-01 10:00:00'));
        $plugin->maybe_queue_incremental_post(202, $after, true, $before);
        $queued = sb_queued_items();
        foreach (array('/post-201/', '/post-203/', '/post-208/') as $path) {
            sb_assert(isset($queued[$path]), 'A redated post did not refresh the neighbour ' . $path . ': ' . json_encode($queued));
        }

        // Deleted while published.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_deleted_post(203, new WP_Post(array('ID' => 203, 'post_type' => 'post', 'post_status' => 'publish', 'post_date' => '2024-01-20 10:00:00')));
        $queued = sb_queued_items();
        sb_assert('delete' === ($queued['/post-203/'] ?? '') && isset($queued['/post-201/']), 'Deleting a post did not refresh its previous post: ' . json_encode($queued));

        // Pages have no «previous» and «next».
        sb_assert(array() === sb_private($plugin, 'adjacent_post_urls', array(new WP_Post(array('ID' => 9, 'post_type' => 'page', 'post_status' => 'publish', 'post_date' => '2024-01-15 10:00:00')))),
            'A page queued neighbours.');
    });
});

sb_test('Menus and widgets (2.5.0): they start one shared refresh after a wait, ten saves are one refresh, and only an editor of the theme starts it', function () {
    sb_cache_items_isolated(function ($plugin, $release) {
        sb_cache_items_routes($release, array('/', '/chi-siamo/'));
        $GLOBALS['sb_test_caps'] = array('edit_theme_options' => true);
        $GLOBALS['sb_test_options']['stylesheet'] = 'tema';
        $finish_request = function () use (&$plugin) {
            $shutdown = array_filter($GLOBALS['sb_test_hooks'], static fn($hook) => 'shutdown' === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0]);
            foreach ($shutdown as $hook) {
                call_user_func($hook[1]);
            }
            $plugin = new Static_Bridge_Plugin();
            return count($shutdown);
        };
        $hook_names = function ($plugin) {
            $names = array();
            foreach ($GLOBALS['sb_test_hooks'] as $hook) {
                if (is_array($hook[1]) && $plugin === $hook[1][0] && 'note_layout_change' === $hook[1][1]) {
                    $names[] = $hook[0];
                }
            }
            return $names;
        };
        $activity = static fn() => implode("\n", sb_group_c_activity());
        sb_assert(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOKS === $hook_names($plugin), 'The menu actions do not take note: ' . json_encode($hook_names($plugin)));
        foreach (array('added_option', 'updated_option', 'deleted_option') as $option_hook) {
            sb_assert(array() !== array_filter($GLOBALS['sb_test_hooks'], static fn($hook) => $option_hook === $hook[0] && is_array($hook[1]) && $plugin === $hook[1][0] && 'maybe_note_layout_option' === $hook[1][1]),
                'The widget options are not watched on ' . $option_hook . '.');
        }
        sb_assert(array('x') === $plugin->note_layout_change(array('x')) && 1 === $finish_request(), 'note_layout_change() did not hand its argument back or take note.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        delete_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION);
        wp_clear_scheduled_hook(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOK);

        // Options that do not reach the pages, and menu locations that stay the same.
        $plugin->maybe_note_layout_option('blogname', 'a', 'b');
        $plugin->maybe_note_layout_option('theme_mods_tema', array('nav_menu_locations' => array('primary' => 3, 'footer' => 4)), array('footer' => 9, 'nav_menu_locations' => array('footer' => 4, 'primary' => 3)));
        $plugin->maybe_note_layout_option('theme_mods_altro', array(), array('nav_menu_locations' => array('primary' => 3)));
        sb_assert(0 === $finish_request(), 'An option outside menus and widgets took note.');

        // A widget saved: nothing is queued yet, the event waits five minutes and Attività says why.
        $plugin->maybe_note_layout_option('widget_text', array(), array(2 => array('text' => 'x')));
        sb_assert(1 === $finish_request(), 'A widget save did not take note.');
        $first_due = wp_next_scheduled(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOK);
        sb_assert(array() === sb_queued_items() && is_int($first_due) && abs($first_due - (time() + Static_Bridge_Plugin::LAYOUT_REFRESH_MIN_WAIT)) <= 2,
            'A widget save did not wait before the refresh: ' . var_export($first_due, true));
        sb_assert(1 === substr_count($activity(), 'Menu o widget modificati: le pagine statiche si aggiornano fra 5 minuti'), 'Attività does not say why the pages wait: ' . $activity());

        // Ten saves of a menu: still one event, never past twice the wait from the first, one line in Attività.
        $state = get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION]['first'] = time() - 400;
        for ($save = 0; $save < 10; $save++) {
            $plugin->note_layout_change(3);
            $plugin->maybe_note_layout_option('sidebars_widgets', array(), array());
            $finish_request();
        }
        $due = wp_next_scheduled(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOK);
        sb_assert(is_int($due) && $due <= time() - 400 + 2 * Static_Bridge_Plugin::LAYOUT_REFRESH_MIN_WAIT + 1 && array() === sb_queued_items(), 'Ten saves moved the refresh past twice the wait or queued pages.');
        sb_assert(1 === substr_count($activity(), 'Menu o widget modificati'), 'Each save wrote a line in Attività.');
        // A menu location assigned in Aspetto → Menu.
        $plugin->maybe_note_layout_option('theme_mods_tema', array('nav_menu_locations' => array('primary' => 3)), array('nav_menu_locations' => array('primary' => 5)));
        sb_assert(1 === $finish_request(), 'A new menu location did not take note.');

        // Someone who cannot edit the theme (a page render, a visitor, another plugin's cron task) never moves it.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION]['last'] = time() - 50;
        $GLOBALS['sb_test_caps'] = array();
        $plugin->maybe_note_layout_option('widget_block', array(), array(1));
        $finish_request();
        sb_assert(time() - 50 === get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION)['last'], 'A request without edit_theme_options moved the menu and widget refresh.');
        $GLOBALS['sb_test_caps'] = array('edit_theme_options' => true);

        // Too early: the event reschedules itself. Due: every route once, with the reason, without a second wait.
        $plugin->run_layout_refresh();
        sb_assert(array() === sb_queued_items() && wp_next_scheduled(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOK), 'An early event queued the pages.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['incremental_wait'] = 10;
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION] = array('first' => time() - 2000, 'last' => time() - 1300);
        delete_option(Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION);
        $plugin->run_layout_refresh();
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION);
        sb_assert(array('/' => 'refresh', '/chi-siamo/' => 'refresh') === sb_queued_items() && !empty($queue[sha1('/chi-siamo/')]['shared_content']), 'The menu and widget refresh did not queue every route: ' . json_encode(sb_queued_items()));
        sb_assert('Un menu o un widget è cambiato.' === get_option(Static_Bridge_Plugin::SHARED_REFRESH_REASON_OPTION), 'The pages do not say why they are regenerated.');
        sb_assert(false === get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION, false) && false === get_option(Static_Bridge_Plugin::INCREMENTAL_WAIT_OPTION, false),
            'The refresh kept its state or waited a second time.');
        // With «Attesa dopo l'ultima modifica» longer than five minutes, the menu waits as long.
        sb_assert(600 === sb_private($plugin, 'layout_refresh_wait'), 'The menu wait is not the longer of the two.');

        // A Customizer save already queued every route in the same request.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        $plugin->maybe_queue_customizer_shared_output(null);
        $plugin->maybe_note_layout_option('widget_text', array(), array(1));
        $finish_request();
        sb_assert(false === get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION, false), 'A Customizer save was followed by a second refresh.');
        // «Aggiorna tutte le pagine statiche» drops a refresh still waiting.
        $plugin->maybe_note_layout_option('widget_text', array(), array(2));
        $finish_request();
        sb_assert(false !== get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION, false), 'The fixture did not wait.');
        sb_private($plugin, 'request_static_refresh', array('all'));
        sb_assert(false === get_option(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION, false) && !wp_next_scheduled(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOK), 'Refreshing every page left the menu refresh waiting.');

        // The filter: valid names only, never a Static Bridge hook; an empty list turns it off, options included.
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_shared_refresh_hooks'] = static fn($hooks) => array_merge($hooks, array('tema_salvato', 'static_bridge_route_updated', 'bad name', 7, 'tema_salvato'));
        $plugin = new Static_Bridge_Plugin();
        sb_assert(array_merge(Static_Bridge_Plugin::LAYOUT_REFRESH_HOOKS, array('tema_salvato')) === $hook_names($plugin), 'The hook list kept an invalid name: ' . json_encode($hook_names($plugin)));
        $GLOBALS['sb_test_filter_callbacks']['static_bridge_shared_refresh_hooks'] = static fn() => array();
        $plugin = new Static_Bridge_Plugin();
        $plugin->maybe_note_layout_option('widget_text', array(), array(3));
        sb_assert(array() === $hook_names($plugin) && 0 === $finish_request(), 'An empty list did not turn the menu and widget refresh off.');
        unset($GLOBALS['sb_test_filter_callbacks']['static_bridge_shared_refresh_hooks']);
    });
});

sb_test('Imported redirects (2.5.0): the Settings keep the choice of a plugin that is off, say it in Attività and ask to copy the Nginx block again', function () use ($plugin, $source) {
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $wpdb, $source) {
            sb_redirect_import_fixture($wpdb);
            // The plugins are not running: nothing is read, nothing changes (this test runs before the constants exist).
            sb_cf_settings();
            $baseline = sb_private($plugin, 'rewrite_block');
            sb_cf_settings(array('import_redirects' => array('redirection', 'rank_math', 'yoast_premium')));
            sb_assert(!defined('REDIRECTION_VERSION') && !defined('RANK_MATH_VERSION') && !defined('WPSEO_PREMIUM_VERSION'), 'This test must run before the constants of the plugins exist.');
            $inactive = sb_private($plugin, 'imported_redirects');
            sb_assert(array() === $inactive['redirects'] && array('inactive') === array_values(array_unique(array_column($inactive['sources'], 'state'))) && array() === $wpdb->queries,
                'An inactive plugin was read: ' . json_encode($inactive));
            sb_assert($baseline === sb_private($plugin, 'rewrite_block'), 'The rules changed with the plugins off.');
            sb_assert(false !== strpos(implode("\n", sb_private($plugin, 'redirect_import_summary')), 'Redirection: plugin non attivo, nessun redirect importato.'), 'The Settings do not say that the plugin is off.');
            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            defined('RANK_MATH_VERSION') || define('RANK_MATH_VERSION', '1.0.230');
            sb_cf_settings(array('import_redirects' => array('yoast_premium')));
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            $_POST = array('strict_mode' => '1', 'incremental_enabled' => '1', 'excluded_paths' => '', 'import_redirects' => array('redirection', 'evil', array('x')));
            try {
                $plugin->save_settings();
            } catch (SB_Test_Response $response) {
            } finally {
                $_POST = array();
            }
            $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
            sb_assert(array('redirection', 'yoast_premium') === $stored['import_redirects'], 'The Settings did not save the boxes, or dropped the choice of a plugin that is off: ' . json_encode($stored['import_redirects']));
            $activity = implode("\n", sb_group_c_activity());
            sb_assert(1 === preg_match('~Redirect importati nelle regole del server\. \| Redirection: [0-9]+ redirect importati\.~', $activity) && false !== strpos($activity, 'Copia il blocco Nginx aggiornato e ricarica Nginx.'),
                'Attività does not say what was imported, or does not ask for the Nginx block: ' . $activity);
            sb_assert(false !== strpos($source, "name=\"import_redirects[]\"") && false !== strpos($source, 'Le espressioni regolari non si portano'), 'The Settings do not show the boxes or do not say that regular expressions are not imported.');
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

sb_test('Imported redirects (2.5.0): only exact paths of Redirection, Rank Math and Yoast SEO Premium reach the rules with Strict, read defensively', function () use ($plugin) {
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $wpdb) {
            sb_redirect_import_fixture($wpdb);
            sb_cf_settings(array('excluded_paths' => array('/iscriviti/')));
            $baseline = sb_private($plugin, 'rewrite_block');
            $baselineNginx = sb_private($plugin, 'nginx_router_block');
            sb_assert(array() === sb_private($plugin, 'settings')['import_redirects'] && array() === $wpdb->queries, 'The import is not off by default, or a plugin was read with it off.');
            sb_cf_settings(array('excluded_paths' => array('/iscriviti/'), 'import_redirects' => array('yoast_premium', 'evil', array(), 'redirection', 'rank_math', 'redirection')));
            sb_assert(array('redirection', 'rank_math', 'yoast_premium') === sb_private($plugin, 'settings')['import_redirects'], 'A stored choice is not checked when read.');

            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            defined('RANK_MATH_VERSION') || define('RANK_MATH_VERSION', '1.0.230');
            defined('WPSEO_PREMIUM_VERSION') || define('WPSEO_PREMIUM_VERSION', '24.0');

            $GLOBALS['sb_test_filter_values']['static_bridge_redirects'] = array('/codice/' => array('to' => '/dal-codice/', 'status' => 302));
            try {
                $imported = sb_private($plugin, 'imported_redirects', array(sb_private($plugin, 'plugin_redirects', array(false))));
                $all = sb_private($plugin, 'plugin_redirects');
                $rules = sb_private($plugin, 'rewrite_block');
                $nginx = sb_private($plugin, 'nginx_router_block');
                $summary = sb_private($plugin, 'redirect_import_summary');
            } finally {
                unset($GLOBALS['sb_test_filter_values']['static_bridge_redirects']);
            }
            $expected = array(
                '/vecchia-pagina' => array('to' => '/nuova-pagina/', 'status' => 301),
                '/uguale' => array('to' => '/stessa/', 'status' => 302),
                '/percento' => array('to' => '/caff%C3%A8%20bar/', 'status' => 307),
                '/pagina-rm' => array('to' => '/nuova-rm/', 'status' => 301),
                '/yoast-vecchia' => array('to' => '/yoast-nuova/', 'status' => 301),
            );
            ksort($expected);
            $got = $imported['redirects'];
            ksort($got);
            sb_assert($expected === $got, 'The imported redirects are not the simple ones: ' . json_encode($got));
            sb_assert(array('to' => '/dal-codice/', 'status' => 302) === $all['/codice'] && 1 === $imported['overridden'], 'A redirect of the filter did not win over an imported one.');
            sb_assert(2 === $imported['conflicts'] && !isset($all['/doppio']), 'A path with two targets in two plugins was imported: ' . json_encode($imported));
            sb_assert(array('state' => 'ok', 'imported' => 3, 'complex' => 4, 'unsupported' => 7) === $imported['sources']['redirection'], 'The Redirection counts are wrong: ' . json_encode($imported['sources']['redirection']));
            sb_assert(array('state' => 'ok', 'imported' => 1, 'complex' => 1, 'unsupported' => 3) === $imported['sources']['rank_math'], 'The Rank Math counts are wrong: ' . json_encode($imported['sources']['rank_math']));
            sb_assert(array('state' => 'ok', 'imported' => 1, 'complex' => 1, 'unsupported' => 1) === $imported['sources']['yoast_premium'], 'The Yoast counts are wrong: ' . json_encode($imported['sources']['yoast_premium']));
            sb_assert(false !== strpos($rules, "RewriteRule ^vecchia\\-pagina/?$ /nuova-pagina/ [R=301,NE,END]\n") && false !== strpos($rules, "RewriteRule ^yoast\\-vecchia/?$ /yoast-nuova/ [R=301,NE,END]\n"),
                'An imported redirect is not in the Apache rules.');
            sb_assert(false !== strpos($rules, 'RewriteRule ^percento/?$ /caff\\%C3\\%A8\\%20bar/ [R=307,NE,END]') && false === strpos($rules, ' /caff%C3'),
                'An encoded target keeps a bare «%» in the Apache substitution, where %2 is a back-reference.');
            sb_assert(false !== strpos($nginx, 'location = /percento/ { absolute_redirect off; return 307 /caff%C3%A8%20bar/$is_args$args; }') && false !== strpos($nginx, 'location = /pagina-rm { absolute_redirect off; return 301 /nuova-rm/$is_args$args; }'),
                'An imported redirect is not in the Nginx block.');
            foreach (array('vecchio', 'solo-loggati', 'con-query', 'flag-regex', 'vedi-altro', 'elsewhere', 'errore', 'doppio', 'evil', 'iscriviti/vecchia', 'cattivo', 'frammento', 'rm-inizia', 'andata', 'relativa', '^re') as $absent) {
                sb_assert(false === strpos($rules, $absent) && false === strpos($nginx, $absent), 'A redirect that is not simple reached the rules: ' . $absent);
            }
            sb_assert(false !== strpos(implode("\n", $summary), 'Redirection: 3 redirect importati. 4 saltati: espressioni regolari, condizioni o parametri nell’indirizzo di partenza. 7 saltati:')
                && false !== strpos(implode("\n", $summary), '2 redirect saltati: lo stesso indirizzo ha destinazioni diverse.'), 'The Settings do not say what was imported and left out: ' . json_encode($summary));
            foreach ($wpdb->queries as $query) {
                sb_assert(0 !== strpos($query[0], 'UNPREPARED') && false === strpos($query[0], "'enabled'") && false === strpos($query[0], "'active'"), 'A query to another plugin\'s table was not prepared: ' . $query[0]);
            }
            sb_assert(in_array(array('enabled', 'enabled', 1, Static_Bridge_Plugin::MAX_REDIRECT_IMPORT_ROWS), array_column($wpdb->queries, 1), true)
                && in_array(array('active', Static_Bridge_Plugin::MAX_REDIRECT_IMPORT_ROWS), array_column($wpdb->queries, 1), true), 'The plugins are not read enabled, of the WordPress module and bounded.');

            // Strict off: WP runs and the plugins make their redirects; the rules are as before.
            $wpdb->queries = array();
            sb_cf_settings(array('strict_mode' => 0, 'excluded_paths' => array('/iscriviti/'), 'import_redirects' => array('redirection', 'rank_math', 'yoast_premium')));
            $off = sb_private($plugin, 'imported_redirects');
            sb_assert(array() === $off['redirects'] && array() === $wpdb->queries && false === strpos(sb_private($plugin, 'rewrite_block'), '[R=30'), 'Redirects were imported without Strict.');
            sb_assert(array('Spenta finché la Modalità strict è spenta: senza Strict i redirect li fa il plugin che li gestisce.') === sb_private($plugin, 'redirect_import_summary'), 'The Settings do not say that the import waits for Strict.');

            // Defensive: other columns, no table, a failing query, a hostile prefix, the module off: nothing, never an error.
            sb_cf_settings(array('excluded_paths' => array('/iscriviti/'), 'import_redirects' => array('redirection', 'rank_math', 'yoast_premium')));
            $columns = $wpdb->tables;
            $wpdb->tables['wp_redirection_items'] = array_values(array_diff($columns['wp_redirection_items'], array('match_data')));
            unset($wpdb->tables['wp_rank_math_redirections']);
            $GLOBALS['sb_test_options']['wpseo-premium-redirects-base'] = 'a:1:{';
            $odd = sb_private($plugin, 'imported_redirects');
            sb_assert(array() === $odd['redirects'] && 'unrecognized' === $odd['sources']['redirection']['state'] && 'missing' === $odd['sources']['rank_math']['state'] && 'unrecognized' === $odd['sources']['yoast_premium']['state'],
                'Other columns, a missing table or another shape did not stop the import: ' . json_encode($odd['sources']));
            sb_assert($baseline === sb_private($plugin, 'rewrite_block') && $baselineNginx === sb_private($plugin, 'nginx_router_block'), 'Unreadable plugins changed the rules.');
            $wpdb->tables = $columns;
            $wpdb->fail = true;
            unset($GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
            $GLOBALS['sb_test_options']['rank_math_modules'] = array('sitemap');
            $failed = sb_private($plugin, 'imported_redirects');
            sb_assert('unrecognized' === $failed['sources']['redirection']['state'] && 'module_off' === $failed['sources']['rank_math']['state'] && 'missing' === $failed['sources']['yoast_premium']['state'] && array() === $failed['redirects'],
                'A failing query, the Rank Math module off or no Yoast option did not leave the import empty: ' . json_encode($failed['sources']));
            $summary = implode("\n", sb_private($plugin, 'redirect_import_summary'));
            sb_assert(false !== strpos($summary, 'Redirection: formato dei redirect non riconosciuto, nessun redirect importato.') && false !== strpos($summary, 'Rank Math: modulo dei redirect spento') && false !== strpos($summary, 'Yoast SEO Premium: tabella o opzione dei redirect non trovata'),
                'The Settings do not say why nothing was imported: ' . $summary);
            $wpdb->fail = false;
            $wpdb->queries = array();
            $prefix = $wpdb->prefix;
            $wpdb->prefix = 'wp_;DROP_';
            try {
                $hostile = sb_private($plugin, 'imported_redirects');
            } finally {
                $wpdb->prefix = $prefix;
            }
            sb_assert('missing' === $hostile['sources']['redirection']['state'] && array() === $wpdb->queries, 'A hostile table prefix reached a query.');

            // At most MAX_IMPORTED_REDIRECTS, those with the most visits.
            $wpdb->rows['redirection'] = array();
            for ($i = 1; $i <= Static_Bridge_Plugin::MAX_IMPORTED_REDIRECTS + 5; $i++) {
                $wpdb->rows['redirection'][] = array('url' => '/molti-' . $i . '/', 'regex' => '0', 'match_type' => 'url', 'match_data' => null, 'action_type' => 'url', 'action_code' => '301', 'action_data' => '/meta/', 'last_count' => (string) (1000 - $i));
            }
            sb_cf_settings(array('import_redirects' => array('redirection')));
            $many = sb_private($plugin, 'imported_redirects');
            sb_assert(Static_Bridge_Plugin::MAX_IMPORTED_REDIRECTS === count($many['redirects']) && 5 === $many['over_limit'] && isset($many['redirects']['/molti-1'])
                && !isset($many['redirects']['/molti-' . (Static_Bridge_Plugin::MAX_IMPORTED_REDIRECTS + 1)]), 'The import is not limited to the most visited redirects.');
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

sb_test('Local Apache and Nginx with Strict on (2.5.0): an imported redirect answers 301 or 307 with the query, a regular expression stays a Strict 404', function () use ($plugin, $fixtureRoot) {
    $servers = array();
    foreach (array('apache' => 'STATIC_BRIDGE_APACHE_BIN', 'nginx' => 'STATIC_BRIDGE_NGINX_BIN') as $kind => $variable) {
        $binary = getenv($variable);
        if ($binary && is_executable($binary)) {
            $servers[$kind] = $binary;
        }
    }
    if (empty($servers) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_APACHE_BIN and/or STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the imported redirect check.');
    }
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $servers, $wpdb) {
            sb_redirect_import_fixture($wpdb);
            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            sb_cf_settings(array('import_redirects' => array('redirection')));
            $failures = array();
            foreach ($servers as $kind => $binary) {
                $docroot = $fixtureRoot . '/redirect-import-docroot-' . $kind;
                $static = $docroot . '/wp-content/static-bridge';
                foreach (array('', 'nuova-pagina/') as $route) {
                    sb_assert(wp_mkdir_p($static . '/releases/r1/' . $route) && false !== file_put_contents($static . '/releases/r1/' . $route . 'index.html', 'STATIC_' . $route), 'Could not create the ' . $kind . ' docroot.');
                }
                file_put_contents($static . '/.enabled', '1');
                file_put_contents($static . '/.strict', '1');
                @symlink('releases/r1', $static . '/current');
                file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
                if ('apache' === $kind) {
                    $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                    $rules = sb_private($plugin, 'archive_protection_block') . "\n\n" . sb_private($plugin, 'rewrite_block')
                        . "\n\n# BEGIN WordPress\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nRewriteRule ^index\\.php$ - [L]\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule . /index.php [L]\n</IfModule>\n# END WordPress\n";
                } else {
                    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                    $rules = sb_private($plugin, 'nginx_router_block');
                }
                sb_assert(false !== strpos($rules, 'vecchia') && false === strpos($rules, 'vecchio'), 'The ' . $kind . ' rules do not hold the imported redirect, or hold a regular expression.');
                list($request, $stop) = sb_cf_start_server($kind, $binary, $docroot, $rules, $fixtureRoot);
                try {
                    foreach (array(
                        array('/vecchia-pagina/', 301, '/nuova-pagina/'),
                        array('/vecchia-pagina', 301, '/nuova-pagina/'),
                        array('/vecchia-pagina/?utm_source=x', 301, '/nuova-pagina/?utm_source=x'),
                        array('/percento/', 307, '/caff%C3%A8%20bar/'),
                        array('/uguale/', 302, '/stessa/'),
                    ) as $case) {
                        $response = $request($case[0]);
                        $location = isset($response['headers']['location'][0]) ? $response['headers']['location'][0] : '';
                        if (!($case[1] === $response['status'] && preg_match('~^(?:https?://[^/]+)?' . preg_quote($case[2], '~') . '$~D', $location))) {
                            $failures[] = $kind . ' redirect ' . $case[0] . ' ' . json_encode(array($response['status'], $location));
                        }
                    }
                    $page = $request('/nuova-pagina/');
                    if (!(200 === $page['status'] && 'STATIC_nuova-pagina/' === trim($page['body']))) {
                        $failures[] = $kind . ' target ' . json_encode($page);
                    }
                    foreach (array('/vecchio/abc/', '/solo-loggati/') as $left) {
                        $response = $request($left);
                        if (404 !== $response['status']) {
                            $failures[] = $kind . ' not imported ' . $left . ' ' . json_encode(array($response['status'], $response['headers']['location'] ?? ''));
                        }
                    }
                } finally {
                    $log = $stop();
                }
                if (!empty($failures) && '' !== trim($log)) {
                    $failures[] = $kind . ' log: ' . substr($log, -400);
                }
            }
            sb_assert(empty($failures), implode('; ', $failures));
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

/** A release with a home page linked as current/ in the fixture's static root, for the steps that look for the copy. */
function sb_d5_with_release(callable $callback)
{
    $static_root = WP_CONTENT_DIR . '/static-bridge';
    $current = $static_root . '/current';
    $old_target = is_link($current) ? readlink($current) : false;
    $release = 'diag-rules-' . bin2hex(random_bytes(4));
    try {
        sb_assert(wp_mkdir_p($static_root . '/releases/' . $release), 'Could not create the release fixture.');
        file_put_contents($static_root . '/releases/' . $release . '/index.html', '<html>STATIC</html>');
        if (is_link($current)) { unlink($current); }
        symlink('releases/' . $release, $current);
        $callback(realpath($static_root . '/releases/' . $release));
    } finally {
        $GLOBALS['sb_test_http_callback'] = null;
        if (is_link($current)) { unlink($current); }
        if (false !== $old_target) { symlink($old_target, $current); }
        @unlink($static_root . '/releases/' . $release . '/index.html');
        @rmdir($static_root . '/releases/' . $release);
    }
}

function sb_d5_step($plugin)
{
    return sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'nginx-rules', 'type' => 'nginx-rules'), array()));
}

sb_test('Diagnostica (2.5.0, D5): the Nginx block in use is compared with the block of the settings and the redirects of now', function () use ($plugin) {
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $wpdb) {
            sb_redirect_import_fixture($wpdb);
            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            sb_d5_with_release(function ($release) use ($plugin, $wpdb) {
                sb_cf_settings();
                $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
                sb_assert(!in_array('nginx-rules', array_column(sb_private($plugin, 'diagnostic_plan', array($release)), 'id'), true), 'Apache has the step of the Nginx block.');
                $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
                sb_assert(in_array('nginx-rules', array_column(sb_private($plugin, 'diagnostic_plan', array($release)), 'id'), true), 'The Diagnostica has no step for the Nginx block in use.');

                $block = sb_private($plugin, 'nginx_router_block');
                $first = sb_private($plugin, 'nginx_rules_fingerprint');
                sb_assert(1 === preg_match('/^[0-9a-f]{12}-0$/D', $first) && $block === sb_private($plugin, 'nginx_router_block'), 'The block has no fingerprint, or it changes between two calls: ' . $first);
                sb_assert(4 === substr_count($block, "add_header X-Static-Bridge-Route static always;\n    add_header X-Static-Bridge-Rules " . $first . " always;\n")
                    && 4 === substr_count($block, 'X-Static-Bridge-Rules'), 'Not every response marked as the copy says which block it came from.');

                // What the server answers: the fingerprint of the block it has, null for a block without one, false for WP.
                $served = $first;
                $GLOBALS['sb_test_http_callback'] = function ($url, $args) use (&$served) {
                    if (false === $served) {
                        return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html'), 'body' => 'WP');
                    }
                    $headers = array('content-type' => 'text/html', 'X-Static-Bridge-Route' => 'static');
                    if (null !== $served) {
                        $headers['X-Static-Bridge-Rules'] = $served;
                    }
                    return array('response' => array('code' => 200), 'headers' => $headers, 'body' => '<html>STATIC</html>');
                };
                $result = sb_d5_step($plugin);
                sb_assert('pass' === $result['status'], 'The block of these settings is not a pass: ' . json_encode($result));
                $served = null;
                $result = sb_d5_step($plugin);
                sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'versione precedente') && false !== strpos($result['remediation'], 'Copia di nuovo il blocco Nginx'), 'A block of before 2.5.0 is not a warning: ' . json_encode($result));
                $served = false;
                $result = sb_d5_step($plugin);
                sb_assert('skip' === $result['status'], 'Without the copy served the step is not skipped: ' . json_encode($result));

                // An option turned on after the copy, then off again after a copy made with it on.
                sb_cf_settings(array('ignore_tracking_params' => 1));
                $tracking = sb_private($plugin, 'nginx_rules_fingerprint');
                sb_assert($tracking !== $first && '-0' === substr($tracking, -2), 'The option does not change the rules fingerprint: ' . $tracking);
                foreach (array(array($first, $tracking), array($tracking, null)) as $case) {
                    if (null === $case[1]) {
                        sb_cf_settings();
                    }
                    $served = $case[0];
                    $result = sb_d5_step($plugin);
                    sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'Le Impostazioni sono cambiate dopo l’ultima copia del blocco Nginx') && false === strpos($result['summary'], 'redirect'), 'A block copied before an option changed is not seen: ' . json_encode($result));
                }

                // Redirects imported from another plugin after the copy: only the redirects differ.
                sb_cf_settings(array('import_redirects' => array('redirection')));
                $imported = sb_private($plugin, 'nginx_rules_fingerprint');
                list($rules, $redirects) = explode('-', $imported);
                sb_assert($rules === explode('-', $first)[0] && '0' !== $redirects, 'The imported redirects are not in their own fingerprint: ' . $imported);
                $served = $first;
                $result = sb_d5_step($plugin);
                sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'mancano i redirect di adesso') && false === strpos($result['summary'], 'Impostazioni'), 'Imported redirects missing from the block are not seen: ' . json_encode($result));
                $served = $imported;
                sb_assert('pass' === sb_d5_step($plugin)['status'], 'The block with the imported redirects is not a pass.');

                // One of them changed in the other plugin, then the choice is removed.
                $wpdb->rows['redirection'][0]['action_data'] = '/altra-pagina/';
                $changed = sb_private($plugin, 'nginx_rules_fingerprint');
                sb_assert($changed !== $imported && 0 === strpos($changed, $rules . '-'), 'A changed redirect does not change only the redirect fingerprint.');
                $result = sb_d5_step($plugin);
                sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'I redirect sono cambiati dopo l’ultima copia'), 'A changed imported redirect is not seen: ' . json_encode($result));
                sb_cf_settings();
                $served = $changed;
                $result = sb_d5_step($plugin);
                sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'fa ancora dei redirect che adesso non ci sono più'), 'Redirects left in the block are not seen: ' . json_encode($result));
            });
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

sb_test('Imported redirects (2.5.0, O3): a choice that brings no redirect says so in Attività and asks for no copy of the Nginx block', function () use ($plugin) {
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $wpdb) {
            sb_redirect_import_fixture($wpdb);
            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            $save = function (array $post) use ($plugin) {
                $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
                $_POST = $post;
                try {
                    $plugin->save_settings();
                } catch (SB_Test_Response $response) {
                } finally {
                    $_POST = array();
                }
                return implode("\n", sb_group_c_activity());
            };
            // Strict off: the box is kept, nothing enters the rules.
            sb_cf_settings(array('strict_mode' => 0));
            $activity = $save(array('incremental_enabled' => '1', 'excluded_paths' => '', 'import_redirects' => array('redirection')));
            sb_assert(false !== strpos($activity, 'Nessun redirect importato nelle regole del server. | Spenta finché la Modalità strict è spenta')
                && false === strpos($activity, 'Redirect importati nelle regole del server.') && false === strpos($activity, 'Copia il blocco Nginx aggiornato'),
                'A choice without redirects says they entered the rules, or asks for the Nginx block: ' . $activity);
            // Strict on: they enter, and the block must be copied.
            $activity = $save(array('strict_mode' => '1', 'incremental_enabled' => '1', 'excluded_paths' => '', 'import_redirects' => array('redirection')));
            sb_assert(1 === preg_match('~Redirect importati nelle regole del server\. \| Redirection: [0-9]+ redirect importati\.~', $activity) && false !== strpos($activity, 'Copia il blocco Nginx aggiornato e ricarica Nginx.'),
                'Imported redirects do not ask for the Nginx block: ' . $activity);
            // Strict off again: they leave the rules, and the block must be copied again.
            $activity = $save(array('incremental_enabled' => '1', 'excluded_paths' => '', 'import_redirects' => array('redirection')));
            sb_assert(false !== strpos($activity, 'Nessun redirect importato nelle regole del server.') && false !== strpos($activity, 'Copia il blocco Nginx aggiornato e ricarica Nginx.'),
                'Redirects that leave the rules do not ask for the Nginx block: ' . $activity);
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

sb_test('Local Nginx (2.5.0, D5): the Diagnostica sees a block copied before an option or the imported redirects changed, and passes once it is copied again', function () use ($plugin, $fixtureRoot) {
    $nginx = getenv('STATIC_BRIDGE_NGINX_BIN');
    if (!$nginx || !is_executable($nginx) || !function_exists('proc_open') || !function_exists('http_get_last_response_headers')) {
        throw new SB_Test_Skip('Set STATIC_BRIDGE_NGINX_BIN (PHP 8.4+) to run the check of the Nginx block in use.');
    }
    $old_wpdb = $GLOBALS['wpdb'];
    $wpdb = sb_redirect_import_wpdb();
    $GLOBALS['wpdb'] = $wpdb;
    try {
        sb_cf_options_isolated(function () use ($plugin, $fixtureRoot, $nginx, $wpdb) {
            sb_redirect_import_fixture($wpdb);
            defined('REDIRECTION_VERSION') || define('REDIRECTION_VERSION', '5.5.0');
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            sb_cf_settings();
            $docroot = $fixtureRoot . '/d5-docroot-' . bin2hex(random_bytes(4));
            $static = $docroot . '/wp-content/static-bridge';
            foreach (array('', 'nuova-pagina/') as $route) {
                sb_assert(wp_mkdir_p($static . '/releases/r1/' . $route) && false !== file_put_contents($static . '/releases/r1/' . $route . 'index.html', '<html>STATIC</html>'), 'Could not create the Nginx docroot.');
            }
            file_put_contents($static . '/.enabled', '1');
            file_put_contents($static . '/.strict', '1');
            symlink('releases/r1', $static . '/current');
            file_put_contents($docroot . '/index.php', 'WORDPRESS_FALLBACK');
            sb_d5_with_release(function () use ($plugin, $fixtureRoot, $nginx, $docroot) {
                $server = null;
                // «Copy the block and reload Nginx»: the server starts again with the block of the settings of now.
                $copy = function () use (&$server, $plugin, $fixtureRoot, $nginx, $docroot) {
                    if (null !== $server) {
                        $server[1]();
                    }
                    $server = sb_cf_start_server('nginx', $nginx, $docroot, sb_private($plugin, 'nginx_router_block'), $fixtureRoot);
                };
                $GLOBALS['sb_test_http_callback'] = function ($url, $args) use (&$server) {
                    $query = (string) wp_parse_url($url, PHP_URL_QUERY);
                    $response = $server[0]((string) wp_parse_url($url, PHP_URL_PATH) . ('' === $query ? '' : '?' . $query));
                    $headers = array();
                    foreach ($response['headers'] as $name => $values) {
                        $headers[$name] = 1 === count($values) ? $values[0] : $values;
                    }
                    return array('response' => array('code' => $response['status']), 'headers' => $headers, 'body' => $response['body']);
                };
                try {
                    $copy();
                    $result = sb_d5_step($plugin);
                    sb_assert('pass' === $result['status'], 'The block just copied is not a pass: ' . json_encode($result));

                    // Copied with the tracking parameters ignored, then the option turned off without a new copy.
                    sb_cf_settings(array('ignore_tracking_params' => 1));
                    $copy();
                    sb_assert('pass' === sb_d5_step($plugin)['status'], 'The block copied with the option on is not a pass.');
                    sb_cf_settings();
                    $tracked = $server[0]('/?utm_source=x');
                    sb_assert('static' === ($tracked['headers']['x-static-bridge-route'][0] ?? ''), 'The fixture does not show the old rules still at work: ' . json_encode($tracked['status']));
                    $result = sb_d5_step($plugin);
                    sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'Le Impostazioni sono cambiate dopo l’ultima copia del blocco Nginx'), 'A block copied before the option was turned off is not seen: ' . json_encode($result));
                    $copy();
                    sb_assert('pass' === sb_d5_step($plugin)['status'] && '' === ($server[0]('/?utm_source=x')['headers']['x-static-bridge-route'][0] ?? ''), 'The block copied again is not a pass, or still gives the copy to a tracking query.');

                    // Redirects of another plugin chosen after the copy: the server still answers the Strict 404.
                    sb_cf_settings(array('import_redirects' => array('redirection')));
                    sb_assert(404 === $server[0]('/vecchia-pagina/')['status'], 'The fixture does not show the redirect missing from the old block.');
                    $result = sb_d5_step($plugin);
                    sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'mancano i redirect di adesso'), 'Imported redirects missing from the block in use are not seen: ' . json_encode($result));
                    $copy();
                    sb_assert('pass' === sb_d5_step($plugin)['status'] && 301 === $server[0]('/vecchia-pagina/')['status'], 'The block copied with the imported redirects is not a pass, or does not redirect.');
                } finally {
                    if (null !== $server) {
                        $server[1]();
                    }
                }
            });
        });
    } finally {
        $GLOBALS['wpdb'] = $old_wpdb;
        unset($GLOBALS['sb_test_options']['rank_math_modules'], $GLOBALS['sb_test_options']['wpseo-premium-redirects-base']);
    }
});

sb_test('Refresh paths (2.5.0): validated like the other routes, queued at every publication and every night by one single event, removed on uninstall', function () use ($source) {
    sb_cache_items_isolated(function ($plugin, $release) use ($source) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['excluded_paths'] = array('/iscriviti/');
        $result = sb_private($plugin, 'sanitize_refresh_paths', array(array('/eventi/', ' ' . home_url('/agenda') . ' ', '/eventi', '', home_url('/x/?a=1'), '/x/#top',
            'https://evil.example/x/', '//evil.example/x/', '/feed.xml', '/../etc/', 'eventi', '/a b/', '/iscriviti/', 7)));
        sb_assert(array('/eventi/', '/agenda/') === $result['paths'], 'The refresh paths were not validated: ' . json_encode($result));
        sb_assert(9 === count($result['invalid']) && 0 === $result['dropped'], 'A refused line was not reported: ' . json_encode($result['invalid']));
        $many = sb_private($plugin, 'sanitize_refresh_paths', array(array_map(static fn($i) => '/p' . $i . '/', range(1, Static_Bridge_Plugin::MAX_REFRESH_PATHS + 7))));
        sb_assert(Static_Bridge_Plugin::MAX_REFRESH_PATHS === count($many['paths']) && 7 === $many['dropped'], 'The refresh paths are not limited.');
        $settings = sb_private($plugin, 'settings');
        sb_assert(array() === $settings['publish_paths'] && array() === $settings['nightly_paths'] && false === wp_next_scheduled(Static_Bridge_Plugin::NIGHTLY_PATHS_HOOK), 'The refresh paths are not empty and off by default.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['publish_paths'] = array('/eventi/', 'https://evil.example/x/', '/../x/', 5);
        sb_assert(array('/eventi/') === sb_private($plugin, 'settings')['publish_paths'], 'A stored path is not checked when read.');

        // The Settings form saves both, says the refused lines in Attività and schedules the nightly event.
        $_POST = array('incremental_enabled' => '1', 'excluded_paths' => "/iscriviti/", 'publish_paths' => "/eventi/\nhttps://evil.example/x/", 'nightly_paths' => "/oggi/\r\n/agenda/");
        try {
            $plugin->save_settings();
        } catch (SB_Test_Response $response) {
        }
        $stored = get_option(Static_Bridge_Plugin::SETTINGS_OPTION);
        sb_assert(array('/eventi/') === $stored['publish_paths'] && array('/oggi/', '/agenda/') === $stored['nightly_paths'], 'The refresh paths were not saved: ' . json_encode($stored));
        sb_assert(false !== strpos(implode("\n", sb_group_c_activity()), 'Righe non valide: «https://evil.example/x/»'), 'A refused line is not in Attività.');
        $next = wp_next_scheduled(Static_Bridge_Plugin::NIGHTLY_PATHS_HOOK);
        $local = (new DateTimeImmutable('@' . (int) $next))->setTimezone(wp_timezone());
        sb_assert(is_int($next) && $next > time() && $next <= time() + DAY_IN_SECONDS && '00:05' === $local->format('H:i'), 'The nightly paths are not scheduled at 00:05 of the site.');

        // At every publication, never over the post's own entry.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['publish_paths'] = array('/eventi/', '/post-201/');
        $post = new WP_Post(array('ID' => 201, 'post_type' => 'post', 'post_status' => 'publish', 'post_date' => '2024-01-15 10:00:00'));
        $plugin->maybe_queue_incremental_post(201, $post, false, new WP_Post(array('ID' => 201, 'post_type' => 'post', 'post_status' => 'draft')));
        $queue = get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION);
        sb_assert(isset($queue[sha1('/eventi/')]) && 'dependent' === $queue[sha1('/eventi/')]['role'] && 'single' === $queue[sha1('/post-201/')]['role'],
            'A publication did not queue «Pagine da aggiornare a ogni pubblicazione», or replaced the post\'s own entry.');

        // Every night: the paths are queued, and the next night is scheduled again (one single event).
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
        wp_clear_scheduled_hook(Static_Bridge_Plugin::NIGHTLY_PATHS_HOOK);
        $plugin->run_nightly_paths();
        sb_assert(array('/agenda/' => 'refresh', '/oggi/' => 'refresh') === sb_queued_items() && wp_next_scheduled(Static_Bridge_Plugin::NIGHTLY_PATHS_HOOK),
            'The nightly paths were not queued or the next night not scheduled: ' . json_encode(sb_queued_items()));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['nightly_paths'] = array();
        $plugin->run_nightly_paths();
        sb_assert(false === wp_next_scheduled(Static_Bridge_Plugin::NIGHTLY_PATHS_HOOK), 'An empty list kept the nightly event.');

        foreach (array('static_bridge_nightly_paths', 'static_bridge_layout_refresh') as $hook) {
            sb_assert(in_array($hook, Static_Bridge_Uninstaller::CRON_HOOKS, true), 'Uninstall does not clear ' . $hook . '.');
        }
        sb_assert(in_array(Static_Bridge_Plugin::LAYOUT_REFRESH_OPTION, Static_Bridge_Uninstaller::OPTIONS, true), 'Uninstall does not delete the menu and widget state.');
        $deactivate = sb_method_body($source, 'deactivate');
        sb_assert(false !== strpos($deactivate, 'self::NIGHTLY_PATHS_HOOK') && false !== strpos($deactivate, 'self::LAYOUT_REFRESH_HOOK'), 'Deactivation keeps the new events.');
    });
});

sb_test('Incremental queue (2.5.0): a route queued by another request while the worker runs is not overwritten by the worker\'s cached copy', function () {
    sb_cache_items_isolated(function ($plugin) {
        $name = Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION;
        $item = function ($path) {
            return array('url' => home_url($path), 'path' => $path, 'action' => 'refresh', 'role' => 'single', 'post_id' => 0, 'builders' => array(), 'queued_at' => time(), 'token' => 't-' . $path, 'attempts' => 0);
        };
        $first = sha1('/chi-siamo/');
        $second = sha1('/eventi/');
        try {
            // The worker read the queue when it started: one route. Its request cache still holds that copy.
            $GLOBALS['sb_test_option_request_cache'][$name] = array($first => $item('/chi-siamo/'));
            // Meanwhile an editor saved another content: the database has two routes.
            $GLOBALS['sb_test_options'][$name] = array($first => $item('/chi-siamo/'), $second => $item('/eventi/'));
            sb_private($plugin, 'complete_incremental_item', array($first, $item('/chi-siamo/')));
            $stored = $GLOBALS['sb_test_options'][$name];
            sb_assert(!isset($stored[$first]), 'The completed route stayed in the queue.');
            sb_assert(isset($stored[$second]), 'The route queued by the other request was lost: the worker wrote back the copy of its own cache.');
            // The same for a retry, and for a plain read on top of a stale copy.
            $GLOBALS['sb_test_option_request_cache'][$name] = array($first => $item('/chi-siamo/'));
            $GLOBALS['sb_test_options'][$name] = array($first => $item('/chi-siamo/'), $second => $item('/eventi/'));
            sb_private($plugin, 'retry_incremental_item', array($first, $item('/chi-siamo/'), 'errore di prova'));
            $stored = $GLOBALS['sb_test_options'][$name];
            sb_assert(isset($stored[$first], $stored[$second]) && 1 === (int) $stored[$first]['attempts'], 'A retry lost the route queued by the other request.');
            $GLOBALS['sb_test_option_request_cache'][$name] = array();
            $GLOBALS['sb_test_options'][$name] = array($second => $item('/eventi/'));
            sb_assert(isset(sb_private($plugin, 'incremental_queue')[$second]), 'The queue was read from the cache of the request.');
        } finally {
            unset($GLOBALS['sb_test_option_request_cache']);
        }
    });
});

sb_test('Incremental queue (2.5.0): every write is one locked step, so two requests never write back each other\'s copy', function () {
    sb_cache_items_isolated(function ($plugin) {
        $name = Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION;
        $lock = Static_Bridge_Plugin::INCREMENTAL_QUEUE_WRITE_LOCK_OPTION;
        $item = function ($path) {
            return array('url' => home_url($path), 'path' => $path, 'action' => 'refresh', 'role' => 'single', 'post_id' => 0, 'builders' => array(), 'queued_at' => time(), 'token' => 't-' . $path, 'attempts' => 0);
        };
        $first = sha1('/chi-siamo/');
        $second = sha1('/eventi/');
        $waited = 0;
        // The other request, played by the rules: the moment this request has read the queue, the other one writes
        // its route at once when nobody holds the write lock, and waits for its turn when somebody does.
        $other = function () use ($plugin, $name, $lock, $second, $item, &$waited) {
            if (sb_private($plugin, 'row_lock_active', array($lock))) {
                $waited++;
                return;
            }
            $GLOBALS['sb_test_options'][$name][$second] = $item('/eventi/');
        };
        $other_takes_its_turn = function () use ($plugin, $second, $item) {
            sb_private($plugin, 'change_incremental_queue', array(function ($queue) use ($second, $item) {
                $queue[$second] = $item('/eventi/');
                return $queue;
            }));
        };
        $writers = array(
            'complete_incremental_item' => function () use ($plugin, $first, $item) {
                sb_private($plugin, 'complete_incremental_item', array($first, $item('/chi-siamo/')));
                return array(false, true);
            },
            'retry_incremental_item' => function () use ($plugin, $first, $item) {
                sb_private($plugin, 'retry_incremental_item', array($first, $item('/chi-siamo/'), 'errore di prova'));
                return array(true, true);
            },
            'enqueue_incremental_urls' => function () use ($plugin) {
                sb_assert(1 === sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/novita/')), 0, 'refresh', array(), 'single')), 'The route was not queued.');
                return array(true, true, sha1('/novita/'));
            },
        );
        try {
            foreach ($writers as $label => $write) {
                $GLOBALS['sb_test_options'][$name] = array($first => $item('/chi-siamo/'));
                unset($GLOBALS['sb_test_options'][$lock]);
                $before = $waited;
                $GLOBALS['sb_test_option_after_read'][$name] = $other;
                $expected = $write();
                sb_assert(!isset($GLOBALS['sb_test_option_after_read'][$name]), $label . ' did not read the queue from the database.');
                sb_assert($before + 1 === $waited, $label . ' read the queue to change it without holding the write lock: the other request wrote in between.');
                sb_assert(!array_key_exists($lock, $GLOBALS['sb_test_options']), $label . ' left the write lock taken.');
                $other_takes_its_turn();
                $stored = $GLOBALS['sb_test_options'][$name];
                sb_assert($expected[0] === isset($stored[$first]) && isset($stored[$second]) && (!isset($expected[2]) || isset($stored[$expected[2]])), $label . ': one of the two changes was lost.');
                sb_assert(!array_key_exists($lock, $GLOBALS['sb_test_options']), 'The other request left the write lock taken.');
            }

            // $change returning null writes nothing; a change inside a change does not wait for its own lock and
            // does not release it; an exception releases it.
            $GLOBALS['sb_test_options'][$name] = array($first => $item('/chi-siamo/'));
            $writes = $GLOBALS['sb_test_option_writes'][$name] ?? 0;
            $returned = sb_private($plugin, 'change_incremental_queue', array(function ($queue) { return null; }));
            sb_assert(array($first) === array_keys($returned) && $writes === ($GLOBALS['sb_test_option_writes'][$name] ?? 0), 'A change that leaves the queue as it is wrote it.');
            $held = array();
            $started = microtime(true);
            sb_private($plugin, 'change_incremental_queue', array(function ($queue) use ($plugin, $lock, &$held) {
                $held[] = sb_private($plugin, 'row_lock_active', array($lock));
                sb_private($plugin, 'change_incremental_queue', array(function ($inner) { return null; }));
                $held[] = sb_private($plugin, 'row_lock_active', array($lock));
                return null;
            }));
            sb_assert(array(true, true) === $held && microtime(true) - $started < 1, 'A change inside a change waited for its own lock or released it.');
            try {
                sb_private($plugin, 'change_incremental_queue', array(function ($queue) { throw new RuntimeException('prova'); }));
                sb_assert(false, 'The exception of a change was swallowed.');
            } catch (RuntimeException $error) {
                sb_assert(!array_key_exists($lock, $GLOBALS['sb_test_options']), 'An exception inside a change left the write lock taken.');
            }

            // A lock nobody releases (a request died holding it): the change is made anyway, after the wait, and the
            // lock of the dead request is not this request's to remove.
            $GLOBALS['sb_test_options'][$lock] = array('token' => 'dead-request', 'expires' => time() + 60);
            $started = microtime(true);
            sb_private($plugin, 'complete_incremental_item', array($first, $item('/chi-siamo/')));
            $elapsed = microtime(true) - $started;
            sb_assert(array() === $GLOBALS['sb_test_options'][$name], 'With the write lock stuck the route stayed in the queue for ever.');
            sb_assert($elapsed > 1 && $elapsed < 5 && 'dead-request' === $GLOBALS['sb_test_options'][$lock]['token'], 'The change did not wait for a held lock, or removed a lock it did not own.');
            // Expired, the same lock is simply replaced.
            $GLOBALS['sb_test_options'][$lock] = array('token' => 'dead-request', 'expires' => time() - 1);
            $GLOBALS['sb_test_options'][$name] = array($first => $item('/chi-siamo/'));
            sb_private($plugin, 'complete_incremental_item', array($first, $item('/chi-siamo/')));
            sb_assert(array() === $GLOBALS['sb_test_options'][$name] && !array_key_exists($lock, $GLOBALS['sb_test_options']), 'An expired write lock was not replaced and released.');
        } finally {
            unset($GLOBALS['sb_test_option_after_read'][$name], $GLOBALS['sb_test_options'][$lock]);
        }

        // No other place writes the queue, and uninstall removes the lock row.
        $source = file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php');
        $body = sb_method_body($source, 'change_incremental_queue');
        sb_assert(1 === substr_count($source, 'update_option(self::INCREMENTAL_QUEUE_OPTION') && 1 === substr_count($body, 'update_option(self::INCREMENTAL_QUEUE_OPTION')
            && false === strpos($source, 'delete_option(self::INCREMENTAL_QUEUE_OPTION'), 'The incremental queue is written outside change_incremental_queue().');
        sb_assert(in_array($lock, Static_Bridge_Uninstaller::OPTIONS, true) && 0 === strpos($lock, Static_Bridge_Uninstaller::OPTION_PREFIX), 'The uninstaller does not know the write lock of the queue.');
    });
});

sb_test('Dates shown in wp-admin (2.5.0): a time() timestamp is printed in the site\'s time zone, never as UTC', function () use ($plugin) {
    $previous = $GLOBALS['sb_test_options'];
    try {
        // A site two hours east of UTC: 23:30 UTC of 14 November is 01:30 of the 15th there.
        $GLOBALS['sb_test_timezone_offset'] = 7200;
        $GLOBALS['sb_test_options']['date_format'] = 'Y-m-d';
        $GLOBALS['sb_test_options']['time_format'] = 'H:i';
        $at = gmmktime(23, 30, 0, 11, 14, 2026);
        sb_assert('2026-11-15 01:30' === sb_private($plugin, 'format_site_datetime', array($at)), 'A timestamp was not printed in the time zone of the site.');
        $release = sb_private($plugin, 'static_root') . '/releases/20261114T233000Z-prova';
        $GLOBALS['sb_test_options']['static_bridge_last_release'] = array('id' => basename($release), 'published_at' => $at);
        $label = sb_private($plugin, 'release_date', array($release));
        sb_assert(false !== strpos($label, '2026-11-15 01:30'), 'The date of a release is printed as UTC: ' . $label);
        // Every date built from a stored timestamp goes through format_site_datetime(); date_i18n() stays only
        // where it prints «now» (Attività), which it does in the site's time zone.
        $source = file_get_contents(dirname(__DIR__, 2) . '/plugin/static-bridge.php');
        sb_assert(1 === preg_match_all('/[^a-z_>]date_i18n\(/', preg_replace('#^\s*(/\*\*|\*|//).*$#m', '', $source))
            && false !== strpos($source, "date_i18n(get_option('date_format') . ' ' . get_option('time_format')),")
            && substr_count($source, '$this->format_site_datetime(') >= 10, 'A date is printed with date_i18n() from a UTC timestamp.');
        foreach (array('server-check.php', 'cli.php', 'server-tuning.php', 'release-updater.php') as $file) {
            sb_assert(false === strpos(file_get_contents(dirname(__DIR__, 2) . '/plugin/' . $file), 'date_i18n('), $file . ' prints a date with date_i18n().');
        }
    } finally {
        unset($GLOBALS['sb_test_timezone_offset']);
        $GLOBALS['sb_test_options'] = $previous;
    }
});

sb_test('static_bridge_route_updated (2.5.0): once per route made final, with the edge purges; static_bridge_all_routes_updated for the whole site', function () {
    sb_cache_items_isolated(function ($plugin) {
        $heard = array();
        $GLOBALS['sb_test_action_callbacks']['static_bridge_route_updated'] = function ($url) use (&$heard) {
            $heard[] = 'route ' . $url;
        };
        $GLOBALS['sb_test_action_callbacks']['static_bridge_all_routes_updated'] = function ($reason) use (&$heard) {
            $heard[] = 'all ' . $reason;
        };
        $url = home_url('/chi-siamo/');
        // The worker completes a route, then purges the edge: one announcement.
        sb_private($plugin, 'complete_incremental_item', array('k', array('url' => $url, 'path' => '/chi-siamo/', 'token' => 't')));
        sb_private($plugin, 'queue_cloudflare_purge', array(array($url), 'pagina statica aggiornata'));
        sb_assert(array('route ' . $url) === $heard, 'A completed route was not announced exactly once: ' . json_encode($heard));
        // Again in the same request: announced again.
        sb_private($plugin, 'complete_incremental_item', array('k', array('url' => $url, 'path' => '/chi-siamo/', 'token' => 't')));
        sb_private($plugin, 'queue_cloudflare_purge', array(array($url), 'pagina statica aggiornata'));
        sb_assert(2 === count($heard), 'A route completed twice was announced once.');
        // An edge purge alone (an editor exclusion): announced; another site, a query or a fragment: never.
        $heard = array();
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/eventi/'), 'https://evil.example/x/', home_url('/x/?q=1'), home_url('/x/#a')), 'percorsi esclusi'));
        sb_private($plugin, 'queue_cloudflare_purge', array('everything', 'nuova release <b>completa</b> pubblicata'));
        sb_assert(array('route ' . home_url('/eventi/'), 'all nuova release completa pubblicata') === $heard, 'The announcements are wrong: ' . json_encode($heard));
        // A listener that throws changes nothing and leaves one line in Attività.
        $GLOBALS['sb_test_action_callbacks']['static_bridge_route_updated'] = function () {
            throw new RuntimeException('varnish giù');
        };
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        sb_private($plugin, 'queue_cloudflare_purge', array(array(home_url('/a/'), home_url('/b/')), 'x'));
        sb_assert(1 === substr_count(implode("\n", sb_group_c_activity()), 'varnish giù'), 'A failing listener was not written once in Attività.');
    });
});


// --- 2.5.0, cache comparison items 4 and 7: after an update of WP, the theme or a plugin; WP-Cron. ---
if (!function_exists('wp_is_maintenance_mode')) {
    function wp_is_maintenance_mode() { return !empty($GLOBALS['sb_test_maintenance']); }
}

/** sb_cache_items_isolated() with no export job, the after-update state cleared and the plugin and theme options set. */
function sb_after_update_isolated(callable $callback)
{
    sb_cache_items_isolated(function ($plugin, $release) use ($callback) {
        $saved_screen = $GLOBALS['sb_test_current_screen'] ?? null;
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION], $GLOBALS['sb_test_options'][Static_Bridge_Plugin::AFTER_UPDATE_OPTION],
            $GLOBALS['sb_test_options']['auto_updater.lock'], $GLOBALS['sb_test_options']['core_updater.lock']);
        $GLOBALS['sb_test_options']['active_plugins'] = array('akismet/akismet.php', sb_private($plugin, 'own_plugin_file'));
        $GLOBALS['sb_test_options']['stylesheet'] = 'figlio';
        $GLOBALS['sb_test_options']['template'] = 'genitore';
        $GLOBALS['sb_test_maintenance'] = false;
        try {
            $callback($plugin, $release);
        } finally {
            $GLOBALS['sb_test_current_screen'] = $saved_screen;
            $GLOBALS['sb_test_maintenance'] = false;
        }
    });
}

sb_test('After an update (2.5.0): WP, the active theme and active plugins updated, a theme switched, a plugin (de)activated are noted; translations, installs, inactive ones and Static Bridge are not', function () use ($source) {
    $GLOBALS['sb_after_update_source'] = $source;
    foreach (array('upgrader_process_complete' => 'note_upgrader_change', 'upgrader_overwrote_package' => 'note_overwritten_package', 'switch_theme' => 'note_theme_switch',
        'activated_plugin' => 'note_plugin_activated', 'deactivated_plugin' => 'note_plugin_deactivated') as $hook => $method) {
        sb_assert(false !== strpos($source, "add_action('" . $hook . "', array(\$this, '" . $method . "')"), 'The hook ' . $hook . ' is not registered.');
    }
    sb_after_update_isolated(function ($plugin) {
        $own = sb_private($plugin, 'own_plugin_file');
        $state = function () use ($plugin) {
            return sb_private($plugin, 'after_update_state');
        };
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'translation', 'translations' => array(array('language' => 'it_IT'))));
        $plugin->note_upgrader_change(null, array('action' => 'install', 'type' => 'plugin'));
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'plugin', 'plugins' => array('spento/spento.php', $own)));
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'theme', 'themes' => array('altro')));
        $plugin->note_plugin_deactivated($own);
        $plugin->note_plugin_activated($own);
        sb_assert(false === get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, false), 'A translation, an install, an inactive plugin or theme or Static Bridge itself was noted.');

        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'core'));
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'plugin', 'plugins' => array('akismet/akismet.php', 'spento/spento.php')));
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'theme', 'theme' => 'genitore'));
        $plugin->note_plugin_activated('hello.php');
        $plugin->note_theme_switch('Nuovo <b>tema</b>');
        $now = $state();
        sb_assert(array('core:wordpress', 'plugin:akismet/akismet.php', 'theme:genitore', 'plugin:hello.php', 'theme:switch') === array_keys($now['items']), 'The noted changes are wrong: ' . json_encode($now));
        sb_assert('Nuovo tema' === $now['items']['theme:switch']['name'] && $now['first'] > 0 && $now['last'] >= $now['first'], 'A name kept its markup or the times are missing.');
        sb_assert('aggiornamento di WordPress, aggiornamento di akismet, aggiornamento del tema genitore, hello attivato e tema Nuovo tema attivato' === sb_private($plugin, 'after_update_summary', array($now)),
            'The summary is wrong: ' . sb_private($plugin, 'after_update_summary', array($now)));
        // The same plugin deactivated: one entry, the last action wins, moved to the end.
        $plugin->note_plugin_deactivated('hello.php');
        $keys = array_keys($state()['items']);
        sb_assert(5 === count($keys) && 'plugin:hello.php' === end($keys) && 'deactivate' === $state()['items']['plugin:hello.php']['action'], 'A second change of the same plugin was not merged.');
        // Small and bounded: ten entries, the others counted.
        for ($i = 0; $i < 8; $i++) {
            $plugin->note_plugin_activated('p' . $i . '/p' . $i . '.php');
        }
        $many = $state();
        sb_assert(10 === count($many['items']) && 3 === $many['more'] && !isset($many['items']['core:wordpress']), 'The list is not bounded to the ten most recent: ' . json_encode($many));
        sb_assert(false !== strpos(sb_private($plugin, 'after_update_summary', array($many)), 'altri 3 cambiamenti'), 'The changes left out are not counted in the summary.');
        // A stored option that is not ours is read as nothing; autoload is false wherever it is written.
        $writes = array();
        preg_match_all('/update_option\(self::AFTER_UPDATE_OPTION, [^;]*;/', $GLOBALS['sb_after_update_source'], $writes);
        sb_assert(2 === count($writes[0]) && 2 === count(preg_grep('/, false\);\z/', $writes[0])), 'The option is autoloaded: ' . implode(' ', $writes[0]));
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::AFTER_UPDATE_OPTION] = array('items' => array('x' => array('type' => 'evil', 'action' => 'update', 'name' => 'x', 'at' => 1), 7 => 'y'));
        sb_assert(array() === $state()['items'], 'A forged entry was read.');
        // Without a release there is nothing old: nothing is noted.
        delete_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION);
        $current = WP_CONTENT_DIR . '/static-bridge/current';
        unlink($current);
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'core'));
        sb_assert(false === get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, false), 'A change was noted without a release online.');
    });
});

sb_test('After an update (2.5.0): the notice shows the changes, escaped, with «Rigenera» and a nonce, only to who may export, on its screens, with a release and no export running', function () {
    sb_after_update_isolated(function ($plugin) {
        $render = function () use ($plugin) {
            ob_start();
            $plugin->render_after_update_notice();
            return (string) ob_get_clean();
        };
        $GLOBALS['sb_test_current_screen'] = (object) array('id' => 'dashboard');
        sb_assert('' === $render(), 'A notice was shown with no change.');
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::AFTER_UPDATE_OPTION] = array('items' => array(
            'plugin:a/a.php' => array('type' => 'plugin', 'action' => 'update', 'name' => 'Moduli & "Co" <script>x</script>', 'at' => time()),
        ), 'first' => time(), 'last' => time(), 'more' => 0);
        $html = $render();
        sb_assert(false !== strpos($html, 'la copia statica è di prima di questi cambiamenti: aggiornamento di Moduli &amp; &quot;Co&quot; x.')
            && false === strpos($html, '<script'), 'The notice is missing or unescaped: ' . $html);
        sb_assert(false !== strpos($html, 'name="action" value="static_bridge_after_update"') && false !== strpos($html, 'name="_wpnonce"')
            && false !== strpos($html, 'value="regenerate"') && false !== strpos($html, 'Rigenera') && false !== strpos($html, 'value="dismiss"'), 'The notice has no «Rigenera» form with a nonce.');
        foreach (array('plugins', 'themes', 'update-core', 'toplevel_page_static-bridge') as $screen) {
            $GLOBALS['sb_test_current_screen'] = (object) array('id' => $screen);
            sb_assert('' !== $render(), 'No notice on ' . $screen);
        }
        $GLOBALS['sb_test_current_screen'] = (object) array('id' => 'edit-post');
        sb_assert('' === $render(), 'The notice reached an unrelated screen.');
        $GLOBALS['sb_test_current_screen'] = (object) array('id' => 'dashboard');
        $GLOBALS['sb_test_caps'] = array('read' => true);
        sb_assert('' === $render(), 'Someone who cannot export saw the notice.');
        $GLOBALS['sb_test_caps'] = array('edit_pages' => true);
        $GLOBALS['sb_test_filter_values']['static_bridge_export_capability'] = 'edit_pages';
        sb_assert('' !== $render(), 'Who has the export capability did not see the notice.');
        unset($GLOBALS['sb_test_caps'], $GLOBALS['sb_test_filter_values']['static_bridge_export_capability']);
        // An export running: hidden.
        sb_assert(!is_wp_error(sb_private($plugin, 'start_export', array('admin'))), 'The fixture export did not start.');
        sb_assert('' === $render(), 'The notice was shown while an export runs.');
        // No release: hidden.
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        unlink(WP_CONTENT_DIR . '/static-bridge/current');
        sb_assert('' === $render(), 'The notice was shown without a release.');
    });
});

sb_test('After an update (2.5.0): «Rigenera» needs the export capability and the nonce and starts the full export; a published export forgets the changes before it; «Ignora» forgets them all', function () {
    sb_after_update_isolated(function ($plugin) {
        $call = function (array $post) use ($plugin) {
            $_POST = $post;
            try {
                $plugin->handle_after_update();
            } catch (SB_Test_Response $response) {
                return $response;
            } catch (SB_Test_WP_Die $die) {
                return $die;
            }
            return null;
        };
        $now = time();
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::AFTER_UPDATE_OPTION] = array('items' => array(
            'core:wordpress' => array('type' => 'core', 'action' => 'update', 'name' => 'WordPress', 'at' => $now - 100),
            'plugin:a/a.php' => array('type' => 'plugin', 'action' => 'update', 'name' => 'A', 'at' => $now + 50),
        ), 'first' => $now - 100, 'last' => $now + 50, 'more' => 0);
        $GLOBALS['sb_test_caps'] = array('read' => true);
        $denied = $call(array('do' => 'regenerate'));
        unset($GLOBALS['sb_test_caps']);
        sb_assert($denied instanceof SB_Test_WP_Die && 403 === $denied->details['args']['response'] && !isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]), 'Someone without the export capability started an export.');
        $GLOBALS['sb_test_nonce_valid'] = false;
        try {
            $call(array('do' => 'regenerate'));
            throw new LogicException('no nonce check');
        } catch (RuntimeException $error) {
            sb_assert('Invalid admin nonce' === $error->getMessage(), 'The nonce was not checked: ' . $error->getMessage());
        } finally {
            $GLOBALS['sb_test_nonce_valid'] = true;
        }
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]), 'An export started without the nonce.');
        $unknown = $call(array('do' => 'boh'));
        sb_assert($unknown instanceof SB_Test_WP_Die && 400 === $unknown->details['args']['response'], 'An unknown action was accepted.');

        $started = $call(array('do' => 'regenerate'));
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION);
        sb_assert($started instanceof SB_Test_Response && 302 === $started->status && false !== strpos($started->data['location'], 'tab=generate'), '«Rigenera» did not go to Genera.');
        sb_assert(is_array($job) && 'running' === $job['status'] && 'notice' === $job['started_by'], '«Rigenera» did not start the full export from the notice.');
        sb_assert(false !== strpos(implode("\n", sb_group_c_activity()), 'Avviata da: avviso dopo gli aggiornamenti.'), 'Attività does not say who started the export.');
        $again = $call(array('do' => 'regenerate'));
        sb_assert($again instanceof SB_Test_WP_Die && 409 === $again->details['args']['response'] && false !== strpos($again->getMessage(), 'già in corso'), 'A second export was started over a running one.');

        // The export publishes: only the change made after it started stays.
        $complete = $job;
        $complete['status'] = 'complete';
        $complete['started_at'] = $now;
        $plugin->handle_export_job_saved($job, $complete);
        $left = sb_private($plugin, 'after_update_state');
        sb_assert(array('plugin:a/a.php') === array_keys($left['items']) && $now + 50 === $left['first'], 'The published export did not forget exactly the changes before it: ' . json_encode($left));
        // A failed export forgets nothing; the next published one forgets the rest and the event.
        $failed = $complete;
        $failed['job_id'] = '00000000-0000-4000-8000-000000000001';
        $failed['status'] = 'failed';
        $failed['started_at'] = $now + 100;
        $plugin->handle_export_job_saved($job, $failed);
        sb_assert(1 === count(sb_private($plugin, 'after_update_state')['items']), 'A failed export removed the notice.');
        $GLOBALS['sb_test_scheduled_hooks'][Static_Bridge_Plugin::AFTER_UPDATE_HOOK] = $now + 600;
        $complete['job_id'] = '00000000-0000-4000-8000-000000000002';
        $complete['started_at'] = $now + 100;
        $plugin->handle_export_job_saved($job, $complete);
        sb_assert(false === get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, false) && false === wp_next_scheduled(Static_Bridge_Plugin::AFTER_UPDATE_HOOK), 'The published export left the notice or its event.');

        // «Ignora»: everything forgotten, said in Attività, back to where the user was.
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::AFTER_UPDATE_OPTION] = array('items' => array(
            'core:wordpress' => array('type' => 'core', 'action' => 'update', 'name' => 'WordPress', 'at' => $now),
        ), 'first' => $now, 'last' => $now, 'more' => 0);
        $dismissed = $call(array('do' => 'dismiss'));
        sb_assert($dismissed instanceof SB_Test_Response && 302 === $dismissed->status && false === get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, false), '«Ignora» kept the changes.');
        sb_assert(false !== strpos(implode("\n", sb_group_c_activity()), 'Avviso dopo gli aggiornamenti ignorato'), '«Ignora» is not in Attività.');
    });
});

sb_test('Rigenera dopo gli aggiornamenti (2.5.0): off by default; on, one single event after the wait, waiting for maintenance and the updater locks, never a second export; removed on deactivation and uninstall', function () use ($source) {
    sb_assert(false !== strpos($source, "'regenerate_after_updates' => isset(\$_POST['regenerate_after_updates']) ? 1 : 0,") && false !== strpos($source, 'name="regenerate_after_updates"'), 'The setting is not saved from the form.');
    sb_assert(false !== strpos(sb_method_body($source, 'deactivate'), 'wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK)'), 'Deactivation keeps the event.');
    sb_assert(in_array(Static_Bridge_Plugin::AFTER_UPDATE_HOOK, Static_Bridge_Uninstaller::CRON_HOOKS, true)
        && in_array(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, Static_Bridge_Uninstaller::OPTIONS, true), 'Uninstall does not know the option or the event.');
    sb_after_update_isolated(function ($plugin) {
        $hook = Static_Bridge_Plugin::AFTER_UPDATE_HOOK;
        sb_assert(0 === sb_private($plugin, 'settings')['regenerate_after_updates'], 'The automatic regeneration is not off by default.');
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'core'));
        sb_assert(false === wp_next_scheduled($hook), 'An event was scheduled with the option off.');
        $plugin->run_after_update_export();
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]), 'An export started with the option off.');

        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['regenerate_after_updates'] = 1;
        $now = time();
        $plugin->note_upgrader_change(null, array('action' => 'update', 'type' => 'core'));
        $at = wp_next_scheduled($hook);
        sb_assert($at >= $now + Static_Bridge_Plugin::AFTER_UPDATE_WAIT && $at <= time() + Static_Bridge_Plugin::AFTER_UPDATE_WAIT, 'The event is not at the end of the wait: ' . var_export($at, true));
        // A series of updates moves it, never past twice the wait from the first.
        $state = get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION);
        $state['first'] = $now - 1000;
        update_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, $state, false);
        $plugin->note_plugin_activated('hello.php');
        sb_assert(wp_next_scheduled($hook) === $now - 1000 + 2 * Static_Bridge_Plugin::AFTER_UPDATE_WAIT, 'A series of changes pushed the export past twice the wait.');
        // Called early (an old event): no export, the event moved to the end of the wait.
        unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $plugin->run_after_update_export();
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]) && is_int(wp_next_scheduled($hook)), 'An early run started an export or lost its event.');

        // The wait is over, but WP is in maintenance, or an updater holds its lock: look again later.
        $state = get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION);
        $state['first'] = $state['last'] = time() - 2000;
        update_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, $state, false);
        $GLOBALS['sb_test_maintenance'] = true;
        $plugin->run_after_update_export();
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]) && wp_next_scheduled($hook) >= time() + Static_Bridge_Plugin::AFTER_UPDATE_RETRY - 1, 'The export did not wait for the end of maintenance.');
        $GLOBALS['sb_test_maintenance'] = false;
        $GLOBALS['sb_test_options']['auto_updater.lock'] = time() - 60;
        $plugin->run_after_update_export();
        sb_assert(!isset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]), 'The export started during a series of automatic updates.');
        $GLOBALS['sb_test_options']['auto_updater.lock'] = time() - 4000;

        // Over: one export, from the update.
        $plugin->run_after_update_export();
        $job = get_option(Static_Bridge_Plugin::JOB_OPTION);
        sb_assert(is_array($job) && 'running' === $job['status'] && 'update' === $job['started_by'], 'The export after the updates did not start.');
        sb_assert(false !== strpos(implode("\n", sb_group_c_activity()), 'Rigenerazione dopo gli aggiornamenti avviata. | aggiornamento di WordPress e hello attivato'), 'Attività does not say why the export started.');
        // Again while it runs: no second export, nothing to wait for (it started after the last change).
        unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $plugin->run_after_update_export();
        sb_assert($job === get_option(Static_Bridge_Plugin::JOB_OPTION) && false === wp_next_scheduled($hook), 'A second export started, or the run waits for an export that already brings the changes.');
        // A running export older than the last change: no second export, look again after it.
        $state = get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION);
        $state['last'] = $job['started_at'] + 1;
        $state['first'] = $job['started_at'] - 2000;
        update_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, $state, false);
        $plugin->run_after_update_export();
        sb_assert($job === get_option(Static_Bridge_Plugin::JOB_OPTION) && is_int(wp_next_scheduled($hook)), 'An older running export was replaced, or not waited for.');
        // A paused export: never replaced, said in red, the notice stays.
        $paused = $job;
        $paused['status'] = 'paused';
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = $paused;
        unset($GLOBALS['sb_test_scheduled_hooks'][$hook]);
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
        $plugin->run_after_update_export();
        $rows = sb_group_c_activity();
        sb_assert($paused === get_option(Static_Bridge_Plugin::JOB_OPTION) && 1 === count($rows) && 0 === strpos($rows[0], 'Rigenerazione dopo gli aggiornamenti saltata: c’è un’esportazione in pausa.') && false !== strpos($rows[0], '| error'),
            'A paused export was replaced or the skip is not in Attività: ' . implode(' / ', $rows));
        sb_assert(false === wp_next_scheduled($hook) && false !== get_option(Static_Bridge_Plugin::AFTER_UPDATE_OPTION, false), 'The skip over a paused export polls, or dropped the notice.');
    });
});

sb_test('WP-Cron (2.5.0): the ninth Server check reports late events of Static Bridge, a stopped WP-Cron, DISABLE_WP_CRON and ALTERNATE_WP_CRON, and advises a system cron', function () {
    $checks = Static_Bridge_Server_Check::checks();
    sb_assert(9 === count($checks) && 'wp-cron' === array_key_last($checks), 'WP-Cron is not the ninth check.');
    $now = 1800000000;
    $labels = array('static_bridge_process_incremental_queue' => 'aggiornamenti incrementali');
    $event = array('k' => array('schedule' => false, 'args' => array()));
    $result = function (array $cron, $disabled = false, $alternate = false) use ($now, $labels) {
        return Static_Bridge_Server_Check::wp_cron_result($cron, $now, $disabled, $alternate, $labels, 'https://example.test/wp-cron.php');
    };
    // An event of Static Bridge 20 minutes late: warning, with what waits and the system cron.
    $late = $result(array($now - 1200 => array('static_bridge_process_incremental_queue' => $event, 'static_bridge_link_check' => $event), 'version' => 2));
    sb_assert('warning' === $late['status'] && 'wp-cron' === $late['id'] && false !== strpos($late['summary'], '2 eventi di Static Bridge sono in ritardo, il più vecchio di 1200 s (aggiornamenti incrementali, static_bridge_link_check)'), 'Late events of Static Bridge: ' . json_encode($late));
    sb_assert(false !== strpos($late['remediation'], 'https://example.test/wp-cron.php ogni 5 minuti') && false !== strpos($late['remediation'], 'DISABLE_WP_CRON a true'), 'No system cron advised: ' . $late['remediation']);
    $late_disabled = $result(array($now - 1200 => array('static_bridge_process_incremental_queue' => $event)), true);
    sb_assert('warning' === $late_disabled['status'] && 0 === strpos($late_disabled['remediation'], 'DISABLE_WP_CRON è acceso'), 'With DISABLE_WP_CRON the advice is not to check the system cron: ' . $late_disabled['remediation']);
    // 10 minutes late is not late yet; a future event never counts.
    $soon = $result(array($now - 600 => array('static_bridge_process_incremental_queue' => $event), $now + 99999 => array('altro' => $event)));
    sb_assert('tip' === $soon['status'] && 0 === strpos($soon['summary'], 'Nessun evento in ritardo, ma WP-Cron parte solo con le visite'), 'An event 10 minutes late was a warning: ' . json_encode($soon));
    // Another plugin's event 2 hours late: WP-Cron has not started.
    $idle = $result(array($now - 7200 => array('altro_plugin' => $event)));
    sb_assert('warning' === $idle['status'] && 0 === strpos($idle['summary'], 'WP-Cron non parte da almeno 7200 s: 1 evento aspetta, e con lui aspettano'), 'A stopped WP-Cron was not reported: ' . json_encode($idle));
    sb_assert('tip' === $result(array($now - 1800 => array('altro_plugin' => $event)))['status'], 'Half an hour of another plugin is a warning.');
    // Nothing late: pass with the system cron, a tip otherwise, also with ALTERNATE_WP_CRON.
    sb_assert('pass' === $result(array(), true)['status'], 'DISABLE_WP_CRON with nothing late is not a pass.');
    $alternate = $result(array(), false, true);
    sb_assert('tip' === $alternate['status'] && false !== strpos($alternate['summary'], 'ALTERNATE_WP_CRON'), 'ALTERNATE_WP_CRON is not said: ' . json_encode($alternate));
    sb_assert('pass' === $result(array(), true, true)['status'], 'DISABLE_WP_CRON did not win over ALTERNATE_WP_CRON.');
});

sb_test('WP-Cron (2.5.0): the Server tab and «Salute del sito» read the events WP keeps, with the names of Static Bridge, and write nothing', function () use ($source) {
    sb_assert(false !== strpos($source, "add_filter('site_status_tests', array(\$this, 'add_site_status_tests'));"), 'The Site Health test is not registered.');
    sb_group_c_isolated(function ($plugin) {
        $tests = $plugin->add_site_status_tests(array('direct' => array('php_version' => array()), 'async' => array()));
        sb_assert(isset($tests['direct']['php_version'], $tests['direct']['static_bridge_wp_cron'], $tests['async']) && is_callable($tests['direct']['static_bridge_wp_cron']['test']), 'The direct test is missing or replaced the others.');
        sb_assert('x' === $plugin->add_site_status_tests('x'), 'A filter value that is not a list was changed.');
        $GLOBALS['sb_test_options']['cron'] = array(time() - 3000 => array('static_bridge_process_incremental_queue' => array('k' => array('schedule' => false, 'args' => array()))), 'version' => 2);
        $before = $GLOBALS['sb_test_options'];
        $health = $plugin->site_status_wp_cron();
        sb_assert('critical' === $health['status'] && 'static_bridge_wp_cron' === $health['test'] && 'blue' === $health['badge']['color'] && false !== strpos($health['description'], 'aggiornamenti incrementali'), 'Late events are not critical in Site Health: ' . json_encode($health));
        sb_assert(0 === strpos($health['description'], '<p>') && false !== strpos($health['actions'], 'tab=server'), 'The Site Health result has no description or link to the Server tab.');
        $server = sb_private($plugin, 'server_check_module')->run('wp-cron');
        sb_assert('warning' === $server['status'] && $server['summary'] === strip_tags(html_entity_decode($health['description'], ENT_QUOTES, 'UTF-8')), 'The Server tab and Site Health disagree.');
        sb_assert($before === $GLOBALS['sb_test_options'], 'The WP-Cron check wrote an option.');
        $GLOBALS['sb_test_options']['cron'] = array('version' => 2);
        $quiet = $plugin->site_status_wp_cron();
        sb_assert('recommended' === $quiet['status'] && false !== strpos($quiet['actions'], 'cron di sistema'), 'A WP-Cron with nothing late but no system cron is not a recommendation: ' . json_encode($quiet));
    });
});


sb_test('Apache rules (2.5.0): X-Static-Bridge-Route static on the four variables of the copy and of Strict, only with mod_headers, and the .gz rules only with mod_headers', function () use ($plugin) {
    sb_cf_options_isolated(function () use ($plugin) {
        $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
        sb_cf_settings(array('precompressed_pages' => function_exists('gzencode') ? 1 : 0));
        $rules = sb_private($plugin, 'rewrite_block');
        $depth = array();
        $marker_lines = 0;
        $gzip_rules = 0;
        foreach (preg_split('/\R/', $rules) as $line) {
            if (preg_match('/^<IfModule (\S+)>$/', $line, $match)) {
                $depth[] = $match[1];
                continue;
            }
            if ('</IfModule>' === $line) {
                array_pop($depth);
                continue;
            }
            if (0 === strpos($line, 'Header always set X-Static-Bridge-Route ')) {
                sb_assert(array('mod_headers.c') === $depth, 'The route marker is outside <IfModule mod_headers.c>: ' . $line);
                $marker_lines++;
            }
            if (preg_match('~^RewriteRule .*index\.html\.gz ~', $line)) {
                sb_assert(array('mod_rewrite.c', 'mod_headers.c') === $depth, 'A .gz rule is served without mod_headers, which writes its Content-Encoding.');
                $gzip_rules++;
            }
        }
        sb_assert(array() === $depth, 'The <IfModule> sections of the Apache block are not balanced.');
        foreach (array('STATIC_BRIDGE_ROUTE', 'REDIRECT_STATIC_BRIDGE_ROUTE', 'STATIC_BRIDGE_STRICT', 'REDIRECT_STATIC_BRIDGE_STRICT') as $variable) {
            sb_assert(1 === substr_count($rules, 'Header always set X-Static-Bridge-Route static env=' . $variable . "\n"), 'The marker misses ' . $variable . '.');
        }
        sb_assert(4 === $marker_lines && false === strpos($rules, 'X-Static-Bridge-Route static env=STATIC_BRIDGE_GZ'), 'The Apache marker is not exactly the four lines.');
        sb_assert(!function_exists('gzencode') || 2 === $gzip_rules, 'The precompressed rules are missing.');
        $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
        sb_assert(4 === substr_count(sb_private($plugin, 'nginx_router_block'), 'add_header X-Static-Bridge-Route static always;'), 'The Nginx block changed its route marker.');
    });
});

sb_test('Diagnostica (2.5.0): on Apache the route marker fails a request that must reach WP, and its absence changes nothing', function () {
    sb_guard_isolated(function ($plugin) {
        $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('excluded_paths' => array('/contatti/'));
        $marked = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html; charset=UTF-8', 'x-static-bridge-route' => 'static'), 'body' => '<html>STATIC</html>');
        $plain = array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html; charset=UTF-8'), 'body' => '<html>WP</html>');
        $htaccess = ABSPATH . '.htaccess';
        $old_htaccess = is_file($htaccess) ? file_get_contents($htaccess) : null;
        try {
            $_SERVER['SERVER_SOFTWARE'] = 'Apache/2.4.43 (Unix)';
            file_put_contents($htaccess, sb_private($plugin, 'rewrite_block') . "\n");
            $steps = array(
                array('id' => 'wp-admin', 'type' => 'admin'),
                array('id' => 'wp-login', 'type' => 'login'),
                array('id' => 'query-bypass', 'type' => 'bypass'),
                array('id' => 'dynamic-0', 'type' => 'dynamic', 'path' => '/contatti/'),
            );
            foreach (array(array($marked, 'fail'), array($plain, 'pass')) as [$answer, $expected]) {
                $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($answer) { return $answer; };
                foreach ($steps as $step) {
                    $result = sb_private($plugin, 'run_diagnostic_step', array($step, array()));
                    sb_assert($expected === $result['status'], 'Apache ' . $step['type'] . ': expected ' . $expected . ', got ' . json_encode($result));
                    sb_assert('fail' !== $expected || false === strpos($result['summary'] . $result['remediation'], 'Nginx'), 'An Apache result talks about Nginx: ' . json_encode($result));
                }
            }
            $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($marked) { return $marked; };
            $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'wp-admin', 'type' => 'admin'), array()));
            sb_assert('fail' === $result['status'] && 'Nginx ha instradato wp-admin alla release statica.' === $result['summary'], 'The Nginx result changed: ' . json_encode($result));
            $headers = sb_private($plugin, 'diagnostic_cache_headers', array($marked));
            sb_assert(in_array('x-static-bridge-route=static', $headers, true), 'A parity mismatch does not show the route marker.');
            sb_assert(true === sb_private($plugin, 'diagnostic_served_static', array(array('headers' => array('X-Static-Bridge-Route' => array('Static')))))
                && false === sb_private($plugin, 'diagnostic_served_static', array(array('headers' => array('x-static-bridge-route' => 'wordpress')))), 'The marker is not read as a list or case-insensitively.');
        } finally {
            if (null === $old_htaccess) { @unlink($htaccess); } else { file_put_contents($htaccess, $old_htaccess); }
        }
    });
});

sb_test('Diagnostica (2.5.0): the home through WP as a computer and as a phone, a warning only when the phone gets another HTML', function () {
    sb_guard_isolated(function ($plugin) {
        unset($GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION]);
        sb_assert(false === sb_private($plugin, 'job_is_running'), 'The fixture still has an export running.');
        $static_root = WP_CONTENT_DIR . '/static-bridge';
        $current = $static_root . '/current';
        $old_target = is_link($current) ? readlink($current) : false;
        $release = 'diag-mobile-' . bin2hex(random_bytes(4));
        try {
            sb_assert(wp_mkdir_p($static_root . '/releases/' . $release), 'Could not create the release fixture.');
            file_put_contents($static_root . '/releases/' . $release . '/index.html', '<html>STATIC</html>');
            if (is_link($current)) { unlink($current); }
            symlink('releases/' . $release, $current);
            $ids = array_column(sb_private($plugin, 'diagnostic_plan', array(realpath($static_root . '/releases/' . $release))), 'id');
            sb_assert(in_array('mobile-html', $ids, true), 'The Diagnostica has no computer/phone step.');

            // $pages: callable(bool $phone, int $call) => HTML; the render proof comes from the HTTP stub.
            $run = function (callable $pages) use ($plugin) {
                $calls = array();
                $GLOBALS['sb_test_http_callback'] = function ($url, $args) use ($pages, &$calls) {
                    $phone = false !== strpos((string) $args['user-agent'], 'iPhone');
                    $calls[] = array('url' => $url, 'phone' => $phone, 'agent' => (string) $args['user-agent']);
                    parse_str((string) wp_parse_url($url, PHP_URL_QUERY), $query);
                    $token = (string) ($query['static_bridge_render'] ?? '');
                    return array('response' => array('code' => 200), 'headers' => array('content-type' => 'text/html', 'X-Static-Bridge-Render' => $token), 'body' => $pages($phone, count($calls), $token));
                };
                try {
                    $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'mobile-html', 'type' => 'mobile-html'), array()));
                } finally {
                    $GLOBALS['sb_test_http_callback'] = null;
                }
                return array($result, $calls);
            };
            $facts = function ($token, $nonce) {
                return '<!--static-bridge-facts:' . $token . ':' . base64_encode(json_encode(array('nonces' => array('wp_rest' => $nonce)))) . '-->';
            };

            // The same page, except what changes at every request: comments, the nonces of the render, a CSP nonce,
            // a nonce in a script, timestamps and clock times.
            list($result, $calls) = $run(function ($phone, $call, $token) use ($facts) {
                $nonce = $phone ? 'bbbbbbbbbb' : 'aaaaaaaaaa';
                return '<html><head><script nonce="' . ($phone ? 'r4nd0m' : 'x9y8z7') . '">var s={"restNonce":"' . ($phone ? 'q1w2e3r4t5' : 'p0o9i8u7y6') . '","t":' . ($phone ? '1763020000' : '1763020123') . '};</script></head>'
                    . '<body data-n="' . $nonce . '">Menu <!-- generated in 0.0' . $call . 's --><time>10:2' . $call . '</time></body></html>' . $facts($token, $nonce);
            });
            sb_assert('pass' === $result['status'], 'Volatile parts made a difference: ' . json_encode($result));
            sb_assert(2 === count($calls) && !$calls[0]['phone'] && $calls[1]['phone'] && 0 === strpos($calls[0]['agent'], 'Static-Bridge/'), 'Equal renders did not take exactly the render user agent and then the phone: ' . json_encode($calls));
            foreach ($calls as $call) {
                sb_assert(false !== strpos($call['url'], 'static_bridge_bypass=1') && false !== strpos($call['url'], 'static_bridge_render='), 'A render of the comparison did not go through WP with the bypass: ' . $call['url']);
            }

            // A theme that writes another menu for phones: warning (never fail), after a second render as a computer.
            list($result, $calls) = $run(function ($phone) {
                return '<html><body>' . ($phone ? '<nav class="mobile-menu">Menu</nav>' : '<nav class="mega-menu">Menu</nav>') . '</body></html>';
            });
            sb_assert('warning' === $result['status'] && false !== strpos($result['summary'], 'i telefoni riceveranno la versione da computer') && false !== strpos($result['summary'], 'wp_is_mobile()'), 'A phone version is not a warning: ' . json_encode($result));
            sb_assert(3 === count($calls) && !$calls[2]['phone'], 'The difference was not checked with a second computer render.');
            // The two sizes in the order the sentence names them: the phone first («mobile-menu» is two bytes longer).
            sb_assert(1 === preg_match('/\(([0-9.,]+) byte al telefono, ([0-9.,]+) al computer,/', $result['summary'], $sizes)
                && (int) str_replace(array('.', ','), '', $sizes[1]) === (int) str_replace(array('.', ','), '', $sizes[2]) + 2, 'The two sizes are not named, or the computer comes first: ' . $result['summary']);

            // A page that changes at every request whatever the device: nothing to say.
            list($result, $calls) = $run(function ($phone, $call) {
                return '<html><body>Visite: ' . str_repeat('x', $call) . '</body></html>';
            });
            sb_assert('skip' === $result['status'] && 3 === count($calls), 'A page that changes at every request was judged: ' . json_encode($result));

            // WP does not answer: skipped, never an error.
            $GLOBALS['sb_test_http_callback'] = function ($url, $args) { return array('response' => array('code' => 500), 'headers' => array(), 'body' => ''); };
            try {
                $result = sb_private($plugin, 'run_diagnostic_step', array(array('id' => 'mobile-html', 'type' => 'mobile-html'), array()));
            } finally {
                $GLOBALS['sb_test_http_callback'] = null;
            }
            sb_assert('skip' === $result['status'], 'A failed render is not a skip: ' . json_encode($result));
        } finally {
            $GLOBALS['sb_test_http_callback'] = null;
            if (is_link($current)) { unlink($current); }
            if (false !== $old_target) { symlink($old_target, $current); }
            @unlink($static_root . '/releases/' . $release . '/index.html');
            @rmdir($static_root . '/releases/' . $release);
        }
    });
});


/**
 * 2.5.0 (confronto con le cache di pagina, voci 6 e 14): a full export of $paths inside sb_retention_isolated(), on
 * Nginx so no .htaccess is written. $render($path, $token) gives the body of a render. Returns array($job_id, $stage).
 */
function sb_cache_export_start($root, $release_id, array $paths, callable $render, array $job_extra = array())
{
    $queue = new Static_Bridge_Export_Queue($GLOBALS['wpdb']);
    $hex = bin2hex(random_bytes(16));
    $job_id = substr($hex, 0, 8) . '-' . substr($hex, 8, 4) . '-4' . substr($hex, 13, 3) . '-8' . substr($hex, 17, 3) . '-' . substr($hex, 20, 12);
    $stage = $root . '/releases/' . $release_id;
    $urls = array_map('home_url', $paths);
    sb_assert($queue->install() && wp_mkdir_p($stage) && count($urls) === $queue->enqueue_batch($job_id, $urls), 'The export fixture could not be prepared.');
    $GLOBALS['sb_test_http_callback'] = function ($url) use ($render) {
        parse_str((string) wp_parse_url($url, PHP_URL_QUERY), $query);
        $token = (string) ($query['static_bridge_render'] ?? '');
        return array('response' => array('code' => 200), 'headers' => array('Content-Type' => 'text/html', 'X-Static-Bridge-Render' => $token), 'body' => $render((string) wp_parse_url($url, PHP_URL_PATH), $token));
    };
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::JOB_OPTION] = array_merge(array(
        'queue_version' => 1, 'job_id' => $job_id, 'status' => 'running', 'release_id' => $release_id, 'stage' => $stage,
        'portable_internal_urls' => 1, 'discovery_source' => 'wordpress-keyset', 'discovery_cursor' => 1, 'discovery_complete' => true,
        'discovered' => count($urls), 'started_at' => time(), 'updated_at' => time(), 'processed' => 0, 'saved' => 0, 'skipped' => 0,
        'issues' => array(), 'current_url' => '',
    ), $job_extra);
    return array($job_id, $stage);
}

/** The facts comment a render for Static Bridge appends, bound to its token. */
function sb_cache_facts($token, array $facts)
{
    return '<!--static-bridge-facts:' . $token . ':' . base64_encode(json_encode($facts)) . '-->';
}

/** Runs $callback on Nginx with the HTTP stub, the filters and the server name restored afterwards. */
function sb_cache_nginx(callable $callback)
{
    $saved = array($GLOBALS['sb_test_http_callback'], $GLOBALS['sb_test_filter_values'], $_SERVER['SERVER_SOFTWARE'] ?? null);
    $_SERVER['SERVER_SOFTWARE'] = 'nginx/1.26.1';
    try {
        $callback();
    } finally {
        list($GLOBALS['sb_test_http_callback'], $GLOBALS['sb_test_filter_values'], $server) = $saved;
        if (null === $server) {
            unset($_SERVER['SERVER_SOFTWARE']);
        } else {
            $_SERVER['SERVER_SOFTWARE'] = $server;
        }
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
    }
}

sb_test('Cache signals (2.5.0): pages saved with no-store or a nonce nobody renews are still saved, and reported in one line per export and per worker run', function () use ($plugin, $fixtureRoot) {
    $reason = function ($html, $facts) use ($plugin) {
        return sb_private($plugin, 'cache_signal_reason', array($html, $facts));
    };
    $nonce = array('nonces' => array('my_plugin_action' => 'abcdef1234'));
    sb_assert('' === $reason('<html>x</html>', array()) && '' === $reason('<html>x</html>', array('nonces' => array(), 'private' => false)), 'A page without signals was reported.');
    $both = $reason('<html>x</html>', array('private' => true) + $nonce);
    sb_assert(false !== strpos($both, 'Cache-Control private o no-store') && false !== strpos($both, 'my_plugin_action'), 'no-store and a stale nonce were not both reported: ' . $both);
    sb_assert(false !== strpos($reason('<html>x</html>', array('nonce_overflow' => true)), 'troppi nonce'), 'Too many nonces were not reported.');
    // Renewed in the browser only where the script that renews it is in the page.
    $fluent = array('nonces' => array('fluentform-submit-form' => 'abcdef1234'));
    sb_assert('' === $reason('<script id="static-bridge-fluent-forms" src="x"></script>', $fluent) && false !== strpos($reason('<html>x</html>', $fluent), 'fluentform-submit-form'), 'A Fluent Forms nonce is judged without its renewing script.');
    $rest = array('nonces' => array('wp_rest' => 'abcdef1234', 'wc_store_api' => '1234abcdef'));
    sb_assert('' === $reason('<script id="static-bridge-woocommerce" src="x"></script>', $rest) && false !== strpos($reason('<html>x</html>', $rest), 'wp_rest'), 'A REST nonce is judged without its renewing script.');
    $GLOBALS['sb_test_filter_values']['static_bridge_static_nonce_actions'] = array('my_plugin_action');
    try {
        sb_assert('' === $reason('<html>x</html>', $nonce), 'A nonce declared with static_bridge_static_nonce_actions was reported.');
    } finally {
        unset($GLOBALS['sb_test_filter_values']['static_bridge_static_nonce_actions']);
    }

    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        sb_cache_nginx(function () use ($root, $plugin) {
            // WooCommerce is active in this part of the suite: its integration off, as decided on the site.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0, 'excluded_paths' => array(), 'woocommerce_enabled' => 0, 'woocommerce_decided' => 1, 'incremental_enabled' => 1);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $paths = array('/', '/modulo/', '/area/', '/pulita/');
            for ($n = 1; $n <= 12; $n++) {
                $paths[] = '/privata-' . $n . '/';
            }
            $signals = function ($path, $token) {
                $facts = array();
                if ('/modulo/' === $path) {
                    $facts = array('private' => true, 'nonces' => array('my_plugin_action' => 'abcdef1234'));
                } elseif ('/area/' === $path) {
                    $facts = array('nonces' => array('wp_rest' => 'abcdef1234'));
                } elseif (0 === strpos($path, '/privata-')) {
                    $facts = array('private' => true);
                }
                return '<html><body>' . $path . '</body></html>' . (empty($facts) ? '' : sb_cache_facts($token, $facts));
            };
            list($job_id, $stage) = sb_cache_export_start($root, 'cache-signals', $paths, $signals);
            $job = sb_private($plugin, 'run_export_queue_step');
            sb_assert('complete' === $job['status'] && 16 === (int) $job['saved'], 'The export with cache signals did not publish every page: ' . json_encode(array($job['status'], $job['saved'], $job['issues'])));
            foreach ($paths as $path) {
                sb_assert(is_file($stage . $path . 'index.html'), 'A page with a cache signal was not saved: ' . $path);
            }
            $listed = array_values(array_filter($job['issues'], function ($issue) {
                return false !== strpos((string) $issue['message'], 'nonce che scadono');
            }));
            sb_assert(1 === count($listed) && false !== strpos($listed[0]['message'], '14 pagine')
                && false !== strpos($listed[0]['message'], '/modulo/ (WordPress ha chiesto di non metterla in cache (Cache-Control private o no-store); contiene nonce che Static Bridge non sa rinnovare (my_plugin_action))')
                && false !== strpos($listed[0]['message'], '/area/ (contiene nonce che Static Bridge non sa rinnovare (wp_rest))')
                && false !== strpos($listed[0]['message'], '…') && false === strpos($listed[0]['message'], '/pulita/')
                && false === strpos($listed[0]['message'], '/privata-12/'), 'The export issues do not hold one line with the count and the first pages: ' . json_encode($job['issues']));
            $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
            $warnings = array_values(array_filter($activity, function ($entry) {
                return 0 === strpos((string) $entry['message'], 'Pagine salvate con un segnale');
            }));
            sb_assert(1 === count($warnings) && !empty($warnings[0]['error']) && $warnings[0]['detail'] === $listed[0]['message'], 'Attività has not one warning for the export: ' . json_encode($activity));
            $manifest = json_decode((string) file_get_contents($stage . '/manifest.json'), true);
            sb_assert(false !== strpos(json_encode($manifest['issues'], JSON_UNESCAPED_UNICODE), '14 pagine'), 'The release manifest misses the cache signals line.');

            // The incremental worker: one line for the run, not one per page.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array();
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            sb_private($plugin, 'enqueue_incremental_urls', array(array(home_url('/modulo/'), home_url('/pulita/'), home_url('/area/')), 0, 'refresh', array(), 'dependent'));
            $plugin->process_incremental_queue();
            $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
            $warnings = array_values(array_filter($activity, function ($entry) {
                return 0 === strpos((string) $entry['message'], 'Pagine salvate con un segnale');
            }));
            $updated = array_filter($activity, function ($entry) {
                return 0 === strpos((string) $entry['message'], 'Pagina statica aggiornata');
            });
            sb_assert(3 === count($updated) && 1 === count($warnings) && false !== strpos($warnings[0]['detail'], '2 pagine')
                && false !== strpos($warnings[0]['detail'], '/modulo/') && false !== strpos($warnings[0]['detail'], '/area/')
                && false === strpos($warnings[0]['detail'], '/pulita/'), 'The worker run did not write one line for its pages with cache signals: ' . json_encode($activity));
            sb_assert(empty(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())), 'The worker left pages with cache signals in the queue.');
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            sb_private($plugin, 'flush_incremental_cache_signals');
            sb_assert(array() === get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), 'The signals of a run were written twice.');
        });
    });
});

sb_test('Identical pages (2.5.0): an automatic refresh whose final HTML and .gz are already in the release is neither written nor purged; changes, unsettled routes and pushes are', function () use ($plugin, $fixtureRoot, $source) {
    sb_assert(0 === sb_private($plugin, 'settings')['skip_identical_pages'], 'Skipping identical pages is not off by default.');
    foreach (array('skip_identical_pages', 'export_load_brake') as $field) {
        sb_assert(false !== strpos($source, "'" . $field . "' => isset(\$_POST['" . $field . "']) ? 1 : 0,") && false !== strpos($source, 'name="' . $field . '"'), 'The setting is not saved from the form: ' . $field);
    }
    $save = sb_method_body($source, 'save_settings');
    sb_assert(false !== strpos($save, "if (empty(\$settings['skip_identical_pages'])) {\n            delete_option(self::UNSETTLED_ROUTES_OPTION);"), 'Turning the option off does not forget the routes it tracked.');
    sb_assert(in_array(Static_Bridge_Plugin::UNSETTLED_ROUTES_OPTION, Static_Bridge_Uninstaller::OPTIONS, true), 'The uninstaller does not remove the routes state.');
    sb_served_isolated($fixtureRoot, function ($root, $htaccess) use ($plugin) {
        $id = '20261113T120000Z-iiiii';
        $release = sb_served_release($root, $id, array('index.html' => '<html>home</html>', 'chi-siamo/index.html' => '<html>vecchia</html>'));
        sb_retention_point_current($root, $id);
        $settings = function (array $values) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array_merge((array) get_option(Static_Bridge_Plugin::SETTINGS_OPTION, array()), $values);
        };
        $settings(array('skip_identical_pages' => 1, 'cloudflare_purge' => 1, 'precompressed_pages' => 0));
        sb_assert(true === sb_private($plugin, 'update_routing_rules'), 'Publishing the Apache rules failed.');
        $url = home_url('/chi-siamo/');
        $page = $release . '/chi-siamo/index.html';
        $run = function ($body, array $extra = array()) use ($plugin, $url, $release) {
            sb_served_render($url, $body);
            $item = array_merge(sb_served_refresh_item($url), $extra);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION] = array(sha1('/chi-siamo/') => $item);
            delete_option(Static_Bridge_Plugin::CLOUDFLARE_PURGE_OPTION);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $result = sb_private($plugin, 'process_incremental_item', array(sha1('/chi-siamo/'), $item, $release));
            clearstatcache();
            $pending = get_option(Static_Bridge_Plugin::CLOUDFLARE_PURGE_OPTION, array());
            $log = implode("\n", array_column(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), 'message'));
            return array($result, isset($pending['urls'][$url]), $log);
        };
        $updates = function () use ($release) {
            return (int) (json_decode((string) file_get_contents($release . '/manifest.json'), true)['incremental_updates'] ?? 0);
        };
        $settled = function () use ($plugin, $release) {
            return sb_private($plugin, 'route_settled', array($release, '/chi-siamo/'));
        };

        // On, but no full export published with it on: every page is written and purged as before.
        list($result, $purged, $log) = $run('<html><body>nuova</body></html>');
        sb_assert('done' === $result && $purged && false !== strpos($log, 'Pagina statica aggiornata') && false !== strpos((string) file_get_contents($page), 'nuova'), 'A page was not written before the first full export with the option on: ' . $log);
        sb_assert(false === $settled(), 'A route counted as written and purged without a full export.');

        // A full export published with the option on: the same render is neither written, manifested nor purged.
        sb_private($plugin, 'reset_unsettled_routes', array($id));
        sb_assert(true === $settled(), 'The full export did not settle its routes.');
        $inode = fileinode($page);
        $before = $updates();
        $copy = get_option('static_bridge_served_copy', array());
        $action_count = count($GLOBALS['sb_test_actions_fired']);
        list($result, $purged, $log) = $run('<html><body>nuova</body></html>');
        clearstatcache();
        sb_assert('done' === $result && !$purged && false !== strpos($log, 'Pagina statica invariata') && false === strpos($log, 'aggiornata'), 'An identical page was written or purged: ' . $log);
        sb_assert($inode === fileinode($page) && $before === $updates() && ($copy['id'] ?? '') === (get_option('static_bridge_served_copy', array())['id'] ?? 'x'), 'An identical page touched the file, the manifest or the Apache served copy.');
        sb_assert(empty(get_option(Static_Bridge_Plugin::INCREMENTAL_QUEUE_OPTION, array())) && false === sb_private($plugin, 'apache_serves_stale_copy'), 'An identical page was not completed.');

        // Another HTML: written, manifested and purged, and settled again.
        list($result, $purged, $log) = $run('<html><body>diversa</body></html>');
        sb_assert('done' === $result && $purged && $before + 1 === $updates() && false !== strpos((string) file_get_contents($page), 'diversa') && true === $settled(), 'A changed page was not written and purged.');

        // A write that never reached its purge (a retry, a killed request): the next identical render is written.
        sb_assert(true === sb_private($plugin, 'mark_route_unsettled', array($release, '/chi-siamo/')) && false === $settled(), 'A route could not be marked unsettled.');
        list($result, $purged, $log) = $run('<html><body>diversa</body></html>');
        sb_assert('done' === $result && $purged && false !== strpos($log, 'aggiornata') && true === $settled(), 'An identical page of an unsettled route was skipped.');

        // A manual push always writes.
        list($result, $purged, $log) = $run('<html><body>diversa</body></html>', array('manual_push_token' => 'aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa'));
        sb_assert('done' === $result && $purged && false !== strpos($log, 'aggiornata'), 'A manual push of an identical page was skipped.');

        // Precompressed pages: the .gz must be what a write leaves now.
        $settings(array('precompressed_pages' => 1));
        @unlink($page . '.gz');
        list($result, $purged) = $run('<html><body>diversa</body></html>');
        sb_assert($purged && is_file($page . '.gz') && gzdecode((string) file_get_contents($page . '.gz')) === file_get_contents($page), 'A page without its .gz was skipped.');
        list($result, $purged) = $run('<html><body>diversa</body></html>');
        sb_assert('done' === $result && !$purged, 'A page identical with its .gz was written.');
        file_put_contents($page . '.gz', gzencode('<html>altro</html>'));
        list($result, $purged) = $run('<html><body>diversa</body></html>');
        clearstatcache();
        sb_assert($purged && gzdecode((string) file_get_contents($page . '.gz')) === file_get_contents($page), 'A page with a stale .gz was skipped.');
        $settings(array('precompressed_pages' => 0));
        list($result, $purged) = $run('<html><body>diversa</body></html>');
        clearstatcache();
        sb_assert($purged && !file_exists($page . '.gz'), 'A .gz left with precompressed pages off was kept.');

        // Off: nothing is compared or tracked, and the state goes at the next publication.
        $settings(array('skip_identical_pages' => 0));
        list($result, $purged, $log) = $run('<html><body>diversa</body></html>');
        sb_assert($purged && false !== strpos($log, 'aggiornata'), 'With the option off an identical page was skipped.');
        sb_private($plugin, 'reset_unsettled_routes', array($id));
        sb_assert(false === get_option(Static_Bridge_Plugin::UNSETTLED_ROUTES_OPTION, false), 'The state stayed with the option off.');
    });
});

sb_test('Activation next to a copy already loaded (2.5.0): a clear message instead of a fatal error, and no second declaration outside an activation', function () use ($pluginFile) {
    // In its own PHP process: the classes must exist before the plugin file is read, as when the module of the
    // builder is on and the separate plugin is activated.
    $run = static function ($sandbox) use ($pluginFile) {
        $code = 'define("ABSPATH", "/"); ' . ($sandbox ? 'define("WP_SANDBOX_SCRAPING", true); ' : '')
            . 'final class Static_Bridge_Plugin {} final class Static_Bridge_I18n {} '
            . 'function esc_html__($text, $domain = "") { return $text; } '
            . 'function wp_die($message, $title = "", $args = array()) { echo "DIE|", $title, "|", $message, "|", json_encode($args); exit(0); } '
            . 'include ' . var_export($pluginFile, true) . '; echo "INCLUDED";';
        $output = array();
        $status = 1;
        exec(escapeshellarg(PHP_BINARY) . ' -d display_errors=1 -r ' . escapeshellarg($code) . ' 2>&1', $output, $status);
        return array($status, implode("\n", $output));
    };
    list($status, $output) = $run(true);
    sb_assert(0 === $status && 0 === strpos($output, 'DIE|Static Bridge è già in funzione|') && false !== strpos($output, 'Histeon') && false !== strpos($output, 'Spegni prima'), 'Activating the plugin next to a copy already loaded does not say what to do: ' . substr($output, 0, 300));
    sb_assert(false !== strpos($output, '"response":200') && false !== strpos($output, '"back_link":true') && false === strpos($output, 'Fatal error') && false === strpos($output, 'INCLUDED'), 'The message of the activation is not a plain page with a way back: ' . substr($output, 0, 300));
    list($status, $output) = $run(false);
    sb_assert(0 === $status && 'INCLUDED' === $output, 'Outside an activation the second copy does not stay out of the way: ' . substr($output, 0, 300));
});

sb_test('Export load brake (2.5.0): slow renders shorten the step down to one URL with a pause, fast ones bring it back, Attività says when; off by default', function () use ($plugin, $fixtureRoot) {
    sb_assert(0 === sb_private($plugin, 'settings')['export_load_brake'], 'The export load brake is not off by default.');
    $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
    $job = array();
    $method = new ReflectionMethod($plugin, 'update_export_load_brake');
    if (PHP_VERSION_ID < 80100) {
        $method->setAccessible(true);
    }
    $method->invokeArgs($plugin, array(&$job, 1.0));
    sb_assert(!isset($job['load_brake']) && array() === get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array()), 'A fast render braked the export.');
    for ($n = 0; $n < 8; $n++) {
        $method->invokeArgs($plugin, array(&$job, 4.2));
    }
    $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    sb_assert(Static_Bridge_Plugin::EXPORT_BRAKE_MAX_LEVEL === $job['load_brake'] && 1 === count($activity) && 'Export rallentato: il server risponde lentamente.' === $activity[0]['message']
        && !empty($activity[0]['error']) && (false !== strpos($activity[0]['detail'], '4,2') || false !== strpos($activity[0]['detail'], '4.2')), 'Slow renders did not brake up to the top level with one Attività line: ' . json_encode(array($job, $activity)));
    for ($n = 0; $n < Static_Bridge_Plugin::EXPORT_BRAKE_CALM * Static_Bridge_Plugin::EXPORT_BRAKE_MAX_LEVEL - 1; $n++) {
        $method->invokeArgs($plugin, array(&$job, 0.5));
    }
    sb_assert(1 === $job['load_brake'] && 1 === count(get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array())), 'Fast renders did not bring the brake down one level at a time.');
    $method->invokeArgs($plugin, array(&$job, 0.5));
    $activity = get_option(Static_Bridge_Plugin::ACTIVITY_OPTION, array());
    sb_assert(!isset($job['load_brake'], $job['load_brake_calm'], $job['load_brake_resume_at']) && 2 === count($activity) && 'Export di nuovo a velocità normale.' === $activity[1]['message'], 'The end of the brake was not said once.');

    sb_retention_isolated($fixtureRoot, function ($root) use ($plugin) {
        sb_cache_nginx(function () use ($root, $plugin) {
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION] = array('strict_mode' => 0, 'excluded_paths' => array(), 'woocommerce_enabled' => 0, 'export_load_brake' => 1);
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::ACTIVITY_OPTION] = array();
            $paths = array('/', '/uno/', '/due/', '/tre/');
            $page = function ($path) {
                return '<html><body>' . $path . '</body></html>';
            };
            // Top level: 40 >> 5 = 1 URL per step, never zero.
            sb_cache_export_start($root, 'load-brake', $paths, $page, array('load_brake' => Static_Bridge_Plugin::EXPORT_BRAKE_MAX_LEVEL, 'load_brake_resume_at' => 0));
            $job = sb_private($plugin, 'run_export_queue_step');
            sb_assert('running' === $job['status'] && 1 === (int) $job['saved'], 'The braked step did not take exactly one URL: ' . json_encode($job));
            // One level: the step waits for the pause after the last render, and with a short budget stops after one URL.
            $job['load_brake'] = 1;
            $job['load_brake_resume_at'] = microtime(true) + 0.4;
            update_option(Static_Bridge_Plugin::JOB_OPTION, $job, false);
            $GLOBALS['sb_test_filter_values']['static_bridge_export_time_budget'] = 1;
            $started = microtime(true);
            $job = sb_private($plugin, 'run_export_queue_step');
            sb_assert(2 === (int) $job['saved'] && microtime(true) - $started >= 0.35, 'The braked step did not wait before its render or took more than one URL with the pause over budget.');
            unset($GLOBALS['sb_test_filter_values']['static_bridge_export_time_budget']);
            // Off: the same job runs the whole step.
            $GLOBALS['sb_test_options'][Static_Bridge_Plugin::SETTINGS_OPTION]['export_load_brake'] = 0;
            $job = sb_private($plugin, 'run_export_queue_step');
            sb_assert('complete' === $job['status'] && 4 === (int) $job['saved'], 'With the brake off the step was still shortened: ' . json_encode($job));
        });
    });
});


$failed = 0;
$passed = 0;
$skipped = 0;
foreach ($results as $result) {
    if ('fail' === $result['status']) {
        $failed++;
    } elseif ('pass' === $result['status']) {
        $passed++;
    } else {
        $skipped++;
    }
}

if ($emitJson) {
    echo json_encode(array(
        'suite' => 'Static Bridge security regression tests',
        'plugin' => realpath($pluginFile),
        'passed' => $passed,
        'skipped' => $skipped,
        'failed' => $failed,
        'results' => $results,
    ), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . PHP_EOL;
} else {
    foreach ($results as $result) {
        echo ('pass' === $result['status'] ? '[PASS] ' : ('skip' === $result['status'] ? '[SKIP] ' : '[FAIL] ')) . $result['name'];
        if (isset($result['detail'])) {
            echo ' — ' . $result['detail'];
        }
        echo PHP_EOL;
    }
    echo sprintf("\n%d passed, %d skipped, %d failed. Source: %s\n", $passed, $skipped, $failed, realpath($pluginFile));
}

exit($failed ? 1 : 0);
